        ["src/games/BedFight/Combat/AutoSwing.lua"] = [[
local Module = {Name = "BedFight Auto Swing", Initialized = false, Connection = nil}

function Module.init(runtime: any): any
    if Module.Initialized then return Module end
    local env: any = getfenv()
    local enabled: boolean = false
    local rate: number = 9
    local nextAt: number = 0
    local function update(): ()
        if not enabled or os.clock() < nextAt then return end
        nextAt = os.clock() + 1 / math.max(rate, 0.5)
        local weapons: any = env.state.weaponLibrary
        if weapons then weapons:Swing() end
    end
    local feature: any = env.createUniversalFeature("Auto Swing", "Presses the game's own sword button on a timer", 4, function(value: boolean): () enabled = value end, {parent = env.state.bedFightScroll, registry = env.state.bedFightFeatures, categoryName = "Combat"})
    env.addNumberOption(feature, "Swings per second", rate, 1, 20, function(value: number): () rate = value end)
    Module.Connection = game:GetService("RunService").Heartbeat:Connect(update)
    Module.Initialized = true
    return Module
end

function Module.destroy(): ()
    if Module.Connection then Module.Connection:Disconnect() Module.Connection = nil end
    Module.Initialized = false
end

return Module

]],
        ["src/games/BedFight/Render/RoundInfo.lua"] = [[
local Module = {Name = "BedFight Round Info", Initialized = false, Connection = nil, Panel = nil}

local function value(name: string): any
    local replicated: ReplicatedStorage = game:GetService("ReplicatedStorage")
    local info: Instance? = replicated:FindFirstChild("GameInfo")
    local item: Instance? = info and info:FindFirstChild(name)
    if item and item:IsA("ValueBase") then return item.Value end
    return item and item:GetAttribute("Value") or nil
end

function Module.init(runtime: any): any
    if Module.Initialized then return Module end
    local env: any = getfenv()
    local enabled: boolean = false
    local status: TextLabel? = nil
    local mode: TextLabel? = nil
    local beds: TextLabel? = nil
    local function clear(): ()
        if Module.Panel then Module.Panel:Destroy() Module.Panel = nil end
        status = nil mode = nil beds = nil
    end
    local function toggle(active: boolean): ()
        enabled = active
        clear()
        if not active then return end
        local root: Frame = env.create("Frame", {Parent = env.ScreenGui, Name = "BedFightInfo", AnchorPoint = Vector2.new(1, 0), BackgroundColor3 = Color3.fromRGB(14, 14, 16), BackgroundTransparency = 0.15, BorderSizePixel = 0, Position = UDim2.new(1, -18, 0, 90), Size = UDim2.fromOffset(196, 64), ZIndex = 60})
        env.create("UICorner", {Parent = root, CornerRadius = UDim.new(0, 4)})
        status = env.makeTextLabel(root, "", 12)
        mode = env.makeTextLabel(root, "", 10)
        beds = env.makeTextLabel(root, "", 10)
        status.Position = UDim2.fromOffset(10, 5) status.Size = UDim2.new(1, -20, 0, 21)
        mode.Position = UDim2.fromOffset(10, 25) mode.Size = UDim2.new(1, -20, 0, 18)
        beds.Position = UDim2.fromOffset(10, 42) beds.Size = UDim2.new(1, -20, 0, 18)
        Module.Panel = root
    end
    env.createUniversalFeature("Round Info", "Status, mode and bed state", 3, toggle, {parent = env.state.bedFightScroll, registry = env.state.bedFightFeatures, categoryName = "Render"})
    Module.Connection = game:GetService("RunService").Heartbeat:Connect(function(): ()
        if not enabled or not status or not mode or not beds then return end
        status.Text = tostring(value("Status") or "—")
        mode.Text = "Mode: " .. tostring(value("GameMode") or "—")
        beds.Text = "Beds: " .. (value("AllBedsBroken") == true and "all broken" or "standing")
    end)
    Module.Initialized = true
    return Module
end

function Module.destroy(): ()
    if Module.Connection then Module.Connection:Disconnect() Module.Connection = nil end
    if Module.Panel then Module.Panel:Destroy() Module.Panel = nil end
    Module.Initialized = false
end

return Module

]],
        ["src/games/BedFight/base.lua"] = [[
local Module = {
    Name = "BedFight",
    PlaceId = 71480482338212,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local runtimeState: any = {
    connections = {} :: {[string]: any},
    bedMarks = {} :: {[Instance]: any},
    generatorMarks = {} :: {[Instance]: any},
    infoPanel = nil :: any,
    voidPanel = nil :: any,
    lastSafe = nil :: Vector3?,
}

local mapCache: any = {beds = {}, generators = {}, at = -1}

local function clearMarks(store: {[Instance]: any}): ()
    for instance: Instance, mark: any in pairs(store) do
        pcall(function(): ()
            mark:Destroy()
        end)
        store[instance] = nil
    end
end

local remoteCache: any = {}

local function remote(path: string): Instance?
    local cached: any = remoteCache[path]
    if cached and cached.Parent then
        return cached
    end
    local replicated: Instance? = game:GetService("ReplicatedStorage")
    local current: Instance? = replicated and replicated:FindFirstChild("Remotes")
    if not current then
        return nil
    end
    for segment: string in string.gmatch(path, "[^%.]+") do
        current = current and current:FindFirstChild(segment)
        if not current then
            return nil
        end
    end
    remoteCache[path] = current
    return current
end

local function fireRemote(path: string, ...: any): boolean
    local target: Instance? = remote(path)
    if not target then
        return false
    end
    local arguments: {any} = table.pack(...)
    return pcall(function(): ()
        (target :: any):FireServer(table.unpack(arguments, 1, arguments.n))
    end)
end

local function gameInfo(): Instance?
    local replicated: Instance? = game:GetService("ReplicatedStorage")
    return replicated and replicated:FindFirstChild("GameInfo") or nil
end


local function scanBeds(): {Model}
    local beds: {Model} = {}
    local container: Instance? = workspace:FindFirstChild("BedsContainer")
    if container then
        for _, child: Instance in ipairs(container:GetChildren()) do
            if child:IsA("Model") then
                table.insert(beds, child :: Model)
            end
        end
    end
    for _, descendant: Instance in ipairs(workspace:GetChildren()) do
        local folder: Instance? = descendant:FindFirstChild("Beds")
        if folder then
            for _, child: Instance in ipairs(folder:GetChildren()) do
                if child:IsA("Model") then
                    table.insert(beds, child :: Model)
                end
            end
        end
    end
    return beds
end

local function scanGenerators(): {BasePart}
    local generators: {BasePart} = {}
    for _, mapChild: Instance in ipairs(workspace:GetChildren()) do
        local folder: Instance? = mapChild:FindFirstChild("Generators")
        if not folder then
            continue
        end
        for _, kind: Instance in ipairs(folder:GetChildren()) do
            for _, part: Instance in ipairs(kind:GetChildren()) do
                if part:IsA("BasePart") then
                    table.insert(generators, part :: BasePart)
                end
            end
        end
    end
    return generators
end

local function refreshMap(): ()
    local now: number = os.clock()
    if now - mapCache.at < 2 then
        return
    end
    mapCache.at = now
    mapCache.beds = scanBeds()
    mapCache.generators = scanGenerators()
end

local function collectBeds(): {Model}
    refreshMap()
    return mapCache.beds
end

local function collectGenerators(): {BasePart}
    refreshMap()
    return mapCache.generators
end

local function anchorOf(model: Model): BasePart?
    local hitbox: Instance? = model:FindFirstChild("BedHitbox")
    if hitbox and hitbox:IsA("BasePart") then
        return hitbox :: BasePart
    end
    local mattress: Instance? = model:FindFirstChild("Mattress")
    if mattress and mattress:IsA("BasePart") then
        return mattress :: BasePart
    end
    return model.PrimaryPart or model:FindFirstChildWhichIsA("BasePart")
end

function Module.init(runtime: any): any
    local environment: any = getfenv()
    local host: any = environment
    local createUniversalFeature: any = host.createUniversalFeature
    local addToggleOption: any = host.addToggleOption
    local addNumberOption: any = host.addNumberOption

    local registerEspExtra: any = host.registerEspExtra
    local addTextOption: any = host.addTextOption
    local addInformationOption: any = host.addInformationOption
    local create: any = host.create
    local makeTextLabel: any = host.makeTextLabel
    local TaskManager: any = host.TaskManager
    local state: any = host.state
    local LocalPlayer: Player = host.LocalPlayer

    local scroll: any = state.bedFightScroll
    local registry: any = state.bedFightFeatures

    local auraSettings: any = {

        range = 20,
        rate = 8,
        weapon = "",
        teamCheck = false,
        maxTargets = 3,
    }
    local placeSettings: any = {
        block = "",
        variant = 3,
        grid = 3,
        rate = 8,
        ahead = 1,
    }

    local function equippedWeaponName(): string
        if auraSettings.weapon ~= "" then
            return auraSettings.weapon
        end
        local camera: Camera? = workspace.CurrentCamera
        local viewModel: Instance? = camera and camera:FindFirstChild("ViewModel")
        if viewModel then
            for _, child: Instance in ipairs(viewModel:GetChildren()) do
                if child:IsA("Model") or child:IsA("BasePart") then
                    return child.Name
                end
            end
        end
        return "Wooden Sword"
    end

    local function characterOf(player: Player): Model?
        local container: Instance? = workspace:FindFirstChild("PlayersContainer")
        local named: Instance? = container and container:FindFirstChild(player.Name)
        if named and named:IsA("Model") then
            return named :: Model
        end
        return player.Character
    end

    local settings: any = {
        bedColour = Color3.fromRGB(236, 236, 240),
        generatorColour = Color3.fromRGB(150, 220, 255),
        showDistance = true,
        showTimers = true,
        maxDistance = 2000,
    }

    local function clearBeds(): ()
        clearMarks(runtimeState.bedMarks)
    end

    local function renderLibrary(): any
        return state.renderLibrary
    end

    local function worldLayer(name: string): Frame?
        local library: any = renderLibrary()
        if not library then
            return nil
        end
        return library:Layer(name)
    end

    local function renderBeds(): ()
        local library: any = renderLibrary()
        local layer: Frame? = worldLayer("BedFightEspLayer")
        local camera: Camera? = workspace.CurrentCamera
        if not library or not layer or not camera then
            return
        end
        local resolvedLayer: Frame = layer :: Frame
        resolvedLayer.Visible = true
        local root: BasePart? = LocalPlayer.Character
            and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") :: BasePart?
        local origin: Vector3 = root and (root :: BasePart).Position or Vector3.zero
        local seen: {[Instance]: boolean} = {}

        for _, bed: Model in ipairs(collectBeds()) do
            local anchor: BasePart? = anchorOf(bed)
            if not anchor then
                continue
            end
            local resolved: BasePart = anchor :: BasePart
            local distance: number = (resolved.Position - origin).Magnitude
            if distance > settings.maxDistance then
                continue
            end
            local projected: Vector2? = library:Project(camera :: Camera, resolved.Position)
            if not projected then
                continue
            end
            seen[bed] = true
            runtimeState.bedMarks[bed] = true
            local drawings: any = library:Set(resolvedLayer, bed)
            drawings:Show(true)
            drawings:Label(
                "NameTag",
                settings.showDistance
                        and ("Bed  " .. tostring(math.round(distance)) .. "m")
                    or "Bed",
                projected :: Vector2,
                0.5,
                12,
                settings.bedColour,
                true
            )
        end

        for bed: Instance in pairs(runtimeState.bedMarks) do
            if not seen[bed] or not bed.Parent then
                library:Release(resolvedLayer, bed)
                runtimeState.bedMarks[bed] = nil
            end
        end
    end

    local function setBedEsp(enabled: boolean): ()
        host.disconnectFeatureConnection("BedFightBeds")
        clearBeds()
        local library: any = renderLibrary()
        local layer: Frame? = worldLayer("BedFightEspLayer")
        if library and layer and not enabled then
            library:ReleaseAll(layer)
            layer.Visible = false
        end
        if not enabled then
            return
        end
        host.featureConnections.BedFightBeds =
            TaskManager:Connect(function(): ()
                renderBeds()
            end)
    end

    registerEspExtra({
        Name = "Beds",
        Default = false,
        Color = settings.bedColour,
        Tooltip = "Every bed on the map, through walls.",
        Toggle = setBedEsp,
        SetColor = function(value: Color3): ()
            settings.bedColour = value
        end,
        Options = {
            {
                Kind = "toggle",
                Name = "distance",
                Default = true,
                Set = function(value: boolean): ()
                    settings.showDistance = value
                end,
            },
            {
                Kind = "number",
                Name = "max distance",
                Default = settings.maxDistance,
                Min = 100,
                Max = 5000,
                Set = function(value: number): ()
                    settings.maxDistance = value
                end,
            },
        },
    })

    local function setGeneratorEsp(enabled: boolean): ()
        host.disconnectFeatureConnection("BedFightGenerators")
        local library: any = renderLibrary()
        local layer: Frame? = worldLayer("BedFightEspLayer")
        if library and layer then
            for generator: Instance in pairs(runtimeState.generatorMarks) do
                library:Release(layer, generator)
            end
        end
        clearMarks(runtimeState.generatorMarks)
        if not enabled then
            return
        end
        host.featureConnections.BedFightGenerators =
            TaskManager:Connect(function(): ()
                local root: BasePart? = LocalPlayer.Character
                    and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") :: BasePart?
                local origin: Vector3 = root and (root :: BasePart).Position or Vector3.zero
                local seen: {[Instance]: boolean} = {}

                for _, generator: BasePart in ipairs(collectGenerators()) do
                    local distance: number = (generator.Position - origin).Magnitude
                    if distance > settings.maxDistance then
                        continue
                    end
                    seen[generator] = true
                    local mark: any = runtimeState.generatorMarks[generator]
                    if not mark or not mark.Parent then
                        local billboard: BillboardGui = create("BillboardGui", {
                            Parent = generator,
                            Name = "Wurst_GeneratorMark",
                            AlwaysOnTop = true,
                            LightInfluence = 0,
                            Size = UDim2.fromOffset(150, 20),
                            StudsOffset = Vector3.new(0, 3, 0),
                        }) :: BillboardGui
                        local label: TextLabel = makeTextLabel(billboard, "", 11)
                        label.Name = "Label"
                        label.Size = UDim2.fromScale(1, 1)
                        label.TextXAlignment = Enum.TextXAlignment.Center
                        runtimeState.generatorMarks[generator] = billboard
                        mark = billboard
                    end
                    local label: TextLabel? = mark:FindFirstChild("Label") :: TextLabel?
                    if not label then
                        continue
                    end

                    local kind: string = generator.Parent
                        and generator.Parent.Name:gsub("Generators", "")
                        or "Generator"
                    local timer: string = ""
                    if settings.showTimers then
                        local progress: Instance? = generator:FindFirstChild("ProgressGui")
                        local timerLabel: Instance? = progress
                            and progress:FindFirstChild("TimerLabel")
                        if timerLabel and timerLabel:IsA("TextLabel") then
                            timer = "  " .. (timerLabel :: TextLabel).Text
                        end
                    end
                    label.TextColor3 = settings.generatorColour
                    label.Text = kind
                        .. (settings.showDistance
                            and ("  " .. tostring(math.round(distance)) .. "m")
                            or "")
                        .. timer
                end

                for generator: Instance, mark: any in pairs(runtimeState.generatorMarks) do
                    if not seen[generator] or not generator.Parent then
                        pcall(function(): ()
                            mark:Destroy()
                        end)
                        runtimeState.generatorMarks[generator] = nil
                    end
                end
            end)
    end

    registerEspExtra({
        Name = "Generators",
        Default = false,
        Color = settings.generatorColour,
        Tooltip = "Diamond and emerald generators, with the game's own "
            .. "countdown.",
        Toggle = setGeneratorEsp,
        SetColor = function(value: Color3): ()
            settings.generatorColour = value
        end,
        Options = {
            {
                Kind = "toggle",
                Name = "timers",
                Default = true,
                Set = function(value: boolean): ()
                    settings.showTimers = value
                end,
            },
        },
    })

    local nukerSettings: any = {
        range = 18,
        rate = 8,
        serverHit = false,
        mine = false,
    }
    local NukerFeature: any = createUniversalFeature(
        "Bed Nuker",
        "Hits the nearest bed in range as fast as the game allows",
        5,
        function(enabled: boolean): ()
            host.disconnectFeatureConnection("BedFightNuker")
            if not enabled then
                return
            end
            local nextAt: number = 0
            host.featureConnections.BedFightNuker =
                TaskManager:Connect(function(): ()
                    local character: Model? = LocalPlayer.Character
                    local root: BasePart? = character
                        and character:FindFirstChild("HumanoidRootPart") :: BasePart?
                    if not root then
                        return
                    end
                    local resolvedRoot: BasePart = root :: BasePart

                    local target: BasePart? = nil
                    local best: number = nukerSettings.range
                    for _, bed: Model in ipairs(collectBeds()) do
                        local anchor: BasePart? = anchorOf(bed)
                        if not anchor then
                            continue
                        end
                        local distance: number =
                            ((anchor :: BasePart).Position - resolvedRoot.Position).Magnitude
                        if distance < best then
                            target = anchor
                            best = distance
                        end
                    end
                    if not target then
                        return
                    end

                    local now: number = os.clock()
                    if now < nextAt then
                        return
                    end
                    nextAt = now + 1 / math.max(nukerSettings.rate, 0.5)

                    local weapons: any = state.weaponLibrary
                    if weapons then
                        weapons:Swing()
                    end

                    if nukerSettings.serverHit then
                        local owner: Instance? = (target :: BasePart)
                            :FindFirstAncestorOfClass("Model")
                        if owner then
                            fireRemote(
                                "ItemsRemotes.SwordHit",
                                owner,
                                equippedWeaponName()
                            )
                        end
                    end
                    if nukerSettings.mine then

                        local origin: BasePart? = character
                            and character:FindFirstChild("HumanoidRootPart") :: BasePart?
                        if origin then
                            local from: Vector3 = (origin :: BasePart).Position
                            local to: Vector3 = (target :: BasePart).Position
                            local heading: Vector3 = to - from
                            heading = heading.Magnitude > 0.001
                                and heading.Unit
                                or Vector3.new(0, -1, 0)
                            fireRemote(
                                "ItemsRemotes.MineBlock",
                                "Wooden Pickaxe",
                                target,
                                Vector3.new(
                                    math.round(to.X),
                                    math.round(to.Y),
                                    math.round(to.Z)
                                ),
                                from,
                                heading
                            )
                        end
                    end

                    local fire: any = environment.firetouchinterest
                    if type(fire) ~= "function" then
                        return
                    end
                    for _, part: Instance in ipairs(character:GetDescendants()) do
                        if not part:IsA("BasePart") then
                            continue
                        end
                        pcall(fire, part, target, 1)
                        pcall(fire, part, target, 0)
                    end
                end)
        end,
        {parent = scroll, registry = registry, categoryName = "Combat"}
    )
    addNumberOption(
        NukerFeature,
        "Range",
        nukerSettings.range,
        6,
        80,
        function(value: number): ()
            nukerSettings.range = value
        end
    )
    addNumberOption(
        NukerFeature,
        "Hits per second",
        nukerSettings.rate,
        1,
        20,
        function(value: number): ()
            nukerSettings.rate = value
        end
    )
    addToggleOption(NukerFeature, "Server hit", false, function(value: boolean): ()
        nukerSettings.serverHit = value
    end)
    addToggleOption(NukerFeature, "Mine remote", false, function(value: boolean): ()
        nukerSettings.mine = value
    end)
    addInformationOption(
        NukerFeature,
        "Safe band: 18 studs and under ten hits a second. This presses the "
            .. "game's own controls, so whatever is in your hand is what "
            .. "swings; the two remote paths are opt-in and the server may or "
            .. "may not accept either for a bed."
    )

    local scaffoldSettings: any = {rate = 6, reach = 6, variant = 3}

    local guiCache: any = {at = -1, block = nil}

    local function blockSlot(): GuiButton?
        if os.clock() - guiCache.at < 1 then
            return guiCache.block
        end
        local playerGui: Instance? = LocalPlayer:FindFirstChild("PlayerGui")
        if not playerGui then
            return nil
        end

        local blockWords: {string} = {"wool", "plank", "stone", "wood", "brick", "block"}
        for _, descendant: Instance in ipairs(playerGui:GetDescendants()) do
            if not descendant:IsA("GuiButton") then
                continue
            end
            local lowered: string = string.lower(descendant.Name)
            for _, word: string in ipairs(blockWords) do
                if string.find(lowered, word, 1, true) then
                    guiCache.block = descendant :: GuiButton
                    guiCache.at = os.clock()
                    return guiCache.block
                end
            end
        end
        guiCache.block = nil
        guiCache.at = os.clock()
        return nil
    end

    local function scaffoldBlockName(): string
        local camera: Camera? = workspace.CurrentCamera
        local viewModel: Instance? = camera and camera:FindFirstChild("ViewModel")
        if viewModel then
            for _, child: Instance in ipairs(viewModel:GetChildren()) do
                local name: string = string.lower(child.Name)
                if string.find(name, "wool", 1, true)
                    or string.find(name, "plank", 1, true)
                    or string.find(name, "block", 1, true) then
                    return child.Name
                end
            end
        end
        local slot: GuiButton? = blockSlot()
        if slot then
            return slot.Name
        end
        return "Wool"
    end

    local ScaffoldFeature: any = createUniversalFeature(
        "Scaffold",
        "Places the game's own blocks under you while you walk over nothing",
        6,
        function(enabled: boolean): ()
            host.disconnectFeatureConnection("BedFightScaffold")
            if not enabled then
                return
            end
            local nextAt: number = 0
            host.featureConnections.BedFightScaffold =
                TaskManager:Connect(function(): ()
                    local character: Model? = LocalPlayer.Character
                    local root: BasePart? = character
                        and character:FindFirstChild("HumanoidRootPart") :: BasePart?
                    local humanoid: Humanoid? = character
                        and character:FindFirstChildOfClass("Humanoid") :: Humanoid?
                    if not root or not humanoid then
                        return
                    end
                    local resolvedRoot: BasePart = root :: BasePart
                    local resolvedHumanoid: Humanoid = humanoid :: Humanoid

                    local parameters: RaycastParams = RaycastParams.new()
                    parameters.FilterType = Enum.RaycastFilterType.Exclude
                    parameters.IgnoreWater = true
                    parameters.FilterDescendantsInstances = {character :: any}
                    local below: RaycastResult? = workspace:Raycast(
                        resolvedRoot.Position,
                        Vector3.new(0, -(resolvedHumanoid.HipHeight + scaffoldSettings.reach), 0),
                        parameters
                    )
                    if below then
                        return
                    end

                    local now: number = os.clock()
                    if now < nextAt then
                        return
                    end
                    nextAt = now + 1 / math.max(scaffoldSettings.rate, 0.5)

                    local slot: GuiButton? = blockSlot()
                    local weapons: any = state.weaponLibrary
                    if slot and weapons then

                        weapons:PressButton(slot :: GuiButton)
                    end

                    local grid: number = 3
                    local base: Vector3 = resolvedRoot.Position
                        - Vector3.new(0, resolvedHumanoid.HipHeight + 1, 0)
                    fireRemote(
                        "ItemsRemotes.PlaceBlock",
                        scaffoldBlockName(),
                        scaffoldSettings.variant,
                        Vector3.new(
                            math.floor(base.X / grid + 0.5) * grid,
                            math.floor(base.Y / grid + 0.5) * grid,
                            math.floor(base.Z / grid + 0.5) * grid
                        )
                    )
                end)
        end,
        {parent = scroll, registry = registry, categoryName = "Movement"}
    )
    addNumberOption(
        ScaffoldFeature,
        "Blocks per second",
        scaffoldSettings.rate,
        1,
        20,
        function(value: number): ()
            scaffoldSettings.rate = value
        end
    )
    addNumberOption(
        ScaffoldFeature,
        "Gap depth",
        scaffoldSettings.reach,
        2,
        30,
        function(value: number): ()
            scaffoldSettings.reach = value
        end
    )
    addNumberOption(
        ScaffoldFeature,
        "Variant",
        scaffoldSettings.variant,
        0,
        12,
        function(value: number): ()
            scaffoldSettings.variant = value
        end
    )
    addInformationOption(
        ScaffoldFeature,
        "Fires PlaceBlock as captured: block name, hotbar slot (3 and 5 in the "
            .. "logs), world position. Variant is that slot. Server Scaffold is "
            .. "the same remote with tiles ahead and a typed block name."
    )

    local voidSettings: any = {margin = 25, rescue = true}
    local VoidFeature: any = createUniversalFeature(
        "Anti Void",
        "Catches you before the map's own kill plane does",
        7,
        function(enabled: boolean): ()
            host.disconnectFeatureConnection("BedFightVoid")
            if runtimeState.voidPanel then
                pcall(function(): ()
                    runtimeState.voidPanel:Destroy()
                end)
                runtimeState.voidPanel = nil
            end
            if not enabled then
                return
            end
            local warning: Frame = create("Frame", {
                Parent = host.ScreenGui,
                Name = "BedFightVoidWarning",
                AnchorPoint = Vector2.new(0.5, 0),
                BackgroundColor3 = Color3.fromRGB(18, 14, 14),
                BackgroundTransparency = 0.1,
                BorderSizePixel = 0,
                Position = UDim2.new(0.5, 0, 0, 74),
                Size = UDim2.fromOffset(210, 26),
                Visible = false,
                ZIndex = 62,
            }) :: Frame
            create("UICorner", {Parent = warning, CornerRadius = UDim.new(0, 4)})
            local label: TextLabel = makeTextLabel(warning, "", 12)
            label.Size = UDim2.fromScale(1, 1)
            label.TextXAlignment = Enum.TextXAlignment.Center
            label.TextColor3 = Color3.fromRGB(232, 160, 160)
            label.ZIndex = 63
            runtimeState.voidPanel = warning

            host.featureConnections.BedFightVoid =
                TaskManager:Connect(function(): ()
                    local info: Instance? = gameInfo()
                    local barrier: Instance? = info
                        and info:FindFirstChild("DeathBarrierInfo")
                    local heightValue: Instance? = barrier
                        and barrier:FindFirstChild("MaxHeight")
                    local root: BasePart? = LocalPlayer.Character
                        and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") :: BasePart?
                    if not root or not heightValue or not heightValue:IsA("NumberValue") then
                        warning.Visible = false
                        return
                    end
                    local resolvedRoot: BasePart = root :: BasePart
                    local floor: number = (heightValue :: NumberValue).Value
                    local drop: number = resolvedRoot.Position.Y - floor

                    local parameters: RaycastParams = RaycastParams.new()
                    parameters.FilterType = Enum.RaycastFilterType.Exclude
                    parameters.IgnoreWater = true
                    parameters.FilterDescendantsInstances = {LocalPlayer.Character :: any}
                    local ground: RaycastResult? = workspace:Raycast(
                        resolvedRoot.Position,
                        Vector3.new(0, -12, 0),
                        parameters
                    )
                    if ground then
                        runtimeState.lastSafe = resolvedRoot.Position
                    end

                    warning.Visible = drop < voidSettings.margin * 2
                    if warning.Visible then
                        label.Text = "Void in " .. tostring(math.round(drop)) .. " studs"
                    end

                    if not voidSettings.rescue or drop > voidSettings.margin then
                        return
                    end

                    resolvedRoot.AssemblyLinearVelocity = Vector3.zero
                    if runtimeState.lastSafe then
                        resolvedRoot.CFrame =
                            CFrame.new(runtimeState.lastSafe + Vector3.new(0, 4, 0))
                    end
                end)
        end,
        {parent = scroll, registry = registry, categoryName = "Movement"}
    )
    addNumberOption(
        VoidFeature,
        "Rescue margin",
        voidSettings.margin,
        5,
        120,
        function(value: number): ()
            voidSettings.margin = value
        end
    )
    addToggleOption(VoidFeature, "Rescue", true, function(value: boolean): ()
        voidSettings.rescue = value
    end)
    addInformationOption(
        VoidFeature,
        "The kill height comes from GameInfo.DeathBarrierInfo, so the margin is "
            .. "measured against the game's own plane."
    )

    local ServerAuraFeature: any = createUniversalFeature(
        "Server Aura",
        "Reports hits straight to the server, no swing needed",
        8,
        function(enabled: boolean): ()
            host.disconnectFeatureConnection("BedFightServerAura")
            if not enabled then
                return
            end
            local nextAt: number = 0
            host.featureConnections.BedFightServerAura =
                TaskManager:Connect(function(): ()
                    local now: number = os.clock()
                    if now < nextAt then
                        return
                    end
                    nextAt = now + 1 / math.max(auraSettings.rate, 0.5)

                    local root: BasePart? = LocalPlayer.Character
                        and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") :: BasePart?
                    if not root then
                        return
                    end
                    local origin: Vector3 = (root :: BasePart).Position
                    local weapon: string = equippedWeaponName()
                    local sent: number = 0

                    for _, player: Player in ipairs(host.Players:GetPlayers()) do
                        if player == LocalPlayer then
                            continue
                        end
                        if sent >= math.round(auraSettings.maxTargets) then
                            break
                        end
                        if auraSettings.teamCheck
                            and player.Team ~= nil
                            and player.Team == LocalPlayer.Team then
                            continue
                        end
                        local targets: any = runtime.Services.protectedTargets
                        if targets.isProtected(player) then
                            continue
                        end
                        local character: Model? = characterOf(player)
                        local victimRoot: Instance? = character
                            and character:FindFirstChild("HumanoidRootPart")
                        local humanoid: Instance? = character
                            and character:FindFirstChildOfClass("Humanoid")
                        if not character or not victimRoot or not humanoid then
                            continue
                        end
                        if (humanoid :: Humanoid).Health <= 0 then
                            continue
                        end
                        if ((victimRoot :: BasePart).Position - origin).Magnitude
                            > auraSettings.range then
                            continue
                        end
                        fireRemote("ItemsRemotes.SwordHit", character, weapon)
                        sent += 1
                    end
                end)
        end,
        {parent = scroll, registry = registry, categoryName = "Combat"}
    )
    addNumberOption(ServerAuraFeature, "Range", auraSettings.range, 5, 40, function(value: number): ()
        auraSettings.range = value
    end)
    addNumberOption(ServerAuraFeature, "Hits per second", auraSettings.rate, 1, 20, function(value: number): ()
        auraSettings.rate = value
    end)
    addNumberOption(ServerAuraFeature, "Max targets", auraSettings.maxTargets, 1, 12, function(value: number): ()
        auraSettings.maxTargets = value
    end)
    addToggleOption(ServerAuraFeature, "Team check", false, function(value: boolean): ()
        auraSettings.teamCheck = value
    end)
    addTextOption(ServerAuraFeature, "Weapon name", "", function(value: string): ()
        auraSettings.weapon = value
    end)
    addInformationOption(
        ServerAuraFeature,
        "Safe band: 20-28 studs of range and single-digit hits per second. "
            .. "Past 28 studs no legitimate swing could have reached, and that "
            .. "is what gets accounts collected in a ban wave. Leave the weapon "
            .. "empty and it reads whichever view model you hold; the Friend "
            .. "List is respected."
    )

    local function equippedBlockName(): string
        if placeSettings.block ~= "" then
            return placeSettings.block
        end

        local camera: Camera? = workspace.CurrentCamera
        local viewModel: Instance? = camera and camera:FindFirstChild("ViewModel")
        if viewModel then
            for _, child: Instance in ipairs(viewModel:GetChildren()) do
                local name: string = string.lower(child.Name)
                if string.find(name, "wool", 1, true)
                    or string.find(name, "plank", 1, true)
                    or string.find(name, "block", 1, true) then
                    return child.Name
                end
            end
        end
        return "Wool"
    end

    local function snap(value: number, grid: number): number
        return math.floor(value / grid + 0.5) * grid
    end

    local ServerScaffoldFeature: any = createUniversalFeature(
        "Server Scaffold",
        "Places real blocks under and ahead of you through the game's remote",
        9,
        function(enabled: boolean): ()
            host.disconnectFeatureConnection("BedFightServerScaffold")
            if not enabled then
                return
            end
            local nextAt: number = 0
            host.featureConnections.BedFightServerScaffold =
                TaskManager:Connect(function(): ()
                    local character: Model? = LocalPlayer.Character
                    local root: BasePart? = character
                        and character:FindFirstChild("HumanoidRootPart") :: BasePart?
                    local humanoid: Humanoid? = character
                        and character:FindFirstChildOfClass("Humanoid") :: Humanoid?
                    if not root or not humanoid then
                        return
                    end
                    local resolvedRoot: BasePart = root :: BasePart
                    local resolvedHumanoid: Humanoid = humanoid :: Humanoid

                    local now: number = os.clock()
                    if now < nextAt then
                        return
                    end

                    local parameters: RaycastParams = RaycastParams.new()
                    parameters.FilterType = Enum.RaycastFilterType.Exclude
                    parameters.IgnoreWater = true
                    parameters.FilterDescendantsInstances = {character :: any}
                    local drop: number = resolvedHumanoid.HipHeight + placeSettings.grid + 1
                    local below: RaycastResult? = workspace:Raycast(
                        resolvedRoot.Position,
                        Vector3.new(0, -drop, 0),
                        parameters
                    )
                    if below then
                        return
                    end
                    nextAt = now + 1 / math.max(placeSettings.rate, 0.5)

                    local grid: number = placeSettings.grid
                    local block: string = equippedBlockName()
                    local base: Vector3 = resolvedRoot.Position
                        - Vector3.new(0, resolvedHumanoid.HipHeight + 1, 0)

                    local heading: Vector3 = resolvedHumanoid.MoveDirection
                    if heading.Magnitude < 0.05 then
                        heading = resolvedRoot.CFrame.LookVector
                    end
                    heading = Vector3.new(heading.X, 0, heading.Z)
                    if heading.Magnitude > 0.05 then
                        heading = heading.Unit
                    else
                        heading = Vector3.zero
                    end

                    for step: number = 0, math.round(placeSettings.ahead) do
                        local spot: Vector3 = base + heading * (grid * step)
                        fireRemote(
                            "ItemsRemotes.PlaceBlock",
                            block,
                            placeSettings.variant,
                            Vector3.new(
                                snap(spot.X, grid),
                                snap(spot.Y, grid),
                                snap(spot.Z, grid)
                            )
                        )
                    end
                end)
        end,
        {parent = scroll, registry = registry, categoryName = "Movement"}
    )
    addNumberOption(ServerScaffoldFeature, "Blocks per second", placeSettings.rate, 1, 20, function(value: number): ()
        placeSettings.rate = value
    end)
    addNumberOption(ServerScaffoldFeature, "Tiles ahead", placeSettings.ahead, 0, 5, function(value: number): ()
        placeSettings.ahead = value
    end)
    addNumberOption(ServerScaffoldFeature, "Grid size", placeSettings.grid, 1, 6, function(value: number): ()
        placeSettings.grid = value
    end)
    addNumberOption(ServerScaffoldFeature, "Variant", placeSettings.variant, 0, 12, function(value: number): ()
        placeSettings.variant = value
    end)
    addTextOption(ServerScaffoldFeature, "Block name", "", function(value: string): ()
        placeSettings.block = value
    end)
    addInformationOption(
        ServerScaffoldFeature,
        "Variant is the second argument, which the client sent as 5 once and 3 "
            .. "another time — most likely the hotbar slot. Leave the block "
            .. "empty to use whatever you are holding, or type one and hold "
            .. "nothing at all."
    )

    local minerSettings: any = {
        tool = "Wooden Pickaxe",

        range = 24,
        rate = 8,
        perTick = 2,
        filter = "",
    }

    local function minableBlocks(origin: Vector3, range: number, filter: string): {BasePart}
        local found: {BasePart} = {}
        local container: Instance? = workspace:FindFirstChild("PlayersBlocksContainer")
        if not container then
            return found
        end
        local wanted: string = string.lower(filter)
        for _, group: Instance in ipairs(container:GetChildren()) do
            for _, block: Instance in ipairs(group:GetChildren()) do
                if not block:IsA("BasePart") then
                    continue
                end
                if wanted ~= ""
                    and not string.find(string.lower(block.Name), wanted, 1, true) then
                    continue
                end
                if ((block :: BasePart).Position - origin).Magnitude > range then
                    continue
                end
                table.insert(found, block :: BasePart)
            end
        end
        table.sort(found, function(first: BasePart, second: BasePart): boolean
            return (first.Position - origin).Magnitude
                < (second.Position - origin).Magnitude
        end)
        return found
    end

    local function mineBlock(block: BasePart, origin: Vector3): ()
        local target: Vector3 = block.Position
        local direction: Vector3 = target - origin
        if direction.Magnitude > 0.001 then
            direction = direction.Unit
        else
            direction = Vector3.new(0, -1, 0)
        end

        fireRemote(
            "ItemsRemotes.MineBlock",
            minerSettings.tool,
            block,
            Vector3.new(
                math.round(target.X),
                math.round(target.Y),
                math.round(target.Z)
            ),
            origin,
            direction
        )
    end

    local MinerFeature: any = createUniversalFeature(
        "Server Miner",
        "Mines the blocks around you without holding a pickaxe",
        10,
        function(enabled: boolean): ()
            host.disconnectFeatureConnection("BedFightMiner")
            if not enabled then
                return
            end
            local nextAt: number = 0
            host.featureConnections.BedFightMiner =
                TaskManager:Connect(function(): ()
                    local now: number = os.clock()
                    if now < nextAt then
                        return
                    end
                    nextAt = now + 1 / math.max(minerSettings.rate, 0.5)

                    local root: BasePart? = LocalPlayer.Character
                        and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") :: BasePart?
                    if not root then
                        return
                    end
                    local origin: Vector3 = (root :: BasePart).Position
                    local blocks: {BasePart} =
                        minableBlocks(origin, minerSettings.range, minerSettings.filter)
                    for index: number = 1, math.min(#blocks, math.round(minerSettings.perTick)) do
                        mineBlock(blocks[index], origin)
                    end
                end)
        end,
        {parent = scroll, registry = registry, categoryName = "Combat"}
    )
    addTextOption(MinerFeature, "Pickaxe", minerSettings.tool, function(value: string): ()
        minerSettings.tool = value
    end)
    addTextOption(MinerFeature, "Only blocks named", "", function(value: string): ()
        minerSettings.filter = value
    end)
    addNumberOption(MinerFeature, "Range", minerSettings.range, 5, 48, function(value: number): ()
        minerSettings.range = value
    end)
    addNumberOption(MinerFeature, "Mines per second", minerSettings.rate, 1, 20, function(value: number): ()
        minerSettings.rate = value
    end)
    addNumberOption(MinerFeature, "Blocks per tick", minerSettings.perTick, 1, 12, function(value: number): ()
        minerSettings.perTick = value
    end)
    addInformationOption(
        MinerFeature,
        "Safe band: about 24 studs and under ten mines a second. The pickaxe "
            .. "is a name, not an object, so nothing has to be equipped — but a "
            .. "player mining thirty blocks a second from across the map is the "
            .. "easiest thing in the game to spot."
    )

    local buySettings: any = {category = "Blocks", item = "Wool", rate = 2, nearest = true}

    local function shopPrompt(): BasePart?
        local root: BasePart? = LocalPlayer.Character
            and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") :: BasePart?
        local origin: Vector3 = root and (root :: BasePart).Position or Vector3.zero
        local best: BasePart? = nil
        local bestDistance: number = math.huge
        for _, mapChild: Instance in ipairs(workspace:GetChildren()) do
            local prompts: Instance? = mapChild:FindFirstChild("ItemShopPrompts")
            if not prompts then
                continue
            end
            for _, prompt: Instance in ipairs(prompts:GetChildren()) do
                if not prompt:IsA("BasePart") then
                    continue
                end
                local distance: number = ((prompt :: BasePart).Position - origin).Magnitude
                if distance < bestDistance then
                    best = prompt :: BasePart
                    bestDistance = distance
                end
            end
        end
        return best
    end

    local BuyFeature: any = createUniversalFeature(
        "Auto Buy",
        "Buys a shop item on a timer through the game's own purchase remote",
        10,
        function(enabled: boolean): ()
            host.disconnectFeatureConnection("BedFightBuy")
            if not enabled then
                return
            end
            local nextAt: number = 0
            host.featureConnections.BedFightBuy =
                TaskManager:Connect(function(): ()
                    local now: number = os.clock()
                    if now < nextAt then
                        return
                    end
                    nextAt = now + 1 / math.max(buySettings.rate, 0.2)
                    local prompt: BasePart? = shopPrompt()
                    if not prompt then
                        return
                    end
                    fireRemote(
                        "PurchaseItemShopItem",
                        prompt,
                        buySettings.category,
                        buySettings.item
                    )
                end)
        end,
        {parent = scroll, registry = registry, categoryName = "Other"}
    )
    addTextOption(BuyFeature, "Category", buySettings.category, function(value: string): ()
        buySettings.category = value
    end)
    addTextOption(BuyFeature, "Item", buySettings.item, function(value: string): ()
        buySettings.item = value
    end)
    addNumberOption(BuyFeature, "Purchases per second", buySettings.rate, 1, 10, function(value: number): ()
        buySettings.rate = value
    end)
    addInformationOption(
        BuyFeature,
        "Observed categories: Blocks, Swords, Pickaxes, Armor. The nearest "
            .. "shop prompt on the map is the one passed to the server. Two a "
            .. "second looks like a person holding the button; twenty does not."
    )

    local QuickFeature: any = createUniversalFeature(
        "Quick Actions",
        "One-shot calls with the arguments the game itself uses",
        11,
        function(): () end,
        {
            parent = scroll,
            registry = registry,
            categoryName = "Other",
            category = true,
        }
    )
    local quickSettings: any = {
        tool = "Wooden Sword",
        armor = "",
        slot = "Pants",
        drop = "Blue Wool",
    }
    addTextOption(QuickFeature, "Tool", quickSettings.tool, function(value: string): ()
        quickSettings.tool = value
    end)
    host.addActionOption(QuickFeature, "Equip tool", function(): ()
        fireRemote("ItemsRemotes.EquipTool", quickSettings.tool)
    end)
    addTextOption(QuickFeature, "Armor", quickSettings.armor, function(value: string): ()
        quickSettings.armor = value
    end)
    addTextOption(QuickFeature, "Armor slot", quickSettings.slot, function(value: string): ()
        quickSettings.slot = value
    end)
    host.addActionOption(QuickFeature, "Wear armor", function(): ()
        fireRemote("WearArmor", quickSettings.armor, quickSettings.slot)
    end)
    addTextOption(QuickFeature, "Drop item", quickSettings.drop, function(value: string): ()
        quickSettings.drop = value
    end)
    host.addActionOption(QuickFeature, "Drop all of it", function(): ()

        fireRemote("ItemsRemotes.DropItem", quickSettings.drop, "All")
    end)
    addInformationOption(
        QuickFeature,
        "EquipTool takes the item's name; WearArmor takes the armor and the "
            .. "slot, which the client sent as (\"\", \"Pants\")."
    )

    Module.Initialized = true
    return Module
end

function Module.destroy(): ()
    local environment: any = getfenv()
    local host: any = environment
    for _, name: string in
        ipairs({
            "BedFightBeds",
            "BedFightGenerators",
            "BedFightInfo",
            "BedFightSwing",
            "BedFightNuker",
            "BedFightVoid",
            "BedFightScaffold",
            "BedFightServerAura",
            "BedFightServerScaffold",
            "BedFightBuy",
            "BedFightMiner",
        })
    do
        if host.disconnectFeatureConnection then
            pcall(host.disconnectFeatureConnection, name)
        end
    end
    clearMarks(runtimeState.bedMarks)
    clearMarks(runtimeState.generatorMarks)
    if runtimeState.infoPanel then
        pcall(function(): ()
            runtimeState.infoPanel.root:Destroy()
        end)
        runtimeState.infoPanel = nil
    end
    if runtimeState.voidPanel then
        pcall(function(): ()
            runtimeState.voidPanel:Destroy()
        end)
        runtimeState.voidPanel = nil
    end
    Module.Initialized = false
end

return Module

]],
        ["src/games/MM2/Blatant/Fling.lua"] = [[
export type Runtime = {
    framework: any,
    entity: any,
    host: any,
    services: any,
}

local Module = {
    Name = "MM2 Fling",
    Events = {} :: {[string]: any},
    Initialized = false,
}

local activeCleanup: (() -> ())? = nil

function Module.init(runtime: any): any
    local host: any = state.frameworkEnvironment
    local core: any = state.mm2Core
    assert(core, "MM2 Fling requires the MM2 core")
    local Players: any = host.Players
    local LocalPlayer: any = host.LocalPlayer
    local getCharacterParts: any = host.getCharacterParts
    local notify: any = host.notify
    local activity: any = services.activity
    local protectedTargets: any = services.protectedTargets
    local gameBridge: any = services.gameBridge
    local createUniversalFeature: any = host.createUniversalFeature
    local addActionOption: any = host.addActionOption
    local addTextOption: any = host.addTextOption
    local addInformationOption: any = host.addInformationOption

    local workspace: any = host.workspace
    local RunService: any = host.RunService

    local findMurderer: any = core.findMurderer
    local findSheriff: any = core.findSheriff
    local getPlayerRole: any = core.getPlayerRole
    local getPlayerWeapon: any = core.getPlayerWeapon
    local isPlayerAlive: any = core.isPlayerAlive

    local flingRunning: boolean = false
    local flingTargetName: string = ""
    local stepAngle: number = 0

    local function setFlingRunning(running: boolean): ()
        flingRunning = running
        activity.set("fling", running)
    end

    local function waitFrameStep(useRenderStep: boolean): ()
        if useRenderStep then
            local okRender: boolean = pcall(function(): ()
                if RunService.RenderStepped and RunService.RenderStepped.Wait then
                    RunService.RenderStepped:Wait()
                elseif RunService.Stepped and RunService.Stepped.Wait then
                    RunService.Stepped:Wait()
                else
                    RunService.Heartbeat:Wait()
                end
            end)
            if not okRender then
                pcall(function(): ()
                    RunService.Heartbeat:Wait()
                end)
            end
        else
            pcall(function(): ()
                RunService.Heartbeat:Wait()
            end)
        end
    end

    local function forceCharacterCollidable(
        character: Model,
        savedCollide: {[BasePart]: boolean},
        savedProps: {[BasePart]: PhysicalProperties?}
    ): ()
        local heavyProps: PhysicalProperties = PhysicalProperties.new(100, 0.3, 0.5, 1, 1)
        for _, child: Instance in ipairs(character:GetChildren()) do
            if child:IsA("BasePart") then
                local part: BasePart = child :: BasePart
                if savedCollide[part] == nil then
                    savedCollide[part] = part.CanCollide
                end
                if savedProps[part] == nil then
                    pcall(function(): ()
                        savedProps[part] = part.CustomPhysicalProperties
                    end)
                end
                pcall(function(): ()
                    part.CanCollide = true
                    part.CustomPhysicalProperties = heavyProps
                end)
            end
        end
    end

    local function restoreCharacterPhysics(
        savedCollide: {[BasePart]: boolean},
        savedProps: {[BasePart]: PhysicalProperties?}
    ): ()
        for part: BasePart, wasCollide: boolean in pairs(savedCollide) do
            if part and part.Parent then
                pcall(function(): ()
                    part.CanCollide = wasCollide
                end)
            end
        end
        for part: BasePart, oldProps: PhysicalProperties? in pairs(savedProps) do
            if part and part.Parent then
                pcall(function(): ()
                    part.CustomPhysicalProperties = oldProps
                end)
            end
        end
        table.clear(savedCollide)
        table.clear(savedProps)
    end

    local function resolveTargetContactPart(targetChar: Model): BasePart?
        return (targetChar:FindFirstChild("HumanoidRootPart") :: BasePart?)
            or (targetChar:FindFirstChild("UpperTorso") :: BasePart?)
            or (targetChar:FindFirstChild("Torso") :: BasePart?)
            or (targetChar:FindFirstChild("Head") :: BasePart?)
            or targetChar:FindFirstChildWhichIsA("BasePart")
    end

    -- Single-step high-impulse contact sweep (usable from per-frame loops
    -- such as Auto Win's Fling Sheriff and Get Gun).
    local function flingSingleStep(
        character: Model,
        humanoid: Humanoid,
        root: BasePart,
        targetPlayer: Player,
        savedCollide: {[BasePart]: boolean}?,
        savedProps: {[BasePart]: PhysicalProperties?}?
    ): boolean
        local targetChar: Model? = targetPlayer and targetPlayer.Character
        if not targetChar then
            return false
        end
        local targetHum: Humanoid? = targetChar:FindFirstChildOfClass("Humanoid")
        local targetPart: BasePart? = resolveTargetContactPart(targetChar)
        if not targetPart or (targetHum and targetHum.Health <= 0) then
            return false
        end
        local destroyHeight: number = workspace.FallenPartsDestroyHeight
        if destroyHeight ~= destroyHeight or math.abs(destroyHeight) > 1e6 then
            destroyHeight = -500
        end
        if targetPart.Position.Y <= destroyHeight + 55 then
            return false
        end

        activity.set("fling", true)
        if savedCollide and savedProps then
            forceCharacterCollidable(character, savedCollide, savedProps)
        else
            pcall(function(): ()
                root.CanCollide = true
                root.CustomPhysicalProperties = PhysicalProperties.new(100, 0.3, 0.5, 1, 1)
            end)
        end

        stepAngle = (stepAngle + 100) % 360
        local phase: number = math.floor(stepAngle / 100) % 4
        local targetVel: Vector3 = Vector3.zero
        local moveDir: Vector3 = Vector3.zero
        pcall(function(): ()
            targetVel = targetPart.AssemblyLinearVelocity
            if targetHum then
                moveDir = targetHum.MoveDirection
            end
        end)

        local leadOffset: Vector3 = if targetVel.Magnitude > 1.5
            then moveDir * math.clamp(targetVel.Magnitude / 1.25, -18, 18)
                + Vector3.new(targetVel.X * 0.08, 0, targetVel.Z * 0.08)
            else Vector3.zero

        local sweepLocal: CFrame
        if phase == 0 then
            sweepLocal = CFrame.new(0, 1.5, 0)
        elseif phase == 1 then
            sweepLocal = CFrame.new(0, -1.5, 0)
        elseif phase == 2 then
            sweepLocal = CFrame.new(2.0, 1.2, -2.0)
        else
            sweepLocal = CFrame.new(-2.0, -1.2, 2.0)
        end

        local rotCF: CFrame = CFrame.Angles(
            math.rad(stepAngle),
            math.rad(stepAngle),
            0
        )
        local finalCF: CFrame = CFrame.new(targetPart.Position + leadOffset)
            * sweepLocal
            * rotCF

        pcall(function(): ()
            if humanoid.Sit then
                humanoid.Sit = false
            end
            humanoid:SetStateEnabled(Enum.HumanoidStateType.Seated, false)
            humanoid.AutoRotate = false
            root.CFrame = finalCF
            character:PivotTo(finalCF)
            root.AssemblyLinearVelocity = Vector3.new(9e7, 9e7 * 10, 9e7)
            root.AssemblyAngularVelocity = Vector3.new(9e8, 9e8, 9e8)
        end)
        return true
    end

    -- Reconstructed full SkidFling / YARHM Fling with BodyVelocity +
    -- high-density collision + 6-phase Heartbeat/RenderStepped FPos sweep.
    local function performFling(targetPlayer: Player?, options: {[string]: any}?): boolean
        if not Module.Initialized or not targetPlayer then
            return false
        end
        if protectedTargets.isProtected(targetPlayer) then
            notify("player protected")
            return false
        end
        local silent: boolean = type(options) == "table" and options.silent == true
        local maxDuration: number = (type(options) == "table" and tonumber(options.duration)) or 5.0
        local shouldStop: (() -> boolean)? = type(options) == "table"
            and type(options.shouldStop) == "function"
            and options.shouldStop
            or nil

        if flingRunning then
            if not silent then
                notify("fling already running")
            end
            return false
        end

        setFlingRunning(true)

        local function runFlingRoutine(): boolean
            local character: Model?, humanoid: Humanoid?, root: BasePart? = getCharacterParts()
            if not character or not humanoid or not root then
                setFlingRunning(false)
                if not silent then
                    notify("character not ready")
                end
                return false
            end

            local savedCFrame: CFrame = (type(options) == "table"
                and typeof(options.returnCFrame) == "CFrame"
                and options.returnCFrame)
                or root.CFrame
            local savedAutoRotate: boolean = humanoid.AutoRotate
            local savedDestroyHeight: number = workspace.FallenPartsDestroyHeight
            if savedDestroyHeight ~= savedDestroyHeight or math.abs(savedDestroyHeight) > 1e6 then
                savedDestroyHeight = -500
            end
            local voidThreshold: number = savedDestroyHeight + 45

            local camera: Camera? = workspace.CurrentCamera
            local savedCameraSubject: any = camera and camera.CameraSubject or nil
            local savedCollide: {[BasePart]: boolean} = {}
            local savedProps: {[BasePart]: PhysicalProperties?} = {}
            local bodyVel: BodyVelocity? = nil

            local touchedTarget: boolean = false
            local reason: string = "timeout"

            local success: boolean, errorMessage: any = pcall(function(): ()
                local startedAt: number = os.clock()
                local angle: number = 0

                pcall(function(): ()
                    workspace.FallenPartsDestroyHeight = 0 / 0
                end)

                humanoid.AutoRotate = false
                if humanoid.Sit then
                    humanoid.Sit = false
                end
                pcall(function(): ()
                    humanoid:SetStateEnabled(Enum.HumanoidStateType.Seated, false)
                end)

                pcall(function(): ()
                    local bv: BodyVelocity = Instance.new("BodyVelocity")
                    bv.Name = "WurstFlingVel"
                    bv.Velocity = Vector3.new(9e8, 9e8, 9e8)
                    bv.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
                    bv.Parent = root
                    bodyVel = bv
                end)

                local function applyFPos(
                    liveChar: Model,
                    liveRoot: BasePart,
                    basePart: BasePart,
                    posOffset: CFrame,
                    angOffset: CFrame
                ): ()
                    local targetCF: CFrame = CFrame.new(basePart.Position)
                        * posOffset
                        * angOffset
                    pcall(function(): ()
                        liveRoot.CFrame = targetCF
                        liveChar:PivotTo(targetCF)
                        liveRoot.AssemblyLinearVelocity = Vector3.new(9e7, 9e7 * 10, 9e7)
                        liveRoot.AssemblyAngularVelocity = Vector3.new(9e8, 9e8, 9e8)
                    end)
                end

                while flingRunning and os.clock() - startedAt < maxDuration do
                    if shouldStop and shouldStop() then
                        reason = "stopped"
                        break
                    end
                    if targetPlayer.Parent == nil then
                        reason = "left"
                        break
                    end

                    local targetCharacter: Model? = targetPlayer.Character
                    local targetHumanoid: Humanoid? = targetCharacter
                        and targetCharacter:FindFirstChildOfClass("Humanoid")
                        :: Humanoid?
                    local targetPart: BasePart? = targetCharacter
                        and resolveTargetContactPart(targetCharacter)
                    if not targetCharacter or not targetPart or not targetPart.Parent then
                        reason = "gone"
                        break
                    end
                    if targetHumanoid and targetHumanoid.Health <= 0 then
                        touchedTarget = true
                        reason = "killed"
                        break
                    end
                    if targetHumanoid and targetHumanoid.Sit then
                        reason = "seated"
                        break
                    end
                    if targetPart.Position.Y <= voidThreshold then
                        touchedTarget = true
                        reason = "void"
                        break
                    end

                    local targetSpeed: number = 0
                    pcall(function(): ()
                        targetSpeed = targetPart.AssemblyLinearVelocity.Magnitude
                    end)
                    if targetSpeed > 250 then
                        touchedTarget = true
                        reason = "flung"
                        break
                    end

                    local liveChar: Model?, liveHumanoid: Humanoid?, liveRoot: BasePart? =
                        getCharacterParts()
                    if not liveChar or not liveHumanoid or not liveRoot or liveHumanoid.Health <= 0 then
                        reason = "died"
                        break
                    end
                    if liveRoot ~= root or liveHumanoid ~= humanoid or liveRoot.Anchored then
                        reason = "died"
                        break
                    end

                    if camera and targetHumanoid then
                        pcall(function(): ()
                            camera.CameraSubject = targetHumanoid
                        end)
                    end

                    forceCharacterCollidable(liveChar, savedCollide, savedProps)

                    pcall(function(): ()
                        (targetPart :: any):SetNetworkOwner(LocalPlayer)
                    end)

                    angle = (angle + 100) % 360
                    local rotCF: CFrame = CFrame.Angles(math.rad(angle), 0, 0)
                    local moveDir: Vector3 = targetHumanoid
                        and targetHumanoid.MoveDirection
                        or Vector3.zero
                    local velMag: number = math.clamp(targetSpeed / 1.25, 0, 25)

                    if targetSpeed < 1.5 then
                        applyFPos(
                            liveChar,
                            liveRoot,
                            targetPart,
                            CFrame.new(0, 1.5, 0) + moveDir * velMag,
                            rotCF
                        )
                        waitFrameStep(false)

                        applyFPos(
                            liveChar,
                            liveRoot,
                            targetPart,
                            CFrame.new(0, -1.5, 0) + moveDir * velMag,
                            rotCF
                        )
                        waitFrameStep(true)

                        applyFPos(
                            liveChar,
                            liveRoot,
                            targetPart,
                            CFrame.new(2.25, 1.5, -2.25) + moveDir * velMag,
                            rotCF
                        )
                        waitFrameStep(false)

                        applyFPos(
                            liveChar,
                            liveRoot,
                            targetPart,
                            CFrame.new(-2.25, -1.5, 2.25) + moveDir * velMag,
                            rotCF
                        )
                        waitFrameStep(true)
                    else
                        applyFPos(
                            liveChar,
                            liveRoot,
                            targetPart,
                            CFrame.new(0, 1.5, velMag) + moveDir * velMag,
                            rotCF
                        )
                        waitFrameStep(false)

                        applyFPos(
                            liveChar,
                            liveRoot,
                            targetPart,
                            CFrame.new(0, -1.5, -velMag) + moveDir * velMag,
                            rotCF
                        )
                        waitFrameStep(true)

                        applyFPos(
                            liveChar,
                            liveRoot,
                            targetPart,
                            CFrame.new(0, 1.5, 0) + moveDir,
                            rotCF
                        )
                        waitFrameStep(false)

                        applyFPos(
                            liveChar,
                            liveRoot,
                            targetPart,
                            CFrame.new(0, -1.5, 0) + moveDir,
                            rotCF
                        )
                        waitFrameStep(true)
                    end
                end
            end)

            if bodyVel then
                pcall(function(): ()
                    bodyVel:Destroy()
                end)
                bodyVel = nil
            end

            restoreCharacterPhysics(savedCollide, savedProps)

            local finalChar: Model?, finalHumanoid: Humanoid?, finalRoot: BasePart? =
                getCharacterParts()
            if finalHumanoid then
                pcall(function(): ()
                    finalHumanoid:SetStateEnabled(Enum.HumanoidStateType.Seated, true)
                    finalHumanoid.PlatformStand = false
                    finalHumanoid.AutoRotate = savedAutoRotate
                    finalHumanoid:ChangeState(Enum.HumanoidStateType.GettingUp)
                end)
                if camera then
                    pcall(function(): ()
                        camera.CameraSubject = savedCameraSubject or finalHumanoid
                    end)
                end
            end
            if finalChar and finalRoot and finalRoot.Parent then
                local returnCF: CFrame = savedCFrame + Vector3.new(0, 2, 0)
                for _ = 1, 5 do
                    pcall(function(): ()
                        for _, part: Instance in ipairs(finalChar:GetChildren()) do
                            if part:IsA("BasePart") then
                                (part :: BasePart).AssemblyLinearVelocity = Vector3.zero;
                                (part :: BasePart).AssemblyAngularVelocity = Vector3.zero
                            end
                        end
                        finalRoot.CFrame = returnCF
                        finalChar:PivotTo(returnCF)
                    end)
                    if (finalRoot.Position - returnCF.Position).Magnitude <= 6 then
                        break
                    end
                    waitFrameStep(false)
                end
            end

            pcall(function(): ()
                workspace.FallenPartsDestroyHeight = savedDestroyHeight
            end)

            setFlingRunning(false)
            if not Module.Initialized then
                return touchedTarget
            end
            if not silent then
                if not success then
                    notify("fling failed: " .. tostring(errorMessage))
                elseif touchedTarget then
                    notify("fling complete: " .. targetPlayer.Name .. " went down.")
                elseif reason == "left" then
                    notify("fling stopped: " .. targetPlayer.Name .. " left the game.")
                elseif reason == "gone" then
                    notify("Fling stopped: the target character disappeared.")
                elseif reason == "died" then
                    notify("Fling stopped: your character died.")
                elseif reason == "seated" then
                    notify("Fling stopped: target is seated.")
                else
                    notify(
                        "Fling stopped after "
                            .. string.format("%.0f", maxDuration)
                            .. "s of flight."
                    )
                end
            end
            return touchedTarget
        end

        if type(options) == "table" and options.blocking == true then
            return runFlingRoutine()
        end
        task.spawn(runFlingRoutine)
        return true
    end

    state.mm2PerformFling = performFling
    state.mm2FlingStep = flingSingleStep

    local function refreshRoles(): ()
        if type(state.clearRoleMemo) == "function" then
            pcall(state.clearRoleMemo)
        end
        if type(core.requestRoleRefresh) == "function" then
            pcall(core.requestRoleRefresh, false)
        end
    end

    local function resolveMurdererTarget(): Player?
        refreshRoles()
        -- 1) Ground truth: any living player holding/carrying the Knife
        --    (and never holding the Gun).
        if type(getPlayerWeapon) == "function" then
            for _, player: Player in ipairs(Players:GetPlayers()) do
                if player ~= LocalPlayer
                    and (type(isPlayerAlive) ~= "function" or isPlayerAlive(player))
                    and getPlayerWeapon(player, "Gun", false) == nil
                    and getPlayerWeapon(player, "Knife", false) ~= nil then
                    return player
                end
            end
        end
        -- 2) MM2 core findMurderer(), double-checked against Gun possession.
        if type(findMurderer) == "function" then
            local target: Player? = findMurderer()
            if target
                and target ~= LocalPlayer
                and (type(isPlayerAlive) ~= "function" or isPlayerAlive(target))
                and (type(getPlayerWeapon) ~= "function"
                    or getPlayerWeapon(target, "Gun", false) == nil) then
                local role: any = type(getPlayerRole) == "function"
                    and getPlayerRole(target)
                    or "Murderer"
                if role ~= "Hero" and role ~= "Sheriff" and role ~= "Dead" then
                    return target
                end
            end
        end
        -- 3) Fallback scan across getPlayerRole / gameBridge.playerRole.
        for _, player: Player in ipairs(Players:GetPlayers()) do
            if player ~= LocalPlayer
                and (type(isPlayerAlive) ~= "function" or isPlayerAlive(player))
                and (type(getPlayerWeapon) ~= "function"
                    or getPlayerWeapon(player, "Gun", false) == nil) then
                local role: any = type(getPlayerRole) == "function"
                    and getPlayerRole(player)
                    or nil
                if not role and type(gameBridge.playerRole) == "function" then
                    local okRole: boolean, r: any = pcall(gameBridge.playerRole, player)
                    if okRole then
                        role = r
                    end
                end
                if role == "Murderer" then
                    return player
                end
            end
        end
        return nil
    end

    local function resolveSheriffOrHeroTarget(): Player?
        refreshRoles()
        -- 1) Ground truth: any living player holding/carrying the Gun
        --    (and never holding the Knife).
        if type(getPlayerWeapon) == "function" then
            for _, player: Player in ipairs(Players:GetPlayers()) do
                if player ~= LocalPlayer
                    and (type(isPlayerAlive) ~= "function" or isPlayerAlive(player))
                    and getPlayerWeapon(player, "Knife", false) == nil
                    and getPlayerWeapon(player, "Gun", false) ~= nil then
                    return player
                end
            end
        end
        -- 2) MM2 core findSheriff(), double-checked against Knife possession.
        if type(findSheriff) == "function" then
            local target: Player? = findSheriff()
            if target
                and target ~= LocalPlayer
                and (type(isPlayerAlive) ~= "function" or isPlayerAlive(target))
                and (type(getPlayerWeapon) ~= "function"
                    or getPlayerWeapon(target, "Knife", false) == nil) then
                local role: any = type(getPlayerRole) == "function"
                    and getPlayerRole(target)
                    or "Sheriff"
                if role ~= "Murderer" and role ~= "Dead" then
                    return target
                end
            end
        end
        -- 3) Fallback scan across getPlayerRole / gameBridge.playerRole.
        for _, player: Player in ipairs(Players:GetPlayers()) do
            if player ~= LocalPlayer
                and (type(isPlayerAlive) ~= "function" or isPlayerAlive(player))
                and (type(getPlayerWeapon) ~= "function"
                    or getPlayerWeapon(player, "Knife", false) == nil) then
                local role: any = type(getPlayerRole) == "function"
                    and getPlayerRole(player)
                    or nil
                if not role and type(gameBridge.playerRole) == "function" then
                    local okRole: boolean, r: any = pcall(gameBridge.playerRole, player)
                    if okRole then
                        role = r
                    end
                end
                if role == "Sheriff" or role == "Hero" then
                    return player
                end
            end
        end
        return nil
    end

    local FlingFeature: any = createUniversalFeature(
        "Fling",
        "MM2 only: fling the murderer, sheriff or innocents",
        2,
        function() end,
        {category = true, categoryName = "Exploits", registry = mm2Features, configKey = "MM2.Fling"}
    )
    addActionOption(FlingFeature, "Fling Murderer", function(): ()
        local target: Player? = resolveMurdererTarget()
        if target then
            performFling(target)
        else
            notify("No murderer was found.")
        end
    end)
    addActionOption(FlingFeature, "Fling Sheriff", function(): ()
        local target: Player? = resolveSheriffOrHeroTarget()
        if target then
            performFling(target)
        else
            notify("No sheriff or hero was found.")
        end
    end)
    addActionOption(FlingFeature, "Fling All Innocents", function(): ()
        refreshRoles()
        task.spawn(function(): ()
            for _, player: Player in ipairs(Players:GetPlayers()) do
                if player ~= LocalPlayer
                    and (type(isPlayerAlive) ~= "function" or isPlayerAlive(player)) then
                    local hasKnife: boolean = type(getPlayerWeapon) == "function"
                        and getPlayerWeapon(player, "Knife", false) ~= nil
                    local hasGun: boolean = type(getPlayerWeapon) == "function"
                        and getPlayerWeapon(player, "Gun", false) ~= nil
                    local role: any = type(getPlayerRole) == "function"
                        and getPlayerRole(player)
                        or nil
                    if not role and type(gameBridge.playerRole) == "function" then
                        local okRole: boolean, r: any = pcall(gameBridge.playerRole, player)
                        if okRole then
                            role = r
                        end
                    end
                    if not hasKnife and not hasGun and role == "Innocent" then
                        performFling(player, {blocking = true})
                        task.wait(0.05)
                    end
                end
            end
        end)
    end)
    addTextOption(
        FlingFeature,
        "Target player",
        "",
        function(value: string): ()
            flingTargetName = value
        end,
        false,
        "Exact or partial name"
    )
    addActionOption(FlingFeature, "Fling", function(): ()
        local needle: string = string.lower(
            string.gsub(flingTargetName or "", "%s+", "")
        )
        if needle == "" then
            notify("Type a player name in the Target player box first.")
            return
        end
        local exact: Player? = nil
        local partial: Player? = nil
        for _, player: Player in ipairs(Players:GetPlayers()) do
            if player ~= LocalPlayer then
                local name: string = string.lower(player.Name)
                if string.gsub(name, "%s+", "") == needle then
                    exact = player
                    break
                end
                if not partial and string.find(name, needle, 1, true) then
                    partial = player
                end
            end
        end
        local target: Player? = exact or partial
        if target then
            performFling(target)
        else
            notify("No player named \"" .. flingTargetName .. "\" was found.")
        end
    end)
    addInformationOption(
        FlingFeature,
        "MM2 only. Choose a role action, or enter a player name and press Fling."
    )

    activeCleanup = function(): ()
        setFlingRunning(false)
        state.mm2PerformFling = nil
        state.mm2FlingStep = nil
    end
    Module.Initialized = true
    return FlingFeature
end

function Module.destroy(): ()
    if activeCleanup then
        pcall(activeCleanup)
    end
    activeCleanup = nil
    Module.Initialized = false
end

return Module

]],
        ["src/games/MM2/Blatant/KnifeAura.lua"] = [=[
local Module = {
    Name = "MM2 Knife Aura",
    Events = {} :: {[string]: any},
    Initialized = false,
    Runtime = nil :: any,
}

local activeCleanup: () -> () = function(): () end

function Module.init(runtime: any): any
    if Module.Initialized then
        return Module
    end
    local core: any = state.mm2Core
    assert(type(core) == "table", "MM2 Knife Aura requires the MM2 core module")
    Module.Runtime = runtime
    local getPlayerRole: any = core.getPlayerRole
    local getPlayerWeapon: any = core.getPlayerWeapon
    local isPlayerAlive: any = core.isPlayerAlive
    local isProtectedTarget: any = core.isProtectedTarget
    local trajectoryCalibration: any = core.trajectoryCalibration

    type KnifeRuntimeState = {
        masterEnabled: boolean,
        auraWanted: boolean,
        throwWanted: boolean,
        lastAuraSwing: number,
    }

    local knifeSettings: any = {
        aura = false,
        auraRange = 14,
    }
    state.mm2KnifeRuntime = {
        masterEnabled = false,
        auraWanted = false,
        throwWanted = false,
        lastAuraSwing = -math.huge,
    } :: KnifeRuntimeState

    local function getEffectiveRange(): number
        return knifeSettings.auraRange or 14
    end

    local function getEquippedWeapon(name: string, _tag: string): Tool?
        return getPlayerWeapon(LocalPlayer, name, true)
    end

    local function canUseEquippedKnife(): (Tool?, BasePart?)
        local character: Model? = LocalPlayer.Character
        local humanoid: Humanoid? = character
            and character:FindFirstChildOfClass("Humanoid")
            :: Humanoid?
        local root: BasePart? = character
            and character:FindFirstChild("HumanoidRootPart")
            :: BasePart?
        local knife: Tool? = getEquippedWeapon("Knife", "Weapon_Knife")
        if not character
            or not humanoid
            or humanoid.Health <= 0
            or not root
            or not knife
            or knife:GetAttribute("Disabled") == true
            or getPlayerRole(LocalPlayer) ~= "Murderer" then
            return nil, nil
        end
        return knife, root
    end

    local function isValidKnifeTarget(player: Player): boolean
        if player == LocalPlayer
            or isProtectedTarget(player)
            or not isPlayerAlive(player)
            or getPlayerRole(player) == "Murderer" then
            return false
        end
        return player.Character ~= nil
            and player.Character:FindFirstChild("HumanoidRootPart") ~= nil
    end

    local function findKnifeAuraTarget(
        localRoot: BasePart,
        maxDistance: number
    ): Player?
        local closest: Player? = nil
        local closestDistance: number = maxDistance
        for _, player: Player in ipairs(Players:GetPlayers()) do
            if isValidKnifeTarget(player) then
                local targetRoot: BasePart? = player.Character
                    and player.Character:FindFirstChild("HumanoidRootPart")
                    :: BasePart?
                if targetRoot then
                    local distance: number =
                        (targetRoot.Position - localRoot.Position).Magnitude
                    if distance <= closestDistance then
                        closest = player
                        closestDistance = distance
                    end
                end
            end
        end
        return closest
    end

    local function processKnifeAura(): ()
        if os.clock() - state.mm2KnifeRuntime.lastAuraSwing < 0.86 then return end
        local knife: Tool?, localRoot: BasePart? = canUseEquippedKnife()
        if not knife or not localRoot then
            return
        end

        local currentRange: number = getEffectiveRange()
        local target: Player? =
            findKnifeAuraTarget(localRoot, currentRange)
        local targetCharacter: Model? = target and target.Character
        local targetRoot: BasePart? = targetCharacter
            and targetCharacter:FindFirstChild("HumanoidRootPart")
            :: BasePart?
        if not target
            or not targetCharacter
            or not targetRoot
            or (targetRoot.Position - localRoot.Position).Magnitude
                > currentRange
            or os.clock() - state.mm2KnifeRuntime.lastAuraSwing < 0.86 then
            return
        end

        local handle: BasePart? = knife:FindFirstChild("Handle") :: BasePart?
        if not handle or not handle:IsA("BasePart") then
            return
        end

        state.mm2KnifeRuntime.lastAuraSwing = os.clock()
        local events: Instance? = knife:FindFirstChild("Events")
        local handleTouched: Instance? = events
            and events:FindFirstChild("HandleTouched")
        knife:Activate()
        task.delay(0.025, function(): ()
            local currentKnife: Tool?, currentLocalRoot: BasePart? =
                canUseEquippedKnife()
            local currentCharacter: Model? = target.Character
            local currentRoot: BasePart? = currentCharacter
                and currentCharacter:FindFirstChild("HumanoidRootPart")
                :: BasePart?
            local currentHandle: BasePart? =
                knife:FindFirstChild("Handle") :: BasePart?
            if not knifeSettings.aura
                or currentKnife ~= knife
                or not currentLocalRoot
                or currentCharacter ~= targetCharacter
                or not isValidKnifeTarget(target)
                or not currentRoot
                or not currentHandle
                or not currentHandle:IsA("BasePart")
                or (currentRoot.Position - currentLocalRoot.Position).Magnitude
                    > getEffectiveRange() then
                return
            end

            if handleTouched and handleTouched:IsA("RemoteEvent") then
                handleTouched:FireServer(currentRoot)
            elseif type(state.fireTouchInterest) == "function" then
                pcall(state.fireTouchInterest, currentHandle, currentRoot, 0)
                pcall(state.fireTouchInterest, currentHandle, currentRoot, 1)
            end
            pcall(trajectoryCalibration.noteAuthoredShot, trajectoryCalibration, {
                kind = "stab",
                toolName = "Knife",
                originPos = currentLocalRoot.Position,
                aimPos = currentRoot.Position,
                target = target,
            })
        end)
    end

    local function refreshKnifeController(): ()
        disconnectFeatureConnection("MM2KnifeVirtualHitbox")
        disconnectFeatureConnection("MM2KnifeAura")
        disconnectFeatureConnection("MM2KnifeController")
        if not knifeSettings.aura or not state.mm2KnifeRuntime.masterEnabled then
            return
        end

        local elapsed: number = 0
        featureConnections.MM2KnifeController =
            TaskManager:Connect(function(deltaTime: number): ()
                elapsed += math.max(0, deltaTime)
                local interval: number = 1 / 20
                if elapsed + 1e-9 < interval then return end
                elapsed = elapsed % interval
                processKnifeAura()
            end)
    end

    local function toggleKnifeAura(enabled: boolean): ()
        knifeSettings.aura = enabled
        state.mm2KnifeRuntime.auraWanted = enabled
        state.mm2KnifeRuntime.lastAuraSwing = -math.huge
        refreshKnifeController()
    end

    local killedCharacterByPlayer: {[Player]: Model} = {}
    local killPlayerOption: any = nil

    local function isLivingInnocentCandidate(player: Player): boolean
        if player == LocalPlayer
            or isProtectedTarget(player)
            or not isPlayerAlive(player) then
            return false
        end
        local character: Model? = player.Character
        if not character or killedCharacterByPlayer[player] == character then
            return false
        end
        local humanoid: Humanoid? = character:FindFirstChildOfClass("Humanoid") :: Humanoid?
        local root: BasePart? = character:FindFirstChild("HumanoidRootPart") :: BasePart?
        if not humanoid or humanoid.Health <= 0 or not root then
            return false
        end
        local role: any = getPlayerRole(player)
        if role == "Murderer" or role == "Dead" or role == "None" then
            return false
        end
        return true
    end

    local function getLivingInnocentNames(): {string}
        local names: {string} = {}
        for _, player: Player in ipairs(Players:GetPlayers()) do
            if isLivingInnocentCandidate(player) then
                table.insert(names, player.Name)
            end
        end
        table.sort(names)
        return names
    end

    local function equipKnifeForKill(): (Model?, Humanoid?, BasePart?, Tool?)
        if getPlayerRole(LocalPlayer) ~= "Murderer" then
            if type(notify) == "function" then
                notify("Kill Aura: Only the Murderer can use Kill All / Kill Player.")
            end
            return nil, nil, nil, nil
        end
        local character: Model? = LocalPlayer.Character
        local humanoid: Humanoid? = character
            and (character:FindFirstChildOfClass("Humanoid") :: Humanoid?)
        local myRoot: BasePart? = character
            and (character:FindFirstChild("HumanoidRootPart") :: BasePart?)
        if not character or not humanoid or humanoid.Health <= 0 or not myRoot then
            return nil, nil, nil, nil
        end
        local knife: Tool? = getPlayerWeapon(LocalPlayer, "Knife", false)
        if not knife then
            if type(notify) == "function" then
                notify("Kill Aura: No Knife found.")
            end
            return nil, nil, nil, nil
        end
        if knife.Parent ~= character then
            pcall(function(): ()
                humanoid:EquipTool(knife :: Tool)
            end)
            local deadline: number = os.clock() + 0.3
            while knife.Parent ~= character and os.clock() < deadline do
                task.wait()
            end
        end
        if knife.Parent ~= character then
            return nil, nil, nil, nil
        end
        return character, humanoid, myRoot, knife
    end

    local function executeKnifeKillOnTargets(targets: {Player}): ()
        if #targets == 0 then
            return
        end
        local _, _, myRoot: BasePart?, knife: Tool? = equipKnifeForKill()
        if not myRoot or not knife then
            return
        end
        local handle: BasePart? = knife:FindFirstChild("Handle") :: BasePart?
        local victimRoots: {BasePart} = {}
        for _, target: Player in ipairs(targets) do
            if isLivingInnocentCandidate(target) then
                local targetChar: Model? = target.Character
                local victimRoot: BasePart? = targetChar
                    and (targetChar:FindFirstChild("HumanoidRootPart") :: BasePart?)
                if targetChar and victimRoot then
                    killedCharacterByPlayer[target] = targetChar
                    table.insert(victimRoots, victimRoot)
                    pcall(function(): ()
                        victimRoot.Anchored = true
                        victimRoot.CFrame = myRoot.CFrame + myRoot.CFrame.LookVector * 1
                    end)
                end
            end
        end
        if killPlayerOption and type(killPlayerOption.Refresh) == "function" then
            pcall(function(): ()
                killPlayerOption:Refresh()
            end)
        end
        if #victimRoots == 0 then
            return
        end
        task.wait(0.1)
        local stab: Instance? = knife:FindFirstChild("Stab")
        if stab and stab:IsA("RemoteEvent") then
            pcall(function(): ()
                (stab :: RemoteEvent):FireServer("Slash")
            end)
        end
        local events: Instance? = knife:FindFirstChild("Events")
        local handleTouched: Instance? = events
            and events:FindFirstChild("HandleTouched")
        pcall(function(): ()
            knife:Activate()
        end)
        local fireTouch: any = state.fireTouchInterest
        for _, victimRoot: BasePart in ipairs(victimRoots) do
            if handleTouched and handleTouched:IsA("RemoteEvent") then
                pcall(function(): ()
                    (handleTouched :: RemoteEvent):FireServer(victimRoot)
                end)
            end
            if handle and handle:IsA("BasePart") and type(fireTouch) == "function" then
                pcall(fireTouch, handle, victimRoot, 0)
                pcall(fireTouch, handle, victimRoot, 1)
            end
            task.wait(0.04)
        end
        task.delay(0.45, function(): ()
            for _, victimRoot: BasePart in ipairs(victimRoots) do
                pcall(function(): ()
                    victimRoot.Anchored = false
                end)
            end
        end)
    end

    local function killAllPlayersAction(): ()
        task.spawn(function(): ()
            local targets: {Player} = {}
            for _, player: Player in ipairs(Players:GetPlayers()) do
                if isLivingInnocentCandidate(player) then
                    table.insert(targets, player)
                end
            end
            executeKnifeKillOnTargets(targets)
        end)
    end

    local aura: any = state.framework and state.framework:GetModule("KillAura")
    assert(aura, "MM2 Knife requires the existing KillAura module")
    local wasEnabled: boolean = aura.Enabled
    if type(configData) == "table" and not configData.values["MM2.Knife.MigratedToKillAura"] then
        for _, label: string in ipairs({"KnifeAura"}) do
            local old: any = configData.states["MM2.Knife." .. label]
            local key: string = "Universal.KillAura." .. label
            if configData.states[key] == nil and old ~= nil then configData.states[key] = old end
        end
        for _, pair in ipairs({
            {"MM2.Knife.AuraRange", "Universal.KillAura.AuraRange"},
            {"Shortcut.MM2Knife", "Shortcut.UniversalKillAura"},
        }) do
            if configData.values[pair[2]] == nil then configData.values[pair[2]] = configData.values[pair[1]] end
        end
        wasEnabled = wasEnabled or configData.states["MM2.Knife"] == true
        configData.values["MM2.Knife.MigratedToKillAura"] = true
        if type(queueConfigSave) == "function" then queueConfigSave() end
    end
    if wasEnabled then aura:Toggle(false) end
    local KnifeFeature: any = aura.Feature
    local originalDescription: string = KnifeFeature.description
    local originalSearch: string = KnifeFeature.searchText
    KnifeFeature.description = "MM2 melee combat: Knife Aura stabs with your held knife. Includes Kill All and Kill Player."
    KnifeFeature.tooltipText = KnifeFeature.description
    KnifeFeature.searchText = "killaura combat mm2 knife aura range kill all kill player"
    aura.CombatAdapter = function(enabled: boolean): ()
        state.mm2KnifeRuntime.masterEnabled = enabled
        refreshKnifeController()
        aura:SetStatus(enabled and "Knife" or nil)
    end
    -- Generic melee controls do not describe the MM2 remote-based controller.
    aura.OptionFilter = function(name: string): boolean
        return name == "Knife Aura"
            or name == "Aura Range"
            or name == "Kill All"
            or name == "Kill Player"
    end
    aura:RefreshVisibility()
    state.mm2KnifeAuraModule = aura
    state.mm2KnifeFeature = KnifeFeature

    aura:CreateToggle({Name = "Knife Aura", Default = true, Function = toggleKnifeAura,
        Tooltip = "MM2 stabs with your equipped knife while KillAura is ON."})
    aura:CreateSlider({Name = "Aura Range", Min = 7, Max = 30, Default = 14,
        Show = {Option = "Knife Aura", Values = {true}},
        Function = function(value: number): () knifeSettings.auraRange = value end})
    aura:CreateButton({
        Name = "Kill All",
        Function = killAllPlayersAction,
        Tooltip = "As Murderer, equip your Knife and eliminate all living Innocent/Sheriff players.",
    })
    local killPlayerReady: boolean = false
    local suppressKillPlayerCallback: boolean = false
    killPlayerOption = aura:CreateList({
        Name = "Kill Player",
        Items = getLivingInnocentNames,
        Single = true,
        EmptyText = "No living innocents",
        Tooltip = "Click to pick a living Innocent player to kill. Dead or eliminated players are removed from the list.",
        Function = function(_selected: any, names: {string}): ()
            if not killPlayerReady or suppressKillPlayerCallback then
                return
            end
            local chosenName: string? = names and names[1]
            if not chosenName or chosenName == "" then
                return
            end
            local targetPlayer: Player? = nil
            for _, player: Player in ipairs(Players:GetPlayers()) do
                if player.Name == chosenName and isLivingInnocentCandidate(player) then
                    targetPlayer = player
                    break
                end
            end
            suppressKillPlayerCallback = true
            if killPlayerOption and type(killPlayerOption.Set) == "function" then
                pcall(function(): ()
                    killPlayerOption:Set(chosenName, false)
                end)
            end
            suppressKillPlayerCallback = false
            if targetPlayer then
                local victim: Player = targetPlayer :: Player
                task.spawn(function(): ()
                    executeKnifeKillOnTargets({victim})
                end)
            end
        end,
    })
    if killPlayerOption and type(killPlayerOption.Selected) == "table" and #killPlayerOption.Selected > 0 then
        suppressKillPlayerCallback = true
        for _, staleName: string in ipairs(table.clone(killPlayerOption.Selected)) do
            pcall(function(): ()
                killPlayerOption:Set(staleName, false)
            end)
        end
        suppressKillPlayerCallback = false
    end
    killPlayerReady = true
    if wasEnabled then aura:Toggle(true) end

    activeCleanup = function(): ()
        if aura.Enabled then aura:Toggle(false) end
        toggleKnifeAura(false)
        table.clear(killedCharacterByPlayer)
        state.mm2KnifeRuntime.masterEnabled = false
        state.mm2KnifeFeature = nil
        state.mm2KnifeAuraModule = nil
        aura.CombatAdapter = nil
        KnifeFeature.description = originalDescription
        KnifeFeature.tooltipText = originalDescription
        KnifeFeature.searchText = originalSearch
        -- If the adapter is detached before the whole UI is destroyed, do
        -- not expose stale MM2 actions beside the generic controls.
        aura.OptionFilter = function(name: string): boolean
            return name ~= "Knife Aura"
                and name ~= "Aura Range"
                and name ~= "Kill All"
                and name ~= "Kill Player"
        end
        aura:RefreshVisibility()
    end
    Module.Events = featureConnections
    Module.Initialized = true
    return Module
end

function Module.destroy(): ()
    if not Module.Initialized then
        return
    end
    Module.Initialized = false
    pcall(activeCleanup)
    activeCleanup = function(): () end
    Module.Events = {}
    Module.Runtime = nil
end

return Module

]=],
        ["src/games/MM2/Blatant/Shoot.lua"] = [[
local Module = {
    Name = "MM2 Shoot",
    Events = {} :: {[string]: any},
    Initialized = false,
    Runtime = nil :: any,
}

local activeCleanup: () -> () = function(): () end

function Module.init(runtime: any): any
    if Module.Initialized then
        return Module
    end
    local core: any = state.mm2Core
    assert(type(core) == "table", "MM2 Shoot requires the MM2 core module")
    local prediction: any = state.mm2Prediction
    assert(type(prediction) == "table", "MM2 Shoot requires MM2 Prediction")
    local trajectoryCalibration: any = core.trajectoryCalibration
    Module.Runtime = runtime
    local connectGunFiredSignal: any = core.connectGunFiredSignal
    local disconnectGunFiredObserver: any = core.disconnectGunFiredObserver
    local findMurderer: any = core.findMurderer
    local getGunOriginCFrame: any = core.getGunOriginCFrame
    local getPlayerRole: any = core.getPlayerRole
    local getPlayerWeapon: any = core.getPlayerWeapon
    local getWeaponServiceModule: any = core.getWeaponServiceModule
    local isPlayerAlive: any = core.isPlayerAlive
    local isProtectedTarget: any = core.isProtectedTarget
    local isWeaponPathClear: any = core.isWeaponPathClear
    local mm2Settings: any = core.mm2Settings
    local validateGunShot: any = core.validateGunShot

    local shootMacro: boolean = false
    -- First thing the untouched ray meets on an allowed shot (nil if nothing
    -- short of the aim). Persisted into the shot's settings.
    local lastGunOccluder: any = nil
    local function macroUnequip(gun: Tool?): ()
        if not shootMacro or not gun then
            return
        end
        task.delay(0.01, function(): ()
            pcall(function(): ()
                local backpack: Instance? = LocalPlayer:FindFirstChildOfClass("Backpack")
                local character: Model? = LocalPlayer.Character
                if backpack and character and gun.Parent == character then
                    gun.Parent = backpack
                end
            end)
        end)
    end

    local function getSelectedShootTarget(): Player?
        local target
        if mm2Settings.shootMode == "Custom"
            and mm2Settings.shootTarget ~= "" then
            target = findPlayerByText(mm2Settings.shootTarget)
        else
            target = findMurderer()
        end
        if not target
            or target == LocalPlayer
            or not isPlayerAlive(target)
            or isProtectedTarget(target) then
            return nil
        end
        if getPlayerRole(target) ~= "Murderer" then
            return nil
        end
        return target
    end

    local function bystanderOnSegment(
        target: Player,
        startPoint: Vector3,
        endPoint: Vector3
    ): boolean
        local parameters: RaycastParams = RaycastParams.new()
        parameters.FilterType = Enum.RaycastFilterType.Include
        parameters.IgnoreWater = true
        local bodies: {Instance} = {}
        for _, player: Player in ipairs(Players:GetPlayers()) do
            if player ~= target
                and player ~= LocalPlayer
                and player.Character
                and isPlayerAlive(player) then
                table.insert(bodies, player.Character)
            end
        end
        if #bodies == 0 then
            return false
        end
        parameters.FilterDescendantsInstances = bodies
        return workspace:Raycast(startPoint, endPoint - startPoint, parameters) ~= nil
    end

    local SILENT_ORIGIN_STUDS: number = 2.5
    local SILENT_PIERCE_STUDS: number = 1.0
    local SILENT_LIFT_STUDS: number = 1.6
    local MAX_SILENT_SWEEP: number = 1.5
    local OVERSHOOT_PROBE_STUDS: number = 12
    local MAX_AUTO_LEAD_SAFE: number = 0.6

    -- The Top/fallback origin lift belongs to the target's rig, not to a
    -- universal constant: R6 and R15 put the head at different heights
    -- above the root, and an origin spawned inside the head can be
    -- ignored by the shot. Predicted endpoint minus predicted root is
    -- the same aim offset the predictor sampled from the live rig.
    local function silentLift(info: any, predicted: Vector3): number
        if type(info) == "table"
            and typeof(info.rootPosition) == "Vector3" then
            local aimOffsetY: number = predicted.Y - info.rootPosition.Y
            if aimOffsetY > 0.5 then
                return math.clamp(aimOffsetY + 0.35, 1.2, 2.4)
            end
        end
        return SILENT_LIFT_STUDS
    end

    -- The server ray is not clipped at our authored endpoint, so the
    -- bystander check covers the segment plus an overshoot probe: a
    -- body just behind the target would take the continuing ray.
    local function bystanderBlocks(
        target: Player,
        startPoint: Vector3,
        endPoint: Vector3
    ): boolean
        if bystanderOnSegment(target, startPoint, endPoint) then
            return true
        end
        local segment: Vector3 = endPoint - startPoint
        if segment.Magnitude <= 0.05 then
            return false
        end
        local beyond: Vector3 = endPoint
            + segment.Unit * OVERSHOOT_PROBE_STUDS
        return bystanderOnSegment(target, endPoint, beyond)
    end

    -- The bypass segment runs along the target's own motion. A fixed extra
    -- length guesses; the confirmed shots already measure how far the aim
    -- lands from the body, so the same measurement decides how much segment
    -- the shot needs. With no confirmations yet the uncertainty is zero and
    -- the configured value is used untouched.
    local function getSilentSweepDistance(speed: number?): number
        local configured: number = tonumber(mm2Settings.silentSweep) or 0
        local sweep: number = math.clamp(configured, 0, MAX_SILENT_SWEEP)
        local uncertainty: number = 0
        if type(prediction) == "table"
            and type(prediction.getLeadUncertainty) == "function" then
            local ok: boolean, seconds: any = pcall(
                prediction.getLeadUncertainty
            )
            if ok and type(seconds) == "number" and seconds == seconds then
                uncertainty = math.clamp(seconds, 0, 0.15)
            end
        end
        if uncertainty <= 0 then
            return sweep
        end
        local travel: number = math.max(tonumber(speed) or 0, 0)
        local extra: number = uncertainty * travel
        return math.clamp(sweep + extra, 0, MAX_SILENT_SWEEP)
    end

    local function buildSilentShot(
        target: Player,
        info: any,
        muzzleOrigin: CFrame?,
        variant: string
    ): (CFrame?, CFrame?, number, number, string)
        local predicted: Vector3 = info.endpoint
        local liftStuds: number = silentLift(info, predicted)
        local velocity: Vector3 = info.velocity
        local horizontal: Vector3 = Vector3.new(velocity.X, 0, velocity.Z)

        local direction: Vector3? = nil
        local sweep: number = 0
        if horizontal.Magnitude > 1.5 then
            direction = horizontal.Unit

            sweep = getSilentSweepDistance(horizontal.Magnitude)
        end
        local sweepStart: Vector3 =
            direction and -direction * sweep or Vector3.zero
        local sweepEnd: Vector3 =
            direction and direction * sweep or Vector3.zero

        local approach: Vector3? = nil
        local approachOffset: number = SILENT_ORIGIN_STUDS
        if muzzleOrigin then
            local toTarget: Vector3 = predicted - muzzleOrigin.Position
            local flat: Vector3 = Vector3.new(toTarget.X, 0, toTarget.Z)
            if flat.Magnitude > 0.05 then
                approach = flat.Unit
                approachOffset = math.min(
                    SILENT_ORIGIN_STUDS,
                    math.max(1.0, flat.Magnitude * 0.6)
                )
            end
        end

        local startPoint: Vector3
        local endPoint: Vector3
        local resolvedVariant: string = variant
        if variant == "Through" and approach then
            resolvedVariant = "Through"
            local captured: Vector3 = info.capturedPosition or predicted
            startPoint = captured - approach * 1.0 + sweepStart
            endPoint = predicted + approach * SILENT_PIERCE_STUDS + sweepEnd
        elseif variant == "Top" then
            resolvedVariant = "Top"
            startPoint = predicted + Vector3.new(0, liftStuds, 0)
                + sweepStart
            endPoint = predicted + sweepEnd
        elseif variant == "Behind" and approach then
            resolvedVariant = "Behind"
            startPoint = predicted + approach * approachOffset + sweepStart
            endPoint = predicted + sweepEnd
        elseif approach then
            resolvedVariant = "Front"
            startPoint = predicted - approach * approachOffset + sweepStart
            endPoint = predicted + sweepEnd
        elseif direction then
            resolvedVariant = "Motion"
            startPoint = predicted + sweepStart
            endPoint = predicted + sweepEnd
        else
            resolvedVariant = "Top"
            startPoint = predicted + Vector3.new(0, liftStuds, 0)
            endPoint = predicted
        end

        if (endPoint - startPoint).Magnitude <= 0.05 then
            startPoint = predicted + Vector3.new(0, liftStuds, 0)
            endPoint = predicted
            resolvedVariant = "Top"
            sweep = 0
        end
        -- Through has length even when the configurable extra sweep is zero.
        -- Record the geometry actually authored, not just the requested
        -- variant: a bystander fallback removes the sweep and can change a
        -- Through/Behind request into the Front or lifted construction.
        if bystanderBlocks(target, startPoint, endPoint) then
            sweep = 0
            if variant ~= "Top" and approach then
                startPoint = predicted - approach * approachOffset
                resolvedVariant = "Front"
            else
                startPoint = predicted + Vector3.new(0, liftStuds, 0)
                resolvedVariant = "Top"
            end
            endPoint = predicted
            if bystanderBlocks(target, startPoint, endPoint) then
                return nil, nil, 0, 0, resolvedVariant
            end
        end

        return CFrame.lookAt(startPoint, endPoint), CFrame.new(endPoint),
            approachOffset, sweep, resolvedVariant
    end

    type FireOptions = {
        silent: boolean?,
        quiet: boolean?,
        whenReady: boolean?,
        continuous: boolean?,
        wallCheck: boolean?,
    }

    -- How long an authored request owns the gun. The feedback queue resolves
    -- or expires a shot at 1.6-1.8 s; keeping the window inside that bound
    -- means the gate never outlives the pending state it reads.
    local SHOT_CONFIRM_WINDOW: number = 1.5

    local ShootFeature: any = nil
    local lastRejectReason: string = ""

    local function fireGunAtTarget(
        target: Player?,
        options: FireOptions?
    ): boolean
        local opts: FireOptions = options or {}
        local silent: boolean = mm2Settings.silentAim
        if opts.silent ~= nil then
            silent = opts.silent
        end
        local quiet: boolean = opts.quiet == true
        local continuous: boolean = opts.continuous == true
        local useRaw: boolean = mm2Settings.shootRaw
            or (continuous and silent)
        local useWallCheck: boolean = if opts.wallCheck ~= nil
            then opts.wallCheck == true
            else mm2Settings.shootWallCheck
        local function reject(message: string): boolean
            lastRejectReason = message
            if not quiet and ShootFeature then ShootFeature:SetStatus(message) end
            return false
        end

        local character, humanoid = getCharacterParts()
        if not target or not target.Character or target == LocalPlayer
            or not isPlayerAlive(target) or isProtectedTarget(target) or getPlayerRole(target) ~= "Murderer" then
            return reject("No selected shoot target was found.")
        end
        if not character or not humanoid then
            return reject("Your character is not available.")
        end
        local targetCharacter = target.Character
        local gun: Tool? = getPlayerWeapon(LocalPlayer, "Gun", true)
        if not gun or gun.Parent ~= character then
            return reject("Equip the sheriff gun yourself to shoot.")
        end
        if gun.Enabled == false or gun:GetAttribute("Disabled") == true
            or gun:GetAttribute("Reloading") == true or gun:GetAttribute("IsReloading") == true then
            return reject("The gun is disabled or reloading.")
        end

        local remote: Instance? = gun and gun:FindFirstChild("Shoot")
        local origin: CFrame? = getGunOriginCFrame(character, gun)

        local info: any = nil
        local reason: string? = nil
        if origin then
            local ok: boolean, endpoint: any, aimInfo: any, aimReason: any =
                pcall(prediction.gunAim, target, origin.Position)
            if not ok then return reject("Aim or visibility check failed.") end
            if endpoint == nil then
                reason = aimReason or "no samples"
            else
                info = aimInfo
            end
        end

        -- Raw mode or continuous Auto Shoot / Auto Win: when gunAim has no
        -- samples yet on the first frame, fall back immediately to the
        -- target's current root position (+ short velocity lead) so the shot
        -- fires without waiting even a single second.
        if (useRaw or continuous) and not info and target.Character then
            local targetRoot: BasePart? = target.Character:FindFirstChild("HumanoidRootPart")
            if targetRoot then
                local vel: Vector3 = Vector3.zero
                pcall(function(): ()
                    vel = targetRoot.AssemblyLinearVelocity
                end)
                local fallbackEndpoint: Vector3 = targetRoot.Position + vel * 0.08
                info = {
                    endpoint = fallbackEndpoint,
                    velocity = vel,
                    leadSeconds = 0.08,
                    motionSource = "raw",
                    model = "raw",
                    sampleAge = 0,
                    samples = 0,
                    capturedPosition = targetRoot.Position,
                    rtt = 0,
                    echoDelay = 0,
                    rttEngine = "raw",
                    echoSamples = 0,
                    turnRate = 0,
                    brakeSeconds = 0,
                    leadCorrection = 0,
                    rootPosition = targetRoot.Position,
                }
            end
        end

        local rejectMessages: {[string]: string} = {
            ["no body"] = "The murderer has no usable body to aim at.",
            ["no samples"] = "The murderer has no fresh motion samples yet.",
            ["stale sample"] = "The murderer's position is stale; waiting for a fresh sample.",
            ["unreachable"] = "The murderer is moving too fast to intercept.",
        }
        if not remote
            or not remote:IsA("RemoteEvent")
            or not origin
            or not info then
            local message: string = rejectMessages[reason or ""]
                or (
                    not origin
                        and "The gun has no usable origin."
                        or "The murderer is unavailable or obstructed."
                )
            return reject(message)
        end
        -- A capped horizon means the transport is longer than the model
        -- will lead: firing anyway sends a shot known to fall short by
        -- seconds of target travel. Manual lead is the user's explicit
        -- choice and is not second-guessed here.
        -- Raw mode skips this gate entirely: the user asked to fire
        -- regardless of target movement.
        if not useRaw
            and not continuous
            and prediction.settings and prediction.settings.autoLead
            and type(info.leadSeconds) == "number"
            and info.leadSeconds >= MAX_AUTO_LEAD_SAFE then
            return reject(
                "Prediction horizon is capped; refusing to fire short."
            )
        end

        -- One authored request at a time (v106). Continuous Auto Shoot /
        -- Auto Win bypasses the 1.5s confirmation gate so it never stops
        -- firing while the Murderer is still alive.
        local pendingShot: any = state.mm2ShotFeedback.pending
        if not continuous
            and type(pendingShot) == "table"
            and type(pendingShot.queuedAt) == "number"
            and os.clock() - pendingShot.queuedAt < SHOT_CONFIRM_WINDOW then
            local remaining: number = SHOT_CONFIRM_WINDOW
                - (os.clock() - pendingShot.queuedAt)
            return reject(string.format(
                "Shot gate: waiting for the previous shot (%.1f s left).",
                remaining))
        end

        local function safeToSend(
            shotOrigin: CFrame,
            shotEnd: CFrame,
            muzzle: CFrame?
        ): boolean
            if gun.Parent ~= character or gun.Enabled == false or gun:GetAttribute("Disabled") == true
                or gun:GetAttribute("Reloading") == true or gun:GetAttribute("IsReloading") == true then
                return reject("The gun is disabled or reloading.")
            end
            -- Raw mode or continuous CFrame: skip the WeaponService wall
            -- filter entirely so CFrame Silent AIM fires immediately.
            if useRaw then
                return true
            end
            -- The muzzle is the character's gun, never the authored origin.
            -- validateGunShot checks BOTH rays: the gun's line of sight and
            -- the authored segment. Passing the silent origin twice made them
            -- one ray, so a shot the gun could not see was cleared by a
            -- near-target origin (the v105 silent map hits), and a body
            -- between the gun and the target was never looked for.
            local muzzlePosition: Vector3 = (muzzle or shotOrigin).Position
            local ok, allowed, why, blocker, occluder = pcall(validateGunShot,target,character,targetCharacter,
                muzzlePosition,shotOrigin.Position,shotEnd.Position,useWallCheck)
            if not ok or not allowed then
                if type(blocker) == "table" and trajectoryCalibration
                    and type(trajectoryCalibration.noteBlockedShot) == "function" then
                    pcall(trajectoryCalibration.noteBlockedShot, trajectoryCalibration, blocker)
                end
                return reject(why or "Shot safety check failed.")
            end
            -- Cleared, but keep what the untouched ray met: a transparent solid
            -- short of the aim is exactly the case the client cannot see.
            if type(occluder) == "table" then
                lastGunOccluder = occluder
            else
                lastGunOccluder = nil
            end
            return true
        end

        -- Do not infer a reload from our last REQUEST: a rejected packet
        -- never proves the server fired. Native Tool/attribute readiness is
        -- checked above; no speculative 3.1-second local lockout.
        if silent then

            local variant: string = mm2Settings.silentSpawn
            local shotOrigin: CFrame?, shotEnd: CFrame?, offset: number,
                sweep: number, resolvedVariant: string =
                buildSilentShot(target, info, origin, variant)
            if not shotOrigin or not shotEnd then
                if continuous and target.Character then
                    local tr: BasePart? = target.Character:FindFirstChild("HumanoidRootPart")
                    if tr then
                        local ep: Vector3 = info.endpoint or tr.Position
                        local startPt: Vector3 = ep + Vector3.new(0, 1.5, -2.5)
                        shotOrigin = CFrame.lookAt(startPt, ep)
                        shotEnd = CFrame.new(ep)
                        offset = 2.5
                        sweep = 0
                        resolvedVariant = "Front"
                    end
                end
                if not shotOrigin or not shotEnd then
                    return reject("Another player blocks the silent shot.")
                end
            end
            variant = resolvedVariant
            -- A near-target origin inside a body can make the engine miss that
            -- containing body. Fall back to the real muzzle, never a bypass.
            -- Raw mode skips this check: the shot fires regardless.
            if not useRaw
                and not isWeaponPathClear(shotOrigin.Position,shotEnd.Position,targetCharacter,nil,{ignoreTarget=true}) then
                shotOrigin,shotEnd = origin,CFrame.new(info.endpoint)
                variant = "Muzzle"
                offset = 0
                sweep = 0
            end
            if not safeToSend(shotOrigin,shotEnd,origin) then return false end
            if not continuous then
                state.mm2ShotFeedback.queue(target, gun, shotOrigin, shotEnd)
            end

            state.lastSilentShotInfo = {
                variant = variant,
                at = os.clock(),
                offset = math.floor(offset * 10) / 10,
            }
            remote:FireServer(shotOrigin, shotEnd)

            pcall(trajectoryCalibration.noteAuthoredShot, trajectoryCalibration, {
                kind = "gun",
                tool = gun,
                toolName = gun and gun.Name or "Gun",
                originPos = shotOrigin.Position,
                aimPos = shotEnd.Position,
                target = target,
                silent = true,
                variant = variant,
                offset = offset,
                settings = {mode = "Silent", spawn = variant,
                    sweep = sweep, wallCheck = useWallCheck,
                    leadSeconds = info.leadSeconds, motionSource = info.motionSource,
                    model = info.model,
                    sampleAge = info.sampleAge, samples = info.samples,
                    referencePoint = info.capturedPosition and {info.capturedPosition.X, info.capturedPosition.Y, info.capturedPosition.Z},
                    predictedPoint = {info.endpoint.X, info.endpoint.Y, info.endpoint.Z},
                    sampledVelocity = {info.velocity.X, info.velocity.Y, info.velocity.Z},
                    rtt = info.rtt, echoDelay = info.echoDelay,
                    rttEngine = info.rttEngine, rttData = info.rttData,
                    occluder = lastGunOccluder,
                    echoSamples = info.echoSamples,
                    turnRate = info.turnRate, brakeSeconds = info.brakeSeconds,
                    leadCorrection = info.leadCorrection},
            })
            if not quiet and ShootFeature then ShootFeature:SetStatus(nil) end
            if not continuous then
                macroUnequip(gun)
            end
            return true
        end

        local shotEndCFrame: CFrame = CFrame.new(info.endpoint)
        if not safeToSend(origin, shotEndCFrame) then return false end
        if not continuous then
            state.mm2ShotFeedback.queue(target, gun, origin, shotEndCFrame)
        end
        -- Author one endpoint, without speculative "piercing" past it.
        -- Echo timing documents transport/visual confirmation, NOT rewind
        -- duration or an authoritative hit-rate denominator.
        remote:FireServer(
            CFrame.lookAt(origin.Position, info.endpoint),
            shotEndCFrame
        )
        pcall(trajectoryCalibration.noteAuthoredShot, trajectoryCalibration, {
            kind = "gun",
            tool = gun,
            toolName = gun and gun.Name or "Gun",
            originPos = origin.Position,
            aimPos = info.endpoint,
            target = target,
            silent = false,
            settings = {mode = "Normal", wallCheck = useWallCheck,
                leadSeconds = info.leadSeconds, motionSource = info.motionSource,
                model = info.model,
                sampleAge = info.sampleAge, samples = info.samples,
                referencePoint = info.capturedPosition and {info.capturedPosition.X, info.capturedPosition.Y, info.capturedPosition.Z},
                predictedPoint = {info.endpoint.X, info.endpoint.Y, info.endpoint.Z},
                sampledVelocity = {info.velocity.X, info.velocity.Y, info.velocity.Z},
                rtt = info.rtt, echoDelay = info.echoDelay,
                rttEngine = info.rttEngine, rttData = info.rttData,
                occluder = lastGunOccluder,
                echoSamples = info.echoSamples,
                turnRate = info.turnRate, brakeSeconds = info.brakeSeconds,
                leadCorrection = info.leadCorrection},
        })
        if not quiet and ShootFeature then ShootFeature:SetStatus(nil) end
        if not continuous then
            macroUnequip(gun)
        end
        return true
    end

    local shootOptionsReady: boolean = false
    local shootFeatureActive: boolean = false
    local autoShootActive: boolean = false
    local autoShootWanted: boolean = false
    local updateAutoShootConnection: (() -> ())? = nil

    local function refreshShootInfrastructure(): ()
        local wantActive: boolean = shootFeatureActive or autoShootActive
        state.mm2ShotFeedback.shootActive = wantActive
        if wantActive then
            local weaponService: any = getWeaponServiceModule()
            if type(weaponService) == "table" then
                connectGunFiredSignal(weaponService)
            end
            return
        end
        disconnectGunFiredObserver()
        state.mm2ShotFeedback.pending = nil
        state.mm2ShotFeedback.lastAccepted = nil
        state.mm2ShotFeedback.hide()
    end

    local manualShotPending: boolean = false
    local function triggerManualShot(): ()
        if not shootFeatureActive then
            notify("Enable SilentAIM first.")
            return
        end
        if manualShotPending then return end
        local character, humanoid = getCharacterParts()
        local gun: Tool? = getPlayerWeapon(LocalPlayer, "Gun")
        if not character or not humanoid or not gun then
            notify("No sheriff gun is available.")
            return
        end
        manualShotPending = true
        local ok: boolean, message: any = pcall(function(): ()
            if gun.Parent ~= character then
                humanoid:EquipTool(gun)
                -- Let the grip/muzzle update before sampling its origin.
                RunService.Heartbeat:Wait()
            end
            -- Never re-equip if the user switched away during that frame.
            if shootFeatureActive and LocalPlayer.Character == character and gun.Parent == character then
                fireGunAtTarget(getSelectedShootTarget(), {whenReady = true})
            end
        end)
        manualShotPending = false
        if not ok then notify("Shoot failed: " .. tostring(message)) end
    end

    local function toggleShootMurderer(enabled: boolean): ()
        shootFeatureActive = enabled
        state.mm2SilentAimEnabled = enabled
        if state.mm2KnifeThrowRefresh then state.mm2KnifeThrowRefresh() end
        autoShootActive = shootFeatureActive and autoShootWanted
        refreshShootInfrastructure()
        if updateAutoShootConnection then updateAutoShootConnection() end
    end

    local lastAutoStatus: string? = nil
    local function autoStatus(message: string): ()
        if ShootFeature and lastAutoStatus ~= message then
            lastAutoStatus = message
            ShootFeature:SetStatus(message)
        end
    end

    local function autoShootTick(): ()
        if not shootFeatureActive or not autoShootActive then return end
        local gun: Tool? = getPlayerWeapon(LocalPlayer, "Gun", true)
        if not gun or gun.Parent ~= LocalPlayer.Character then
            autoStatus("Equip gun")
            return
        end
        -- One pending slot: a second authored shot overwrites the first
        -- shot's record, its GunFired echo can no longer be matched and
        -- the calibration gains an unmatched signal. fireGunAtTarget applies
        -- the same gate to manual and automatic requests.
        if state and state.mm2ShotFeedback
            and state.mm2ShotFeedback.pending then
            autoStatus("Esperando confirmación")
            return
        end
        local target: Player? = getSelectedShootTarget()
        if not target then autoStatus("No target"); return end
        lastRejectReason = ""
        local sent: boolean = fireGunAtTarget(target, {whenReady = true, quiet = true})
        autoStatus(sent and "Auto: request sent" or lastRejectReason)
    end

    updateAutoShootConnection = function(): ()
        disconnectFeatureConnection("MM2AutoShoot")
        autoShootActive = shootOptionsReady and shootFeatureActive and autoShootWanted
        if not autoShootActive then
            lastAutoStatus = nil
            if ShootFeature then ShootFeature:SetStatus(nil) end
            return
        end
        -- One attempt per current frame, with no range/confidence/fire-delay
        -- timer. No cached aim or visibility survives into the next attempt.
        featureConnections.MM2AutoShoot = TaskManager:Connect(autoShootTick)
        autoShootTick()
    end

    local function toggleAutoShoot(enabled: boolean): ()
        autoShootWanted = enabled
        autoShootActive = shootFeatureActive and autoShootWanted
        refreshShootInfrastructure()
        if updateAutoShootConnection then updateAutoShootConnection() end
    end

    -- Preserve explicit bindings and enabled state when the old card becomes
    -- a child option. Never overwrite a setting already saved for the child.
    if type(configData) == "table" then
        local changed: boolean = false
        if configData.states["MM2.Shoot.AutoShoot"] == nil and configData.states["MM2.AutoShoot"] ~= nil then
            local enabled: boolean = configData.states["MM2.AutoShoot"] == true
            configData.states["MM2.Shoot.AutoShoot"] = enabled
            if enabled then configData.states["MM2.Shoot"] = true end
            changed = true
        end
        local oldKey: any = configData.values["Shortcut.MM2AutoShoot"]
        if configData.values["Shortcut.MM2ShootAutoShoot"] == nil and type(oldKey) == "string" then
            configData.values["Shortcut.MM2ShootAutoShoot"] = oldKey
            changed = true
        end
        if changed and type(queueConfigSave) == "function" then queueConfigSave() end
    end

    if type(configData) == "table" and configData.values["MM2.Shoot.Aimmethod"] == nil then
        configData.values["MM2.Shoot.Aimmethod"] = configData.values["MM2.Shoot.Mode"]
    end
    ShootFeature = createUniversalFeature(
        "Gun Aimbot",
        "Gun aimbot with Bullet and CFrame modes. The main assigned key fires/equips Gun. Every shot uses the kinematic predictor with the game-filter WallCheck.",
        4,
        toggleShootMurderer,
        {
            categoryName = "Combat",
            configKey = "MM2.Shoot", -- preserve existing Gun settings and activation key
            parent = MM2Scroll,
            registry = mm2Features,
        }
    )
    state.mm2SilentAimFeature = ShootFeature
    -- Other modules (Auto Shoot, Auto Farm's full-bag grab, Auto Win) fire
    -- through the exact Gun Aimbot path instead of hand-rolling their own shot.
    state.mm2FireSilentShot = function(target: Player?): boolean
        return fireGunAtTarget(target, {
            silent = true,
            quiet = true,
            continuous = true,
        })
    end
    state.mm2FireGunShot = function(target: Player?, shotOpts: any): boolean
        local opts: any = type(shotOpts) == "table" and shotOpts or {}
        return fireGunAtTarget(target, {
            silent = opts.silent == true,
            wallCheck = opts.wallCheck,
            quiet = opts.quiet ~= false,
            continuous = opts.continuous ~= false,
        })
    end
    -- One card, two weapons: the heading keeps the gun rows together and the
    -- knife module opens its own section further down.
    if addSectionOption then addSectionOption(ShootFeature, "Gun") end
    local ShootTargetBox
    local function refreshShootOptions(): ()
        if ShootTargetBox then
            setOptionVisible(
                ShootFeature,
                ShootTargetBox.Parent :: GuiObject,
                mm2Settings.shootMode == "Custom"
            )
        end
    end
    addCycleOption(
        ShootFeature,
        "Aim method",
        {"Bullet", "CFrame"},
        mm2Settings.silentAim and 2 or 1,
        function(value: string): ()
            mm2Settings.silentAim = value == "CFrame" or value == "Silent AIM"
            refreshShootOptions()
        end,
        "Bullet fires from the gun; CFrame uses a near-target silent origin. "
            .. "Both respect WallCheck and always protect other players."
    )
    addCycleOption(
        ShootFeature,
        "Target",
        {"Murder", "Custom"},
        mm2Settings.shootMode == "Custom" and 2 or 1,
        function(value: string): ()
            mm2Settings.shootMode = value
            refreshShootOptions()
        end
    )

    if state.bindFeatureActivationKey then
        state.bindFeatureActivationKey(
            ShootFeature,
            mm2Settings.shootKey,
            triggerManualShot
        )
    end
    addToggleOption(
        ShootFeature,
        "Raw",
        mm2Settings.shootRaw,
        function(value: boolean): ()
            mm2Settings.shootRaw = value
        end,
        "Fires the shot regardless of walls, bystanders, target movement, or "
            .. "prediction confidence. When ON, the WallCheck and all shot-safety "
            .. "gates are skipped. The gun must still be equipped and ready, and "
            .. "the target must still be the Murderer. Use with caution."
    )
    addToggleOption(
        ShootFeature,
        "Macro",
        shootMacro,
        function(value: boolean): ()
            shootMacro = value
        end,
        "Pistol macro: hides the gun 0.01 seconds after every shot."
    )
    ShootTargetBox = addTextOption(ShootFeature, "Target player", "", function(
        value: string
    ): ()
        mm2Settings.shootTarget = value
    end, false)
    refreshShootOptions()

    -- The visible Auto control is at the top, but arming waits until saved
    -- aim method/target options below have all been restored.
    shootOptionsReady = true
    if updateAutoShootConnection then updateAutoShootConnection() end

    activeCleanup = function(): ()
        toggleShootMurderer(false)
        state.mm2SilentAimFeature = nil
        state.mm2FireSilentShot = nil
        state.mm2FireGunShot = nil
        toggleAutoShoot(false)
        state.mm2ShotFeedback.hide()
    end
    Module.Events = featureConnections
    Module.Initialized = true
    return Module
end

function Module.destroy(): ()
    if not Module.Initialized then
        return
    end
    Module.Initialized = false
    pcall(activeCleanup)
    activeCleanup = function(): () end
    Module.Events = {}
    Module.Runtime = nil
end

return Module

]],
        ["src/games/MM2/Combat/AutoShoot.lua"] = [[
local Module = {
    Name = "MM2 Auto Shoot",
    Events = {} :: {[string]: any},
    Initialized = false,
    Runtime = nil :: any,
}

local activeCleanup: () -> () = function(): () end

function Module.init(runtime: any): any
    if Module.Initialized then
        return Module
    end
    local core: any = state.mm2Core
    assert(type(core) == "table", "MM2 Auto Shoot requires the MM2 core module")
    local prediction: any = state.mm2Prediction
    assert(type(prediction) == "table", "MM2 Auto Shoot requires MM2 Prediction")
    Module.Runtime = runtime

    local findMurderer: any = core.findMurderer
    local getPlayerRole: any = core.getPlayerRole
    local getPlayerWeapon: any = core.getPlayerWeapon
    local isPlayerAlive: any = core.isPlayerAlive
    local isProtectedTarget: any = core.isProtectedTarget
    local isWeaponPathClear: any = core.isWeaponPathClear
    local getGunOriginCFrame: any = core.getGunOriginCFrame

    local settings = {
        mode = "Bullet",
        wallCheck = true,
        proximity = false,
        aura = 25,
    }

    local autoShootActive: boolean = false
    local AutoShootFeature: any = nil
    local toolConnections: {RBXScriptConnection} = {}

    local function clearToolConnections(): ()
        for _, conn: RBXScriptConnection in ipairs(toolConnections) do
            pcall(function(): ()
                conn:Disconnect()
            end)
        end
        table.clear(toolConnections)
    end

    local function findLocalGun(): (Tool?, Model?, Humanoid?, BasePart?)
        local character: Model? = LocalPlayer and LocalPlayer.Character
        if not character then
            return nil, nil, nil, nil
        end
        local humanoid: Humanoid? = character:FindFirstChildOfClass("Humanoid")
        local root: BasePart? = character:FindFirstChild("HumanoidRootPart") :: BasePart?
        if not humanoid or humanoid.Health <= 0 or not root then
            return nil, character, humanoid, root
        end
        local gun: Tool? = nil
        if type(getPlayerWeapon) == "function" then
            gun = getPlayerWeapon(LocalPlayer, "Gun", false)
        end
        if not gun then
            local charGun: Instance? = character:FindFirstChild("Gun")
            if charGun and charGun:IsA("Tool") then
                gun = charGun
            end
        end
        if not gun then
            local backpack: Instance? = LocalPlayer:FindFirstChildOfClass("Backpack")
            local bpGun: Instance? = backpack and backpack:FindFirstChild("Gun")
            if bpGun and bpGun:IsA("Tool") then
                gun = bpGun
            end
        end
        return gun, character, humanoid, root
    end

    local function ensureGunEquipped(
        character: Model,
        humanoid: Humanoid,
        gun: Tool
    ): boolean
        if gun.Parent == character then
            return true
        end
        pcall(function(): ()
            humanoid:EquipTool(gun)
        end)
        if gun.Parent ~= character then
            pcall(function(): ()
                gun.Parent = character
            end)
        end
        return gun.Parent == character
    end

    local function resolveMurdererTarget(
        localRoot: BasePart,
        enforceProximity: boolean
    ): (Player?, BasePart?)
        local murderer: Player? = nil
        if type(findMurderer) == "function" then
            murderer = findMurderer()
        end
        if not murderer then
            local playersService: Players = game:GetService("Players")
            for _, player: Player in ipairs(playersService:GetPlayers()) do
                if player ~= LocalPlayer then
                    local role: any = type(getPlayerRole) == "function"
                        and getPlayerRole(player)
                        or nil
                    local hasKnife: boolean = type(getPlayerWeapon) == "function"
                        and getPlayerWeapon(player, "Knife", false) ~= nil
                    if role == "Murderer" or hasKnife then
                        murderer = player
                        break
                    end
                end
            end
        end
        if not murderer or murderer == LocalPlayer then
            return nil, nil
        end
        if type(isPlayerAlive) == "function" and not isPlayerAlive(murderer) then
            return nil, nil
        end
        if type(isProtectedTarget) == "function" and isProtectedTarget(murderer) then
            return nil, nil
        end
        local targetChar: Model? = murderer.Character
        local targetRoot: BasePart? = targetChar
            and targetChar:FindFirstChild("HumanoidRootPart") :: BasePart?
        if not targetRoot then
            return nil, nil
        end
        if enforceProximity then
            local okDist: boolean, distance: any = pcall(function(): any
                return (targetRoot.Position - localRoot.Position).Magnitude
            end)
            if okDist and type(distance) == "number" and distance > settings.aura then
                return nil, nil
            end
        end
        return murderer, targetRoot
    end

    local function computeTargetEndpoint(
        target: Player,
        targetRoot: BasePart,
        originPos: Vector3
    ): Vector3
        if type(prediction) == "table" and type(prediction.gunAim) == "function" then
            local ok: boolean, endpoint: any = pcall(
                prediction.gunAim,
                target,
                originPos
            )
            if ok and typeof(endpoint) == "Vector3" then
                return endpoint
            end
        end
        local vel: Vector3 = Vector3.zero
        pcall(function(): ()
            vel = targetRoot.AssemblyLinearVelocity
        end)
        return targetRoot.Position + vel * 0.08
    end

    local function fireCFrameShotImmediate(
        target: Player,
        targetRoot: BasePart,
        character: Model,
        localRoot: BasePart,
        gun: Tool
    ): boolean
        local shootRemote: Instance? = gun:FindFirstChild("Shoot")
        if not (shootRemote and shootRemote:IsA("RemoteEvent")) then
            return false
        end
        if gun.Enabled == false
            or gun:GetAttribute("Disabled") == true
            or gun:GetAttribute("Reloading") == true
            or gun:GetAttribute("IsReloading") == true then
            return false
        end
        local originCF: CFrame = (type(getGunOriginCFrame) == "function"
            and getGunOriginCFrame(character, gun))
            or localRoot.CFrame
        local endpoint: Vector3 = computeTargetEndpoint(
            target,
            targetRoot,
            originCF.Position
        )
        local lookDir: Vector3 = Vector3.new(0, 0, -1)
        pcall(function(): ()
            lookDir = targetRoot.CFrame.LookVector
        end)
        local startPoint: Vector3 = endpoint - lookDir * 2.5 + Vector3.new(0, 1.2, 0)
        if (startPoint - endpoint).Magnitude < 0.2 then
            startPoint = endpoint + Vector3.new(0, 2.0, -2.5)
        end
        local shotOrigin: CFrame = CFrame.lookAt(startPoint, endpoint)
        local shotEnd: CFrame = CFrame.new(endpoint)
        local firedSilent: boolean = false
        if type(state.mm2FireSilentShot) == "function" then
            local okSilent: boolean, res: any = pcall(state.mm2FireSilentShot, target)
            firedSilent = okSilent and res == true
        end
        if not firedSilent then
            pcall(function(): ()
                (shootRemote :: RemoteEvent):FireServer(shotOrigin, shotEnd)
            end)
        end
        return true
    end

    local function fireBulletShotImmediate(
        target: Player,
        targetRoot: BasePart,
        character: Model,
        localRoot: BasePart,
        gun: Tool
    ): boolean
        local shootRemote: Instance? = gun:FindFirstChild("Shoot")
        if not (shootRemote and shootRemote:IsA("RemoteEvent")) then
            return false
        end
        if gun.Enabled == false
            or gun:GetAttribute("Disabled") == true
            or gun:GetAttribute("Reloading") == true
            or gun:GetAttribute("IsReloading") == true then
            return false
        end
        local originCF: CFrame = (type(getGunOriginCFrame) == "function"
            and getGunOriginCFrame(character, gun))
            or localRoot.CFrame
        local endpoint: Vector3 = computeTargetEndpoint(
            target,
            targetRoot,
            originCF.Position
        )
        if settings.wallCheck and type(isWeaponPathClear) == "function" then
            local okClear: boolean, clear: any = pcall(
                isWeaponPathClear,
                originCF.Position,
                endpoint,
                target.Character
            )
            if not okClear or clear ~= true then
                return false
            end
        end
        local firedCore: boolean = false
        if type(state.mm2FireGunShot) == "function" then
            local okShot: boolean, res: any = pcall(state.mm2FireGunShot, target, {
                silent = false,
                wallCheck = settings.wallCheck,
                continuous = true,
                quiet = true,
            })
            firedCore = okShot and res == true
        end
        if not firedCore then
            local shotOrigin: CFrame = CFrame.lookAt(originCF.Position, endpoint)
            local shotEnd: CFrame = CFrame.new(endpoint)
            pcall(function(): ()
                (shootRemote :: RemoteEvent):FireServer(shotOrigin, shotEnd)
            end)
        end
        return true
    end

    -- Shared helper for Auto Win ("Insta Kill As Sheriff (Usa AutoShoot CFrame)")
    -- and Auto Shoot CFrame mode: equips the gun the instant the player
    -- receives it (whether as Sheriff, Hero, or Innocent who picked up GunDrop)
    -- and fires Silent AIM CFrame continuously until the Murderer is dead.
    local function executeAutoShootCFrameOnce(enforceProximity: boolean): boolean
        local gun: Tool?, character: Model?, humanoid: Humanoid?,
            localRoot: BasePart? = findLocalGun()
        if not gun or not character or not humanoid or not localRoot then
            return false
        end
        local target: Player?, targetRoot: BasePart? =
            resolveMurdererTarget(localRoot, enforceProximity)
        if not target or not targetRoot then
            return false
        end
        if not ensureGunEquipped(character, humanoid, gun) then
            return false
        end
        return fireCFrameShotImmediate(target, targetRoot, character, localRoot, gun)
    end
    state.mm2AutoShootCFrameOnce = executeAutoShootCFrameOnce

    local function autoShootTick(): ()
        if not autoShootActive then
            return
        end
        local gun: Tool?, character: Model?, humanoid: Humanoid?,
            localRoot: BasePart? = findLocalGun()
        if not gun or not character or not humanoid or not localRoot then
            return
        end
        local target: Player?, targetRoot: BasePart? =
            resolveMurdererTarget(localRoot, settings.proximity == true)
        if not target or not targetRoot then
            return
        end
        if not ensureGunEquipped(character, humanoid, gun) then
            return
        end
        local isCFrame: boolean = settings.mode == "CFrame"
            or settings.mode == "Cframe"
            or settings.mode == "Silent AIM"
        if isCFrame then
            fireCFrameShotImmediate(target, targetRoot, character, localRoot, gun)
        else
            fireBulletShotImmediate(target, targetRoot, character, localRoot, gun)
        end
    end

    local function watchToolContainer(container: Instance?): ()
        if not container or type((container :: any).ChildAdded) ~= "table"
            and typeof((container :: any).ChildAdded) ~= "RBXScriptSignal" then
            return
        end
        pcall(function(): ()
            local conn: RBXScriptConnection = (container :: any).ChildAdded:Connect(
                function(child: Instance): ()
                    if autoShootActive and child and child.Name == "Gun" then
                        autoShootTick()
                    end
                end
            )
            table.insert(toolConnections, conn)
        end)
    end

    local function setupInstantGunWatchers(): ()
        clearToolConnections()
        if not LocalPlayer then
            return
        end
        watchToolContainer(LocalPlayer.Character)
        watchToolContainer(LocalPlayer:FindFirstChildOfClass("Backpack"))
        pcall(function(): ()
            if LocalPlayer.CharacterAdded then
                table.insert(
                    toolConnections,
                    LocalPlayer.CharacterAdded:Connect(function(newChar: Model): ()
                        watchToolContainer(newChar)
                        watchToolContainer(LocalPlayer:FindFirstChildOfClass("Backpack"))
                    end)
                )
            end
            if LocalPlayer.ChildAdded then
                table.insert(
                    toolConnections,
                    LocalPlayer.ChildAdded:Connect(function(child: Instance): ()
                        if child and child:IsA("Backpack") then
                            watchToolContainer(child)
                        end
                    end)
                )
            end
        end)
    end

    local function updateStatus(): ()
        if not AutoShootFeature or not AutoShootFeature.enabled then
            return
        end
        if settings.proximity then
            AutoShootFeature:SetStatus(
                settings.mode .. " · " .. tostring(settings.aura) .. " studs"
            )
        else
            AutoShootFeature:SetStatus(settings.mode)
        end
    end

    local function toggleAutoShoot(enabled: boolean): ()
        autoShootActive = enabled == true
        if enabled then
            updateStatus()
            setupInstantGunWatchers()
            featureConnections.MM2AutoShoot = TaskManager:Connect(autoShootTick)
            autoShootTick()
        else
            clearToolConnections()
            disconnectFeatureConnection("MM2AutoShoot")
            if AutoShootFeature then
                AutoShootFeature:SetStatus(nil)
            end
        end
    end

    AutoShootFeature = createUniversalFeature(
        "Auto Shoot",
        "Automatically equips the Gun the instant you receive it (as Sheriff or Hero) and shoots the Murderer continuously using Bullet (respects WallCheck) or CFrame (Silent AIM). Optional Proximity radius filter.",
        4,
        toggleAutoShoot,
        {
            categoryName = "Combat",
            parent = MM2Scroll,
            registry = mm2Features,
        }
    )
    state.mm2AutoShootFeature = AutoShootFeature

    local auraSlider: GuiObject? = nil
    local function refreshProximityOption(): ()
        if auraSlider and type(setOptionVisible) == "function" then
            setOptionVisible(
                AutoShootFeature,
                auraSlider.Parent :: GuiObject,
                settings.proximity == true
            )
        end
        updateStatus()
    end

    addCycleOption(AutoShootFeature, "Mode", {"Bullet", "CFrame"}, 1,
        function(value: string): ()
            settings.mode = value
            updateStatus()
        end,
        "Bullet: shoots continuously while respecting WallCheck. CFrame: shoots immediately with Silent AIM CFrame upon receiving the gun.")

    addToggleOption(AutoShootFeature, "WallCheck", true,
        function(value: boolean): ()
            settings.wallCheck = value
        end,
        "In Bullet mode, only shoot when there is a clear line of sight to the Murderer.")

    addToggleOption(AutoShootFeature, "Proximity", false,
        function(value: boolean): ()
            settings.proximity = value == true
            refreshProximityOption()
        end,
        "When enabled, only shoot when the Murderer enters the configured radius.")

    auraSlider = addNumberOption(AutoShootFeature, "Aura", 25, 5, 150,
        function(value: number): ()
            settings.aura = value
            if AutoShootFeature.enabled then
                AutoShootFeature:SetStatus(tostring(value) .. " studs")
            end
        end,
        "Maximum distance in studs to automatically shoot at the Murderer while Proximity is ON.", 1)

    refreshProximityOption()

    activeCleanup = function(): ()
        toggleAutoShoot(false)
        state.mm2AutoShootFeature = nil
        state.mm2AutoShootCFrameOnce = nil
    end
    Module.Events = featureConnections
    Module.Initialized = true
    return Module
end

function Module.destroy(): ()
    if not Module.Initialized then
        return
    end
    Module.Initialized = false
    pcall(activeCleanup)
    activeCleanup = function(): () end
    Module.Events = {}
    Module.Runtime = nil
end

return Module

]],
        ["src/games/MM2/Combat/KnifeThrow.lua"] = [[
local Module = {
    Name = "MM2 Knife Throw",
    Events = {} :: {[string]: any},
    Initialized = false,
    Runtime = nil :: any,
}

local activeCleanup: () -> () = function(): () end

function Module.init(runtime: any): any
    if Module.Initialized then
        return Module
    end
    local core: any = state.mm2Core
    assert(type(core) == "table", "MM2 Knife Throw requires the MM2 core module")
    local prediction: any = state.mm2Prediction
    assert(type(prediction) == "table", "MM2 Knife Throw requires MM2 Prediction")
    Module.Runtime = runtime
    
    local findMurderer: any = core.findMurderer
    local getPlayerRole: any = core.getPlayerRole
    local getPlayerWeapon: any = core.getPlayerWeapon
    local isPlayerAlive: any = core.isPlayerAlive
    local isProtectedTarget: any = core.isProtectedTarget
    local isWeaponPathClear: any = core.isWeaponPathClear
    
    local settings = {
        wallCheck = true,
        delay = 0,
    }
    
    local knifeThrowActive = false
    local lastThrowAttempt = 0
    
    local function getKnife(): Tool?
        local character = LocalPlayer.Character
        if not character then return nil end
        return getPlayerWeapon(LocalPlayer, "Knife", true)
    end
    
    local function findTarget(): Player?
        local murderer = findMurderer()
        if murderer ~= LocalPlayer then return nil end
        
        local localRoot = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
        if not localRoot then return nil end
        
        local candidates = {}
        for _, player in ipairs(game:GetService("Players"):GetPlayers()) do
            if player ~= LocalPlayer 
                and isPlayerAlive(player) 
                and not isProtectedTarget(player)
                and getPlayerRole(player) ~= "Murderer" then
                
                local targetRoot = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
                if targetRoot then
                    table.insert(candidates, {
                        player = player,
                        distance = (targetRoot.Position - localRoot.Position).Magnitude
                    })
                end
            end
        end
        
        table.sort(candidates, function(a, b) return a.distance < b.distance end)
        
        for _, candidate in ipairs(candidates) do
            if not settings.wallCheck or isWeaponPathClear(localRoot.Position, candidate.player.Character.HumanoidRootPart.Position, {}) then
                return candidate.player
            end
        end
        
        return nil
    end
    
    local function throwKnife(target: Player): boolean
        local knife = getKnife()
        if not knife then return false end
        
        local character = LocalPlayer.Character
        if not character then return false end
        
        local root = character:FindFirstChild("HumanoidRootPart")
        local targetRoot = target.Character and target.Character:FindFirstChild("HumanoidRootPart")
        if not root or not targetRoot then return false end
        
        -- Get the throw remote
        local remotes = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
        if not remotes then return false end
        
        local event = remotes:FindFirstChild("Event")
        if not event then return false end
        
        -- Calculate aim with prediction
        local originCFrame = getGunOriginCFrame(knife)
        local aimPosition = targetRoot.Position
        
        -- Invoke the remote directly to trigger natural throw animation
        -- The game will handle the animation and throw naturally
        pcall(function()
            event:FireServer("Throw", {
                Origin = originCFrame,
                Direction = (aimPosition - originCFrame.Position).Unit,
                Target = target
            })
        end)
        
        return true
    end
    
    local function knifeThrowTick(): ()
        if not knifeThrowActive then return end
        
        local now = os.clock()
        local delay = settings.delay
        if now - lastThrowAttempt < delay then return end
        
        local target = findTarget()
        if not target then return end
        
        lastThrowAttempt = now
        throwKnife(target)
    end
    
    local function toggleKnifeThrow(enabled: boolean): ()
        knifeThrowActive = enabled
        
        if enabled then
            featureConnections.MM2KnifeThrow = TaskManager:Connect(knifeThrowTick)
            knifeThrowTick()
        else
            disconnectFeatureConnection("MM2KnifeThrow")
        end
    end
    
    local KnifeThrowFeature: any = createUniversalFeature(
        "Knife Throw",
        "Automatically throws knives at targets using the game's natural throw animation. Invokes the Remote directly for authentic behavior with prediction.",
        5,
        toggleKnifeThrow,
        {
            categoryName = "Combat",
            parent = MM2Scroll,
            registry = mm2Features,
        }
    )
    state.mm2KnifeThrowFeature = KnifeThrowFeature
    
    addToggleOption(KnifeThrowFeature, "WallCheck", true,
        function(value: boolean): ()
            settings.wallCheck = value
        end,
        "Only throw if there's a clear path to the target.")
    
    addNumberOption(KnifeThrowFeature, "Delay", 0, 0, 10,
        function(value: number): ()
            settings.delay = value
            if KnifeThrowFeature.enabled then
                KnifeThrowFeature:SetStatus(string.format("%.1fs", value))
            end
        end,
        "Delay in seconds between each throw attempt. 0 = throw as fast as possible.", 0.1)
    
    activeCleanup = function(): ()
        toggleKnifeThrow(false)
    end
    Module.Events = featureConnections
    Module.Initialized = true
    return Module
end

function Module.destroy(): ()
    if not Module.Initialized then
        return
    end
    Module.Initialized = false
    pcall(activeCleanup)
    activeCleanup = function(): () end
    Module.Events = {}
    Module.Runtime = nil
end

return Module

]],
        ["src/games/MM2/Fun/BlurtRoles.lua"] = [[
local Module = {
    Name = "MM2 Blurt Roles",
    Events = {} :: {[string]: any},
    Initialized = false,
    Runtime = nil :: any,
}

local activeCleanup: () -> () = function(): () end

function Module.init(runtime: any): any
    if Module.Initialized then
        return Module
    end
    local core: any = state.mm2Core
    assert(type(core) == "table", "MM2 Blurt Roles requires the MM2 core module")
    Module.Runtime = runtime
    local findMurderer: any = core.findMurderer
    local findSheriff: any = core.findSheriff
    local hasActiveRoundRoles: any = core.hasActiveRoundRoles
    local mm2Settings: any = core.mm2Settings

    local blurtEnabled: boolean = false
    local blurtSignature: string = ""
    local blurtPending: boolean = false
    local lastBlurtAt: number = -math.huge

    local function sendPublicChat(message: string): boolean
        local sent: boolean = false

        local textChatOk: boolean = pcall(function(): ()
            local textChatService: TextChatService =
                game:GetService("TextChatService")
            if textChatService.ChatVersion ~= Enum.ChatVersion.TextChatService then
                return
            end
            local channels: Instance? = textChatService:FindFirstChild("TextChannels")
            local channel: Instance? = channels
                and (channels:FindFirstChild("RBXGeneral")
                    or channels:FindFirstChildWhichIsA("TextChannel"))
            if channel and channel:IsA("TextChannel") then
                (channel :: TextChannel):SendAsync(message)
                sent = true
            end
        end)

        if sent then
            return true
        end

        local legacyOk: boolean = pcall(function(): ()
            local events: Instance? = game:GetService("ReplicatedStorage")
                :FindFirstChild("DefaultChatSystemChatEvents")
            local say: Instance? = events
                and events:FindFirstChild("SayMessageRequest")
            if say and say:IsA("RemoteEvent") then
                (say :: RemoteEvent):FireServer(message, "All")
                sent = true
            end
        end)

        return sent and (textChatOk or legacyOk)
    end

    local function buildBlurtMessage(): (string?, string?)
        if not hasActiveRoundRoles() then
            return nil, nil
        end
        local murderer: Player? = findMurderer()
        local sheriff: Player? = findSheriff()
        if not murderer and not sheriff then
            return nil, nil
        end
        local murdererName: string = murderer and murderer.Name or "?"
        local sheriffName: string = sheriff and sheriff.Name or "?"
        local message: string
        local signature: string
        if mm2Settings.blurtFake then

            message = string.format(
                'Murder; "%s" Sheriff; "%s"',
                sheriffName,
                murdererName
            )
            signature = "fake/" .. sheriffName .. "/" .. murdererName
        else
            message = string.format(
                'Murder; "%s" Sheriff; "%s" | Wurst',
                murdererName,
                sheriffName
            )
            signature = murdererName .. "/" .. sheriffName
        end
        return message, signature
    end

    local function blurtRoles(manual: boolean): ()
        local message: string?, signature: string? = buildBlurtMessage()
        if not message then
            if manual then
                notify("MM2 · no roles to blurt yet.")
            end
            return
        end
        if not manual then
            if signature == blurtSignature and not mm2Settings.blurtRepeat then
                return
            end
            if os.clock() - lastBlurtAt < 2.5 then
                return
            end
        end
        blurtSignature = signature :: string
        lastBlurtAt = os.clock()
        task.spawn(function(): ()
            if sendPublicChat(message :: string) then
                notify("MM2 · blurted: " .. (message :: string))
            else
                notify("MM2 · the chat refused the message (filtered or disabled).")
            end
        end)
    end

    local function scheduleBlurt(): ()
        if not blurtEnabled or blurtPending then
            return
        end
        local message: string?, signature: string? = buildBlurtMessage()
        if not message then
            return
        end
        if signature == blurtSignature and not mm2Settings.blurtRepeat then
            return
        end
        blurtPending = true
        task.delay(math.max(mm2Settings.blurtDelay, 0), function(): ()
            blurtPending = false
            if blurtEnabled then
                blurtRoles(false)
            end
        end)
    end

    local instantSent: boolean = false
    local function notifyInstantRoles(): ()
        if not mm2Settings.instantRoleNotify or instantSent or not hasActiveRoundRoles() then return end
        local murderer: Player? = findMurderer()
        local sheriff: Player? = findSheriff()
        if not murderer or not sheriff then return end
        instantSent = true
        notify("Roles ready - Murderer: " .. murderer.Name .. " | Sheriff/Hero: " .. sheriff.Name)
    end

    local unsubscribe: () -> () = core.onRoundRoles(function(active: boolean): ()
        if not active then
            blurtSignature = ""
            instantSent = false
            return
        end
        notifyInstantRoles()
        scheduleBlurt()
    end)

    local function toggleBlurtRoles(enabled: boolean): ()
        blurtEnabled = enabled
        disconnectFeatureConnection("MM2BlurtRoles")
        if not enabled then
            return
        end
        blurtSignature = ""
        local elapsed: number = 0
        featureConnections.MM2BlurtRoles = TaskManager:Connect(function(deltaTime: number): ()
            elapsed += deltaTime
            if elapsed < 1 then
                return
            end
            elapsed = 0
            if not hasActiveRoundRoles() then
                blurtSignature = ""
                return
            end
            scheduleBlurt()
        end)
    end

    local BlurtFeature = createUniversalFeature(
        "Blurt Roles",
        "Announces the murderer and sheriff in the public chat once per round",
        3,
        toggleBlurtRoles,
        {
            categoryName = "World",
            parent = MM2Scroll,
            registry = mm2Features,
        }
    )
    addToggleOption(BlurtFeature, "Instant Roles", mm2Settings.instantRoleNotify, function(value: boolean): ()
        mm2Settings.instantRoleNotify = value
        if value then notifyInstantRoles() end
    end, "Private notification once per round, independent of public chat announcements.")
    addNumberOption(
        BlurtFeature,
        "Delay",
        mm2Settings.blurtDelay,
        0,
        15,
        function(value: number): ()
            mm2Settings.blurtDelay = value
        end,
        "Seconds to wait after the roles are known before typing.",
        0.5
    )
    addToggleOption(
        BlurtFeature,
        "Repeat on change",
        mm2Settings.blurtRepeat,
        function(value: boolean): ()
            mm2Settings.blurtRepeat = value
        end,
        "Blurt again when the sheriff dies and the gun changes hands."
    )
    addToggleOption(
        BlurtFeature,
        "Fake Blurt Roles",
        mm2Settings.blurtFake,
        function(value: boolean): ()
            mm2Settings.blurtFake = value
        end,
        "Announces the roles SWAPPED (and without the Wurst tag) so the chat "
            .. "lies about who the murderer and sheriff are."
    )
    addActionOption(BlurtFeature, "Blurt now", function(): ()
        blurtRoles(true)
    end)
    addInformationOption(
        BlurtFeature,
        "This types in the real public chat: everyone reads it and you will be"
            .. " reported. Roblox also rate-limits and filters messages."
    )

    activeCleanup = function(): ()
        pcall(unsubscribe)
        mm2Settings.instantRoleNotify = false
        toggleBlurtRoles(false)
    end
    Module.Events = featureConnections
    Module.Initialized = true
    return Module
end

function Module.destroy(): ()
    if not Module.Initialized then
        return
    end
    Module.Initialized = false
    pcall(activeCleanup)
    activeCleanup = function(): () end
    Module.Events = {}
    Module.Runtime = nil
end

return Module

]],
        ["src/games/MM2/Movement/Sprint.lua"] = [[
local Module = {
    Name = "MM2 Sprint",
    Events = {} :: {[string]: any},
    Initialized = false,
    Runtime = nil :: any,
}

local activeCleanup: () -> () = function(): () end

function Module.init(runtime: any): any
    if Module.Initialized then
        return Module
    end
    local core: any = state.mm2Core
    assert(type(core) == "table", "MM2 Sprint requires the MM2 core module")
    Module.Runtime = runtime

    local sprintTrailObjects: {Instance} = {}


    local function clearSprintTrail(): ()
        for _, object: Instance in ipairs(sprintTrailObjects) do
            if object.Parent then
                object:Destroy()
            end
        end
        table.clear(sprintTrailObjects)
    end

    local function ensureSprintTrail(root: BasePart): Trail
        local existing: Instance? = root:FindFirstChild("Wurst_SprintTail")
        if existing and existing:IsA("Trail") then
            return existing
        end

        clearSprintTrail()
        local left: Attachment = Instance.new("Attachment")
        left.Name = "Wurst_SprintLeft"
        left.Position = Vector3.new(-0.8, -0.5, 0.75)
        left.Parent = root

        local right: Attachment = Instance.new("Attachment")
        right.Name = "Wurst_SprintRight"
        right.Position = Vector3.new(0.8, -0.5, 0.75)
        right.Parent = root

        local trail: Trail = Instance.new("Trail")
        trail.Name = "Wurst_SprintTail"
        trail.Attachment0 = left
        trail.Attachment1 = right
        trail.Color = ColorSequence.new(
            Color3.fromRGB(255, 220, 55),
            Color3.fromRGB(175, 115, 20)
        )
        trail.Lifetime = 0.38
        trail.LightEmission = 0.25
        trail.FaceCamera = true
        trail.Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0.2),
            NumberSequenceKeypoint.new(1, 1),
        })
        trail.Enabled = false
        trail.Parent = root
        sprintTrailObjects = {trail, left, right}
        return trail
    end

    local speed: any = state.framework and state.framework:GetModule("Speed")
    assert(speed, "Sprint option requires the Speed module")
    speed.ClearSprint = clearSprintTrail
    speed.SprintFrame = function(active: boolean, root: BasePart): ()
        if not active then clearSprintTrail(); return end
        local _, humanoid: Humanoid? = getCharacterParts()
        ensureSprintTrail(root).Enabled = humanoid ~= nil and humanoid.MoveDirection.Magnitude > 0.05
    end
    local function releaseSprint(): ()
        disconnectFeatureConnection("MM2SprintHold")
        speed.SetSprintHeld(false)
        clearSprintTrail()
    end
    speed:CreateButton({
        Name = "Sprint", Hold = true,
        Function = function(): ()
            speed.SetSprintHeld(true)
            if not featureConnections.MM2SprintHold then
                featureConnections.MM2SprintHold = TaskManager:Connect(speed.StepSprint)
            end
        end,
        OnRelease = releaseSprint,
        Tooltip = "Hold this button, its assigned key or the touch action to sprint. Works with Speed OFF; release restores normal Speed or your original speed. No toggle state is saved.",
    })
    activeCleanup = function(): ()
        releaseSprint()
        speed.ClearSprint = nil
        speed.SprintFrame = nil
    end
    Module.Events = featureConnections
    Module.Initialized = true
    return Module
end

function Module.destroy(): ()
    if not Module.Initialized then
        return
    end
    Module.Initialized = false
    pcall(activeCleanup)
    activeCleanup = function(): () end
    Module.Events = {}
    Module.Runtime = nil
end

return Module

]],
        ["src/games/MM2/Movement/Teleport.lua"] = [[
local Module = {
    Name = "MM2 Teleport",
    Events = {} :: {[string]: any},
    Initialized = false,
    Runtime = nil :: any,
}

local activeCleanup: () -> () = function(): () end

function Module.init(runtime: any): any
    if Module.Initialized then
        return Module
    end
    local core: any = state.mm2Core
    assert(type(core) == "table", "MM2 Teleport requires the MM2 core module")
    Module.Runtime = runtime
    local findDroppedGun: any = core.findDroppedGun
    local findMM2Map: any = core.findMM2Map
    local getPlayerRole: any = core.getPlayerRole
    local isRoundLifecycleActive: any = core.isRoundLifecycleActive
    local mm2Settings: any = core.mm2Settings

    -- Auto Get Gun is an innocent-only, in-round action. As Murderer it
    -- must never run (the knife role has no use for the sheriff gun and
    -- grabbing it exposes the role), and in the lobby there is no dropped
    -- gun worth chasing. Fail closed when the role or round state is not
    -- positively known.
    local function canAutoGetGun(): boolean
        if type(getPlayerRole) ~= "function"
            or getPlayerRole(LocalPlayer) ~= "Innocent" then
            return false
        end
        if type(isRoundLifecycleActive) ~= "function"
            or isRoundLifecycleActive() ~= true then
            return false
        end
        if type(findMM2Map) ~= "function" or not findMM2Map() then
            return false
        end
        return true
    end

    -- Immediate pickup without moving the character: pulse the touch
    -- between our root and the dropped gun's part, with no sleep or
    -- configurable delay. The next Heartbeat can retry while weapon
    -- replication is still catching up.
    local function touchDroppedGun(gunDrop: Instance): boolean
        if type(state.fireTouchInterest) ~= "function" then
            return false
        end
        local character: Model? = LocalPlayer.Character
        local root: Instance? = character
            and character:FindFirstChild("HumanoidRootPart")
        if not root then
            return false
        end
        local touchPart: Instance? = nil
        if gunDrop:IsA("BasePart") then
            touchPart = gunDrop
        elseif gunDrop:IsA("Model") then
            touchPart = gunDrop:FindFirstChild("Handle", true)
                or gunDrop:FindFirstChildWhichIsA("BasePart", true)
        end
        if not touchPart then
            return false
        end
        pcall(state.fireTouchInterest, root, touchPart, 0)
        pcall(state.fireTouchInterest, root, touchPart, 1)
        local backpack: Instance? =
            LocalPlayer:FindFirstChildOfClass("Backpack")
        return (backpack ~= nil and backpack:FindFirstChild("Gun") ~= nil)
            or (character ~= nil and character:FindFirstChild("Gun") ~= nil)
    end

    local autoGetGunBusy = false

    local function toggleAutoGetGun(enabled)
        disconnectFeatureConnection("MM2AutoGetGun")
        autoGetGunBusy = false
        state.mm2AutoGetGunEnabled = enabled == true

        if not enabled then
            return
        end

        -- No polling throttle: TaskManager already runs this on
        -- Heartbeat, so checking every frame is the fastest the
        -- client can react (one frame, never a 0.5 s wait). The tick
        -- also runs once synchronously on enable, so a gun that is
        -- already on the ground is grabbed in the same frame the
        -- toggle turns on instead of waiting for the next Heartbeat.
        local function autoGetGunTick(): ()
            if autoGetGunBusy then
                return
            end

            local character = LocalPlayer.Character
            local backpack = LocalPlayer:FindFirstChildOfClass("Backpack")
            local gunDrop = findDroppedGun()
            if not character or not gunDrop
                or not canAutoGetGun()
                or (backpack and backpack:FindFirstChild("Gun"))
                or character:FindFirstChild("Gun") then
                return
            end

            -- Instant touch first: no PivotTo, no position the server
            -- can call invalid. If the touch does not deliver the gun,
            -- stay put and let the next frame retry instead of falling
            -- back to a teleport the user did not ask for.
            autoGetGunBusy = true
            task.spawn(function()
                pcall(touchDroppedGun, gunDrop)
                autoGetGunBusy = false
            end)
        end
        featureConnections.MM2AutoGetGun =
            TaskManager:Connect(autoGetGunTick)
        autoGetGunTick()
    end

    local function moveCharacterTo(character: any, destination: CFrame): ()
        local root: any = character:FindFirstChild("HumanoidRootPart")
        if root then
            pcall(function(): ()
                root.Anchored = false
                root.AssemblyLinearVelocity = Vector3.zero
                root.AssemblyAngularVelocity = Vector3.zero
            end)
        end
        character:PivotTo(destination)
        if root then
            pcall(function(): ()
                root.CFrame = destination
            end)
        end
    end

    local function teleportToMap()
        local map = findMM2Map()
        local spawns = map and (map:FindFirstChild("Spawns") or map:FindFirstChild("Spawns", true))
        local character = LocalPlayer.Character
        if not map or not character then
            notify("No active MM2 map was found.")
            return
        end

        local target = nil
        if spawns and type(spawns.GetChildren) == "function" then
            local spawnList = spawns:GetChildren()
            target = spawnList[math.random(1, math.max(1, #spawnList))]
            if target and not target:IsA("BasePart") and type(target.FindFirstChildWhichIsA) == "function" then
                target = target:FindFirstChildWhichIsA("BasePart", true)
            end
        end
        if (not target or not target:IsA("BasePart"))
            and spawns
            and type(spawns.FindFirstChildWhichIsA) == "function" then
            target = spawns:FindFirstChildWhichIsA("BasePart", true)
        end
        if (not target or not target:IsA("BasePart"))
            and type(map.FindFirstChildWhichIsA) == "function" then
            target = map:FindFirstChildWhichIsA("BasePart", true)
        end
        if target and target:IsA("BasePart") then
            moveCharacterTo(character, target.CFrame + Vector3.new(0, 3, 0))
        else
            notify("No active MM2 map spawn was found.")
        end
    end

    local function findLobbySpawn()
        local lobby = workspace:FindFirstChild("Lobby")
            or workspace:FindFirstChild("MainLobby")
            or workspace:FindFirstChild("RegularLobby")
        if not lobby and type(workspace.GetChildren) == "function" then
            for _, child in ipairs(workspace:GetChildren()) do
                local lowerName = string.lower(tostring(child.Name))
                if string.find(lowerName, "lobby", 1, true) ~= nil
                    or child:FindFirstChild("VotePads", true) ~= nil
                    or child:FindFirstChild("VotePad1", true) ~= nil
                    or child:FindFirstChild("VoteIcons", true) ~= nil then
                    lobby = child
                    break
                end
            end
        end
        if lobby then
            local spawns = lobby:FindFirstChild("Spawns")
                or lobby:FindFirstChild("Spawns", true)
            if spawns then
                if type(spawns.FindFirstChildWhichIsA) == "function" then
                    local spawn = spawns:FindFirstChildWhichIsA("SpawnLocation")
                        or spawns:FindFirstChildWhichIsA("BasePart")
                        or spawns:FindFirstChildWhichIsA("BasePart", true)
                    if spawn then
                        return spawn
                    end
                end
                if type(spawns.GetChildren) == "function" then
                    for _, item in ipairs(spawns:GetChildren()) do
                        if type(item.IsA) == "function" and item:IsA("BasePart") then
                            return item
                        end
                    end
                end
            end
            if type(lobby.FindFirstChildWhichIsA) == "function" then
                local directSpawn = lobby:FindFirstChildWhichIsA("SpawnLocation", true)
                if directSpawn then
                    return directSpawn
                end
            end
            local votePads = lobby:FindFirstChild("VotePads", true)
                or lobby:FindFirstChild("VotePad1", true)
            if votePads and type(votePads.FindFirstChildWhichIsA) == "function" then
                local padPart = votePads:FindFirstChildWhichIsA("BasePart", true)
                if padPart then
                    return padPart
                end
            end
            if type(lobby.FindFirstChildWhichIsA) == "function" then
                local anyPart = lobby:FindFirstChildWhichIsA("BasePart", true)
                if anyPart then
                    return anyPart
                end
            end
        end
        local worldSpawns = workspace:FindFirstChild("Spawns")
        if worldSpawns and type(worldSpawns.FindFirstChildWhichIsA) == "function" then
            local spawn = worldSpawns:FindFirstChildWhichIsA("SpawnLocation")
                or worldSpawns:FindFirstChildWhichIsA("BasePart")
            if spawn then
                return spawn
            end
        end
        if type(workspace.FindFirstChildWhichIsA) == "function" then
            return workspace:FindFirstChildWhichIsA("SpawnLocation", true)
        end
        return nil
    end

    local function teleportToLobby()
        local spawn = findLobbySpawn()
        local character = LocalPlayer.Character
        if spawn and character then
            moveCharacterTo(character, spawn.CFrame + Vector3.new(0, 3, 0))
        else
            notify("The MM2 lobby spawn was not found.")
        end
    end

    local teleportTargetName = ""

    local function teleportToPlayer()
        local character = LocalPlayer.Character
        if not character then
            notify("Your character is not available.")
            return
        end
        local needle = string.lower(
            string.gsub(teleportTargetName or "", "%s+", "")
        )
        if needle == "" then
            notify("Type a player name in the Player name box first.")
            return
        end
        local exact, partial = nil, nil
        for _, player in ipairs(Players:GetPlayers()) do
            if player ~= LocalPlayer then
                local name = string.lower(player.Name)
                if string.gsub(name, "%s+", "") == needle then
                    exact = player
                    break
                end
                if not partial and string.find(name, needle, 1, true) then
                    partial = player
                end
            end
        end
        local target = exact or partial
        local targetRoot = target
            and target.Character
            and target.Character:FindFirstChild("HumanoidRootPart")
        if targetRoot then
            character:PivotTo(targetRoot.CFrame + Vector3.new(0, 3, 0))
        elseif target then
            notify(target.Name .. " has no character to teleport to.")
        else
            notify("No player named \"" .. teleportTargetName .. "\" was found.")
        end
    end

    local function grabDroppedGun()
        local gunDrop = findDroppedGun()
        if gunDrop and LocalPlayer.Character then
            touchDroppedGun(gunDrop)
        else
            notify("No dropped gun was found.")
        end
    end

    local teleport = state.framework:GetModule("Teleport")
    assert(teleport, "MM2 extends the universal Teleport module")
    for _, id in ipairs({"GetGunkey", "Playername"}) do
        local key = "Universal.ClickTeleport." .. id
        if configData.values[key] == nil then configData.values[key] = configData.values["MM2.Teleport." .. id] end
    end
    local autoKey = "Universal.ClickTeleport.AutoGetGun"
    if configData.states[autoKey] == nil then configData.states[autoKey] = configData.states["MM2.Teleport.AutoGetGun"] end
    local show = {Option = "Destination", Values = {"MM2"}}
    teleport:CreateButton({Name = "Teleport to Map", Show = show, Function = teleportToMap})
    teleport:CreateButton({Name = "Teleport to Lobby", Show = show, Function = teleportToLobby})
    teleport:CreateTextBox({Name = "Player name", Default = "", Show = show,
        Function = function(value) teleportTargetName = value end})
    teleport:CreateButton({Name = "Teleport to Player", Show = show, Function = teleportToPlayer})
    teleport:CreateButton({Name = "Get Gun", Show = show, Function = grabDroppedGun})
    local key = teleport:CreateBind({Name = "Get Gun key", Default = mm2Settings.getGunKey, Show = show,
        Function = function(value) mm2Settings.getGunKey = value end})
    if state.bindMobileActionPlacement and key.Object then
        state.bindMobileActionPlacement(key.Object, "MM2GetGun", "GUN", grabDroppedGun)
    end
    featureConnections.MM2GetGunKey = UserInputService.InputBegan:Connect(
        function(input, gameProcessed)
            if gameProcessed
                or state.keyCaptureCallback
                or state.waitingForKey
                or UserInputService:GetFocusedTextBox() then
                return
            end
            if input.UserInputType == Enum.UserInputType.Keyboard
                and input.KeyCode == mm2Settings.getGunKey then
                task.spawn(grabDroppedGun)
            end
        end
    )
    teleport:CreateToggle({Name = "Auto Get Gun", Default = false, Show = show, Function = toggleAutoGetGun})

    activeCleanup = function(): ()
        toggleAutoGetGun(false)
        disconnectFeatureConnection("MM2GetGunKey")
    end
    Module.Events = featureConnections
    Module.Initialized = true
    return Module
end

function Module.destroy(): ()
    if not Module.Initialized then
        return
    end
    Module.Initialized = false
    pcall(activeCleanup)
    activeCleanup = function(): () end
    Module.Events = {}
    Module.Runtime = nil
end

return Module

]],
        ["src/games/MM2/Other/AutoFarm.lua"] = [[
local Module = {
    Name = "MM2 Auto Farm",
    Events = {},
    Initialized = false,
}

local activeCleanup: () -> () = function(): ()
end

function Module.init(_runtime: any): any
    assert(state.mm2Core, "MM2 Auto Farm requires the MM2 core")
    local core: any = state.mm2Core
    local getPlayerRole: any = core.getPlayerRole
    local getPlayerWeapon: any = core.getPlayerWeapon
    local isPlayerAlive: any = core.isPlayerAlive
    local findMurderer: any = core.findMurderer
    local findSheriff: any = core.findSheriff
    local findDroppedGun: any = core.findDroppedGun
    local isRoundLifecycleActive: any = core.isRoundLifecycleActive
    local findMM2Map: any = core.findMM2Map
    local getEstimatedLatency: any = core.getEstimatedLatency
    local getGunOriginCFrame: any = core.getGunOriginCFrame

    local settings = {
        mode = "Walk",
        speed = 16,
        safeZone = true,
        resetOnFull = true,
        flingMurder = false,
        flingSheriff = false,
        grabGunShoot = false,
        killAllOnFull = false,
    }

    local totalCoinsCollected: number = 0
    local farmElapsedSeconds: number = 0
    local lastFormattedSecond: number = -1
    local coinsCollectedStat: any = nil
    local farmTimeStat: any = nil
    local safeZonePlatform: Part? = nil

    local function formatFarmTime(totalSeconds: number): string
        local whole: number = math.max(0, math.floor(totalSeconds))
        local hours: number = math.floor(whole / 3600)
        local mins: number = math.floor((whole % 3600) / 60)
        local secs: number = whole % 60
        if hours > 0 then
            return string.format("%02d:%02d:%02d", hours, mins, secs)
        end
        return string.format("%02d:%02d", mins, secs)
    end

    local function refreshFarmOverlay(): ()
        if coinsCollectedStat and type(coinsCollectedStat.set) == "function" then
            coinsCollectedStat.set(tostring(totalCoinsCollected))
        end
        local wholeSec: number = math.max(0, math.floor(farmElapsedSeconds))
        if wholeSec ~= lastFormattedSecond then
            lastFormattedSecond = wholeSec
            if farmTimeStat and type(farmTimeStat.set) == "function" then
                farmTimeStat.set(formatFarmTime(wholeSec))
            end
        end
    end

    local function destroySafeZonePlatform(): ()
        if safeZonePlatform then
            pcall(function(): ()
                safeZonePlatform:Destroy()
            end)
            safeZonePlatform = nil
        end
    end

    local function ensureSafeZonePlatform(originPos: Vector3): Vector3
        local voidCenter: Vector3 = Vector3.new(
            originPos.X + 650,
            math.max(originPos.Y + 280, 380),
            originPos.Z + 650
        )
        if not safeZonePlatform or not safeZonePlatform.Parent then
            pcall(function(): ()
                local part: Part = Instance.new("Part")
                part.Name = "Wurst_AutoFarmSafeZone"
                part.Anchored = true
                part.CanCollide = true
                part.CanQuery = false
                part.CanTouch = false
                part.CastShadow = false
                part.Size = Vector3.new(64, 4, 64)
                part.Material = Enum.Material.SmoothPlastic
                part.Color = Color3.fromRGB(35, 42, 55)
                part.Transparency = 0.15
                part.CFrame = CFrame.new(voidCenter)
                part.Parent = workspace
                safeZonePlatform = part
            end)
        end
        if safeZonePlatform and safeZonePlatform.Parent then
            return safeZonePlatform.Position + Vector3.new(0, 5, 0)
        end
        return voidCenter + Vector3.new(0, 5, 0)
    end

    -- Two ways to reach a coin, chosen with Farm Mode:
    --
    -- Walk: the humanoid simply walks on the ground (Humanoid:Move).
    -- No prone tilt, no PlatformStand, no NoClip, no flying -- the
    -- body's normal touch against Coin_Server pays, which is why this
    -- is the reliable default. The slider becomes WalkSpeed.
    --
    -- Below (Hitbox): the character stays UPRIGHT and flies by physics
    -- velocity underneath the floor, but the root's hitbox is grown
    -- while engaged (4 x 8 x 4), so riding with the root centre
    -- BELOW_OFFSET under the coin still overlaps Coin_Server (1.2 x 2 x
    -- 2, one stud either side of its centre). The old build lay the
    -- body face-down to get a part into that volume; the tilted camera
    -- fight is what glitched, and the hitbox makes it unnecessary.
    local BELOW_OFFSET: number = 3.0
    local HITBOX_SIZE: Vector3 = Vector3.new(4, 8, 4)
    -- A coin that does not collect within this long is skipped for a
    -- while instead of trapping the farm on one unreachable pickup.
    local STUCK_SECONDS: number = 1.4
    local BLACKLIST_SECONDS: number = 6

    local function characterParts(): (Model?, Humanoid?, BasePart?)
        if type(getCharacterParts) == "function" then
            local ok: boolean, character: any, humanoid: any, root: any =
                pcall(getCharacterParts)
            if ok and character then
                return character, humanoid, root
            end
        end
        local character: Model? = LocalPlayer and LocalPlayer.Character
        if not character then
            return nil, nil, nil
        end
        local humanoid: Humanoid? =
            character:FindFirstChildOfClass("Humanoid") :: Humanoid?
        local root: BasePart? =
            character:FindFirstChild("HumanoidRootPart") :: BasePart?
        return character, humanoid, root
    end

    local function rootOf(player: Player?): BasePart?
        local character: Model? = player and player.Character
        if not character then
            return nil
        end
        return character:FindFirstChild("HumanoidRootPart") :: BasePart?
    end

    -- The pickup parts of the family in use, shared with Coin ESP.
    -- A throttled local scan keeps this working if Coin ESP is off.
    local function coinPickups(): {Instance}
        if type(state.mm2CoinPickups) == "function" then
            local ok: boolean, list: any = pcall(state.mm2CoinPickups)
            if ok and type(list) == "table" then
                return list
            end
        end
        -- Cheap first: the game's own tag list. The descendant walk
        -- below is only for builds where the tag list is unavailable.
        local okTagged: boolean, tagged: any = pcall(function(): any
            return game:GetService("CollectionService"):GetTagged("CoinVisual")
        end)
        if okTagged and type(tagged) == "table" and #tagged > 0 then
            return tagged
        end
        local out: {Instance} = {}
        local ok: boolean, descendants: any = pcall(function(): any
            return workspace:GetDescendants()
        end)
        if ok and type(descendants) == "table" then
            for _, object: Instance in ipairs(descendants) do
                if object.Name == "Coin_Server" and object:IsA("BasePart") then
                    local collected: any = nil
                    pcall(function(): ()
                        collected = (object :: any):GetAttribute("Collected")
                    end)
                    if collected ~= true then
                        table.insert(out, object)
                    end
                end
            end
        end
        return out
    end

    -- Live ping for the status line. The farm speed itself is the
    -- slider: the server kicks ("Invalid position", 267) when the
    -- root arrives faster than it accepts, and that limit varies by
    -- map and connection, so the user tunes it -- start low.
    local function pingMillis(): number
        if type(getEstimatedLatency) == "function" then
            local ok: boolean, value: any = pcall(getEstimatedLatency)
            if ok and type(value) == "number" and value == value then
                return math.round(math.clamp(value, 0.02, 0.6) * 1000)
            end
        end
        return 0
    end

    local function setStatus(text: string?): ()
        local card: any = state.mm2AutoFarmFeature
        if card then
            card:SetStatus(text)
        end
    end

    -- Kill All, adapted from YARHM 1.21 ("Kill EVERYONE as
    -- murderer"): equip the knife, pull every living player in front
    -- of us (anchored), then slash. The slash uses the repo's own
    -- knife path (Events.HandleTouched per victim, as KnifeAura
    -- does) and falls back to the game's Stab remote like YARHM.
    local function killAll(): ()
        if type(getPlayerRole) ~= "function"
            or getPlayerRole(LocalPlayer) ~= "Murderer" then
            notify("Auto Farm: Kill All only works as the Murderer.")
            return
        end
        local character: Model?, humanoid: Humanoid?, myRoot: BasePart? =
            characterParts()
        if not character or not humanoid or not myRoot then
            return
        end
        local knife: Tool? = nil
        if type(getPlayerWeapon) == "function" then
            knife = getPlayerWeapon(LocalPlayer, "Knife")
        end
        if not knife then
            notify("Auto Farm: no Knife found for Kill All.")
            return
        end
        if knife.Parent ~= character then
            pcall(function(): ()
                humanoid:EquipTool(knife :: Tool)
            end)
            -- Wait only until the equip lands (one frame normally),
            -- never a fixed sleep: 0.3 s is the ceiling, not the cost.
            local equipDeadline: number = os.clock() + 0.3
            while knife.Parent ~= character
                and os.clock() < equipDeadline do
                task.wait()
            end
        end
        if knife.Parent ~= character then
            return
        end
        local victims: {BasePart} = {}
        for _, player: Player in ipairs(Players:GetPlayers()) do
            if player ~= LocalPlayer
                and (type(isPlayerAlive) ~= "function" or isPlayerAlive(player)) then
                local victimRoot: BasePart? = rootOf(player)
                if victimRoot then
                    table.insert(victims, victimRoot)
                    pcall(function(): ()
                        victimRoot.Anchored = true
                        victimRoot.CFrame = myRoot.CFrame
                            + myRoot.CFrame.LookVector * 1
                    end)
                end
            end
        end
        if #victims == 0 then
            return
        end
        task.wait(0.15)
        local stab: Instance? = knife:FindFirstChild("Stab")
        if stab and stab:IsA("RemoteEvent") then
            pcall(function(): ()
                (stab :: RemoteEvent):FireServer("Slash")
            end)
        end
        local events: Instance? = knife:FindFirstChild("Events")
        local handleTouched: Instance? = events
            and events:FindFirstChild("HandleTouched")
        pcall(function(): ()
            (knife :: Tool):Activate()
        end)
        for _, victimRoot: BasePart in ipairs(victims) do
            if handleTouched and handleTouched:IsA("RemoteEvent") then
                pcall(function(): ()
                    (handleTouched :: RemoteEvent):FireServer(victimRoot)
                end)
            end
            task.wait(0.05)
        end
        task.delay(0.5, function(): ()
            for _, victimRoot: BasePart in ipairs(victims) do
                pcall(function(): ()
                    victimRoot.Anchored = false
                end)
            end
        end)
        notify("Auto Farm: Kill All fired at " .. #victims .. " players.")
    end

    -- Compact spin fling: park on the target spinning hard for a
    -- couple of seconds; contact physics does the rest.
    local function flingPlayer(target: Player?): ()
        if not target then
            return
        end
        if type(state.mm2PerformFling) == "function" then
            pcall(state.mm2PerformFling, target, {
                silent = true,
                duration = 3.5,
                blocking = true,
            })
            return
        end
        local _, _, myRoot: BasePart? = characterParts()
        if not myRoot then
            return
        end
        local saved: CFrame = myRoot.CFrame
        local startedAt: number = os.clock()
        while os.clock() - startedAt < 2.2 do
            local targetRoot: BasePart? = rootOf(target)
            if not targetRoot then
                break
            end
            pcall(function(): ()
                myRoot.CFrame = targetRoot.CFrame
                myRoot.AssemblyAngularVelocity = Vector3.new(0, 400, 0)
                myRoot.AssemblyLinearVelocity = Vector3.zero
            end)
            task.wait()
        end
        pcall(function(): ()
            myRoot.AssemblyAngularVelocity = Vector3.zero
            myRoot.CFrame = saved
        end)
    end

    -- Auto grab gun + auto shoot: equip the dropped sheriff gun and
    -- fire predicted shots at the murderer (same gun remote and
    -- prediction the Shoot module authors).
    local lastShotAt: number = 0
    local function shootMurderer(murderer: Player): boolean
        if os.clock() - lastShotAt < 0.22 then
            return false
        end
        local character: Model?, humanoid: Humanoid? = characterParts()
        if not character or not humanoid then
            return false
        end
        local gun: Tool? = nil
        if type(getPlayerWeapon) == "function" then
            gun = getPlayerWeapon(LocalPlayer, "Gun")
        end
        if not gun then
            return false
        end
        if gun.Parent ~= character then
            pcall(function(): ()
                humanoid:EquipTool(gun :: Tool)
            end)
            local equipDeadline: number = os.clock() + 0.2
            while gun.Parent ~= character
                and os.clock() < equipDeadline do
                task.wait()
            end
        end
        if gun.Parent ~= character
            or gun:GetAttribute("Reloading") == true
            or gun:GetAttribute("IsReloading") == true then
            return false
        end
        local remote: Instance? = gun:FindFirstChild("Shoot")
        if not remote or not remote:IsA("RemoteEvent") then
            return false
        end
        local origin: CFrame? = nil
        if type(getGunOriginCFrame) == "function" then
            local ok: boolean, value: any =
                pcall(getGunOriginCFrame, character, gun)
            if ok then
                origin = value
            end
        end
        if not origin then
            return false
        end
        local endpoint: Vector3? = nil
        local prediction: any = state.mm2Prediction
        if prediction and type(prediction.gunAim) == "function" then
            local ok: boolean, predicted: any = pcall(
                prediction.gunAim, murderer, (origin :: CFrame).Position)
            if ok and predicted then
                endpoint = predicted
            end
        end
        if not endpoint then
            local targetRoot: BasePart? = rootOf(murderer)
            if not targetRoot then
                return false
            end
            endpoint = targetRoot.Position + Vector3.new(0, 0.6, 0)
        end
        lastShotAt = os.clock()
        pcall(function(): ()
            (remote :: RemoteEvent):FireServer(
                CFrame.lookAt((origin :: CFrame).Position, endpoint :: Vector3),
                CFrame.new(endpoint :: Vector3)
            )
        end)
        return true
    end

    local function toggleAutoFarm(enabled: boolean): ()
        disconnectFeatureConnection("MM2AutoFarmTick")
        disconnectFeatureConnection("MM2AutoFarmCoinCollected")
        -- Invokes the restore closure the previous enable registered:
        -- collisions, PlatformStand, AutoRotate and the root all go
        -- back, and the character returns to where the farm grabbed
        -- it (never left lying under the floor, stuck in geometry).
        disconnectFeatureConnection("MM2AutoFarmRestore")

        if not enabled then
            setStatus(nil)
            return
        end

        local bagAmount: number = 0
        local bagLimit: number = 50
        local busy: boolean = false
        local fullHandled: boolean = false
        local roundFullReached: boolean = false
        local teleportedHomeThisRound: boolean = false
        local wasInActiveRound: boolean = false
        local scanCache: {Instance} = {}
        local scanAt: number = 0
        local stuckPart: Instance? = nil
        local stuckSince: number = 0
        local lastTouchPulse: number = 0
        local blacklist: {[Instance]: number} = {}

        -- Engagement state. The farm touches the character ONLY while
        -- engaged inside an active round on a map. In the lobby or
        -- between rounds, the character is left completely alone.
        local engaged: boolean = false
        local engagedCharacter: Model? = nil
        local homeCFrame: CFrame? = nil
        local homeCharacter: Model? = nil
        local hideAnchorPosition: Vector3? = nil
        local savedCollide: {[Instance]: boolean} = {}
        local engagedMode: string? = nil
        local savedWalkSpeed: number? = nil
        local savedRootSize: Vector3? = nil
        local walkLastDistance: number = math.huge
        local walkStuckSince: number = 0

        local function yawOf(frame: CFrame): number
            local look: Vector3 = frame.LookVector
            return math.atan2(-look.X, -look.Z)
        end

        local function getHiddenUnderMapPosition(root: BasePart): Vector3
            if hideAnchorPosition then
                return hideAnchorPosition
            end
            if homeCFrame then
                return homeCFrame.Position - Vector3.new(0, BELOW_OFFSET + 4, 0)
            end
            return root.Position - Vector3.new(0, BELOW_OFFSET + 4, 0)
        end

        local function holdHiddenUnderMap(
            character: Model,
            humanoid: Humanoid,
            root: BasePart
        ): ()
            for _, object: Instance in ipairs(character:GetDescendants()) do
                if object:IsA("BasePart") then
                    if savedCollide[object] == nil then
                        savedCollide[object] = (object :: BasePart).CanCollide
                    end
                    pcall(function(): ()
                        (object :: BasePart).CanCollide = false
                    end)
                end
            end
            local hidePos: Vector3 = getHiddenUnderMapPosition(root)
            pcall(function(): ()
                humanoid.PlatformStand = true
                humanoid.AutoRotate = false
                humanoid:Move(Vector3.zero, false)
                root.AssemblyLinearVelocity = Vector3.zero
                root.AssemblyAngularVelocity = Vector3.zero
                root.CFrame = CFrame.new(hidePos)
                    * CFrame.Angles(0, yawOf(root.CFrame), 0)
            end)
        end

        local function isCharacterInActiveRound(root: BasePart): boolean
            if type(isRoundLifecycleActive) == "function"
                and isRoundLifecycleActive() ~= true then
                return false
            end
            if type(findMM2Map) ~= "function" then
                return false
            end
            local map: Instance? = findMM2Map()
            if not map then
                return false
            end
            if type(getPlayerRole) == "function" then
                local role: any = getPlayerRole(LocalPlayer)
                if role == "Dead" or role == "None" then
                    return false
                end
            end
            if safeZonePlatform and safeZonePlatform.Parent then
                local okZoneDist: boolean, zoneDist: any = pcall(function(): any
                    return (root.Position - safeZonePlatform.Position).Magnitude
                end)
                if okZoneDist and type(zoneDist) == "number" and zoneDist <= 120 then
                    return true
                end
            end
            local refPart: BasePart? = nil
            local spawns: Instance? = (map :: Instance):FindFirstChild("Spawns")
            if spawns then
                refPart = spawns:FindFirstChildWhichIsA("BasePart")
            end
            if not refPart then
                local coinContainer: Instance? = (map :: Instance):FindFirstChild("CoinContainer")
                if coinContainer then
                    refPart = coinContainer:FindFirstChildWhichIsA("BasePart", true)
                end
            end
            if refPart then
                local okDist: boolean, dist: any = pcall(function(): any
                    return (root.Position - refPart.Position).Magnitude
                end)
                if okDist and type(dist) == "number" and dist > 1500 then
                    return false
                end
            end
            return true
        end

        local function restoreCharacter(returnHome: boolean): ()
            local character: Model?, humanoid: Humanoid?, root: BasePart? =
                characterParts()
            for part: Instance, was: boolean in pairs(savedCollide) do
                pcall(function(): ()
                    (part :: BasePart).CanCollide = was
                end)
            end
            table.clear(savedCollide)
            if humanoid then
                pcall(function(): ()
                    humanoid.PlatformStand = false
                    humanoid.AutoRotate = true
                    if humanoid.Sit then
                        humanoid.Sit = false
                    end
                    if savedWalkSpeed then
                        humanoid.WalkSpeed = savedWalkSpeed
                    end
                    humanoid:Move(Vector3.zero, false)
                    humanoid:ChangeState(Enum.HumanoidStateType.Running)
                end)
            end
            savedWalkSpeed = nil
            if root then
                pcall(function(): ()
                    if savedRootSize then
                        root.Size = savedRootSize
                    end
                    root.AssemblyLinearVelocity = Vector3.zero
                    root.AssemblyAngularVelocity = Vector3.zero
                    -- Return the character to the exact last position
                    -- it had right before Auto Farm started (homeCFrame),
                    -- never to a random spawn point, and during active
                    -- farming strictly only when the player has 50 coins.
                    -- Once that 50-coin teleport has cleanly happened once,
                    -- never teleport the character anywhere else in this round.
                    local allowReturnHome: boolean = returnHome
                        and not teleportedHomeThisRound
                        and (bagAmount >= 50 or not enabled)
                        and homeCFrame ~= nil
                        and (not homeCharacter or homeCharacter == character)
                    if allowReturnHome and homeCFrame then
                        local destPosition: Vector3 = homeCFrame.Position
                        if enabled and settings.safeZone and bagAmount >= 50 then
                            destPosition = ensureSafeZonePlatform(homeCFrame.Position)
                        end
                        local targetCF: CFrame = CFrame.new(destPosition)
                            * CFrame.Angles(0, yawOf(homeCFrame), 0)
                        if character then
                            pcall(function(): ()
                                character:PivotTo(targetCF)
                            end)
                        end
                        root.CFrame = targetCF
                        if bagAmount >= 50 then
                            teleportedHomeThisRound = true
                            homeCFrame = nil
                        end
                    elseif not teleportedHomeThisRound then
                        -- Stand back up exactly where we are.
                        root.CFrame = CFrame.new(root.Position)
                            * CFrame.Angles(0, yawOf(root.CFrame), 0)
                    end
                end)
            end
            savedRootSize = nil
            engaged = false
            engagedMode = nil
            engagedCharacter = nil
        end

        local function engage(
            character: Model,
            humanoid: Humanoid,
            root: BasePart
        ): ()
            if homeCharacter ~= character or not homeCFrame then
                homeCFrame = root.CFrame
                homeCharacter = character
            end
            if engagedMode ~= settings.mode then
                -- Mode switched (or first engage): undo the other
                -- mode's body changes without losing homeCFrame.
                restoreCharacter(false)
                engagedMode = settings.mode
            end
            if engagedCharacter ~= character then
                -- New body (respawn): the previous restore belongs to
                -- the old character; remember this one's start point.
                restoreCharacter(false)
                engagedMode = settings.mode
                if homeCharacter ~= character or not homeCFrame then
                    homeCFrame = root.CFrame
                    homeCharacter = character
                end
                engagedCharacter = character
            end
            if not engaged then
                engaged = true
                walkLastDistance = math.huge
                walkStuckSince = os.clock()
                if settings.mode ~= "Walk" then
                    -- Below: upright, always -- no face-down tilt, the
                    -- hitbox below does the reaching. PlatformStand
                    -- hands the body to physics velocity alone.
                    pcall(function(): ()
                        root.CFrame = CFrame.new(root.Position)
                            * CFrame.Angles(0, yawOf(root.CFrame), 0)
                        humanoid.PlatformStand = true
                        humanoid.AutoRotate = false
                        if savedRootSize == nil then
                            savedRootSize = root.Size
                        end
                        root.Size = HITBOX_SIZE
                    end)
                end
            end
            if settings.mode == "Walk" then
                -- Walk on the real ground: collisions stay exactly as
                -- they are (NoClip would drop the character through
                -- the floor), and the slider is the WalkSpeed.
                if savedWalkSpeed == nil then
                    savedWalkSpeed = humanoid.WalkSpeed
                end
                pcall(function(): ()
                    humanoid.WalkSpeed =
                        math.clamp(settings.speed, 5, 60)
                end)
                return
            end
            -- Below keeps NoClip: every character part (tools
            -- included) is forced non-collidable each tick, so the
            -- flight never bumps a platform edge on the way to a coin.
            for _, object: Instance in ipairs(character:GetDescendants()) do
                if object:IsA("BasePart") then
                    if savedCollide[object] == nil then
                        savedCollide[object] = (object :: BasePart).CanCollide
                    end
                    pcall(function(): ()
                        (object :: BasePart).CanCollide = false
                    end)
                end
            end
        end

        -- Fly the root at a destination with PHYSICS velocity. The
        -- v82 build wrote CFrame positions every tick and zeroed the
        -- velocity: to the server that is a stream of teleports, and
        -- MM2 answers "Invalid position" (kick 267). A velocity the
        -- physics engine integrates replicates as ordinary movement.
        -- Speed is the Farm Speed slider -- start low, raise it until
        -- just before the server complains, that point is yours.
        local function moveTowards(
            root: BasePart,
            destination: Vector3,
            deltaTime: number
        ): number
            local delta: Vector3 = destination - root.Position
            local distance: number = delta.Magnitude
            if distance < 0.05 then
                pcall(function(): ()
                    root.AssemblyLinearVelocity = Vector3.zero
                end)
                return 0
            end
            local speed: number = math.clamp(settings.speed, 5, 60)
            if distance <= math.max(0.5, speed * deltaTime) then
                -- Final approach inside one step: land on the point
                -- and stop, instead of orbiting it at full speed.
                pcall(function(): ()
                    root.CFrame = CFrame.new(destination)
                        * (root.CFrame - root.CFrame.Position)
                    root.AssemblyLinearVelocity = Vector3.zero
                end)
                return 0
            end
            pcall(function(): ()
                root.AssemblyLinearVelocity = delta.Unit * speed
                root.AssemblyAngularVelocity = Vector3.zero
            end)
            return distance
        end

        -- Walk mode movement: point the humanoid at the coin and let
        -- the engine's own locomotion do the walking. Returns the
        -- horizontal distance left. If the distance stops shrinking
        -- (a wall, a ledge), a hop is tried once a second; the caller's
        -- stuck timer blacklists coins walking truly cannot reach.
        local function walkTowards(
            humanoid: Humanoid,
            root: BasePart,
            destination: Vector3
        ): number
            local delta: Vector3 = destination - root.Position
            local flat: Vector3 = Vector3.new(delta.X, 0, delta.Z)
            local distance: number = flat.Magnitude
            local now: number = os.clock()
            if distance < 1.4 then
                pcall(function(): ()
                    humanoid:Move(Vector3.zero, false)
                end)
                return distance
            end
            if distance < walkLastDistance - 0.3 then
                walkLastDistance = distance
                walkStuckSince = now
            elseif now - walkStuckSince > 1.0 then
                walkStuckSince = now
                pcall(function(): ()
                    humanoid.Jump = true
                end)
            end
            pcall(function(): ()
                humanoid:Move(flat.Unit, false)
            end)
            return distance
        end

        -- The Coin_Server part that pays for a pickup entry (ESP hands
        -- out the visual, the server part is its parent).
        local function serverPartOf(part: Instance): Instance?
            if part.Name == "Coin_Server" then
                return part
            end
            local parent: Instance? = part.Parent
            if parent and parent.Name == "Coin_Server" then
                return parent
            end
            return part
        end

        -- Still there to be collected? A coin somebody already took
        -- keeps its entry in the throttled scan for a moment, and the
        -- old farm flew up to that ghost and hovered over it. The
        -- attribute/parent check runs on the chosen coin every tick,
        -- so a collected coin stops being a target at once.
        local function stillCollectable(part: Instance): boolean
            if not part.Parent then
                return false
            end
            local server: Instance? = serverPartOf(part)
            local collected: any = nil
            pcall(function(): ()
                collected = (server :: any):GetAttribute("Collected")
            end)
            return collected ~= true
        end

    -- The gun grab is an in-round action for non-Murderer roles: as
    -- Murderer it must never run, and in the lobby there is no round,
    -- no murderer and no dropped gun to shoot with. Note that once an
    -- Innocent picks up the dropped gun, MM2 promotes their role to
    -- "Hero" / "Sheriff", so those roles must remain allowed while
    -- equipping and continuously shooting the Murderer.
    local function canGrabGun(): boolean
        if type(getPlayerRole) ~= "function" then
            return false
        end
        local role: any = getPlayerRole(LocalPlayer)
        if role ~= "Innocent" and role ~= "Sheriff" and role ~= "Hero" then
            return false
        end
        if type(isRoundLifecycleActive) ~= "function"
            or isRoundLifecycleActive() ~= true then
            return false
        end
        if type(findMM2Map) ~= "function" or not findMM2Map() then
            return false
        end
        return true
    end

    -- Immediate pickup attempt: pulse the touch between our root and the
    -- dropped gun's part instead of travelling or sleeping. True only
    -- when the gun has already arrived; the farm can retry on a later frame.
    local function touchDroppedGun(
        drop: Instance,
        root: BasePart
    ): boolean
        if type(state.fireTouchInterest) ~= "function" then
            return false
        end
        local touchPart: Instance? = nil
        if drop:IsA("BasePart") then
            touchPart = drop
        elseif drop:IsA("Model") then
            touchPart = drop:FindFirstChild("Handle", true)
                or drop:FindFirstChildWhichIsA("BasePart", true)
        end
        if not touchPart then
            return false
        end
        pcall(state.fireTouchInterest, root, touchPart, 0)
        pcall(state.fireTouchInterest, root, touchPart, 1)
        return type(getPlayerWeapon) == "function"
            and getPlayerWeapon(LocalPlayer, "Gun") ~= nil
    end

    -- Full-bag Auto Grab gun and Shoot: fetch the dropped sheriff gun
    -- if we do not already carry it, equip it, and continuously shoot
    -- the murderer until the murderer is eliminated or the round ends.
    local function grabGunAndShoot(): ()
        if not canGrabGun() then
            return
        end
        local shootLoopDeadline: number = os.clock() + 30
        while os.clock() < shootLoopDeadline and enabled and settings.grabGunShoot do
            if not canGrabGun() then
                return
            end
            local murderer: Player? = nil
            if type(findMurderer) == "function" then
                murderer = findMurderer()
            end
            if not murderer
                or (type(isPlayerAlive) == "function"
                    and not isPlayerAlive(murderer)) then
                return
            end
            local character: Model?, humanoid: Humanoid?,
                startRoot: BasePart? = characterParts()
            if not character or not humanoid or not startRoot
                or humanoid.Health <= 0 then
                return
            end

            local gun: Tool? = nil
            if type(getPlayerWeapon) == "function" then
                gun = getPlayerWeapon(LocalPlayer, "Gun")
            end
            if not gun and type(findDroppedGun) == "function" then
                local firstDrop: Instance? = findDroppedGun()
                if firstDrop and touchDroppedGun(firstDrop, startRoot) then
                    gun = getPlayerWeapon(LocalPlayer, "Gun")
                end
                local pickupDeadline: number = os.clock() + 5
                while os.clock() < pickupDeadline and not gun do
                    if not canGrabGun() or not enabled or not settings.grabGunShoot then
                        return
                    end
                    local curChar: Model?, curHum: Humanoid?,
                        root: BasePart? = characterParts()
                    local drop: Instance? = findDroppedGun()
                    if not curChar or not curHum or not root or not drop then
                        break
                    end
                    if touchDroppedGun(drop, root) then
                        gun = getPlayerWeapon(LocalPlayer, "Gun")
                        if gun then
                            break
                        end
                    end
                    if teleportedHomeThisRound or roundFullReached then
                        break
                    end
                    local dropPosition: Vector3? = nil
                    pcall(function(): ()
                        if drop:IsA("BasePart") then
                            dropPosition = (drop :: BasePart).Position
                        elseif drop:IsA("Model") then
                            dropPosition = (drop :: Model):GetPivot().Position
                        end
                    end)
                    if not dropPosition then
                        break
                    end
                    engage(curChar, curHum, root)
                    local remaining: number
                    if settings.mode == "Walk" then
                        remaining = walkTowards(
                            curHum, root, dropPosition :: Vector3)
                    else
                        remaining = moveTowards(
                            root,
                            (dropPosition :: Vector3) + Vector3.new(0, 1, 0),
                            0.05
                        )
                    end
                    if remaining < 2.5 then
                        task.wait(0.05)
                        gun = getPlayerWeapon(LocalPlayer, "Gun")
                        if gun then
                            break
                        end
                    end
                    task.wait()
                end
            end

            if not gun then
                -- Wait briefly for the gun to drop or become available while the round is active
                task.wait(0.15)
                continue
            end

            character, humanoid = characterParts()
            if not character or not humanoid or humanoid.Health <= 0 then
                return
            end
            if gun.Parent ~= character then
                pcall(function(): ()
                    humanoid:EquipTool(gun :: Tool)
                end)
                local equipWait: number = os.clock() + 0.15
                while gun.Parent ~= character and os.clock() < equipWait do
                    task.wait()
                end
            end
            if gun.Parent == character and canGrabGun() then
                local firedSilent: boolean = false
                if type(state.mm2FireSilentShot) == "function" then
                    local okShot: boolean, shotRes: any =
                        pcall(state.mm2FireSilentShot, murderer)
                    firedSilent = okShot and shotRes == true
                end
                if not firedSilent then
                    shootMurderer(murderer)
                end
            end
            task.wait(0.12)
        end
    end

        -- The full-bag sequence, in the user's order: Kill All,
        -- return to exact pre-farm position, Auto Grab gun and Shoot,
        -- reset, then the post-reset flings. Runs once per 50-coin fill.
        local function runFullSequence(): ()
            busy = true
            local ok: boolean, err: any = pcall(function(): ()
                -- Everything in this sequence happens ONLY when the
                -- bag is full (50): Kill All, return to the character's
                -- last position before Auto Farm started (homeCFrame),
                -- gun grab + continuous shooting, reset, and flings.
                -- None of it runs during ordinary farming.
                if settings.killAllOnFull then
                    killAll()
                    task.wait()
                end
                restoreCharacter(true)
                if settings.grabGunShoot then
                    grabGunAndShoot()
                    task.wait(0.15)
                end
                if settings.resetOnFull then
                    local oldCharacter: Model? = LocalPlayer.Character
                    local _, humanoid: Humanoid? = characterParts()
                    if humanoid then
                        pcall(function(): ()
                            humanoid.Health = 0
                        end)
                    end
                    -- Wait for the respawned character, checking
                    -- every frame instead of four times a second.
                    local deadline: number = os.clock() + 10
                    while os.clock() < deadline do
                        local character: Model?, newHumanoid: Humanoid?,
                            newRoot: BasePart? = characterParts()
                        if character and character ~= oldCharacter
                            and newHumanoid and newHumanoid.Health > 0
                            and newRoot then
                            break
                        end
                        task.wait()
                    end
                    task.wait(0.1)
                end
                -- Flings belong to the full bag too, reset or not: with
                -- a reset they meet the fresh character first (above),
                -- without one they simply happen now.
                if settings.flingMurder
                    and type(findMurderer) == "function" then
                    flingPlayer(findMurderer())
                end
                if settings.flingSheriff
                    and type(findSheriff) == "function" then
                    flingPlayer(findSheriff())
                end
            end)
            if not ok then
                warn("Auto Farm full-bag sequence failed: " .. tostring(err))
            end
            busy = false
        end

        local remotes: any = core.mm2GameplayRemotes
        local collected: Instance? = remotes
            and remotes:FindFirstChild("CoinCollected")
        if collected and collected:IsA("RemoteEvent") then
            featureConnections.MM2AutoFarmCoinCollected =
                (collected :: any).OnClientEvent:Connect(
                    function(_bag: any, amount: any, limit: any): ()
                        if type(limit) == "number" and limit >= 50 then
                            bagLimit = limit
                        end
                        if type(amount) == "number" then
                            if amount > bagAmount then
                                totalCoinsCollected += (amount - bagAmount)
                                refreshFarmOverlay()
                            end
                            bagAmount = amount
                        end
                        local targetLimit: number = math.max(50, bagLimit)
                        if bagAmount < targetLimit then
                            fullHandled = false
                            roundFullReached = false
                        end
                    end
                )
        end

        featureConnections.MM2AutoFarmTick = TaskManager:Connect(
            function(deltaTime: number): ()
                if type(deltaTime) == "number" and deltaTime > 0 and deltaTime < 5 then
                    farmElapsedSeconds += deltaTime
                    refreshFarmOverlay()
                end
                if busy then
                    return
                end
                local character: Model?, humanoid: Humanoid?,
                    root: BasePart? = characterParts()
                if not character or not humanoid or not root
                    or humanoid.Health <= 0 then
                    return
                end

                -- Strict lobby & non-round guard: NEVER activate, move,
                -- or farm in the lobby or outside an active round on a map.
                local inActiveRound: boolean = isCharacterInActiveRound(root)
                if not inActiveRound then
                    if engaged then
                        restoreCharacter(false)
                    end
                    if wasInActiveRound then
                        wasInActiveRound = false
                        bagAmount = 0
                        fullHandled = false
                        roundFullReached = false
                        teleportedHomeThisRound = false
                        homeCFrame = nil
                        homeCharacter = nil
                        hideAnchorPosition = nil
                        destroySafeZonePlatform()
                    end
                    setStatus("Auto Farm: waiting in lobby")
                    stuckPart = nil
                    return
                end

                if not wasInActiveRound then
                    wasInActiveRound = true
                    bagAmount = 0
                    fullHandled = false
                    roundFullReached = false
                    teleportedHomeThisRound = false
                    homeCFrame = root.CFrame
                    homeCharacter = character
                    hideAnchorPosition = root.Position - Vector3.new(0, BELOW_OFFSET + 4, 0)
                end

                local targetLimit: number = math.max(50, bagLimit)

                -- Stop farming ONLY when 50 coins (full bag) are detected!
                if bagAmount >= targetLimit then
                    if not fullHandled then
                        fullHandled = true
                        roundFullReached = true
                        if settings.killAllOnFull or settings.resetOnFull
                            or settings.flingMurder or settings.flingSheriff
                            or settings.grabGunShoot then
                            task.spawn(runFullSequence)
                        else
                            restoreCharacter(true)
                        end
                    elseif settings.grabGunShoot and canGrabGun() then
                        task.spawn(function(): ()
                            if busy then
                                return
                            end
                            busy = true
                            pcall(grabGunAndShoot)
                            busy = false
                        end)
                    else
                        setStatus(string.format(
                            "Auto Farm: full bag (%d/%d) - stopped at start position",
                            bagAmount, targetLimit
                        ))
                    end
                    return
                end

                if roundFullReached then
                    return
                end

                -- Void guard. While bagAmount < 50, never teleport back to
                -- homeCFrame on top of the map; recover directly to the
                -- hidden spot underneath the map instead of falling further.
                local destroyHeight: number = workspace.FallenPartsDestroyHeight
                if destroyHeight ~= destroyHeight then
                    destroyHeight = -500
                end
                if root.Position.Y <= destroyHeight + 60 then
                    holdHiddenUnderMap(character, humanoid, root)
                    setStatus(
                        "Auto Farm: recovered from the void - hidden under map"
                    )
                    return
                end

                -- Capture pre-farm homeCFrame and stay engaged while
                -- bagAmount < 50 inside the active round.
                engage(character, humanoid, root)

                -- Nearest pickup, from Coin ESP's own detection.
                local now: number = os.clock()
                local scanInterval: number = if #scanCache == 0 then 0.12 else 0.35
                if now - scanAt > scanInterval then
                    scanAt = now
                    scanCache = coinPickups()
                end
                local nearest: Instance? = nil
                local nearestPosition: Vector3? = nil
                local nearestDistance: number = math.huge
                for _, part: Instance in ipairs(scanCache) do
                    if part.Parent
                        and stillCollectable(part)
                        and (not blacklist[part] or blacklist[part] < now) then
                        local position: Vector3? = nil
                        pcall(function(): ()
                            position = (part :: BasePart).Position
                        end)
                        if position then
                            local distance: number =
                                ((position :: Vector3) - root.Position).Magnitude
                            if distance < nearestDistance then
                                nearest = part
                                nearestPosition = position
                                nearestDistance = distance
                            end
                        end
                    end
                end
                if not nearest or not nearestPosition then
                    -- Round starting or 0 coins currently in the server while
                    -- bag < 50: stay quietly hidden underneath the map (fixed
                    -- CFrame + zero velocity so gravity never pulls us down),
                    -- never teleporting back to the map surface until 50 coins.
                    scanAt = now - 0.25
                    holdHiddenUnderMap(character, humanoid, root)
                    setStatus(string.format(
                        "Auto Farm (%s): waiting for coin - bag %d/%d - speed %d u/s - ping %dms",
                        settings.mode, bagAmount, targetLimit,
                        math.round(math.clamp(settings.speed, 5, 60)),
                        pingMillis()
                    ))
                    stuckPart = nil
                    return
                end
                hideAnchorPosition = Vector3.new(
                    (nearestPosition :: Vector3).X,
                    (nearestPosition :: Vector3).Y - (BELOW_OFFSET + 4),
                    (nearestPosition :: Vector3).Z
                )
                local remaining: number
                local arrived: boolean
                if settings.mode == "Walk" then
                    remaining = walkTowards(
                        humanoid,
                        root,
                        nearestPosition :: Vector3
                    )
                    arrived = remaining < 1.4
                else
                    local destination: Vector3 =
                        (nearestPosition :: Vector3)
                        + Vector3.new(0, -BELOW_OFFSET, 0)
                    remaining = moveTowards(root, destination, deltaTime)
                    arrived = remaining < 1.2
                end
                if arrived then
                    -- Belt and braces: some builds only pay on a
                    -- physics Touched, and a fully NoClipped body can
                    -- miss that pairing. Pulse the touch directly
                    -- against the Coin_Server part, like the farm in
                    -- YARHM did, until the coin is gone.
                    if now - lastTouchPulse > 0.25 then
                        lastTouchPulse = now
                        local touchPart: Instance? =
                            serverPartOf(nearest)
                        if type(state.fireTouchInterest) == "function"
                            and touchPart then
                            pcall(state.fireTouchInterest, root, touchPart, 0)
                            pcall(state.fireTouchInterest, root, touchPart, 1)
                        end
                    end
                end
                setStatus(string.format(
                    "Auto Farm (%s): %d coins - bag %d/%d - speed %d u/s - ping %dms",
                    settings.mode, #scanCache, bagAmount, targetLimit,
                    math.round(math.clamp(settings.speed, 5, 60)),
                    pingMillis()
                ))
                if arrived then
                    -- Parked under the coin: if it does not collect,
                    -- skip it for a while instead of getting stuck.
                    if stuckPart ~= nearest then
                        stuckPart = nearest
                        stuckSince = now
                    elseif now - stuckSince > STUCK_SECONDS then
                        blacklist[nearest] = now + BLACKLIST_SECONDS
                        stuckPart = nil
                    end
                else
                    stuckPart = nil
                end
            end
        )

        -- Turning the feature off runs this through
        -- disconnectFeatureConnection above: full restore, and the
        -- character is put back where the farm first grabbed it.
        featureConnections.MM2AutoFarmRestore = {
            Disconnect = function(): ()
                destroySafeZonePlatform()
                restoreCharacter(true)
            end,
        }
    end

    local AutoFarmFeature: any = createUniversalFeature(
        "Auto Farm",
        "Walks on the ground to the nearest coins (Walk), or flies upright under the floor with a grown hitbox that still touches them (Below), with full-bag actions.",
        6,
        toggleAutoFarm,
        {
            categoryName = "Utilities",
            parent = MM2Scroll,
            registry = mm2Features,
        }
    )
    state.mm2AutoFarmFeature = AutoFarmFeature

    if type(state.addSectionOption) == "function" then
        state.addSectionOption(AutoFarmFeature, "Overlay Info")
    end
    if type(state.addStatOption) == "function" then
        coinsCollectedStat = state.addStatOption(AutoFarmFeature, "Coins Collected", "0")
        farmTimeStat = state.addStatOption(AutoFarmFeature, "Time", "00:00")
    end

    addCycleOption(AutoFarmFeature, "Farm Mode", {"Walk", "Below (Hitbox)"}, 1,
        function(value: string): ()
            settings.mode = if value == "Walk" then "Walk" else "Below"
        end, "Walk: your character walks on the ground to each coin (nothing about the body is changed; the slider is WalkSpeed). Below (Hitbox): upright, NoClip, flying under the floor with the root hitbox grown so it still touches the coin from below.")
    addNumberOption(AutoFarmFeature, "Farm Speed", 16, 5, 60,
        function(value: number): ()
            settings.speed = value
        end, "Walk mode: WalkSpeed. Below mode: flight speed in studs/second -- if the server kicks you (Invalid position), lower it; raise it slowly to find your fastest safe speed.", 1)
    addToggleOption(AutoFarmFeature, "Safe Zone", true,
        function(value: boolean): ()
            settings.safeZone = value == true
        end, "When you reach 50 coins, teleports you to a platform in the void so the Murderer cannot reach or kill you.")
    addToggleOption(AutoFarmFeature, "Reset When Full Coin Bag", true,
        function(value: boolean): ()
            settings.resetOnFull = value
        end, "Reset the character as soon as the coin bag fills.")
    addToggleOption(AutoFarmFeature, "Fling Murder after reset", false,
        function(value: boolean): ()
            settings.flingMurder = value
        end, "When the coin bag fills (50): fling the Murderer (after the reset above, if it is on).")
    addToggleOption(AutoFarmFeature, "Fling Sheriff after reset", false,
        function(value: boolean): ()
            settings.flingSheriff = value
        end, "When the coin bag fills (50): fling the Sheriff (after the reset above, if it is on).")
    addToggleOption(AutoFarmFeature, "Auto Grab gun and Shoot", false,
        function(value: boolean): ()
            settings.grabGunShoot = value
        end, "Only when the coin bag fills (50), only as Innocent and only during an active round (never as Murderer, never in the lobby): try an instant touch for the dropped sheriff gun, otherwise walk/fly to it, equip it, and fire one SilentAim shot at the Murderer. Never during ordinary farming.")
    addToggleOption(AutoFarmFeature, "Auto Kill All When full coin bag", false,
        function(value: boolean): ()
            settings.killAllOnFull = value
        end, "As Murderer, when the bag fills: pull everyone in front of you and slash (YARHM Kill All).")
    addInformationOption(
        AutoFarmFeature,
        "Walk walks your character on the ground to the nearest pickup Coin ESP sees (safest, and the body's own touch collects). Below (Hitbox) flies upright under the floor by physics velocity (never position teleports) with NoClip and the root hitbox grown to 4x8x4, so the coin pays from underneath without lying the character face-down. Already-collected coins are dropped as targets the moment they are collected. If Below kicks you for Invalid position, lower Farm Speed and raise it little by little. Turning it off restores collisions, hitbox and WalkSpeed, and returns you upright to where you started."
    )

    activeCleanup = function(): ()
        state.mm2AutoFarmFeature = nil
        toggleAutoFarm(false)
    end
    Module.Events = featureConnections
    Module.Initialized = true
    return Module
end

function Module.destroy(): ()
    if not Module.Initialized then
        return
    end
    Module.Initialized = false
    pcall(activeCleanup)
    activeCleanup = function(): ()
    end
    Module.Events = {}
    Module.Runtime = nil
end

return Module

]],
        ["src/games/MM2/Other/AutoUnbox.lua"] = [=[
-- MM2 Auto Unbox: opens the game's own mystery boxes through the same remote
-- the shop uses, with the box and the currency chosen in the menu.
--
-- What the place dump says a box is. The box catalogue lives in
-- `ReplicatedStorage/Database/Sync`: `Sync.MysteryBox` (Mystery Box #1/#2,
-- Knife Box #1-#5, Rainbow Box, Gun Box #1-#3) and `Sync.Eggs` (Common Egg).
-- Event boxes live under `SharedServices/EventInfoService1`: the
-- `MysteryBoxes` folder (Christmas2024Box) and one `MysteryBox` module per
-- entry of `EventList` (Summer2025Box, Halloween2025Box). Every box id also
-- appears in `Sync.NewShop` with its `Price` table, whose keys ARE the
-- currencies it accepts: classic boxes take Coins/Gems/Key, the Christmas box
-- takes SnowTokens2024/SnowKey2024, the Summer box BeachBalls2025/SummerKey2025
-- and the Halloween box Candies2025/HalloweenKey2025.
--
-- How the game opens one. The shop calls
-- `Remotes.Shop.OpenCrate:InvokeServer(boxId, "MysteryBox", currency)` (or
-- `("...", "Eggs", currency)` for pets) and gets the rewarded item id back.
-- The reveal is pure client cosmetics: `Remotes.Shop.BoxController:Fire(list)`
-- plays the official opening animation and reports `CrateComplete`, or
-- `Remotes.Shop.EggController:Fire(eggId, petId)` hatches pets. This module
-- replays exactly that flow; it never touches a Robux prompt.
--
-- Which currency to pay with. The round announces the coin family it pays out
-- through `Remotes/Gameplay/CoinsStarted` (bag names `Coin`, `Candy`,
-- `SnowToken`, `BeachBall`, `Egg`), and `Workspace` carries `CurrentEvent`,
-- `isChristmas`, `IsSummer`, `IsEaster` and `isValentines`. Auto maps that
-- family onto the currencies the chosen box accepts.
local Module = {
    Name = "MM2 Auto Unbox",
    Events = {} :: {[string]: any},
    Initialized = false,
    Runtime = nil :: any,
}

local activeCleanup: () -> () = function(): () end

type BoxEntry = {
    id: string,
    name: string,
    category: string,
    prices: {[string]: number},
}

local AUTO_CURRENCY: string = "Auto"
local REVEAL_ON: string = "On"
local REVEAL_OFF: string = "Off"
local DEFAULT_BOX_LABEL: string = "Mystery Box #1"

-- The catalogue as the dump ships it, used when the Sync module cannot be
-- required. Order matches the shop: classic boxes, eggs, event boxes.
local FALLBACK_BOXES: {BoxEntry} = {
    {id = "MysteryBox1", name = "Mystery Box #1", category = "MysteryBox", prices = {Coins = 1000, Gems = 100, Key = 1}},
    {id = "MysteryBox2", name = "Mystery Box #2", category = "MysteryBox", prices = {Coins = 1000, Gems = 100, Key = 1}},
    {id = "KnifeBox1", name = "Knife Box #1", category = "MysteryBox", prices = {Coins = 1000, Gems = 100, Key = 1}},
    {id = "KnifeBox2", name = "Knife Box #2", category = "MysteryBox", prices = {Coins = 1000, Gems = 100, Key = 1}},
    {id = "KnifeBox3", name = "Knife Box #3", category = "MysteryBox", prices = {Coins = 1000, Gems = 100, Key = 1}},
    {id = "KnifeBox4", name = "Knife Box #4", category = "MysteryBox", prices = {Coins = 1000, Gems = 100, Key = 1}},
    {id = "KnifeBox5", name = "Knife Box #5", category = "MysteryBox", prices = {Coins = 1000, Gems = 100, Key = 1}},
    {id = "MLG Box", name = "Rainbow Box", category = "MysteryBox", prices = {Coins = 1000, Gems = 100, Key = 1}},
    {id = "GunBox1", name = "Gun Box #1", category = "MysteryBox", prices = {Coins = 1000, Gems = 100, Key = 1}},
    {id = "GunBox2", name = "Gun Box #2", category = "MysteryBox", prices = {Coins = 1000, Gems = 100, Key = 1}},
    {id = "GunBox3", name = "Gun Box #3", category = "MysteryBox", prices = {Coins = 1000, Gems = 100, Key = 1}},
    {id = "Egg", name = "Common Egg", category = "Eggs", prices = {Coins = 1000, Gems = 100}},
    {id = "Christmas2024Box", name = "Christmas Box '24", category = "MysteryBox", prices = {SnowTokens2024 = 800, SnowKey2024 = 1}},
    {id = "Summer2025Box", name = "Summer Box '25", category = "MysteryBox", prices = {BeachBalls2025 = 800, SummerKey2025 = 1}},
    {id = "Halloween2025Box", name = "Halloween Box '25", category = "MysteryBox", prices = {Candies2025 = 800, HalloweenKey2025 = 1}},
}

-- Coin family to the currencies that family pays for. Currency names come
-- from `Sync.Currencies`; the order prefers the current year's currency.
local FAMILY_CURRENCIES: {[string]: {string}} = {
    Coin = {"Coins"},
    Candy = {"Candies2025", "Candies2024", "Candies2022"},
    SnowToken = {"SnowTokens2024", "SnowTokens2023", "SnowTokens2022", "SnowTokens2020"},
    BeachBall = {"BeachBalls2025"},
    Egg = {"Eggs2025", "RareEggs2025"},
    Heart = {"Hearts2023"},
}

local BAG_TO_FAMILY: {[string]: string} = {
    Coin = "Coin",
    Candy = "Candy",
    SnowToken = "SnowToken",
    BeachBall = "BeachBall",
    Egg = "Egg",
}

local function lower(value: string): string
    return string.lower(value)
end

local function contains(value: string, needle: string): boolean
    return string.find(value, needle, 1, true) ~= nil
end

local function sortedKeys(map: {[string]: any}): {string}
    local keys: {string} = {}
    for key: string in pairs(map) do
        table.insert(keys, key)
    end
    table.sort(keys)
    return keys
end

function Module.init(runtime: any): any
    if Module.Initialized then
        return Module
    end
    local core: any = state.mm2Core
    assert(type(core) == "table", "MM2 Auto Unbox requires the MM2 core module")
    Module.Runtime = runtime

    local settings = {
        boxLabel = DEFAULT_BOX_LABEL,
        currency = AUTO_CURRENCY,
        delay = 1.5,
        maxBoxes = 10,
        reveal = REVEAL_ON,
    }
    local session = {
        opened = 0,
        failures = 0,
        consecutiveFailures = 0,
        nextAt = 0,
        finished = false,
    }
    -- The coin family the server announces; drives the Auto currency.
    local serverFamily: string? = nil

    ---------------------------------------------------------------
    -- Catalogue: every box the game knows, with its display name and
    -- the currencies its price table accepts.
    ---------------------------------------------------------------

    local function safeRequire(instance: Instance?): any?
        if not instance then
            return nil
        end
        local ok: boolean, result: any = pcall(function(): any
            return (state :: any).requireModule(instance)
        end)
        if ok then
            return result
        end
        return nil
    end

    local function priceOf(boxId: string, sync: any): {[string]: number}?
        if type(sync) == "table" and type(sync.NewShop) == "table" then
            local newShop: any = sync.NewShop
            local holders: {any} = {}
            if type(newShop[boxId]) == "table" then
                table.insert(holders, newShop[boxId])
            end
            if type(newShop.Weapons) == "table" and type(newShop.Weapons[boxId]) == "table" then
                table.insert(holders, newShop.Weapons[boxId])
            end
            if type(newShop.MysteryBox) == "table" and type(newShop.MysteryBox[boxId]) == "table" then
                table.insert(holders, newShop.MysteryBox[boxId])
            end
            for _, holder: any in ipairs(holders) do
                if type(holder.Price) == "table" then
                    return holder.Price
                end
            end
        end
        for _, entry: BoxEntry in ipairs(FALLBACK_BOXES) do
            if entry.id == boxId then
                return entry.prices
            end
        end
        return nil
    end

    local function eventBoxModules(): {Instance}
        local found: {Instance} = {}
        local replicated: Instance = game:GetService("ReplicatedStorage")
        local shared: Instance? = replicated:FindFirstChild("SharedServices")
        local service: Instance? = shared and shared:FindFirstChild("EventInfoService1")
        if not service then
            return found
        end
        local direct: Instance? = service:FindFirstChild("MysteryBoxes")
        if direct then
            for _, child: Instance in ipairs(direct:GetChildren()) do
                if child:IsA("ModuleScript") then
                    table.insert(found, child)
                end
            end
        end
        local eventList: Instance? = service:FindFirstChild("EventList")
        if eventList then
            for _, event: Instance in ipairs(eventList:GetChildren()) do
                local boxModule: Instance? = event:FindFirstChild("MysteryBox")
                if boxModule and boxModule:IsA("ModuleScript") then
                    table.insert(found, boxModule)
                end
            end
        end
        return found
    end

    local function buildCatalog(): ({BoxEntry}, {string})
        local catalog: {BoxEntry} = {}
        local seen: {[string]: boolean} = {}
        local function add(entry: BoxEntry): ()
            if seen[entry.id] then
                return
            end
            seen[entry.id] = true
            table.insert(catalog, entry)
        end

        local replicated: Instance = game:GetService("ReplicatedStorage")
        local database: Instance? = replicated:FindFirstChild("Database")
        local sync: any = safeRequire(database and database:FindFirstChild("Sync"))
        if type(sync) == "table" then
            for _, bankName: string in ipairs({"MysteryBox", "Eggs"}) do
                local bank: any = (sync :: any)[bankName]
                if type(bank) == "table" then
                    for id: string, data: any in pairs(bank) do
                        add({
                            id = id,
                            name = (type(data) == "table" and type(data.Name) == "string" and data.Name) or id,
                            category = bankName == "Eggs" and "Eggs" or "MysteryBox",
                            prices = priceOf(id, sync) or {},
                        })
                    end
                end
            end
        end

        -- Event boxes: the module instance name is the box id, its
        -- `ItemData.Name` (or `Name`) is what the shop calls it.
        for _, boxModule: Instance in ipairs(eventBoxModules()) do
            local data: any = safeRequire(boxModule)
            local display: string? = nil
            if type(data) == "table" then
                if type(data.ItemData) == "table" and type(data.ItemData.Name) == "string" then
                    display = data.ItemData.Name
                elseif type(data.Name) == "string" and data.Name ~= boxModule.Name then
                    display = data.Name
                end
            end
            add({
                id = boxModule.Name,
                name = display or boxModule.Name,
                category = "MysteryBox",
                prices = priceOf(boxModule.Name, sync) or {},
            })
        end

        -- Anything the dump knows and the live game has not registered yet is
        -- still worth offering: the remote answers with a nil reward when a
        -- box is not on sale, and that is reported honestly.
        for _, entry: BoxEntry in ipairs(FALLBACK_BOXES) do
            add(entry)
        end

        table.sort(catalog, function(a: BoxEntry, b: BoxEntry): boolean
            return lower(a.name) < lower(b.name)
        end)

        -- Unique labels for the selector.
        local labelCounts: {[string]: number} = {}
        for _, entry: BoxEntry in ipairs(catalog) do
            labelCounts[entry.name] = (labelCounts[entry.name] or 0) + 1
        end
        local labels: {string} = {}
        for _, entry: BoxEntry in ipairs(catalog) do
            if labelCounts[entry.name] > 1 then
                table.insert(labels, entry.name .. " (" .. entry.id .. ")")
            else
                table.insert(labels, entry.name)
            end
        end
        return catalog, labels
    end

    local catalog: {BoxEntry}, boxLabels: {string} = buildCatalog()
    local labelToEntry: {[string]: BoxEntry} = {}
    for index: number, entry: BoxEntry in ipairs(catalog) do
        labelToEntry[boxLabels[index]] = entry
    end
    if not labelToEntry[settings.boxLabel] then
        settings.boxLabel = boxLabels[1] or ""
    end

    local function currentEntry(): BoxEntry?
        return labelToEntry[settings.boxLabel] or catalog[1]
    end

    -- Every currency the catalogue references, so the selector can name the
    -- coin the player is farming right now.
    local currencyChoices: {string} = {AUTO_CURRENCY}
    do
        local seen: {[string]: boolean} = {[AUTO_CURRENCY] = true}
        for _, entry: BoxEntry in ipairs(catalog) do
            for currency: string in pairs(entry.prices) do
                if not seen[currency] then
                    seen[currency] = true
                    table.insert(currencyChoices, currency)
                end
            end
        end
    end

    ---------------------------------------------------------------
    -- Which coin the server is paying out.
    ---------------------------------------------------------------

    local function familyFromWorkspace(): string?
        local ok: boolean, value: any = pcall(function(): any
            return workspace:GetAttribute("CurrentEvent")
        end)
        local eventName: string = ok and lower(tostring(value or "")) or ""
        if contains(eventName, "halloween") then
            return "Candy"
        elseif contains(eventName, "christmas") then
            return "SnowToken"
        elseif contains(eventName, "summer") then
            return "BeachBall"
        elseif contains(eventName, "easter") then
            return "Egg"
        elseif contains(eventName, "valentine") then
            return "Heart"
        end
        for attribute: string, family: string in pairs({
            isValentines = "Heart",
            isChristmas = "SnowToken",
            isChristmasEnding = "SnowToken",
            IsSummer = "BeachBall",
            IsEaster = "Egg",
        }) do
            local okAttr: boolean, flag: any = pcall(function(): any
                return workspace:GetAttribute(attribute)
            end)
            if okAttr and flag == true then
                return family
            end
        end
        return nil
    end

    local function activeFamily(): string?
        return serverFamily or familyFromWorkspace()
    end

    local function readSyncDatabase(): any
        local replicated: Instance = game:GetService("ReplicatedStorage")
        local database: Instance? = replicated:FindFirstChild("Database")
        return safeRequire(database and database:FindFirstChild("Sync"))
    end

    local function readProfileData(): any
        local replicated: Instance = game:GetService("ReplicatedStorage")
        local modules: Instance? = replicated:FindFirstChild("Modules")
        return safeRequire(modules and modules:FindFirstChild("ProfileData"))
    end

    -- Read the player's real balance for `currency` from MM2's ProfileData
    -- module when available in the live game. Returns nil only when
    -- ProfileData is not present (e.g. offline test harness).
    local function getPlayerCurrencyBalance(currency: string): number?
        if currency == "Robux" then
            return nil
        end
        local profile: any = readProfileData()
        if type(profile) ~= "table" then
            return nil
        end
        local direct: any = profile[currency]
        if type(direct) == "number" then
            return direct
        end
        local materials: any = profile.Materials
        if type(materials) == "table" and type(materials.Owned) == "table" then
            local matOwned: any = materials.Owned[currency]
            if type(matOwned) == "number" then
                return matOwned
            end
        end
        local weapons: any = profile.Weapons
        if type(weapons) == "table" and type(weapons.Owned) == "table" then
            local wepOwned: any = weapons.Owned[currency]
            if type(wepOwned) == "number" then
                return wepOwned
            end
        end
        if type(profile.Coins) == "number"
            or type(profile.Gems) == "number"
            or type(materials) == "table"
            or type(weapons) == "table" then
            return 0
        end
        return nil
    end

    local function canAffordCurrency(entry: BoxEntry, currency: string): boolean
        local price: number? = entry.prices and entry.prices[currency] or nil
        if type(price) ~= "number" or price <= 0 then
            return true
        end
        local balance: number? = getPlayerCurrencyBalance(currency)
        if balance == nil then
            return true
        end
        return balance >= price
    end

    -- Auto: pay with the currency the active coin family fills, then Coins
    -- and Gems, then the box's event currency, and only then a key. When
    -- ProfileData is loaded, prefer a currency the player can actually afford.
    local function autoCurrency(entry: BoxEntry): string?
        local prices: {[string]: number} = entry.prices or {}
        local orderedCandidates: {string} = {}
        local seenCandidate: {[string]: boolean} = {}
        local function pushCandidate(c: string): ()
            if prices[c] and not seenCandidate[c] then
                seenCandidate[c] = true
                table.insert(orderedCandidates, c)
            end
        end
        local family: string? = activeFamily()
        if family then
            for _, currency: string in ipairs(FAMILY_CURRENCIES[family] or {}) do
                pushCandidate(currency)
            end
        end
        for _, currency: string in ipairs({"Coins", "Gems"}) do
            pushCandidate(currency)
        end
        for _, currency: string in ipairs(sortedKeys(prices)) do
            if not contains(lower(currency), "key") then
                pushCandidate(currency)
            end
        end
        for _, currency: string in ipairs(sortedKeys(prices)) do
            pushCandidate(currency)
        end
        for _, currency: string in ipairs(orderedCandidates) do
            if canAffordCurrency(entry, currency) then
                return currency
            end
        end
        return orderedCandidates[1]
    end

    local function resolveCurrency(entry: BoxEntry): (string?, boolean)
        if settings.currency ~= AUTO_CURRENCY then
            if entry.prices and entry.prices[settings.currency] then
                return settings.currency, false
            end
            -- The chosen currency does not open this box; fall back rather
            -- than fire a request the server has to reject.
            return autoCurrency(entry), true
        end
        return autoCurrency(entry), false
    end

    ---------------------------------------------------------------
    -- Opening: the shop's own remote, then the shop's own reveal.
    ---------------------------------------------------------------

    local function shopRemotes(): Instance?
        local replicated: Instance = game:GetService("ReplicatedStorage")
        local remotes: Instance? = replicated:FindFirstChild("Remotes")
        return remotes and remotes:FindFirstChild("Shop") or nil
    end

    local function report(text: string): ()
        local card: any = state.mm2AutoUnboxFeature
        if card then
            card:SetStatus(text)
        end
    end

    local function summary(): string
        local entry: BoxEntry? = currentEntry()
        local currency: string? = entry and resolveCurrency(entry) or nil
        local text: string = (entry and entry.name or "no box")
            .. " · pay " .. (currency or "nothing")
        local family: string? = activeFamily()
        if family then
            text ..= " · server coin: " .. family
        end
        if session.opened > 0 or session.failures > 0 then
            text ..= " · " .. tostring(session.opened) .. " opened"
            if session.failures > 0 then
                text ..= " · " .. tostring(session.failures) .. " failed"
            end
        end
        if session.finished then
            text ..= " · done"
        end
        return text
    end

    -- A universal card has no :Toggle (that belongs to framework modules); it
    -- switches off through its own onToggle plus the shared repaint.
    local function turnCardOff(): ()
        local card: any = state.mm2AutoUnboxFeature
        if not card then
            return
        end
        card.enabled = false
        pcall(function(): ()
            card.onToggle(false)
        end)
        if type(refreshFeatureToggle) == "function" then
            pcall(refreshFeatureToggle, card)
        end
    end

    local function stop(reason: string?): ()
        disconnectFeatureConnection("MM2AutoUnbox")
        if reason then
            notify(reason)
        end
        turnCardOff()
    end

    -- Opening state that deliberately survives toggles. The tick runs every
    -- frame and InvokeServer yields, so without a hard busy flag the next
    -- tick (or a spam of off/on) fires a second OpenCrate while the first
    -- reveal is still on screen; stacked BoxController reveals are the grey
    -- screen that never clears. One opening at a time, and a reveal owns
    -- the screen until its window ends -- toggling cannot bypass either.
    local openingBusy: boolean = false
    local revealUntil: number = 0
    local REVEAL_SECONDS: number = 5

    -- Clean up any stuck MysteryBoxOpen / Unboxing2 dark overlay ScreenGui
    -- left behind in PlayerGui if MM2's MysteryBoxService errored mid-tween.
    local function clearStuckUnboxOverlays(): ()
        pcall(function(): ()
            local playerGui: Instance? = LocalPlayer
                and LocalPlayer:FindFirstChildOfClass("PlayerGui")
            if not playerGui then
                return
            end
            for _, gui: Instance in ipairs(playerGui:GetChildren()) do
                if gui.Name == "MysteryBoxOpen" or gui.Name == "Unboxing2" then
                    gui:Destroy()
                elseif gui.Name == "MainGUI" then
                    for _, subName: string in ipairs({"Lobby", "Game"}) do
                        local sub: Instance? = gui:FindFirstChild(subName)
                        local proc: Instance? = sub and sub:FindFirstChild("Processing")
                        if proc and proc:IsA("GuiObject") then
                            (proc :: GuiObject).Visible = false
                        end
                    end
                end
            end
        end)
    end

    local function isValidReward(reward: any, category: string): boolean
        if type(reward) ~= "string" or reward == "" or reward == "false" or reward == "nil" then
            return false
        end
        local sync: any = readSyncDatabase()
        if type(sync) == "table" then
            if category == "Eggs" then
                local pets: any = sync.Pets
                if type(pets) == "table" and next(pets) ~= nil then
                    return pets[reward] ~= nil
                end
            else
                local weapons: any = sync.Weapons
                local items: any = sync.Item
                if type(weapons) == "table" and next(weapons) ~= nil then
                    if weapons[reward] ~= nil then
                        return true
                    end
                    if type(items) == "table" and items[reward] ~= nil then
                        return true
                    end
                    return false
                end
            end
        end
        return true
    end

    -- MysteryBoxService:PlayOpeningAnimation indexes Sync.MysteryBox[boxId]
    -- and Sync.Weapons[reward] AFTER parenting the dark MysteryBoxOpen GUI
    -- to PlayerGui. If an event box is not in Sync.MysteryBox (or reward is
    -- not in Sync.Weapons), PlayOpeningAnimation crashes mid-function and
    -- leaves the dark overlay stuck forever. Check before firing BoxController.
    local function canPlayBoxAnimationSafely(boxId: string, reward: string): boolean
        local sync: any = readSyncDatabase()
        if type(sync) ~= "table" then
            return true
        end
        local weapons: any = sync.Weapons
        if type(weapons) ~= "table" or next(weapons) == nil then
            return true
        end
        if type(weapons[reward]) ~= "table" then
            return false
        end
        local mysteryBoxes: any = sync.MysteryBox
        if type(mysteryBoxes) == "table" and next(mysteryBoxes) ~= nil then
            local boxDef: any = mysteryBoxes[boxId]
            if type(boxDef) ~= "table" or type(boxDef.Contents) ~= "table" then
                return false
            end
        end
        return true
    end

    local function reveal(boxId: string, category: string, reward: any): ()
        local remotes: Instance? = shopRemotes()
        if not remotes then
            return
        end
        if settings.reveal == REVEAL_ON then
            -- The official flow: the game plays the reveal and reports the
            -- crate as complete (the BoxController LocalScript does both).
            if category == "Eggs" then
                revealUntil = os.clock() + REVEAL_SECONDS
                local eggController: Instance? = remotes:FindFirstChild("EggController")
                if eggController then
                    pcall(function(): ()
                        (eggController :: any):Fire(boxId, reward)
                    end)
                end
                return
            elseif canPlayBoxAnimationSafely(boxId, tostring(reward)) then
                revealUntil = os.clock() + REVEAL_SECONDS
                local boxController: Instance? = remotes:FindFirstChild("BoxController")
                if boxController then
                    pcall(function(): ()
                        (boxController :: any):Fire({{MysteryBoxId = boxId, RewardedItemId = reward}})
                    end)
                end
                return
            end
        end
        -- No animation (or event box missing from Sync.MysteryBox which would
        -- crash MysteryBoxService and leave a dark screen): still report the
        -- crate so the server and inventory register the unboxed item cleanly.
        local crateComplete: Instance? = remotes:FindFirstChild("CrateComplete")
        if crateComplete then
            pcall(function(): ()
                (crateComplete :: any):FireServer(reward)
            end)
        end
    end

    local function openOnce(): boolean
        if openingBusy then
            return false
        end
        openingBusy = true
        local entry: BoxEntry? = currentEntry()
        if not entry then
            session.finished = true
            openingBusy = false
            stop("Auto Unbox: no box catalogue found.")
            return false
        end
        local currency: string?, forced: boolean = resolveCurrency(entry)
        if not currency then
            session.finished = true
            openingBusy = false
            stop("Auto Unbox: " .. entry.name .. " has no known price currency.")
            return false
        end
        -- Verify the player actually has enough currency BEFORE calling
        -- OpenCrate or playing any reveal animation. If insufficient, do
        -- nothing and stay enabled waiting for currency while farming.
        local requiredPrice: number? = entry.prices and entry.prices[currency] or nil
        local currentBalance: number? = getPlayerCurrencyBalance(currency)
        if type(requiredPrice) == "number"
            and requiredPrice > 0
            and type(currentBalance) == "number"
            and currentBalance < requiredPrice then
            clearStuckUnboxOverlays()
            openingBusy = false
            report(
                summary()
                    .. " · waiting for "
                    .. tostring(currency)
                    .. " ("
                    .. tostring(currentBalance)
                    .. "/"
                    .. tostring(requiredPrice)
                    .. ")"
            )
            return false
        end
        local remotes: Instance? = shopRemotes()
        local openCrate: Instance? = remotes and remotes:FindFirstChild("OpenCrate")
        if not (openCrate and openCrate:IsA("RemoteFunction")) then
            openingBusy = false
            report(summary() .. " · waiting for shop")
            return false
        end
        local note: string = forced
            and (" · " .. settings.currency .. " rejected, using " .. currency)
            or ""
        local ok: boolean, reward: any = pcall(function(): any
            return (openCrate :: any):InvokeServer(entry.id, entry.category, currency)
        end)
        if ok and isValidReward(reward, entry.category) then
            reveal(entry.id, entry.category, reward)
            session.opened += 1
            session.consecutiveFailures = 0
            report(summary() .. note)
            openingBusy = false
            return true
        end
        -- Not enough currency or server rejected the open: do nothing, do not
        -- play any reveal animation, and keep Auto Unbox active so it
        -- automatically opens boxes as soon as farming collects enough coins.
        clearStuckUnboxOverlays()
        session.failures += 1
        session.consecutiveFailures += 1
        report(summary() .. note .. " · waiting for " .. tostring(currency))
        openingBusy = false
        return false
    end

    local function tick(_deltaTime: number): ()
        local now: number = os.clock()
        if now < session.nextAt or now < revealUntil or openingBusy then
            return
        end
        local opened: boolean = openOnce()
        -- Extra settle time while the reveal plays: firing the next
        -- BoxController animation over a running one can leave the screen
        -- black, so a revealed box always gets a longer breather. When no
        -- box was opened (waiting for coins), check again after delay.
        local settle: number = (opened and settings.reveal == REVEAL_ON)
            and REVEAL_SECONDS or 0
        session.nextAt = os.clock() + settings.delay + settle
    end

    local AutoUnboxFeature: any = createUniversalFeature(
        "Auto Unbox",
        "Opens any mystery box or egg of the game through its own OpenCrate remote, paying with the currency you choose or the coin the server is giving.",
        4,
        function(enabled: boolean): ()
            disconnectFeatureConnection("MM2AutoUnbox")
            if os.clock() >= revealUntil then
                clearStuckUnboxOverlays()
            end
            if not enabled then
                return
            end
            session.opened = 0
            session.failures = 0
            session.consecutiveFailures = 0
            -- Never sooner than a reveal still on screen: re-enabling in
            -- the middle of one must not stack a second BoxController.
            session.nextAt = math.max(os.clock(), revealUntil)
            session.finished = false
            report(summary())
            featureConnections.MM2AutoUnbox = TaskManager:Connect(tick)
        end,
        {
            categoryName = "Utilities",
            parent = MM2Scroll,
            registry = mm2Features,
        }
    )
    state.mm2AutoUnboxFeature = AutoUnboxFeature

    -- The server names the coin family this round pays out; Auto uses it to
    -- pick the currency.
    local startedRemote: Instance? = core.mm2GameplayRemotes
        and core.mm2GameplayRemotes:FindFirstChild("CoinsStarted")
    if startedRemote and startedRemote:IsA("RemoteEvent") then
        featureConnections.MM2AutoUnboxCoinsStarted =
            (startedRemote :: any).OnClientEvent:Connect(function(bagTable: any): ()
                if type(bagTable) == "table" then
                    for bag: any in pairs(bagTable) do
                        local family: string? = BAG_TO_FAMILY[tostring(bag)]
                        if family then
                            serverFamily = family
                        end
                    end
                end
                if state.mm2AutoUnboxFeature then
                    report(summary())
                end
            end)
    end

    local defaultBoxIndex: number = table.find(boxLabels, DEFAULT_BOX_LABEL) or 1
    addCycleOption(
        AutoUnboxFeature,
        "Box to open",
        boxLabels,
        defaultBoxIndex,
        function(value: string): ()
            settings.boxLabel = value
        end,
        "Every box and egg of the game, including the event boxes."
    )
    addCycleOption(
        AutoUnboxFeature,
        "Pay with",
        currencyChoices,
        1,
        function(value: string): ()
            settings.currency = value
        end,
        "Auto pays with the currency the server's current coin fills."
    )
    addCycleOption(
        AutoUnboxFeature,
        "Reveal animation",
        {REVEAL_ON, REVEAL_OFF},
        1,
        function(value: string): ()
            settings.reveal = value
        end,
        "On replays the game's own opening animation and crate report."
    )
    addNumberOption(
        AutoUnboxFeature,
        "Delay between boxes",
        settings.delay,
        0.8,
        5,
        function(value: number): ()
            settings.delay = value
        end
    )
    addNumberOption(
        AutoUnboxFeature,
        "Max boxes per run",
        settings.maxBoxes,
        1,
        50,
        function(value: number): ()
            settings.maxBoxes = value
        end
    )
    addActionOption(
        AutoUnboxFeature,
        "Report boxes and coin",
        function(): ()
            local entry: BoxEntry? = currentEntry()
            local prices: {string} = {}
            if entry then
                for _, currency: string in ipairs(sortedKeys(entry.prices)) do
                    table.insert(prices, currency .. "=" .. tostring(entry.prices[currency]))
                end
            end
            notify(
                "Boxes found: " .. tostring(#catalog)
                    .. " · chosen: " .. (entry and entry.name or "none")
                    .. " (" .. (entry and entry.id or "?") .. ")"
                    .. " · price: " .. (#prices > 0 and table.concat(prices, ", ") or "unknown")
                    .. " · server coin: " .. tostring(activeFamily() or "unknown")
            )
        end
    )
    addInformationOption(
        AutoUnboxFeature,
        "Uses the shop's own OpenCrate remote with the box id and currency the game expects, then the game's own reveal. Robux prompts are never pressed."
    )

    activeCleanup = function(): ()
        state.mm2AutoUnboxFeature = nil
        disconnectFeatureConnection("MM2AutoUnbox")
        disconnectFeatureConnection("MM2AutoUnboxCoinsStarted")
    end
    Module.Events = featureConnections
    Module.Initialized = true
    return Module
end

function Module.destroy(): ()
    if not Module.Initialized then
        return
    end
    Module.Initialized = false
    pcall(activeCleanup)
    activeCleanup = function(): ()
    end
    Module.Events = {}
    Module.Runtime = nil
end

return Module

]=],
        ["src/games/MM2/Other/AutoVote.lua"] = [[
local Module = {
    Name = "MM2 Auto Vote",
    Events = {} :: {[string]: any},
    Initialized = false,
    Runtime = nil :: any,
}

local activeCleanup: () -> () = function(): () end

function Module.init(runtime: any): any
    if Module.Initialized then
        return Module
    end
    local core: any = state.mm2Core
    assert(type(core) == "table", "MM2 Auto Vote requires the MM2 core module")
    Module.Runtime = runtime

    local TICK_INTERVAL: number = 0.10
    local MAP_REFRESH_INTERVAL: number = 0.50
    local VOTE_HOLD_BEFORE_RESET: number = 0.22
    local RESET_RETRY_INTERVAL: number = 0.25
    local MAX_LOBBY_PAD_DISTANCE: number = 250

    local DEFAULT_MAP_CHOICES: {string} = {
        "House 2",
        "Hospital 3",
        "Police Station",
    }
    local mapChoices: {string} = {
        DEFAULT_MAP_CHOICES[1],
        DEFAULT_MAP_CHOICES[2],
        DEFAULT_MAP_CHOICES[3],
    }
    local selectedSlot: number = 1
    local selectedMapName: string = mapChoices[1]
    local selectMapButton: TextButton? = nil
    local selectMapOptionKey: string = "MM2.AutoVote.SelectMap"
    local AutoVoteFeature: any = nil

    local cachedLobby: Instance? = nil
    local cachedPadModels: {[number]: Instance?} = {}
    local cachedVotePadsFolder: Instance? = nil
    local cachedVoteIconsFolder: Instance? = nil
    local lastLobbyCheckAt: number = -math.huge
    local lastMapRefreshAt: number = -math.huge
    local savedDetectorCFrames: {[BasePart]: CFrame} = {}
    local roundBlockingVote: boolean = false
    local lastBillboardVotingState: boolean = false

    local function trim(s: string): string
        return (string.gsub(s, "^%s*(.-)%s*$", "%1"))
    end

    local function isPlaceholderMapLabel(title: string?): boolean
        if type(title) ~= "string" then
            return true
        end
        local clean: string = string.upper(trim(title))
        return clean == ""
            or clean == "MAP NAME"
            or clean == "LOADING"
            or clean == "NONE"
            or clean == "MAP 1"
            or clean == "MAP 2"
            or clean == "MAP 3"
    end

    local function isValidMapTitle(title: string?): boolean
        return not isPlaceholderMapLabel(title)
    end

    local function isLobbyContainer(candidate: Instance?): boolean
        if not candidate or not candidate.Parent then
            return false
        end
        return candidate:FindFirstChild("VotePad1") ~= nil
            or candidate:FindFirstChild("VotePads") ~= nil
            or candidate:FindFirstChild("VoteIcons") ~= nil
    end

    local function findLobbyModel(): Instance?
        local now: number = os.clock()
        if cachedLobby and cachedLobby:IsDescendantOf(workspace) and now - lastLobbyCheckAt < 1.0 then
            return cachedLobby
        end
        lastLobbyCheckAt = now

        -- 1. Fast check on direct workspace children
        for _, name: string in ipairs({"RegularLobby", "Lobby", "MainLobby", "HalloweenLobby"}) do
            local candidate: Instance? = workspace:FindFirstChild(name)
            if isLobbyContainer(candidate) then
                cachedLobby = candidate
                return candidate
            end
        end

        local okChildren: boolean, children: any = pcall(function(): any
            return workspace:GetChildren()
        end)
        if okChildren and type(children) == "table" then
            for _, child: Instance in ipairs(children) do
                if (child:IsA("Model") or child:IsA("Folder")) and isLobbyContainer(child) then
                    cachedLobby = child
                    return child
                end
            end
        end

        -- 2. Check CollectionService "VotePad" tag (used on VotePad1..3 in MM2)
        local okTagged: boolean, tagged: any = pcall(function(): any
            return game:GetService("CollectionService"):GetTagged("VotePad")
        end)
        if okTagged and type(tagged) == "table" then
            for _, inst: Instance in ipairs(tagged) do
                if inst and inst:IsDescendantOf(workspace) then
                    local slotNum: number? = tonumber(string.match(inst.Name, "^VotePad(%d)$"))
                    if slotNum then
                        cachedPadModels[slotNum] = inst
                    end
                    if inst.Parent and inst.Parent ~= workspace then
                        cachedLobby = inst.Parent
                    end
                end
            end
            if cachedLobby and cachedLobby:IsDescendantOf(workspace) then
                return cachedLobby
            end
        end

        -- 3. Recursive fallback for nested seasonal/event lobbies
        local okDeep: boolean, deepPad: any = pcall(function(): any
            return workspace:FindFirstChild("VotePads", true)
                or workspace:FindFirstChild("VotePad1", true)
                or workspace:FindFirstChild("VoteIcons", true)
        end)
        if okDeep and deepPad and (deepPad :: Instance):IsDescendantOf(workspace) then
            local parent: Instance? = (deepPad :: Instance).Parent
            if parent and parent.Name == "VoteIcons" and parent.Parent then
                parent = parent.Parent
            end
            cachedLobby = parent
            return cachedLobby
        end

        cachedLobby = nil
        return nil
    end

    local function getPadModel(lobby: Instance?, slot: number): Instance?
        local cached: Instance? = cachedPadModels[slot]
        if cached and cached:IsDescendantOf(workspace) and not (cached.Parent and cached.Parent.Name == "VoteIcons") then
            return cached
        end
        local padName: string = "VotePad" .. tostring(slot)
        if lobby then
            local direct: Instance? = lobby:FindFirstChild(padName)
            if direct and not (direct.Parent and direct.Parent.Name == "VoteIcons") then
                cachedPadModels[slot] = direct
                return direct
            end
            local okDeep: boolean, deep: any = pcall(function(): any
                return lobby:FindFirstChild(padName, true)
            end)
            if okDeep and deep and not ((deep :: Instance).Parent and (deep :: Instance).Parent.Name == "VoteIcons") then
                cachedPadModels[slot] = deep :: Instance
                return deep :: Instance
            end
        end
        return nil
    end

    local function getVoteIconsFolder(lobby: Instance?): Instance?
        if cachedVoteIconsFolder and cachedVoteIconsFolder:IsDescendantOf(workspace) then
            return cachedVoteIconsFolder
        end
        if lobby then
            local direct: Instance? = lobby:FindFirstChild("VoteIcons")
                or lobby:FindFirstChild("VoteIcons", true)
            if direct then
                cachedVoteIconsFolder = direct
                return direct
            end
        end
        return nil
    end

    local function getVotePadsFolder(lobby: Instance?): Instance?
        if cachedVotePadsFolder and cachedVotePadsFolder:IsDescendantOf(workspace) then
            return cachedVotePadsFolder
        end
        if lobby then
            local direct: Instance? = lobby:FindFirstChild("VotePads")
                or lobby:FindFirstChild("VotePads", true)
            if direct then
                cachedVotePadsFolder = direct
                return direct
            end
        end
        return nil
    end

    -- Read the map name displayed on billboard slot i (1..3) from the lobby.
    local function readSlotMapName(lobby: Instance?, slot: number): string?
        if not lobby then
            return nil
        end
        local padModel: Instance? = getPadModel(lobby, slot)
        if padModel then
            local voteInfoGui: Instance? = padModel:FindFirstChild("VoteInfoGui")
            local container: Instance? = voteInfoGui and voteInfoGui:FindFirstChild("Container")
            local mapLabel: Instance? = (container and container:FindFirstChild("MapName"))
                or padModel:FindFirstChild("MapName", true)
            if mapLabel and mapLabel:IsA("TextLabel") then
                local text: string = (mapLabel :: TextLabel).Text
                if isValidMapTitle(text) then
                    return trim(text)
                end
            end
        end

        local voteIcons: Instance? = getVoteIconsFolder(lobby)
        local iconPart: Instance? = voteIcons and voteIcons:FindFirstChild("VotePad" .. tostring(slot))
        if iconPart then
            local mapLabel: Instance? = iconPart:FindFirstChild("MapName", true)
            if mapLabel and mapLabel:IsA("TextLabel") then
                local text: string = (mapLabel :: TextLabel).Text
                if isValidMapTitle(text) then
                    return trim(text)
                end
            end
            local mapObj: Instance? = iconPart:FindFirstChild("Map")
            if mapObj and mapObj:IsA("ObjectValue") then
                local val: Instance? = (mapObj :: ObjectValue).Value
                if val and isValidMapTitle(val.Name) then
                    return trim(val.Name)
                end
            end
        end

        return nil
    end

    -- Read the current vote count on slot i (1..3).
    local function readSlotVoteCount(lobby: Instance?, slot: number): number?
        if not lobby then
            return nil
        end
        local voteIcons: Instance? = getVoteIconsFolder(lobby)
        local iconPart: Instance? = voteIcons and voteIcons:FindFirstChild("VotePad" .. tostring(slot))
        if iconPart then
            local votesVal: Instance? = iconPart:FindFirstChild("Votes")
            if votesVal and votesVal:IsA("IntValue") then
                return (votesVal :: IntValue).Value
            end
        end
        local padModel: Instance? = getPadModel(lobby, slot)
        if padModel then
            local voteInfoGui: Instance? = padModel:FindFirstChild("VoteInfoGui")
            local container: Instance? = voteInfoGui and voteInfoGui:FindFirstChild("Container")
            local votesLabel: Instance? = (container and container:FindFirstChild("Votes"))
                or padModel:FindFirstChild("Votes", true)
            if votesLabel and votesLabel:IsA("TextLabel") then
                local numStr: string? = string.match((votesLabel :: TextLabel).Text, "(%d+)")
                if numStr then
                    return tonumber(numStr)
                end
            end
        end
        return nil
    end

    local function syncSelectMapControl(): ()
        local control: any = state.valueControls
            and state.valueControls[selectMapOptionKey]
        if type(control) == "table" and type(control.setIndex) == "function" then
            pcall(control.setIndex, selectedSlot)
        elseif selectMapButton then
            pcall(function(): ()
                selectMapButton.Text = mapChoices[selectedSlot]
            end)
        end
    end

    -- Refresh the 3 map choices in-place from the lobby billboard so the
    -- "Select Map" dropdown always displays the 3 real maps on the board.
    local function refreshMapChoices(force: boolean?): ()
        local now: number = os.clock()
        if not force and now - lastMapRefreshAt < MAP_REFRESH_INTERVAL then
            return
        end
        lastMapRefreshAt = now

        local lobby: Instance? = findLobbyModel()
        local changed: boolean = false
        for slot: number = 1, 3 do
            local title: string? = readSlotMapName(lobby, slot)
            local current: string? = mapChoices[slot]
            local nextLabel: string = title
                or (isValidMapTitle(current) and (current :: string) or DEFAULT_MAP_CHOICES[slot])
            if mapChoices[slot] ~= nextLabel then
                mapChoices[slot] = nextLabel
                changed = true
            end
        end

        if isValidMapTitle(selectedMapName) then
            local matchedSlot: number? = nil
            local targetLower: string = string.lower(selectedMapName)
            for slot: number = 1, 3 do
                if string.lower(mapChoices[slot]) == targetLower then
                    matchedSlot = slot
                    break
                end
            end
            if matchedSlot and selectedSlot ~= matchedSlot then
                selectedSlot = matchedSlot
                changed = true
            end
        end

        selectedSlot = math.clamp(selectedSlot, 1, 3)
        selectedMapName = mapChoices[selectedSlot]

        if changed or force then
            syncSelectMapControl()
        end
    end

    -- Resolve the wooden pad detector parts for slot (1..3):
    -- VotePads.Detector{slot} and VotePad{slot}.Pad
    local function getSlotDetectorParts(lobby: Instance?, slot: number): {BasePart}
        local parts: {BasePart} = {}
        if not lobby then
            return parts
        end

        local padModel: Instance? = getPadModel(lobby, slot)
        if padModel then
            local padPart: Instance? = padModel:FindFirstChild("Pad")
                or padModel:FindFirstChild("Pad", true)
            if padPart and padPart:IsA("BasePart") then
                parts[#parts + 1] = padPart :: BasePart
            end
        end

        local votePads: Instance? = getVotePadsFolder(lobby)
        if votePads then
            local detector: Instance? = votePads:FindFirstChild("Detector" .. tostring(slot))
                or votePads:FindFirstChild("Detector" .. tostring(slot), true)
            if detector and detector:IsA("BasePart") then
                parts[#parts + 1] = detector :: BasePart
            end
        end

        return parts
    end

    local function rememberDetectorPart(part: BasePart): ()
        if savedDetectorCFrames[part] then
            return
        end
        local ok: boolean, cf: any = pcall(function(): any
            return part.CFrame
        end)
        if ok and cf then
            savedDetectorCFrames[part] = cf
        end
    end

    local function restoreAllDetectorParts(): ()
        for part, cf in pairs(savedDetectorCFrames) do
            if part and part.Parent then
                pcall(function(): ()
                    part.CFrame = cf
                end)
            end
        end
        table.clear(savedDetectorCFrames)
    end

    -- Check whether the lobby voting billboards are currently enabled.
    local function areVotingBillboardsActive(lobby: Instance?): boolean
        if not lobby then
            return false
        end

        for slot: number = 1, 3 do
            local padModel: Instance? = getPadModel(lobby, slot)
            if padModel then
                local voteGui: Instance? = padModel:FindFirstChild("VoteInfoGui")
                if voteGui and voteGui:IsA("SurfaceGui") and (voteGui :: SurfaceGui).Enabled == true then
                    return true
                end
                local mapGui: Instance? = padModel:FindFirstChild("MapInfoGui")
                if mapGui and mapGui:IsA("SurfaceGui") and (mapGui :: SurfaceGui).Enabled == true then
                    return true
                end
            end

            local voteIcons: Instance? = getVoteIconsFolder(lobby)
            local iconPart: Instance? = voteIcons and voteIcons:FindFirstChild("VotePad" .. tostring(slot))
            if iconPart then
                local votingFlag: Instance? = iconPart:FindFirstChild("Voting")
                if votingFlag and votingFlag:IsA("BoolValue") and (votingFlag :: BoolValue).Value == true then
                    return true
                end
                local surface: Instance? = iconPart:FindFirstChild("Surface")
                if surface and surface:IsA("SurfaceGui") and (surface :: SurfaceGui).Enabled == true then
                    return true
                end
                local mapInfo: Instance? = iconPart:FindFirstChild("MapInfo")
                local infoSurface: Instance? = mapInfo and mapInfo:FindFirstChild("Surface")
                if infoSurface and infoSurface:IsA("SurfaceGui") and (infoSurface :: SurfaceGui).Enabled == true then
                    return true
                end
            end
        end

        return false
    end

    -- Returns true ONLY while the lobby voting intermission is open and the
    -- player is in the lobby. Returns false the instant voting ends or a round starts.
    local function isVotingIntermissionActive(root: BasePart?, detector: BasePart?): boolean
        local lobby: Instance? = findLobbyModel()
        if not lobby then
            return false
        end

        local billboardsOn: boolean = areVotingBillboardsActive(lobby)

        -- If the voting billboards just turned on for a new intermission, clear
        -- any previous round lock. If they were on and just turned off, lock until
        -- the next intermission.
        if billboardsOn and not lastBillboardVotingState then
            roundBlockingVote = false
        elseif not billboardsOn and lastBillboardVotingState then
            roundBlockingVote = true
        end
        lastBillboardVotingState = billboardsOn

        if roundBlockingVote then
            return false
        end

        local timerPart: Instance? = workspace:FindFirstChild("RoundTimerPart")
        local timerIndicatesLobby: boolean = false
        if timerPart then
            local okTime: boolean, roundTime: any = pcall(function(): any
                return timerPart:GetAttribute("Time")
            end)
            if okTime and type(roundTime) == "number" then
                if roundTime > 0 then
                    return false
                end
                timerIndicatesLobby = true
            end
        end

        local isNearPad: boolean = false
        if root and detector then
            local okDist: boolean, dist: any = pcall(function(): any
                return (root.Position - detector.Position).Magnitude
            end)
            if okDist and type(dist) == "number" then
                if dist > MAX_LOBBY_PAD_DISTANCE then
                    return false
                end
                isNearPad = true
            end
        end

        if not isNearPad and type(core.isRoundLifecycleActive) == "function"
            and core.isRoundLifecycleActive() == true then
            return false
        end

        if billboardsOn then
            return true
        end

        -- When enabled mid-intermission on servers where SurfaceGui.Enabled is
        -- not replicated, verify the player is in the lobby near the pads (or
        -- RoundTimerPart Time <= 0) and the voting board has map names loaded.
        if isNearPad or timerIndicatesLobby then
            for slot: number = 1, 3 do
                if readSlotMapName(lobby, slot) ~= nil then
                    return true
                end
            end
        end

        return false
    end

    local function resolveTargetSlot(lobby: Instance?): number
        refreshMapChoices(false)
        if lobby and isValidMapTitle(selectedMapName) then
            local targetLower: string = string.lower(selectedMapName)
            for slot: number = 1, 3 do
                local nameOnBoard: string? = readSlotMapName(lobby, slot)
                if nameOnBoard and string.lower(nameOnBoard) == targetLower then
                    selectedSlot = slot
                    return slot
                end
            end
        end
        return math.clamp(selectedSlot, 1, 3)
    end

    -- Step onto the wooden vote pad and pulse touch on its detectors so the
    -- server registers the vote on VotePads.Detector{slot} and VotePad{slot}.Pad.
    local function pulseVotePad(root: BasePart, detectors: {BasePart}): ()
        local primaryPad: BasePart? = detectors[1]
        if primaryPad then
            local okPos: boolean, padPos: any = pcall(function(): any
                local saved: CFrame? = savedDetectorCFrames[primaryPad]
                return saved and saved.Position or primaryPad.Position
            end)
            if okPos and typeof(padPos) == "Vector3" then
                pcall(function(): ()
                    local currentCF: CFrame = root.CFrame
                    local rotOnly: CFrame = currentCF - currentCF.Position
                    root.CFrame = CFrame.new(padPos) * rotOnly
                    root.AssemblyLinearVelocity = Vector3.zero
                end)
            end
        end

        local fireTouch: any = state.fireTouchInterest
        local rootCF: CFrame? = root.CFrame
        for _, part: BasePart in ipairs(detectors) do
            rememberDetectorPart(part)
            pcall(function(): ()
                part.CanCollide = false
                if rootCF then
                    part.CFrame = rootCF
                end
            end)
            if type(fireTouch) == "function" then
                pcall(fireTouch, root, part, 0)
                pcall(fireTouch, root, part, 1)
            end
        end
    end

    local function resetLocalCharacter(character: Model, humanoid: Humanoid): ()
        pcall(function(): ()
            humanoid:ChangeState(Enum.HumanoidStateType.Dead)
        end)
        pcall(function(): ()
            humanoid.Health = 0
        end)
        pcall(function(): ()
            if humanoid.Health > 0 then
                character:BreakJoints()
            end
        end)
    end

    local lastStatus: string? = nil
    local function setStatus(text: string?): ()
        if text == lastStatus then
            return
        end
        lastStatus = text
        if AutoVoteFeature then
            AutoVoteFeature:SetStatus(text)
        end
    end

    local function connectGameplayRemotes(): ()
        local okRs: boolean, rs: any = pcall(function(): any
            return game:GetService("ReplicatedStorage")
        end)
        if not okRs or not rs then
            return
        end
        local remotes: Instance? = rs:FindFirstChild("Remotes")
        local gameplay: Instance? = remotes and remotes:FindFirstChild("Gameplay")
        if not gameplay then
            return
        end

        for _, stopName: string in ipairs({
            "LoadingMap",
            "Fade",
            "RoleSelect",
            "ShowRoleSelect",
            "ShowRoleSelectNew",
            "RoundStart",
            "CoinsStarted",
        }) do
            local rem: Instance? = gameplay:FindFirstChild(stopName)
            if rem and rem:IsA("RemoteEvent") then
                local key: string = "MM2AutoVoteStop_" .. stopName
                disconnectFeatureConnection(key)
                featureConnections[key] = (rem :: RemoteEvent).OnClientEvent:Connect(function(): ()
                    roundBlockingVote = true
                    restoreAllDetectorParts()
                end)
            end
        end

        for _, endName: string in ipairs({
            "RoundEndFade",
            "VictoryScreen",
            "GameOver",
        }) do
            local rem: Instance? = gameplay:FindFirstChild(endName)
            if rem and rem:IsA("RemoteEvent") then
                local key: string = "MM2AutoVoteEnd_" .. endName
                disconnectFeatureConnection(key)
                featureConnections[key] = (rem :: RemoteEvent).OnClientEvent:Connect(function(): ()
                    roundBlockingVote = false
                    refreshMapChoices(true)
                end)
            end
        end
    end

    local function disconnectAllAutoVoteConnections(): ()
        disconnectFeatureConnection("MM2AutoVote")
        for key in pairs(featureConnections) do
            if string.sub(key, 1, 11) == "MM2AutoVote" and key ~= "MM2AutoVoteMapSync" then
                disconnectFeatureConnection(key)
            end
        end
    end

    local function toggleAutoVote(enabled: boolean): ()
        disconnectAllAutoVoteConnections()
        restoreAllDetectorParts()

        if not enabled then
            setStatus(nil)
            return
        end

        roundBlockingVote = false
        lastBillboardVotingState = false
        refreshMapChoices(true)
        connectGameplayRemotes()

        local lastTickAt: number = -math.huge
        local currentChar: Model? = nil
        local firstTouchAt: number = 0
        local lastResetAttemptAt: number = 0
        local voteCountBeforeTouch: number? = nil

        local function autoVoteTick(): ()
            local now: number = os.clock()
            if now - lastTickAt < TICK_INTERVAL then
                return
            end
            lastTickAt = now

            refreshMapChoices(false)

            local lobby: Instance? = findLobbyModel()
            local slot: number = resolveTargetSlot(lobby)
            local targetMapLabel: string = mapChoices[slot] or DEFAULT_MAP_CHOICES[slot]
            local detectors: {BasePart} = getSlotDetectorParts(lobby, slot)
            local primaryDetector: BasePart? = detectors[1]

            local character: Model? = LocalPlayer and LocalPlayer.Character
            local root: BasePart? = character
                and (character:FindFirstChild("HumanoidRootPart") :: BasePart?)
            local humanoid: Humanoid? = character
                and (character:FindFirstChildOfClass("Humanoid") :: Humanoid?)

            -- Stop immediately if the voting intermission is not active or has ended!
            if not isVotingIntermissionActive(root, primaryDetector) then
                restoreAllDetectorParts()
                firstTouchAt = 0
                lastResetAttemptAt = 0
                setStatus("Waiting for vote · " .. tostring(targetMapLabel))
                return
            end

            if #detectors == 0 then
                setStatus("No vote pad")
                return
            end

            if not character or not root or not humanoid or humanoid.Health <= 0 then
                restoreAllDetectorParts()
                return
            end

            if character ~= currentChar then
                currentChar = character
                firstTouchAt = 0
                lastResetAttemptAt = 0
                voteCountBeforeTouch = readSlotVoteCount(lobby, slot)
            end

            -- Step onto the wooden vote pad and pulse touch on its detectors
            pulseVotePad(root, detectors)
            if firstTouchAt == 0 then
                firstTouchAt = now
            end

            local currentVotes: number? = readSlotVoteCount(lobby, slot)
            local voteIncremented: boolean = (
                currentVotes ~= nil
                and voteCountBeforeTouch ~= nil
                and currentVotes > voteCountBeforeTouch
            )

            setStatus(
                "Voting " .. targetMapLabel
                .. (currentVotes ~= nil and (" (" .. tostring(currentVotes) .. ")") or "")
            )

            -- Once this character life has cast its vote on the wooden pad,
            -- re-verify voting intermission is STILL active and reset the
            -- character to stack another vote.
            if (voteIncremented or (now - firstTouchAt >= VOTE_HOLD_BEFORE_RESET))
                and (now - lastResetAttemptAt >= RESET_RETRY_INTERVAL) then
                restoreAllDetectorParts()
                if isVotingIntermissionActive(root, primaryDetector) then
                    lastResetAttemptAt = now
                    resetLocalCharacter(character, humanoid)
                end
            end
        end

        featureConnections.MM2AutoVote = TaskManager:Connect(autoVoteTick)
        autoVoteTick()
    end

    -- Clear any legacy "Map 1..3" placeholder saved in config so real map names show.
    pcall(function(): ()
        if type(configData) == "table" and type(configData.values) == "table" then
            local saved: any = configData.values[selectMapOptionKey]
            if isPlaceholderMapLabel(saved) then
                configData.values[selectMapOptionKey] = nil
            end
        end
    end)

    -- Populate initial map names if already in the lobby
    pcall(refreshMapChoices, true)

    AutoVoteFeature = createUniversalFeature(
        "Auto Vote",
        "Detects the 3 maps on the lobby voting billboard, votes on the wooden floor pad for your selected map, and resets repeatedly to stack votes until voting intermission ends.",
        7,
        toggleAutoVote,
        {
            categoryName = "Utilities",
            parent = MM2Scroll,
            registry = mm2Features,
        }
    )
    state.mm2AutoVoteFeature = AutoVoteFeature

    selectMapButton = addCycleOption(
        AutoVoteFeature,
        "Select Map",
        mapChoices,
        1,
        function(value: string): ()
            refreshMapChoices(false)
            selectedMapName = tostring(value)
            for slot: number = 1, 3 do
                if mapChoices[slot] == selectedMapName then
                    selectedSlot = slot
                    break
                end
            end
            if AutoVoteFeature and AutoVoteFeature.enabled then
                setStatus("Voting " .. tostring(mapChoices[selectedSlot] or selectedMapName))
            end
        end,
        "Select which of the 3 lobby billboard maps to vote for."
    )

    -- Refresh the 3 billboard map names right BEFORE the dropdown opens
    -- and keep the label synced with the lobby boards even while Auto Vote is OFF.
    pcall(function(): ()
        local control: any = state.valueControls
            and state.valueControls[selectMapOptionKey]
        if type(control) == "table" then
            control.onBeforeOpen = function(): ()
                refreshMapChoices(true)
            end
        end
    end)

    local lastBgSyncAt: number = -math.huge
    disconnectFeatureConnection("MM2AutoVoteMapSync")
    featureConnections.MM2AutoVoteMapSync = TaskManager:Connect(function(): ()
        local now: number = os.clock()
        if now - lastBgSyncAt < 1.0 then
            return
        end
        lastBgSyncAt = now
        refreshMapChoices(false)
    end)

    activeCleanup = function(): ()
        disconnectFeatureConnection("MM2AutoVoteMapSync")
        toggleAutoVote(false)
    end
    Module.Events = featureConnections
    Module.Initialized = true
    return Module
end

function Module.destroy(): ()
    if not Module.Initialized then
        return
    end
    Module.Initialized = false
    pcall(activeCleanup)
    activeCleanup = function(): () end
    Module.Events = {}
    Module.Runtime = nil
end

return Module

]],
        ["src/games/MM2/Other/AutoWin.lua"] = [[
local Module = {
    Name = "MM2 Auto Win",
    Events = {} :: {[string]: any},
    Initialized = false,
    Runtime = nil :: any,
}

local activeCleanup: () -> () = function(): () end

function Module.init(runtime: any): any
    if Module.Initialized then
        return Module
    end
    local core: any = state.mm2Core
    assert(type(core) == "table", "MM2 Auto Win requires the MM2 core module")
    local prediction: any = state.mm2Prediction
    Module.Runtime = runtime

    local findDroppedGun: any = core.findDroppedGun
    local findMM2Map: any = core.findMM2Map
    local findMurderer: any = core.findMurderer
    local findSheriff: any = core.findSheriff
    local getGunOriginCFrame: any = core.getGunOriginCFrame
    local getPlayerRole: any = core.getPlayerRole
    local getPlayerWeapon: any = core.getPlayerWeapon
    local isPlayerAlive: any = core.isPlayerAlive
    local isProtectedTarget: any = core.isProtectedTarget
    local isRoundLifecycleActive: any = core.isRoundLifecycleActive

    local ABOVE_MAP_OFFSET: number = 120

    local settings = {
        instaKillMurder = true,
        instaKillSheriff = true,
        flingSheriffGetGun = false,
        flingMurderIfDead = false,
    }

    local autoWinActive: boolean = false
    local AutoWinFeature: any = nil
    local lastStatus: string? = nil

    local sheriffWins: number = 0
    local murderWins: number = 0
    local innocentWins: number = 0
    local sheriffWinsStat: any = nil
    local murderWinsStat: any = nil
    local innocentWinsStat: any = nil

    local wasOnMap: boolean = false
    local participatedInRound: boolean = false
    local roundMyRole: string? = nil
    local roundSawMurderer: boolean = false
    local roundCountedWin: boolean = false
    local flungMurderThisDeath: boolean = false
    local flingBusy: boolean = false

    local safeAbovePosition: Vector3? = nil
    local savedCollide: {[Instance]: boolean} = {}
    local savedCustomProps: {[BasePart]: PhysicalProperties?} = {}
    local victimSnapshots: {[BasePart]: {cframe: CFrame, anchored: boolean, canCollide: boolean}} = {}
    local toolConnections: {RBXScriptConnection} = {}
    local flingAngle: number = 0

    local function updateWinOverlay(): ()
        if sheriffWinsStat and type(sheriffWinsStat.set) == "function" then
            sheriffWinsStat.set(tostring(sheriffWins))
        end
        if murderWinsStat and type(murderWinsStat.set) == "function" then
            murderWinsStat.set(tostring(murderWins))
        end
        if innocentWinsStat and type(innocentWinsStat.set) == "function" then
            innocentWinsStat.set(tostring(innocentWins))
        end
    end

    local function awardRoundWin(roleCategory: string?): ()
        if roundCountedWin then
            return
        end
        local cat: string = roleCategory or roundMyRole or "Innocent"
        roundCountedWin = true
        if cat == "Murderer" then
            murderWins += 1
        elseif cat == "Sheriff" or cat == "Hero" then
            sheriffWins += 1
        else
            innocentWins += 1
        end
        updateWinOverlay()
    end

    local function setStatus(text: string?): ()
        if text == lastStatus then
            return
        end
        lastStatus = text
        if AutoWinFeature then
            AutoWinFeature:SetStatus(text)
        end
    end

    local function yawOf(frame: CFrame): number
        local look: Vector3 = frame.LookVector
        return math.atan2(-look.X, -look.Z)
    end

    local function characterParts(): (Model?, Humanoid?, BasePart?)
        local character: Model? = LocalPlayer and LocalPlayer.Character
        if not character then
            return nil, nil, nil
        end
        local humanoid: Humanoid? = character:FindFirstChildOfClass("Humanoid")
        local root: BasePart? = character:FindFirstChild("HumanoidRootPart") :: BasePart?
        if not humanoid or not root then
            return nil, nil, nil
        end
        return character, humanoid, root
    end

    local function findLobbyReferencePart(): BasePart?
        for _, child: Instance in ipairs(workspace:GetChildren()) do
            local lowerName: string = string.lower(tostring(child.Name))
            local isLobby: boolean = string.find(lowerName, "lobby", 1, true) ~= nil
                or child:FindFirstChild("VotePads", true) ~= nil
                or child:FindFirstChild("VotePad1", true) ~= nil
                or child:FindFirstChild("VoteIcons", true) ~= nil
            if isLobby then
                local votePads: Instance? = child:FindFirstChild("VotePads", true)
                if votePads then
                    local padPart: BasePart? = votePads:FindFirstChildWhichIsA("BasePart", true)
                    if padPart then
                        return padPart
                    end
                end
                local spawns: Instance? = child:FindFirstChild("Spawns", true)
                if spawns then
                    local spawnPart: BasePart? = spawns:FindFirstChildWhichIsA("BasePart", true)
                    if spawnPart then
                        return spawnPart
                    end
                end
                local anyPart: BasePart? = child:FindFirstChildWhichIsA("BasePart", true)
                if anyPart then
                    return anyPart
                end
            end
        end
        return nil
    end

    -- True as soon as the player's character is on the MM2 map, even during
    -- the pre-round countdown before roles or weapons have been handed out.
    local function isCharacterOnMap(root: BasePart): (boolean, Vector3?)
        if type(findMM2Map) ~= "function" then
            return false, nil
        end
        local map: Instance? = findMM2Map()
        if not map then
            return false, nil
        end
        local okRoot: boolean, rootPos: any = pcall(function(): any
            return root.Position
        end)
        if not okRoot or typeof(rootPos) ~= "Vector3" then
            return false, nil
        end
        local lobbyPart: BasePart? = findLobbyReferencePart()
        if lobbyPart then
            local okLobbyDist: boolean, lobbyDist: any = pcall(function(): any
                return ((rootPos :: Vector3) - lobbyPart.Position).Magnitude
            end)
            if okLobbyDist and type(lobbyDist) == "number" and lobbyDist <= 350 then
                return false, nil
            end
        end
        local refPart: BasePart? = nil
        local spawns: Instance? = (map :: Instance):FindFirstChild("Spawns")
        if spawns then
            refPart = spawns:FindFirstChildWhichIsA("BasePart", true)
        end
        if not refPart then
            local coinContainer: Instance? = (map :: Instance):FindFirstChild("CoinContainer")
            if coinContainer then
                refPart = coinContainer:FindFirstChildWhichIsA("BasePart", true)
            end
        end
        if not refPart then
            refPart = (map :: Instance):FindFirstChildWhichIsA("BasePart", true)
        end
        if refPart then
            local okMapDist: boolean, mapDist: any = pcall(function(): any
                return ((rootPos :: Vector3) - refPart.Position).Magnitude
            end)
            if okMapDist and type(mapDist) == "number" and mapDist > 1500 then
                return false, nil
            end
            return true, refPart.Position
        end
        return true, rootPos :: Vector3
    end

    local function restoreVictims(): ()
        for part: BasePart, snap in pairs(victimSnapshots) do
            if part and part.Parent then
                pcall(function(): ()
                    part.Anchored = snap.anchored
                    part.CanCollide = snap.canCollide
                    part.CFrame = snap.cframe
                end)
            end
        end
        table.clear(victimSnapshots)
    end

    local function restoreLocalCharacter(): ()
        restoreVictims()
        if services and services.activity then
            pcall(function(): ()
                services.activity.set("fling", false)
            end)
        end
        for part: Instance, wasCollide: boolean in pairs(savedCollide) do
            if part and part.Parent then
                pcall(function(): ()
                    (part :: BasePart).CanCollide = wasCollide
                end)
            end
        end
        table.clear(savedCollide)
        for part: BasePart, oldProps: PhysicalProperties? in pairs(savedCustomProps) do
            if part and part.Parent then
                pcall(function(): ()
                    part.CustomPhysicalProperties = oldProps
                end)
            end
        end
        table.clear(savedCustomProps)

        local character: Model?, humanoid: Humanoid?, root: BasePart? = characterParts()
        if humanoid then
            pcall(function(): ()
                humanoid.PlatformStand = false
                humanoid.AutoRotate = true
                humanoid:SetStateEnabled(Enum.HumanoidStateType.FallingDown, true)
                humanoid:SetStateEnabled(Enum.HumanoidStateType.Seated, true)
                humanoid:ChangeState(Enum.HumanoidStateType.Running)
            end)
        end
        if root then
            pcall(function(): ()
                root.AssemblyLinearVelocity = Vector3.zero
                root.AssemblyAngularVelocity = Vector3.zero
                if safeAbovePosition then
                    local groundPos: Vector3 = safeAbovePosition - Vector3.new(0, ABOVE_MAP_OFFSET - 4, 0)
                    local targetCF: CFrame = CFrame.new(groundPos)
                        * CFrame.Angles(0, yawOf(root.CFrame), 0)
                    if character then
                        pcall(function(): ()
                            character:PivotTo(targetCF)
                        end)
                    end
                    root.CFrame = targetCF
                end
            end)
        end
    end

    local function disableCharacterCollisions(character: Model): ()
        for _, object: Instance in ipairs(character:GetDescendants()) do
            if object:IsA("BasePart") then
                if savedCollide[object] == nil then
                    savedCollide[object] = (object :: BasePart).CanCollide
                end
                pcall(function(): ()
                    (object :: BasePart).CanCollide = false
                end)
            end
        end
    end

    local function enableCharacterFlingCollisions(character: Model): ()
        local heavyProps: PhysicalProperties = PhysicalProperties.new(100, 0.3, 0.5, 1, 1)
        for _, object: Instance in ipairs(character:GetChildren()) do
            if object:IsA("BasePart") then
                local part: BasePart = object :: BasePart
                if savedCollide[part] == nil then
                    savedCollide[part] = part.CanCollide
                end
                if savedCustomProps[part] == nil then
                    pcall(function(): ()
                        savedCustomProps[part] = part.CustomPhysicalProperties
                    end)
                end
                pcall(function(): ()
                    part.CanCollide = true
                    part.CustomPhysicalProperties = heavyProps
                end)
            end
        end
    end

    local function holdAboveMap(
        character: Model,
        humanoid: Humanoid,
        root: BasePart
    ): ()
        if services and services.activity then
            pcall(function(): ()
                services.activity.set("fling", false)
            end)
        end
        disableCharacterCollisions(character)
        local holdPos: Vector3 = safeAbovePosition
            or (root.Position + Vector3.new(0, ABOVE_MAP_OFFSET, 0))
        pcall(function(): ()
            humanoid.PlatformStand = true
            humanoid.AutoRotate = false
            root.AssemblyLinearVelocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
            root.CFrame = CFrame.new(holdPos)
                * CFrame.Angles(0, yawOf(root.CFrame), 0)
        end)
    end

    local function findLocalTool(toolName: string): Tool?
        local character: Model? = LocalPlayer and LocalPlayer.Character
        if type(getPlayerWeapon) == "function" then
            local found: Tool? = getPlayerWeapon(LocalPlayer, toolName, false)
            if found then
                return found
            end
        end
        if character then
            local inChar: Instance? = character:FindFirstChild(toolName)
            if inChar and inChar:IsA("Tool") then
                return inChar
            end
        end
        local backpack: Instance? = LocalPlayer and LocalPlayer:FindFirstChildOfClass("Backpack")
        if backpack then
            local inBp: Instance? = backpack:FindFirstChild(toolName)
            if inBp and inBp:IsA("Tool") then
                return inBp
            end
        end
        return nil
    end

    local function ensureToolEquipped(
        character: Model,
        humanoid: Humanoid,
        tool: Tool
    ): boolean
        if tool.Parent == character then
            return true
        end
        pcall(function(): ()
            humanoid:EquipTool(tool)
        end)
        if tool.Parent ~= character then
            pcall(function(): ()
                tool.Parent = character
            end)
        end
        return tool.Parent == character
    end

    local function findActiveMurderer(): Player?
        local playersService: Players = game:GetService("Players")
        if type(getPlayerWeapon) == "function" then
            for _, player: Player in ipairs(playersService:GetPlayers()) do
                if player ~= LocalPlayer
                    and (type(isPlayerAlive) ~= "function" or isPlayerAlive(player))
                    and getPlayerWeapon(player, "Gun", false) == nil
                    and getPlayerWeapon(player, "Knife", false) ~= nil then
                    return player
                end
            end
        end
        if type(findMurderer) == "function" then
            local target: Player? = findMurderer()
            if target
                and target ~= LocalPlayer
                and (type(isPlayerAlive) ~= "function" or isPlayerAlive(target))
                and (type(getPlayerWeapon) ~= "function"
                    or getPlayerWeapon(target, "Gun", false) == nil) then
                return target
            end
        end
        for _, player: Player in ipairs(playersService:GetPlayers()) do
            if player ~= LocalPlayer
                and (type(isPlayerAlive) ~= "function" or isPlayerAlive(player))
                and (type(getPlayerWeapon) ~= "function"
                    or getPlayerWeapon(player, "Gun", false) == nil) then
                local role: any = type(getPlayerRole) == "function"
                    and getPlayerRole(player)
                    or nil
                if role == "Murderer" then
                    return player
                end
            end
        end
        return nil
    end

    local function findActiveSheriffOrHero(): Player?
        local playersService: Players = game:GetService("Players")
        if type(getPlayerWeapon) == "function" then
            for _, player: Player in ipairs(playersService:GetPlayers()) do
                if player ~= LocalPlayer
                    and (type(isPlayerAlive) ~= "function" or isPlayerAlive(player))
                    and getPlayerWeapon(player, "Knife", false) == nil
                    and getPlayerWeapon(player, "Gun", false) ~= nil then
                    return player
                end
            end
        end
        if type(findSheriff) == "function" then
            local target: Player? = findSheriff()
            if target
                and target ~= LocalPlayer
                and (type(isPlayerAlive) ~= "function" or isPlayerAlive(target))
                and (type(getPlayerWeapon) ~= "function"
                    or getPlayerWeapon(target, "Knife", false) == nil) then
                return target
            end
        end
        return nil
    end

    -- Insta Kill as Murder (Kill All while staying safely above the map).
    local function runInstaKillAsMurder(
        character: Model,
        humanoid: Humanoid,
        root: BasePart,
        knife: Tool
    ): boolean
        holdAboveMap(character, humanoid, root)
        if not ensureToolEquipped(character, humanoid, knife) then
            return false
        end
        local handle: BasePart? = (knife:FindFirstChild("Handle") :: BasePart?)
            or knife:FindFirstChildWhichIsA("BasePart")
        local slashRemote: Instance? = knife:FindFirstChild("Slash")
        local stabRemote: Instance? = knife:FindFirstChild("Stab")
        local eventsFolder: Instance? = knife:FindFirstChild("Events")
        local touchedRemote: Instance? = eventsFolder
            and eventsFolder:FindFirstChild("HandleTouched")

        local attackCF: CFrame = (handle and handle.CFrame)
            or (root.CFrame * CFrame.new(0, 0, -2.5))
        local playersService: Players = game:GetService("Players")
        local hitAny: boolean = false

        for _, player: Player in ipairs(playersService:GetPlayers()) do
            if player ~= LocalPlayer
                and (type(isPlayerAlive) ~= "function" or isPlayerAlive(player))
                and (type(isProtectedTarget) ~= "function" or not isProtectedTarget(player)) then
                local victimChar: Model? = player.Character
                local victimRoot: BasePart? = victimChar
                    and victimChar:FindFirstChild("HumanoidRootPart") :: BasePart?
                if victimChar and victimRoot then
                    local onVictimMap: boolean = isCharacterOnMap(victimRoot)
                    if onVictimMap then
                        hitAny = true
                        if not victimSnapshots[victimRoot] then
                            pcall(function(): ()
                                victimSnapshots[victimRoot] = {
                                    cframe = victimRoot.CFrame,
                                    anchored = victimRoot.Anchored,
                                    canCollide = victimRoot.CanCollide,
                                }
                            end)
                        end
                        pcall(function(): ()
                            victimRoot.Anchored = true
                            victimRoot.CanCollide = false
                            victimRoot.AssemblyLinearVelocity = Vector3.zero
                            victimRoot.AssemblyAngularVelocity = Vector3.zero
                            victimRoot.CFrame = attackCF
                        end)
                        if slashRemote and slashRemote:IsA("RemoteEvent") then
                            pcall(function(): ()
                                (slashRemote :: RemoteEvent):FireServer("Slash")
                            end)
                        end
                        if stabRemote and stabRemote:IsA("RemoteEvent") then
                            pcall(function(): ()
                                (stabRemote :: RemoteEvent):FireServer("Slash")
                            end)
                        end
                        if touchedRemote and touchedRemote:IsA("RemoteEvent") then
                            pcall(function(): ()
                                (touchedRemote :: RemoteEvent):FireServer(victimRoot)
                            end)
                        end
                        if handle and type(state.fireTouchInterest) == "function" then
                            pcall(state.fireTouchInterest, handle, victimRoot, 0)
                            pcall(state.fireTouchInterest, handle, victimRoot, 1)
                        end
                    end
                end
            end
        end
        if not hitAny then
            restoreVictims()
            awardRoundWin("Murderer")
        end
        return hitAny
    end

    -- Insta Kill As Sheriff (uses AutoShoot CFrame immediately upon receiving
    -- the Gun, whether our role is Sheriff, Hero, or Innocent).
    local function runInstaKillAsSheriff(
        character: Model,
        humanoid: Humanoid,
        root: BasePart,
        gun: Tool
    ): boolean
        holdAboveMap(character, humanoid, root)
        if not ensureToolEquipped(character, humanoid, gun) then
            return false
        end
        local murderer: Player? = findActiveMurderer()
        if not murderer then
            if roundSawMurderer then
                awardRoundWin("Sheriff")
            end
            return false
        end
        roundSawMurderer = true
        if type(state.mm2AutoShootCFrameOnce) == "function" then
            local okHelper: boolean, helperRes: any =
                pcall(state.mm2AutoShootCFrameOnce, false)
            if okHelper and helperRes == true then
                return true
            end
        end
        if type(isProtectedTarget) == "function" and isProtectedTarget(murderer) then
            return false
        end
        local targetChar: Model? = murderer.Character
        local targetRoot: BasePart? = targetChar
            and targetChar:FindFirstChild("HumanoidRootPart") :: BasePart?
        if not targetRoot then
            return false
        end
        if type(state.mm2FireSilentShot) == "function" then
            local okSilent: boolean, res: any = pcall(state.mm2FireSilentShot, murderer)
            if okSilent and res == true then
                return true
            end
        end
        local shootRemote: Instance? = gun:FindFirstChild("Shoot")
        if not (shootRemote and shootRemote:IsA("RemoteEvent")) then
            return false
        end
        local originCF: CFrame = (type(getGunOriginCFrame) == "function"
            and getGunOriginCFrame(character, gun))
            or root.CFrame
        local endpoint: Vector3 = targetRoot.Position
        if type(prediction) == "table" and type(prediction.gunAim) == "function" then
            local okAim: boolean, aimPt: any = pcall(
                prediction.gunAim,
                murderer,
                originCF.Position
            )
            if okAim and typeof(aimPt) == "Vector3" then
                endpoint = aimPt
            else
                local vel: Vector3 = Vector3.zero
                pcall(function(): ()
                    vel = targetRoot.AssemblyLinearVelocity
                end)
                endpoint = targetRoot.Position + vel * 0.08
            end
        end
        local startPoint: Vector3 = endpoint + Vector3.new(0, 1.5, -2.5)
        local shotOrigin: CFrame = CFrame.lookAt(startPoint, endpoint)
        local shotEnd: CFrame = CFrame.new(endpoint)
        pcall(function(): ()
            (shootRemote :: RemoteEvent):FireServer(shotOrigin, shotEnd)
        end)
        return true
    end

    -- Grab the dropped gun ONLY via fireTouchInterest while staying safely
    -- above the map (never risking a teleport down to the map).
    local function grabDroppedGunTouchOnly(
        character: Model,
        humanoid: Humanoid,
        root: BasePart,
        drop: Instance
    ): boolean
        holdAboveMap(character, humanoid, root)
        if type(state.fireTouchInterest) ~= "function" then
            return false
        end
        local touchPart: BasePart? = nil
        if drop:IsA("BasePart") then
            touchPart = drop :: BasePart
        elseif drop:IsA("Model") then
            touchPart = (drop:FindFirstChild("Handle", true) :: BasePart?)
                or drop:FindFirstChildWhichIsA("BasePart", true)
        end
        if not touchPart then
            return false
        end
        pcall(state.fireTouchInterest, root, touchPart, 0)
        pcall(state.fireTouchInterest, root, touchPart, 1)
        return findLocalTool("Gun") ~= nil
    end

    -- Reconstructed high-impulse Fling on the Sheriff: forces CanCollide=true
    -- and high density on contact so the Sheriff is actually flung, while
    -- stopping before the void so our character never dies.
    local function flingSheriffStep(
        character: Model,
        humanoid: Humanoid,
        root: BasePart,
        sheriff: Player
    ): boolean
        if type(state.mm2FlingStep) == "function" then
            local okStep: boolean, res: any = pcall(
                state.mm2FlingStep,
                character,
                humanoid,
                root,
                sheriff,
                savedCollide,
                savedCustomProps
            )
            if okStep and res == true then
                return true
            end
            holdAboveMap(character, humanoid, root)
            return false
        end
        local sheriffChar: Model? = sheriff.Character
        local sheriffHum: Humanoid? = sheriffChar
            and sheriffChar:FindFirstChildOfClass("Humanoid")
        local sheriffRoot: BasePart? = sheriffChar
            and sheriffChar:FindFirstChild("HumanoidRootPart") :: BasePart?
        if not sheriffChar or not sheriffHum or sheriffHum.Health <= 0 or not sheriffRoot then
            holdAboveMap(character, humanoid, root)
            return false
        end
        local destroyHeight: number = workspace.FallenPartsDestroyHeight
        if destroyHeight ~= destroyHeight or math.abs(destroyHeight) > 1e6 then
            destroyHeight = -500
        end
        local sheriffPos: Vector3 = sheriffRoot.Position
        if sheriffPos.Y <= destroyHeight + 55 then
            holdAboveMap(character, humanoid, root)
            return false
        end
        if services and services.activity then
            pcall(function(): ()
                services.activity.set("fling", true)
            end)
        end
        enableCharacterFlingCollisions(character)
        flingAngle = (flingAngle + 100) % 360
        local phase: number = math.floor(flingAngle / 100) % 4
        local sweepOffset: CFrame = if phase == 0
            then CFrame.new(0, 1.5, 0)
            elseif phase == 1 then CFrame.new(0, -1.5, 0)
            elseif phase == 2 then CFrame.new(2.0, 1.2, -2.0)
            else CFrame.new(-2.0, -1.2, 2.0)
        local sheriffVel: Vector3 = Vector3.zero
        pcall(function(): ()
            sheriffVel = sheriffRoot.AssemblyLinearVelocity
        end)
        local targetCF: CFrame = CFrame.new(sheriffPos + sheriffVel * 0.08)
            * sweepOffset
            * CFrame.Angles(math.rad(flingAngle), math.rad(flingAngle), 0)
        pcall(function(): ()
            if humanoid.Sit then
                humanoid.Sit = false
            end
            humanoid.AutoRotate = false
            root.CFrame = targetCF
            character:PivotTo(targetCF)
            root.AssemblyLinearVelocity = Vector3.new(9e7, 9e7 * 10, 9e7)
            root.AssemblyAngularVelocity = Vector3.new(9e8, 9e8, 9e8)
        end)
        return true
    end

    local function autoWinTick(): ()
        if not autoWinActive or flingBusy then
            return
        end
        local character: Model?, humanoid: Humanoid?, root: BasePart? = characterParts()
        if not character or not humanoid or not root or humanoid.Health <= 0 then
            return
        end

        local onMap: boolean, mapRefPos: Vector3? = isCharacterOnMap(root)
        local activeMurderer: Player? = findActiveMurderer()
        if activeMurderer then
            roundSawMurderer = true
        end

        if not onMap then
            if wasOnMap then
                wasOnMap = false
                safeAbovePosition = nil
                restoreLocalCharacter()
            end

            local roundStillRunning: boolean = type(findMM2Map) == "function"
                and findMM2Map() ~= nil
                and activeMurderer ~= nil
                and (type(isRoundLifecycleActive) ~= "function"
                    or isRoundLifecycleActive() ~= false)

            if not roundStillRunning then
                if participatedInRound and not roundCountedWin and roundSawMurderer then
                    local myRoleNow: any = type(getPlayerRole) == "function"
                        and getPlayerRole(LocalPlayer)
                        or nil
                    if myRoleNow ~= "Dead" then
                        awardRoundWin(roundMyRole)
                    end
                end
                participatedInRound = false
                roundMyRole = nil
                roundSawMurderer = false
                roundCountedWin = false
                flungMurderThisDeath = false
                setStatus("Auto Win: waiting for map")
                return
            end

            -- We are in the lobby while the round is still running on the map
            -- (meaning we died / were killed during the round).
            local myRole: any = type(getPlayerRole) == "function"
                and getPlayerRole(LocalPlayer)
                or nil
            local diedInRound: boolean = participatedInRound or myRole == "Dead"
            if settings.flingMurderIfDead
                and diedInRound
                and not flungMurderThisDeath
                and activeMurderer then
                flungMurderThisDeath = true
                if type(state.mm2PerformFling) == "function" then
                    flingBusy = true
                    setStatus("Auto Win: Flinging Murderer (killed us)")
                    task.spawn(function(): ()
                        pcall(state.mm2PerformFling, activeMurderer, {
                            silent = true,
                            duration = 5.0,
                            blocking = true,
                        })
                        flingBusy = false
                    end)
                    return
                end
            end

            setStatus("Auto Win: waiting in lobby")
            return
        end

        if not wasOnMap or not safeAbovePosition then
            wasOnMap = true
            participatedInRound = true
            flungMurderThisDeath = false
            local anchor: Vector3 = mapRefPos or root.Position
            safeAbovePosition = anchor + Vector3.new(0, ABOVE_MAP_OFFSET, 0)
        end

        -- Check if the Murderer died while we are alive on the map -> count win!
        if roundSawMurderer and not activeMurderer and not roundCountedWin then
            awardRoundWin(roundMyRole)
        end

        -- 1) Murderer / Knife check: Insta Kill as Murder (Kill All).
        local knife: Tool? = findLocalTool("Knife")
        if knife then
            roundMyRole = "Murderer"
            if settings.instaKillMurder then
                runInstaKillAsMurder(character, humanoid, root, knife)
                setStatus("Auto Win: Insta Kill as Murder")
            else
                holdAboveMap(character, humanoid, root)
                setStatus("Auto Win: safe above map (Murderer)")
            end
            return
        end

        -- 2) Gun check (Sheriff OR Hero OR Innocent who received the Gun!):
        --    Dispara al momento que reciba la pistola con AutoShoot CFrame,
        --    incluso si Fling Sheriff and Get Gun está desactivado y el arma
        --    se recogió con Auto Grab Gun.
        local gun: Tool? = findLocalTool("Gun")
        if gun then
            roundMyRole = "Sheriff"
            if settings.instaKillSheriff then
                runInstaKillAsSheriff(character, humanoid, root, gun)
                setStatus("Auto Win: Insta Kill As Sheriff (CFrame)")
            else
                holdAboveMap(character, humanoid, root)
                setStatus("Auto Win: safe above map (Gun ready)")
            end
            return
        end

        if not roundMyRole then
            local roleNow: any = type(getPlayerRole) == "function"
                and getPlayerRole(LocalPlayer)
                or nil
            if roleNow == "Murderer" then
                roundMyRole = "Murderer"
            elseif roleNow == "Sheriff" or roleNow == "Hero" then
                roundMyRole = "Sheriff"
            else
                roundMyRole = "Innocent"
            end
        end

        -- 3) Dropped gun on the map: grab ONLY via fireTouchInterest (no
        --    risky teleport) if Fling Sheriff and Get Gun is ON or Auto Grab
        --    Gun is enabled.
        local autoGrabExternal: boolean = state.mm2GunAuraEnabled == true
            or state.mm2AutoGetGunEnabled == true
        if settings.flingSheriffGetGun or autoGrabExternal then
            local drop: Instance? = type(findDroppedGun) == "function"
                and findDroppedGun()
                or nil
            if drop then
                local grabbed: boolean = grabDroppedGunTouchOnly(
                    character,
                    humanoid,
                    root,
                    drop
                )
                setStatus("Auto Win: touching dropped gun")
                if grabbed then
                    roundMyRole = "Sheriff"
                    local freshGun: Tool? = findLocalTool("Gun")
                    if freshGun and settings.instaKillSheriff then
                        runInstaKillAsSheriff(character, humanoid, root, freshGun)
                    end
                end
                return
            end
        end

        -- 4) Fling Sheriff and Get Gun while Sheriff is still alive.
        if settings.flingSheriffGetGun then
            local sheriff: Player? = findActiveSheriffOrHero()
            if sheriff
                and sheriff ~= LocalPlayer
                and (type(isProtectedTarget) ~= "function" or not isProtectedTarget(sheriff)) then
                if flingSheriffStep(character, humanoid, root, sheriff) then
                    setStatus("Auto Win: flinging Sheriff for gun")
                    return
                end
            end
        end

        -- 5) Default on map (including pre-round before weapons are given):
        --    Stay safely high above the map where nobody can kill us.
        holdAboveMap(character, humanoid, root)
        setStatus("Auto Win: safe above map")
    end

    local function clearToolConnections(): ()
        for _, conn: RBXScriptConnection in ipairs(toolConnections) do
            pcall(function(): ()
                conn:Disconnect()
            end)
        end
        table.clear(toolConnections)
    end

    local function watchToolContainer(container: Instance?): ()
        if not container
            or (type((container :: any).ChildAdded) ~= "table"
                and typeof((container :: any).ChildAdded) ~= "RBXScriptSignal") then
            return
        end
        pcall(function(): ()
            local conn: RBXScriptConnection = (container :: any).ChildAdded:Connect(
                function(child: Instance): ()
                    if autoWinActive
                        and child
                        and (child.Name == "Gun" or child.Name == "Knife") then
                        autoWinTick()
                    end
                end
            )
            table.insert(toolConnections, conn)
        end)
    end

    local function setupInstantWeaponWatchers(): ()
        clearToolConnections()
        if not LocalPlayer then
            return
        end
        watchToolContainer(LocalPlayer.Character)
        watchToolContainer(LocalPlayer:FindFirstChildOfClass("Backpack"))
        pcall(function(): ()
            if LocalPlayer.CharacterAdded then
                table.insert(
                    toolConnections,
                    LocalPlayer.CharacterAdded:Connect(function(newChar: Model): ()
                        watchToolContainer(newChar)
                        watchToolContainer(LocalPlayer:FindFirstChildOfClass("Backpack"))
                    end)
                )
            end
            if LocalPlayer.ChildAdded then
                table.insert(
                    toolConnections,
                    LocalPlayer.ChildAdded:Connect(function(child: Instance): ()
                        if child and child:IsA("Backpack") then
                            watchToolContainer(child)
                        end
                    end)
                )
            end
        end)
    end

    local function toggleAutoWin(enabled: boolean): ()
        autoWinActive = enabled == true
        disconnectFeatureConnection("MM2AutoWin")
        clearToolConnections()
        if not enabled then
            wasOnMap = false
            participatedInRound = false
            roundMyRole = nil
            roundSawMurderer = false
            roundCountedWin = false
            flungMurderThisDeath = false
            restoreLocalCharacter()
            safeAbovePosition = nil
            setStatus(nil)
            return
        end
        setupInstantWeaponWatchers()
        featureConnections.MM2AutoWin = TaskManager:Connect(autoWinTick)
        autoWinTick()
    end

    AutoWinFeature = createUniversalFeature(
        "Auto Win",
        "Keeps your character safely above the map as soon as you enter the map (even before the round starts) so nobody can kill you, with Insta Kill as Murder, Insta Kill As Sheriff (AutoShoot CFrame), Fling Sheriff and Get Gun, and Fling Murder if Dead.",
        8,
        toggleAutoWin,
        {
            categoryName = "Utilities",
            parent = MM2Scroll,
            registry = mm2Features,
        }
    )
    state.mm2AutoWinFeature = AutoWinFeature

    if type(state.addSectionOption) == "function" then
        state.addSectionOption(AutoWinFeature, "Overlay Info")
    end
    if type(state.addStatOption) == "function" then
        sheriffWinsStat = state.addStatOption(AutoWinFeature, "Sheriff Wins", "0")
        murderWinsStat = state.addStatOption(AutoWinFeature, "Murder Wins", "0")
        innocentWinsStat = state.addStatOption(AutoWinFeature, "Innocent Wins", "0")
    end

    addToggleOption(AutoWinFeature, "Insta Kill as Murder", true,
        function(value: boolean): ()
            settings.instaKillMurder = value == true
        end,
        "Automatically kills all living players as soon as you receive the Knife as Murderer.")

    addToggleOption(AutoWinFeature, "Insta Kill As Sheriff", true,
        function(value: boolean): ()
            settings.instaKillSheriff = value == true
        end,
        "Automatically equips the Gun and shoots the Murderer using AutoShoot CFrame the instant you receive the Gun (as Sheriff or Hero).")

    addToggleOption(AutoWinFeature, "Fling Sheriff and Get Gun", false,
        function(value: boolean): ()
            settings.flingSheriffGetGun = value == true
        end,
        "Safely flies to the Sheriff with Fling without killing yourself, then automatically grabs the dropped gun via TouchInterest once the Sheriff dies and shoots the Murderer.")

    addToggleOption(AutoWinFeature, "Fling Murder if Dead", false,
        function(value: boolean): ()
            settings.flingMurderIfDead = value == true
        end,
        "If the Murderer kills you and sends you to the lobby while the round is still active, automatically flings the Murderer.")

    activeCleanup = function(): ()
        toggleAutoWin(false)
        state.mm2AutoWinFeature = nil
    end
    Module.Events = featureConnections
    Module.Initialized = true
    return Module
end

function Module.destroy(): ()
    if not Module.Initialized then
        return
    end
    Module.Initialized = false
    pcall(activeCleanup)
    activeCleanup = function(): () end
    Module.Events = {}
    Module.Runtime = nil
end

return Module

]],
        ["src/games/MM2/Other/CalibrationTrails.lua"] = [[
local Module = {Name = "MM2 Calibration Trails", Initialized = false}
local activeCleanup = function() end

function Module.init(runtime: any): any
    if Module.Initialized then return Module end
    local core = state.mm2Core
    -- The Calibration card is a debug surface: no card, no trail options.
    if not state.mm2CalibrationFeature then
        Module.Initialized = true
        return Module
    end
    assert(core, "Calibration Trails requires the MM2 core module")
    local options = {trailEsp = false, color = Color3.fromRGB(100, 185, 255)}
    local trailFolder: Folder? = nil
    local connection: any = nil
    local function ensureTrailFolder(): Folder
        if not trailFolder or not trailFolder.Parent then
            trailFolder = Instance.new("Folder")
            trailFolder.Name = "MM2TrailESP"
            trailFolder.Parent = workspace
        end
        -- Bound transient visuals even if many players fire together.
        local children: {Instance} = trailFolder:GetChildren()
        while #children >= 64 do
            children[1]:Destroy()
            table.remove(children, 1)
        end
        return trailFolder :: Folder
    end

    local function clearTrails(): ()
        if trailFolder then
            pcall(function(): () trailFolder:Destroy() end)
            trailFolder = nil
        end
    end

    local function drawShotTrail(origin: Vector3, hit: Vector3, hitPart: any): ()
        local folder: Folder = ensureTrailFolder()
        local segment: Vector3 = hit - origin
        local length: number = segment.Magnitude
        if options.trailEsp and length > 0.5 then
            local beam: Part = Instance.new("Part")
            beam.Name = "TrailSegment"
            beam.Anchored = true
            beam.CanCollide = false
            beam.CanQuery = false
            beam.CanTouch = false
            beam.CastShadow = false
            beam.Material = Enum.Material.Neon
            beam.Color = options.color
            beam.Transparency = 0.25
            beam.Size = Vector3.new(0.07, 0.07, length)
            beam.CFrame = CFrame.lookAt(origin + segment * 0.5, hit)
            beam.Parent = folder
            pcall(function(): ()
                TweenService:Create(
                    beam,
                    TweenInfo.new(1.4, Enum.EasingStyle.Linear),
                    { Transparency = 1 }
                ):Play()
            end)
            task.delay(1.55, function(): ()
                if beam.Parent then
                    pcall(function(): () beam:Destroy() end)
                end
            end)
        end
        -- Pixel-sized ring at the reported endpoint; never highlight the
        -- entire hitPart (a single hitPart can be a whole wall).
        local anchor: Part = Instance.new("Part")
        anchor.Name = "TrailLanding"
        anchor.Size = Vector3.new(0.02, 0.02, 0.02)
        anchor.Transparency = 1
        anchor.Anchored = true
        anchor.CanCollide = false
        anchor.CanQuery = false
        anchor.CanTouch = false
        anchor.Position = hit
        anchor.Parent = folder
        local billboard: BillboardGui = Instance.new("BillboardGui")
        billboard.Name = "LandingCircle"
        billboard.Adornee = anchor
        billboard.AlwaysOnTop = true
        billboard.Size = UDim2.fromOffset(12, 12)
        billboard.Parent = anchor
        local ring: Frame = Instance.new("Frame")
        ring.Size = UDim2.fromScale(1, 1)
        ring.BackgroundTransparency = 1
        ring.Parent = billboard
        local corner: UICorner = Instance.new("UICorner")
        corner.CornerRadius = UDim.new(1, 0)
        corner.Parent = ring
        local stroke: UIStroke = Instance.new("UIStroke")
        stroke.Color = options.color
        stroke.Thickness = 2
        stroke.Parent = ring
        task.delay(1.55, function(): ()
            if anchor.Parent then anchor:Destroy() end
        end)
    end


    local function toggle(enabled: boolean)
        options.trailEsp = enabled
        if connection then connection:Disconnect(); connection = nil end
        clearTrails()
        if not enabled then return end
        local ok, service = pcall(core.getWeaponServiceModule)
        if not ok or type(service) ~= "table" or not service.GunFired then return end
        local connected, result = pcall(function()
            return service.GunFired.OnClientEvent:Connect(function(_handle, origin, hit, hitPart)
                if not options.trailEsp then return end
                local function position(value)
                    local v = typeof(value) == "Vector3" and value
                        or typeof(value) == "CFrame" and value.Position or nil
                    if v and v.X == v.X and v.Y == v.Y and v.Z == v.Z and v.Magnitude < 1e7 then return v end
                    return nil
                end
                local a, b = position(origin), position(hit)
                if a and b then drawShotTrail(a, b, hitPart) end
            end)
        end)
        if connected then connection = result end
    end
    local config = configData
    local key = "MM2.Calibration.TrailESP"
    if config.states[key] == nil then config.states[key] = config.states["MM2.WeaponVisuals.TrailESP"] end
    if config.values["MM2.Calibration.Trailcolor"] == nil then
        config.values["MM2.Calibration.Trailcolor"] = config.values["MM2.WeaponVisuals.Trailcolor"]
    end
    addToggleOption(state.mm2CalibrationFeature, "TrailESP", false, toggle,
        "Visualizes replicated GunFired paths/endpoints. Calibration already records shot data; this adds no duplicate recorder.")
    addColorOption(state.mm2CalibrationFeature, "Trail color", options.color, function(color) options.color = color end)
    activeCleanup = function() toggle(false) end
    Module.Initialized = true
    return Module
end
function Module.destroy()
    if not Module.Initialized then return end
    Module.Initialized = false
    activeCleanup()
end
return Module

]],
        ["src/games/MM2/Other/CoinsAura.lua"] = [[
local Module = {
    Name = "MM2 Coins Aura",
    Events = {} :: {[string]: any},
    Initialized = false,
    Runtime = nil :: any,
}

local activeCleanup: () -> () = function(): () end

function Module.init(runtime: any): any
    if Module.Initialized then
        return Module
    end
    local core: any = state.mm2Core
    assert(type(core) == "table", "MM2 Coins Aura requires the MM2 core module")
    Module.Runtime = runtime

    -- Maximum coin pickup distance accepted by the MM2 server (~15 studs).
    local MAX_SERVER_REACH: number = 15
    local MAX_SERVER_REACH_SQ: number = MAX_SERVER_REACH * MAX_SERVER_REACH
    local TICK_INTERVAL: number = 0.08
    local CACHE_INTERVAL: number = 0.5

    local savedCFrames: {[BasePart]: CFrame} = {}
    local savedPositions: {[BasePart]: Vector3} = {}
    local activeCoin: BasePart? = nil

    local function rememberCoin(serverPart: BasePart): Vector3?
        local pos: Vector3? = savedPositions[serverPart]
        if pos then
            return pos
        end
        local ok: boolean, cf: any = pcall(function(): any
            return serverPart.CFrame
        end)
        if ok and cf then
            savedCFrames[serverPart] = cf
            local p: Vector3 = cf.Position
            savedPositions[serverPart] = p
            return p
        end
        return nil
    end

    local function restoreCoin(serverPart: BasePart?): ()
        if not serverPart then
            return
        end
        local cf: CFrame? = savedCFrames[serverPart]
        if cf and serverPart.Parent then
            pcall(function(): ()
                serverPart.CFrame = cf
            end)
        end
        if activeCoin == serverPart then
            activeCoin = nil
        end
    end

    local function restoreAllCoins(): ()
        if activeCoin then
            restoreCoin(activeCoin)
        end
        for serverPart, cf in pairs(savedCFrames) do
            if serverPart and serverPart.Parent then
                pcall(function(): ()
                    serverPart.CFrame = cf
                end)
            end
        end
        table.clear(savedCFrames)
        table.clear(savedPositions)
        activeCoin = nil
    end

    local function isCoinCollectable(serverPart: BasePart): boolean
        if not serverPart or not serverPart.Parent then
            return false
        end
        if serverPart:GetAttribute("Collected") == true
            or serverPart:GetAttribute("Delete") == true then
            return false
        end
        local visual: Instance? = serverPart:FindFirstChild("CoinVisual")
        if visual and (
            visual:GetAttribute("Collected") == true
            or visual:GetAttribute("Delete") == true
        ) then
            return false
        end
        return true
    end

    -- Detach CoinVisual's WeldConstraint once before pulling Coin_Server so
    -- moving Coin_Server never triggers rigid-body weld recalculation or
    -- fights CoinVisualizer's PreSimulation spin.
    local function detachVisualWeld(serverPart: BasePart): ()
        local visual: Instance? = serverPart:FindFirstChild("CoinVisual")
        if not visual or not visual:IsA("BasePart") then
            return
        end
        local vPart: BasePart = visual :: BasePart
        vPart.Anchored = true
        local weld: Instance? = vPart:FindFirstChildOfClass("WeldConstraint")
        if weld and weld:IsA("WeldConstraint") then
            (weld :: WeldConstraint).Enabled = false
        end
    end

    local function pulseCoinTouch(root: BasePart, serverPart: BasePart): ()
        rememberCoin(serverPart)
        detachVisualWeld(serverPart)
        serverPart.CanCollide = false
        local rootCF: CFrame? = root.CFrame
        if rootCF then
            serverPart.CFrame = rootCF
        end
        local fireTouch: any = state.fireTouchInterest
        if type(fireTouch) == "function" then
            pcall(fireTouch, root, serverPart, 0)
            pcall(fireTouch, root, serverPart, 1)
        end
    end

    local CoinsAuraFeature: any = nil

    local function toggleCoinsAura(enabled: boolean): ()
        disconnectFeatureConnection("MM2CoinsAura")
        restoreAllCoins()

        if not enabled then
            if CoinsAuraFeature then
                CoinsAuraFeature:SetStatus(nil)
            end
            return
        end

        local cachedCoins: {BasePart} = {}
        local lastCacheAt: number = -math.huge
        local lastTickAt: number = -math.huge

        if CoinsAuraFeature then
            CoinsAuraFeature:SetStatus("Max reach")
        end

        local function refreshCoins(now: number): ()
            if now - lastCacheAt < CACHE_INTERVAL then
                return
            end
            lastCacheAt = now

            local list: {BasePart} = {}
            local seen: {[BasePart]: boolean} = {}

            local function addCoin(candidate: Instance?): ()
                if not candidate then
                    return
                end
                local serverPart: BasePart? = nil
                if candidate:IsA("BasePart") then
                    if candidate.Name == "Coin_Server" or candidate.Name == "ServerCoinPart" then
                        serverPart = candidate :: BasePart
                    elseif candidate.Parent and candidate.Parent:IsA("BasePart")
                        and (candidate.Parent.Name == "Coin_Server" or candidate.Parent.Name == "ServerCoinPart") then
                        serverPart = candidate.Parent :: BasePart
                    else
                        serverPart = candidate :: BasePart
                    end
                elseif candidate:IsA("Model") then
                    local child: Instance? = candidate:FindFirstChild("Coin_Server")
                        or candidate:FindFirstChildWhichIsA("BasePart")
                    if child and child:IsA("BasePart") then
                        serverPart = child :: BasePart
                    end
                end
                if serverPart and not seen[serverPart] and isCoinCollectable(serverPart) then
                    seen[serverPart] = true
                    rememberCoin(serverPart)
                    list[#list + 1] = serverPart
                end
            end

            if type(core.findMM2Map) == "function" then
                local map: Instance? = core.findMM2Map()
                if map then
                    local container: Instance? = map:FindFirstChild("CoinContainer")
                        or map:FindFirstChild("CoinAreas")
                        or map:FindFirstChild("Coins")
                    if container then
                        for _, child: Instance in ipairs(container:GetChildren()) do
                            addCoin(child)
                        end
                    end
                end
            end

            if #list == 0 and type(state.mm2CoinPickups) == "function" then
                local okPickups: boolean, pickups: any = pcall(state.mm2CoinPickups)
                if okPickups and type(pickups) == "table" then
                    for _, pickup: Instance in ipairs(pickups) do
                        addCoin(pickup)
                    end
                end
            end

            cachedCoins = list
        end

        local function auraTick(): ()
            local now: number = os.clock()
            if now - lastTickAt < TICK_INTERVAL then
                return
            end
            lastTickAt = now

            local character: Model? = LocalPlayer and LocalPlayer.Character
            local root: BasePart? = character and character:FindFirstChild("HumanoidRootPart") :: BasePart?
            if not root then
                if activeCoin then
                    restoreCoin(activeCoin)
                end
                return
            end
            local humanoid: Humanoid? = character:FindFirstChildOfClass("Humanoid") :: Humanoid?
            if humanoid and humanoid.Health <= 0 then
                if activeCoin then
                    restoreCoin(activeCoin)
                end
                return
            end

            refreshCoins(now)

            local rootPos: Vector3 = root.Position
            local bestCoin: BasePart? = nil
            local bestDistSq: number = MAX_SERVER_REACH_SQ

            for i: number = 1, #cachedCoins do
                local coin: BasePart = cachedCoins[i]
                if isCoinCollectable(coin) then
                    local coinPos: Vector3? = savedPositions[coin] or rememberCoin(coin)
                    if coinPos then
                        local diff: Vector3 = coinPos - rootPos
                        local distSq: number = diff.X * diff.X + diff.Y * diff.Y + diff.Z * diff.Z
                        if distSq <= bestDistSq then
                            bestDistSq = distSq
                            bestCoin = coin
                        end
                    end
                elseif coin == activeCoin then
                    restoreCoin(coin)
                end
            end

            if activeCoin and activeCoin ~= bestCoin then
                restoreCoin(activeCoin)
            end

            if bestCoin then
                activeCoin = bestCoin
                pcall(pulseCoinTouch, root, bestCoin)
            end
        end

        featureConnections.MM2CoinsAura = TaskManager:Connect(auraTick)
        auraTick()
    end

    CoinsAuraFeature = createUniversalFeature(
        "Coins Aura",
        "Automatically collects nearby coins at the maximum reach allowed by the MM2 server with minimal CPU usage.",
        7,
        toggleCoinsAura,
        {
            categoryName = "Utilities",
            parent = MM2Scroll,
            registry = mm2Features,
        }
    )
    state.mm2CoinsAuraFeature = CoinsAuraFeature

    activeCleanup = function(): ()
        toggleCoinsAura(false)
    end
    Module.Events = featureConnections
    Module.Initialized = true
    return Module
end

function Module.destroy(): ()
    if not Module.Initialized then
        return
    end
    Module.Initialized = false
    pcall(activeCleanup)
    activeCleanup = function(): () end
    Module.Events = {}
    Module.Runtime = nil
end

return Module

]],
        ["src/games/MM2/Other/GunAura.lua"] = [[
local Module = {
    Name = "MM2 Gun Aura",
    Events = {} :: {[string]: any},
    Initialized = false,
    Runtime = nil :: any,
}

local activeCleanup: () -> () = function(): () end

function Module.init(runtime: any): any
    if Module.Initialized then
        return Module
    end
    local core: any = state.mm2Core
    assert(type(core) == "table", "MM2 Gun Aura requires the MM2 core module")
    Module.Runtime = runtime

    local settings = {
        studs = 25,
    }

    local TICK_INTERVAL: number = 0.08
    local SCAN_INTERVAL: number = 0.4
    local ESP_INTERVAL: number = 0.5

    local gunAuraActive = false
    local gunHitboxes: {[Instance]: BasePart} = {}
    local espParts: {[Player]: BasePart} = {}
    local savedGunStates: {[BasePart]: {cframe: CFrame, canCollide: boolean}} = {}
    local trackedDrops: {[Instance]: boolean} = {}
    local lastScanAt: number = -math.huge
    local lastTickAt: number = -math.huge
    local lastEspAt: number = -math.huge

    local function resolveGunTouchPart(gun: Instance?): BasePart?
        if not gun then
            return nil
        end
        if gun:IsA("BasePart") then
            return gun :: BasePart
        end
        local handle: Instance? = gun:FindFirstChild("Handle")
            or gun:FindFirstChild("GunDrop")
            or gun:FindFirstChildWhichIsA("BasePart")
        if handle and handle:IsA("BasePart") then
            return handle :: BasePart
        end
        return nil
    end

    local function rememberGunPartState(part: BasePart): {cframe: CFrame, canCollide: boolean}?
        local existing = savedGunStates[part]
        if existing then
            return existing
        end
        local ok: boolean, snap: any = pcall(function(): any
            return {
                cframe = part.CFrame,
                canCollide = part.CanCollide,
            }
        end)
        if ok and type(snap) == "table" then
            savedGunStates[part] = snap
            return snap
        end
        return nil
    end

    local function restoreGunPartState(part: BasePart): ()
        local snap = savedGunStates[part]
        if not snap then
            return
        end
        if part and part.Parent then
            pcall(function(): ()
                part.CFrame = snap.cframe
                part.CanCollide = snap.canCollide
            end)
        end
        savedGunStates[part] = nil
    end

    local function restoreAllGunPartStates(): ()
        for part in pairs(savedGunStates) do
            restoreGunPartState(part)
        end
        table.clear(savedGunStates)
    end

    local function trueGunPartPosition(part: BasePart): Vector3?
        local snap = savedGunStates[part]
        if snap and snap.cframe then
            return snap.cframe.Position
        end
        local okPos: boolean, pos: any = pcall(function(): any
            return part.Position
        end)
        if okPos and typeof(pos) == "Vector3" then
            return pos :: Vector3
        end
        return nil
    end

    local function canGrabGun(): boolean
        local character = LocalPlayer and LocalPlayer.Character
        if not character then
            return false
        end

        local humanoid = character:FindFirstChildOfClass("Humanoid")
        if not humanoid or humanoid.Health <= 0 then
            return false
        end

        if type(core.getPlayerRole) == "function" then
            local role = core.getPlayerRole(LocalPlayer)
            if role == "Murderer" or role == "Sheriff" or role == "Hero" then
                return false
            end
        end

        local backpack = LocalPlayer:FindFirstChildOfClass("Backpack")
        if (backpack and (backpack:FindFirstChild("Gun") or backpack:FindFirstChild("Knife")))
            or character:FindFirstChild("Gun")
            or character:FindFirstChild("Knife") then
            return false
        end

        return true
    end

    local function isValidGunDrop(obj: Instance?): boolean
        if not obj or not obj.Parent then
            return false
        end
        if obj.Name == "GunDrop" and (obj:IsA("BasePart") or obj:IsA("Model")) then
            return resolveGunTouchPart(obj) ~= nil
        end
        return false
    end

    local function createGunHitbox(gun: Instance): BasePart?
        local handle = resolveGunTouchPart(gun)
        if not handle then
            return nil
        end
        rememberGunPartState(handle)
        local pos = trueGunPartPosition(handle)
        if not pos then
            return nil
        end

        local part = Instance.new("Part")
        part.Name = "WurstGunAuraHitbox"
        part.Size = Vector3.new(settings.studs, settings.studs, settings.studs)
        part.Transparency = 0.65
        part.BrickColor = BrickColor.new("White")
        part.Material = Enum.Material.Neon
        part.CanCollide = false
        part.CanQuery = false
        part.CanTouch = false
        part.Anchored = true
        part.CFrame = CFrame.new(pos)
        part.Parent = workspace

        return part
    end

    -- Lightweight GunDrop discovery: uses DescendantAdded events + top-level
    -- workspace children every 0.4s (never recursive GetDescendants).
    local function refreshTrackedDrops(now: number): ()
        if now - lastScanAt < SCAN_INTERVAL then
            return
        end
        lastScanAt = now

        local wsDrop: Instance? = workspace:FindFirstChild("GunDrop")
        if wsDrop and isValidGunDrop(wsDrop) then
            trackedDrops[wsDrop] = true
        end

        local okChildren: boolean, children: any = pcall(function(): any
            return workspace:GetChildren()
        end)
        if okChildren and type(children) == "table" then
            for _, child: Instance in ipairs(children) do
                if child.Name == "GunDrop" and isValidGunDrop(child) then
                    trackedDrops[child] = true
                elseif child:IsA("Model") or child:IsA("Folder") then
                    local gd: Instance? = child:FindFirstChild("GunDrop")
                    if gd and isValidGunDrop(gd) then
                        trackedDrops[gd] = true
                    end
                end
            end
        end

        if type(core.findDroppedGun) == "function" then
            local okCore: boolean, drop: any = pcall(core.findDroppedGun)
            if okCore and drop and isValidGunDrop(drop) then
                trackedDrops[drop] = true
            end
        end
    end

    local function isWithinAura(truePos: Vector3, rootPos: Vector3): boolean
        local diff = rootPos - truePos
        local radius = settings.studs
        if diff.X * diff.X + diff.Y * diff.Y + diff.Z * diff.Z <= radius * radius then
            return true
        end
        local half = radius * 0.5
        return math.abs(diff.X) <= half
            and math.abs(diff.Y) <= math.max(half, 8)
            and math.abs(diff.Z) <= half
    end

    local function tryGrabGun(root: BasePart, handle: BasePart): ()
        rememberGunPartState(handle)
        handle.CanCollide = false
        local rootCF: CFrame? = root.CFrame
        if rootCF then
            handle.CFrame = rootCF
        end
        local fireTouch: any = state.fireTouchInterest
        if type(fireTouch) == "function" then
            pcall(fireTouch, root, handle, 0)
            pcall(fireTouch, root, handle, 1)
        end
    end

    local function clearAllHitboxes(): ()
        for gun, hitbox in pairs(gunHitboxes) do
            if hitbox and hitbox.Parent then
                pcall(function(): ()
                    hitbox:Destroy()
                end)
            end
            gunHitboxes[gun] = nil
        end
    end

    local function clearAllEsp(): ()
        for player, esp in pairs(espParts) do
            if esp and esp.Parent then
                pcall(function(): ()
                    esp:Destroy()
                end)
            end
            espParts[player] = nil
        end
    end

    local function updateSheriffESP(player: Player): ()
        local character = player.Character
        local root = character and character:FindFirstChild("HumanoidRootPart")
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        if not character or not root or not root:IsA("BasePart")
            or not humanoid or humanoid.Health > 0 then
            local existing = espParts[player]
            if existing then
                if existing.Parent then
                    pcall(function(): ()
                        existing:Destroy()
                    end)
                end
                espParts[player] = nil
            end
            return
        end

        local esp = espParts[player]
        if not esp or not esp.Parent then
            esp = Instance.new("Part")
            esp.Name = "WurstDeadSheriffESP_" .. player.Name
            esp.Size = Vector3.new(3, 3, 3)
            esp.Transparency = 0.3
            esp.BrickColor = BrickColor.new("White")
            esp.Material = Enum.Material.Neon
            esp.CanCollide = false
            esp.CanQuery = false
            esp.CanTouch = false
            esp.Anchored = true
            esp.Parent = workspace
            espParts[player] = esp
        end
        esp.CFrame = (root :: BasePart).CFrame
    end

    local GunAuraFeature: any = nil
    local lastStatus: string? = nil

    local function setStatus(text: string?): ()
        if text == lastStatus then
            return
        end
        lastStatus = text
        if GunAuraFeature then
            GunAuraFeature:SetStatus(text)
        end
    end

    local function gunAuraTick(): ()
        if not gunAuraActive then
            return
        end
        local now: number = os.clock()
        if now - lastTickAt < TICK_INTERVAL then
            return
        end
        lastTickAt = now

        refreshTrackedDrops(now)

        local character = LocalPlayer and LocalPlayer.Character
        local root: BasePart? = character and character:FindFirstChild("HumanoidRootPart") :: BasePart?
        local canGrab = canGrabGun()
        local activeGuns: {[Instance]: boolean} = {}
        local touchedParts: {[BasePart]: boolean} = {}
        local gunCount: number = 0

        for gun in pairs(trackedDrops) do
            if isValidGunDrop(gun) then
                local handle: BasePart? = resolveGunTouchPart(gun)
                if handle then
                    gunCount += 1
                    activeGuns[gun] = true
                    rememberGunPartState(handle)
                    local truePos: Vector3? = trueGunPartPosition(handle)

                    local hitbox = gunHitboxes[gun]
                    if not hitbox or not hitbox.Parent then
                        hitbox = createGunHitbox(gun)
                        if hitbox then
                            gunHitboxes[gun] = hitbox
                        end
                    elseif truePos then
                        local targetSize = Vector3.new(settings.studs, settings.studs, settings.studs)
                        if hitbox.Size ~= targetSize then
                            hitbox.Size = targetSize
                        end
                        hitbox.CFrame = CFrame.new(truePos)
                    end

                    if canGrab and root and truePos and isWithinAura(truePos, root.Position) then
                        touchedParts[handle] = true
                        pcall(tryGrabGun, root, handle)
                    end
                end
            else
                trackedDrops[gun] = nil
            end
        end

        for part in pairs(savedGunStates) do
            if not touchedParts[part] then
                restoreGunPartState(part)
            end
        end

        for gun, hitbox in pairs(gunHitboxes) do
            if not activeGuns[gun] then
                if hitbox and hitbox.Parent then
                    pcall(function(): ()
                        hitbox:Destroy()
                    end)
                end
                gunHitboxes[gun] = nil
            end
        end

        if gunCount > 0 then
            setStatus("Gun detected · " .. tostring(math.round(settings.studs)) .. " studs")
        else
            setStatus(tostring(math.round(settings.studs)) .. " studs")
        end

        if now - lastEspAt >= ESP_INTERVAL and type(core.getPlayerRole) == "function" then
            lastEspAt = now
            local seenSheriffs: {[Player]: boolean} = {}
            for _, player in ipairs(game:GetService("Players"):GetPlayers()) do
                if player ~= LocalPlayer then
                    local role = core.getPlayerRole(player)
                    if role == "Sheriff" then
                        seenSheriffs[player] = true
                        updateSheriffESP(player)
                    end
                end
            end
            for player, esp in pairs(espParts) do
                if not seenSheriffs[player] then
                    if esp and esp.Parent then
                        pcall(function(): ()
                            esp:Destroy()
                        end)
                    end
                    espParts[player] = nil
                end
            end
        end
    end

    local function toggleGunAura(enabled: boolean): ()
        gunAuraActive = enabled
        state.mm2GunAuraEnabled = enabled == true
        disconnectFeatureConnection("MM2GunAura")
        disconnectFeatureConnection("MM2GunAuraDescendant")

        if not enabled then
            clearAllHitboxes()
            clearAllEsp()
            restoreAllGunPartStates()
            table.clear(trackedDrops)
            setStatus(nil)
            return
        end

        lastScanAt = -math.huge
        lastTickAt = -math.huge
        lastEspAt = -math.huge

        if workspace.DescendantAdded then
            featureConnections.MM2GunAuraDescendant = workspace.DescendantAdded:Connect(function(obj: Instance): ()
                if obj.Name == "GunDrop" then
                    trackedDrops[obj] = true
                end
            end)
        end

        setStatus(tostring(math.round(settings.studs)) .. " studs")
        featureConnections.MM2GunAura = TaskManager:Connect(gunAuraTick)
        gunAuraTick()
    end

    GunAuraFeature = createUniversalFeature(
        "Gun Aura",
        "Detects dropped guns in the map with event-driven tracking, draws a white aura box around them, and automatically grabs the gun within Studs range.",
        7,
        toggleGunAura,
        {
            categoryName = "Utilities",
            parent = MM2Scroll,
            registry = mm2Features,
        }
    )
    state.mm2GunAuraFeature = GunAuraFeature

    addNumberOption(GunAuraFeature, "Studs", 25, 5, 250,
        function(value: number): ()
            settings.studs = math.clamp(tonumber(value) or 25, 5, 250)
            if GunAuraFeature.enabled then
                setStatus(tostring(math.round(settings.studs)) .. " studs")
            end
        end,
        "Distance in studs around each dropped gun to automatically grab it.", 1)

    activeCleanup = function(): ()
        toggleGunAura(false)
    end
    Module.Events = featureConnections
    Module.Initialized = true
    return Module
end

function Module.destroy(): ()
    if not Module.Initialized then
        return
    end
    Module.Initialized = false
    pcall(activeCleanup)
    activeCleanup = function(): () end
    Module.Events = {}
    Module.Runtime = nil
end

return Module

]],
        ["src/games/MM2/Other/TrajectoryCalibration.lua"] = [[
local Module = {
    Name = "MM2 Trajectory Calibration",
    Events = {} :: {[string]: any},
    Initialized = false,
    Runtime = nil :: any,
}

local activeCleanup: () -> () = function(): () end

function Module.init(runtime: any): any
    if Module.Initialized then
        return Module
    end
    local core: any = state.mm2Core
    assert(type(core) == "table", "MM2 Trajectory Calibration requires the MM2 core module")
    Module.Runtime = runtime
    local trajectoryCalibration: any = core.trajectoryCalibration

    -- Capture tools only exist with WURST_DEBUG on. The recorder in base.lua
    -- keeps working either way; this is the card the player would otherwise
    -- see between "Blurt Roles" and the real modules.
    if state.debug ~= true then
        Module.Events = featureConnections
        Module.Initialized = true
        return Module
    end

    local TrajectoryFeature: any = state.mm2CalibrationFeature
    if not TrajectoryFeature then
        TrajectoryFeature = createUniversalFeature(
            "Calibration",
            "MM2 shot and knife trajectory calibration; isolated from universal modules.",
            5,
            function(): () end,
            {
                category = true,
                categoryName = "Other",
                parent = MM2Scroll,
                registry = mm2Features,
            }
        )
        state.mm2CalibrationFeature = TrajectoryFeature
    end
    addActionOption(TrajectoryFeature, "Calibration status", function(): ()
        notify(trajectoryCalibration:status())
    end)
    addActionOption(TrajectoryFeature, "Save calibration", function(): ()
        if trajectoryCalibration:save("manual") then
            notify("Trajectory calibration saved in the executor workspace.")
        else
            notify("Trajectory calibration could not be saved; check F9.")
        end
    end)
    addActionOption(TrajectoryFeature, "Clear MM2 history", function(): ()
        trajectoryCalibration:reset()
        notify("Trajectory calibration history cleared.")
    end)
    addInformationOption(
        TrajectoryFeature,
        "Records target windows around your shots and throws. MM2-only calibration; no universal learning observer."
    )

    activeCleanup = function(): ()

    end
    Module.Events = featureConnections
    Module.Initialized = true
    return Module
end

function Module.destroy(): ()
    if not Module.Initialized then
        return
    end
    Module.Initialized = false
    pcall(activeCleanup)
    activeCleanup = function(): () end
    Module.Events = {}
    Module.Runtime = nil
end

return Module

]],
        ["src/games/MM2/Prediction.lua"] = [=[
local Module = {
    Name = "MM2 Prediction",
    Events = {} :: {[string]: any},
    Initialized = false,
    Runtime = nil :: any,
}

--[[
    Kinematic prediction core for MM2 gun shots and knife throws.

    What this model is based on (TestingStuff evidence, not guesses):

      * GunFired echoes carry (handle, origin, endpoint, hitPart). The time
        between our FireServer and that echo is the only transport number we
        can measure in-game; the saved calibration recorded 297 confirmed
        shots with a mean of ~123.5 ms.
      * ThrowingKnifeVisuals advances the blade linearly:
            CFrame + Direction * ThrowSpeed * dt
        with ThrowSpeed 96 by default and no gravity term. A blade therefore
        needs an intercept solve, not a ballistic one.
      * A remote character's replicated position is older than the server
        state the gun ray is checked against. The aim point advances by
        the full measured transport plus the replication interpolation
        window (the saved sessions score hits at the confirmation
        instant, i.e. the server behaves as if it rewound by the whole
        ping; the one-way half was tried in v85 and led short).

    What this model deliberately does NOT do:

      * No unmeasured heuristics. The turn (chord) and braking terms are
        computed from two weighted fits 0.10 s apart, gated on clean residuals
        and a real speed, and capped at 45 degrees / the stop distance. A
        straight run leaves both at zero; nothing here guesses.
      * No unconstrained auto-tuned lead. Transport is the median of at least
        three fresh echoes inside sane pairing limits, with smoothed RTT as
        fallback; the separate residual correction is median-filtered and
        capped at 60 ms.
      * No invented movement when the measured velocity is zero but
        MoveDirection is not. The server only knows replicated motion.
      * No distance/confidence gate before firing. Freshness of the sample,
        WallCheck and weapon readiness are the real conditions.
]]

type Sample = {
    at: number,
    position: Vector3,
    velocity: Vector3,
    state: string,
    grounded: boolean,
    aimOffset: Vector3,
    aimPart: string,
    -- Replicated control input, recorded so an offline replay can weigh an
    -- input-based turn against the measured velocity turn.
    moveDirection: Vector3,
}

type Track = {
    character: Model,
    humanoid: Humanoid,
    root: BasePart,
    samples: {Sample},
}

type Fit = {
    velocity: Vector3,
    residual: number,
    count: number,
    span: number,
    -- Weighted mean sample time. The slope is the chord over the window, so
    -- this is where the measured velocity actually points.
    center: number,
}

type Motion = {
    velocity: Vector3,
    horizontal: Vector3,
    vertical: number,
    airborne: boolean,
    sampleAge: number,
    samples: number,
    residual: number,
    source: string,
    -- Signed yaw rate in rad/s measured between two fits. Zero when the
    -- measurement is not trustworthy (slow, noisy or too few samples).
    turnRate: number,
    -- Longitudinal acceleration along the current direction, clamped. Used
    -- only to keep the lead length honest while the target speeds up or stops.
    longitudinalAccel: number,
    -- Full horizontal acceleration vector measured between two fits,
    -- magnitude-clamped. The calibration replays (85 scored confirmations)
    -- picked a constant-acceleration model over constant velocity 57 to 19,
    -- so the vector is applied over the horizon when it is meaningful.
    accelX: number,
    accelZ: number,
    -- Seconds until the target stops when it is braking hard, else nil.
    brakeSeconds: number?,
    -- How far behind the newest position sample the fitted direction sits.
    -- predictedRoot starts at that sample, not at the later gunAim call.
    fitLag: number,
    -- True only when the measured vertical speed is worth extrapolating. The
    -- humanoid state alone is not enough: a replicated "Jumping" pose can be a
    -- character standing at the apex of a jump.
    verticalLead: boolean,
}

type AimInfo = {
    endpoint: Vector3,
    targetPosition: Vector3,
    capturedPosition: Vector3,
    rootPosition: Vector3,
    velocity: Vector3,
    leadSeconds: number,
    turnRate: number,
    brakeSeconds: number?,
    sampleAge: number,
    samples: number,
    residual: number,
    motionSource: string,
    model: string,
    rtt: number,
    -- Raw engine readings at aim time, so a calibration can tell which of the
    -- two sources produced the lead instead of having to reconstruct it.
    rttEngine: number?,
    rttData: number?,
    echoDelay: number?,
    -- How many echoes back the recorded delay. Zero means the horizon used
    -- the ping, which the calibration can distinguish from a real median.
    echoSamples: number,
    -- Seconds added to the horizon by the confirmed-shot feedback. Zero until
    -- three confirmations have been measured.
    leadCorrection: number,
    flightSeconds: number?,
}

local MAX_SAMPLE_AGE: number = 0.35
local FIT_WINDOW: number = 0.16
local FIT_TAU: number = 0.055
local HISTORY_SECONDS: number = 0.6
-- Remote characters replicate around 20 Hz. 60 Hz keeps three observations per
-- replicated pose (so a fit is never built from a single packet) without
-- inventing detail that the network never sent. Raising it only re-weights the
-- same poses and costs CPU; the dominant error is the transport horizon.
local SAMPLE_HZ: number = 60
local MAX_HORIZONTAL_SPEED: number = 60
local DEFAULT_KNIFE_SPEED: number = 96
local MAX_ECHOES: number = 8
-- A median of two echoes is just the mean of two mismatches. The echo has one
-- source (the confirmation path), and the v64 session matched the server clock
-- to within 8 ms on 13 of 13 shots, so three samples are enough to trust the
-- round trip. Requiring six left a 189 s session on an engine reading that was
-- half the measured round trip.
local MIN_ECHO_SAMPLES: number = 3
-- Pairing sanity limits. An echo only reaches noteEcho after base.lua matched
-- the same gun, an origin within 3.5 studs and a direction within ~15 degrees,
-- so a late sample is our own shot, not a crossed one. The upper bound mirrors
-- the 1.6 s pending-shot window in base.lua; the v18 session has a confirmed
-- 1007.7 ms echo at 270.3 ms ping, which an 800 ms cut would have thrown away.
local MIN_ECHO_DELAY: number = 0.05
local MAX_ECHO_DELAY: number = 1.6
-- Echo housekeeping (v105). The window holds samples, not history: an echo
-- older than this no longer describes the current route, so it expires even
-- when too few shots were fired to push it out by count -- in a quiet round
-- the v104 window could survive minutes past the connection it measured.
local ECHO_MAX_AGE: number = 30
-- A healthy echo median sits at ~1.0-1.1x the RTT (both are the same round
-- trip). If the median climbs past 1.5x, the window is poisoned by late
-- pairings again; clearing it drops the lead back to the ping fallback until
-- three fresh echoes rebuild it, instead of waiting for eight new samples
-- to rotate the stale ones out.
local ECHO_DIVERGENCE_RATIO: number = 1.5
-- Transport + manual lead. A full second only happens when the session ping
-- or the manual offset asks for it; the status line shows the real number.
local MAX_HORIZON: number = 1.0
-- Automatic lead never exceeds this. At 16 studs/s a 1 s lead is 16 studs of
-- overshoot; past 0.6 s the sample is stale enough that refusing to invent
-- more distance is safer. Manual offset is still allowed up to MAX_HORIZON.
local MAX_AUTO_LEAD: number = 0.6
-- Turn and braking corrections are measured, never guessed:
--   * two weighted fits 0.10 s apart give a signed yaw rate;
--   * the same pair gives longitudinal acceleration for the stop cap.
local TURN_SPAN: number = 0.10
local TURN_MIN_SPEED: number = 2.0
local TURN_MAX_RATE: number = 10.0
-- Below ~23 deg/s the two fits are mostly replication jitter; a correction
-- that small only adds noise to the endpoint.
local TURN_MIN_RATE: number = 0.4
local TURN_MAX_ANGLE: number = math.rad(45)
-- Two fits over replicated poses disagree by jitter as much as by turning.
-- At 0.5 the recorded session produced 224 deg and 152 deg turns on a
-- straight run; at 0.20 the shots with a >100 deg turn drop from five to two
-- and the measured aim improves, so this is where the noise stops.
local TURN_RESIDUAL: number = 0.20
-- Vertical extrapolation needs a real vertical speed. A humanoid reported as
-- Jumping at its apex has almost no vertical velocity; dropping the aim by a
-- full ballistic term there is what put shot 6 2.3 studs under the target.
local VERTICAL_MIN_SPEED: number = 8.0
-- Robust transport fallback: a single GetNetworkPing spike (0.31 s against a
-- 0.107 s baseline in the 2026-10-18 session) must not move the next aim.
local RTT_SAMPLES: number = 8
local RTT_SAMPLE_INTERVAL: number = 0.25
local BRAKE_MIN_ACCEL: number = 6.0
local BRAKE_MAX_ACCEL: number = 120.0
-- Closed-loop lead feedback. Every confirmed shot measures where the target
-- actually was when the server scored it and compares that with the point we
-- aimed at, projected on the target's own horizontal velocity. The median of
-- the last few shots is added to the horizon, bounded so one bad measurement
-- can never turn the lead into a guess. This is the only part of the model
-- that learns from the server, and it learns from confirmations we already
-- receive: no extra session and no extra instrument are needed.
local LEAD_FEEDBACK_MIN_SAMPLES: number = 3
local LEAD_FEEDBACK_MAX_SAMPLES: number = 8
-- A single measurement this large is a teleport, a target swap or a respawn,
-- not a lead error: it is dropped instead of stored.
local LEAD_FEEDBACK_SAMPLE_LIMIT: number = 0.15
-- The applied correction. At 18 studs/s this is ~1.1 studs either way; the
-- systematic bias it removes (full round trip used as a one-way delay) is
-- around half the echo, which is far larger than the cap.
local MAX_LEAD_CORRECTION: number = 0.06

local settings = {
    -- Automatic lead is the default: the measured FireServer -> GunFired echo
    -- (fallback: smoothed ping) already includes the device/network timing.
    -- Manual offset is only used when autoLead is turned off.
    autoLead = true,
    -- Manual calibration in seconds. Positive aims further ahead.
    extraLead = 0,
    -- Half of the default 20 Hz replication interval. This is the window the
    -- client interpolates between two replicated character states.
    interpolation = 1 / 40,
}

local activeCleanup: () -> () = function(): () end

local function finiteNumber(value: any): boolean
    return type(value) == "number" and value == value and math.abs(value) < math.huge
end

local function finiteVector(value: any): boolean
    return value ~= nil
        and finiteNumber(value.X)
        and finiteNumber(value.Y)
        and finiteNumber(value.Z)
end

local function humanoidStateName(humanoid: Humanoid): string
    local ok: boolean, state: any = pcall(function(): any
        return humanoid:GetState()
    end)
    if not ok or state == nil then
        return ""
    end
    local name: any = state.Name
    if type(name) == "string" then
        return name
    end
    return tostring(state)
end

local AIM_PARTS: {string} = {
    "UpperTorso",
    "Torso",
    "HumanoidRootPart",
    "Head",
}

local function findAimPart(character: Model): (BasePart?, string)
    for _, partName: string in ipairs(AIM_PARTS) do
        local part: Instance? = character:FindFirstChild(partName)
        if part and part:IsA("BasePart") then
            return part :: BasePart, partName
        end
    end
    local root: Instance? = character:FindFirstChild("HumanoidRootPart")
    if root and root:IsA("BasePart") then
        return root :: BasePart, "HumanoidRootPart"
    end
    return nil, ""
end

function Module.init(runtime: any): any
    if Module.Initialized then
        return Module
    end
    local core: any = state.mm2Core
    assert(type(core) == "table", "MM2 Prediction requires the MM2 core module")
    local predictionMath: any = core.predictionMath
    assert(type(predictionMath) == "table", "MM2 Prediction requires predictionMath")
    Module.Runtime = runtime

    local tracks: {[Player]: Track} =
        setmetatable({}, {__mode = "k"}) :: any
    local echoes: {number} = {}
    local echoTimes: {number} = {}
    local elapsed: number = 0

    local function ensureTrack(player: Player): Track?
        local character: Model? = player.Character
        if not character then
            tracks[player] = nil
            return nil
        end
        local humanoid: Humanoid? = character:FindFirstChildOfClass("Humanoid")
            :: Humanoid?
        local root: BasePart? = character:FindFirstChild("HumanoidRootPart")
            :: BasePart?
        if not humanoid or not root or humanoid.Health <= 0 then
            tracks[player] = nil
            return nil
        end
        local track: Track? = tracks[player]
        if not track or track.character ~= character then
            track = {
                character = character,
                humanoid = humanoid,
                root = root,
                samples = {},
            }
            tracks[player] = track
        end
        track.humanoid = humanoid
        track.root = root
        return track
    end

    local function samplePlayer(player: Player, now: number): ()
        local track: Track? = ensureTrack(player)
        if not track then
            return
        end
        local root: BasePart = track.root
        local position: Vector3 = root.Position
        local velocity: Vector3 = root.AssemblyLinearVelocity
        if not finiteVector(velocity) then
            velocity = Vector3.zero
        end
        local stateName: string = humanoidStateName(track.humanoid)
        -- FloorMaterial often reads Air on remote characters that are walking
        -- on flat ground. The humanoid state is the reliable signal.
        local grounded: boolean = stateName ~= "Jumping"
            and stateName ~= "Freefall"
        local moveDirection: Vector3 = Vector3.zero
        pcall(function(): ()
            local move: any = track.humanoid.MoveDirection
            if typeof(move) == "Vector3" and finiteVector(move) then
                moveDirection = move
            end
        end)
        local aimPart: BasePart?, aimPartName: string = findAimPart(track.character)
        local aimOffset: Vector3 = aimPart
            and (aimPart.Position - position)
            or Vector3.zero

        local samples: {Sample} = track.samples
        local last: Sample? = samples[#samples]
        if last then
            local delta: number = now - last.at
            -- Respawns, teleports and ownership changes must not seed a fit.
            if delta > 0 and delta < 0.4
                and (position - last.position).Magnitude > 8 + 120 * delta then
                table.clear(samples)
            end
        end
        table.insert(samples, {
            at = now,
            position = position,
            velocity = velocity,
            state = stateName,
            grounded = grounded,
            aimOffset = aimOffset,
            aimPart = aimPartName,
            moveDirection = moveDirection,
        })
        while #samples > 2 and now - samples[1].at > HISTORY_SECONDS do
            table.remove(samples, 1)
        end
    end

    local function fitVelocity(track: Track, reference: number): Fit?
        local samples: {Sample} = track.samples
        if #samples < 3 then
            return nil
        end
        -- Collect the window that ends at `reference`, not necessarily at the
        -- newest sample: the same weights applied to an older window give the
        -- velocity direction 0.10 s ago, which is what the turn rate needs.
        local collected: {Sample} = {}
        for index: number = #samples, 1, -1 do
            local sample: Sample = samples[index]
            if sample.at <= reference + 1e-4 then
                if reference - sample.at > FIT_WINDOW then
                    break
                end
                table.insert(collected, 1, sample)
            end
        end
        if #collected < 3 then
            return nil
        end
        local anchor: number = collected[#collected].at
        local sw, st, stt: number = 0, 0, 0
        local sx, sy, sz: number = 0, 0, 0
        local stx, sty, stz: number = 0, 0, 0
        for _, sample: Sample in ipairs(collected) do
            local dt: number = sample.at - anchor
            local age: number = math.max(0, reference - sample.at)
            local weight: number = math.exp(-age / FIT_TAU)
            sw += weight
            st += weight * dt
            stt += weight * dt * dt
            sx += weight * sample.position.X
            sy += weight * sample.position.Y
            sz += weight * sample.position.Z
            stx += weight * dt * sample.position.X
            sty += weight * dt * sample.position.Y
            stz += weight * dt * sample.position.Z
        end
        if sw <= 0 then
            return nil
        end
        local denominator: number = stt - st * st / sw
        if denominator <= 1e-8 then
            return nil
        end
        local meanT: number = st / sw
        local meanX: number = sx / sw
        local meanY: number = sy / sw
        local meanZ: number = sz / sw
        local vx: number = (stx - st * sx / sw) / denominator
        local vy: number = (sty - st * sy / sw) / denominator
        local vz: number = (stz - st * sz / sw) / denominator
        local squared: number = 0
        for _, sample: Sample in ipairs(collected) do
            local dt: number = sample.at - anchor
            local dx: number = sample.position.X - (meanX + vx * (dt - meanT))
            local dy: number = sample.position.Y - (meanY + vy * (dt - meanT))
            local dz: number = sample.position.Z - (meanZ + vz * (dt - meanT))
            squared += dx * dx + dy * dy + dz * dz
        end
        return {
            velocity = Vector3.new(vx, vy, vz),
            residual = math.sqrt(squared / #collected),
            count = #collected,
            span = collected[#collected].at - collected[1].at,
            -- `dt` is relative to the newest sample in this window, not to
            -- `reference`. Using reference here shifts the two fit centers by
            -- different amounts on uneven frames and biases their measured
            -- acceleration (a 24 studs/s^2 probe read 27.33 before this fix).
            center = anchor + meanT,
        }
    end

    -- Two fits 0.10 s apart: their directions give the signed yaw rate, their
    -- magnitudes give the longitudinal braking. Everything is gated on a clean
    -- fit and a real speed, so noise and near-stationary targets stay at zero.
    local function measureTurn(
        track: Track,
        now: number,
        fit: Fit
    ): (number, number, number?, number, number, number)
        local newest: Sample? = track.samples[#track.samples]
        -- The extrapolation starts at the newest position sample. Measuring
        -- from `now` instead would add sampleAge to every acceleration and
        -- turn correction even though that age is already in the horizon.
        local fitLag: number = newest
            and math.max(0, newest.at - fit.center)
            or 0
        if fit.count < 3 or fit.span < 0.06 then
            return 0, 0, nil, fitLag, 0, 0
        end
        local previous: Fit? = fitVelocity(track, now - TURN_SPAN)
        if not previous or previous.count < 3 or previous.span < 0.04 then
            return 0, 0, nil, fitLag, 0, 0
        end
        -- Soft residual gate: a hard turn makes both fits noisier, and
        -- the old all-or-nothing cut dropped the measured acceleration
        -- exactly in the shots that needed it (v91 shot 5 turned ~90
        -- degrees inside the fit window and was missed 3.3 studs
        -- sideways). Between one and 2.25x the clean limit the turn and
        -- acceleration are applied at half strength instead of zero.
        local worstResidual: number = math.max(fit.residual, previous.residual)
        local confidence: number = 1
        if worstResidual > TURN_RESIDUAL then
            if worstResidual > TURN_RESIDUAL * 2.25 then
                return 0, 0, nil, fitLag, 0, 0
            end
            confidence = 0.5
        end
        local v0: Vector3 = Vector3.new(previous.velocity.X, 0, previous.velocity.Z)
        local v1: Vector3 = Vector3.new(fit.velocity.X, 0, fit.velocity.Z)
        if v0.Magnitude < TURN_MIN_SPEED or v1.Magnitude < TURN_MIN_SPEED then
            return 0, 0, nil, fitLag, 0, 0
        end
        local dt: number = math.max(0.04, fit.center - previous.center)
        local cross: number = v0.Z * v1.X - v0.X * v1.Z
        local dot: number = v0.X * v1.X + v0.Z * v1.Z
        local rate: number = math.clamp(
            math.atan2(cross, dot) / dt,
            -TURN_MAX_RATE,
            TURN_MAX_RATE
        )
        if math.abs(rate) < TURN_MIN_RATE then
            rate = 0
        end
        local ax: number = (v1.X - v0.X) / dt * confidence
        local az: number = (v1.Z - v0.Z) / dt * confidence
        rate *= confidence
        if math.abs(rate) < TURN_MIN_RATE then
            rate = 0
        end
        local speed: number = v1.Magnitude
        local along: number = math.clamp(
            (ax * v1.X + az * v1.Z) / speed,
            -BRAKE_MAX_ACCEL,
            BRAKE_MAX_ACCEL
        )
        local brakeSeconds: number? = nil
        if along <= -BRAKE_MIN_ACCEL then
            local currentSpeed: number = math.max(0, speed + along * fitLag)
            brakeSeconds = currentSpeed / -along
        end
        local accelMagnitude: number = math.sqrt(ax * ax + az * az)
        if accelMagnitude > BRAKE_MAX_ACCEL then
            local scale: number = BRAKE_MAX_ACCEL / accelMagnitude
            ax *= scale
            az *= scale
        end
        return rate, along, brakeSeconds, fitLag, ax, az
    end

    local function estimateMotion(track: Track, now: number): Motion?
        local samples: {Sample} = track.samples
        local last: Sample? = samples[#samples]
        if not last then
            return nil
        end
        local age: number = math.max(0, now - last.at)
        if age > MAX_SAMPLE_AGE then
            return nil
        end
        local fit: Fit? = fitVelocity(track, now)
        local reported: Vector3 = last.velocity
        local horizontal: Vector3
        local source: string
        local turnRate: number = 0
        local longitudinalAccel: number = 0
        local accelX: number = 0
        local accelZ: number = 0
        local brakeSeconds: number? = nil
        local fitLag: number = 0
        local verticalLead: boolean = false
        if fit and fit.count >= 3 and fit.span >= 0.04 and fit.residual <= 1.5 then
            -- Relaxed gates (v118): the old residual <= 0.5 and span >= 0.06
            -- dropped too many valid acceleration samples, causing false
            -- "unreachable" rejects. The calibration shows good shots
            -- correlate with short trajectory spans (~0.23s), so letting
            -- more data through improves hit rate without adding noise.
            horizontal = Vector3.new(fit.velocity.X, 0, fit.velocity.Z)
            source = "history"
        else
            horizontal = Vector3.new(reported.X, 0, reported.Z)
            source = "replicated"
        end
        if not finiteVector(horizontal) then
            horizontal = Vector3.zero
        elseif horizontal.Magnitude > MAX_HORIZONTAL_SPEED then
            horizontal = horizontal.Unit * MAX_HORIZONTAL_SPEED
        end
        -- Airborne is a physics fact before it is a state name: in the
        -- v91 session one target fell at -46 studs/s while its state
        -- still read "Running" (it had just left a ledge), so no
        -- ballistic lead was applied and the shot went over its head.
        -- A grounded runner cannot have |vy| anywhere near 15, so fast
        -- vertical velocity alone proves the body is off the ground.
        local airborne: boolean = last.state == "Jumping"
            or last.state == "Freefall"
            or math.abs(reported.Y) >= 15
        local vertical: number = 0
        if airborne then
            vertical = reported.Y
            if not finiteNumber(vertical) then
                vertical = 0
            elseif math.abs(vertical) < 0.5 and fit then
                vertical = fit.velocity.Y
            end
            vertical = math.clamp(vertical, -120, 120)
        end
        if fit then
            turnRate, longitudinalAccel, brakeSeconds, fitLag, accelX, accelZ =
                measureTurn(track, now, fit)
        end
        if airborne and math.abs(vertical) >= VERTICAL_MIN_SPEED then
            verticalLead = true
        end
        return {
            velocity = Vector3.new(horizontal.X, vertical, horizontal.Z),
            horizontal = horizontal,
            vertical = vertical,
            airborne = airborne,
            sampleAge = age,
            samples = #samples,
            residual = fit and fit.residual or math.huge,
            source = source,
            turnRate = turnRate,
            longitudinalAccel = longitudinalAccel,
            accelX = accelX,
            accelZ = accelZ,
            brakeSeconds = brakeSeconds,
            fitLag = fitLag,
            verticalLead = verticalLead,
        }
    end

    -- Lead displacement for a horizon, with the measured turn and braking.
    -- The fitted direction sits `fitLag` behind the newest position sample,
    -- and the chord over the horizon points at the tangent halfway through
    -- it, so the rotation is rate * (horizon/2 + fitLag). The horizon already
    -- includes the sample's age. Capped at 45 degrees on purpose: a larger
    -- correction is a turn the samples cannot describe anymore.
    local function leadHorizontal(motion: Motion, horizon: number): Vector3
        local speed: number = motion.horizontal.Magnitude
        if speed < 1e-4 or horizon <= 0 then
            return Vector3.zero
        end
        local direction: Vector3 = motion.horizontal.Unit
        -- Measured-acceleration path. Across the scored calibration replays
        -- this model beat constant velocity 57 to 19: MM2 targets accelerate,
        -- brake and strafe constantly, and the lateral component of the
        -- measured vector IS the turn, so no direction rotation is applied on
        -- top of it. The application clamp is tighter than the measurement
        -- clamp: the v61 failure came from a +120 swing stretching the lead,
        -- and 60 studs/s^2 already covers a humanoid reaching WalkSpeed.
        local accelMagnitude: number = math.sqrt(
            motion.accelX * motion.accelX + motion.accelZ * motion.accelZ
        )
        if accelMagnitude >= 4 then
            local applied: Vector3 = Vector3.new(
                motion.accelX,
                0,
                motion.accelZ
            )
            if accelMagnitude > 60 then
                applied *= 60 / accelMagnitude
            end
            local displacement: Vector3 = motion.horizontal * horizon
                + applied * (motion.fitLag * horizon
                    + 0.5 * horizon * horizon)
            if motion.brakeSeconds and horizon > motion.brakeSeconds then
                -- Already stopped by then: cap the along-track component at
                -- the stop distance and keep the lateral correction.
                local alongDistance: number = displacement:Dot(direction)
                local along: number = math.min(
                    0,
                    motion.longitudinalAccel
                )
                local speedNow: number = math.max(
                    0,
                    speed + along * motion.fitLag
                )
                local stopDistance: number = speedNow
                    * motion.brakeSeconds * 0.5
                if alongDistance > stopDistance then
                    displacement -= direction
                        * (alongDistance - stopDistance)
                end
            end
            return displacement
        end
        if math.abs(motion.turnRate) > 1e-3 then
            local angle: number = math.clamp(
                motion.turnRate * (horizon * 0.5 + motion.fitLag),
                -TURN_MAX_ANGLE,
                TURN_MAX_ANGLE
            )
            local cosine: number = math.cos(angle)
            local sine: number = math.sin(angle)
            direction = Vector3.new(
                direction.X * cosine + direction.Z * sine,
                0,
                -direction.X * sine + direction.Z * cosine
            )
        end
        -- The fit is a chord over the window, so it lags the current speed.
        -- Correct it by the measured longitudinal acceleration over that lag,
        -- and include the acceleration over the horizon itself. Both terms
        -- are clamped in measureTurn; a clean straight run leaves them at 0.
        -- Only deceleration earns a length correction. In the recorded v61
        -- session the measured "acceleration" of a running target swung to the
        -- +120 clamp and stretched the lead by 1.5 studs; a real stop is the
        -- case that matters and it is a negative value.
        local along: number = math.min(0, motion.longitudinalAccel)
        local speedNow: number = math.max(0, speed + along * motion.fitLag)
        local length: number = speedNow * horizon
            + 0.5 * along * horizon * horizon
        length = math.max(0, length)
        if motion.brakeSeconds and horizon > motion.brakeSeconds then
            -- The target is already stopped by then; extrapolating further
            -- would aim past it.
            length = math.min(
                length,
                speedNow * motion.brakeSeconds * 0.5
            )
        end
        return direction * length
    end

    local function predictedRoot(
        track: Track,
        motion: Motion,
        horizon: number
    ): Vector3
        local last: Sample = track.samples[#track.samples]
        local lead: Vector3 = leadHorizontal(motion, horizon)
        local x: number = last.position.X + lead.X
        local z: number = last.position.Z + lead.Z
        local y: number = last.position.Y
        if motion.verticalLead then
            y += motion.vertical * horizon
                - 0.5 * workspace.Gravity * horizon * horizon
        end
        return Vector3.new(x, y, z)
    end

    local function currentRtt(): number
        local latency: any = nil
        -- Prefer Data Ping when both readings exist. The calibration
        -- buckets are keyed by Data Ping for a reason: in the v102
        -- session the smoothed lower-of-two estimate read 92-98 ms
        -- while Data Ping read 109-118 ms and the server echo landed
        -- at 110-130 ms, so taking the lower reading under-led every
        -- shot until echoes accumulated. The combined estimate stays
        -- as the fallback when Data Ping is unavailable.
        if type(core.getLatencyReadings) == "function" then
            local ok: boolean, engine: any, data: any =
                pcall(core.getLatencyReadings)
            if ok and finiteNumber(data) then
                latency = data
            elseif ok and finiteNumber(engine) then
                latency = engine
            end
        end
        if not finiteNumber(latency)
            and type(core.getEstimatedLatency) == "function" then
            local ok: boolean, value: any = pcall(core.getEstimatedLatency)
            if ok then
                latency = value
            end
        end
        if not finiteNumber(latency) then
            latency = 0.08
        end
        return math.clamp(latency, 0.02, 0.6)
    end

    -- A median of recent readings, not the live number. A single spike in the
    -- engine estimate produced leads of 0.36-0.40 s against a 0.13 s baseline
    -- on 2026-10-18, and both of those shots missed by 7+ studs.
    local rttSamples: {number} = {}
    local lastRttSampleAt: number = -math.huge
    local function robustRtt(): number
        local now: number = os.clock()
        if now - lastRttSampleAt >= RTT_SAMPLE_INTERVAL then
            lastRttSampleAt = now
            table.insert(rttSamples, currentRtt())
            while #rttSamples > RTT_SAMPLES do
                table.remove(rttSamples, 1)
            end
        end
        local sorted: {number} = table.clone(rttSamples)
        table.insert(sorted, currentRtt())
        table.sort(sorted)
        return sorted[math.floor((#sorted + 1) / 2)]
    end

    local function pruneEchoes(now: number): ()
        if not finiteNumber(now) then
            return
        end
        while #echoes > 0 and now - echoTimes[1] > ECHO_MAX_AGE do
            table.remove(echoes, 1)
            table.remove(echoTimes, 1)
        end
    end

    local function echoMedian(): number?
        -- Expire on reads as well as writes. Otherwise the first shot after a
        -- quiet round uses a median from the previous connection/round; the
        -- v104/v105 files contain such shots after 72-2765 second gaps.
        pruneEchoes(os.clock())
        local count: number = #echoes
        if count < MIN_ECHO_SAMPLES then
            return nil
        end
        local sorted: {number} = table.clone(echoes)
        table.sort(sorted)
        local middle: number = (count + 1) / 2
        local lower: number = math.floor(middle)
        local upper: number = math.ceil(middle)
        return (sorted[lower] + sorted[upper]) / 2
    end

    local function noteEcho(sentAt: number, receivedAt: number): ()
        if not finiteNumber(sentAt) or not finiteNumber(receivedAt) then
            return
        end
        local delay: number = receivedAt - sentAt
        if delay < MIN_ECHO_DELAY or delay > MAX_ECHO_DELAY then
            return
        end
        -- A confirmation matched hundreds of milliseconds late is not
        -- transport: it is a stale pending paired with a later signal
        -- (in the v103 session, pairings at 416-1840 ms entered the
        -- median and dragged it from the true 106 ms to 532 ms, which
        -- led every shot ~0.4 s long and then tripped the capped-
        -- horizon refusal). Real round trips scale with the ping, so
        -- the acceptance window scales with the measured RTT instead
        -- of trusting the absolute 1.6 s pairing limit alone. v104 used
        -- 4x RTT (~540 ms at a 135 ms ping) and the A5AACF6D session
        -- still fed it 279-990 ms pairings that held the median at
        -- 210 ms against a 131-143 ms ping; 2.5x + 50 ms (~388 ms at
        -- that ping) closes that band while staying far above any
        -- genuine round trip on the same connection.
        local plausible: number = math.clamp(
            currentRtt() * 2.5 + 0.05, 0.3, MAX_ECHO_DELAY)
        if delay > plausible then
            return
        end
        -- Also prune against the arriving sample's clock. This keeps explicit
        -- replayed timestamps ordered and prevents one fresh echo from
        -- resurrecting samples that already expired.
        pruneEchoes(receivedAt)
        table.insert(echoes, delay)
        table.insert(echoTimes, receivedAt)
        while #echoes > MAX_ECHOES do
            table.remove(echoes, 1)
            table.remove(echoTimes, 1)
        end
        -- Auto-reset on divergence: if the surviving median no longer
        -- describes this connection's round trip, the window is
        -- poisoned; drop it and let the ping fallback carry the lead
        -- until fresh echoes rebuild the median.
        local median: number? = echoMedian()
        if median and median > currentRtt() * ECHO_DIVERGENCE_RATIO then
            table.clear(echoes)
            table.clear(echoTimes)
        end
    end

    local function manualLead(): number
        return settings.autoLead and 0 or settings.extraLead
    end

    -- Signed over/under-lead measurements, in seconds. Positive means the
    -- target was ahead of the point we aimed at when the server scored it.
    local leadErrors: {number} = {}

    local function medianOf(values: {number}): number?
        local count: number = #values
        if count == 0 then
            return nil
        end
        local sorted: {number} = table.clone(values)
        table.sort(sorted)
        if count % 2 == 1 then
            return sorted[(count + 1) // 2]
        end
        return (sorted[count // 2] + sorted[count // 2 + 1]) * 0.5
    end

    local function noteLeadError(seconds: any): ()
        if not finiteNumber(seconds) then
            return
        end
        if math.abs(seconds) > LEAD_FEEDBACK_SAMPLE_LIMIT then
            return
        end
        table.insert(leadErrors, seconds)
        while #leadErrors > LEAD_FEEDBACK_MAX_SAMPLES do
            table.remove(leadErrors, 1)
        end
    end

    local function leadCorrection(): number
        if #leadErrors < LEAD_FEEDBACK_MIN_SAMPLES then
            return 0
        end
        local median: number? = medianOf(leadErrors)
        if not median then
            return 0
        end
        return math.clamp(median, -MAX_LEAD_CORRECTION, MAX_LEAD_CORRECTION)
    end

    -- How far the recent shots were off, without their sign. Silent aim draws
    -- its bypass segment along the target's own motion, and that segment has to
    -- be as long as the lead's uncertainty: at 16 studs/s a 60 ms error is a
    -- whole stud, which is wider than the blade and most of a limb. Derived
    -- from the same confirmations as the correction, never from a constant.
    local function leadUncertainty(): number
        if #leadErrors < LEAD_FEEDBACK_MIN_SAMPLES then
            return 0
        end
        local absolute: {number} = {}
        for _, seconds: number in ipairs(leadErrors) do
            table.insert(absolute, math.abs(seconds))
        end
        return medianOf(absolute) or 0
    end

    local function gunHorizon(): (number, number, number?)
        local rtt: number = robustRtt()
        local echo: number? = echoMedian()
        -- The echo is measured client-side from the activation to the
        -- confirmation, so it is a real round trip rather than an engine
        -- estimate; it replaces the ping when a median exists. It has to be
        -- measured from the confirmation path for that to happen at all:
        -- v61 recorded none (`echoDelay` nil on all 13 shots).
        -- Blend: rtt is the stable base, echo adds freshness when
        -- available. The calibration shows echo alone leads systematically
        -- short (echo mean 0.227 vs rtt 0.263), so a 60/40 blend avoids
        -- the jump between echo-present and echo-absent without losing
        -- the freshness signal. When echo is stale/nil, rtt stands alone.
        local pipeline: number = echo
            and (rtt * 0.6 + echo * 0.4)
            or rtt
        -- Full transport, NOT the one-way half -- and this is measured,
        -- not assumed: in the saved calibration sessions the confirmed
        -- hits cluster at about +14 ms against the confirmation instant
        -- (a full round trip after firing) and at about -55 ms against
        -- the receive instant, so the server scores the shot as if it
        -- rewound by the shooter's whole ping. v85 halved this on a
        -- no-rewind theory and led systematically short.
        local horizon: number = pipeline
            + settings.interpolation
            + manualLead()
        if settings.autoLead then
            horizon = math.min(horizon, MAX_AUTO_LEAD)
        end
        return math.clamp(horizon, 0.005, MAX_HORIZON), rtt, echo
    end

    -- The blade travels on the same connection as the bullet, so the measured
    -- FireServer -> GunFired round trip is a better transport number than the
    -- engine's ping estimate here too. The v64 file measured 126-472 ms of real
    -- round trip against an 80-154 ms engine reading: leading a thrown blade
    -- with the engine number leaves up to 300 ms of unled movement, which is
    -- the knife missing high and behind a target that is already running.
    local function knifeHorizon(): (number, number, number?)
        local rtt: number = robustRtt()
        local echo: number? = echoMedian()
        local pipeline: number = echo
            and (rtt * 0.6 + echo * 0.4)
            or rtt
        -- Same full-transport rule as the gun (measured the same way:
        -- the blade's effective spawn behaves like a full rewind, so
        -- the intercept leads the whole round trip plus flight time).
        local horizon: number = pipeline
            + settings.interpolation
            + manualLead()
        if settings.autoLead then
            horizon = math.min(horizon, MAX_AUTO_LEAD)
        end
        return math.clamp(horizon, 0.005, MAX_HORIZON), rtt, echo
    end

    local function gunAim(
        target: Player,
        _muzzle: Vector3
    ): (Vector3?, AimInfo?, string?)
        local track: Track? = tracks[target]
        if not track or #track.samples == 0 then
            return nil, nil, "no samples"
        end
        local now: number = os.clock()
        local motion: Motion? = estimateMotion(track, now)
        if not motion then
            return nil, nil, "stale sample"
        end
        local pipeline: number, rtt: number, echo: number? = gunHorizon()
        local rttEngine: number?, rttData: number? = nil, nil
        if type(core.getLatencyReadings) == "function" then
            local ok: boolean, engine: any, data: any = pcall(core.getLatencyReadings)
            if ok then
                rttEngine = finiteNumber(engine) and engine or nil
                rttData = finiteNumber(data) and data or nil
            end
        end
        local horizon: number = math.clamp(
            motion.sampleAge + pipeline,
            0.005,
            MAX_HORIZON
        )
        local rootPosition: Vector3 = predictedRoot(track, motion, horizon)
        local last: Sample = track.samples[#track.samples]
        -- The torso offset turns with the character. The sampled offset is
        -- one sample old; the part's current offset from the current root
        -- is the same measurement without the sample delay, and at a
        -- 100 ms horizon a turning target has already rotated it.
        local aimOffset: Vector3 = last.aimOffset
        local freshAimPart: BasePart? = findAimPart(track.character)
        if freshAimPart then
            aimOffset = freshAimPart.Position - track.root.Position
        end
        local endpoint: Vector3 = rootPosition + aimOffset
        return endpoint, {
            endpoint = endpoint,
            targetPosition = endpoint,
            capturedPosition = last.position + aimOffset,
            rootPosition = rootPosition,
            velocity = motion.velocity,
            leadSeconds = horizon,
            sampleAge = motion.sampleAge,
            samples = motion.samples,
            residual = motion.residual,
            motionSource = motion.source,
            model = "kinematic-v51",
            rtt = rtt,
            rttEngine = rttEngine,
            rttData = rttData,
            echoDelay = echo,
            echoSamples = #echoes,
            turnRate = motion.turnRate,
            brakeSeconds = motion.brakeSeconds,
            leadCorrection = leadCorrection(),
        }, nil
    end

    local function knifeAim(
        target: Player,
        origin: Vector3,
        speed: number?
    ): (Vector3?, AimInfo?, string?)
        local track: Track? = tracks[target]
        if not track or #track.samples == 0 then
            return nil, nil, "no samples"
        end
        local now: number = os.clock()
        local motion: Motion? = estimateMotion(track, now)
        if not motion then
            return nil, nil, "stale sample"
        end
        local resolvedSpeed: number = tonumber(speed) or DEFAULT_KNIFE_SPEED
        if resolvedSpeed < 24 or resolvedSpeed > 300 then
            resolvedSpeed = DEFAULT_KNIFE_SPEED
        end
        local pipeline: number, rtt: number, echo: number? = knifeHorizon()
        local rttEngine: number?, rttData: number? = nil, nil
        if type(core.getLatencyReadings) == "function" then
            local ok: boolean, engine: any, data: any = pcall(core.getLatencyReadings)
            if ok then
                rttEngine = finiteNumber(engine) and engine or nil
                rttData = finiteNumber(data) and data or nil
            end
        end
        local horizon: number = math.clamp(
            motion.sampleAge + pipeline,
            0.005,
            MAX_HORIZON
        )
        local last: Sample = track.samples[#track.samples]
        local aimStart: Vector3 = last.position + last.aimOffset
        local initial: Vector3 = motion.velocity
        local flight: number? = predictionMath.interceptTime(
            aimStart + initial * horizon - origin,
            initial,
            resolvedSpeed
        )
        if not flight then
            return nil, nil, "unreachable"
        end
        -- One re-solve with the average velocity over the whole flight: a
        -- turning or braking target does not travel along the instantaneous
        -- tangent, and the blade needs the chord.
        local span: number = horizon + flight
        local lead: Vector3 = leadHorizontal(motion, span)
        local vertical: number = motion.verticalLead and motion.vertical or 0
        if motion.verticalLead then
            vertical -= 0.5 * workspace.Gravity * span
        end
        local effective: Vector3 = Vector3.new(
            lead.X,
            vertical * span,
            lead.Z
        ) / span
        local revised: number? = predictionMath.interceptTime(
            aimStart + effective * horizon - origin,
            effective,
            resolvedSpeed
        )
        if revised then
            flight = revised
            span = horizon + flight
            lead = leadHorizontal(motion, span)
            vertical = motion.verticalLead and motion.vertical or 0
            if motion.verticalLead then
                vertical -= 0.5 * workspace.Gravity * span
            end
            effective = Vector3.new(lead.X, vertical * span, lead.Z) / span
        end
        local endpoint: Vector3 = aimStart + effective * (horizon + flight)
        if motion.airborne then
            -- A straight blade cannot follow a ballistic arc; aim at the
            -- root's projected position at impact instead of a linear Y.
            endpoint = predictedRoot(track, motion, horizon + flight)
                + last.aimOffset
        end
        return endpoint, {
            endpoint = endpoint,
            targetPosition = endpoint,
            capturedPosition = aimStart,
            rootPosition = predictedRoot(track, motion, horizon + flight),
            velocity = motion.velocity,
            leadSeconds = horizon,
            flightSeconds = flight,
            sampleAge = motion.sampleAge,
            samples = motion.samples,
            residual = motion.residual,
            motionSource = motion.source,
            model = "kinematic-v51",
            rtt = rtt,
            rttEngine = rttEngine,
            rttData = rttData,
            echoDelay = echo,
            echoSamples = #echoes,
            turnRate = motion.turnRate,
            brakeSeconds = motion.brakeSeconds,
            leadCorrection = 0,
        }, nil
    end

    local function playerStatus(target: Player?): string
        local rtt: number = robustRtt()
        local echo: number? = echoMedian()
        local parts: {string} = {
            string.format("RTT %.0f ms", rtt * 1000),
        }
        if echo then
            table.insert(
                parts,
                string.format("echo %.0f ms (%d)", echo * 1000, #echoes)
            )
        end
        table.insert(
            parts,
            string.format("interp %.0f ms", settings.interpolation * 1000)
        )
        if settings.autoLead then
            table.insert(
                parts,
                echo and "auto lead (echo)" or "auto lead (ping)"
            )
        elseif settings.extraLead ~= 0 then
            table.insert(
                parts,
                string.format("manual %+.0f ms", settings.extraLead * 1000)
            )
        end
        local horizon: number = (echo or rtt)
            + settings.interpolation
            + manualLead()
        -- The status must show the horizon the shot actually uses:
        -- gunAim adds the age of the newest sample on top of the
        -- pipeline. Showing only the pipeline (98 ms when the shot
        -- used 111 ms) makes the lead look shorter than it is.
        if target then
            local track: Track? = tracks[target]
            local preview: Motion? = track and estimateMotion(track, os.clock())
            if preview then
                horizon += preview.sampleAge
            end
        end
        local capped: boolean = false
        if settings.autoLead and horizon > MAX_AUTO_LEAD then
            horizon = MAX_AUTO_LEAD
            capped = true
        end
        if horizon > MAX_HORIZON then
            horizon = MAX_HORIZON
            capped = true
        end
        table.insert(
            parts,
            string.format(
                "lead %.0f ms%s",
                horizon * 1000,
                capped and " (capped)" or ""
            )
        )
        if target then
            local track: Track? = tracks[target]
            local motion: Motion? = track and estimateMotion(track, os.clock())
            if motion then
                table.insert(parts, string.format("%.1f studs/s", motion.horizontal.Magnitude))
                table.insert(parts, string.format("%d samples", motion.samples))
                table.insert(parts, string.format("age %.0f ms", motion.sampleAge * 1000))
                if motion.airborne then
                    table.insert(parts, "airborne")
                end
                if math.abs(motion.turnRate) > 0.05 then
                    table.insert(
                        parts,
                        string.format("turn %+.0f deg/s", math.deg(motion.turnRate))
                    )
                end
                if motion.brakeSeconds then
                    table.insert(
                        parts,
                        string.format("brake %.2f s", motion.brakeSeconds)
                    )
                end
            else
                table.insert(parts, "no fresh samples")
            end
        end
        return table.concat(parts, " · ")
    end

    local controller: any = {
        settings = settings,
        noteEcho = noteEcho,
        -- The movement window that ends at the call, oldest first, with `at`
        -- in seconds relative to now (negative). Telemetry attaches it to each
        -- shot so an alternative predictor can be replayed offline from the
        -- same inputs instead of being judged only on live hits.
        getHistory = function(
            player: Player,
            seconds: number?
        ): ({any}?, number?)
            local track: Track? = tracks[player]
            if not track or #track.samples < 2 then
                return nil, 0
            end
            local span: number = math.clamp(
                seconds or HISTORY_SECONDS,
                0.05,
                HISTORY_SECONDS
            )
            -- Times are relative to the newest sample, not to this call. The
            -- modules do not share a clock epoch (the v61 log recorded a
            -- -2546 s offset), so only the predictor's own timestamps can be
            -- subtracted from each other. The caller gets the age separately.
            local newest: Sample = track.samples[#track.samples]
            local age: number = math.max(0, os.clock() - newest.at)
            local points: {any} = {}
            for _, sample: Sample in ipairs(track.samples) do
                local at: number = sample.at - newest.at
                if at >= -span - 1e-6 then
                    table.insert(points, {
                        at = at,
                        position = sample.position,
                        velocity = sample.velocity,
                        state = sample.state,
                        grounded = sample.grounded,
                        moveDirection = sample.moveDirection,
                    })
                end
            end
            if #points < 2 then
                return nil, age
            end
            return points, age
        end,
        gunAim = gunAim,
        knifeAim = knifeAim,
        status = playerStatus,
        getRtt = currentRtt,
        getEchoDelay = echoMedian,
        predict = function(player: Player, horizon: number): Vector3?
            local track: Track? = tracks[player]
            if not track or #track.samples == 0 or not finiteNumber(horizon) then
                return nil
            end
            local motion: Motion? = estimateMotion(track, os.clock())
            if not motion then
                return nil
            end
            return predictedRoot(track, motion, math.clamp(horizon, 0, 2))
        end,
        getMotion = function(player: Player): Motion?
            local track: Track? = tracks[player]
            if not track then
                return nil
            end
            return estimateMotion(track, os.clock())
        end,
        noteLeadError = noteLeadError,
        getLeadCorrection = leadCorrection,
        getLeadUncertainty = leadUncertainty,
        reset = function(): ()
            table.clear(echoes)
            table.clear(echoTimes)
            table.clear(tracks)
            table.clear(rttSamples)
            table.clear(leadErrors)
            lastRttSampleAt = -math.huge
        end,
    }

    local function tick(deltaTime: number): ()
        elapsed += math.max(0, deltaTime or 0)
        local interval: number = 1 / SAMPLE_HZ
        if elapsed + 1e-9 < interval then
            return
        end
        elapsed = elapsed % interval
        local now: number = os.clock()
        for _, player: Player in ipairs(Players:GetPlayers()) do
            if player ~= LocalPlayer then
                samplePlayer(player, now)
            end
        end
    end

    state.mm2Prediction = controller
    featureConnections.MM2PredictionSampler = TaskManager:Connect(tick)

    activeCleanup = function(): ()
        disconnectFeatureConnection("MM2PredictionSampler")
        if state.mm2Prediction == controller then
            state.mm2Prediction = nil
        end
        table.clear(echoes)
        table.clear(echoTimes)
        table.clear(tracks)
    end

    Module.Events = featureConnections
    Module.Initialized = true
    return Module
end

function Module.destroy(): ()
    if not Module.Initialized then
        return
    end
    Module.Initialized = false
    pcall(activeCleanup)
    activeCleanup = function(): () end
    Module.Events = {}
    Module.Runtime = nil
end

return Module

]=],
        ["src/games/MM2/Render/CoinEsp.lua"] = [[
-- MM2 Coin ESP: highlights ONLY the real pickups the game itself spawns.
--
-- A real pickup carries three exact signatures from the game's own code,
-- and this module accepts a part when ANY of them matches -- never a
-- generic name search:
--
--   1. The CollectionService tag "CoinVisual". The game's CoinVisualizer
--      script animates exactly GetTagged("CoinVisual"), skips the parts
--      whose "Collected" attribute is true and destroys the "Delete" ones.
--   2. The "CoinID" attribute. The same script keys every pickup by
--      GetAttribute("CoinID") when CoinCollected fires, so only a real
--      pickup carries it.
--   3. The exact spawn structure from the place: an invisible server part
--      named Coin_Server whose visible child is named CoinVisual, with the
--      mesh children (MainCoin / DecalPart / 2Part, or the event look of
--      the season) under it.
--
-- The highlight always sits on the visible CoinVisual part itself -- never
-- on a parent model or container. (An earlier version walked up to the
-- container model and painted the whole map yellow, and counted every
-- part with "coin" in its name; that detection is gone.)
--
-- The family of a pickup (Coin, Candy, SnowToken, BeachBall, Egg, Heart)
-- is read from its own mesh children; when the meshes say nothing
-- specific, the family the server announced applies, because a round only
-- pays one kind of pickup. Candies replace coins during Halloween with
-- this same spawn system ([1](https://murder-mystery-2.fandom.com/wiki/Halloween_Event_2025)),
-- so a candy round is found by the same signatures. The server family
-- comes from the Remotes/Gameplay/CoinsStarted bag table (Coin, Candy,
-- SnowToken, BeachBall, Egg) and the Workspace event attributes.
local Module = {
    Name = "MM2 Coin ESP",
    Events = {} :: {[string]: any},
    Initialized = false,
    Runtime = nil :: any,
}

local activeCleanup: () -> () = function(): () end

-- The exact signatures of a real pickup.
local COIN_TAG: string = "CoinVisual"
local VISUAL_NAME: string = "CoinVisual"
local SERVER_NAME: string = "Coin_Server"

local FAMILY_COIN: string = "Coin"
local FAMILY_CANDY: string = "Candy"
local FAMILY_SNOW: string = "SnowToken"
local FAMILY_BEACH: string = "BeachBall"
local FAMILY_EGG: string = "Egg"
local FAMILY_HEART: string = "Heart"
local FAMILY_ALL: string = "All"
local FAMILY_AUTO: string = "Auto (server)"

-- Most specific first: a SnowToken can carry a mesh named Coin.
local FAMILY_ORDER: {string} = {
    FAMILY_EGG,
    FAMILY_BEACH,
    FAMILY_SNOW,
    FAMILY_CANDY,
    FAMILY_HEART,
    FAMILY_COIN,
}

local COUNT_ORDER: {string} = {
    FAMILY_COIN,
    FAMILY_CANDY,
    FAMILY_SNOW,
    FAMILY_BEACH,
    FAMILY_EGG,
    FAMILY_HEART,
}

local FAMILY_NOUNS: {[string]: {string}} = {
    [FAMILY_COIN] = {"coin", "coins"},
    [FAMILY_CANDY] = {"candy", "candies"},
    [FAMILY_SNOW] = {"snowtoken", "snowtokens"},
    [FAMILY_BEACH] = {"beachball", "beachballs"},
    [FAMILY_EGG] = {"egg", "eggs"},
    [FAMILY_HEART] = {"heart", "hearts"},
}

local FAMILY_CHOICES: {string} = {
    FAMILY_AUTO,
    FAMILY_COIN,
    FAMILY_CANDY,
    FAMILY_SNOW,
    FAMILY_BEACH,
    FAMILY_EGG,
    FAMILY_HEART,
    FAMILY_ALL,
}

local BAG_TO_FAMILY: {[string]: string} = {
    Coin = FAMILY_COIN,
    Candy = FAMILY_CANDY,
    SnowToken = FAMILY_SNOW,
    BeachBall = FAMILY_BEACH,
    Egg = FAMILY_EGG,
}

-- Words read ONLY from the pickup's own mesh children (never from
-- parents: a container name must not reclassify every coin inside).
-- The tagged part itself is always named CoinVisual, whatever family it
-- pays, so that name must never classify a part as a plain coin either.
local FAMILY_PHRASES: {[string]: {string}} = {
    [FAMILY_EGG] = {"egg", "eggs"},
    [FAMILY_BEACH] = {"beachball", "beach ball", "beachballs", "beach balls"},
    [FAMILY_SNOW] = {"snowtoken", "snow token", "snowtokens", "snow tokens", "snowball", "snow ball"},
    [FAMILY_CANDY] = {"candy", "candies", "candied", "candycorn", "candy corn"},
    [FAMILY_HEART] = {"heart", "hearts"},
    [FAMILY_COIN] = {"maincoin", "coinold", "decalpart"},
}

-- Safety-net rescan; the signals do the real work.
local RESCAN_PERIOD: number = 2

local function lower(value: string): string
    return string.lower(value)
end

local function contains(value: string, needle: string): boolean
    return string.find(value, needle, 1, true) ~= nil
end

function Module.init(runtime: any): any
    if Module.Initialized then
        return Module
    end
    local core: any = state.mm2Core
    assert(type(core) == "table", "MM2 Coin ESP requires the MM2 core module")
    Module.Runtime = runtime
    local CoinEffects: any = core.CoinEffects
    local clearEffects: any = core.clearEffects
    local mm2Settings: any = core.mm2Settings
    local collectionService: any = game:GetService("CollectionService")

    local settings = {
        family = FAMILY_AUTO,
    }
    -- Set by the `CoinsStarted` remote and by the Workspace event attributes.
    local serverFamily: string? = nil
    -- Raw signature counts from the last scan, for the report action.
    local lastRaw = {tagged = 0, coinId = 0, named = 0}

    -- Native per-pickup marker: ONE small BoxHandleAdornment per
    -- pickup, sized exactly to the visible coin mesh. No labels and
    -- no per-frame Lua: a hundred markers cost the engine one
    -- adornment each and nothing else. The adornment renders through
    -- walls regardless of the holder's transparency.
    local coinTags: {[Instance]: {box: Instance}} = {}
    -- Pickup -> family, kept between scans for the tag text.
    local lastFamilies: {[Instance]: string} = {}
    -- Parts currently carrying a tag, for tests and the report action.
    state.mm2CoinTagParts = {}

    local function clearTags(): ()
        for part: Instance, entry in pairs(coinTags) do
            coinTags[part] = nil
            pcall(function(): ()
                entry.box:Destroy()
            end)
        end
        table.clear(lastFamilies)
        state.mm2CoinTagParts = {}
    end

    local function attribute(object: Instance, name: string): any
        local ok: boolean, value: any = pcall(function(): any
            return object:GetAttribute(name)
        end)
        if ok then
            return value
        end
        return nil
    end

    local function hasTag(object: Instance): boolean
        local ok: boolean, tagged: boolean = pcall(function(): boolean
            return collectionService:HasTag(object, COIN_TAG)
        end)
        return ok and tagged == true
    end

    -- The visible half of a pickup. A server part resolves to its
    -- CoinVisual child; anything else is used as-is. Parents are NEVER
    -- walked: the container must stay dark.
    local function visualOf(part: Instance): Instance?
        if part.Name == SERVER_NAME then
            local child: Instance? = part:FindFirstChild(VISUAL_NAME)
            if child and child:IsA("BasePart") then
                return child
            end
            return nil
        end
        return part
    end

    -- Filters that are safe to fail open: if an engine call errors, the
    -- signature that found the part is trusted instead of dropping it.
    local function passesFilters(part: Instance): boolean
        if not part:IsA("BasePart") then
            return false
        end
        if attribute(part, "Collected") == true or attribute(part, "Delete") == true then
            return false
        end
        local okDesc: boolean, inside: boolean = pcall(function(): boolean
            return part:IsDescendantOf(workspace)
        end)
        if okDesc and not inside then
            return false
        end
        -- A character is never a pickup, whatever it carries.
        local current: Instance? = part.Parent
        while current and current ~= workspace do
            local okHum: boolean, humanoid: Instance? = pcall(function(): Instance?
                return current:FindFirstChildOfClass("Humanoid")
            end)
            if okHum and humanoid then
                return false
            end
            current = current.Parent
        end
        return true
    end

    -- The family the server says is in play: the `CoinsStarted` table first,
    -- then the Workspace event attributes.
    local function familyFromWorkspace(): string?
        local eventName: string = lower(tostring(attribute(workspace, "CurrentEvent") or ""))
        if contains(eventName, "halloween") then
            return FAMILY_CANDY
        elseif contains(eventName, "christmas") then
            return FAMILY_SNOW
        elseif contains(eventName, "summer") then
            return FAMILY_BEACH
        elseif contains(eventName, "easter") then
            return FAMILY_EGG
        elseif contains(eventName, "valentine") then
            return FAMILY_HEART
        end
        for attrName: string, family: string in pairs({
            isValentines = FAMILY_HEART,
            isChristmas = FAMILY_SNOW,
            isChristmasEnding = FAMILY_SNOW,
            IsSummer = FAMILY_BEACH,
            IsEaster = FAMILY_EGG,
        }) do
            if attribute(workspace, attrName) == true then
                return family
            end
        end
        return nil
    end

    local function activeFamily(): string?
        return serverFamily or familyFromWorkspace()
    end

    -- Family of one pickup: its mesh children only. With no specific
    -- word, the round's family applies (a round pays a single kind of
    -- pickup), falling back to the classic coin.
    local familyCache: {[Instance]: string} = {}
    local function familyOf(part: Instance): string
        local cached: string? = familyCache[part]
        if cached then
            return cached
        end
        local names: {string} = {}
        local ok: boolean, descendants: any = pcall(function(): any
            return part:GetDescendants()
        end)
        if ok and type(descendants) == "table" then
            for _, object: Instance in ipairs(descendants) do
                table.insert(names, object.Name)
            end
        end
        local haystack: string = lower(table.concat(names, " "))
        -- A round pays a single kind of pickup, and event pickups are
        -- built on the classic coin template (MainCoin/DecalPart meshes
        -- with an event look). So when the server announces an event
        -- family, plain coin mesh names must NOT drag the pickup back
        -- to Coin -- that mismatch is what left Auto showing nothing
        -- while the map was full of candies.
        local active: string? = activeFamily()
        for _, family: string in ipairs(FAMILY_ORDER) do
            if family ~= FAMILY_COIN or active == nil or active == FAMILY_COIN then
                for _, phrase: string in ipairs(FAMILY_PHRASES[family]) do
                    if contains(haystack, phrase) then
                        -- Cache only the non-Coin mesh families:
                        -- they win over the server family in every
                        -- scan, so they can never go stale. A Coin
                        -- mesh classification is NOT cached -- when
                        -- the server announces an event family, the
                        -- coin template must reclassify to it.
                        if family ~= FAMILY_COIN then
                            familyCache[part] = family
                        end
                        return family
                    end
                end
            end
        end
        return active or FAMILY_COIN
    end

    -- Every real pickup on the map, merged from the three signatures.
    -- (v84 tried a "cheap" rescan -- tag list plus previously-known
    -- parts -- and in the live game the ESP stopped reporting coins
    -- entirely; the mock suite passed, the game did not. The full
    -- scan below is the behaviour that demonstrably works in game.
    -- The cost is kept down elsewhere: Auto Farm's polls are cached
    -- (1.5 s), the family classification is cached, and the ancestor
    -- walk inside passesFilters is cached per part.)
    local filterCache: {[Instance]: boolean} = {}
    local function collectAll(): ({[Instance]: string}, {[string]: number})
        local found: {[Instance]: string} = {}
        local counts: {[string]: number} = {}
        lastRaw = {tagged = 0, coinId = 0, named = 0}

        -- The attribute half of the filter is volatile (Collected
        -- flips when a coin is taken) and is always re-read; only
        -- the static half (in the workspace, not inside a character)
        -- is cached -- a pickup's ancestry never changes.
        local function passesFiltersCached(part: Instance): boolean
            if attribute(part, "Collected") == true
                or attribute(part, "Delete") == true then
                return false
            end
            local cached: boolean? = filterCache[part]
            if cached ~= nil then
                return cached
            end
            local result: boolean = passesFilters(part)
            filterCache[part] = result
            return result
        end

        local function consider(part: Instance?): ()
            if not part then
                return
            end
            local visual: Instance? = visualOf(part)
            if not visual or found[visual] then
                return
            end
            if not passesFiltersCached(visual) then
                return
            end
            local family: string = familyOf(visual)
            found[visual] = family
            counts[family] = (counts[family] or 0) + 1
        end

        -- Signature 1: the game's own tag list.
        local okTagged: boolean, tagged: any = pcall(function(): any
            return collectionService:GetTagged(COIN_TAG)
        end)
        if okTagged and type(tagged) == "table" then
            lastRaw.tagged = #tagged
            for _, object: Instance in ipairs(tagged) do
                if object:IsA("BasePart") then
                    consider(object)
                end
            end
        end

        -- Signatures 2 and 3: the CoinID attribute and the exact spawn
        -- part names, from one workspace scan.
        local okScan: boolean, descendants: any = pcall(function(): any
            return workspace:GetDescendants()
        end)
        if okScan and type(descendants) == "table" then
            for _, object: Instance in ipairs(descendants) do
                if object:IsA("BasePart") then
                    if attribute(object, "CoinID") ~= nil then
                        lastRaw.coinId += 1
                        consider(object)
                    elseif object.Name == VISUAL_NAME or object.Name == SERVER_NAME then
                        lastRaw.named += 1
                        consider(object)
                    end
                end
            end
        end
        return found, counts
    end

    local function wanted(family: string): boolean
        local choice: string = settings.family
        if choice == FAMILY_ALL then
            return true
        end
        if choice == FAMILY_AUTO then
            local active: string? = activeFamily()
            return active == nil or family == active
        end
        return family == choice
    end

    local function describe(counts: {[string]: number}): string
        local parts: {string} = {}
        for _, family: string in ipairs(COUNT_ORDER) do
            local amount: number = counts[family] or 0
            if amount > 0 then
                local nouns: {string} = FAMILY_NOUNS[family]
                table.insert(parts, tostring(amount) .. " " .. (amount == 1 and nouns[1] or nouns[2]))
            end
        end
        if #parts == 0 then
            return "no coins yet"
        end
        return table.concat(parts, " · ")
    end

    -- Shared with Auto Farm: the pickup parts of the family in use.
    -- CACHED: this used to run a full collectAll() per call, and Auto
    -- Farm polls every 0.4 s -- each poll re-scanned every descendant
    -- of Workspace and hitch-spiked the frame. The cache refreshes on
    -- the ESP's own scans, or at most every 0.5 s when polled.
    local pickupCache: {at: number, list: {Instance}} = {at = -math.huge, list = {}}
    local function refreshPickupCache(found: {[Instance]: string}): ()
        local list: {Instance} = {}
        for part: Instance, family: string in pairs(found) do
            if wanted(family) then
                table.insert(list, part)
            end
        end
        pickupCache = {at = os.clock(), list = list}
    end
    state.mm2CoinPickups = function(): {Instance}
        if os.clock() - pickupCache.at < 0.5 then
            return pickupCache.list
        end
        local found: {[Instance]: string} = collectAll()
        refreshPickupCache(found)
        return pickupCache.list
    end

    local function toggleCoinEsp(enabled: boolean): ()
        disconnectFeatureConnection("MM2CoinRefresh")
        disconnectFeatureConnection("MM2CoinCollected")
        disconnectFeatureConnection("MM2CoinsStarted")
        disconnectFeatureConnection("MM2CoinTagAdded")
        disconnectFeatureConnection("MM2CoinTagRemoved")
        disconnectFeatureConnection("MM2CoinAdded")
        clearEffects(CoinEffects)
        clearTags()

        if not enabled then
            local card: any = state.mm2CoinFeature
            if card then
                card:SetStatus(nil)
            end
            return
        end

        local marked: {[Instance]: boolean} = {}
        local elapsed: number = 0
        local lastStatus: string? = nil
        local dirty: boolean = true

        local function setStatus(text: string): ()

            if text == lastStatus then
                return
            end
            lastStatus = text
            local card: any = state.mm2CoinFeature
            if card then
                card:SetStatus(text)
            end
        end

        -- The visible mesh of a pickup: MainCoin under the CoinVisual
        -- holder (the Candy / coin itself), falling back to the pickup
        -- part. The box takes THIS part's exact size, so the marker is
        -- as small as the candy on screen -- never the big invisible
        -- Coin_Server touch volume.
        local function visualOf(part: Instance): Instance
            local ok: boolean, found: any = pcall(function(): any
                local main: Instance? = part:FindFirstChild("MainCoin", true)
                if main and main:IsA("BasePart") then
                    return main
                end
                local visual: Instance? = part:FindFirstChild("CoinVisual", true)
                if visual and visual:IsA("BasePart") then
                    return visual
                end
                return part
            end)
            if ok and found then
                return found
            end
            return part
        end

        -- One small adornment per visible pickup. Creation happens
        -- once per pickup; between rescans Lua does nothing at all.
        local tagClock: number = 0
        local tagsDirty: boolean = true
        -- Opacity guard: the setting's old default (0.8, from the
        -- full-model Highlight era) made a candy-sized adornment
        -- effectively invisible -- v82-v85 "detected nothing" while
        -- the farm, using the same list, walked to the coins fine.
        -- Cap the marker at 0.6 transparency whatever is saved.
        local function markerTransparency(): number
            return math.clamp(mm2Settings.coinTransparency, 0, 0.6)
        end
        local function drawOverlay(): ()
            tagClock += 1
            local refreshColour: boolean = tagClock % 30 == 0
            local seen: {[Instance]: boolean} = {}
            for part: Instance in pairs(lastFamilies) do
                if part.Parent then
                    seen[part] = true
                    local entry = coinTags[part]
                    if not entry then
                        local okMake: boolean, created: any = pcall(function(): any
                            local visual: Instance = visualOf(part)
                            local box: Instance = Instance.new("BoxHandleAdornment")
                            box.Name = "WurstCoinBox"
                            box.AlwaysOnTop = true
                            box.ZIndex = 5
                            box.Adornee = visual
                            box.Color3 = mm2Settings.coinColor
                            box.Transparency = markerTransparency()
                            local okSize: boolean, visualSize: any = pcall(function(): any
                                return (visual :: any).Size
                            end)
                            if okSize and visualSize then
                                box.Size = visualSize * 1.3
                            end
                            box.Parent = part
                            return {box = box}
                        end)
                        if okMake and created then
                            coinTags[part] = created
                            tagsDirty = true
                        end
                    elseif refreshColour then
                        pcall(function(): ()
                            entry.box.Color3 = mm2Settings.coinColor
                            entry.box.Transparency = markerTransparency()
                        end)
                    end
                end
            end
            for part: Instance in pairs(coinTags) do
                if not seen[part] then
                    local entry = coinTags[part]
                    coinTags[part] = nil
                    pcall(function(): ()
                        entry.box:Destroy()
                    end)
                    tagsDirty = true
                end
            end
            -- Publish which parts carry a marker right now (only
            -- when the set actually changed; this runs every tick).
            if tagsDirty then
                tagsDirty = false
                local published: {[Instance]: boolean} = {}
                for part: Instance in pairs(coinTags) do
                    published[part] = true
                end
                state.mm2CoinTagParts = published
            end
        end

        -- One pickup, cham(s) on its visible geometry only.
        local function refresh(): ()
            local found: {[Instance]: string}, counts: {[string]: number} = collectAll()
            local visible: {[Instance]: boolean} = {}
            table.clear(lastFamilies)
            for object: Instance, family: string in pairs(found) do
                if wanted(family) then
                    visible[object] = true
                    lastFamilies[object] = family
                end
            end
            -- Auto follows the server family, but a mismatch between
            -- the classification and the announcement must not blank
            -- the ESP: fall back to showing every pickup found.
            if settings.family == FAMILY_AUTO and activeFamily() ~= nil then
                local anyWanted: boolean = false
                for object: Instance in pairs(visible) do
                    anyWanted = true
                    break
                end
                if not anyWanted then
                    for object: Instance, family: string in pairs(found) do
                        visible[object] = true
                        lastFamilies[object] = family
                    end
                end
            end
            local changed: boolean = false
            for object: Instance in pairs(visible) do
                if not marked[object] then
                    marked[object] = true
                    changed = true
                end
            end
            for object: Instance in pairs(marked) do
                if not visible[object] then
                    marked[object] = nil
                    changed = true
                end
            end
            -- `changed` no longer drives any drawing: tags are created
            -- and removed by drawOverlay from lastFamilies alone.
            refreshPickupCache(found)
            drawOverlay(true)
            local shown: number = 0
            for _ in pairs(visible) do
                shown += 1
            end
            local foundTotal: number = 0
            for _ in pairs(found) do
                foundTotal += 1
            end
            if foundTotal == 0 then
                setStatus(string.format(
                    "no coins yet (tag %d · id %d · named %d)",
                    lastRaw.tagged, lastRaw.coinId, lastRaw.named))
            else
                setStatus(describe(counts) .. " · " .. shown .. " shown")
            end
            dirty = false
        end

        -- A pickup appears: watch the tag signal (the game's own) and new
        -- workspace parts carrying one of the exact signatures.
        featureConnections.MM2CoinTagAdded =
            collectionService:GetInstanceAddedSignal(COIN_TAG):Connect(function(): ()
                dirty = true
            end)
        featureConnections.MM2CoinTagRemoved =
            collectionService:GetInstanceRemovedSignal(COIN_TAG):Connect(function(): ()
                dirty = true
            end)
        featureConnections.MM2CoinAdded = workspace.DescendantAdded:Connect(function(object: Instance): ()
            if object:IsA("BasePart")
                and (object.Name == VISUAL_NAME or object.Name == SERVER_NAME
                    or attribute(object, "CoinID") ~= nil or hasTag(object))
            then
                dirty = true
            end
        end)

        local started: Instance? = core.mm2GameplayRemotes
            and core.mm2GameplayRemotes:FindFirstChild("CoinsStarted")
        if started and started:IsA("RemoteEvent") then
            featureConnections.MM2CoinsStarted =
                (started :: any).OnClientEvent:Connect(function(bagTable: any): ()
                    if type(bagTable) == "table" then
                        for bag: any in pairs(bagTable) do
                            local family: string? = BAG_TO_FAMILY[tostring(bag)]
                            if family then
                                serverFamily = family
                            end
                        end
                    end
                    dirty = true
                end)
        end

        local remotes: any = core.mm2GameplayRemotes
        local collected: Instance? = remotes and remotes:FindFirstChild("CoinCollected")
        if collected and collected:IsA("RemoteEvent") then
            featureConnections.MM2CoinCollected =
                (collected :: any).OnClientEvent:Connect(function(): ()
                    dirty = true
                end)
        end

        refresh()
        featureConnections.MM2CoinRefresh = TaskManager:Connect(
            function(deltaTime: number): ()
                -- The adornments follow their parts inside the
                -- engine; Lua only rescans when the map changed or on
                -- the safety timer. With ~100 coins out this is the
                -- whole per-frame cost.
                drawOverlay()
                elapsed += deltaTime
                if not dirty and elapsed < RESCAN_PERIOD then
                    return
                end
                elapsed = 0
                refresh()
            end
        )
    end

    local CoinFeature: any = createUniversalFeature(
        "Coin ESP",
        "Draws one small box, exactly the size of the coin, candy, snow token, beach ball or egg mesh, on every real pickup and reports how many of each family exist.",
        3,
        toggleCoinEsp,
        {
            categoryName = "Render",
            parent = MM2Scroll,
            registry = mm2Features,
        }
    )
    state.mm2CoinFeature = CoinFeature

    addCycleOption(
        CoinFeature,
        "Coin in use",
        FAMILY_CHOICES,
        1,
        function(value: string): ()
            settings.family = value
            if CoinFeature.enabled then
                toggleCoinEsp(true)
            end
        end,
        "Auto follows the coin family the server announces through CoinsStarted."
    )
    addColorOption(
        CoinFeature,
        "Coin colour",
        mm2Settings.coinColor,
        function(value: Color3): ()
            mm2Settings.coinColor = value
            if CoinFeature.enabled then
                toggleCoinEsp(true)
            end
        end
    )
    addNumberOption(
        CoinFeature,
        "Coin transparency",
        mm2Settings.coinTransparency,
        0,
        1,
        function(value: number): ()
            mm2Settings.coinTransparency = value
            if CoinFeature.enabled then
                toggleCoinEsp(true)
            end
        end
    )
    addInformationOption(
        CoinFeature,
        "Pickups are recognised by the game's own signatures only: the CoinVisual tag, the CoinID attribute and the exact server/visual part pair. Each pickup gets a single BoxHandleAdornment sized exactly to its visible mesh (no labels), so a hundred coins cost no per-frame Lua. Auto follows the family the server announces on CoinsStarted."
    )

    activeCleanup = function(): ()
        state.mm2CoinFeature = nil
        toggleCoinEsp(false)
    end
    Module.Events = featureConnections
    Module.Initialized = true
    return Module
end

function Module.destroy(): ()
    if not Module.Initialized then
        return
    end
    Module.Initialized = false
    pcall(activeCleanup)
    activeCleanup = function(): ()
    end
    Module.Events = {}
    Module.Runtime = nil
end

return Module

]],
        ["src/games/MM2/Render/RoundEsp.lua"] = [[
local Module = {
    Name = "MM2 Round ESP",
    Events = {} :: {[string]: any},
    Initialized = false,
    Runtime = nil :: any,
}

local activeCleanup: () -> () = function(): () end

function Module.init(runtime: any): any
    if Module.Initialized then
        return Module
    end
    local core: any = state.mm2Core
    assert(type(core) == "table", "MM2 Round ESP requires the MM2 core module")
    Module.Runtime = runtime
    local GunEffects: any = core.GunEffects
    local TrapEffects: any = core.TrapEffects
    local clearEffects: any = core.clearEffects
    local createMM2Cham: any = core.createMM2Cham
    local createMM2Marker: any = core.createMM2Marker
    local findDroppedGun: any = core.findDroppedGun
    local findMM2Map: any = core.findMM2Map
    local mm2Settings: any = core.mm2Settings

    local function toggleGunEsp(enabled: boolean): ()
        disconnectFeatureConnection("MM2GunESP")
        clearEffects(GunEffects)

        if not enabled then
            return
        end

        local elapsed: number = 1
        local markedGun: Instance? = nil
        featureConnections.MM2GunESP = TaskManager:Connect(function(deltaTime: number): ()
            elapsed += deltaTime
            if elapsed < 0.4 then
                return
            end
            elapsed = 0
            local gun: any = findDroppedGun()
            if gun == markedGun and (gun == nil or gun.Parent ~= nil) then
                return
            end
            markedGun = gun
            clearEffects(GunEffects)
            if gun then
                createMM2Marker(
                    GunEffects,
                    gun,
                    "Gun",
                    mm2Settings.gunColor,
                    mm2Settings.gunTransparency
                )
            end
        end)
    end

    local savedTrapTransparency: {[Instance]: number} =
        setmetatable({}, {__mode = "k"}) :: any

    local function restoreTrapTransparency(): ()
        for part: Instance, orig: number in pairs(savedTrapTransparency) do
            pcall(function(): ()
                (part :: BasePart).Transparency = orig
            end)
        end
        table.clear(savedTrapTransparency)
    end

    local function revealTrapPart(part: Instance): ()
        pcall(function(): ()
            if part:IsA("BasePart") then
                local current: any = (part :: BasePart).Transparency
                if type(current) == "number" and current >= 0.95 then
                    if savedTrapTransparency[part] == nil then
                        savedTrapTransparency[part] = current
                    end
                    ;(part :: BasePart).Transparency = 0.35
                end
            end
        end)
    end

    local function toggleTrapEsp(enabled: boolean): ()
        disconnectFeatureConnection("MM2TrapAdded")
        restoreTrapTransparency()
        clearEffects(TrapEffects)

        if not enabled then
            return
        end

        local marked = setmetatable({}, {__mode = "k"})
        local function addTrap(object: Instance): ()
            if marked[object] then
                return
            end
            if (object.Name == "TrapVisual" or object.Name == "Trap")
                and (object:IsA("Model") or object:IsA("BasePart")) then
                local parent: Instance? = (object :: any).Parent
                if parent and marked[parent] then
                    revealTrapPart(object)
                    return
                end
                marked[object] = true
                revealTrapPart(object)
                pcall(function(): ()
                    if type((object :: any).GetDescendants) == "function" then
                        for _, child: Instance in ipairs((object :: any):GetDescendants()) do
                            revealTrapPart(child)
                        end
                    end
                end)
                createMM2Cham(
                    TrapEffects,
                    object,
                    mm2Settings.trapColor,
                    mm2Settings.trapTransparency
                )
            end
        end

        local map = findMM2Map()
        for _, object in ipairs((map or workspace):GetDescendants()) do
            addTrap(object)
        end
        if map and type((workspace :: any).GetChildren) == "function" then
            for _, child: Instance in ipairs((workspace :: any):GetChildren()) do
                addTrap(child)
            end
        end
        featureConnections.MM2TrapAdded = workspace.DescendantAdded:Connect(addTrap)
    end

    core.toggleGunEsp = toggleGunEsp
    core.toggleTrapEsp = toggleTrapEsp

    local unregister = {}
    local itemEsp = services and services.itemEsp
    assert(itemEsp and type(itemEsp.register) == "function", "MM2 item ESP requires the provider service")
    for _, provider in ipairs({
        {name = "Gun ESP", tooltip = "Highlights the dropped MM2 gun while ItemESP is ON.", setEnabled = toggleGunEsp},
        {name = "Trap ESP", tooltip = "Highlights existing and newly placed MM2 traps while ItemESP is ON.", setEnabled = toggleTrapEsp},
    }) do
        local release = itemEsp.register(provider)
        if release then table.insert(unregister, release) end
    end

    activeCleanup = function(): ()
        for _, release in ipairs(unregister) do pcall(release) end
        table.clear(unregister)
        toggleGunEsp(false)
        toggleTrapEsp(false)
    end

    Module.Events = featureConnections
    Module.Initialized = true
    return Module
end

function Module.destroy(): ()
    if not Module.Initialized then
        return
    end
    Module.Initialized = false
    pcall(activeCleanup)
    activeCleanup = function(): () end
    Module.Events = {}
    Module.Runtime = nil
end

return Module

]],
        ["src/games/MM2/base.lua"] = [[
local Module = {
    Name = "MM2",
    Events = {} :: {[string]: any},
    Initialized = false,
    Menu = nil :: any,
    Runtime = nil :: any,
}

local moduleCleanup: () -> () = function(): () end

local function buildMM2Features()
local host: any = getfenv()
local trajectoryLogPrefix: string = "[" .. tostring(host.PRODUCT.logPrefix)
    .. ":MM2:Trajectory]"
local MM2Effects = create("Folder", {
    Parent = ScreenGui,
    Name = "MM2Effects",
})
local GunEffects = create("Folder", {
    Parent = MM2Effects,
    Name = "GunESP",
})
local TrapEffects = create("Folder", {
    Parent = MM2Effects,
    Name = "TrapESP",
})
local CoinEffects = create("Folder", {
    Parent = MM2Effects,
    Name = "CoinChams",
})

local mm2RoundData: {[any]: any} = {}
local mm2GameplayRemotes: Instance? = nil
local mm2RoleRemote: RemoteFunction? = nil
local roleRefreshRunning: boolean = false
local lastRoleRefreshAt: number = -math.huge
local roundLifecycleActive: boolean? = nil
local roleRefreshGeneration: number = 0

pcall(function()
    local replicatedStorage: ReplicatedStorage =
        game:GetService("ReplicatedStorage")
    local remotes: Instance? = replicatedStorage:WaitForChild("Remotes", 5)
    local gameplay: Instance? = remotes and remotes:WaitForChild("Gameplay", 5)
    if not gameplay then
        return
    end
    mm2GameplayRemotes = gameplay
    local getCurrentPlayerData: Instance? = gameplay:FindFirstChild(
        "GetCurrentPlayerData"
    )
    if getCurrentPlayerData and getCurrentPlayerData:IsA("RemoteFunction") then

        mm2RoleRemote = getCurrentPlayerData
    end
end)

local mm2Settings = {
    shootMode = "Manual",
    shootWallCheck = true,
    shootRaw = false,
    silentAim = false,
    shootKey = Enum.KeyCode.Unknown,
    shootTarget = "",
    showMissCooldown = false,
    predictionRtt = 0.08,
    silentSweep = 0.5,

    -- Front is the maintained silent construction. Experimental spawn and
    -- sweep controls are internal calibration inputs, not ordinary menu rows.
    silentSpawn = "Front",
    getGunKey = Enum.KeyCode.Unknown,
    instantRoleNotify = false,
    roleEspAll = false,

    roleEspRoundOnly = false,
    roleEspInnocent = false,
    roleEspMurderer = false,
    roleEspSheriff = false,

    innocentColor = Color3.fromRGB(0, 255, 8),
    innocentTransparency = 0.62,
    deadColor = Color3.fromRGB(170, 170, 180),
    deadTransparency = 0.72,
    murdererColor = Color3.fromRGB(255, 0, 4),
    murdererTransparency = 0.5,
    sheriffColor = Color3.fromRGB(0, 153, 255),
    sheriffTransparency = 0.5,
    heroColor = Color3.fromRGB(255, 196, 0),
    heroTransparency = 0.5,
    roleTagsAll = false,
    blurtDelay = 1.5,
    blurtRepeat = false,
    blurtFake = false,
    coinColor = Color3.fromRGB(230, 220, 65),
    coinTransparency = 0.35,
    trapColor = Color3.fromRGB(145, 25, 25),
    trapTransparency = 0.7,

    gunColor = Color3.fromRGB(255, 215, 0),
    gunTransparency = 0.55,
    autoPlayId = "",
}

local function isProtectedTarget(player: Player?): boolean
    local runtime: any = Module.Runtime
    local targets: any = runtime and runtime.Services and runtime.Services.protectedTargets
    return targets ~= nil and targets.isProtected(player) == true
end

local function clearEffects(folder)
    for _, child in ipairs(folder:GetChildren()) do
        if child:IsA("ObjectValue") and child.Value then
            child.Value:Destroy()
        end
        child:Destroy()
    end
end

-- Match the recovered client's cursor filters, not an assertion about server rules.
-- Returns (clear, blocker). `blocker` describes the part that stopped the ray
-- (or the last transparent part that was skipped) so the caller can record what
-- the server disagreed about instead of guessing.
local function isWeaponPathClear(origin: Vector3, endpoint: Vector3, target: Model?, strict: boolean?, options: {ignoreTarget: boolean?, requireTarget: boolean?}?): (boolean, any?)
    local direction: Vector3 = endpoint - origin
    if direction.Magnitude < 0.05 then return true, nil end
    local excluded: {Instance} = {}
    if LocalPlayer.Character then table.insert(excluded, LocalPlayer.Character) end
    -- Projectile endpoints are future poses: the target's present body must
    -- not hide a wall farther along the predicted segment. Hitscan is unchanged.
    if options and options.ignoreTarget and target then table.insert(excluded, target) end
    for _, object: Instance in ipairs(CollectionService:GetTagged("WeaponPassthrough")) do
        table.insert(excluded, object)
    end
    local params: RaycastParams = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    params.IgnoreWater = true
    for _ = 1, 32 do
        params.FilterDescendantsInstances = excluded
        local hit: RaycastResult? = workspace:Raycast(origin, direction, params)
        if not hit then return not (options and options.requireTarget == true), nil end
        if target and hit.Instance:IsDescendantOf(target) then return true, nil end
        -- The gun uses the game's rule verbatim: every fully transparent part
        -- is skipped. With strict (knife, and the second gun pass) only
        -- transparent parts that cannot collide are skipped; an invisible
        -- solid barrier stops the ray.
        local part: Instance = hit.Instance
        local info: any = {
            name = nil,
            className = nil,
            transparency = nil,
            canCollide = nil,
            distance = nil,
            skipped = false,
        }
        pcall(function(): ()
            info.name = string.sub(part:GetFullName(), 1, 160)
            info.className = part.ClassName
            local hitPosition: any = (hit :: any).Position
            if hitPosition then
                info.distance = (hitPosition - origin).Magnitude
            end
        end)
        if part:IsA("BasePart") then
            info.transparency = part.Transparency
            info.canCollide = part.CanCollide
        end
        if part:IsA("BasePart") and part.Transparency == 1
            and (not strict or part.CanCollide == false) then
            info.skipped = true
            table.insert(excluded, part)
        else
            return false, info
        end
    end
    return false, { name = "raycast budget", skipped = false } -- conservative
end

-- What the ray meets when nothing is skipped. Recorded on every allowed
-- shot, not only on refusals: five shots of the v61 session passed every check
-- and still stopped 24-56 studs short of the aim, and without this there is no
-- way to tell whether transparent geometry was in the way.
local function describeRayHit(origin: Vector3, endpoint: Vector3, target: Model?): any
    local direction: Vector3 = endpoint - origin
    if direction.Magnitude < 0.05 then
        return nil
    end
    local excluded: {Instance} = {}
    if LocalPlayer.Character then
        table.insert(excluded, LocalPlayer.Character)
    end
    for _, object: Instance in ipairs(CollectionService:GetTagged("WeaponPassthrough")) do
        table.insert(excluded, object)
    end
    local params: RaycastParams = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    params.IgnoreWater = true
    params.FilterDescendantsInstances = excluded
    local hit: RaycastResult? = workspace:Raycast(origin, direction, params)
    if not hit then
        return nil
    end
    local part: Instance = hit.Instance
    local info: any = {
        onTarget = target ~= nil and part:IsDescendantOf(target),
    }
    pcall(function(): ()
        info.name = string.sub(part:GetFullName(), 1, 160)
        info.className = part.ClassName
        local position: any = (hit :: any).Position
        if position then
            info.distance = (position - origin).Magnitude
        end
    end)
    if part:IsA("BasePart") then
        info.transparency = part.Transparency
        info.canCollide = part.CanCollide
    end
    return info
end

local function getWeaponFromContainer(
    container: Instance?,
    weaponName: string,
    weaponTag: string
): Tool?
    if not container then
        return nil
    end

    for _, child: Instance in ipairs(container:GetChildren()) do
        if child:IsA("Tool") then
            if CollectionService:HasTag(child, weaponTag) then
                return child
            end

            if weaponName == "Gun" then
                if child.Name == "Gun" then
                    return child
                end
                if child.Name ~= "FakeGun" then
                    local shootRemote: Instance? = child:FindFirstChild("Shoot")
                    if shootRemote and shootRemote:IsA("RemoteEvent") then
                        return child
                    end
                end
            elseif weaponName == "Knife" then
                if child.Name == "Knife" then
                    return child
                end
                local slashRemote: Instance? = child:FindFirstChild("Slash")
                local stabRemote: Instance? = child:FindFirstChild("Stab")
                if (slashRemote and slashRemote:IsA("RemoteEvent"))
                    or (stabRemote and stabRemote:IsA("RemoteEvent")) then
                    return child
                end
                local events: Instance? = child:FindFirstChild("Events")
                local knifeThrown: Instance? = events
                    and events:FindFirstChild("KnifeThrown")
                local knifeStabbed: Instance? = events
                    and events:FindFirstChild("KnifeStabbed")
                if knifeThrown and knifeThrown:IsA("RemoteEvent")
                    and knifeStabbed and knifeStabbed:IsA("RemoteEvent") then
                    return child
                end
            end
        end
    end
    return nil
end

local function getPlayerWeapon(
    player: Player,
    weaponName: string,
    equippedOnly: boolean?
): Tool?
    local tag: string = "Weapon_" .. weaponName
    local equipped: Tool? = getWeaponFromContainer(player.Character, weaponName, tag)
    if equipped or equippedOnly then
        return equipped
    end
    return getWeaponFromContainer(
        player:FindFirstChildOfClass("Backpack"),
        weaponName,
        tag
    )
end

local function isPlayerAlive(player: Player): boolean
    local humanoid: Humanoid? = player.Character
        and player.Character:FindFirstChildOfClass("Humanoid")
        :: Humanoid?
    return humanoid ~= nil and humanoid.Health > 0
end


local function playerFromRoundKey(key: any, data: any): Player?
    if typeof(key) == "Instance" and key:IsA("Player") then
        return key
    end

    local player: Player? = nil
    local namedPlayer: Instance? = Players:FindFirstChild(tostring(key))
    if namedPlayer and namedPlayer:IsA("Player") then
        player = namedPlayer
    end

    if type(data) == "table" then
        if data.Name then
            local namedFromData: Instance? =
                Players:FindFirstChild(tostring(data.Name))

            if namedFromData and namedFromData:IsA("Player") then
                player = namedFromData :: Player
            end
        end
        if not player and data.UserId then
            local userId = tonumber(data.UserId)
            if userId then
                local success, resolvedPlayer = pcall(
                    Players.GetPlayerByUserId,
                    Players,
                    userId
                )
                player = success and resolvedPlayer or nil
            end
        end
    end

    return player
end

local function isRoundEntryDead(data: any): boolean
    if type(data) ~= "table" then
        return false
    end
    return data.Dead == true or data.Killed == true
end

local function getRoundRole(player: Player): string?
    for key: any, data: any in pairs(mm2RoundData) do
        if playerFromRoundKey(key, data) == player and type(data) == "table" then
            if isRoundEntryDead(data) then
                return "Dead"
            end
            local role: any = data.Role
            if role == "Murderer"
                or role == "Sheriff"
                or role == "Hero"
                or role == "Innocent" then
                return role
            end
        end
    end
    return nil
end

local roundRolesListeners: {(boolean) -> ()} = {}
local publishedRoundRolesActive: boolean = false
local function emitRoundRoles(active: boolean): ()
    publishedRoundRolesActive = active
    for _, listener: (boolean) -> () in ipairs(roundRolesListeners) do
        pcall(listener, active)
    end
end
local function onRoundRoles(listener: (boolean) -> ()): () -> ()
    table.insert(roundRolesListeners, listener)

    task.defer(function(): ()
        if table.find(roundRolesListeners, listener) then
            pcall(listener, publishedRoundRolesActive)
        end
    end)
    return function(): ()
        local index: number? = table.find(roundRolesListeners, listener)
        if index then
            table.remove(roundRolesListeners, index)
        end
    end
end

local invalidateRoleCaches: () -> ()
local rebuildRoleIndex: () -> ()

local function hasValidRoundRoleData(dataTable: any): boolean
    if type(dataTable) ~= "table" then
        return false
    end
    for _, entry: any in pairs(dataTable) do
        if type(entry) == "table" and entry.Dead ~= true then
            local role: any = entry.Role
            if role == "Murderer"
                or role == "Sheriff"
                or role == "Hero"
                or role == "Innocent" then
                return true
            end
        end
    end
    return false
end

local function requestRoleRefresh(force: boolean?): ()
    if not mm2RoleRemote
        or (not force and roleRefreshRunning)
        or (not force and os.clock() - lastRoleRefreshAt < 0.8) then
        return
    end

    roleRefreshRunning = true
    local generation: number = roleRefreshGeneration
    task.spawn(function(): ()
        local success: boolean, result: any = pcall(
            mm2RoleRemote.InvokeServer,
            mm2RoleRemote
        )
        roleRefreshRunning = false
        lastRoleRefreshAt = os.clock()
        if success
            and generation == roleRefreshGeneration
            and type(result) == "table"
            and (roundLifecycleActive ~= false or hasValidRoundRoleData(result)) then
            if hasValidRoundRoleData(result) and roundLifecycleActive == nil then
                roundLifecycleActive = true
            end
            mm2RoundData = result
            invalidateRoleCaches()
            if rebuildRoleIndex then
                rebuildRoleIndex()
            end
        end
    end)
end

local roleIndex: {
    roles: {[Player]: string?},
    murderer: Player?,
    sheriff: Player?,
    rolesKnown: boolean,
    gunHolders: {[Player]: boolean}?,
} = {roles = {}, murderer = nil, sheriff = nil, rolesKnown = false, gunHolders = {}}
local roleIndexDirty: boolean = true
local roleIndexAt: number = -math.huge
local roleIndexRefreshQueued: boolean = false
local roleWatchers: {[Player]: {RBXScriptConnection}} = {}

function invalidateRoleCaches(): ()
    roleIndexDirty = true

    if type(state.clearRoleMemo) == "function" then
        state.clearRoleMemo()
    end

    if roleIndexRefreshQueued then
        return
    end
    roleIndexRefreshQueued = true
    task.defer(function(): ()
        roleIndexRefreshQueued = false
        if roleIndexDirty and rebuildRoleIndex then
            rebuildRoleIndex()
        end
    end)
end

local function hasMurdererCollisionGroup(character: Model?): boolean
    if not character then
        return false
    end
    for _, child: Instance in ipairs(character:GetChildren()) do
        if child:IsA("BasePart") and child.CollisionGroup == "Murderer" then
            return true
        end
    end
    return false
end

local function buildRoundRoleMap(): {[Player]: string}
    local map: {[Player]: string} = {}
    for key: any, data: any in pairs(mm2RoundData) do
        if type(data) == "table" then
            local player: Player? = playerFromRoundKey(key, data)
            if player then
                if isRoundEntryDead(data) then
                    map[player] = "Dead"
                else
                    local role: any = data.Role
                    if role == "Murderer"
                        or role == "Sheriff"
                        or role == "Hero"
                        or role == "Innocent" then
                        map[player] = role
                    end
                end
            end
        end
    end
    return map
end

rebuildRoleIndex = function(): ()
    roleIndexDirty = false
    roleIndexAt = os.clock()

    local roles: {[Player]: string?} = {}
    local roundRoleByPlayer: {[Player]: string} = buildRoundRoleMap()
    local murderer: Player? = nil
    local murdererHasKnife: boolean = false
    local sheriff: Player? = nil
    local sheriffHasGun: boolean = false
    local alive: {[Player]: boolean} = {}
    local special: {[Player]: string} = {}
    local gunHolders: {[Player]: boolean} = {}

    for _, player: Player in ipairs(Players:GetPlayers()) do
        local character: Model? = player.Character
        local humanoid: Humanoid? = character
            and character:FindFirstChildOfClass("Humanoid")
        local roundRole: string? = roundRoleByPlayer[player]
        local isAlive: boolean = humanoid ~= nil
            and humanoid.Health > 0
            and roundRole ~= "Dead"
        alive[player] = isAlive

        local hasGun: boolean = getPlayerWeapon(player, "Gun") ~= nil
        local hasKnife: boolean = not hasGun
            and getPlayerWeapon(player, "Knife") ~= nil
        local resolved: string? = nil

        -- Weapon possession is ground truth in MM2:
        -- 1) Anyone carrying the Gun is Sheriff or Hero (never Murderer).
        -- 2) Anyone carrying the Knife is Murderer.
        -- 3) Otherwise use server round data (ignoring dead entries), and
        --    only fall back to Murderer collision group when roundRole is
        --    absent so a Hero/Sheriff is never misidentified as Murderer.
        if hasGun then
            gunHolders[player] = true
            if roundRole == "Innocent"
                or roundRole == "Hero"
                or roundRole == "Dead" then
                resolved = "Hero"
            else
                resolved = "Sheriff"
            end
        elseif hasKnife then
            resolved = "Murderer"
        elseif roundRole == "Dead" then
            resolved = "Dead"
        elseif roundRole and roundRole ~= "Innocent" then
            resolved = roundRole
        elseif roundRole == nil and hasMurdererCollisionGroup(character) then
            resolved = "Murderer"
        end

        if resolved and resolved ~= "Dead" then
            special[player] = resolved

            if resolved == "Murderer" then
                local better: boolean = not murderer
                    or (isAlive and not alive[murderer])
                    or (isAlive == alive[murderer] and hasKnife and not murdererHasKnife)
                if better then
                    murderer = player
                    murdererHasKnife = hasKnife
                end
            elseif resolved == "Sheriff" or resolved == "Hero" then
                local better: boolean = not sheriff
                    or (isAlive and not alive[sheriff])
                    or (isAlive == alive[sheriff] and hasGun and not sheriffHasGun)
                if better then
                    sheriff = player
                    sheriffHasGun = hasGun
                end
            end
        end
    end

    local rolesKnown: boolean = next(special) ~= nil
    if roundLifecycleActive == false then
        rolesKnown = false
    end

    for _, player: Player in ipairs(Players:GetPlayers()) do
        local resolved: string? = special[player]
        if not resolved and rolesKnown then
            resolved = alive[player] and "Innocent" or "Dead"
        end
        roles[player] = resolved
    end

    local rolesChanged: boolean = roleIndex.rolesKnown ~= rolesKnown
        or roleIndex.murderer ~= murderer
        or roleIndex.sheriff ~= sheriff
    if not rolesChanged then
        for player: Player, role: string? in pairs(roles) do
            if roleIndex.roles[player] ~= role then
                rolesChanged = true
                break
            end
        end
    end
    if not rolesChanged then
        for player: Player in pairs(roleIndex.roles) do
            if roles[player] == nil and roleIndex.roles[player] ~= nil then
                rolesChanged = true
                break
            end
        end
    end

    roleIndex.roles = roles
    roleIndex.murderer = murderer
    roleIndex.sheriff = sheriff
    roleIndex.rolesKnown = rolesKnown

    -- A gun changing hands (sheriff died, someone picked it up) must
    -- re-sync the round data: the server knows the new Hero long before
    -- our cached copy does, and only a fresh remote read promotes the
    -- picker from "Innocent" and demotes the dead sheriff.
    local gunHoldersChanged: boolean = false
    do
        local previous: {[Player]: boolean} = roleIndex.gunHolders or {}
        for player in pairs(gunHolders) do
            if not previous[player] then
                gunHoldersChanged = true
            end
        end
        for player in pairs(previous) do
            if not gunHolders[player] then
                gunHoldersChanged = true
            end
        end
    end
    roleIndex.gunHolders = gunHolders
    if gunHoldersChanged and roundLifecycleActive ~= false then
        requestRoleRefresh()
    end

    if rolesChanged then

        if type(state.invalidateGameRoles) == "function" then
            state.invalidateGameRoles()
        elseif type(state.clearRoleMemo) == "function" then
            state.clearRoleMemo()
        end
        emitRoundRoles(rolesKnown)
    end

    if not rolesKnown and roundLifecycleActive ~= false then
        requestRoleRefresh()
    end
end

local function ensureRoleIndex(): ()

    if roleIndexDirty or os.clock() - roleIndexAt > 1 then
        rebuildRoleIndex()
    end
end

local function unwatchPlayer(player: Player): ()
    local connections: {RBXScriptConnection}? = roleWatchers[player]
    if not connections then
        return
    end
    roleWatchers[player] = nil
    for _, connection: RBXScriptConnection in ipairs(connections) do
        pcall(function(): ()
            connection:Disconnect()
        end)
    end
end

local function watchPlayer(player: Player): ()
    unwatchPlayer(player)
    local connections: {RBXScriptConnection} = {}
    local watchedTools: {[Tool]: boolean} = setmetatable({}, {__mode = "k"}) :: any

    local function watchTool(tool: Tool): ()
        if watchedTools[tool] then
            return
        end
        watchedTools[tool] = true

        table.insert(
            connections,
            tool.DescendantAdded:Connect(invalidateRoleCaches)
        )
        table.insert(
            connections,
            tool.DescendantRemoving:Connect(invalidateRoleCaches)
        )
    end

    local function watchContainer(container: Instance?): ()
        if not container then
            return
        end
        for _, child: Instance in ipairs(container:GetChildren()) do
            if child:IsA("Tool") then
                watchTool(child)
            end
        end
        table.insert(
            connections,
            container.ChildAdded:Connect(function(child: Instance): ()
                if child:IsA("Tool") then
                    watchTool(child)
                end
                invalidateRoleCaches()
            end)
        )
        table.insert(connections, container.ChildRemoved:Connect(invalidateRoleCaches))
    end

    local function watchCharacter(character: Model): ()
        invalidateRoleCaches()
        watchContainer(character)

        local function watchCollisionPart(part: BasePart): ()
            table.insert(
                connections,
                part:GetPropertyChangedSignal("CollisionGroup")
                    :Connect(invalidateRoleCaches)
            )
        end
        for _, child: Instance in ipairs(character:GetChildren()) do
            if child:IsA("BasePart") then
                watchCollisionPart(child)
            end
        end
        table.insert(
            connections,
            character.ChildAdded:Connect(function(child: Instance): ()
                if child:IsA("BasePart") then
                    watchCollisionPart(child)
                end
            end)
        )

        local humanoid: Humanoid? = character:FindFirstChildOfClass("Humanoid")
        if humanoid then
            table.insert(
                connections,
                humanoid.Died:Connect(invalidateRoleCaches)
            )
        end
    end

    table.insert(connections, player.CharacterAdded:Connect(watchCharacter))
    table.insert(connections, player.CharacterRemoving:Connect(invalidateRoleCaches))
    table.insert(
        connections,
        player.ChildAdded:Connect(function(child: Instance): ()
            if child:IsA("Backpack") then
                watchContainer(child)
                invalidateRoleCaches()
            end
        end)
    )
    watchContainer(player:FindFirstChildOfClass("Backpack"))
    if player.Character then
        watchCharacter(player.Character)
    end
    roleWatchers[player] = connections
end

for _, player: Player in ipairs(Players:GetPlayers()) do
    watchPlayer(player)
end
featureConnections.MM2RoleWatchAdded = Players.PlayerAdded:Connect(function(player: Player): ()
    watchPlayer(player)
    invalidateRoleCaches()
end)
featureConnections.MM2RoleWatchRemoving = Players.PlayerRemoving:Connect(function(player: Player): ()
    unwatchPlayer(player)
    invalidateRoleCaches()
end)
for _, weaponTag: string in ipairs({"Weapon_Knife", "Weapon_Gun"}) do
    featureConnections["MM2RoleTagAdded" .. weaponTag] = CollectionService
        :GetInstanceAddedSignal(weaponTag)
        :Connect(invalidateRoleCaches)
    featureConnections["MM2RoleTagRemoved" .. weaponTag] = CollectionService
        :GetInstanceRemovedSignal(weaponTag)
        :Connect(invalidateRoleCaches)
end

local function roundRolesKnown(): boolean
    ensureRoleIndex()
    return roleIndex.rolesKnown
end

local function getPlayerRole(player: Player): string?
    ensureRoleIndex()
    return roleIndex.roles[player]
end

local function findMM2Role(toolName: string, excludedPlayer: Player?): Player?
    ensureRoleIndex()
    local wanted: string = toolName == "Knife" and "Murderer" or "Sheriff"
    for player: Player, role: string? in pairs(roleIndex.roles) do
        if player ~= excludedPlayer
            and (role == wanted or (wanted == "Sheriff" and role == "Hero")) then
            return player
        end
    end
    return nil
end

local function findPlayerByRoundRole(role: string): Player?
    for key, data in pairs(mm2RoundData) do
        if type(data) == "table"
            and not isRoundEntryDead(data)
            and data.Role == role then
            local player: Player? = playerFromRoundKey(key, data)
            if player and isPlayerAlive(player) then
                if role == "Murderer" and getPlayerWeapon(player, "Gun") ~= nil then
                    continue
                end
                if (role == "Sheriff" or role == "Hero")
                    and getPlayerWeapon(player, "Knife") ~= nil then
                    continue
                end
                return player
            end
        end
    end
    return nil
end

local function hasActiveRoundRoles(): boolean
    return roundRolesKnown()
end

local function findMurderer(): Player?
    ensureRoleIndex()
    for _, player: Player in ipairs(Players:GetPlayers()) do
        if isPlayerAlive(player)
            and getPlayerWeapon(player, "Gun") == nil
            and getPlayerWeapon(player, "Knife") ~= nil then
            return player
        end
    end
    local candidate: Player? = roleIndex.murderer or findPlayerByRoundRole("Murderer")
    if candidate and getPlayerWeapon(candidate, "Gun") ~= nil then
        return nil
    end
    return candidate
end

local function findSheriff(): Player?
    ensureRoleIndex()
    for _, player: Player in ipairs(Players:GetPlayers()) do
        if isPlayerAlive(player)
            and getPlayerWeapon(player, "Knife") == nil
            and getPlayerWeapon(player, "Gun") ~= nil then
            return player
        end
    end
    local candidate: Player? = roleIndex.sheriff
        or findPlayerByRoundRole("Sheriff")
        or findPlayerByRoundRole("Hero")
    if candidate and getPlayerWeapon(candidate, "Knife") ~= nil then
        return nil
    end
    return candidate
end

local MM2_MAP_COIN_CONTAINERS: {string} = {
    "CoinContainer",
    "CoinAreas",
    "Coins",
}

local LOBBY_MODEL_NAMES: {string} = {
    "Lobby",
    "MainLobby",
    "RegularLobby",
}

local function isLobbyName(name: string): boolean
    for _, candidate: string in ipairs(LOBBY_MODEL_NAMES) do
        if name == candidate then
            return true
        end
    end
    return string.find(string.lower(tostring(name)), "lobby", 1, true) ~= nil
end

local function isLobbyModel(object: Instance): boolean
    if isLobbyName(object.Name) then
        return true
    end
    if object:FindFirstChild("VotePad1")
        or object:FindFirstChild("VotePads")
        or object:FindFirstChild("VoteIcons") then
        return true
    end
    return false
end

local function isMM2MapModel(object: Instance): boolean
    if not object:IsA("Model") or isLobbyModel(object) then
        return false
    end
    for _, containerName: string in ipairs(MM2_MAP_COIN_CONTAINERS) do
        if object:FindFirstChild(containerName) then
            return true
        end
    end
    if object:FindFirstChild("GunDrop") then
        return true
    end
    return false
end

local mm2MapCache: {map: Instance?, at: number} = {map = nil, at = -math.huge}

local function findMM2MapUncached(): Instance?
    for _, object: Instance in ipairs(workspace:GetChildren()) do
        if isMM2MapModel(object) then
            return object
        end
    end

    for _, object: Instance in ipairs(workspace:GetChildren()) do
        if object:IsA("Model")
            and not isLobbyModel(object)
            and object:FindFirstChild("Spawns") then
            return object
        end
    end
    return nil
end

local function findMM2Map(): Instance?
    local cached: Instance? = mm2MapCache.map
    if cached and cached.Parent == workspace and isMM2MapModel(cached) then
        return cached
    end
    if os.clock() - mm2MapCache.at < 0.1 then
        return (cached and cached.Parent == workspace) and cached or nil
    end
    mm2MapCache.at = os.clock()
    mm2MapCache.map = findMM2MapUncached()
    return mm2MapCache.map
end

local droppedGunCache: {gun: (Model | BasePart)?, at: number} =
    {gun = nil, at = -math.huge}
local lastGunSweepAt: number = -math.huge

local function isLooseGun(object: Instance): boolean
    if not object:IsA("Tool") then
        return false
    end
    if object.Name ~= "Gun" and not CollectionService:HasTag(object, "Weapon_Gun") then
        return false
    end

    return object:IsDescendantOf(workspace)
        and not object:FindFirstAncestorOfClass("Backpack")
        and (object.Parent == workspace or object.Parent == findMM2Map()
            or object.Parent ~= nil and not object.Parent:FindFirstChildOfClass("Humanoid"))
end

local function resolveGunPart(object: Instance): (Model | BasePart)?
    if object:IsA("Model") or object:IsA("BasePart") then
        return object :: any
    end
    local handle: Instance? = object:FindFirstChild("Handle")
        or object:FindFirstChildWhichIsA("BasePart")
    return (handle and handle:IsA("BasePart")) and handle or nil
end

local function findDroppedGunUncached(): (Model | BasePart)?
    local map: Instance? = findMM2Map()
    local candidate: Instance? = map and map:FindFirstChild("GunDrop")
    if not candidate then
        candidate = workspace:FindFirstChild("GunDrop")
    end
    if candidate and (candidate:IsA("Model") or candidate:IsA("BasePart")) then
        return candidate :: any
    end

    for _, taggedDrop: Instance in ipairs(CollectionService:GetTagged("GunDrop")) do
        if taggedDrop:IsDescendantOf(workspace)
            and (taggedDrop:IsA("Model") or taggedDrop:IsA("BasePart")) then
            return taggedDrop :: any
        end
    end

    for _, object: Instance in ipairs(workspace:GetChildren()) do
        if object:IsA("Model") or object:IsA("Folder") then
            local childDrop: Instance? = object:FindFirstChild("GunDrop")
            if childDrop and (childDrop:IsA("Model") or childDrop:IsA("BasePart")) then
                return childDrop :: any
            end
        end
    end

    for _, object: Instance in ipairs(CollectionService:GetTagged("Weapon_Gun")) do
        if isLooseGun(object) then
            local part: (Model | BasePart)? = resolveGunPart(object)
            if part then
                return part
            end
        end
    end

    for _, object: Instance in ipairs(workspace:GetChildren()) do
        if isLooseGun(object) then
            local part: (Model | BasePart)? = resolveGunPart(object)
            if part then
                return part
            end
        end
    end

    if os.clock() - lastGunSweepAt < 1.5 then
        return nil
    end
    lastGunSweepAt = os.clock()
    local deepCandidate: Instance? = (map and map:FindFirstChild("GunDrop", true))
        or workspace:FindFirstChild("GunDrop", true)
    if deepCandidate
        and (deepCandidate:IsA("Model") or deepCandidate:IsA("BasePart")) then
        return deepCandidate :: any
    end
    return nil
end

local function findDroppedGun(): (Model | BasePart)?
    local cached: (Model | BasePart)? = droppedGunCache.gun
    if cached and cached.Parent and cached:IsDescendantOf(workspace) then
        return cached
    end
    -- Negative results are only held for ~3 frames. The old 0.4 s
    -- cache meant a gun dropped just after a scan stayed invisible
    -- to Auto Get Gun for almost half a second; the cheap checks
    -- (direct GunDrop child, Weapon_Gun tags, workspace children)
    -- run first every call and the expensive descendant sweep keeps
    -- its own 3 s gate below.
    if os.clock() - droppedGunCache.at < 0.05 then
        return nil
    end
    droppedGunCache.at = os.clock()
    droppedGunCache.gun = findDroppedGunUncached()
    return droppedGunCache.gun
end

local function createMM2Marker(folder, adornee, labelText, color, transparency)
    local highlight = Instance.new("Highlight")
    highlight.Name = labelText .. "Highlight"
    highlight.Adornee = adornee
    highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
    highlight.FillColor = color
    highlight.FillTransparency = transparency or 0.68
    highlight.OutlineColor = color
    highlight.OutlineTransparency = 0
    highlight.Parent = adornee

    local highlightReference = Instance.new("ObjectValue")
    highlightReference.Name = labelText .. "HighlightReference"
    highlightReference.Value = highlight
    highlightReference.Parent = folder

    local head = adornee:IsA("Model")
        and (adornee:FindFirstChild("Head")
            or adornee:FindFirstChild("HumanoidRootPart")
            or adornee:FindFirstChild("Handle", true)
            or adornee:FindFirstChildWhichIsA("BasePart", true))
        or adornee

    if head and head:IsA("BasePart") then
        local billboard = Instance.new("BillboardGui")
        billboard.Name = labelText .. "Label"
        billboard.Adornee = head
        billboard.AlwaysOnTop = true
        billboard.LightInfluence = 0
        billboard.MaxDistance = 1500
        billboard.Size = UDim2.fromOffset(150, 22)
        billboard.StudsOffset = Vector3.new(0, 3.5, 0)
        billboard.Parent = head

        local billboardReference = Instance.new("ObjectValue")
        billboardReference.Name = labelText .. "LabelReference"
        billboardReference.Value = billboard
        billboardReference.Parent = folder

        local text = Instance.new("TextLabel")
        text.BackgroundTransparency = 1
        text.BorderSizePixel = 0
        text.Font = Enum.Font.GothamBold
        text.Size = UDim2.fromScale(1, 1)
        text.Text = labelText
        text.TextColor3 = color
        text.TextSize = 14
        text.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
        text.TextStrokeTransparency = 0.3
        text.Parent = billboard
    end
end

local function createMM2Cham(folder, adornee, color, transparency)
    local highlight = Instance.new("Highlight")
    highlight.Name = "WurstCham"
    highlight.Adornee = adornee
    highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
    highlight.FillColor = color
    highlight.FillTransparency = transparency
    highlight.OutlineColor = color
    highlight.OutlineTransparency = math.clamp(transparency + 0.15, 0, 1)
    highlight.Parent = adornee

    local reference = Instance.new("ObjectValue")
    reference.Name = "ChamReference"
    reference.Value = highlight
    reference.Parent = folder
end

local function getPlayerPerk(player: Player): string?
    local char: Model? = player.Character
    if char then
        local perkAttr: any = char:GetAttribute("Perk") or player:GetAttribute("Perk")
        if type(perkAttr) == "string" and perkAttr ~= "" then
            return perkAttr
        end
    end
    for key: any, data: any in pairs(mm2RoundData) do
        if playerFromRoundKey(key, data) == player and type(data) == "table" then
            local perk: any = data.Perk or data.EquippedPerk or data.perk
            if type(perk) == "string" and perk ~= "" then
                return perk
            end
        end
    end
    if char then
        if char:FindFirstChild("Trap") or (player:FindFirstChild("Backpack") and player.Backpack:FindFirstChild("Trap")) then
            return "Trap"
        end
        if char:FindFirstChild("FakeGun") or (player:FindFirstChild("Backpack") and player.Backpack:FindFirstChild("FakeGun")) then
            return "FakeGun"
        end
    end
    return nil
end

local function registerMM2Roles(): ()
    registerRoleProvider({
        Name = "MM2",
        ReplacesTeams = true,
        DeadRoles = {"Dead"},
        Roles = {"Murderer", "Sheriff", "Hero", "Innocent", "Dead"},
        Colors = {
            Murderer = mm2Settings.murdererColor,
            Sheriff = mm2Settings.sheriffColor,
            Hero = mm2Settings.heroColor,
            Innocent = mm2Settings.innocentColor,
            Dead = mm2Settings.deadColor,
        },
        Get = function(player: Player): string?
            return getPlayerRole(player)
        end,
        GetPerk = function(player: Player): string?
            return getPlayerPerk(player)
        end,
        GetColor = function(roleName: string): Color3?
            if roleName == "Murderer" then return mm2Settings.murdererColor end
            if roleName == "Sheriff" then return mm2Settings.sheriffColor end
            if roleName == "Hero" then return mm2Settings.heroColor end
            if roleName == "Innocent" then return mm2Settings.innocentColor end
            if roleName == "Dead" then return mm2Settings.deadColor end
            return nil
        end,
        SetColor = function(roleName: string, colour: Color3): ()
            if roleName == "Murderer" then
                mm2Settings.murdererColor = colour
            elseif roleName == "Sheriff" then
                mm2Settings.sheriffColor = colour
            elseif roleName == "Hero" then
                mm2Settings.heroColor = colour
            elseif roleName == "Innocent" then
                mm2Settings.innocentColor = colour
            elseif roleName == "Dead" then
                mm2Settings.deadColor = colour
            end
        end,
    })
end

local primeRoundState: () -> ()
local setRoundPhase: (string, string) -> ()
local lastPhase: string = "unknown"

if mm2GameplayRemotes then
    local playerDataChanged = mm2GameplayRemotes:FindFirstChild("PlayerDataChanged")
    if playerDataChanged and playerDataChanged:IsA("RemoteEvent") then
        featureConnections.MM2PlayerDataChanged = playerDataChanged.OnClientEvent:Connect(function(newData)
            if type(newData) == "table" and hasValidRoundRoleData(newData) then
                roundLifecycleActive = true
                mm2MapCache.at = -math.huge
                mm2RoundData = newData
                lastRoleRefreshAt = os.clock()
                invalidateRoleCaches()
                if rebuildRoleIndex then
                    rebuildRoleIndex()
                end
                if setRoundPhase and findMM2Map() then
                    lastPhase = "map"
                    setRoundPhase("map", "PlayerDataChanged")
                end
            elseif type(newData) ~= "table"
                or next(newData) == nil
                or roundLifecycleActive == false then
                mm2RoundData = {}
                invalidateRoleCaches()
                if rebuildRoleIndex then
                    rebuildRoleIndex()
                end
            else
                for key: any, value: any in pairs(newData) do
                    mm2RoundData[key] = value
                end
                lastRoleRefreshAt = os.clock()
                invalidateRoleCaches()
                if rebuildRoleIndex then
                    rebuildRoleIndex()
                end
            end
        end)
    end

    local roleSelect = mm2GameplayRemotes:FindFirstChild("RoleSelect")
    if roleSelect and roleSelect:IsA("RemoteEvent") then
        featureConnections.MM2RoleSelect = roleSelect.OnClientEvent:Connect(function(localRole: any)
            roundLifecycleActive = true
            mm2MapCache.at = -math.huge
            mm2RoundData = {}
            if type(localRole) == "string"
                and (localRole == "Murderer"
                    or localRole == "Sheriff"
                    or localRole == "Hero"
                    or localRole == "Innocent") then
                mm2RoundData[LocalPlayer.Name] = {
                    Name = LocalPlayer.Name,
                    UserId = LocalPlayer.UserId,
                    Role = localRole,
                }
            end
            invalidateRoleCaches()
            if rebuildRoleIndex then
                rebuildRoleIndex()
            end
            if primeRoundState then
                primeRoundState()
            end
            if setRoundPhase then
                lastPhase = "map"
                setRoundPhase("map", "RoleSelect")
            end
        end)
    end

    for _, remoteName: string in ipairs({"ShowRoleSelect", "ShowRoleSelectNew"}) do
        local showRole = mm2GameplayRemotes:FindFirstChild(remoteName)
        if showRole and showRole:IsA("RemoteEvent") then
            featureConnections["MM2" .. remoteName] = showRole.OnClientEvent:Connect(function()
                roundLifecycleActive = true
                mm2MapCache.at = -math.huge
                invalidateRoleCaches()
                if primeRoundState then
                    primeRoundState()
                end
                if setRoundPhase then
                    lastPhase = "map"
                    setRoundPhase("map", remoteName)
                end
            end)
        end
    end
end

local roundTimer: {endsAt: number?} = {endsAt = nil}
local timerRemotes = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
local timerGameplay = timerRemotes and timerRemotes:FindFirstChild("Gameplay")
local timerRoundStart = timerGameplay and timerGameplay:FindFirstChild("RoundStart")
local timerRoundEnd = timerGameplay and timerGameplay:FindFirstChild("RoundEndFade")
local sessionRoundActive = false

if timerRoundStart and timerRoundStart:IsA("RemoteEvent") then
    featureConnections.MM2TimerTrackerStart = timerRoundStart.OnClientEvent:Connect(
        function(duration, startPlayerData)
            duration = tonumber(duration)
            roundTimer.endsAt = duration and os.clock() + duration or nil
            if not duration or duration <= 0 then
                mm2RoundData = {}
                sessionRoundActive = false
            elseif type(startPlayerData) == "table"
                and hasValidRoundRoleData(startPlayerData) then
                mm2RoundData = startPlayerData
            end
            invalidateRoleCaches()
            roundLifecycleActive = duration ~= nil and duration > 0
            roleRefreshGeneration += 1
            if duration and duration > 0 then
                mm2MapCache.at = -math.huge
                primeRoundState()
                lastPhase = "map"
                setRoundPhase("map", "RoundStart")
            end
            if duration and duration > 0
                and not sessionRoundActive
                and state.sessionInfo
                and state.sessionInfo.addRound then
                sessionRoundActive = true
                state.sessionInfo.addRound()
            end
        end
    )
end
if timerRoundEnd and timerRoundEnd:IsA("RemoteEvent") then
    featureConnections.MM2TimerTrackerEnd = timerRoundEnd.OnClientEvent:Connect(function()
        roundTimer.endsAt = nil
        sessionRoundActive = false
        roundLifecycleActive = false
        invalidateRoleCaches()
        roleRefreshGeneration += 1
        mm2RoundData = {}
        setRoundPhase("lobby", "RoundEndFade")
    end)
end

local roundPhase: string = "unknown"
local roundPhaseListeners: {(string, string) -> ()} = {}

local function emitRoundPhase(phase: string, reason: string): ()
    for _, listener: (string, string) -> () in ipairs(roundPhaseListeners) do
        pcall(listener, phase, reason)
    end
end

setRoundPhase = function(phase: string, reason: string): ()
    if roundPhase == phase then
        return
    end
    roundPhase = phase
    emitRoundPhase(phase, reason)
end

local function onRoundPhase(listener: (string, string) -> ()): () -> ()
    table.insert(roundPhaseListeners, listener)
    task.defer(function(): ()
        if table.find(roundPhaseListeners, listener) then
            pcall(listener, roundPhase, "subscribe")
        end
    end)
    return function(): ()
        local index: number? = table.find(roundPhaseListeners, listener)
        if index then
            table.remove(roundPhaseListeners, index)
        end
    end
end

local function findLobbyModel(): Instance?
    for _, object: Instance in ipairs(workspace:GetChildren()) do
        if isLobbyName(object.Name) or isLobbyModel(object) then
            return object
        end
    end
    return nil
end

local function isRootNearLobby(root: BasePart, lobby: Instance): boolean
    local okRoot: boolean, rootPos: any = pcall(function(): any
        return root.Position
    end)
    if not okRoot or typeof(rootPos) ~= "Vector3" then
        return false
    end
    local votePads: Instance? = lobby:FindFirstChild("VotePads", true)
    local refPart: BasePart? = nil
    if votePads then
        refPart = votePads:FindFirstChildWhichIsA("BasePart", true)
    end
    if not refPart then
        local spawns: Instance? = lobby:FindFirstChild("Spawns", true)
        if spawns then
            refPart = spawns:FindFirstChildWhichIsA("BasePart", true)
        end
    end
    if not refPart then
        refPart = lobby:FindFirstChildWhichIsA("BasePart", true)
    end
    if refPart then
        local okDist: boolean, dist: any = pcall(function(): any
            return (rootPos - refPart.Position).Magnitude
        end)
        if okDist and type(dist) == "number" and dist <= 350 then
            return true
        end
    end
    return false
end

local function detectRoundPhase(): string
    local character: Model? = LocalPlayer.Character
    if not character then
        return "lobby"
    end
    local root: BasePart? = character:FindFirstChild("HumanoidRootPart") :: BasePart?
    if not root then
        return "lobby"
    end

    local lobby: Instance? = findLobbyModel()
    if lobby and (root:IsDescendantOf(lobby) or isRootNearLobby(root, lobby)) then
        return "lobby"
    end
    if findMM2Map() then
        return "map"
    end

    return roundPhase == "map" and "map" or "lobby"
end

primeRoundState = function(): ()
    roleRefreshGeneration += 1
    local generation: number = roleRefreshGeneration
    requestRoleRefresh(true)
    task.spawn(function(): ()
        for _, delay: number in ipairs({0.05, 0.15, 0.3, 0.5, 0.8, 1.2, 2.0, 3.0}) do
            task.wait(delay)
            if generation ~= roleRefreshGeneration or roundRolesKnown() then
                break
            end
            requestRoleRefresh(true)
        end
    end)
end

local phaseElapsed: number = 0
lastPhase = detectRoundPhase()
if lastPhase == "map" then
    roundLifecycleActive = true
    primeRoundState()
end
featureConnections.MM2RoundPhase = TaskManager:Connect(function(deltaTime: number): ()
    phaseElapsed += deltaTime
    if phaseElapsed < 0.05 then
        return
    end
    phaseElapsed = 0
    local phase: string = detectRoundPhase()
    if phase == lastPhase then
        return
    end
    lastPhase = phase
    if phase == "map" then
        if not hasValidRoundRoleData(mm2RoundData) then
            mm2RoundData = {}
        end
        roundLifecycleActive = true
        invalidateRoleCaches()
        primeRoundState("map")
        setRoundPhase("map", "teleport")
    else
        mm2RoundData = {}
        roundLifecycleActive = false
        roundTimer.endsAt = nil
        invalidateRoleCaches()
        roleRefreshGeneration += 1
        setRoundPhase("lobby", "teleport")
    end
end)
setRoundPhase(lastPhase, "boot")

local roundTimerPartCache: {part: Instance?, at: number} =
    {part = nil, at = -math.huge}

local function findRoundTimerPart(): Instance?
    local cached: Instance? = roundTimerPartCache.part
    if cached and cached.Parent then
        return cached
    end
    if os.clock() - roundTimerPartCache.at < 1 then
        return cached
    end
    roundTimerPartCache.at = os.clock()
    local found: Instance? = workspace:FindFirstChild("RoundTimerPart")
    roundTimerPartCache.part = found
    return found
end

local function readRoundTimerPartSeconds(): number?
    local part: Instance? = findRoundTimerPart()
    if not part then
        return nil
    end
    local remaining: number? = tonumber(part:GetAttribute("Time") :: any)
    if not remaining or remaining <= 0 or remaining > 600 then
        return nil
    end
    return remaining
end

local hudTimerCache: {frame: Instance?, label: Instance?, at: number} =
    {frame = nil, label = nil, at = -math.huge}

local function findHudTimerLabel(): Instance?
    local cached: Instance? = hudTimerCache.label
    if cached and cached.Parent then
        return cached
    end
    if os.clock() - hudTimerCache.at < 1 then
        return cached
    end
    hudTimerCache.at = os.clock()
    local playerGui: PlayerGui? = LocalPlayer:FindFirstChildOfClass("PlayerGui")
    local mainGui: Instance? = playerGui and playerGui:FindFirstChild("MainGUI")
    local gameFrame: Instance? = mainGui and mainGui:FindFirstChild("Game")
    local frame: Instance? = gameFrame and gameFrame:FindFirstChild("Timer")

    if not frame then
        frame = mainGui and mainGui:FindFirstChild("Timer", true)
    end
    hudTimerCache.frame = (frame and frame:IsA("GuiObject")) and frame or nil

    local label: Instance? = frame
        and (frame:FindFirstChild("XPText")
            or frame:FindFirstChild("Timer")
            or frame:FindFirstChildWhichIsA("TextLabel", true))
    hudTimerCache.label = (label and label:IsA("TextLabel")) and label or nil
    return hudTimerCache.label
end

local function parseHudTimerSeconds(text: string?): number?
    if type(text) ~= "string" or text == "" then
        return nil
    end
    local minutes: string?, seconds: string? = text:match("^%s*(%d+):(%d%d)s?%s*$")
    if minutes and seconds then
        return tonumber(minutes) * 60 + tonumber(seconds)
    end
    local whole: string? = text:match("^%s*(%d%d?)s?%s*$")
    if whole then
        return tonumber(whole)
    end
    return nil
end

local function isHudTimerVisible(label: Instance): boolean

    local ancestor: Instance? = label
    while ancestor do
        if ancestor:IsA("GuiObject") and ancestor.Visible == false then
            return false
        end
        ancestor = ancestor.Parent
    end
    return true
end

local function readHudTimerSeconds(): number?
    local label: Instance? = findHudTimerLabel()
    if not label then
        return nil
    end
    if not isHudTimerVisible(label) then
        return nil
    end
    local remaining: number? = parseHudTimerSeconds((label :: any).Text)
    if not remaining or remaining <= 0 or remaining > 600 then
        return nil
    end
    return remaining
end

local lastAttributeRemaining: number? = nil
local lastAttributeChangeAt: number = -math.huge
local clockElapsed: number = 0
featureConnections.MM2RoundClock = TaskManager:Connect(function(deltaTime: number): ()
    clockElapsed += deltaTime
    if clockElapsed < 0.25 then
        return
    end
    clockElapsed = 0
    local remaining: number? = readRoundTimerPartSeconds()
        or readHudTimerSeconds()
    if not remaining or roundPhase == "lobby" then

        lastAttributeRemaining = nil
        return
    end

    if lastAttributeRemaining == nil
        or math.abs(remaining - lastAttributeRemaining) > 0.01 then
        lastAttributeChangeAt = os.clock()
    end
    lastAttributeRemaining = remaining
    if os.clock() - lastAttributeChangeAt > 3 then
        return
    end
    roundTimer.endsAt = os.clock() + remaining
    if roundLifecycleActive == nil then
        roundLifecycleActive = true
    end
end)

requestRoleRefresh(true)

-- Pure prediction helpers: shared by Shoot/Knife and exercised without Roblox.
local predictionMath = {}
function predictionMath.finite(value: any): boolean
    return type(value) == "number" and value == value and math.abs(value) < math.huge
end

function predictionMath.interceptTime(offset: Vector3, velocity: Vector3, speed: number): number?
    if not predictionMath.finite(speed) or speed <= 1 then return nil end
    local a: number = velocity:Dot(velocity) - speed * speed
    local b: number = 2 * offset:Dot(velocity)
    local c: number = offset:Dot(offset)
    if not predictionMath.finite(a) or not predictionMath.finite(b)
        or not predictionMath.finite(c) then return nil end
    if c < 1e-8 then return 0 end
    local time: number? = nil
    if math.abs(a) < 1e-6 then
        if b < -1e-6 then time = -c / b end
    else
        local discriminant: number = b * b - 4 * a * c
        if discriminant >= 0 then
            local root: number = math.sqrt(discriminant)
            local first: number = (-b - root) / (2 * a)
            local second: number = (-b + root) / (2 * a)
            if first >= 0 then time = first end
            if second >= 0 and (not time or second < time) then time = second end
        end
    end
    -- A long/unsolvable trajectory is not a reliable shot; do not clamp it
    -- into a fictitious intercept. Covers the configured 400-stud knife range.
    return time and predictionMath.finite(time) and time <= 5 and time or nil
end

local lastLatencyReadAt: number = -math.huge

-- Two engine readings of the same path. They disagree: in the 2026-10-18
-- session GetNetworkPing read 314/342 ms on two shots whose measured
-- confirmation echo was 152/164 ms, and it read 241 ms at session start when
-- Data Ping read 130 and the echo came back in 144. Across 17 recorded shots
-- Data Ping was within 30 ms of the echo in 12, GetNetworkPing in 3.
-- This legacy smoothed fallback takes the lower of the two: over-leading is
-- the failure this data shows, and Prediction's median rejects a one-off dip.
-- The live predictor itself prefers Data Ping when both readings are present.
local function readLatencyReadings(): (number?, number?)
    local engine: number? = nil
    local data: number? = nil
    pcall(function(): ()
        local direct: any = (LocalPlayer :: any).GetNetworkPing
        if type(direct) == "function" then
            local okDirect: boolean, seconds: any = pcall(direct, LocalPlayer)
            if okDirect and predictionMath.finite(seconds)
                and (seconds :: number) > 0.001 and (seconds :: number) <= 2 then
                engine = seconds :: number
            end
        end
        local network: Instance? = Stats:FindFirstChild("Network")
        local serverItems: Instance? = network
            and network:FindFirstChild("ServerStatsItem")
        local pingItem: any = serverItems and serverItems:FindFirstChild("Data Ping")
        if pingItem and type(pingItem.GetValue) == "function" then
            local pingMilliseconds: number? = tonumber(pingItem:GetValue())
            if predictionMath.finite(pingMilliseconds)
                and pingMilliseconds >= 10 and pingMilliseconds <= 2000 then
                data = pingMilliseconds / 1000
            end
        end
    end)
    return engine, data
end

local function getEstimatedLatency(): number
    local now: number = os.clock()
    if now - lastLatencyReadAt < 0.1 then
        return math.clamp(mm2Settings.predictionRtt, 0.02, 0.6)
    end
    local elapsed: number = now - lastLatencyReadAt
    lastLatencyReadAt = now
    local measuredRtt: number = mm2Settings.predictionRtt
    pcall(function(): ()
        local engine: number?, data: number? = readLatencyReadings()
        local lower: number? = nil
        if engine and data then
            lower = math.min(engine, data)
        else
            lower = engine or data
        end
        if lower then
            measuredRtt = lower
        end
    end)
    -- Time-based smoothing: sampling frequency must not change the RTT.
    -- The upper bound covers the 400-500 ms sessions in TestingStuff; the
    -- old 0.3 cap silently under-led every high-ping shot by 200+ ms.
    local alpha: number = 1 - math.exp(-math.min(elapsed, 1) / 0.5)
    mm2Settings.predictionRtt += (measuredRtt - mm2Settings.predictionRtt) * alpha

    return math.clamp(
        mm2Settings.predictionRtt,
        0.02,
        0.6
    )
end

local trajectoryCalibration: any = nil

local function getGunOriginCFrame(character: Model, gun: Tool?): CFrame?
    local root: BasePart? = character:FindFirstChild("HumanoidRootPart") :: BasePart?
    local attachment: Attachment? = root
        and root:FindFirstChild("GunRaycastAttachment")
        :: Attachment?
    if attachment and attachment:IsA("Attachment") then
        return attachment.WorldCFrame
    end

    if gun then
        for _, partName: string in ipairs({"Muzzle", "Handle"}) do
            local part: Instance? = gun:FindFirstChild(partName)
            if part and part:IsA("BasePart") then
                return part.CFrame
            end
        end
    end
    for _, partName: string in ipairs({"RightHand", "Right Arm", "Head"}) do
        local part: Instance? = character:FindFirstChild(partName)
        if part and part:IsA("BasePart") then
            return part.CFrame
        end
    end
    local camera: Camera? = workspace.CurrentCamera
    if camera and root then
        return CFrame.new(root.Position + Vector3.new(0, 1.5, 0))
            * (camera.CFrame - camera.CFrame.Position)
    end
    return root and root.CFrame or nil
end

local function createTrajectoryCalibration(): any
    type TrajectoryPoint = {
        dt: number,
        serverTime: number,
        pingMs: number,
        position: {number},
        velocity: {number},
        moveDirection: {number},
        humanoidState: string,
        grounded: boolean,
        jumping: boolean,
    }
    -- The movement window that ended at the shot. `dt` is negative (seconds
    -- before the shot), unlike TrajectoryPoint's non-negative `dt`, so an
    -- alternative predictor can be replayed from the same inputs offline.
    type HistoryPoint = {
        dt: number,
        position: {number},
        velocity: {number},
        humanoidState: string,
        grounded: boolean,
        -- The replicated control input. It leads the velocity on a turn, so
        -- recording it lets an offline replay test an input-based turn instead
        -- of needing another session.
        moveDirection: {number}?,
        -- Offset from the root to the part the aim fell on. The v64 misses
        -- passed 0.2-0.3 studs below the root, which is under the torso: a
        -- replay needs this to test aiming at the torso instead of the root.
        aimOffset: {number}?,
    }
    type RunningStats = {
        count: number,
        mean: number,
        m2: number,
        minimum: number,
        maximum: number,
    }
    type PendingGun = {
        shotId: string?,
        attemptCounted: boolean?,
        tool: Tool,
        activatedAt: number,
        origin: Vector3?,
        requestedAim: Vector3?,
        pingMs: number,
        targetUserId: number?,
        targetName: string?,
        targetTrajectory: {TrajectoryPoint},
        targetHistory: {HistoryPoint},
        lastTrajectorySampleAt: number,
        confirmedAt: number?,
        latencyMs: number?,
        confirmedEndpoint: Vector3?,
        confirmedHitTarget: boolean?,
        -- Everything below exists so a saved session can answer "did the shot
        -- land, where, and when" without a second session: the server-clock
        -- round trip, the part that was actually hit and its size, and the
        -- target's health before and after.
        serverActivatedAt: number?,
        serverConfirmedAt: number?,
        shotMode: string?,
        silentSpawn: string?,
        confirmedServerOrigin: Vector3?,
        confirmedHitPart: string?,
        confirmedHitPartPosition: Vector3?,
        confirmedHitPartSize: Vector3?,
        rootAtConfirmation: {[string]: any}?,
        lastSeenPosition: Vector3?,
        targetHealthAtAim: number?,
        targetHealthAtConfirmation: number?,
        targetHealthAfter: number?,
        targetHealthDropAt: number?,
        targetHealthDropServerTime: number?,
        targetDiedAt: number?,
        targetDiedServerTime: number?,
        healthConnection: RBXScriptConnection?,
        samplingStoppedAt: number?,
        samplingStoppedReason: string?,
        trajectoryCapped: boolean?,
        rttEngineAtConfirmation: number?,
        rttDataAtConfirmation: number?,
    }
    type PendingKnife = {
        shotId: string?,
        attemptCounted: boolean?,
        tool: Tool,
        activatedAt: number,
        origin: Vector3?,
        requestedAim: Vector3?,
        pingMs: number,
        targetUserId: number?,
        targetName: string?,
        targetTrajectory: {TrajectoryPoint},
        targetHistory: {HistoryPoint},
        lastTrajectorySampleAt: number,
        serverActivatedAt: number?,
        samplingStoppedAt: number?,
        samplingStoppedReason: string?,
        trajectoryCapped: boolean?,
        lastSeenPosition: Vector3?,
        targetHealthAtAim: number?,
        targetHealthAfter: number?,
        healthConnection: RBXScriptConnection?,
    }
    type KnifeTrack = {
        shotId: string?,
        attemptCounted: boolean?,
        startedAt: number,
        previousAt: number?,
        previousPosition: Vector3?,
        speeds: {number},
        rawSpeed: number?,
        spawnDelayMs: number,
        pingMs: number,
        targetUserId: number?,
        targetName: string?,
        targetTrajectory: {TrajectoryPoint},
        targetHistory: {HistoryPoint},
        lastTrajectorySampleAt: number,
        destroyConnection: RBXScriptConnection?,
    }
    type CalibrationEvent = {
        shotId: string?,
        settings: any?,
        phase: string?,
        sessionId: string?,
        buildStamp: string?,
        kind: string,
        serverTime: number,
        pingMs: number,
        latencyMs: number?,
        distance: number?,
        speed: number?,
        rawSpeed: number?,
        samples: number?,
        reason: string?,
        targetUserId: number?,
        targetName: string?,
        targetState: string?,
        targetJumped: boolean?,
        targetTrajectory: {TrajectoryPoint}?,
        targetHistory: {HistoryPoint}?,
        observedDisplacement: {number}?,
        constantVelocityResidual: {number}?,
        horizontalLeadSeconds: number?,
        verticalLeadSeconds: number?,
        endpoint: {number}?,
        origin: {number}?,
        observedTargetPosition: {number}?,
        endpointToObservedTarget: number?,
        shotRange: number?,
        hitPartPath: string?,
        evidence: string?,
        targetPositionScope: string?,
        hitTarget: boolean?,
        pingBucket: string?,
        bestMotionModel: string?,
        motionModelErrors: {[string]: number}?,
        evaluationSeconds: number?,
        blockedName: string?,
        blockedTransparency: number?,
        blockedCanCollide: boolean?,
        blockedSkipped: boolean?,
        blockedDistance: number?,
        rttEngine: number?,
        rttData: number?,
        occluder: any?,
    }
    type Estimates = {
        gunAcceptanceMs: number?,
        knifeSpeed: number?,
        confirmedShots: number,
        confirmedThrows: number,
        liveGunAcceptanceMs: number?,
        liveGunSamples: number,
        maxStabDistance: number?,
        knifeSpawnDelayMs: number?,
        confirmedSpawnDelays: number,
        -- Direct endpoint error of our own predicted point, in studs,
        -- measured against where the target really was at the scoring
        -- instant. This is the number the accuracy question needs; it
        -- used to require an offline replay of aim + trajectory.
        predictionErrorSamples: number,
        predictionErrorMedianStuds: number?,
        predictionErrorMeanStuds: number?,
    }
    type Controller = {
        start: (self: Controller) -> (),
        save: (self: Controller, reason: string?) -> boolean,
        reset: (self: Controller) -> (),
        destroy: (self: Controller) -> (),
        status: (self: Controller) -> string,
        getEstimates: (self: Controller) -> Estimates,
        noteAuthoredShot: (self: Controller, info: any) -> (),
        noteTracerData: (self: Controller, info: any) -> (),
    }

    local OUTPUT_ROOT: string = host.PRODUCT.storageFolder
    local OUTPUT_FOLDER: string = OUTPUT_ROOT .. "/Telemetry"
    local OUTPUT_PATH: string = OUTPUT_FOLDER
        .. "/MM2_Trajectory_Calibration.json"
    local MAX_EVENTS: number = 2400
    local MAX_PENDING_AGE: number = 2.5
    -- 30 Hz could not resolve a 0.02 s horizon, and the offline question is
    -- exactly how the target moved in the last tens of milliseconds.
    local TRAJECTORY_SAMPLE_HZ: number = 60
    -- 2.5 s of pending life at 60 Hz needs 150; the margin covers a slow
    -- frame without silently truncating the tail.
    local MAX_TRAJECTORY_POINTS: number = 200
    local environment: {[string]: any} = getfenv() :: any
    local playerMouse: Mouse = LocalPlayer:GetMouse()
    local runtime: any = {
        active = false,
        dirty = false,
        revision = 0,
        saveScheduled = false,
        startedAt = os.clock(),
        startedAtUnix = os.time(),
        sessionId = HttpService:GenerateGUID(false),
        buildStamp = tostring(host.SOURCE_STAMP or "unknown"),
        shotSequence = 0,
        historyBackup = nil :: string?,
        persistenceBlocked = false,
        rawKnifeActivations = 0,
        unmatchedGunSignals = 0,
        sessionStabAttempts = 0,
        sessionGunAttempts = 0,
        sessionGunConfirmed = 0,
        sessionGunHitTarget = 0,
        sessionGunKills = 0,
        sessionKnifeAttempts = 0,
        sessionKnifeConfirmed = 0,
        pendingGuns = {} :: {PendingGun},
        lastBlockedAt = 0,
        evictedEvents = 0,
        pendingKnives = {} :: {PendingKnife},
        tracks = {} :: {[Instance]: KnifeTrack},
        observedTools = setmetatable({}, {__mode = "k"}) :: {[Tool]: boolean},
        connections = {} :: {RBXScriptConnection},
        events = {} :: {CalibrationEvent},
        freshGunLatency = {} :: {{at: number, ms: number}},
        gunAcceptance = nil :: RunningStats?,
        knifeSpeed = nil :: RunningStats?,
        knifeSpawnDelay = nil :: RunningStats?,
        motionBuckets = {} :: {[string]: any},
        trajectorySampler = nil :: any,
    }
    local controller: Controller
    local saveSnapshot: (reason: string) -> boolean
    local compactPending: (queue: {any}, now: number) -> ()
    local finalizeGunCapture: (pending: PendingGun) -> ()

    local function nextShotId(): string
        runtime.shotSequence += 1
        return runtime.sessionId .. ":" .. tostring(runtime.shotSequence)
    end
    local function emitShot(eventType: string, info: any): ()
        info.sessionId = runtime.sessionId
        info.buildStamp = runtime.buildStamp
        if type(state.emitGameBridgeEvent) == "function" then
            state.emitGameBridgeEvent(eventType, info)
        end
    end

    local function newStats(): RunningStats
        return {
            count = 0,
            mean = 0,
            m2 = 0,
            minimum = math.huge,
            maximum = -math.huge,
        }
    end

    runtime.gunAcceptance = newStats()
    runtime.knifeSpeed = newStats()
    runtime.knifeSpawnDelay = newStats()

    local function finite(value: number): boolean
        return value == value and value > -math.huge and value < math.huge
    end

    local function applyStatsPayload(
        stats: RunningStats,
        payload: {[string]: number}
    ): ()
        stats.count = tonumber(payload.count) or 0
        stats.mean = tonumber(payload.mean) or 0
        stats.m2 = tonumber(payload.m2) or 0
        stats.minimum = stats.count > 0
            and (tonumber(payload.minimum) or 0)
            or math.huge
        stats.maximum = stats.count > 0
            and (tonumber(payload.maximum) or 0)
            or -math.huge
    end

    local function restoreMotionBucket(bucket: any): any
        local count: number = tonumber(bucket.count) or 0
        local residual: any = bucket.meanConstantVelocityResidual or {}
        local errors: any = bucket.meanModelError or {}
        return {
            count = count,
            durationSum = bucket.durationSum or (bucket.meanDurationSeconds or 0) * count,
            horizontalLeadCount = bucket.horizontalLeadCount or (bucket.meanHorizontalLeadSeconds and count or 0),
            horizontalLeadSum = bucket.horizontalLeadSum or (bucket.meanHorizontalLeadSeconds or 0) * count,
            verticalLeadCount = bucket.verticalLeadCount or (bucket.meanVerticalLeadSeconds and count or 0),
            verticalLeadSum = bucket.verticalLeadSum or (bucket.meanVerticalLeadSeconds or 0) * count,
            residualXSum = bucket.residualXSum or (residual[1] or 0) * count,
            residualYSum = bucket.residualYSum or (residual[2] or 0) * count,
            residualZSum = bucket.residualZSum or (residual[3] or 0) * count,
            constantVelocityErrorSum = bucket.constantVelocityErrorSum or (errors.constantVelocity or 0) * count,
            observedAccelerationErrorSum = bucket.observedAccelerationErrorSum or (errors.observedAcceleration or 0) * count,
            airborneBallisticErrorSum = bucket.airborneBallisticErrorSum or (errors.airborneBallistic or 0) * count,
        }
    end

    local function loadSavedHistory(): ()
        if type(environment.readfile) ~= "function" then
            runtime.persistenceBlocked = true
            return
        end
        local okRead: boolean, raw: any = pcall(environment.readfile, OUTPUT_PATH)
        if not okRead then
            local okExists, exists = pcall(function() return environment.isfile(OUTPUT_PATH) end)
            runtime.persistenceBlocked = not (okExists and exists == false)
            return
        end
        if type(raw) ~= "string" then runtime.persistenceBlocked = true; return end
        if #raw == 0 then return end
        local backup: string = OUTPUT_PATH .. ".before-" .. runtime.sessionId .. ".json"
        local okBackup: boolean = type(environment.writefile) == "function"
            and pcall(environment.writefile, backup, raw)
        local okVerify, backedUp = pcall(environment.readfile, backup)
        if not okBackup or not okVerify or backedUp ~= raw then
            runtime.persistenceBlocked = true
            warn(trajectoryLogPrefix .. " History backup failed; existing file will not be overwritten.")
            return
        end
        runtime.historyBackup = backup
        local ok, decoded = pcall(HttpService.JSONDecode, HttpService, raw)
        if not ok or type(decoded) ~= "table" then return end
        -- Only plausible statistical estimates are portable. Counts such as
        -- 10^57, old events and old motion buckets never become session data.
        local aggregate: any = type(decoded.aggregate) == "table" and decoded.aggregate or {}
        local function importStats(stats: RunningStats, payload: any, low: number, high: number): ()
            if type(payload) ~= "table" then return end
            for _, key in ipairs({"count", "mean", "m2", "minimum", "maximum"}) do
                if not predictionMath.finite(payload[key]) then return end
            end
            if payload.count < 1 or payload.count > 1000000 or payload.count % 1 ~= 0
                or payload.m2 < 0 or payload.m2 > payload.count * (high - low) ^ 2
                or payload.minimum < low or payload.maximum > high
                or payload.mean < payload.minimum or payload.mean > payload.maximum then return end
            applyStatsPayload(stats, payload)
        end
        importStats(runtime.gunAcceptance, aggregate.gunAcceptanceMs, 0, 2500)
        importStats(runtime.knifeSpeed, aggregate.knifeSpeedStudsPerSecond, 24, 300)
        importStats(runtime.knifeSpawnDelay, aggregate.knifeSpawnDelayMs, 0, 5000)
    end

    local function vectorArray(value: Vector3): {number}
        return {value.X, value.Y, value.Z}
    end

    local function pingBucketKey(pingMs: number): string
        if pingMs > 250 then
            return "250+"
        end
        local lower: number = math.clamp(math.floor(pingMs / 5) * 5, 0, 245)
        return string.format("%03d-%03d", lower, lower + 5)
    end

    local function getTargetRoot(player: Player?): BasePart?
        return player
            and player.Character
            and player.Character:FindFirstChild("HumanoidRootPart") :: BasePart?
    end

    local function getTargetHumanoid(player: Player?): Humanoid?
        return player
            and player.Character
            and player.Character:FindFirstChildOfClass("Humanoid") :: Humanoid?
    end

    local function captureTrajectoryPoint(
        player: Player,
        activatedAt: number,
        pingMs: number
    ): TrajectoryPoint?
        local root: BasePart? = getTargetRoot(player)
        local humanoid: Humanoid? = getTargetHumanoid(player)
        if not root or not humanoid or humanoid.Health <= 0 then
            return nil
        end
        local stateName: string = humanoid:GetState().Name
        local grounded: boolean = humanoid.FloorMaterial ~= Enum.Material.Air
        local jumping: boolean = stateName == "Jumping"
            or stateName == "Freefall"
            or not grounded
        return {
            dt = os.clock() - activatedAt,
            serverTime = workspace:GetServerTimeNow(),
            pingMs = pingMs,
            position = vectorArray(root.Position),
            velocity = vectorArray(root.AssemblyLinearVelocity),
            moveDirection = vectorArray(humanoid.MoveDirection),
            humanoidState = stateName,
            grounded = grounded,
            jumping = jumping,
        }
    end

    -- Health is the only client-visible proof that a shot did damage. The
    -- `hitPart` of GunFired says a ray touched the target; a drop says the
    -- server applied it. Both are recorded, with both clocks, per shot.
    local function watchPendingHealth(pending: any, target: Player?): ()
        pending.targetHealthAtAim = nil
        pending.targetHealthAfter = nil
        pending.targetHealthDropAt = nil
        pending.targetDiedAt = nil
        local character: Model? = target and target.Character
        local humanoid: Humanoid? = character
            and character:FindFirstChildOfClass("Humanoid")
        if not humanoid then
            return
        end
        pending.targetHealthAtAim = humanoid.Health
        if pending.healthConnection then
            pending.healthConnection:Disconnect()
            pending.healthConnection = nil
        end
        pending.healthConnection = humanoid.HealthChanged:Connect(
            function(health: number): ()
                if not predictionMath.finite(health) then
                    return
                end
                if pending.targetHealthAfter == nil
                    or health < pending.targetHealthAfter then
                    pending.targetHealthAfter = health
                    if pending.targetHealthDropAt == nil then
                        pending.targetHealthDropAt = os.clock()
                        pending.targetHealthDropServerTime =
                            workspace:GetServerTimeNow()
                    end
                    if health <= 0 and pending.targetDiedAt == nil then
                        pending.targetDiedAt = os.clock()
                        pending.targetDiedServerTime =
                            workspace:GetServerTimeNow()
                    end
                end
            end
        )
    end

    local function findKnifeAnalysisTarget(aimPosition: Vector3?): Player?
        local selected: Player? = nil
        local selectedScore: number = math.huge
        for _, player: Player in ipairs(Players:GetPlayers()) do
            if player ~= LocalPlayer
                and isPlayerAlive(player)
                and getPlayerRole(player) ~= "Murderer"
                and not isProtectedTarget(player) then
                local root: BasePart? = getTargetRoot(player)
                if root then
                    local score: number = aimPosition
                            and (root.Position - aimPosition).Magnitude
                        or (root.Position - (LocalPlayer.Character
                                and LocalPlayer.Character:GetPivot().Position
                            or Vector3.zero)).Magnitude
                    if score < selectedScore then
                        selected = player
                        selectedScore = score
                    end
                end
            end
        end
        return selected
    end

    local function getRequestedAim(): Vector3?
        local aim: Vector3? = nil
        pcall(function(): ()
            aim = playerMouse.Hit.Position
        end)
        return aim
    end

    local function samplePendingTrajectories(): ()
        local now: number = os.clock()
        local function sampleQueue(queue: {any}): ()
            for _, pending: any in ipairs(queue) do
                if pending.targetUserId
                    and now - pending.lastTrajectorySampleAt
                        >= 1 / TRAJECTORY_SAMPLE_HZ then
                    local target: Player? = Players:GetPlayerByUserId(
                        pending.targetUserId
                    )
                    local point: TrajectoryPoint? = target
                        and captureTrajectoryPoint(
                            target,
                            pending.activatedAt,
                            pending.pingMs
                        )
                        or nil
                    if point then
                        if #pending.targetTrajectory < MAX_TRAJECTORY_POINTS then
                            table.insert(pending.targetTrajectory, point)
                        else
                            pending.trajectoryCapped = true
                        end
                    elseif pending.samplingStoppedAt == nil then
                        -- The only two ways this is nil: the character is gone
                        -- or the humanoid is dead. Either way it is the reason
                        -- a saved trajectory ends early, so it gets written
                        -- down instead of being guessed at later.
                        pending.samplingStoppedAt = now
                        pending.samplingStoppedReason = target
                                and "target-dead-or-missing"
                            or "target-left"
                    end
                    if target then
                        local root: BasePart? = getTargetRoot(target)
                        if root then
                            pending.lastSeenPosition = root.Position
                        end
                    end
                    pending.lastTrajectorySampleAt = now
                end
            end
        end
        sampleQueue(runtime.pendingGuns)
        sampleQueue(runtime.pendingKnives)
        for index: number = #runtime.pendingGuns, 1, -1 do
            local pending: PendingGun = runtime.pendingGuns[index]
            if pending.confirmedAt and now - pending.confirmedAt >= 0.5 then
                table.remove(runtime.pendingGuns, index)
                finalizeGunCapture(pending)
            end
        end
        if #runtime.pendingGuns == 0 and #runtime.pendingKnives == 0
            and runtime.trajectorySampler then
            runtime.trajectorySampler:Disconnect()
            runtime.trajectorySampler = nil
        end
    end

    local function ensureTrajectorySampler(): ()
        if runtime.trajectorySampler then
            return
        end
        runtime.trajectorySampler = TaskManager:Connect(function(
            _deltaTime: number
        ): ()
            compactPending(runtime.pendingGuns, os.clock())
            compactPending(runtime.pendingKnives, os.clock())
            samplePendingTrajectories()
        end)
    end

    local function addSample(stats: RunningStats, value: number): ()
        if not finite(value) then
            return
        end
        stats.count += 1
        local delta: number = value - stats.mean
        stats.mean += delta / stats.count
        stats.m2 += delta * (value - stats.mean)
        stats.minimum = math.min(stats.minimum, value)
        stats.maximum = math.max(stats.maximum, value)
    end

    local function statsPayload(stats: RunningStats): {[string]: number}
        return {
            count = stats.count,
            mean = stats.mean,
            m2 = stats.m2,
            minimum = stats.count > 0 and stats.minimum or 0,
            maximum = stats.count > 0 and stats.maximum or 0,
        }
    end

    local function getPingMilliseconds(): number
        local pingMs: number = 0
        pcall(function(): ()
            local network: Instance? = Stats:FindFirstChild("Network")
            local serverItems: Instance? = network
                and network:FindFirstChild("ServerStatsItem")
            local pingItem: any = serverItems
                and serverItems:FindFirstChild("Data Ping")
            if pingItem and type(pingItem.GetValue) == "function" then
                pingMs = tonumber(pingItem:GetValue()) or 0
            end
        end)
        return math.max(0, pingMs)
    end

    local function worldPosition(value: any): Vector3?
        if typeof(value) == "Vector3" then
            return value
        elseif typeof(value) == "CFrame" then
            return value.Position
        elseif typeof(value) == "Instance" then
            if value:IsA("Attachment") then
                return value.WorldPosition
            elseif value:IsA("BasePart") then
                return value.Position
            elseif value:IsA("Model") then
                return value:GetPivot().Position
            end
        end
        return nil
    end

    local function projectilePosition(projectile: Instance): Vector3?
        local visual: Instance? = projectile:FindFirstChild("KnifeVisual", true)
        if visual and visual:IsA("BasePart") then
            return visual.Position
        end
        local blade: Instance? = projectile:FindFirstChild("BladePosition", true)
        local bladePosition: Vector3? = worldPosition(blade)
        if bladePosition then
            return bladePosition
        end
        return worldPosition(projectile)
    end

    local function toolOrigin(tool: Tool): Vector3?
        local handle: Instance? = tool:FindFirstChild("Handle")
        return worldPosition(handle)
    end

    local function appendEvent(record: CalibrationEvent): ()
        record.sessionId = runtime.sessionId
        record.buildStamp = runtime.buildStamp
        if #runtime.events >= MAX_EVENTS then
            -- A session that spams the knife (158 authored events on
            -- 2026-10-18) evicted the gun records before their confirmations
            -- could be matched, so a shot could no longer be scored. The knife
            -- noise goes first; the gun record carries the settings.
            local victim: number = 1
            for index: number = 1, #runtime.events do
                local candidate: CalibrationEvent = runtime.events[index]
                if candidate.kind == "knife" and candidate.phase == "authored" then
                    victim = index
                    break
                end
            end
            table.remove(runtime.events, victim)
            runtime.evictedEvents = (runtime.evictedEvents or 0) + 1
        end
        table.insert(runtime.events, record)
        runtime.revision += 1
        runtime.dirty = true
        if runtime.saveScheduled then
            return
        end
        runtime.saveScheduled = true
        task.delay(10, function(): ()
            runtime.saveScheduled = false
            if runtime.active and runtime.dirty then
                saveSnapshot("autosave")
            end
        end)
    end

    -- Pre-shot movement window, straight from the predictor's ring buffer.
    -- Without it a second predictor can only be scored on the shot it took;
    -- with it the same slot can be replayed from the inputs.
    local function captureTargetHistory(
        player: Player?,
        now: number
    ): {HistoryPoint}
        local points: {HistoryPoint} = {}
        if not player or not state.mm2Prediction
            or type(state.mm2Prediction.getHistory) ~= "function" then
            return points
        end
        local ok: boolean, history: any, age: any = pcall(
            state.mm2Prediction.getHistory,
            player,
            0.6
        )
        if not ok or type(history) ~= "table" then
            return points
        end
        -- `at` is relative to the newest predictor sample and `age` is how old
        -- that sample was at the shot. Clocks in the two modules do not share
        -- an epoch, so the subtraction happens on the predictor's side only.
        local sampleAge: number = predictionMath.finite(age) and age or 0
        for _, sample: any in ipairs(history) do
            if #points >= 36 then
                break
            end
            local position: any = sample.position
            local velocity: any = sample.velocity
            if typeof(position) == "Vector3" and typeof(velocity) == "Vector3" then
                local move: any = sample.moveDirection
                local offset: any = sample.aimOffset
                table.insert(points, {
                    dt = (sample.at or 0) - sampleAge,
                    position = {position.X, position.Y, position.Z},
                    velocity = {velocity.X, velocity.Y, velocity.Z},
                    humanoidState = tostring(sample.state or "Running"),
                    grounded = sample.grounded == true,
                    moveDirection = typeof(move) == "Vector3"
                            and {move.X, move.Y, move.Z}
                        or nil,
                    aimOffset = typeof(offset) == "Vector3"
                            and {offset.X, offset.Y, offset.Z}
                        or nil,
                })
            end
        end
        return points
    end

    local function trackConnection(connection: RBXScriptConnection): ()
        table.insert(runtime.connections, connection)
    end

    compactPending = function(queue: {any}, now: number): ()
        local function drop(index: number): ()
            local entry: any = queue[index]
            if entry and entry.healthConnection then
                pcall(function(): ()
                    (entry.healthConnection :: RBXScriptConnection):Disconnect()
                end)
                entry.healthConnection = nil
            end
            table.remove(queue, index)
        end
        while #queue > 0 and now - queue[1].activatedAt > MAX_PENDING_AGE do
            drop(1)
        end
        while #queue > 12 do
            drop(1)
        end
    end

    local function vectorFromArray(value: {number}): Vector3
        return Vector3.new(value[1] or 0, value[2] or 0, value[3] or 0)
    end

    local function analyzeTargetTrajectory(
        trajectory: {TrajectoryPoint},
        pingMs: number,
        eventKind: string,
        evaluationSeconds: number?
    ): {[string]: any}
        if #trajectory < 2 then
            return {
                pingBucket = pingBucketKey(pingMs),
                sampleCount = #trajectory,
            }
        end
        local first: TrajectoryPoint = trajectory[1]
        local last: TrajectoryPoint = trajectory[#trajectory]
        if evaluationSeconds then
            local desiredDt: number = first.dt + evaluationSeconds
            local closestDistance: number = math.huge
            for _, point: TrajectoryPoint in ipairs(trajectory) do
                local distance: number = math.abs(point.dt - desiredDt)
                if distance < closestDistance then
                    last = point
                    closestDistance = distance
                end
            end
        end
        local initialPosition: Vector3 = vectorFromArray(first.position)
        local finalPosition: Vector3 = vectorFromArray(last.position)
        local initialVelocity: Vector3 = vectorFromArray(first.velocity)
        local duration: number = math.max(0.0001, last.dt - first.dt)
        local displacement: Vector3 = finalPosition - initialPosition
        local residual: Vector3 = displacement - initialVelocity * duration
        local constantVelocityPrediction: Vector3 = initialPosition
            + initialVelocity * duration
        local observedAcceleration: Vector3 = Vector3.zero
        if #trajectory >= 3 then
            local second: TrajectoryPoint = trajectory[2]
            local accelerationDelta: number = math.max(
                1 / 240,
                second.dt - first.dt
            )
            observedAcceleration = (
                vectorFromArray(second.velocity) - initialVelocity
            ) / accelerationDelta
            if observedAcceleration.Magnitude > 500 then
                observedAcceleration = observedAcceleration.Unit * 500
            end
        end
        local accelerationPrediction: Vector3 = initialPosition
            + initialVelocity * duration
            + observedAcceleration * (0.5 * duration * duration)
        local ballisticPrediction: Vector3 = initialPosition
            + initialVelocity * duration
            + Vector3.new(0, -workspace.Gravity, 0)
                * (0.5 * duration * duration)
        local modelErrors: {[string]: number} = {
            constantVelocity = (constantVelocityPrediction - finalPosition).Magnitude,
            observedAcceleration = (accelerationPrediction - finalPosition).Magnitude,
            airborneBallistic = (ballisticPrediction - finalPosition).Magnitude,
        }
        local bestMotionModel: string = "constantVelocity"
        local bestMotionError: number = modelErrors.constantVelocity
        for modelName: string, modelError: number in pairs(modelErrors) do
            if modelError < bestMotionError then
                bestMotionModel = modelName
                bestMotionError = modelError
            end
        end
        local horizontalVelocity: Vector3 = Vector3.new(
            initialVelocity.X,
            0,
            initialVelocity.Z
        )
        local horizontalDisplacement: Vector3 = Vector3.new(
            displacement.X,
            0,
            displacement.Z
        )
        local horizontalLead: number? = nil
        if horizontalVelocity.Magnitude > 0.75 then
            horizontalLead = math.clamp(
                horizontalDisplacement:Dot(horizontalVelocity)
                    / horizontalVelocity:Dot(horizontalVelocity),
                -0.15,
                0.6
            )
        end
        local verticalLead: number? = nil
        if math.abs(initialVelocity.Y) > 0.75 then
            verticalLead = math.clamp(
                displacement.Y / initialVelocity.Y,
                -0.15,
                0.6
            )
        end
        local jumped: boolean = false
        for _, point: TrajectoryPoint in ipairs(trajectory) do
            if point.jumping then
                jumped = true
                break
            end
        end
        local stateName: string = jumped and "Airborne" or "Grounded"
        local bucketKey: string = eventKind
            .. ":"
            .. pingBucketKey(pingMs)
            .. ":"
            .. stateName
        local bucket: any = runtime.motionBuckets[bucketKey]
        if type(bucket) ~= "table" then
            bucket = {
                count = 0,
                horizontalLeadSum = 0,
                horizontalLeadCount = 0,
                verticalLeadSum = 0,
                verticalLeadCount = 0,
                residualXSum = 0,
                residualYSum = 0,
                residualZSum = 0,
                durationSum = 0,
                constantVelocityErrorSum = 0,
                observedAccelerationErrorSum = 0,
                airborneBallisticErrorSum = 0,
            }
            runtime.motionBuckets[bucketKey] = bucket
        end
        bucket.count += 1
        bucket.durationSum += duration
        bucket.residualXSum += residual.X
        bucket.residualYSum += residual.Y
        bucket.residualZSum += residual.Z
        bucket.constantVelocityErrorSum += modelErrors.constantVelocity
        bucket.observedAccelerationErrorSum += modelErrors.observedAcceleration
        bucket.airborneBallisticErrorSum += modelErrors.airborneBallistic
        if horizontalLead then
            bucket.horizontalLeadSum += horizontalLead
            bucket.horizontalLeadCount += 1
        end
        if verticalLead then
            bucket.verticalLeadSum += verticalLead
            bucket.verticalLeadCount += 1
        end
        return {
            pingBucket = pingBucketKey(pingMs),
            sampleCount = #trajectory,
            initialState = first.humanoidState,
            finalState = last.humanoidState,
            jumped = jumped,
            durationSeconds = duration,
            evaluationSeconds = evaluationSeconds or duration,
            displacement = vectorArray(displacement),
            constantVelocityResidual = vectorArray(residual),
            horizontalLeadSeconds = horizontalLead,
            verticalLeadSeconds = verticalLead,
            bestMotionModel = bestMotionModel,
            motionModelErrors = modelErrors,
        }
    end

    local function motionModelPayload(buckets: {[string]: any}): {[string]: any}
        local payload: {[string]: any} = {}
        for key: string, bucket: any in pairs(buckets) do
            if type(bucket) == "table" then
                local count: number = math.max(1, tonumber(bucket.count) or 1)
                local horizontalCount: number = math.max(
                    1,
                    tonumber(bucket.horizontalLeadCount) or 0
                )
                local verticalCount: number = math.max(
                    1,
                    tonumber(bucket.verticalLeadCount) or 0
                )

                local meanDuration: number = tonumber(bucket.meanDurationSeconds)
                    or (bucket.durationSum and (bucket.durationSum / count))
                    or 0

                local meanHorizLead: number? = nil
                if bucket.horizontalLeadSum and horizontalCount > 0 then
                    meanHorizLead = bucket.horizontalLeadSum / horizontalCount
                elseif bucket.meanHorizontalLeadSeconds then
                    meanHorizLead = bucket.meanHorizontalLeadSeconds
                end

                local meanVertLead: number? = nil
                if bucket.verticalLeadSum and verticalCount > 0 then
                    meanVertLead = bucket.verticalLeadSum / verticalCount
                elseif bucket.meanVerticalLeadSeconds then
                    meanVertLead = bucket.meanVerticalLeadSeconds
                end

                local meanResidual: {number}
                if type(bucket.meanConstantVelocityResidual) == "table" then
                    meanResidual = bucket.meanConstantVelocityResidual
                else
                    meanResidual = {
                        (tonumber(bucket.residualXSum) or 0) / count,
                        (tonumber(bucket.residualYSum) or 0) / count,
                        (tonumber(bucket.residualZSum) or 0) / count,
                    }
                end

                local meanModelErr: {[string]: number}
                if type(bucket.meanModelError) == "table" then
                    meanModelErr = bucket.meanModelError
                else
                    meanModelErr = {
                        constantVelocity = (tonumber(bucket.constantVelocityErrorSum) or 0) / count,
                        observedAcceleration = (tonumber(bucket.observedAccelerationErrorSum) or 0) / count,
                        airborneBallistic = (tonumber(bucket.airborneBallisticErrorSum) or 0) / count,
                    }
                end

                payload[key] = {
                    durationSum = bucket.durationSum,
                    horizontalLeadSum = bucket.horizontalLeadSum,
                    horizontalLeadCount = bucket.horizontalLeadCount,
                    verticalLeadSum = bucket.verticalLeadSum,
                    verticalLeadCount = bucket.verticalLeadCount,
                    residualXSum = bucket.residualXSum,
                    residualYSum = bucket.residualYSum,
                    residualZSum = bucket.residualZSum,
                    constantVelocityErrorSum = bucket.constantVelocityErrorSum,
                    observedAccelerationErrorSum = bucket.observedAccelerationErrorSum,
                    airborneBallisticErrorSum = bucket.airborneBallisticErrorSum,
                    count = tonumber(bucket.count) or 0,
                    meanDurationSeconds = meanDuration,
                    meanHorizontalLeadSeconds = meanHorizLead,
                    meanVerticalLeadSeconds = meanVertLead,
                    meanConstantVelocityResidual = meanResidual,
                    meanModelError = meanModelErr,
                }
            end
        end
        return payload
    end

    local function median(values: {number}): number?
        if #values == 0 then
            return nil
        end
        local sorted: {number} = table.clone(values)
        table.sort(sorted)
        local middle: number = math.floor((#sorted + 1) / 2)
        if #sorted % 2 == 1 then
            return sorted[middle]
        end
        return (sorted[middle] + sorted[middle + 1]) * 0.5
    end

    local estimatesCache: Estimates? = nil
    local estimatesAt: number = -math.huge
    local function endpointErrorStats(): (number, number?, number?)
        local values: {number} = {}
        for _, ev in ipairs(runtime.events) do
            if ev.kind == "gun"
                and predictionMath.finite(ev.endpointErrorStuds) then
                table.insert(values, ev.endpointErrorStuds)
            end
        end
        local mean: number? = nil
        if #values > 0 then
            local total: number = 0
            for _, value in ipairs(values) do
                total += value
            end
            mean = total / #values
        end
        return #values, median(values), mean
    end

    local function estimates(): Estimates
        local now: number = os.clock()
        if estimatesCache and now - estimatesAt < 0.25 then return estimatesCache end
        local fresh: {number} = {}
        for _, sample in ipairs(runtime.freshGunLatency) do
            if now - sample.at <= 60 then table.insert(fresh, sample.ms) end
        end
        local gunStats: RunningStats = runtime.gunAcceptance
        local speedStats: RunningStats = runtime.knifeSpeed
        local spawnDelayStats: RunningStats = runtime.knifeSpawnDelay
        local maxStab: number? = nil
        for _, ev in ipairs(runtime.events) do
            if ev.kind == "stab" and ev.hitTarget == true
                and predictionMath.finite(ev.distance) then
                if not maxStab or ev.distance > maxStab then
                    maxStab = ev.distance
                end
            end
        end
        local errCount: number, errMedian: number?, errMean: number? =
            endpointErrorStats()
        estimatesCache = {
            predictionErrorSamples = errCount,
            predictionErrorMedianStuds = errMedian,
            predictionErrorMeanStuds = errMean,
            gunAcceptanceMs = gunStats.count > 0 and gunStats.mean or nil,
            knifeSpeed = speedStats.count > 0 and speedStats.mean or nil,
            confirmedShots = gunStats.count,
            confirmedThrows = speedStats.count,
            maxStabDistance = maxStab,
            liveGunAcceptanceMs = #fresh >= 6 and median(fresh) or nil,
            liveGunSamples = #fresh,
            knifeSpawnDelayMs = spawnDelayStats.count > 0
                and spawnDelayStats.mean
                or nil,
            confirmedSpawnDelays = spawnDelayStats.count,
        }
        estimatesAt = now
        return estimatesCache :: Estimates
    end

    saveSnapshot = function(reason: string): boolean
        if runtime.persistenceBlocked then return false end
        if type(environment.writefile) ~= "function" then
            warn(trajectoryLogPrefix .. " writefile is unavailable; data was not saved.")
            return false
        end

        -- History is loaded once. Re-merging the on-disk totals at each save
        -- used to double counters/buckets and read/decode a large JSON per shot.
        local savedRevision: number = runtime.revision
        local mergedGun = statsPayload(runtime.gunAcceptance)
        local mergedKnife = statsPayload(runtime.knifeSpeed)
        local mergedDelay = statsPayload(runtime.knifeSpawnDelay)
        local payload: {[string]: any} = {
            schema = 4,
            kind = "mm2-trajectory-analytics",
            buildStamp = runtime.buildStamp,
            sessionId = runtime.sessionId,
            historyBackup = runtime.historyBackup,
            settings = {
                silentSpawn = mm2Settings.silentSpawn,
                silentAim = mm2Settings.silentAim,
                silentSweep = mm2Settings.silentSweep,
                wallCheck = mm2Settings.shootWallCheck,
                autoLead = state.mm2Prediction
                    and state.mm2Prediction.settings.autoLead
                    or true,
                leadOffsetSeconds = state.mm2Prediction
                    and state.mm2Prediction.settings.extraLead
                    or 0,
                replicationInterpolationSeconds = state.mm2Prediction
                    and state.mm2Prediction.settings.interpolation
                    or nil,
            },
            placeId = game.PlaceId,
            savedAt = DateTime.now():ToIsoDate(),
            reason = reason,
            aggregateScope = "validated-history-plus-this-session; not a hit-rate denominator",
            aggregate = {
                gunAcceptanceMs = mergedGun,
                knifeSpeedStudsPerSecond = mergedKnife,
                knifeSpawnDelayMs = mergedDelay,
            },
            estimator = {
                gunAcceptanceMs = mergedGun.count > 0 and mergedGun.mean or nil,
                knifeSpeed = mergedKnife.count > 0 and mergedKnife.mean or nil,
                confirmedShots = mergedGun.count,
                confirmedThrows = mergedKnife.count,
            },
            analytics = {
                bucketSpec = {
                    metric = "Data Ping",
                    widthMs = 5,
                    minimumMs = 0,
                    maximumMs = 250,
                    states = {"Grounded", "Airborne"},
                },
                motionModel = motionModelPayload(runtime.motionBuckets),
            },
            session = {
                startedAt = runtime.startedAtUnix,
                countersScope = "this-session-only",
                gunConfirmationMeaning = "matched GunFired signal; hitTarget means the ray reached the target, died means the humanoid reached 0 health",
                evictedEvents = runtime.evictedEvents,
                healthMeaning = "client-observed Humanoid.Health; healthDropServerTime is GetServerTimeNow at the drop",
                knifeConfirmationMeaning = "observed projectile with valid speed; not an impact",
                rawKnifeActivations = runtime.rawKnifeActivations,
                unmatchedGunSignals = runtime.unmatchedGunSignals,
                stabAttempts = runtime.sessionStabAttempts,
                elapsedSeconds = os.clock() - runtime.startedAt,
                predictionError = (function(): {[string]: any}
                    local ok: boolean, n: any, med: any, mean: any =
                        pcall(endpointErrorStats)
                    return {
                        samples = ok and n or 0,
                        medianStuds = ok and med or nil,
                        meanStuds = ok and mean or nil,
                        scope = "own predicted point vs target at scoring instant, confirmed gun shots",
                    }
                end)(),
                gunByMode = (function(): {[string]: any}
                    local modes: {[string]: any} = {}
                    if type(runtime.events) == "table" then
                        for _, ev in ipairs(runtime.events) do
                            if ev.kind == "gun" then
                                if ev.phase == "authored" then
                                    local mode: string = type(ev.settings) == "table"
                                            and tostring(ev.settings.mode or "?")
                                        or "?"
                                    local row: any = modes[mode]
                                        or {attempts = 0, confirmed = 0, hits = 0, kills = 0}
                                    row.attempts += 1
                                    modes[mode] = row
                                elseif ev.phase == "confirmation" then
                                    local mode: string =
                                        tostring(ev.shotMode or "?")
                                    local row: any = modes[mode]
                                        or {attempts = 0, confirmed = 0, hits = 0, kills = 0}
                                    row.confirmed += 1
                                    if ev.hitTarget then row.hits += 1 end
                                    if ev.died then row.kills += 1 end
                                    modes[mode] = row
                                end
                            end
                        end
                    end
                    return modes
                end)(),
                gunAttempts = runtime.sessionGunAttempts,
                gunConfirmed = runtime.sessionGunConfirmed,
                gunHitTarget = runtime.sessionGunHitTarget,
                gunKills = runtime.sessionGunKills,
                knifeAttempts = runtime.sessionKnifeAttempts,
                knifeConfirmed = runtime.sessionKnifeConfirmed,
                events = runtime.events,
            },
        }
        local encodedOk: boolean, encoded: any = pcall(
            HttpService.JSONEncode,
            HttpService,
            payload
        )
        if not encodedOk or type(encoded) ~= "string" then
            warn(trajectoryLogPrefix .. " JSONEncode failed: " .. tostring(encoded))
            return false
        end
        if type(environment.makefolder) == "function" then
            pcall(environment.makefolder, OUTPUT_ROOT)
            pcall(environment.makefolder, OUTPUT_FOLDER)
        end
        local writeOk: boolean, writeError: any = pcall(
            environment.writefile,
            OUTPUT_PATH,
            encoded
        )
        if not writeOk then
            warn(trajectoryLogPrefix .. " writefile failed: " .. tostring(writeError))
            return false
        end

        -- A yielding executor write must not clear events recorded meanwhile.
        runtime.dirty = runtime.revision ~= savedRevision
        print(
            trajectoryLogPrefix .. " Saved "
                .. OUTPUT_PATH
                .. " ("
                .. tostring(#encoded)
                .. " bytes)"
        )
        return true
    end

    local function normalizeGun(value: any): Tool?
        if typeof(value) ~= "Instance" then
            return nil
        end
        if value:IsA("Tool") then
            return value
        end
        return value:FindFirstAncestorOfClass("Tool")
    end

    -- Where the target really was when the server scored the shot, compared
    -- with the point we aimed at, projected on the target's own horizontal
    -- velocity. That projection is the lead error in seconds: positive means
    -- the target was ahead of our aim (we under-led), negative means we led too
    -- far. The server scores roughly one way into the measured round trip, so
    -- the target's root is interpolated between the newest pre-shot sample and
    -- the root captured at confirmation.
    local function measureLeadErrorSeconds(pending: PendingGun): number?
        local history: {HistoryPoint} = pending.targetHistory or {}
        local newest: HistoryPoint? = history[#history]
        local aim: Vector3? = pending.requestedAim
        local latencyMs: any = pending.latencyMs
        local confirmation: any = pending.rootAtConfirmation
        if not newest or not aim or not confirmation then
            return nil
        end
        if not predictionMath.finite(latencyMs) or latencyMs <= 0
            or latencyMs > 1200 then
            return nil
        end
        if not predictionMath.finite(pending.activatedAt) then
            return nil
        end
        local beforeAt: number = pending.activatedAt + (newest.dt or 0)
        local afterAt: number = pending.confirmedAt
                and pending.confirmedAt
            or (pending.activatedAt + latencyMs / 1000)
        if not predictionMath.finite(afterAt) or afterAt <= beforeAt then
            return nil
        end
        -- Score where the server actually scores. The saved sessions
        -- separate hits from misses at the CONFIRMATION instant (a
        -- full round trip after firing), not half-way: scoring at
        -- activatedAt + latency/2 measured the aim ~55 ms AHEAD and
        -- taught the feedback loop a capped -60 ms correction, which
        -- then fought the (correct) full-transport lead on every
        -- shot -- the recorded cause of the chronic under-lead.
        local scoringAt: number = pending.activatedAt + latencyMs / 1000
        local alpha: number = math.clamp(
            (scoringAt - beforeAt) / (afterAt - beforeAt),
            0,
            1
        )
        local p0: {number}? = newest.position
        local p1: {number}? = confirmation.position
        if type(p0) ~= "table" or type(p1) ~= "table"
            or #p0 < 3 or #p1 < 3 then
            return nil
        end
        local rootX: number = p0[1] + (p1[1] - p0[1]) * alpha
        local rootY: number = p0[2] + (p1[2] - p0[2]) * alpha
        local rootZ: number = p0[3] + (p1[3] - p0[3]) * alpha
        local offset: {number}? = newest.aimOffset
        if type(offset) == "table" and #offset >= 3 then
            rootX += offset[1]
            rootY += offset[2]
            rootZ += offset[3]
        end
        local velocity: {number}? = newest.velocity
        if type(velocity) ~= "table" or #velocity < 3 then
            return nil
        end
        local vx: number = velocity[1]
        local vz: number = velocity[3]
        local speed: number = math.sqrt(vx * vx + vz * vz)
        -- A target that is not walking has no lead to correct; its aim error is
        -- noise around a stationary body.
        if speed < 3 then
            return nil
        end
        local along: number = ((rootX - aim.X) * vx + (rootZ - aim.Z) * vz) / speed
        -- Anything past this is not a lead error: a respawn, a teleport or the
        -- aim landing on a different player.
        if math.abs(along) > 6 then
            return nil
        end
        return along / speed
    end

    -- Same scoring-instant interpolation as measureLeadErrorSeconds,
    -- but the full 3D distance between the point we aimed at and where
    -- the target's aim point really was -- the direct endpoint error.
    -- No speed gate: a stationary target's error is real information
    -- here (it isolates geometry/origin problems from lead problems).
    local function measureEndpointErrorStuds(pending: PendingGun): number?
        local history: {HistoryPoint} = pending.targetHistory or {}
        local newest: HistoryPoint? = history[#history]
        local aim: Vector3? = pending.requestedAim
        local latencyMs: any = pending.latencyMs
        local confirmation: any = pending.rootAtConfirmation
        if not newest or not aim or not confirmation then
            return nil
        end
        if not predictionMath.finite(latencyMs) or latencyMs <= 0
            or latencyMs > 1200 then
            return nil
        end
        if not predictionMath.finite(pending.activatedAt) then
            return nil
        end
        local beforeAt: number = pending.activatedAt + (newest.dt or 0)
        local afterAt: number = pending.confirmedAt
                and pending.confirmedAt
            or (pending.activatedAt + latencyMs / 1000)
        if not predictionMath.finite(afterAt) or afterAt <= beforeAt then
            return nil
        end
        local scoringAt: number = pending.activatedAt + latencyMs / 1000
        local alpha: number = math.clamp(
            (scoringAt - beforeAt) / (afterAt - beforeAt),
            0,
            1
        )
        local p0: {number}? = newest.position
        local p1: {number}? = confirmation.position
        if type(p0) ~= "table" or type(p1) ~= "table"
            or #p0 < 3 or #p1 < 3 then
            return nil
        end
        local rootX: number = p0[1] + (p1[1] - p0[1]) * alpha
        local rootY: number = p0[2] + (p1[2] - p0[2]) * alpha
        local rootZ: number = p0[3] + (p1[3] - p0[3]) * alpha
        local offset: {number}? = newest.aimOffset
        if type(offset) == "table" and #offset >= 3 then
            rootX += offset[1]
            rootY += offset[2]
            rootZ += offset[3]
        end
        local dx: number = rootX - aim.X
        local dy: number = rootY - aim.Y
        local dz: number = rootZ - aim.Z
        local distance: number = math.sqrt(dx * dx + dy * dy + dz * dz)
        if not predictionMath.finite(distance) or distance > 30 then
            return nil
        end
        return distance
    end

    finalizeGunCapture = function(pending: PendingGun): ()
        if pending.targetDiedAt then
            runtime.sessionGunKills += 1
        end
        if pending.healthConnection then
            pcall(function(): ()
                (pending.healthConnection :: RBXScriptConnection):Disconnect()
            end)
            pending.healthConnection = nil
        end
        -- The echo lives here on purpose. The shot-feedback handler that used
        -- to feed it depends on a connection made when the feature toggles;
        -- the v61 log shows it never fired (echoDelay nil on all 13 shots
        -- despite 9 confirmations). This handler is the one that produced
        -- those 9 confirmations, so it is the reliable place to measure.
        if state.mm2Prediction and type(state.mm2Prediction.noteEcho) == "function"
            and predictionMath.finite(pending.latencyMs)
            and predictionMath.finite(pending.activatedAt) then
            state.mm2Prediction.noteEcho(
                pending.activatedAt,
                pending.activatedAt + pending.latencyMs / 1000
            )
        end
        -- Feed the measured lead error back into the predictor before the
        -- record is written, so the event can show what the next shot used.
        local leadError: number? = measureLeadErrorSeconds(pending)
        if leadError and state.mm2Prediction
            and type(state.mm2Prediction.noteLeadError) == "function" then
            pcall(state.mm2Prediction.noteLeadError, leadError)
        end
        local leadCorrection: number? = nil
        if state.mm2Prediction
            and type(state.mm2Prediction.getLeadCorrection) == "function" then
            local ok: boolean, value: any = pcall(
                state.mm2Prediction.getLeadCorrection
            )
            if ok and predictionMath.finite(value) then
                leadCorrection = value
            end
        end
        local endpointError: number? = measureEndpointErrorStuds(pending)
        local analysis: {[string]: any} = analyzeTargetTrajectory(
            pending.targetTrajectory,
            pending.pingMs,
            "gun",
            (pending.latencyMs or 0) / 1000
        )
        appendEvent({
            shotId = pending.shotId,
            phase = "confirmation",
            kind = "gun",
            serverTime = workspace:GetServerTimeNow(),
            clock = os.clock(),
            pingMs = pending.pingMs,
            latencyMs = pending.latencyMs,
            targetUserId = pending.targetUserId,
            targetName = pending.targetName,
            targetState = analysis.initialState,
            targetJumped = analysis.jumped,
            targetTrajectory = pending.targetTrajectory,
            targetHistory = #(pending.targetHistory or {}) > 0
                    and pending.targetHistory
                or nil,
            observedDisplacement = analysis.displacement,
            constantVelocityResidual = analysis.constantVelocityResidual,
            horizontalLeadSeconds = analysis.horizontalLeadSeconds,
            verticalLeadSeconds = analysis.verticalLeadSeconds,
            endpoint = pending.confirmedEndpoint
                    and vectorArray(pending.confirmedEndpoint)
                or nil,
            hitTarget = pending.confirmedHitTarget,
            shotMode = pending.shotMode,
            silentSpawn = pending.silentSpawn,
            -- Server-clock round trip: activation to GunFired, both stamped
            -- with GetServerTimeNow. Independent of GetNetworkPing and of the
            -- engine's Data Ping, so it settles which of them the lead needs.
            serverEchoMs = (pending.serverConfirmedAt
                    and pending.serverActivatedAt)
                    and (pending.serverConfirmedAt - pending.serverActivatedAt)
                        * 1000
                or nil,
            -- Anchor for the server-clock axis: every trajectory point carries
            -- its own serverTime, so serverDt = point.serverTime - this.
            serverActivatedAt = pending.serverActivatedAt,
            serverConfirmedAt = pending.serverConfirmedAt,
            serverOrigin = pending.confirmedServerOrigin
                    and vectorArray(pending.confirmedServerOrigin)
                or nil,
            aimOffsetAtFire = (function(): {number}?
                local history: {HistoryPoint} = pending.targetHistory or {}
                local newest: HistoryPoint? = history[#history]
                return newest and newest.aimOffset or nil
            end)(),
            -- Signed lead error measured from this very confirmation, and the
            -- bounded correction the next shot will apply. Both are written in
            -- seconds so a saved session can be replayed and audited without
            -- rerunning the shot.
            leadErrorSeconds = leadError,
            leadCorrectionSeconds = leadCorrection,
            endpointErrorStuds = endpointError,
            trajectoryPoints = #pending.targetTrajectory,
            trajectorySpanSeconds = (
                    #pending.targetTrajectory > 1
                    and (pending.targetTrajectory[#pending.targetTrajectory].dt
                        - pending.targetTrajectory[1].dt)
                )
                or 0,
            trajectoryCapped = pending.trajectoryCapped == true,
            samplingStoppedReason = pending.samplingStoppedReason,
            samplingStoppedAt = pending.samplingStoppedAt,
            rttEngineAtConfirmation = pending.rttEngineAtConfirmation,
            rttDataAtConfirmation = pending.rttDataAtConfirmation,
            aim = pending.requestedAim and vectorArray(pending.requestedAim) or nil,
            origin = pending.origin and vectorArray(pending.origin) or nil,
            hitPart = pending.confirmedHitPart,
            hitPartPosition = pending.confirmedHitPartPosition
                    and vectorArray(pending.confirmedHitPartPosition)
                or nil,
            hitPartSize = pending.confirmedHitPartSize
                    and vectorArray(pending.confirmedHitPartSize)
                or nil,
            rootAtConfirmation = pending.rootAtConfirmation,
            lastSeenPosition = pending.lastSeenPosition
                    and vectorArray(pending.lastSeenPosition)
                or nil,
            healthAtAim = pending.targetHealthAtAim,
            healthAtConfirmation = pending.targetHealthAtConfirmation,
            healthAfter = pending.targetHealthAfter,
            healthDropAt = pending.targetHealthDropAt,
            healthDropServerTime = pending.targetHealthDropServerTime,
            diedAt = pending.targetDiedAt,
            diedServerTime = pending.targetDiedServerTime,
            died = pending.targetDiedAt ~= nil,
            pingBucket = analysis.pingBucket,
            bestMotionModel = analysis.bestMotionModel,
            motionModelErrors = analysis.motionModelErrors,
            evaluationSeconds = analysis.evaluationSeconds,
        })
    end

    local function handleGunFired(
        eventGun: any,
        eventOriginValue: any,
        endpointValue: any,
        hitPartValue: any
    ): ()
        if not runtime.active then
            return
        end
        local now: number = os.clock()
        compactPending(runtime.pendingGuns, now)
        local eventTool: Tool? = normalizeGun(eventGun)
        local eventOrigin: Vector3? = worldPosition(eventOriginValue)
        -- Match the OLDEST unconfirmed attempt whose tool and origin geometry
        -- agree with the signal. Iterating newest-first let a signal confirm
        -- a younger shot and feed a wrong latency into the adaptive horizon.
        local selectedIndex: number? = nil
        local fallbackIndex: number? = nil
        for index: number = 1, #runtime.pendingGuns do
            local pending: PendingGun = runtime.pendingGuns[index]
            if not pending.confirmedAt then
                local toolMatches: boolean = eventTool ~= nil
                    and eventTool == pending.tool
                local originMatches: boolean = eventOrigin ~= nil
                    and pending.origin ~= nil
                    and (eventOrigin - pending.origin).Magnitude <= 8
                if toolMatches and originMatches then
                    selectedIndex = index
                    break
                end
                if fallbackIndex == nil then
                    if toolMatches
                        and (eventOrigin == nil or pending.origin == nil) then
                        fallbackIndex = index
                    elseif eventTool == nil and originMatches then
                        fallbackIndex = index
                    end
                end
            end
        end
        if not selectedIndex then
            selectedIndex = fallbackIndex
        end
        if not selectedIndex then
            local character: Model? = LocalPlayer.Character
            local root: BasePart? = character and character:FindFirstChild("HumanoidRootPart") :: BasePart?
            local isLocalShooter: boolean = false
            if eventTool and eventTool.Parent == character then
                isLocalShooter = true
            elseif root and eventOrigin and (eventOrigin - root.Position).Magnitude <= 20 then
                isLocalShooter = true
            end
            if isLocalShooter then
                runtime.unmatchedGunSignals += 1
                appendEvent({kind = "gun", phase = "unmatched-signal",
                    serverTime = workspace:GetServerTimeNow(), pingMs = getPingMilliseconds()})
            end
            return
        end
        local pending: PendingGun = runtime.pendingGuns[selectedIndex]
        local latencyMs: number = math.max(0, (now - pending.activatedAt) * 1000)
        local target: Player? = pending.targetUserId
            and Players:GetPlayerByUserId(pending.targetUserId)
            or nil
        if target then
            local finalPoint: TrajectoryPoint? = captureTrajectoryPoint(
                target,
                pending.activatedAt,
                pending.pingMs
            )
            if finalPoint then
                table.insert(pending.targetTrajectory, finalPoint)
            end
        end
        local endpoint: Vector3? = worldPosition(endpointValue)
        local targetCharacter: Model? = target and target.Character
        local hitTarget: boolean = typeof(hitPartValue) == "Instance"
            and targetCharacter ~= nil
            and hitPartValue:IsDescendantOf(targetCharacter)
        -- Recorded at the moment the signal arrives, on the server clock, so
        -- the round trip can be measured without either engine estimate.
        pending.serverConfirmedAt = workspace:GetServerTimeNow()
        pending.confirmedServerOrigin = eventOrigin
        local engineNow: number?, dataNow: number? = readLatencyReadings()
        pending.rttEngineAtConfirmation = engineNow
        pending.rttDataAtConfirmation = dataNow
        if typeof(hitPartValue) == "Instance" then
            pcall(function(): ()
                pending.confirmedHitPart = string.sub(hitPartValue.Name, 1, 80)
                if hitPartValue:IsA("BasePart") then
                    pending.confirmedHitPartPosition = hitPartValue.Position
                    pending.confirmedHitPartSize = hitPartValue.Size
                end
            end)
        end
        if target then
            local root: BasePart? = getTargetRoot(target)
            local humanoid: Humanoid? = getTargetHumanoid(target)
            if root then
                local stateName: string? = nil
                if humanoid then
                    pcall(function(): ()
                        stateName = humanoid:GetState().Name
                    end)
                end
                pending.rootAtConfirmation = {
                    position = vectorArray(root.Position),
                    velocity = vectorArray(root.AssemblyLinearVelocity),
                    state = stateName,
                }
            end
            if humanoid then
                pending.targetHealthAtConfirmation = humanoid.Health
            end
        end
        if latencyMs >= 30 and latencyMs <= 450 then
            table.insert(runtime.freshGunLatency, {at = now, ms = latencyMs})
            if #runtime.freshGunLatency > 24 then table.remove(runtime.freshGunLatency, 1) end
            estimatesAt = -math.huge
        end
        addSample(runtime.gunAcceptance, latencyMs)
        runtime.sessionGunConfirmed += 1
        if hitTarget then
            runtime.sessionGunHitTarget += 1
        end
        pending.confirmedAt = now
        pending.latencyMs = latencyMs
        pending.confirmedEndpoint = endpoint
        pending.confirmedHitTarget = hitTarget
        emitShot("shotConfirmation", {
            shotId = pending.shotId, kind = "gun", hitTarget = hitTarget,
            targetName = pending.targetName, latencyMs = latencyMs,
            endpoint = endpoint, evidence = "GunFired.hitPart",
        })
        ensureTrajectorySampler()
    end

    local finishKnifeTrack: (projectile: Instance, reason: string) -> ()
    local function stopKnifeSamplerIfIdle(): ()
        if next(runtime.tracks) == nil then
            disconnectFeatureConnection("MM2TrajectorySampler")
        end
    end

    finishKnifeTrack = function(projectile: Instance, reason: string): ()
        local track: KnifeTrack? = runtime.tracks[projectile]
        if not track then
            return
        end
        runtime.tracks[projectile] = nil
        if track.destroyConnection then
            track.destroyConnection:Disconnect()
            track.destroyConnection = nil
        end
        local measuredSpeed: number? = median(track.speeds)
        local resolvedSpeed: number? = track.rawSpeed or measuredSpeed
        if resolvedSpeed and resolvedSpeed >= 24 and resolvedSpeed <= 300 then
            local analysis: {[string]: any} = analyzeTargetTrajectory(
                track.targetTrajectory,
                track.pingMs,
                "knife",
                nil
            )
            addSample(runtime.knifeSpeed, resolvedSpeed)
            runtime.sessionKnifeConfirmed += 1
            appendEvent({
                shotId = track.shotId,
                phase = "projectile-observed",
                kind = "knife",
                serverTime = workspace:GetServerTimeNow(),
                pingMs = track.pingMs,
                latencyMs = track.spawnDelayMs,
                speed = resolvedSpeed,
                rawSpeed = track.rawSpeed,
                samples = #track.speeds,
                reason = reason,
                targetUserId = track.targetUserId,
                targetName = track.targetName,
                targetState = analysis.initialState,
                targetJumped = analysis.jumped,
                targetTrajectory = track.targetTrajectory,
                targetHistory = #track.targetHistory > 0
                        and track.targetHistory
                    or nil,
                observedDisplacement = analysis.displacement,
                constantVelocityResidual = analysis.constantVelocityResidual,
                horizontalLeadSeconds = analysis.horizontalLeadSeconds,
                verticalLeadSeconds = analysis.verticalLeadSeconds,
                pingBucket = analysis.pingBucket,
                bestMotionModel = analysis.bestMotionModel,
                motionModelErrors = analysis.motionModelErrors,
                evaluationSeconds = analysis.evaluationSeconds,
            })
        end
        stopKnifeSamplerIfIdle()
    end

    local function ensureKnifeSampler(): ()
        if featureConnections.MM2TrajectorySampler then
            return
        end
        featureConnections.MM2TrajectorySampler = TaskManager:Connect(function(
            _deltaTime: number
        ): ()
            local now: number = os.clock()
            local completed: {Instance} = {}
            for projectile: Instance, track: KnifeTrack in pairs(runtime.tracks) do
                if not projectile.Parent or now - track.startedAt >= 1.25 then
                    table.insert(completed, projectile)
                    continue
                end
                local position: Vector3? = projectilePosition(projectile)
                if position and track.previousPosition and track.previousAt then
                    local sampleDelta: number = now - track.previousAt
                    local displacement: number = (position - track.previousPosition).Magnitude
                    if sampleDelta >= 1 / 240 and displacement >= 0.01 then
                        local speed: number = displacement / sampleDelta
                        if speed >= 24 and speed <= 300 then
                            table.insert(track.speeds, speed)
                        end
                    end
                end
                if position then
                    track.previousPosition = position
                    track.previousAt = now
                end
                if track.targetUserId
                    and now - track.lastTrajectorySampleAt >= 1 / 30 then
                    local target: Player? = Players:GetPlayerByUserId(
                        track.targetUserId
                    )
                    local point: TrajectoryPoint? = target
                        and captureTrajectoryPoint(
                            target,
                            track.startedAt - track.spawnDelayMs / 1000,
                            track.pingMs
                        )
                        or nil
                    if point and #track.targetTrajectory < 120 then
                        table.insert(track.targetTrajectory, point)
                    end
                    track.lastTrajectorySampleAt = now
                end
            end
            for _, projectile: Instance in ipairs(completed) do
                finishKnifeTrack(projectile, "sample-window-complete")
            end
        end)
    end

    local function resolveKnifeProjectile(projectile: Instance): ()
        local sessionId = runtime.sessionId
        task.spawn(function(): ()
            local linkedHandle: Instance? = nil
            for _attempt: number = 1, 20 do
                if not runtime.active or runtime.sessionId ~= sessionId or not projectile.Parent then
                    return
                end
                local handleLink: Instance? = projectile:FindFirstChild(
                    "HandleLink",
                    true
                )
                if handleLink and handleLink:IsA("ObjectValue") and handleLink.Value then
                    linkedHandle = handleLink.Value
                    break
                end
                task.wait(0.05)
            end
            if not linkedHandle then
                return
            end
            local now: number = os.clock()
            compactPending(runtime.pendingKnives, now)
            local selectedIndex: number? = nil
            for index: number = #runtime.pendingKnives, 1, -1 do
                local pending: PendingKnife = runtime.pendingKnives[index]
                local handle: Instance? = pending.tool:FindFirstChild("Handle")
                if linkedHandle == handle
                    or linkedHandle:IsDescendantOf(pending.tool) then
                    selectedIndex = index
                    break
                end
            end
            if not selectedIndex or runtime.tracks[projectile] then
                return
            end
            local pending: PendingKnife = table.remove(
                runtime.pendingKnives,
                selectedIndex
            )
            local spawnDelayMs: number = math.max(
                0,
                (now - pending.activatedAt) * 1000
            )
            addSample(runtime.knifeSpawnDelay, spawnDelayMs)
            local rawSpeed: number? = tonumber(projectile:GetAttribute("ThrowSpeed"))
            if rawSpeed and (rawSpeed < 24 or rawSpeed > 300) then
                rawSpeed = nil
            end
            if not pending.attemptCounted then
                runtime.sessionKnifeAttempts += 1
                emitShot("authoringShot", {shotId = pending.shotId, kind = "knife",
                    toolName = pending.tool.Name, originPos = pending.origin,
                    aimPos = pending.requestedAim, targetName = pending.targetName,
                    eventSource = "observed-projectile"})
            end
            emitShot("shotConfirmation", {shotId = pending.shotId, kind = "knife",
                evidence = "projectile-observed", targetName = pending.targetName})
            local track: KnifeTrack = {
                shotId = pending.shotId,
                startedAt = now,
                previousAt = now,
                previousPosition = projectilePosition(projectile),
                speeds = {},
                rawSpeed = rawSpeed,
                spawnDelayMs = spawnDelayMs,
                pingMs = pending.pingMs,
                targetUserId = pending.targetUserId,
                targetName = pending.targetName,
                targetTrajectory = pending.targetTrajectory,
                targetHistory = pending.targetHistory or {},
                lastTrajectorySampleAt = now,
                destroyConnection = nil,
            }
            runtime.tracks[projectile] = track
            track.destroyConnection = projectile.Destroying:Connect(function(): ()
                finishKnifeTrack(projectile, "destroyed")
            end)
            ensureKnifeSampler()
        end)
    end

    local function isGun(tool: Tool): boolean
        return tool.Name == "Gun"
            or CollectionService:HasTag(tool, "Weapon_Gun")
            or tool:FindFirstChild("Shoot") ~= nil
    end

    local function isKnife(tool: Tool): boolean
        return tool.Name == "Knife"
            or CollectionService:HasTag(tool, "Weapon_Knife")
            or (tool:FindFirstChild("Events") ~= nil
                and tool.Events:FindFirstChild("KnifeThrown") ~= nil)
    end

    -- One constructor for every pending shot. The activation observer and the
    -- authored-shot path used to build this table separately, and on
    -- 2026-10-18 the authored copy was missing the health watcher and the
    -- server-clock pair: 13 confirmations, healthAtAim nil on all of them and
    -- no serverEchoMs. Duplicating the record was the bug; there is one now.
    local function beginPendingShot(kind: string, entry: any, target: Player?): any
        local now: number = entry.activatedAt or os.clock()
        entry.activatedAt = now
        entry.serverActivatedAt = workspace:GetServerTimeNow()
        entry.targetUserId = target and target.UserId or entry.targetUserId
        entry.targetName = target and target.Name or entry.targetName
        if entry.targetTrajectory == nil then
            entry.targetTrajectory = {}
            if target then
                local point: TrajectoryPoint? = captureTrajectoryPoint(
                    target,
                    now,
                    entry.pingMs or 0
                )
                if point then
                    table.insert(entry.targetTrajectory, point)
                end
            end
        end
        if entry.targetHistory == nil then
            entry.targetHistory = captureTargetHistory(target, now)
        end
        entry.lastTrajectorySampleAt = entry.lastTrajectorySampleAt or now
        watchPendingHealth(entry, target)
        local queue: {any} = kind == "gun"
                and runtime.pendingGuns
            or runtime.pendingKnives
        table.insert(queue, entry)
        compactPending(queue, now)
        ensureTrajectorySampler()
        return entry
    end

    local function observeTool(tool: Tool): ()
        if runtime.observedTools[tool] then
            return
        end
        local gun: boolean = isGun(tool)
        local knife: boolean = isKnife(tool)
        if not gun and not knife then
            return
        end
        runtime.observedTools[tool] = true
        trackConnection(tool.Activated:Connect(function(): ()
            if not runtime.active then
                return
            end
            local now: number = os.clock()
            local requestedAim: Vector3? = getRequestedAim()
            local pingMs: number = getPingMilliseconds()
            local target: Player? = gun
                    and findMurderer()
                or findKnifeAnalysisTarget(requestedAim)
            local targetTrajectory: {TrajectoryPoint} = {}
            if target then
                local initialPoint: TrajectoryPoint? = captureTrajectoryPoint(
                    target,
                    now,
                    pingMs
                )
                if initialPoint then
                    table.insert(targetTrajectory, initialPoint)
                end
            end
            local shotId: string = nextShotId()
            appendEvent({shotId = shotId, kind = gun and "gun" or "knifeActivation",
                phase = gun and "attempt" or "activation",
                serverTime = workspace:GetServerTimeNow(), pingMs = pingMs,
                targetName = target and target.Name or nil})
            emitShot("authoringShot", {shotId = shotId, kind = gun and "gun" or "knifeActivation",
                toolName = tool.Name, originPos = toolOrigin(tool), aimPos = requestedAim,
                targetName = target and target.Name or nil, eventSource = "tool-activation"})
            if gun then
                runtime.sessionGunAttempts += 1
                beginPendingShot("gun", {
                    shotId = shotId,
                    attemptCounted = true,
                    tool = tool,
                    activatedAt = now,
                    origin = toolOrigin(tool),
                    requestedAim = requestedAim,
                    pingMs = pingMs,
                    targetTrajectory = targetTrajectory,
                }, target)
            elseif knife then
                runtime.rawKnifeActivations += 1
                beginPendingShot("knife", {
                    shotId = shotId,
                    attemptCounted = false,
                    tool = tool,
                    activatedAt = now,
                    origin = toolOrigin(tool),
                    requestedAim = requestedAim,
                    pingMs = pingMs,
                    targetTrajectory = targetTrajectory,
                }, target)
            end
        end))
    end

    local function observeContainer(container: Instance?): ()
        if not container then
            return
        end
        for _, child: Instance in ipairs(container:GetChildren()) do
            if child:IsA("Tool") then
                observeTool(child)
            end
        end
        trackConnection(container.ChildAdded:Connect(function(child: Instance): ()
            if child:IsA("Tool") then
                observeTool(child)
            end
        end))
    end

    local function installGunConfirmation(): ()
        task.spawn(function(): ()
            local clientServices: Instance? = nil
            local weaponModule: Instance? = nil
            for _attempt: number = 1, 20 do
                if not runtime.active then
                    return
                end
                clientServices = game:GetService("ReplicatedStorage")
                    :FindFirstChild("ClientServices")
                weaponModule = clientServices
                    and clientServices:FindFirstChild("WeaponService")
                if weaponModule then
                    break
                end
                task.wait(0.25)
            end
            if not weaponModule then
                warn(trajectoryLogPrefix .. " WeaponService did not appear; Knife remains active.")
                return
            end
            local loaded: boolean, weaponService: any = pcall(
                state.requireModule,
                weaponModule
            )
            if not loaded or type(weaponService) ~= "table" then
                warn(
                    trajectoryLogPrefix .. " Could not observe WeaponService: "
                        .. tostring(weaponService)
                )
                return
            end
            local connected: boolean, connection: any = pcall(function(): any
                return weaponService.GunFired.OnClientEvent:Connect(handleGunFired)
            end)
            if connected and connection then
                trackConnection(connection :: RBXScriptConnection)
                print(trajectoryLogPrefix .. " GunFired confirmation connected.")
            else
                warn(
                    trajectoryLogPrefix .. " GunFired no es compatible: "
                        .. tostring(connection)
                )
            end
        end)
    end

    controller = {} :: Controller

    function controller:start(): ()
        if runtime.active then
            return
        end

        if not GAME_CHECK.MM2Active then
            warn(trajectoryLogPrefix .. " Inicio omitido fuera de MM2.")
            return
        end
        runtime.active = true
        runtime.startedAt = os.clock()
        runtime.startedAtUnix = os.time()
        loadSavedHistory()
        observeContainer(LocalPlayer:FindFirstChildOfClass("Backpack"))
        observeContainer(LocalPlayer.Character)
        trackConnection(LocalPlayer.CharacterAdded:Connect(function(
            character: Model
        ): ()
            observeContainer(character)
        end))
        trackConnection(
            CollectionService:GetInstanceAddedSignal("ThrowingKnife"):Connect(
                resolveKnifeProjectile
            )
        )
        installGunConfirmation()
        print(trajectoryLogPrefix .. " Passive calibration started in the background.")
    end

    local function clearHistory(): ()
        runtime.gunAcceptance = newStats()
        runtime.knifeSpeed = newStats()
        runtime.knifeSpawnDelay = newStats()
        runtime.motionBuckets = {}
        runtime.events = {}
        runtime.freshGunLatency = {}
        estimatesCache = nil
        estimatesAt = -math.huge
        runtime.sessionGunAttempts = 0
        runtime.sessionGunConfirmed = 0
        runtime.sessionKnifeAttempts = 0
        runtime.sessionKnifeConfirmed = 0
        runtime.rawKnifeActivations = 0
        runtime.unmatchedGunSignals = 0
        runtime.sessionStabAttempts = 0
        runtime.startedAt = os.clock()
        runtime.startedAtUnix = os.time()
        for _, track in pairs(runtime.tracks) do
            if track.destroyConnection then track.destroyConnection:Disconnect() end
        end
        table.clear(runtime.tracks)
        disconnectFeatureConnection("MM2TrajectorySampler")
        runtime.sessionId = HttpService:GenerateGUID(false)
        runtime.shotSequence = 0
        table.clear(runtime.pendingGuns)
        table.clear(runtime.pendingKnives)
    end

    function controller:save(reason: string?): boolean
        return saveSnapshot(reason or "manual")
    end

    function controller:reset(): ()
        clearHistory()
        runtime.dirty = false
        if type(environment.delfile) == "function" then
            pcall(environment.delfile, OUTPUT_PATH)
        elseif type(environment.writefile) == "function" then
            pcall(environment.writefile, OUTPUT_PATH, "{}")
        end
        print(trajectoryLogPrefix .. " History cleared.")
    end

    function controller:getEstimates(): Estimates
        return estimates()
    end

    -- Separate feedback event: never count an echo as another authored shot
    -- or use endpoint-to-client-position distance as proof of a server miss.
    function controller:noteTracerData(info: any): ()
        if not runtime.active or type(info) ~= "table" then return end
        local function validVector(value: any): boolean
            return typeof(value) == "Vector3"
                and predictionMath.finite(value.X) and predictionMath.finite(value.Y)
                and predictionMath.finite(value.Z) and value.Magnitude < 1e7
        end
        if not validVector(info.origin) or not validVector(info.endpoint) then return end
        local function pack(value: Vector3): {number}
            return {value.X, value.Y, value.Z}
        end
        local shotId: string? = nil
        local now: number = os.clock()
        for index: number = #runtime.pendingGuns, 1, -1 do
            local pending: PendingGun = runtime.pendingGuns[index]
            if now - pending.activatedAt <= 2.5 and pending.origin
                and (pending.origin - info.origin).Magnitude <= 8 then
                shotId = pending.shotId
                break
            end
        end
        local target: any = info.target
        local targetPosition: Vector3? = validVector(info.targetPosition) and info.targetPosition or nil
        local path: string? = nil
        local hitTarget: boolean? = nil
        if typeof(info.hitPart) == "Instance" then
            pcall(function(): () path = string.sub(info.hitPart:GetFullName(), 1, 512) end)
            if target and target.Character then
                hitTarget = info.hitPart:IsDescendantOf(target.Character)
            end
        end
        appendEvent({kind = "gun", phase = "tracer-data", shotId = shotId,
            serverTime = workspace:GetServerTimeNow(), pingMs = getPingMilliseconds(),
            origin = pack(info.origin), endpoint = pack(info.endpoint),
            shotRange = (info.endpoint - info.origin).Magnitude,
            targetUserId = target and target.UserId or nil,
            targetName = target and target.Name or nil,
            observedTargetPosition = targetPosition and pack(targetPosition) or nil,
            endpointToObservedTarget = targetPosition and (info.endpoint - targetPosition).Magnitude or nil,
            targetPositionScope = "client-observed-at-GunFired-receipt; not server impact-time position",
            hitPartPath = path, hitTarget = hitTarget, evidence = "GunFired endpoint/hitPart",
        })
    end

    -- A shot the client refused. Recorded so the blocker that the server
    -- respects (invisible wall, barrier, tagged part) can be identified
    -- instead of being inferred from a miss. Throttled: a held auto-shoot
    -- would otherwise flood the event ring.
    function controller:noteBlockedShot(blocker: any): ()
        if not runtime.active or type(blocker) ~= "table" then
            return
        end
        local now: number = os.clock()
        if now - runtime.lastBlockedAt < 1 then
            return
        end
        runtime.lastBlockedAt = now
        appendEvent({
            kind = "gun",
            phase = "blocked",
            serverTime = workspace:GetServerTimeNow(),
            pingMs = getPingMilliseconds(),
            reason = "wall",
            blockedName = type(blocker.name) == "string" and blocker.name or nil,
            blockedTransparency = tonumber(blocker.transparency),
            blockedCanCollide = blocker.canCollide == true,
            blockedSkipped = blocker.skipped == true,
            blockedDistance = tonumber(blocker.distance),
        })
    end

    function controller:noteAuthoredShot(info: any): ()
        if not runtime.active or type(info) ~= "table" then
            return
        end
        local kind: string = tostring(info.kind or "gun")
        local shotId: string = nextShotId()
        local now: number = os.clock()
        local pingMs: number = getPingMilliseconds()
        local target: Player? =
            info.target and info.target.Character ~= nil and info.target or nil
        -- Captured before the authored event so the record carries the window
        -- the predictor actually had, not a reconstruction.
        local targetHistory: {HistoryPoint} = captureTargetHistory(target, now)
        if kind ~= "stab" then
            appendEvent({kind = kind, shotId = shotId, phase = "authored",
                serverTime = workspace:GetServerTimeNow(), clock = now,
                pingMs = pingMs,
                settings = info.settings, targetName = info.target and info.target.Name or nil,
                targetHistory = #targetHistory > 0 and targetHistory or nil})
        end
        local targetTrajectory: {TrajectoryPoint} = {}
        if target then
            local initialPoint: TrajectoryPoint? = captureTrajectoryPoint(
                target,
                now,
                pingMs
            )
            if initialPoint then
                table.insert(targetTrajectory, initialPoint)
            end
        end
        if kind == "stab" then
            runtime.sessionStabAttempts += 1
            local targetRoot: BasePart? = getTargetRoot(target)
            local localRoot: BasePart? =
                LocalPlayer.Character
                and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
                :: BasePart?
            local distance: number? = targetRoot
                and localRoot
                and (targetRoot.Position - localRoot.Position).Magnitude
            appendEvent({
                kind = "stab", shotId = shotId, phase = "attempt",
                serverTime = workspace:GetServerTimeNow(),
                pingMs = pingMs,
                distance = distance and math.floor(distance * 10 + 0.5) / 10 or nil,
                targetUserId = target and target.UserId or nil,
                targetName = target and target.Name or nil,
                targetState = targetTrajectory[1]
                    and targetTrajectory[1].humanoidState
                    or nil,
                targetTrajectory = #targetTrajectory > 0 and targetTrajectory or nil,
                targetHistory = #targetHistory > 0 and targetHistory or nil,
            })
        else
            local isGun: boolean = kind ~= "knife"
            local authoredTool: Tool? = nil
            if typeof(info.tool) == "Instance" and info.tool:IsA("Tool") then
                authoredTool = info.tool :: Tool
            end

            if isGun or authoredTool ~= nil then
                if isGun then
                    runtime.sessionGunAttempts += 1
                else
                    runtime.sessionKnifeAttempts += 1
                end
                beginPendingShot(isGun and "gun" or "knife", {
                    shotId = shotId,
                    attemptCounted = true,
                    tool = authoredTool,
                    shotMode = type(info.settings) == "table"
                            and info.settings.mode
                        or (info.silent and "Silent" or nil),
                    silentSpawn = info.variant,
                    activatedAt = now,
                    origin = info.originPos,
                    requestedAim = info.aimPos,
                    pingMs = pingMs,
                    targetTrajectory = targetTrajectory,
                    targetHistory = targetHistory,
                }, target)
            end
        end

        if type(state.emitGameBridgeEvent) == "function" then
            emitShot("authoringShot", {
                shotId = shotId,
                eventSource = "authored",
                settings = info.settings,
                kind = kind,
                toolName = tostring(info.toolName or (kind == "knife" and "Knife" or "Gun")),
                originPos = info.originPos,
                aimPos = info.aimPos,
                targetName = target and target.Name or nil,
                silent = info.silent == true,
                variant = info.variant,
                offset = info.offset,
            })
        end
    end

    function controller:status(): string
        local current: Estimates = estimates()
        local knifeText: string = current.knifeSpeed
                and string.format("%.2f studs/s", current.knifeSpeed)
            or "learning"
        local bucketCount: number = 0
        for _key: string in pairs(runtime.motionBuckets) do
            bucketCount += 1
        end
        return string.format(
            "MM2 session observations · guns %d · knives %d · motion buckets %d · knife %s",
            runtime.sessionGunConfirmed,
            runtime.sessionKnifeConfirmed,
            bucketCount,
            knifeText
        )
    end

    function controller:destroy(): ()
        if not runtime.active then
            return
        end
        if runtime.dirty then
            saveSnapshot("module-destroy")
        end
        runtime.active = false
        disconnectFeatureConnection("MM2TrajectorySampler")
        if runtime.trajectorySampler then
            runtime.trajectorySampler:Disconnect()
            runtime.trajectorySampler = nil
        end
        for projectile: Instance, track: KnifeTrack in pairs(runtime.tracks) do
            if track.destroyConnection then
                track.destroyConnection:Disconnect()
            end
            runtime.tracks[projectile] = nil
        end
        for _, connection: RBXScriptConnection in ipairs(runtime.connections) do
            connection:Disconnect()
        end
        table.clear(runtime.connections)
        table.clear(runtime.pendingGuns)
        table.clear(runtime.pendingKnives)
    end

    return controller
end

trajectoryCalibration = createTrajectoryCalibration()
state.mm2TrajectoryCalibration = trajectoryCalibration
trajectoryCalibration:start()

pcall(function(): ()
    if type((game :: any).BindToClose) == "function" then
        game:BindToClose(function(): ()
            if type(trajectoryCalibration.save) == "function" then
                pcall(trajectoryCalibration.save, trajectoryCalibration, "close")
            end
        end)
    end
end)

local weaponServiceModule: any = nil
type PendingShot = {
    target: Player,
    targetCharacter: Model?,
    gun: Tool,
    origin: Vector3,
    aimPosition: Vector3?,
    healthBefore: number,
    targetedMurderer: boolean,
    queuedAt: number,

    ambiguous: boolean?,
}

state.mm2ShotFeedback = {

    shootActive = false,
    pending = nil :: PendingShot?,
    lastAccepted = nil :: PendingShot?,

    token = 0,
    defaultDuration = 5,
    gunFiredConnected = false,
    theme = {
        Background = Color3.fromRGB(14, 14, 18),
        Accent = Color3.fromRGB(205, 82, 42),
        Outline = Color3.fromRGB(220, 115, 58),
        Text = Color3.fromRGB(255, 232, 208),
    },
    resolve = function(_candidate: PendingShot, _directHit: boolean): () end,
    showMiss = function(_gun: Tool, _candidate: PendingShot): () end,
}
state.mm2ShotFeedback.root = create("Frame", {
    Parent = ScreenGui,
    Name = "MM2ShotCooldown",
    AnchorPoint = Vector2.new(0.5, 0.5),
    BackgroundColor3 = state.mm2ShotFeedback.theme.Background,
    BackgroundTransparency = 0.38,
    BorderSizePixel = 0,
    ClipsDescendants = true,
    Position = UDim2.fromScale(0.5, 0.62),
    Size = UDim2.fromOffset(320, 36),
    Visible = false,
    ZIndex = 240,
}) :: Frame
create("UICorner", {
    Parent = state.mm2ShotFeedback.root,
    CornerRadius = UDim.new(0, 7),
})
create("UIStroke", {
    Parent = state.mm2ShotFeedback.root,
    Color = state.mm2ShotFeedback.theme.Outline,
    Transparency = 0.35,
    Thickness = 1,
})
state.mm2ShotFeedback.fill = create("Frame", {
    Parent = state.mm2ShotFeedback.root,
    Name = "Fill",
    BackgroundColor3 = state.mm2ShotFeedback.theme.Accent,
    BackgroundTransparency = 0.46,
    BorderSizePixel = 0,
    Size = UDim2.fromScale(0, 1),
    ZIndex = 241,
}) :: Frame
create("UICorner", {
    Parent = state.mm2ShotFeedback.fill,
    CornerRadius = UDim.new(0, 7),
})
state.mm2ShotFeedback.text = create("TextLabel", {
    TextTruncate = Enum.TextTruncate.AtEnd,
    ClipsDescendants = true,
    Parent = state.mm2ShotFeedback.root,
    Name = "Countdown",
    BackgroundTransparency = 1,
    Font = Enum.Font.GothamBold,
    Size = UDim2.fromScale(1, 1),
    Text = "",
    TextColor3 = state.mm2ShotFeedback.theme.Text,
