    local function toggleProximity(enabled: boolean): ()
        disconnectFeatureConnection("VDKillerProximity")
        if runtime.proximityGui then
            runtime.proximityGui:Destroy()
            runtime.proximityGui = nil
        end
        if not enabled then
            return
        end
        local gui: ScreenGui = createProximityGui()
        runtime.proximityGui = gui
        local panel: Frame = gui:WaitForChild("Panel") :: Frame
        local label: TextLabel = panel:WaitForChild("Distance") :: TextLabel
        local bar: Frame = (panel:WaitForChild("Track") :: Frame):WaitForChild("Bar") :: Frame
        featureConnections.VDKillerProximity = TaskManager:Connect(function(): ()
            if not isRoundActive() or not isLocalKiller() then
                gui.Enabled = false
                label.Text = "NEAREST SURVIVOR: NO SIGNAL"
                label.TextColor3 = Theme.textMuted
                bar.Size = UDim2.fromScale(0, 1)
                return
            end
            gui.Enabled = true
            local localRoot: BasePart? = getRoot(LocalPlayer.Character)
            local nearestDistance: number? = nil
            if localRoot then
                for _, player: Player in ipairs(Players:GetPlayers()) do
                    local team: Team? = player.Team
                    local targetRoot: BasePart? = getRoot(player.Character)
                    if player ~= LocalPlayer
                        and team ~= nil
                        and lower(team.Name) == "survivors"
                        and targetRoot ~= nil then
                        local distance: number = (targetRoot.Position - localRoot.Position).Magnitude
                        if nearestDistance == nil or distance < nearestDistance then
                            nearestDistance = distance
                        end
                    end
                end
            end
            if not nearestDistance then
                label.Text = "NEAREST SURVIVOR: NO SIGNAL"
                label.TextColor3 = Theme.textMuted
                bar.Size = UDim2.fromScale(0, 1)
                return
            end
            local distance: number = nearestDistance
            local color: Color3 = if distance <= 25
                then VD_KILLER_COLOR
                elseif distance <= 60 then Color3.fromRGB(244, 190, 88)
                else Theme.positive
            label.Text = string.format("NEAREST SURVIVOR: %.1f STUDS", distance)
            label.TextColor3 = color
            bar.BackgroundColor3 = color
            bar.Size = UDim2.fromScale(1 - math.clamp(distance / settings.proximityRange, 0, 1), 1)
        end)
    end


    local function findRemoteEvent(folderName: string, eventName: string): RemoteEvent?
        local remotes: Instance? = ReplicatedStorageService:FindFirstChild("Remotes")
        local folder: Instance? = if remotes then remotes:FindFirstChild(folderName) else nil
        local remote: Instance? = if folder then folder:FindFirstChild(eventName) else nil
        return if remote and remote:IsA("RemoteEvent") then remote else nil
    end

    local function getGeneratorForPoint(point: BasePart): Model?
        local parent: Instance? = point.Parent
        return if parent and parent:IsA("Model") and isGenerator(parent)
            then parent
            else nil
    end

    local function nearestGeneratorPoint(root: BasePart): BasePart?
        local map: Instance? = getMap()
        if not map then
            return nil
        end
        local bestPoint: BasePart? = nil
        local bestDistance: number = settings.autoGeneratorRange
        for _, descendant: Instance in ipairs(map:GetDescendants()) do
            if descendant:IsA("BasePart")
                and string.sub(lower(descendant.Name), 1, 14) == "generatorpoint" then
                local generator: Model? = getGeneratorForPoint(descendant)
                if generator then
                    local progress: number = generatorState(generator)
                    local distance: number = (descendant.Position - root.Position).Magnitude
                    if progress < 99.95 and distance <= bestDistance then
                        bestPoint = descendant
                        bestDistance = distance
                    end
                end
            end
        end
        return bestPoint
    end

    local function stopCurrentRepair(repairRemote: RemoteEvent?): ()
        local point: BasePart? = runtime.currentRepairPoint
        runtime.currentRepairPoint = nil
        local animationTrack: AnimationTrack? = runtime.repairAnimation
        if animationTrack then
            animationTrack:Stop(0.12)
            runtime.repairAnimation = nil
        end
        if runtime.repairAnimationObject then
            runtime.repairAnimationObject:Destroy()
            runtime.repairAnimationObject = nil
        end
        if repairRemote and point and point.Parent then
            repairRemote:FireServer(point, false)
        end
    end

    local function maintainRepairAnimation(): ()
        if not settings.autoGeneratorAnimation then
            local current: AnimationTrack? = runtime.repairAnimation
            if current then
                current:Stop(0.12)
                runtime.repairAnimation = nil
            end
            return
        end
        local track: AnimationTrack? = runtime.repairAnimation
        if track and track.IsPlaying then
            return
        end
        local character: Model? = LocalPlayer.Character
        local humanoid: Humanoid? = if character
            then character:FindFirstChildOfClass("Humanoid")
            else nil
        local animator: Animator? = if humanoid
            then humanoid:FindFirstChildOfClass("Animator")
            else nil
        if not animator then
            return
        end
        local animation: Animation = Instance.new("Animation")
        animation.Name = "Wurst_VD_RepairCrouch"
        animation.AnimationId = "rbxassetid://73650663675588"
        local ok: boolean, loaded: any = pcall(function(): AnimationTrack
            return animator:LoadAnimation(animation)
        end)
        if not ok or not loaded then
            animation:Destroy()
            return
        end
        track = loaded :: AnimationTrack
        track.Looped = true
        track.Priority = Enum.AnimationPriority.Action
        track:Play(0.12, 1, 1)
        runtime.repairAnimationObject = animation
        runtime.repairAnimation = track
    end

    local function killerInsideCriticalRange(root: BasePart): boolean
        local _, killer: Model? = getKiller()
        local killerRoot: BasePart? = getRoot(killer)
        return killerRoot ~= nil
            and (killerRoot.Position - root.Position).Magnitude < 4
    end

    local function toggleAutoGeneratorAura(enabled: boolean): ()
        disconnectFeatureConnection("VDAutoGeneratorAura")
        disconnectFeatureConnection("VDAutoGeneratorCancel")
        local repairRemote: RemoteEvent? = findRemoteEvent("Generator", "RepairEvent")
        stopCurrentRepair(repairRemote)
        runtime.manualGeneratorBlocked = false
        runtime.manualGeneratorLeft = false
        runtime.manualGeneratorOrigin = nil
        if not enabled then
            return
        end
        assert(repairRemote, "VD Remotes.Generator.RepairEvent is unavailable")
        featureConnections.VDAutoGeneratorCancel = UserInputService.InputBegan:Connect(function(
            input: InputObject,
            _gameProcessed: boolean
        ): ()
            if not state.keyCaptureCallback
                and not state.waitingForKey
                and input.KeyCode == Enum.KeyCode.Space
                and settings.autoGeneratorGetOff == "Manual" then
                local currentPoint: BasePart? = runtime.currentRepairPoint
                local root: BasePart? = getRoot(LocalPlayer.Character)
                runtime.manualGeneratorBlocked = true
                runtime.manualGeneratorLeft = false
                runtime.manualGeneratorOrigin = if currentPoint
                    then currentPoint.Position
                    elseif root then root.Position
                    else nil
                stopCurrentRepair(repairRemote)
                notify("Auto Generator paused; move 5 studs away and return.")
            end
        end)
        featureConnections.VDAutoGeneratorAura = TaskManager:Connect(function(): ()
            local team: Team? = LocalPlayer.Team
            local root: BasePart? = getRoot(LocalPlayer.Character)
            if not isRoundActive()
                or not team
                or lower(team.Name) ~= "survivors"
                or not root then
                stopCurrentRepair(repairRemote)
                return
            end
            if settings.autoGeneratorGetOff == "Smart"
                and killerInsideCriticalRange(root) then
                stopCurrentRepair(repairRemote)
                return
            end
            if settings.autoGeneratorGetOff == "Manual"
                and runtime.manualGeneratorBlocked then
                local origin: Vector3? = runtime.manualGeneratorOrigin
                local originDistance: number = if origin
                    then (root.Position - origin).Magnitude
                    else 0
                if not runtime.manualGeneratorLeft and originDistance >= 5 then
                    runtime.manualGeneratorLeft = true
                elseif runtime.manualGeneratorLeft
                    and originDistance <= settings.autoGeneratorRange then
                    runtime.manualGeneratorBlocked = false
                    runtime.manualGeneratorLeft = false
                    runtime.manualGeneratorOrigin = nil
                else
                    stopCurrentRepair(repairRemote)
                    return
                end
            end
            local point: BasePart? = nearestGeneratorPoint(root)
            if point ~= runtime.currentRepairPoint then
                stopCurrentRepair(repairRemote)
                runtime.currentRepairPoint = point
            end
            if not point then
                stopCurrentRepair(repairRemote)
                return
            end
            maintainRepairAnimation()
            if settings.autoGeneratorMode == "Blatant" then

                if os.clock() - runtime.lastRepairFire >= 0.03 then
                    runtime.lastRepairFire = os.clock()
                    repairRemote:FireServer(point, true)
                end
            elseif os.clock() - runtime.lastRepairFire >= settings.autoGeneratorInterval then
                runtime.lastRepairFire = os.clock()
                repairRemote:FireServer(point, true)
            end
        end)
    end

    local function isAttackTrack(track: AnimationTrack): boolean
        local animation: Animation? = track.Animation
        local descriptor: string = lower(track.Name)
            .. " "
            .. lower(if animation then animation.AnimationId else "")
        for _, excluded: string in ipairs({
            "idle", "walk", "run", "vault", "stun", "carry", "mori", "break",
        }) do
            if contains(descriptor, excluded) then
                return false
            end
        end
        for _, keyword: string in ipairs({
            "attack", "swing", "slash", "stab", "strike", "lunge", "basic", "m1",
        }) do
            if contains(descriptor, keyword) then
                return true
            end
        end
        return track.Priority == Enum.AnimationPriority.Action
            or track.Priority == Enum.AnimationPriority.Action2
            or track.Priority == Enum.AnimationPriority.Action3
            or track.Priority == Enum.AnimationPriority.Action4
    end

    local function bindAutoParryAnimator(
        animator: Animator?,
        parryRemote: RemoteEvent
    ): ()
        if runtime.boundKillerAnimator == animator then
            return
        end
        disconnectFeatureConnection("VDAutoParryAnimation")
        runtime.boundKillerAnimator = animator
        if not animator then
            return
        end
        featureConnections.VDAutoParryAnimation = animator.AnimationPlayed:Connect(function(
            track: AnimationTrack
        ): ()
            if not isAttackTrack(track) or not isRoundActive() then
                return
            end
            local team: Team? = LocalPlayer.Team
            local localRoot: BasePart? = getRoot(LocalPlayer.Character)
            local killer: Model? = animator:FindFirstAncestorOfClass("Model")
            local killerRoot: BasePart? = getRoot(killer)
            if not team
                or lower(team.Name) ~= "survivors"
                or not localRoot
                or not killerRoot
                or (killerRoot.Position - localRoot.Position).Magnitude > settings.autoParryRange
                or os.clock() - runtime.lastParry < 0.22 then
                return
            end
            runtime.lastParry = os.clock()
            parryRemote:FireServer()
        end)
    end

    local function toggleAutoParry(enabled: boolean): ()
        disconnectFeatureConnection("VDAutoParryScan")
        disconnectFeatureConnection("VDAutoParryAnimation")
        runtime.boundKillerAnimator = nil
        if not enabled then
            return
        end
        local parryRemote: RemoteEvent? = nil
        local remotes: Instance? = ReplicatedStorageService:FindFirstChild("Remotes")
        local items: Instance? = if remotes then remotes:FindFirstChild("Items") else nil
        local dagger: Instance? = if items then items:FindFirstChild("Parrying Dagger") else nil
        local candidate: Instance? = if dagger then dagger:FindFirstChild("parry") else nil
        if candidate and candidate:IsA("RemoteEvent") then
            parryRemote = candidate
        end
        assert(parryRemote, "VD Remotes.Items.Parrying Dagger.parry is unavailable")
        local elapsed: number = 1
        featureConnections.VDAutoParryScan = TaskManager:Connect(function(deltaTime: number): ()
            elapsed += deltaTime
            if elapsed < 0.1 then
                return
            end
            elapsed = 0
            local _, killer: Model? = getKiller()
            local humanoid: Humanoid? = if killer then killer:FindFirstChildOfClass("Humanoid") else nil
            local animator: Animator? = if humanoid then humanoid:FindFirstChildOfClass("Animator") else nil
            bindAutoParryAnimator(if getMap() then animator else nil, parryRemote :: RemoteEvent)
        end)
    end

    local function nearestSurvivor(root: BasePart, maximumRange: number): BasePart?
        local best: BasePart? = nil
        local bestDistance: number = maximumRange
        for _, player: Player in ipairs(Players:GetPlayers()) do
            local character: Model? = player.Character
            local humanoid: Humanoid? = if character then character:FindFirstChildOfClass("Humanoid") else nil
            local targetRoot: BasePart? = getRoot(character)
            if player ~= LocalPlayer
                and player.Team ~= nil
                and lower((player.Team :: Team).Name) == "survivors"
                and humanoid
                and humanoid.Health > 0
                and targetRoot then
                local distance: number = (targetRoot.Position - root.Position).Magnitude
                if distance <= bestDistance then
                    best = targetRoot
                    bestDistance = distance
                end
            end
        end
        return best
    end

    local function toggleKillerHitAura(enabled: boolean): ()
        disconnectFeatureConnection("VDKillerHitAura")
        if not enabled then
            local character: Model? = LocalPlayer.Character
            local humanoid: Humanoid? = if character
                then character:FindFirstChildOfClass("Humanoid")
                else nil
            if humanoid and runtime.killerBaseWalkSpeed and not runtime.walkSpeedEnabled then
                humanoid.WalkSpeed = runtime.killerBaseWalkSpeed
            end
            runtime.killerBaseWalkSpeed = nil
            return
        end
        local attackRemote: RemoteEvent? = findRemoteEvent("Attacks", "BasicAttack")
        assert(attackRemote, "VD Remotes.Attacks.BasicAttack is unavailable")
        featureConnections.VDKillerHitAura = TaskManager:Connect(function(): ()
            local team: Team? = LocalPlayer.Team
            local character: Model? = LocalPlayer.Character
            local localRoot: BasePart? = getRoot(LocalPlayer.Character)
            local humanoid: Humanoid? = if character
                then character:FindFirstChildOfClass("Humanoid")
                else nil
            if not isRoundActive()
                or not team
                or lower(team.Name) ~= "killer"
                or not localRoot
                or not humanoid then
                return
            end
            if runtime.killerBaseWalkSpeed == nil then
                runtime.killerBaseWalkSpeed = humanoid.WalkSpeed
            end
            local preventSlowdown: boolean = settings.hitAuraMode == "Blatant"
                or settings.hitAuraRun == true
            if preventSlowdown then
                humanoid.WalkSpeed = math.max(
                    humanoid.WalkSpeed,
                    runtime.killerBaseWalkSpeed :: number
                )
            end
            local attackRange: number = if settings.hitAuraMode == "Blatant"
                then settings.hitAuraBlatantReach
                else settings.hitAuraRange
            local target: BasePart? = nearestSurvivor(localRoot, attackRange)
            if not target then
                return
            end
            if settings.hitAuraMode == "Blatant" then

                if os.clock() - runtime.lastHit >= 0.12 then
                    runtime.lastHit = os.clock()
                    attackRemote:FireServer()
                end
            elseif os.clock() - runtime.lastHit >= settings.hitAuraInterval then
                runtime.lastHit = os.clock()
                attackRemote:FireServer()
            end
        end)
    end

    local function isFootstepSound(sound: Sound): boolean
        local name: string = lower(sound.Name)
        return contains(name, "foot")
            or contains(name, "step")
            or contains(name, "running")
            or contains(name, "walking")
            or contains(name, "sprint")
    end

    local function silenceSound(sound: Sound): ()
        if not isFootstepSound(sound) or runtime.soundStates[sound] then
            return
        end
        runtime.soundStates[sound] = {volume = sound.Volume}
        sound.Volume = 0
        sound:Stop()
        runtime.soundConnections[sound] = sound.Played:Connect(function(): ()
            if runtime.silentStepsEnabled then
                sound.Volume = 0
                sound:Stop()
            end
        end)
    end

    local function restoreSilentSounds(): ()
        for sound: Sound, connection: RBXScriptConnection in pairs(runtime.soundConnections) do
            connection:Disconnect()
            runtime.soundConnections[sound] = nil
        end
        for sound: Sound, original: SoundState in pairs(runtime.soundStates) do
            if sound.Parent then
                sound.Volume = original.volume
            end
            runtime.soundStates[sound] = nil
        end
    end

    local function bindSilentCharacter(character: Model): ()
        disconnectFeatureConnection("VDSilentDescendant")
        for _, descendant: Instance in ipairs(character:GetDescendants()) do
            if descendant:IsA("Sound") then
                silenceSound(descendant)
            end
        end
        featureConnections.VDSilentDescendant = character.DescendantAdded:Connect(function(
            descendant: Instance
        ): ()
            if descendant:IsA("Sound") then
                silenceSound(descendant)
            end
        end)
    end

    local function toggleSilentSteps(enabled: boolean): ()
        disconnectFeatureConnection("VDSilentCharacter")
        disconnectFeatureConnection("VDSilentDescendant")
        runtime.silentStepsEnabled = enabled
        restoreSilentSounds()
        if not enabled then
            return
        end
        if LocalPlayer.Character then
            bindSilentCharacter(LocalPlayer.Character)
        end
        featureConnections.VDSilentCharacter = LocalPlayer.CharacterAdded:Connect(function(
            character: Model
        ): ()
            if runtime.silentStepsEnabled then
                bindSilentCharacter(character)
            end
        end)
    end

    local function nearestVault(root: BasePart): BasePart?
        local map: Instance? = getMap()
        local best: BasePart? = nil
        local bestDistance: number = settings.vaultRange
        if not map then
            return nil
        end
        for _, descendant: Instance in ipairs(map:GetDescendants()) do
            if descendant:IsA("BasePart") and lower(descendant.Name) == "vaulttrigger" then
                local distance: number = (descendant.Position - root.Position).Magnitude
                if distance < bestDistance then
                    best = descendant
                    bestDistance = distance
                end
            end
        end
        return best
    end

    local function toggleFastVault(enabled: boolean): ()
        disconnectFeatureConnection("VDFastVault")
        if not enabled then
            return
        end
        local vaultRemote: RemoteEvent? = findRemoteEvent("Window", "VaultEvent")
        local fastVaultRemote: RemoteEvent? = findRemoteEvent("Window", "fastvault")
        local completePartRemote: RemoteEvent? = findRemoteEvent(
            "Window",
            "VaultCompleteEventpart1"
        )
        local completeRemote: RemoteEvent? = findRemoteEvent("Window", "VaultCompleteEvent")
        assert(vaultRemote, "VD Remotes.Window.VaultEvent is unavailable")
        local verifiedVaultRemote: RemoteEvent = vaultRemote :: RemoteEvent
        featureConnections.VDFastVault = TaskManager:Connect(function(): ()
            local character: Model? = LocalPlayer.Character
            local root: BasePart? = getRoot(character)
            local humanoid: Humanoid? = if character then character:FindFirstChildOfClass("Humanoid") else nil
            if not root or not humanoid or humanoid.MoveDirection.Magnitude < 0.2 then
                return
            end
            local trigger: BasePart? = nearestVault(root)
            if not trigger then
                return
            end
            local repeatDelay: number = math.max(0.08, 0.55 / settings.vaultSpeed)
            if trigger ~= runtime.lastVaultPoint
                or os.clock() - runtime.lastVaultInput > repeatDelay then
                runtime.lastVaultInput = os.clock()
                runtime.lastVaultPoint = trigger
                local destination: CFrame = trigger.CFrame * CFrame.new(0, 2, -1)
                root.CFrame = root.CFrame:Lerp(
                    destination,
                    math.clamp(settings.vaultSpeed / 10, 0.25, 1)
                )
                verifiedVaultRemote:FireServer(trigger, true)
                if fastVaultRemote then
                    fastVaultRemote:FireServer(LocalPlayer)
                end
                if completePartRemote then
                    completePartRemote:FireServer()
                end
                if completeRemote then
                    completeRemote:FireServer(trigger, false)
                end
            end
        end)
    end

    local facingParts: {[Player]: Part} = {}
    local function clearFacing(): ()
        for player: Player, part: Part in pairs(facingParts) do
            part:Destroy()
            facingParts[player] = nil
        end
    end

    local function toggleFacingESP(enabled: boolean): ()
        disconnectFeatureConnection("VDFacingESP")
        clearFacing()
        if not enabled then
            return
        end
        featureConnections.VDFacingESP = TaskManager:Connect(function(): ()
            if not getMap() then
                clearFacing()
                return
            end
            for _, player: Player in ipairs(Players:GetPlayers()) do
                if player ~= LocalPlayer
                    and isPlayerInRound(player)
                    and player.Character then
                    local head: BasePart? = player.Character:FindFirstChild("Head") :: BasePart?
                    if head then
                        local line: Part? = facingParts[player]
                        if not line then
                            line = Instance.new("Part")
                            line.Name = "Wurst_VD_Facing"
                            line.Anchored = true
                            line.CanCollide = false
                            line.CanQuery = false
                            line.CanTouch = false
                            line.CastShadow = false
                            line.Material = Enum.Material.Neon
                            line.Transparency = 0.28
                            line.Parent = getVisualFolder()
                            facingParts[player] = line
                        end
                        local length: number = 16
                        local origin: Vector3 = head.Position
                        local direction: Vector3 = head.CFrame.LookVector
                        line.Color = if isKillerCharacter(player.Character)
                            then VD_KILLER_COLOR else Theme.accent
                        line.Size = Vector3.new(0.08, 0.08, length)
                        line.CFrame = CFrame.lookAt(
                            origin + direction * (length / 2),
                            origin + direction * length
                        )
                    end
                end
            end
            for player: Player, part: Part in pairs(facingParts) do
                if not player.Parent or not player.Character then
                    part:Destroy()
                    facingParts[player] = nil
                end
            end
        end)
    end

    local function isHiding(player: Player, character: Model): boolean
        for _, name: string in ipairs({"Hiding", "InLocker", "IsHiding", "Hidden"}) do
            if player:GetAttribute(name) == true or character:GetAttribute(name) == true then
                return true
            end
        end
        local lockerValue: Instance? = character:FindFirstChild("Locker", true)
            or character:FindFirstChild("CurrentLocker", true)
        return lockerValue ~= nil
    end

    local function clearLockerMarkers(): ()
        for player: Player, record: MarkerRecord in pairs(runtime.lockerMarkers) do
            destroyMarker(record)
            runtime.lockerMarkers[player] = nil
        end
    end

    local function toggleLockerDetector(enabled: boolean): ()
        disconnectFeatureConnection("VDLockerDetector")
        table.clear(runtime.lockerAlerts)
        clearLockerMarkers()
        if not enabled then
            return
        end
        local elapsed: number = 1
        featureConnections.VDLockerDetector = TaskManager:Connect(function(deltaTime: number): ()
            elapsed += deltaTime
            if elapsed < 0.25 then
                return
            end
            elapsed = 0
            local localRoot: BasePart? = getRoot(LocalPlayer.Character)
            if not getMap() or not localRoot then
                clearLockerMarkers()
                return
            end
            for _, player: Player in ipairs(Players:GetPlayers()) do
                local character: Model? = player.Character
                local root: BasePart? = getRoot(character)
                local record: MarkerRecord? = runtime.lockerMarkers[player]
                local hidingInRange: boolean = player ~= LocalPlayer and character ~= nil and root ~= nil
                    and not isKillerCharacter(character)
                    and isHiding(player, character)
                    and (root.Position - localRoot.Position).Magnitude <= settings.lockerRange
                if hidingInRange and character and root then
                    local distance: number = (root.Position - localRoot.Position).Magnitude
                    local text: string = string.format(
                        "HIDDEN PLAYER\n%s · %.0f STUDS",
                        player.DisplayName,
                        distance
                    )
                    if not record or record.highlight.Adornee ~= character then
                        destroyMarker(record)
                        record = createMarker(character, root, Theme.accent, text, 600)
                        record.highlight.FillTransparency = 0.3
                        record.highlight.OutlineTransparency = 0
                        runtime.lockerMarkers[player] = record
                    elseif record.label then
                        record.label.Text = text
                    end
                    local lastAlert: number = runtime.lockerAlerts[player] or 0
                    if os.clock() - lastAlert > 8 then
                        runtime.lockerAlerts[player] = os.clock()
                        notify(player.DisplayName .. " entered a nearby locker/hideout.")
                    end
                elseif record then
                    destroyMarker(record)
                    runtime.lockerMarkers[player] = nil
                end
            end
            for player: Player, record: MarkerRecord in pairs(runtime.lockerMarkers) do
                if not player.Parent then
                    destroyMarker(record)
                    runtime.lockerMarkers[player] = nil
                end
            end
        end)
    end

    local function isAcceleratedAction(track: AnimationTrack): boolean
        local animation: Animation? = track.Animation
        local descriptor: string = lower(track.Name)
            .. " "
            .. lower(if animation then animation.AnimationId else "")
        for _, keyword: string in ipairs({
            "vault", "pallet", "break", "hook", "unhook", "rescue",
            "repair", "heal", "interact", "open", "lever", "pickup",
        }) do
            if contains(descriptor, keyword) then
                return true
            end
        end
        return track.Priority == Enum.AnimationPriority.Action
            or track.Priority == Enum.AnimationPriority.Action2
            or track.Priority == Enum.AnimationPriority.Action3
            or track.Priority == Enum.AnimationPriority.Action4
    end

    local function bindActionAnimator(animator: Animator?): ()
        if runtime.actionAnimator == animator then
            return
        end
        disconnectFeatureConnection("VDCooldownAnimation")
        runtime.actionAnimator = animator
        if not animator then
            return
        end
        featureConnections.VDCooldownAnimation = animator.AnimationPlayed:Connect(function(
            track: AnimationTrack
        ): ()
            if runtime.cooldownModifierEnabled and isAcceleratedAction(track) then
                track:AdjustSpeed(settings.actionSpeed)
            end
        end)
        for _, track: AnimationTrack in ipairs(animator:GetPlayingAnimationTracks()) do
            if isAcceleratedAction(track) then
                track:AdjustSpeed(settings.actionSpeed)
            end
        end
    end

    local function toggleCooldownModifier(enabled: boolean): ()
        disconnectFeatureConnection("VDCooldownModifier")
        disconnectFeatureConnection("VDCooldownAnimation")
        runtime.cooldownModifierEnabled = enabled
        runtime.actionAnimator = nil
        if not enabled then
            local character: Model? = LocalPlayer.Character
            local humanoid: Humanoid? = if character
                then character:FindFirstChildOfClass("Humanoid")
                else nil
            local animator: Animator? = if humanoid
                then humanoid:FindFirstChildOfClass("Animator")
                else nil
            if animator then
                for _, track: AnimationTrack in ipairs(animator:GetPlayingAnimationTracks()) do
                    if isAcceleratedAction(track) then
                        track:AdjustSpeed(1)
                    end
                end
            end
            return
        end
        featureConnections.VDCooldownModifier = TaskManager:Connect(function(): ()
            local character: Model? = LocalPlayer.Character
            local humanoid: Humanoid? = if character
                then character:FindFirstChildOfClass("Humanoid")
                else nil
            local animator: Animator? = if humanoid
                then humanoid:FindFirstChildOfClass("Animator")
                else nil
            bindActionAnimator(animator)
        end)
    end

    local function bindDamageHumanoid(humanoid: Humanoid?): ()
        if runtime.trackedHumanoid == humanoid then
            return
        end
        disconnectFeatureConnection("VDDamageHealth")
        runtime.trackedHumanoid = humanoid
        if not humanoid then
            return
        end
        local previousHealth: number = humanoid.Health
        featureConnections.VDDamageHealth = humanoid.HealthChanged:Connect(function(
            health: number
        ): ()
            if runtime.damageBoostEnabled and health < previousHealth and health > 0 then
                runtime.damageBoostToken += 1
                local boostToken: number = runtime.damageBoostToken
                local originalSpeed: number = humanoid.WalkSpeed
                runtime.damageOriginalSpeed = originalSpeed
                runtime.damageBoostUntil = os.clock() + settings.damageBoostDuration
                humanoid.WalkSpeed = math.max(
                    humanoid.WalkSpeed,
                    originalSpeed + settings.damageBoost
                )
                task.delay(settings.damageBoostDuration, function(): ()
                    if runtime.damageBoostEnabled
                        and runtime.damageBoostToken == boostToken
                        and humanoid.Parent
                        and not runtime.walkSpeedEnabled then
                        humanoid.WalkSpeed = originalSpeed
                        runtime.damageOriginalSpeed = nil
                    end
                end)
            end
            previousHealth = health
        end)
    end

    local function toggleDamageBoost(enabled: boolean): ()
        disconnectFeatureConnection("VDDamageBoost")
        disconnectFeatureConnection("VDDamageHealth")
        runtime.damageBoostEnabled = enabled
        runtime.trackedHumanoid = nil
        runtime.damageBoostToken += 1
        runtime.damageBoostUntil = 0
        if not enabled then
            local character: Model? = LocalPlayer.Character
            local humanoid: Humanoid? = if character
                then character:FindFirstChildOfClass("Humanoid")
                else nil
            if humanoid and runtime.damageOriginalSpeed and not runtime.walkSpeedEnabled then
                humanoid.WalkSpeed = runtime.damageOriginalSpeed
            end
            runtime.damageOriginalSpeed = nil
            return
        end
        featureConnections.VDDamageBoost = TaskManager:Connect(function(): ()
            local character: Model? = LocalPlayer.Character
            local humanoid: Humanoid? = if character
                then character:FindFirstChildOfClass("Humanoid")
                else nil
            bindDamageHumanoid(humanoid)
        end)
    end

    local function isSelectiveNoclipPart(part: BasePart): boolean
        local cursor: Instance? = part
        for _depth: number = 1, 4 do
            if not cursor then
                break
            end
            local name: string = lower(cursor.Name)
            if contains(name, "pallet")
                or contains(name, "vault")
                or contains(name, "window") then
                return true
            end
            if cursor:IsA("Model")
                and cursor:FindFirstChild("VaultTrigger") ~= nil then
                return true
            end
            cursor = cursor.Parent
        end
        return false
    end

    local function restoreSelectiveCollisions(): ()
        for part: BasePart, original: CollisionState in pairs(runtime.selectiveCollisions) do
            if part.Parent then
                part.CanCollide = original.canCollide
            end
            runtime.selectiveCollisions[part] = nil
        end
    end

    local function toggleSelectiveNoclip(enabled: boolean): ()
        disconnectFeatureConnection("VDSelectiveNoclip")
        restoreSelectiveCollisions()
        if not enabled then
            return
        end
        local elapsed: number = 1
        featureConnections.VDSelectiveNoclip = TaskManager:Connect(function(
            deltaTime: number
        ): ()
            elapsed += deltaTime
            if elapsed < 0.35 then
                return
            end
            elapsed = 0
            local map: Instance? = getMap()
            if not map then
                restoreSelectiveCollisions()
                return
            end
            for _, descendant: Instance in ipairs(map:GetDescendants()) do
                if descendant:IsA("BasePart")
                    and descendant.CanCollide
                    and isSelectiveNoclipPart(descendant) then
                    if not runtime.selectiveCollisions[descendant] then
                        runtime.selectiveCollisions[descendant] = {
                            canCollide = descendant.CanCollide,
                        }
                    end
                    descendant.CanCollide = false
                end
            end
            for part: BasePart, original: CollisionState in pairs(runtime.selectiveCollisions) do
                if not part:IsDescendantOf(map) then
                    if part.Parent then
                        part.CanCollide = original.canCollide
                    end
                    runtime.selectiveCollisions[part] = nil
                end
            end
        end)
    end

    local function toggleWalkSpeed(enabled: boolean): ()
        disconnectFeatureConnection("VDWalkSpeed")
        runtime.walkSpeedEnabled = enabled
        local character: Model? = LocalPlayer.Character
        local humanoid: Humanoid? = if character
            then character:FindFirstChildOfClass("Humanoid")
            else nil
        if not enabled then
            if humanoid and runtime.walkSpeedBase then
                humanoid.WalkSpeed = runtime.walkSpeedBase
            end
            runtime.walkSpeedBase = nil
            return
        end
        runtime.walkSpeedBase = if humanoid then humanoid.WalkSpeed else settings.walkSpeed
        featureConnections.VDWalkSpeed = TaskManager:Connect(function(): ()
            local currentCharacter: Model? = LocalPlayer.Character
            local currentHumanoid: Humanoid? = if currentCharacter
                then currentCharacter:FindFirstChildOfClass("Humanoid")
                else nil
            if currentHumanoid and isRoundActive() then
                local activeBoost: number = if os.clock() < runtime.damageBoostUntil
                    then settings.damageBoost
                    else 0
                currentHumanoid.WalkSpeed = settings.walkSpeed + activeBoost
            end
        end)
    end

    local function createCooldownGui(): ScreenGui
        local gui: ScreenGui = Instance.new("ScreenGui")
        gui.Name = "Wurst_VD_Cooldowns"
        gui.IgnoreGuiInset = true
        gui.ResetOnSpawn = false
        gui.Parent = PlayerGui
        local label: TextLabel = Instance.new("TextLabel")
        label.Name = "Cooldowns"
        label.AnchorPoint = Vector2.new(1, 0.5)
        label.BackgroundColor3 = Color3.fromRGB(10, 13, 21)
        label.BackgroundTransparency = 0.12
        label.BorderSizePixel = 0
        label.Font = Enum.Font.GothamMedium
        label.Position = UDim2.new(1, -22, 0.5, 0)
        label.Size = UDim2.fromOffset(260, 100)
        label.Text = "KILLER POWER\nNO DATA"
        label.TextColor3 = Theme.text
        label.TextSize = 13
        label.TextWrapped = true
        label.Parent = gui
        local corner: UICorner = Instance.new("UICorner")
        corner.CornerRadius = UDim.new(0, 11)
        corner.Parent = label
        return gui
    end

    local function cooldownText(): string
        local killerPlayer: Player?, killer: Model? = getKiller()
        if not killer then
            return "KILLER POWER\nNO SIGNAL"
        end
        local lines: {string} = {"KILLER POWER"}
        local function appendAttributes(instance: Instance): ()
            for name: string, value: any in pairs(instance:GetAttributes()) do
                local key: string = lower(name)
                if (contains(key, "cooldown") or contains(key, "charge") or contains(key, "power"))
                    and (type(value) == "number" or type(value) == "boolean") then
                    table.insert(lines, name .. ": " .. tostring(value))
                    if #lines >= 6 then
                        return
                    end
                end
            end
        end
        appendAttributes(killer)
        if killerPlayer and #lines < 6 then
            appendAttributes(killerPlayer)
        end
        if #lines == 1 then
            table.insert(lines, "READY / NO REPLICATED TIMER")
        end
        return table.concat(lines, "\n")
    end

    local function toggleCooldownTracker(enabled: boolean): ()
        disconnectFeatureConnection("VDCooldownTracker")
        if runtime.cooldownGui then
            runtime.cooldownGui:Destroy()
            runtime.cooldownGui = nil
        end
        if not enabled then
            return
        end
        local gui: ScreenGui = createCooldownGui()
        runtime.cooldownGui = gui
        local label: TextLabel = gui:WaitForChild("Cooldowns") :: TextLabel
        local elapsed: number = 1
        featureConnections.VDCooldownTracker = TaskManager:Connect(function(deltaTime: number): ()
            elapsed += deltaTime
            if elapsed >= 0.15 then
                elapsed = 0
                label.Text = cooldownText()
            end
        end)
    end

    local function suppressBlindEffect(effect: Instance): ()
        local name: string = lower(effect.Name)
        if not contains(name, "blind")
            and not contains(name, "flash")
            and not contains(name, "whiteout") then
            return
        end
        if effect:IsA("PostEffect") then
            if runtime.effectStates[effect] == nil then
                runtime.effectStates[effect] = effect.Enabled
            end
            effect.Enabled = false
        elseif effect:IsA("GuiObject") and effect ~= ScreenGui then
            if runtime.effectStates[effect] == nil then
                runtime.effectStates[effect] = effect.Visible
            end
            effect.Visible = false
        end
    end

    local function toggleNoBlind(enabled: boolean): ()
        disconnectFeatureConnection("VDNoBlindLighting")
        disconnectFeatureConnection("VDNoBlindGui")
        disconnectFeatureConnection("VDNoBlindGuard")
        if not enabled then
            for effect: Instance, original: any in pairs(runtime.effectStates) do
                if effect.Parent then
                    if effect:IsA("PostEffect") then
                        effect.Enabled = original
                    elseif effect:IsA("GuiObject") then
                        effect.Visible = original
                    end
                end
                runtime.effectStates[effect] = nil
            end
            return
        end
        for _, root: Instance in ipairs({Lighting, PlayerGui}) do
            for _, descendant: Instance in ipairs(root:GetDescendants()) do
                suppressBlindEffect(descendant)
            end
        end
        featureConnections.VDNoBlindLighting = Lighting.DescendantAdded:Connect(function(
            descendant: Instance
        ): ()
            suppressBlindEffect(descendant)
        end)
        featureConnections.VDNoBlindGui = PlayerGui.DescendantAdded:Connect(function(
            descendant: Instance
        ): ()
            suppressBlindEffect(descendant)
        end)
        featureConnections.VDNoBlindGuard = TaskManager:Connect(function(): ()
            for effect: Instance, _original: any in pairs(runtime.effectStates) do
                if not effect.Parent then
                    runtime.effectStates[effect] = nil
                elseif effect:IsA("PostEffect") then
                    effect.Enabled = false
                elseif effect:IsA("GuiObject") then
                    effect.Visible = false
                end
            end
        end)
    end

    registerRoleProvider({
        Name = "VD",
        Roles = {"Killer", "Survivor"},
        Colors = {
            Killer = Color3.fromRGB(226, 72, 72),
            Survivor = Color3.fromRGB(120, 190, 255),
        },
        Get = function(player: Player): string?
            local character: Model? = player.Character
            if not character then
                return nil
            end
            return isKillerCharacter(character) and "Killer" or "Survivor"
        end,
    })

    registerEspExtra({
        Name = "Generators",
        Default = false,
        Tooltip = "Match generators with their exact progress, state and "
            .. "distance. workspace.Map only; Lobby and Spectator objects are "
            .. "ignored.",
        Toggle = toggleGeneratorESP,
        Options = {
            {
                Kind = "number",
                Name = "max distance",
                Default = 1800,
                Min = 200,
                Max = 3000,
                Set = function(value: number): ()
                    settings.generatorDistance = value
                end,
            },
            {
                Kind = "number",
                Name = "fill",
                Default = 0.82,
                Min = 0,
                Max = 1,
                Set = function(value: number): ()
                    settings.generatorTransparency = math.clamp(value, 0, 1)
                end,
            },
        },
    })

    local GeneratorAuraFeature: any = createUniversalFeature(
        "Auto Generator",
        "Automatically maintains the native RepairEvent on a nearby generator point",
        3,
        toggleAutoGeneratorAura,
        {parent = state.vdScroll, registry = state.vdFeatures}
    )
    addToggleOption(GeneratorAuraFeature, "Animation", true, function(value: boolean): ()
        settings.autoGeneratorAnimation = value
    end)
    addCycleOption(GeneratorAuraFeature, "Get Off", {"Manual", "Smart"}, 1, function(value: string): ()
        settings.autoGeneratorGetOff = value
        runtime.manualGeneratorBlocked = false
        runtime.manualGeneratorLeft = false
        runtime.manualGeneratorOrigin = nil
    end)
    addNumberOption(GeneratorAuraFeature, "Interaction range", 18, 5, 30, function(value: number): ()
        settings.autoGeneratorRange = math.max(1, value)
    end)
    local GeneratorIntervalOption: Frame = addNumberOption(
        GeneratorAuraFeature,
        "Legit interval",
        0.12,
        0.03,
        0.5,
        function(value: number): ()
            settings.autoGeneratorInterval = math.max(0.01, value)
        end
    )
    addCycleOption(GeneratorAuraFeature, "Mode", {"Legit", "Blatant"}, 1, function(value: string): ()
        settings.autoGeneratorMode = value
        setOptionVisible(GeneratorAuraFeature, GeneratorIntervalOption, value == "Legit")
    end)

    local AutoParryFeature: any = createUniversalFeature(
        "Auto Parry / Auto Block",
        "Fire the dagger parry remote when an in-range Killer attack starts",
        4,
        toggleAutoParry,
        {parent = state.vdScroll, registry = state.vdFeatures}
    )
    addNumberOption(AutoParryFeature, "Parry range", 18, 4, 35, function(value: number): ()
        settings.autoParryRange = math.max(1, value)
    end)

    local HitAuraFeature: any = createUniversalFeature(
        "Killer Hit Aura",
        "Trigger the native BasicAttack without forcing camera or character rotation",
        5,
        toggleKillerHitAura,
        {parent = state.vdScroll, registry = state.vdFeatures}
    )
    local HitRunButton: TextButton = addToggleOption(
        HitAuraFeature,
        "Run",
        false,
        function(value: boolean): ()
            settings.hitAuraRun = value
        end
    )
    local HitRangeOption: Frame = addNumberOption(
        HitAuraFeature,
        "Legit range",
        12,
        3,
        18,
        function(value: number): ()
            settings.hitAuraRange = math.max(1, value)
        end
    )
    local HitIntervalOption: Frame = addNumberOption(
        HitAuraFeature,
        "Legit cooldown",
        0.72,
        0.2,
        1.5,
        function(value: number): ()
            settings.hitAuraInterval = math.max(0.05, value)
        end
    )
    local BlatantReachOption: Frame = addNumberOption(
        HitAuraFeature,
        "Blatant reach",
        34,
        12,
        60,
        function(value: number): ()
            settings.hitAuraBlatantReach = math.max(1, value)
        end
    )
    addCycleOption(HitAuraFeature, "Mode", {"Legit", "Blatant"}, 1, function(value: string): ()
        settings.hitAuraMode = value
        local legit: boolean = value == "Legit"
        setOptionVisible(HitAuraFeature, HitRunButton.Parent :: GuiObject, legit)
        setOptionVisible(HitAuraFeature, HitRangeOption, legit)
        setOptionVisible(HitAuraFeature, HitIntervalOption, legit)
        setOptionVisible(HitAuraFeature, BlatantReachOption, not legit)
    end)

    local VaultFeature: any = createUniversalFeature(
        "Fast Vault Optimizer",
        "Use VD's verified vault sequence and accelerate local alignment",
        6,
        toggleFastVault,
        {parent = state.vdScroll, registry = state.vdFeatures}
    )
    addNumberOption(VaultFeature, "Activation range", 7, 3, 12, function(value: number): ()
        settings.vaultRange = value
    end)
    addNumberOption(VaultFeature, "Vault speed", 5, 1, 10, function(value: number): ()
        settings.vaultSpeed = math.clamp(value, 1, 10)
    end)

    local ActionFeature: any = createUniversalFeature(
        "Cooldown Modifier",
        "Accelerate vault, pallet, break, rescue and interaction action tracks",
        7,
        toggleCooldownModifier,
        {parent = state.vdScroll, registry = state.vdFeatures}
    )
    addNumberOption(ActionFeature, "Action speed", 4, 1, 10, function(value: number): ()
        settings.actionSpeed = math.clamp(value, 1, 10)
    end)

    local DamageFeature: any = createUniversalFeature(
        "Damage Boost",
        "Apply an immediate configurable WalkSpeed burst after losing health",
        8,
        toggleDamageBoost,
        {parent = state.vdScroll, registry = state.vdFeatures}
    )
    addNumberOption(DamageFeature, "Speed boost", 5, 1, 20, function(value: number): ()
        settings.damageBoost = math.max(0, value)
    end)
    addNumberOption(DamageFeature, "Boost duration", 1, 0.1, 4, function(value: number): ()
        settings.damageBoostDuration = math.max(0.05, value)
    end)

    createUniversalFeature(
        "Noclip (Vaults & Pallets)",
        "Disable collision only on vault/window and pallet descendants, never floors or walls",
        9,
        toggleSelectiveNoclip,
        {parent = state.vdScroll, registry = state.vdFeatures}
    )

    local currentCharacter: Model? = LocalPlayer.Character
    local currentHumanoid: Humanoid? = if currentCharacter
        then currentCharacter:FindFirstChildOfClass("Humanoid")
        else nil
    local defaultWalkSpeed: number = if currentHumanoid then currentHumanoid.WalkSpeed else 16
    settings.walkSpeed = defaultWalkSpeed
    local WalkSpeedFeature: any = createUniversalFeature(
        "WalkSpeed Hack",
        "Maintain a configurable movement speed from the game's current base up to 50",
        10,
        toggleWalkSpeed,
        {parent = state.vdScroll, registry = state.vdFeatures}
    )
    addNumberOption(WalkSpeedFeature, "WalkSpeed", defaultWalkSpeed, 1, 50, function(value: number): ()
        settings.walkSpeed = math.clamp(value, 1, 50)
    end)

    createUniversalFeature(
        "Silent Steps / Anti-Sound",
        "Stop and mute local running, walking, sprint and footstep sounds as they appear",
        11,
        toggleSilentSteps,
        {parent = state.vdScroll, registry = state.vdFeatures}
    )

    local ProximityFeature: any = createUniversalFeature(
        "Killer Proximity Visualizer",
        "Killer-only widget showing the nearest active Survivor distance",
        12,
        toggleProximity,
        {parent = state.vdScroll, registry = state.vdFeatures}
    )
    addNumberOption(ProximityFeature, "Safe range", 150, 50, 400, function(value: number): ()
        settings.proximityRange = value
    end)
    local function updateProximityFeatureVisibility(): ()
        ProximityFeature.row.Visible = isLocalKiller()
    end
    updateProximityFeatureVisibility()
    featureConnections.VDProximityVisibility = LocalPlayer:GetPropertyChangedSignal("Team"):Connect(
        updateProximityFeatureVisibility
    )

    createUniversalFeature(
        "Line of Sight ESP",
        "Draw a lightweight facing vector from every active-round character",
        13,
        toggleFacingESP,
        {parent = state.vdScroll, registry = state.vdFeatures}
    )

    local LockerFeature: any = createUniversalFeature(
        "Locker & Hideout Detector",
        "Show a bright through-wall marker and Toast for nearby hidden Survivors",
        14,
        toggleLockerDetector,
        {parent = state.vdScroll, registry = state.vdFeatures}
    )
    addNumberOption(LockerFeature, "Alert range", 45, 10, 150, function(value: number): ()
        settings.lockerRange = value
    end)

    createUniversalFeature(
        "Killer Power Cooldowns",
        "Show replicated Killer power, charge and cooldown attributes",
        15,
        toggleCooldownTracker,
        {parent = state.vdScroll, registry = state.vdFeatures}
    )

    createUniversalFeature(
        "Optimize Blind / Flash Protection",
        "Disable local flashlight, blind and whiteout overlays as soon as they appear",
        17,
        toggleNoBlind,
        {parent = state.vdScroll, registry = state.vdFeatures}
    )

    state.cleanupVDRuntime = function(): ()
        disconnectFeatureConnection("VDProximityVisibility")
        toggleGeneratorESP(false)
        toggleAutoGeneratorAura(false)
        toggleAutoParry(false)
        toggleKillerHitAura(false)
        toggleFastVault(false)
        toggleCooldownModifier(false)
        toggleDamageBoost(false)
        toggleSelectiveNoclip(false)
        toggleWalkSpeed(false)
        toggleSilentSteps(false)
        toggleProximity(false)
        toggleFacingESP(false)
        toggleLockerDetector(false)
        toggleCooldownTracker(false)
        toggleNoBlind(false)
        clearFacing()
        clearLockerMarkers()
        restoreSelectiveCollisions()
        if runtime.visualFolder then
            runtime.visualFolder:Destroy()
            runtime.visualFolder = nil
        end
    end
end

function Module.init(runtime: any): any
    assert(type(runtime) == "table", "VD requires a Runtime table")
    assert(type(runtime.Menu) == "table", "VD requires Runtime.Menu")
    assert(runtime.TaskManager ~= nil, "VD requires Runtime.TaskManager")
    if Module.Initialized then
        return Module
    end
    Module.Menu = runtime.Menu
    Module.Runtime = runtime
    buildVDFeatures()
    if type(state.cleanupVDRuntime) == "function" then
        moduleCleanup = state.cleanupVDRuntime
    end
    Module.Events = featureConnections
    Module.Initialized = true
    return Module
end

function Module.destroy(): ()
    if not Module.Initialized then
        return
    end
    Module.Initialized = false
    moduleCleanup()
    Module.Events = {}
    Module.Menu = nil
    Module.Runtime = nil
end

return Module

]],
        ["src/games/X2Duels/Other/AutoFarm.lua"] = [[
-- Halloween PumpkinCurrency and round-team PumpCoins farming for X2 Duels.
-- This is intentionally independent from Auto Win and its combat logic.

local Module = {
    Name = "X2Duels Auto Farm",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
    Runtime = nil :: any,
}

local moduleCleanup: () -> () = function(): () end

local function buildAutoFarm(runtime: any): ()
    local host: any = getfenv()
    local state: any = runtime.State or host.state
    local players: Players = game:GetService("Players")
    local localPlayer: Player = players.LocalPlayer
    local currentWorkspace: Workspace = host.workspace or workspace
    local core: any = state.x2duelsCore
    assert(state.mvsdScroll and state.mvsdFeatures,
        "X2Duels Auto Farm requires the MVS menu section")

    local settings: {[string]: any} = {
        enabled = false,
        interval = 0.12,
    }
    local coins: {[Model]: BasePart} = {}
    local farms: {[Model]: {BasePart}} = {}
    local farmTeams: {[Model]: any} = {}
    local podiums: {Model} = {}
    local retryAt: {[Instance]: number} = {}
    local connections: {any} = {}
    local nextRefreshAt: number = 0
    local nextStructureAt: number = 0
    local nextFarmAt: number = 0
    local savedRoot: BasePart? = nil
    local savedCharacter: Model? = nil
    local savedCFrame: CFrame? = nil
    local farmCard: any = nil
    local roundTeam: string? = nil
    local roundStarted: boolean = false
    local podiumEvidence: boolean = false

    local TEAM_NAMES: {[string]: boolean} = {
        team = true,
        teamvalue = true,
        teamname = true,
        teamid = true,
        side = true,
        faction = true,
        matchteam = true,
    }
    local VALUE_CLASSES: {[string]: boolean} = {
        StringValue = true,
        ObjectValue = true,
        IntValue = true,
        NumberValue = true,
        BoolValue = true,
        TeamValue = true,
    }

    local function setStatus(text: string?): ()
        if farmCard and type(farmCard.SetStatus) == "function" then
            farmCard:SetStatus(text)
        end
    end

    local function normalized(value: any): string?
        if value == nil or value == false then
            return nil
        end
        if typeof(value) == "Instance" then
            local ok: boolean, name: any = pcall(function(): any
                return value.Name
            end)
            return ok and normalized(name) or nil
        end
        local text: string = string.lower(
            string.match(tostring(value), "^%s*(.-)%s*$") or ""
        )
        if text == "" or text == "nil" or text == "none" or text == "false" then
            return nil
        end
        return text
    end

    local function readValue(instance: Instance): any
        if not VALUE_CLASSES[instance.ClassName] then
            return nil
        end
        local ok: boolean, value: any = pcall(function(): any
            return (instance :: any).Value
        end)
        return ok and value or nil
    end

    local function teamOf(player: Player): string?
        -- Share the MVS resolver with combat/ESP. In particular, do not use a
        -- common Roblox lobby Team or an FFA sentinel as farm ownership.
        if core and type(core.teamOf) == "function" then
            local ok: boolean, token: any = pcall(core.teamOf, player)
            return ok and token or nil
        end
        for _, name: string in ipairs({
            "Team", "TeamName", "TeamId", "TeamID", "Side", "Faction", "MatchTeam",
        }) do
            local ok: boolean, value: any = pcall(function(): any
                return player:GetAttribute(name)
            end)
            local token: string? = ok and normalized(value) or nil
            if token then return token end
        end
        local ok: boolean, team: any = pcall(function(): any
            return player.Team
        end)
        return ok and normalized(team) or nil
    end

    local function playerFromValue(value: any): Player?
        if typeof(value) == "Instance" then
            if value:IsA("Player") then
                return value :: Player
            end
            if value:IsA("Model") then
                local ok: boolean, player: any = pcall(function(): any
                    return players:GetPlayerFromCharacter(value :: Model)
                end)
                if ok and player then return player end
                for _, candidate: Player in ipairs(players:GetPlayers()) do
                    if candidate.Character == value then return candidate end
                end
            end
            return nil
        end
        if type(value) == "number" then
            local ok: boolean, player: any = pcall(function(): any
                return players:GetPlayerByUserId(value)
            end)
            return ok and player or nil
        end
        if type(value) ~= "string" then
            return nil
        end
        local text: string = string.match(value, "^%s*(.-)%s*$") or ""
        local userId: number? = tonumber(text)
        if userId then
            local ok: boolean, player: any = pcall(function(): any
                return players:GetPlayerByUserId(userId)
            end)
            if ok and player then return player end
        end
        local lowered: string = string.lower(text)
        for _, candidate: Player in ipairs(players:GetPlayers()) do
            if string.lower(candidate.Name) == lowered
                or string.lower(candidate.DisplayName) == lowered then
                return candidate
            end
        end
        return nil
    end

    local function playerEntries(container: Instance): {Player}
        local members: Instance = container
        for _, descendant: Instance in ipairs(container:GetDescendants()) do
            if string.lower(descendant.Name) == "teammembers" then
                members = descendant
                break
            end
        end
        local result: {Player} = {}
        local seen: {[Player]: boolean} = {}
        local function visit(node: Instance): ()
            for _, child: Instance in ipairs(node:GetChildren()) do
                local key: string = string.lower(child.Name)
                if not TEAM_NAMES[key] then
                    local player: Player? = playerFromValue(readValue(child))
                    if player and not seen[player] then
                        seen[player] = true
                        table.insert(result, player)
                    end
                end
                visit(child)
            end
        end
        visit(members)
        return result
    end

    local function findTeamToken(container: Instance): string?
        for _, name: string in ipairs({
            "Team", "TeamName", "TeamId", "TeamID", "Side", "Faction", "MatchTeam",
        }) do
            local ok: boolean, value: any = pcall(function(): any
                return container:GetAttribute(name)
            end)
            local token: string? = ok and normalized(value) or nil
            if token then return token end
        end
        local function fromEntry(entry: Instance): string?
            if not TEAM_NAMES[string.lower(entry.Name)] then
                return nil
            end
            local value: any = readValue(entry)
            local player: Player? = playerFromValue(value)
            if player then return teamOf(player) end
            return normalized(value)
        end
        local direct: string? = fromEntry(container)
        if direct then return direct end
        for _, descendant: Instance in ipairs(container:GetDescendants()) do
            local token: string? = fromEntry(descendant)
            if token then return token end
        end
        return nil
    end

    local function describe(container: Instance): (string?, {Player})
        local token: string? = findTeamToken(container)
        local entries: {Player} = playerEntries(container)
        if not token then
            for _, player: Player in ipairs(entries) do
                token = teamOf(player)
                if token then break end
            end
        end
        return token, entries
    end

    -- Team membership comes from podium values/players, never from whichever
    -- character model happens to be closest to the local root.
    local function claimRoundTeamFromPodiums(): ()
        podiumEvidence = #podiums > 0
        roundStarted = false
        roundTeam = nil
        if not podiumEvidence then
            roundTeam = teamOf(localPlayer)
            return
        end

        local infos: {any} = {}
        local ownToken: string? = nil
        for _, podium: Model in ipairs(podiums) do
            local token: string?, entries: {Player} = describe(podium)
            table.insert(infos, {token = token, entries = entries})
            if not ownToken then
                for _, player: Player in ipairs(entries) do
                    if player == localPlayer then
                        ownToken = token or teamOf(localPlayer)
                        break
                    end
                end
            end
        end
        local localTeam: string? = teamOf(localPlayer)
        if not ownToken and localTeam then
            for _, info: any in ipairs(infos) do
                if info.token == localTeam then
                    ownToken = localTeam
                    break
                end
            end
        end
        -- This is the actual local team, not a claim based on a nearby model.
        ownToken = ownToken or localTeam
        roundTeam = ownToken
        if not ownToken then return end
        for _, info: any in ipairs(infos) do
            if info.token and info.token ~= ownToken then
                roundStarted = true -- at least one opposing podium entry
                return
            end
        end
    end

    local function ownerPlayer(model: Model): Player?
        for _, child: Instance in ipairs(model:GetChildren()) do
            local key: string = string.lower(child.Name)
            if key == "owner" or key == "player" or key == "user"
                or key == "userid" or key == "owneruserid" then
                local player: Player? = playerFromValue(readValue(child))
                if player then return player end
            end
        end
        for _, name: string in ipairs({"OwnerUserId", "UserId", "PlayerUserId"}) do
            local ok: boolean, value: any = pcall(function(): any
                return model:GetAttribute(name)
            end)
            if ok and value ~= nil then
                local player: Player? = playerFromValue(value)
                if player then return player end
            end
        end
        for _, name: string in ipairs({"Owner", "Player"}) do
            local ok: boolean, value: any = pcall(function(): any
                return model:GetAttribute(name)
            end)
            if ok and value ~= nil then
                local player: Player? = playerFromValue(value)
                if player then return player end
            end
        end
        return playerFromValue(model.Name)
    end

    local function friendlyFarm(model: Model): boolean
        if not roundStarted then
            return false
        end
        local owner: Player? = ownerPlayer(model)
        if owner then
            if owner == localPlayer then return true end
            local ownerTeam: string? = teamOf(owner)
            return roundTeam ~= nil and ownerTeam == roundTeam
        end
        local entries: {Player} = playerEntries(model)
        for _, player: Player in ipairs(entries) do
            if player == localPlayer then return true end
        end
        local token: string? = farmTeams[model] or findTeamToken(model)
        local effectiveTeam: string? = roundTeam or teamOf(localPlayer)
        if token and effectiveTeam then
            return token == effectiveTeam
        end
        if effectiveTeam then
            for _, player: Player in ipairs(entries) do
                local playerTeam: string? = teamOf(player)
                if playerTeam and playerTeam == effectiveTeam then
                    return true
                end
            end
        end
        -- No ownership/team evidence means no teleport, even if it is close.
        return false
    end

    local function rootOf(): BasePart?
        local character: Model? = localPlayer.Character
        if not character then return nil end
        local humanoid: Humanoid? = character:FindFirstChildOfClass("Humanoid")
        if not humanoid or humanoid.Health <= 0 then return nil end
        local root: Instance? = character:FindFirstChild("HumanoidRootPart")
        return root and root:IsA("BasePart") and root :: BasePart or nil
    end

    local function rememberPosition(root: BasePart): ()
        if savedRoot == root and savedCFrame ~= nil then return end
        savedRoot = root
        savedCharacter = localPlayer.Character
        savedCFrame = root.CFrame
    end

    local function restoreSavedPosition(): ()
        local root: BasePart? = savedRoot
        local character: Model? = savedCharacter
        local cframe: CFrame? = savedCFrame
        savedRoot = nil
        savedCharacter = nil
        savedCFrame = nil
        if not root or not character or not cframe or not root.Parent
            or localPlayer.Character ~= character then
            return
        end
        pcall(function(): ()
            root.CFrame = cframe
            root.AssemblyLinearVelocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
        end)
    end

    local function addCoin(instance: Instance): ()
        if not instance:IsA("Model")
            or not string.match(instance.Name, "^PumpkinCurrency_%d+$") then
            return
        end
        local pumpkin: Instance? = instance:FindFirstChild("Pumpkin", true)
        if pumpkin and pumpkin:IsA("BasePart") then
            coins[instance :: Model] = pumpkin :: BasePart
        end
    end

    local function addCoinFromDescendant(instance: Instance): ()
        local current: Instance? = instance
        local depth: number = 0
        while current and current ~= currentWorkspace and depth < 6 do
            if current:IsA("Model")
                and string.match(current.Name, "^PumpkinCurrency_%d+$") then
                addCoin(current)
                return
            end
            current = current.Parent
            depth += 1
        end
    end

    local function refreshCoins(): ()
        table.clear(coins)
        for _, descendant: Instance in ipairs(currentWorkspace:GetDescendants()) do
            if descendant:IsA("Model") then addCoin(descendant) end
        end
        for key: Instance, _time: number in pairs(retryAt) do
            if not key.Parent then retryAt[key] = nil end
        end
    end

    local function isAvailable(model: Model, part: BasePart): boolean
        -- The editor stores these spawnables with CanTouch=false. A live
        -- event controller may enable them, so do not discard them permanently.
        if not model.Parent or not part.Parent or part.Transparency >= 0.95 then
            return false
        end
        return model:GetAttribute("Collected") ~= true
            and part:GetAttribute("Collected") ~= true
    end

    local function isFarmAvailable(model: Model, part: BasePart): boolean
        -- PumpCoins are often invisible TouchTransmitter parts: transparency
        -- is not a collected state for this family.
        if not model.Parent or not part.Parent then return false end
        return model:GetAttribute("Collected") ~= true
            and part:GetAttribute("Collected") ~= true
    end

    local function nearestCoin(root: BasePart, now: number): (Model?, BasePart?, number)
        local bestModel: Model? = nil
        local bestPart: BasePart? = nil
        local bestDistance: number = math.huge
        local remaining: number = 0
        for model: Model, part: BasePart in pairs(coins) do
            if isAvailable(model, part) then
                remaining += 1
                if (retryAt[part] or 0) <= now then
                    local distance: number = (part.Position - root.Position).Magnitude
                    if distance < bestDistance then
                        bestDistance = distance
                        bestModel = model
                        bestPart = part
                    end
                end
            end
        end
        return bestModel, bestPart, remaining
    end

    local function nearestOwned(root: BasePart, now: number): (Model?, BasePart?, number)
        if not roundStarted then
            return nil, nil, 0
        end
        local bestModel: Model? = nil
        local bestPart: BasePart? = nil
        local bestDistance: number = math.huge
        local remaining: number = 0
        for model: Model, parts: {BasePart} in pairs(farms) do
            if friendlyFarm(model) then
                for _, part: BasePart in ipairs(parts) do
                    if isFarmAvailable(model, part) then
                        remaining += 1
                        if (retryAt[part] or 0) <= now then
                            local distance: number = (part.Position - root.Position).Magnitude
                            if distance < bestDistance then
                                bestDistance = distance
                                bestModel = model
                                bestPart = part
                            end
                        end
                    end
                end
            end
        end
        return bestModel, bestPart, remaining
    end

    local function touchCoin(model: Model, part: BasePart, root: BasePart): ()
        rememberPosition(root)
        local currentCFrame: CFrame = root.CFrame
        local currencyCFrame: CFrame = part.CFrame
        -- Use the currency's own CFrame, including invisible PumpCoins, never
        -- an owner character's HumanoidRootPart as a proxy for the coin.
        root.CFrame = CFrame.fromMatrix(
            currencyCFrame.Position + Vector3.new(0, 1.25, 0),
            currentCFrame.RightVector,
            currentCFrame.UpVector
        )
        root.AssemblyLinearVelocity = Vector3.zero
        root.AssemblyAngularVelocity = Vector3.zero

        local prompt: Instance? = part:FindFirstChildOfClass("ProximityPrompt")
        local touch: Instance? = part:FindFirstChildOfClass("TouchTransmitter")
        local fireTouch: any = host.firetouchinterest
        local firePrompt: any = host.fireproximityprompt
        if prompt and not touch and type(firePrompt) == "function" then
            pcall(firePrompt, prompt)
        elseif type(fireTouch) == "function" then
            pcall(fireTouch, root, part, 0)
            pcall(fireTouch, root, part, 1)
        end
        retryAt[part] = os.clock() + 4
    end

    local function isPumpContainer(instance: Instance): boolean
        local name: string = string.lower(instance.Name)
        return name == "pumpcoins" or name == "pumpcoin" or name == "pumpkincoins"
    end

    local function ancestorModel(instance: Instance): Model?
        local current: Instance? = instance.Parent
        while current and current ~= currentWorkspace do
            if current:IsA("Model") then return current :: Model end
            current = current.Parent
        end
        return instance:IsA("Model") and instance :: Model or nil
    end

    local function hasInteraction(part: BasePart): boolean
        return part:FindFirstChildOfClass("TouchTransmitter") ~= nil
            or part:FindFirstChildOfClass("ProximityPrompt") ~= nil
    end

    local function currencyParts(model: Model): {BasePart}
        local result: {BasePart} = {}
        local seen: {[BasePart]: boolean} = {}
        local function addContainer(container: Instance): ()
            if container:IsA("BasePart") and hasInteraction(container :: BasePart) then
                seen[container :: BasePart] = true
                table.insert(result, container :: BasePart)
            end
            for _, descendant: Instance in ipairs(container:GetDescendants()) do
                if descendant:IsA("BasePart") then
                    local part: BasePart = descendant :: BasePart
                    if not seen[part] and hasInteraction(part) then
                        seen[part] = true
                        table.insert(result, part)
                    end
                end
            end
        end
        if isPumpContainer(model) then addContainer(model) end
        for _, descendant: Instance in ipairs(model:GetDescendants()) do
            if isPumpContainer(descendant) then addContainer(descendant) end
        end
        return result
    end

    local function refreshStructures(): ()
        table.clear(farms)
        table.clear(farmTeams)
        table.clear(podiums)
        local farmSet: {[Model]: boolean} = {}
        local podiumSet: {[Model]: boolean} = {}
        for _, descendant: Instance in ipairs(currentWorkspace:GetDescendants()) do
            if isPumpContainer(descendant) then
                local model: Model? = ancestorModel(descendant)
                if model then farmSet[model] = true end
            elseif string.lower(descendant.Name) == "teammembers" then
                local model: Model? = ancestorModel(descendant)
                if model then podiumSet[model] = true end
            end
        end
        for model: Model, _present: boolean in pairs(farmSet) do
            local parts: {BasePart} = currencyParts(model)
            if #parts > 0 then
                farms[model] = parts
                farmTeams[model] = findTeamToken(model)
            end
        end
        for model: Model, _present: boolean in pairs(podiumSet) do
            table.insert(podiums, model)
        end
        claimRoundTeamFromPodiums()
    end

    local function update(_deltaTime: number): ()
        if not settings.enabled then return end
        local now: number = os.clock()
        if now >= nextRefreshAt then
            nextRefreshAt = now + 10
            refreshCoins()
        end
        if now >= nextStructureAt then
            nextStructureAt = now + 2
            refreshStructures()
        end
        if now < nextFarmAt then return end
        local root: BasePart? = rootOf()
        if not root then
            setStatus("No character")
            nextFarmAt = now + 0.5
            return
        end

        local farmModel: Model?, farmPart: BasePart?, farmRemaining: number =
            nearestOwned(root, now)
        if farmModel and farmPart then
            touchCoin(farmModel, farmPart, root)
            nextFarmAt = now + settings.interval
            setStatus("Farming team coins · " .. tostring(farmRemaining))
            return
        end

        local model: Model?, part: BasePart?, remaining: number = nearestCoin(root, now)
        if model and part then
            touchCoin(model, part, root)
            nextFarmAt = now + settings.interval
            setStatus("Farming · " .. tostring(remaining) .. " visible")
            return
        end
        if not roundStarted and next(farms) ~= nil then
            setStatus("Waiting for round team")
        elseif farmRemaining > 0 or remaining > 0 then
            setStatus("Retrying currency")
        else
            setStatus("No currency")
        end
        nextFarmAt = now + 0.5
    end

    moduleCleanup = function(): ()
        settings.enabled = false
        restoreSavedPosition()
        setStatus(nil)
        if host.featureConnections.X2DuelsAutoFarm then
            host.disconnectFeatureConnection("X2DuelsAutoFarm")
        end
        for _, connection: any in ipairs(connections) do
            pcall(function(): () connection:Disconnect() end)
        end
        table.clear(connections)
        table.clear(coins)
        table.clear(farms)
        table.clear(farmTeams)
        table.clear(podiums)
        table.clear(retryAt)
    end

    farmCard = host.createUniversalFeature(
        "Auto Farm",
        "Farm friendly PumpCoins and Halloween PumpkinCurrency through native contact",
        1,
        function(enabled: boolean): ()
            settings.enabled = enabled
            nextRefreshAt = 0
            nextStructureAt = 0
            nextFarmAt = 0
            table.clear(retryAt)
            if enabled then
                savedRoot = nil
                savedCharacter = nil
                savedCFrame = nil
                setStatus("Scanning currency")
            else
                restoreSavedPosition()
                setStatus(nil)
            end
        end,
        {
            parent = state.mvsdScroll,
            registry = state.mvsdFeatures,
            categoryName = "Utilities",
        }
    )
    host.addNumberOption(farmCard, "Step interval", 0.12, 0.06, 0.5, function(value: number): ()
        settings.interval = value
    end)
    host.addInformationOption(
        farmCard,
        "PumpCoins use podium player/team evidence; nearby enemy models are rejected. Attempts are not confirmed currency."
    )

    table.insert(connections, currentWorkspace.DescendantAdded:Connect(function(instance: Instance): ()
        nextStructureAt = 0
        if settings.enabled then addCoinFromDescendant(instance) end
    end))
    table.insert(connections, currentWorkspace.DescendantRemoving:Connect(function(instance: Instance): ()
        nextStructureAt = 0
        if instance:IsA("Model") then coins[instance :: Model] = nil end
        retryAt[instance] = nil
    end))
    table.insert(connections, localPlayer.CharacterAdded:Connect(function(): ()
        savedRoot = nil
        savedCharacter = nil
        savedCFrame = nil
        nextRefreshAt = 0
        nextStructureAt = 0
        nextFarmAt = 0
        table.clear(retryAt)
    end))
    host.featureConnections.X2DuelsAutoFarm = runtime.TaskManager:Connect(update)
end

function Module.init(runtime: any): any
    if Module.Initialized then return Module end
    assert(type(runtime) == "table" and runtime.TaskManager,
        "X2Duels Auto Farm requires Runtime.TaskManager")
    Module.Runtime = runtime
    local ok: boolean, failure: any = pcall(buildAutoFarm, runtime)
    if not ok then
        moduleCleanup()
        Module.Runtime = nil
        error(failure)
    end
    Module.Initialized = true
    return Module
end

function Module.destroy(): ()
    moduleCleanup()
    moduleCleanup = function(): () end
    Module.Runtime = nil
    Module.Initialized = false
end

return Module

]],
        ["src/games/X2Duels/Rules.lua"] = [[
-- Pure rules shared by X2 Duels combat, ESP and match automation.
-- No remote argument schemas live here: combat uses the game's native Tools.

local Module = {
    Name = "X2Duels Rules",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local function compact(value: any): string
    return string.lower(tostring(value or "")):gsub("[%W_]", "")
end

local function normalizeToken(value: any): string?
    if value == nil or value == false then
        return nil
    end
    local valueType: string = type(value)
    if valueType == "string" then
        local trimmed: string = string.match(value, "^%s*(.-)%s*$") or ""
        local lowered: string = string.lower(trimmed)
        if lowered == "" or lowered == "false" or lowered == "none"
            or lowered == "nil" then
            return nil
        end
        return lowered
    end
    if valueType == "number" or valueType == "boolean" then
        return string.lower(tostring(value))
    end

    -- Team objects are accepted without making the pure rules depend on
    -- Roblox's typeof(). Unsupported userdata simply has no readable Name.
    local ok: boolean, name: any = pcall(function(): any
        return value.Name
    end)
    if ok and name ~= nil and name ~= value then
        return normalizeToken(name)
    end
    return nil
end

-- MVS also uses Team for FFA/lobby state. A shared sentinel is not a
-- team: treating it as one paints every player green and protects everyone.
local NON_TEAM_TOKENS: {[string]: boolean} = {
    ffa = true,
    freeforall = true,
    lobby = true,
    neutral = true,
    none = true,
    spectator = true,
    spectating = true,
    unknown = true,
    unassigned = true,
    solo = true,
    all = true,
    everyone = true,
    default = true,
    team = true,
    ["true"] = true,
}

local function normalizeTeamToken(value: any): string?
    local token: string? = normalizeToken(value)
    if token == nil or NON_TEAM_TOKENS[token] then
        return nil
    end
    return token
end

local function sameMatch(localMatch: any, otherMatch: any): boolean
    local mine: string? = normalizeToken(localMatch)
    if mine == nil then
        -- Manual features can still work in places without match attributes.
        -- Auto Win additionally requires its own active-match signal.
        return true
    end
    local theirs: string? = normalizeToken(otherMatch)
    return theirs ~= nil and mine == theirs
end

local function relation(
    localTeam: any,
    otherTeam: any,
    sharesMatch: boolean
): string
    if not sharesMatch then
        return "Outside"
    end
    local mine: string? = normalizeTeamToken(localTeam)
    local theirs: string? = normalizeTeamToken(otherTeam)
    if mine == nil or theirs == nil then
        return "Unknown"
    end
    return mine == theirs and "Teammate" or "Enemy"
end

local function isOpponent(
    localTeam: any,
    otherTeam: any,
    sharesMatch: boolean,
    teamCheck: boolean
): boolean
    if not sharesMatch then
        return false
    end
    if not teamCheck then
        return true
    end
    -- Fail closed in team modes. Painting an unknown player amber is safer
    -- than killing a teammate because an attribute was late to replicate.
    return relation(localTeam, otherTeam, sharesMatch) == "Enemy"
end

local GUN_WORDS: {string} = {
    "gun", "revolver", "pistol", "rifle", "shotgun", "sniper", "uzi",
    "crossfire", "lightburst", "shooter", "shot",
}
local KNIFE_WORDS: {string} = {
    "knife", "blade", "dagger", "sword", "katana", "machete", "fang",
    "starcarver", "cometfall",
}

local function containsAny(text: string, words: {string}): boolean
    for _, word: string in ipairs(words) do
        if string.find(text, word, 1, true) then
            return true
        end
    end
    return false
end

local function classifyTool(
    name: any,
    hasGunStructure: boolean?,
    hasKnifeStructure: boolean?
): string?
    local lowered: string = string.lower(tostring(name or ""))
    if hasGunStructure == true or containsAny(lowered, GUN_WORDS) then
        return "Gun"
    end
    if hasKnifeStructure == true or containsAny(lowered, KNIFE_WORDS) then
        return "Knife"
    end
    return nil
end

local function isPlayAgainText(value: any): boolean
    local key: string = compact(value)
    if key == "" then
        return false
    end
    if string.find(key, "playagain", 1, true)
        or string.find(key, "queueagain", 1, true) then
        return true
    end
    return key == "rematch"
        or key == "rematchbutton"
        or string.find(key, "rematchbutton", 1, true) ~= nil
end

local function isVictoryText(value: any): boolean
    if type(value) ~= "string" then
        return false
    end
    local key: string = compact(value)
    return key == "victory" or key == "winner" or key == "winners"
        or key == "win" or key == "won" or key == "youwin"
        or key == "youwon" or key == "roundwin" or key == "roundwon"
end

local function isLocalVictoryLabel(value: any): boolean
    if type(value) ~= "string" then
        return false
    end
    local key: string = compact(value)
    return key == "victory" or key == "youwin" or key == "youwon"
        or key == "roundwin" or key == "roundwon"
end

local function safeField(value: any, key: string): any
    if type(value) ~= "table" and type(value) ~= "userdata" then
        return nil
    end
    local ok: boolean, field: any = pcall(function(): any
        return value[key]
    end)
    return ok and field or nil
end

local function matchesIdentity(
    value: any,
    identity: {[string]: any},
    allowTeam: boolean,
    seen: {[any]: boolean}?,
    depth: number?
): boolean
    if value == nil then
        return false
    end
    if identity.player ~= nil and value == identity.player then
        return true
    end

    local valueType: string = type(value)
    if valueType == "string" or valueType == "number" then
        local token: string? = normalizeToken(value)
        if token == nil then
            return false
        end
        if token == "you" or token == "local" or token == "localplayer"
            or (allowTeam and token == "yourteam") then
            return true
        end
        for _, key: string in ipairs({"userId", "name", "displayName"}) do
            local expected: string? = normalizeToken(identity[key])
            if expected ~= nil and token == expected then
                return true
            end
        end
        if allowTeam then
            local team: string? = normalizeToken(identity.team)
            return team ~= nil and token == team
        end
        return false
    end
    if valueType ~= "table" and valueType ~= "userdata" then
        return false
    end
    if allowTeam then
        local expectedTeam: string? = normalizeToken(identity.team)
        local valueTeam: string? = normalizeToken(value)
        if expectedTeam ~= nil and valueTeam == expectedTeam then
            return true
        end
    end

    local level: number = depth or 0
    if level > 4 then
        return false
    end
    local visited: {[any]: boolean} = seen or {}
    if visited[value] then
        return false
    end
    visited[value] = true

    local userId: any = safeField(value, "UserId")
        or safeField(value, "PlayerId")
    if userId ~= nil then
        local expected: string? = normalizeToken(identity.userId)
        if expected ~= nil and normalizeToken(userId) == expected then
            return true
        end
    end
    for _, key: string in ipairs({"Player", "Name", "DisplayName"}) do
        local field: any = safeField(value, key)
        if field ~= nil and matchesIdentity(
            field, identity, false, visited, level + 1
        ) then
            return true
        end
    end
    if allowTeam then
        for _, key: string in ipairs({"Team", "TeamName", "TeamId", "Side"}) do
            local field: any = safeField(value, key)
            if field ~= nil then
                local expected: string? = normalizeToken(identity.team)
                local token: string? = normalizeToken(field)
                if expected ~= nil and token == expected then
                    return true
                end
            end
        end
    end
    if valueType == "table" then
        for key: any, field: any in pairs(value) do
            if type(key) == "number" and matchesIdentity(
                field, identity, allowTeam, visited, level + 1
            ) then
                return true
            end
        end
    end
    return false
end

local WINNER_KEYS: {[string]: boolean} = {
    winner = true,
    winners = true,
    winningplayer = true,
    winningplayers = true,
    winningteam = true,
    winningteams = true,
    winnerteam = true,
    teamwinner = true,
    victor = true,
    victors = true,
}
local OUTCOME_KEYS: {[string]: boolean} = {
    result = true,
    outcome = true,
    localresult = true,
    matchresult = true,
    roundresult = true,
}
local LOCAL_WIN_FLAGS: {[string]: boolean} = {
    won = true,
    iswinner = true,
    victory = true,
    localwon = true,
}

local function recordBelongsToOther(
    record: {[any]: any},
    identity: {[string]: any}
): boolean
    local userId: any = safeField(record, "UserId")
        or safeField(record, "PlayerId")
    local expectedUserId: string? = normalizeToken(identity.userId)
    if userId ~= nil and expectedUserId ~= nil then
        return normalizeToken(userId) ~= expectedUserId
    end
    local player: any = safeField(record, "Player")
    if player ~= nil and identity.player ~= nil then
        return player ~= identity.player
    end
    return false
end

local function scanResult(
    record: {[any]: any},
    identity: {[string]: any},
    seen: {[any]: boolean},
    depth: number
): boolean
    if depth > 5 or seen[record] then
        return false
    end
    seen[record] = true
    local belongsToOther: boolean = recordBelongsToOther(record, identity)

    for key: any, value: any in pairs(record) do
        if type(key) == "string" then
            local normalized: string = compact(key)
            if WINNER_KEYS[normalized] and matchesIdentity(
                value, identity, true, seen, depth + 1
            ) then
                return true
            end
            if not belongsToOther and OUTCOME_KEYS[normalized]
                and isVictoryText(value) then
                return true
            end
            if not belongsToOther and LOCAL_WIN_FLAGS[normalized]
                and value == true then
                return true
            end
        end
        if type(value) == "table" and scanResult(
            value, identity, seen, depth + 1
        ) then
            return true
        end
    end
    return false
end

local function didLocalWin(
    arguments: {[any]: any},
    identity: {[string]: any},
    directWinnerArguments: boolean?
): boolean
    if directWinnerArguments == true then
        for _, value: any in ipairs(arguments) do
            if type(value) == "string" then
                local outcome: string = compact(value)
                if string.find(outcome, "defeat", 1, true)
                    or string.find(outcome, "loss", 1, true)
                    or outcome == "lost" then
                    return false
                end
            end
        end
        for _, value: any in ipairs(arguments) do
            if type(value) ~= "table" and matchesIdentity(
                value, identity, true, nil, 0
            ) then
                return true
            end
        end
    end
    for _, value: any in ipairs(arguments) do
        if type(value) == "table" and scanResult(value, identity, {}, 0) then
            return true
        end
    end
    return false
end

Module.compact = compact
Module.normalizeToken = normalizeToken
Module.normalizeTeamToken = normalizeTeamToken
Module.sameMatch = sameMatch
Module.relation = relation
Module.isOpponent = isOpponent
Module.classifyTool = classifyTool
Module.isPlayAgainText = isPlayAgainText
Module.isVictoryText = isVictoryText
Module.isLocalVictoryLabel = isLocalVictoryLabel
Module.matchesIdentity = matchesIdentity
Module.didLocalWin = didLocalWin

function Module.init(runtime: any): any
    if Module.Initialized then
        return Module
    end
    assert(type(runtime) == "table" and type(runtime.State) == "table",
        "X2Duels Rules requires Runtime.State")
    Module.Runtime = runtime
    runtime.State.x2duelsRules = Module
    Module.Initialized = true
    return Module
end

function Module.destroy(): ()
    local runtime: any = Module.Runtime
    if runtime and runtime.State and runtime.State.x2duelsRules == Module then
        runtime.State.x2duelsRules = nil
    end
    Module.Runtime = nil
    Module.Initialized = false
end

return Module

]],
        ["src/games/X2Duels/base.lua"] = [[
-- X2 Duels (MVS) native combat and observed session statistics.
--
-- The supplied Cobalt log captures DefaultGun/DefaultKnife native calls,
-- including fire/showBeam and the respawn/death events. Combat still goes
-- through the game's own Tool:Activate() path; no remote arguments are guessed.

local Module = {
    Name = "X2Duels",
    PlaceId = 92876937625630,
    Events = {} :: {[string]: any},
    Initialized = false,
    Runtime = nil :: any,
}

local moduleCleanup: () -> () = function(): () end

local function buildX2Duels(runtime: any): ()
    local host: any = getfenv()
    local state: any = runtime.State or host.state
    local rules: any = state and state.x2duelsRules
    assert(type(rules) == "table", "X2Duels Rules must initialize before base")
    assert(type(host.createUniversalFeature) == "function",
        "X2Duels requires the Wurst card API")
    assert(state.mvsdScroll and state.mvsdFeatures,
        "X2Duels requires the existing MVS menu section")

    local players: Players = game:GetService("Players")
    local replicated: ReplicatedStorage = game:GetService("ReplicatedStorage")
    local localPlayer: Player = players.LocalPlayer
    local currentWorkspace: Workspace = host.workspace or workspace
    local services: any = runtime.Services or {}
    local protectedTargets: any = services.protectedTargets
    local activity: any = services.activity
    local notify: any = host.notify or (runtime.Menu and runtime.Menu.Notify)
        or function(): () end

    local settings: {[string]: any} = {
        -- Auto Win is now a session-statistics card, not a combat driver.
        stats = false,
        silentAim = false,
        silentMode = "Legit",
        autoShoot = false,
        knifeThrow = false,
        killAura = false,
        hitboxes = false,
        teamCheck = true,
        wallCheck = true,
        senderMode = "CFrame",
        maxDistance = 1000,
        shotInterval = 0.035,
        killAuraInterval = 0.12,
        killAuraRange = 12,
        hitboxSize = 10,
    }

    local runtimeState: {[string]: any} = {
        connections = {},
        selected = nil,
        observedRound = false,
        resultsPending = false,
        resultWinCounted = false,
        lastMatchToken = nil,
        roundSerial = 0,
        lastWinRound = -1,
        lastWinAt = -math.huge,
        wins = 0,
        kills = 0,
        loses = 0,
        lastLossRound = -1,
        killVictims = setmetatable({}, {__mode = "k"}),
        sessionStartedAt = os.clock(),
        nextStatsAt = 0,
        nextSelectionAt = 0,
        nextGunAt = 0,
        knifeBusy = false,
        knifeToken = 0,
        knifePending = nil,
        nextAuraAt = 0,
        nextHitboxAt = 0,
        nextRemoteAt = 0,
        remoteBound = {},
        deadPlayers = setmetatable({}, {__mode = "k"}),
        hitboxes = {},
        suppressRaycast = false,
        cameraOverride = nil,
        rayHookInstalled = false,
        oldRay = nil,
        rayWrapper = nil,
        raycastHookInstalled = false,
        oldRaycast = nil,
        raycastWrapper = nil,
    }

    local autoWinCard: any = nil
    local silentAimCard: any = nil

    -- MVS stores the real side in Team/TeamName/etc. Role is deliberately
    -- excluded: a role is not proof that two players share a team.
    local TEAM_ATTRIBUTES: {string} = {
        "Team", "TeamName", "TeamId", "TeamID", "Side", "Faction", "MatchTeam",
    }
    local ROLE_COLORS: {[string]: Color3} = {
        Enemy = Color3.fromRGB(255, 82, 82),
        Teammate = Color3.fromRGB(75, 220, 135),
        Unknown = Color3.fromRGB(255, 190, 75),
        Outside = Color3.fromRGB(255, 190, 75),
    }
    local MATCH_ATTRIBUTES: {string} = {
        "Game", "Match", "MatchId", "MatchID",
    }

    local function track(connection: any): ()
        if connection then
            table.insert(runtimeState.connections, connection)
        end
    end

    local function forceCardOff(card: any): ()
        if not card then
            return
        end
        task.defer(function(): ()
            card.enabled = false
            if host.configData and card.configKey then
                host.configData.states[card.configKey] = false
            end
            if type(host.refreshFeatureToggle) == "function" then
                pcall(host.refreshFeatureToggle, card)
            end
            if type(host.flushConfigSave) == "function" then
                pcall(host.flushConfigSave)
            end
        end)
    end

    local function setAimActivity(active: boolean): ()
        if activity and type(activity.set) == "function" then
            pcall(activity.set, "mvsdSilentAim", active)
        end
    end

    local function firstAttribute(player: Player, names: {string}): any
        local containers: {Instance?} = {player, player.Character}
        for _, container: Instance? in ipairs(containers) do
            if container then
                for _, name: string in ipairs(names) do
                    local ok: boolean, value: any = pcall(
                        container.GetAttribute, container, name
                    )
                    if ok and value ~= nil and value ~= "" then
                        return value
                    end
                end
            end
        end
        return nil
    end

    local function matchToken(player: Player): string?
        return rules.normalizeToken(firstAttribute(player, MATCH_ATTRIBUTES))
    end

    local function teamToken(player: Player): string?
        -- Do not fall back to player.Team here. MVS keeps players on a common
        -- Roblox lobby team in some states; that fallback made everyone green.
        -- Read every supported attribute so an FFA sentinel can be followed by
        -- a real replicated side instead of hiding it.
        local containers: {Instance?} = {player, player.Character}
        for _, container: Instance? in ipairs(containers) do
            if container then
                for _, name: string in ipairs(TEAM_ATTRIBUTES) do
                    local ok: boolean, value: any = pcall(
                        container.GetAttribute, container, name
                    )
                    local token: string? = ok and rules.normalizeTeamToken(value) or nil
                    if token ~= nil then
                        return token
                    end
                end
            end
        end
        return nil
    end

    local function sharesMatch(other: Player): boolean
        local mine: string? = matchToken(localPlayer)
        local theirs: string? = matchToken(other)
        -- Once either side has a match id, a missing/different id is not the
        -- same round. With no match API at all, retain manual-team compatibility.
        if mine ~= nil or theirs ~= nil then
            return mine ~= nil and mine == theirs
        end
        return true
    end

    local function relation(other: Player): string
        if other == localPlayer then
            return "Local"
        end
        return rules.relation(
            teamToken(localPlayer), teamToken(other), sharesMatch(other)
        )
    end

    local function isAlive(player: Player): boolean
        if runtimeState.deadPlayers[player] == true
            or firstAttribute(player, {"Died", "Dead"}) == true then
            return false
        end
        local character: Model? = player.Character
        local humanoid: Humanoid? = character
            and character:FindFirstChildOfClass("Humanoid")
        return humanoid ~= nil and humanoid.Health > 0
    end

    local function isProtected(player: Player): boolean
        if not protectedTargets or type(protectedTargets.isProtected) ~= "function" then
            return false
        end
        local ok: boolean, protected: any = pcall(
            protectedTargets.isProtected, player
        )
        return ok and protected == true
    end

    local function isTeammate(other: Player?): boolean
        return other ~= nil and other ~= localPlayer and relation(other) == "Teammate"
    end

    local function isEnemy(other: Player?, allowTeammates: boolean?): boolean
        if not other or other == localPlayer or not isAlive(other)
            or isProtected(other) then
            return false
        end
        return rules.isOpponent(
            teamToken(localPlayer), teamToken(other), sharesMatch(other),
            settings.teamCheck and allowTeammates ~= true
        )
    end

    local function rootOf(character: Model?): BasePart?
        if not character then
            return nil
        end
        local root: Instance? = character:FindFirstChild("HumanoidRootPart")
        if root and root:IsA("BasePart") then
            return root :: BasePart
        end
        return character.PrimaryPart
    end

    local function targetPartOf(character: Model?): BasePart?
        if not character then
            return nil
        end
        local head: Instance? = character:FindFirstChild("Head")
        if head and head:IsA("BasePart") then
            return head :: BasePart
        end
        return rootOf(character)
    end

    local function targetRecord(player: Player): {[string]: any}?
        local character: Model? = player.Character
        local part: BasePart? = targetPartOf(character)
        if not character or not part then
            return nil
        end
        return {player = player, character = character, part = part}
    end

    local function hasLineOfSight(target: {[string]: any}): boolean
        local camera: Camera? = currentWorkspace.CurrentCamera
        local localRoot: BasePart? = rootOf(localPlayer.Character)
        local origin: Vector3? = if camera then camera.CFrame.Position
            elseif localRoot then localRoot.Position else nil
        if not origin then
            return false
        end
        local direction: Vector3 = target.part.Position - origin
        if direction.Magnitude < 0.05 then
            return true
        end
        local parameters: RaycastParams = RaycastParams.new()
        parameters.FilterType = Enum.RaycastFilterType.Exclude
        parameters.IgnoreWater = true
        parameters.FilterDescendantsInstances = localPlayer.Character
            and {localPlayer.Character} or {}
        runtimeState.suppressRaycast = true
        local ok: boolean, hit: any = pcall(function(): any
            return currentWorkspace:Raycast(origin, direction, parameters)
        end)
        runtimeState.suppressRaycast = false
        if not ok then
            return false
        end
        return hit == nil or hit.Instance:IsDescendantOf(target.character)
    end

    local function nearestEnemy(maxDistance: number): {[string]: any}?
        local localRoot: BasePart? = rootOf(localPlayer.Character)
        if not localRoot then
            return nil
        end
        local best: {[string]: any}? = nil
        local bestDistance: number = maxDistance
        for _, player: Player in ipairs(players:GetPlayers()) do
            if isEnemy(player) then
                local target: {[string]: any}? = targetRecord(player)
                if target then
                    local distance: number =
                        (target.part.Position - localRoot.Position).Magnitude
                    if distance <= bestDistance
                        and (not settings.wallCheck or hasLineOfSight(target)) then
                        best = target
                        bestDistance = distance
                    end
                end
            end
        end
        runtimeState.selected = best
        return best
    end

    local function candidateTools(): {Tool}
        local result: {Tool} = {}
        local backpack: Instance? = localPlayer:FindFirstChildOfClass("Backpack")
        for _, container: Instance? in ipairs({localPlayer.Character, backpack}) do
            if container then
                for _, child: Instance in ipairs(container:GetChildren()) do
                    if child:IsA("Tool") then
                        table.insert(result, child :: Tool)
                    end
                end
            end
        end
        return result
    end

    local function hasChild(tool: Tool, names: {string}): boolean
        for _, name: string in ipairs(names) do
            if tool:FindFirstChild(name, true) then
                return true
            end
        end
        return false
    end

    local function toolKind(tool: Tool?): string?
        if not tool then
            return nil
        end
        local gunStructure: boolean = hasChild(tool, {"fire", "showBeam", "GunKill"})
        local knifeStructure: boolean = hasChild(tool, {
            "ThrowEvent", "SlashEvent", "MobileKnifeLocalScript", "KnifeKill",
        })
        return rules.classifyTool(tool.Name, gunStructure, knifeStructure)
    end

    local function findWeapon(kind: string): Tool?
        for _, tool: Tool in ipairs(candidateTools()) do
            if toolKind(tool) == kind then
                return tool
            end
        end
        return nil
    end

    local function equippedTool(): Tool?
        local character: Model? = localPlayer.Character
        if not character then
            return nil
        end
        for _, child: Instance in ipairs(character:GetChildren()) do
            if child:IsA("Tool") then
                return child :: Tool
            end
        end
        return nil
    end

    local function equip(tool: Tool?): boolean
        if not tool then
            return false
        end
        local character: Model? = localPlayer.Character
        if not character then
            return false
        end
        if tool.Parent == character then
            return true
        end
        local humanoid: Humanoid? = character:FindFirstChildOfClass("Humanoid")
        if not humanoid or humanoid.Health <= 0 then
            return false
        end
        pcall(function(): ()
            humanoid:EquipTool(tool)
        end)
        return tool.Parent == character
    end

    local function restoreCamera(): ()
        local override: any = runtimeState.cameraOverride
        runtimeState.cameraOverride = nil
        if override and override.camera and override.camera.Parent then
            pcall(function(): ()
                override.camera.CFrame = override.cframe
            end)
        end
    end

    local function aimWithCFrame(position: Vector3): ()
        local camera: Camera? = currentWorkspace.CurrentCamera
        if camera then
            local override: any = runtimeState.cameraOverride
            if not override or override.camera ~= camera then
                override = {
                    camera = camera,
                    cframe = camera.CFrame,
                    token = 0,
                }
                runtimeState.cameraOverride = override
            end
            override.token += 1
            local token: number = override.token
            camera.CFrame = CFrame.lookAt(camera.CFrame.Position, position)
            task.defer(function(): ()
                local current: any = runtimeState.cameraOverride
                if current == override and current.token == token then
                    restoreCamera()
                end
            end)
        end

        local root: BasePart? = rootOf(localPlayer.Character)
        if root then
            local flat: Vector3 = Vector3.new(position.X, root.Position.Y, position.Z)
            if (flat - root.Position).Magnitude > 0.05 then
                root.CFrame = CFrame.lookAt(root.Position, flat)
            end
        end
    end

    local function activateNative(
        tool: Tool?,
        target: {[string]: any}?
    ): boolean
        if not tool or not equip(tool) then
            return false
        end
        local enabledOk: boolean, enabled: any = pcall(function(): any
            return tool.Enabled
        end)
        if enabledOk and enabled == false then
            return false
        end
        if settings.senderMode == "CFrame" and target then
            aimWithCFrame(target.part.Position)
        end
        local ok: boolean = pcall(function(): ()
            tool:Activate()
        end)
        return ok
    end

    local function selectedTarget(): {[string]: any}?
        local target: any = runtimeState.selected
        if not target or not isEnemy(target.player) then
            return nil
        end
        if not target.part.Parent or not target.character.Parent then
            return nil
        end
        return target
    end

    local function fireGun(target: {[string]: any}?): (boolean, boolean)
        local gun: Tool? = findWeapon("Gun")
        if not gun then
            return false, false
        end
        if not target then
            return false, true
        end
        -- The exact same target drives Legit rendering, Silent ray rewriting
        -- and native activation; no hidden crosshair/mouse packet is involved.
        runtimeState.selected = target
        return activateNative(gun, target), true
    end

    local function cancelKnifeThrow(): ()
        runtimeState.knifeToken = (runtimeState.knifeToken or 0) + 1
        local pending: any = runtimeState.knifePending
        runtimeState.knifePending = nil
        runtimeState.knifeBusy = false
        if pending then
            if pending.rightDown and type(host.mouse2release) == "function" then
                pcall(host.mouse2release)
            end
            if pending.forceThrow and pending.tool then
                pcall(function(): ()
                    pending.tool:SetAttribute("ForceThrow", pending.previousForceThrow)
                end)
            end
        end
        restoreCamera()
    end

    local function fireKnife(target: {[string]: any}?): boolean
        if not target or runtimeState.knifeBusy then
            return false
        end
        local knife: Tool? = findWeapon("Knife")
        if not knife or not equip(knife) then
            return false
        end
        local enabledOk: boolean, enabled: any = pcall(function(): any
            return knife.Enabled
        end)
        if enabledOk and enabled == false then
            return false
        end

        local token: number = (runtimeState.knifeToken or 0) + 1
        runtimeState.knifeToken = token
        runtimeState.knifeBusy = true
        local pending: {[string]: any} = {
            tool = knife,
            rightDown = false,
            forceThrow = false,
            previousForceThrow = nil,
        }
        runtimeState.knifePending = pending

        task.spawn(function(): ()
            local ok: boolean, failure: any = pcall(function(): ()
                if token ~= runtimeState.knifeToken then return end
                if settings.senderMode == "CFrame" then
                    aimWithCFrame(target.part.Position)
                end

                local usedMouse: boolean = false
                if type(host.mouse2press) == "function"
                    and type(host.mouse2release) == "function" then
                    local pressed: boolean = pcall(host.mouse2press)
                    if pressed then
                        usedMouse = true
                        pending.rightDown = true
                        -- X2's desktop LocalScript enters its throwing state
                        -- from MouseButton2 before Tool:Activate().
                        task.wait(0.2)
                        if token ~= runtimeState.knifeToken then return end
                        if target.part.Parent then
                            activateNative(knife, target)
                        end
                        pending.rightDown = false
                        pcall(host.mouse2release)
                    end
                end

                if not usedMouse then
                    -- The touch/ForceThrow path is read by the same native
                    -- controller. It does not manufacture remote arguments.
                    pending.previousForceThrow = knife:GetAttribute("ForceThrow")
                    knife:SetAttribute("ForceThrow", true)
                    pending.forceThrow = true
                    if token ~= runtimeState.knifeToken then return end
                    if target.part.Parent then
                        activateNative(knife, target)
                    end
                    task.wait()
                end
            end)

            if token == runtimeState.knifeToken then
                if pending.rightDown and type(host.mouse2release) == "function" then
                    pcall(host.mouse2release)
                end
                if pending.forceThrow then
                    pcall(function(): ()
                        knife:SetAttribute("ForceThrow", pending.previousForceThrow)
                    end)
                end
                runtimeState.knifePending = nil
                runtimeState.knifeBusy = false
                restoreCamera()
            end
            if not ok then
                runtimeState.lastKnifeError = tostring(failure)
            end
        end)
        return true
    end

    local function redirectRay(origin: Vector3, direction: Vector3): Vector3?
        if runtimeState.suppressRaycast or not settings.silentAim
            or settings.silentMode ~= "Silent" then
            return nil
        end
        local equipped: Tool? = equippedTool()
        if not equipped or toolKind(equipped) == nil then
            return nil
        end
        local target: {[string]: any}? = selectedTarget()
        if not target or direction.Magnitude < 0.05 then
            return nil
        end
        local camera: Camera? = currentWorkspace.CurrentCamera
        local root: BasePart? = rootOf(localPlayer.Character)
        local nearCamera: boolean = camera ~= nil
            and (origin - camera.CFrame.Position).Magnitude <= 35
        local nearCharacter: boolean = root ~= nil
            and (origin - root.Position).Magnitude <= 35
        if not nearCamera and not nearCharacter then
            return nil
        end
        local offset: Vector3 = target.part.Position - origin
        if offset.Magnitude < 0.05 then
            return nil
        end
        local reach: number = math.max(direction.Magnitude, offset.Magnitude + 5)
        return offset.Unit * reach
    end

    local function installHooks(): boolean
        local hookFunction: any = host.hookfunction
        if type(hookFunction) ~= "function" then
            return false
        end
        local newClosure: any = host.newcclosure
        local function wrap(callback: any): any
            return type(newClosure) == "function" and newClosure(callback) or callback
        end

        if not runtimeState.rayHookInstalled and host.Ray ~= nil then
            local predecessor: any = nil
            local callback: any = function(origin: any, direction: any): any
                if predecessor == nil then
                    return nil
                end
                if typeof(origin) == "Vector3" and typeof(direction) == "Vector3" then
                    local redirected: Vector3? = redirectRay(origin, direction)
                    if redirected then
                        return predecessor(origin, redirected)
                    end
                end
                return predecessor(origin, direction)
            end
            local wrapper: any = wrap(callback)
            local ok: boolean, old: any = pcall(hookFunction, host.Ray.new, wrapper)
            if ok and old ~= nil then
                runtimeState.oldRay = old
                runtimeState.rayWrapper = wrapper
                runtimeState.rayHookInstalled = true
                predecessor = old
            end
        end

        if not runtimeState.raycastHookInstalled then
            local method: any = currentWorkspace.Raycast
            if type(method) == "function" then
                local predecessor: any = nil
                local callback: any = function(self: any, ...: any): any
                    if predecessor == nil then
                        return nil
                    end
                    if runtimeState.suppressRaycast then
                        return predecessor(self, ...)
                    end
                    local arguments: {any} = {...}
                    local origin: any = arguments[1]
                    local direction: any = arguments[2]
                    if typeof(origin) == "Vector3" and typeof(direction) == "Vector3" then
                        local redirected: Vector3? = redirectRay(origin, direction)
                        if redirected then
                            arguments[2] = redirected
                            return predecessor(self, unpack(arguments))
                        end
                    end
                    return predecessor(self, ...)
                end
                local wrapper: any = wrap(callback)
                local ok: boolean, old: any = pcall(hookFunction, method, wrapper)
                if ok and old ~= nil then
                    runtimeState.oldRaycast = old
                    runtimeState.raycastWrapper = wrapper
                    runtimeState.raycastHookInstalled = true
                    predecessor = old
                end
            end
        end
        return runtimeState.rayHookInstalled or runtimeState.raycastHookInstalled
    end

    local function uninstallHooks(): ()
        local hookFunction: any = host.hookfunction
        if type(hookFunction) ~= "function" then
            return
        end
        if runtimeState.rayHookInstalled and host.Ray ~= nil then
            local ok: boolean, displaced: any = pcall(
                hookFunction, host.Ray.new, runtimeState.oldRay
            )
            -- If another script hooked after us, put its hook back instead of
            -- deleting it while removing ours from the chain.
            if ok and displaced ~= runtimeState.rayWrapper
                and type(displaced) == "function" then
                pcall(hookFunction, host.Ray.new, displaced)
            end
            if ok then
                runtimeState.rayHookInstalled = false
                runtimeState.oldRay = nil
                runtimeState.rayWrapper = nil
            end
        end
        if runtimeState.raycastHookInstalled then
            local ok: boolean, displaced: any = pcall(
                hookFunction, currentWorkspace.Raycast, runtimeState.oldRaycast
            )
            if ok and displaced ~= runtimeState.raycastWrapper
                and type(displaced) == "function" then
                pcall(hookFunction, currentWorkspace.Raycast, displaced)
            end
            if ok then
                runtimeState.raycastHookInstalled = false
                runtimeState.oldRaycast = nil
                runtimeState.raycastWrapper = nil
            end
        end
    end

    local function registerWin(): boolean
        local now: number = os.clock()
        if runtimeState.lastWinRound == runtimeState.roundSerial then
            return false
        end
        if now - runtimeState.lastWinAt < 0.5 then
            return false
        end
        runtimeState.lastWinAt = now
        runtimeState.lastWinRound = runtimeState.roundSerial
        runtimeState.wins += 1
        return true
    end

    local function registerLoss(): boolean
        if runtimeState.lastLossRound == runtimeState.roundSerial
            or runtimeState.resultWinCounted then
            return false
        end
        runtimeState.lastLossRound = runtimeState.roundSerial
        runtimeState.loses += 1
        return true
    end

    local function formatTimePlayed(seconds: number): string
        local total: number = math.max(0, math.floor(seconds))
        local hours: number = math.floor(total / 3600)
        local minutes: number = math.floor((total % 3600) / 60)
        local remainder: number = total % 60
        return string.format("%02d:%02d:%02d", hours, minutes, remainder)
    end

    local function updateStats(): ()
        if not autoWinCard or type(autoWinCard.SetStatus) ~= "function" then
            return
        end
        if not settings.stats then
            autoWinCard:SetStatus(nil)
            return
        end
        local played: number = os.clock() - runtimeState.sessionStartedAt
        autoWinCard:SetStatus(string.format(
            "Wins: %d | Time Played: %s | Kills: %d | Loses: %d",
            runtimeState.wins,
            formatTimePlayed(played),
            runtimeState.kills,
            runtimeState.loses
        ))
    end

    local function resultIdentity(): {[string]: any}
        return {
            player = localPlayer,
            userId = localPlayer.UserId,
            name = localPlayer.Name,
            displayName = localPlayer.DisplayName,
            team = teamToken(localPlayer),
        }
    end

    local function playerFromEventValue(value: any): Player?
        if typeof(value) ~= "Instance" then
            return nil
        end
        if value:IsA("Player") then
            return value :: Player
        end
        if value:IsA("Model") then
            local ok: boolean, player: any = pcall(function(): any
                return players:GetPlayerFromCharacter(value :: Model)
            end)
            if ok and player then
                return player :: Player
            end
        end
        return nil
    end

    local function playerFromEvent(arguments: {any}): Player?
        -- Cobalt captured PlayerRespawned with different argument layouts,
        -- including nil, Player. Never assume the Player is argument one.
        for _, value: any in pairs(arguments) do
            local player: Player? = playerFromEventValue(value)
            if player then
                return player
            end
        end
        return nil
    end

    local function onMatchResults(...: any): ()
        runtimeState.resultsPending = true
        runtimeState.observedRound = false
        runtimeState.resultWinCounted = false
        runtimeState.selected = nil
        cancelKnifeThrow()
        local arguments: {any} = {...}
        if rules.didLocalWin(arguments, resultIdentity(), false) then
            runtimeState.resultWinCounted = true
            registerWin()
            updateStats()
        end
    end

    local function onRemovePlayer(...: any): ()
        local arguments: {any} = {...}
        local removed: Player? = playerFromEvent(arguments)
        if removed and removed ~= localPlayer then
            return
        end
        -- RemovePlayer ends a round; it is not itself a victory or loss.
        runtimeState.resultsPending = true
        runtimeState.observedRound = false
        runtimeState.selected = nil
        cancelKnifeThrow()
    end

    local function onWinNotification(...: any): ()
        local arguments: {any} = {...}
        if rules.didLocalWin(arguments, resultIdentity(), true) then
            if registerWin() then
                runtimeState.resultWinCounted = true
            end
            updateStats()
        end
    end

    local function onSetDead(...: any): ()
        local arguments: {any} = {...}
        local dead: Player? = playerFromEvent(arguments)
        if not dead then
            return
        end
        runtimeState.deadPlayers[dead] = true
        local selected: any = runtimeState.selected
        if selected and selected.player == dead then
            runtimeState.selected = nil
        end
        if dead == localPlayer then
            -- SetDead is a death signal, never a win signal. Count one local
            -- loss per round and leave the other combat preferences alone.
            registerLoss()
            cancelKnifeThrow()
            restoreCamera()
            updateStats()
        end
    end

    local function onDestroyBody(...: any): ()
        local arguments: {any} = {...}
        -- The captured MVS DestroyBody shape is victim, optional data, killer.
        -- Only that observed third Player value is accepted as a local kill;
        -- a remote name or a victim alone never fabricates a kill.
        local victim: Player? = playerFromEventValue(arguments[1])
        local killer: Player? = playerFromEventValue(arguments[3])
        if victim and killer == localPlayer
            and runtimeState.killVictims[victim] ~= runtimeState.roundSerial then
            runtimeState.killVictims[victim] = runtimeState.roundSerial
            runtimeState.kills += 1
            updateStats()
        end
    end

    local function onPlayerRespawned(...: any): ()
        local arguments: {any} = {...}
        local respawned: Player? = playerFromEvent(arguments)
        if respawned then
            runtimeState.deadPlayers[respawned] = nil
            runtimeState.killVictims[respawned] = nil
        end
        if respawned and respawned ~= localPlayer then
            -- Another player's respawn must not reset our session statistics.
            return
        end
        runtimeState.deadPlayers[localPlayer] = nil
        runtimeState.roundSerial += 1
        runtimeState.observedRound = true
        runtimeState.resultsPending = false
        runtimeState.resultWinCounted = false
        runtimeState.nextGunAt = 0
        cancelKnifeThrow()
    end

    local function findRemote(path: string): Instance?
        local current: Instance? = replicated
        for segment: string in string.gmatch(path, "[^/]+") do
            current = current and current:FindFirstChild(segment)
        end
        return current
    end

    local function connectRemote(path: string, callback: any): ()
        if runtimeState.remoteBound[path] then
            return
        end
        local remote: Instance? = findRemote(path)
        if not remote then
            return
        end
        local ok: boolean, connection: any = pcall(function(): any
            return (remote :: any).OnClientEvent:Connect(callback)
        end)
        if ok and connection then
            runtimeState.remoteBound[path] = true
            track(connection)
        end
    end

    local function ensureRemoteEvents(): ()
        connectRemote("Packages/Networking/RE/Match/MatchResults", onMatchResults)
        connectRemote("Packages/Networking/RE/Match/RemovePlayer", onRemovePlayer)
        connectRemote("Packages/Networking/RE/Match/WinNotification", onWinNotification)
        connectRemote("Packages/Networking/RE/Match/SetDead", onSetDead)
        connectRemote("Packages/Networking/RE/Match/PlayerRespawned", onPlayerRespawned)
        connectRemote("Packages/Networking/RE/Combat/DestroyBody", onDestroyBody)
    end

    local function runGun(maxDistance: number, interval: number): (boolean, boolean)
        runtimeState.nextGunAt = os.clock() + interval
        local target: {[string]: any}? = nil
        if settings.silentAim then
            target = selectedTarget()
        end
        if not target then
            target = nearestEnemy(maxDistance)
        end
        return fireGun(target)
    end

    local function runKnifeThrow(maxDistance: number): ()
        -- No user interval: try on every scheduler tick. fireKnife only holds
        -- the short native windup, so a new attempt starts as soon as it ends.
        local target: {[string]: any}? = nearestEnemy(maxDistance)
        fireKnife(target)
    end

    local function runKillAura(): ()
        runtimeState.nextAuraAt = os.clock() + settings.killAuraInterval
        local knife: Tool? = findWeapon("Knife")
        if not knife then
            return
        end
        local target: {[string]: any}? = nearestEnemy(settings.killAuraRange)
        if target and equip(knife) then
            activateNative(knife, target)
        end
    end

    local function restoreHitbox(player: Player): ()
        local record: any = runtimeState.hitboxes[player]
        runtimeState.hitboxes[player] = nil
        if record and record.part then
            pcall(function(): ()
                record.part.Size = record.size
                record.part.Transparency = record.transparency
                record.part.CanCollide = record.canCollide
            end)
        end
    end

    local function restoreAllHitboxes(): ()
        for player: Player, _record: any in pairs(runtimeState.hitboxes) do
            restoreHitbox(player)
        end
        table.clear(runtimeState.hitboxes)
    end

    local function updateHitboxes(): ()
        local seen: {[Player]: boolean} = {}
        local desiredSize: Vector3 = Vector3.new(
            settings.hitboxSize, settings.hitboxSize, settings.hitboxSize
        )
        for _, player: Player in ipairs(players:GetPlayers()) do
            if isEnemy(player) then
                local root: BasePart? = rootOf(player.Character)
                if root then
                    seen[player] = true
                    local record: any = runtimeState.hitboxes[player]
                    if not record or record.part ~= root then
                        restoreHitbox(player)
                        record = {
                            part = root,
                            size = root.Size,
                            transparency = root.Transparency,
                            canCollide = root.CanCollide,
                        }
                        runtimeState.hitboxes[player] = record
                    end
                    if root.Size ~= desiredSize then
                        root.Size = desiredSize
                    end
                    root.Transparency = 0.65
                    root.CanCollide = false
                end
            end
        end
        for player: Player, _record: any in pairs(runtimeState.hitboxes) do
            if not seen[player] then
                restoreHitbox(player)
            end
        end
    end

    local function updateMatchToken(): ()
        local token: string? = matchToken(localPlayer)
        if token ~= runtimeState.lastMatchToken then
            table.clear(runtimeState.deadPlayers)
            if token ~= nil then
                -- A lobby transition clears the old token before the next
                -- match arrives. That still starts a new win-counting round.
                runtimeState.resultsPending = false
                runtimeState.resultWinCounted = false
                runtimeState.observedRound = true
                runtimeState.roundSerial += 1
                runtimeState.nextGunAt = 0
            else
                runtimeState.observedRound = false
                runtimeState.selected = nil
            end
            runtimeState.lastMatchToken = token
        end
    end

    local function update(_deltaTime: number): ()
        updateMatchToken()
        local now: number = os.clock()
        if now >= runtimeState.nextRemoteAt then
            runtimeState.nextRemoteAt = now + 2
            ensureRemoteEvents()
        end
        if settings.silentAim and now >= runtimeState.nextSelectionAt then
            runtimeState.nextSelectionAt = now + 0.06
            nearestEnemy(settings.maxDistance)
        elseif not settings.silentAim then
            runtimeState.selected = nil
        end

        if settings.silentAim and settings.autoShoot
            and now >= runtimeState.nextGunAt then
            runGun(settings.maxDistance, settings.shotInterval)
        end
        if settings.silentAim and settings.knifeThrow then
            runKnifeThrow(600)
        end
        if settings.killAura and now >= runtimeState.nextAuraAt then
            runKillAura()
        end
        if settings.hitboxes and now >= runtimeState.nextHitboxAt then
            runtimeState.nextHitboxAt = now + 0.2
            updateHitboxes()
        end
        if settings.stats and now >= runtimeState.nextStatsAt then
            runtimeState.nextStatsAt = now + 0.25
            updateStats()
        end
    end

    local function render(deltaTime: number): ()
        if not settings.silentAim or settings.silentMode ~= "Legit" then
            return
        end
        local camera: Camera? = currentWorkspace.CurrentCamera
        local target: {[string]: any}? = selectedTarget()
        if not camera or not target then
            return
        end
        local desired: CFrame = CFrame.lookAt(camera.CFrame.Position, target.part.Position)
        camera.CFrame = camera.CFrame:Lerp(
            desired, math.clamp(deltaTime * 18, 0.05, 1)
        )
    end

    local core: any = nil
    local teamProvider: any = nil
    local roleProvider: any = nil

    moduleCleanup = function(): ()
        settings.stats = false
        settings.silentAim = false
        settings.autoShoot = false
        settings.knifeThrow = false
        settings.killAura = false
        settings.hitboxes = false
        updateStats()
        setAimActivity(false)
        restoreAllHitboxes()
        cancelKnifeThrow()
        restoreCamera()
        uninstallHooks()
        if host.featureConnections.X2DuelsCore then
            host.disconnectFeatureConnection("X2DuelsCore")
        end
        if host.featureConnections.X2DuelsLegitAim then
            host.disconnectFeatureConnection("X2DuelsLegitAim")
        end
        for _, connection: any in ipairs(runtimeState.connections) do
            pcall(function(): () connection:Disconnect() end)
        end
        table.clear(runtimeState.connections)
        table.clear(runtimeState.remoteBound)
        table.clear(runtimeState.deadPlayers)
        if roleProvider and state.gameBridge
            and state.gameBridge.roleProvider == roleProvider then
            if type(state.unregisterRoleProvider) == "function" then
                state.unregisterRoleProvider(roleProvider)
            else
                state.gameBridge.roleProvider = nil
            end
        end
        if teamProvider and state.gameBridge
            and state.gameBridge.teamProvider == teamProvider then
            state.gameBridge.teamProvider = nil
            state.teamProvider = nil
        end
        if state.x2duelsCore == core then
            state.x2duelsCore = nil
        end
        if state.mvsdCore == core then
            state.mvsdCore = nil
        end
    end


    core = {
        settings = settings,
        RoleColors = ROLE_COLORS,
        teamOf = teamToken,
        matchIdOf = matchToken,
        relation = relation,
        inSameMatch = sharesMatch,
        isAlive = isAlive,
        isTeammate = isTeammate,
        isEnemy = isEnemy,
        nearestEnemy = nearestEnemy,
        targetFor = targetRecord,
        findGun = function(): Tool? return findWeapon("Gun") end,
        findKnife = function(): Tool? return findWeapon("Knife") end,
        equippedTool = equippedTool,
        toolKind = toolKind,
        equip = equip,
        activateNative = activateNative,
        fireGun = fireGun,
        fireKnife = fireKnife,
        getWins = function(): number return runtimeState.wins end,
        getStats = function(): {[string]: number}
            return {
                Wins = runtimeState.wins,
                TimePlayed = math.max(0, os.clock() - runtimeState.sessionStartedAt),
                Kills = runtimeState.kills,
                Loses = runtimeState.loses,
            }
        end,
    }
    state.x2duelsCore = core
    state.mvsdCore = core

    local function playerFromInstance(instance: Instance): Player?
        if instance:IsA("Player") then
            return instance :: Player
        end
        if instance:IsA("Model") then
            local ok: boolean, player: any = pcall(function(): any
                return players:GetPlayerFromCharacter(instance :: Model)
            end)
            return ok and player or nil
        end
        return nil
    end

    teamProvider = {
        Name = "X2Duels",
        Get = function(instance: Instance): string?
            local player: Player? = playerFromInstance(instance)
            return player and teamToken(player) or nil
        end,
        GetRelation = function(instance: Instance): string
            local player: Player? = playerFromInstance(instance)
            return player and relation(player) or "Unknown"
        end,
        IsFriendly = function(player: Player?): boolean
            return isTeammate(player)
        end,
    }
    if type(host.registerTeamProvider) == "function" then
        host.registerTeamProvider(teamProvider)
    end

    -- Supply the same palette to universal PlayerESP/Chams/Nametags without
    -- disabling their teammate filters. ReplacesTeams stays false: Team Check
    -- must still reject confirmed teammates and fail closed on Unknown.
    roleProvider = {
        Name = "X2Duels",
        ReplacesTeams = false,
        Roles = {"Enemy", "Teammate", "Unknown", "Outside"},
        Colors = ROLE_COLORS,
        Get = function(player: Player): string?
            local current: string = relation(player)
            return current ~= "Local" and current or nil
        end,
        GetColor = function(roleName: string): Color3?
            return ROLE_COLORS[roleName]
        end,
    }
    if type(host.registerRoleProvider) == "function" then
        host.registerRoleProvider(roleProvider)
    end

    local parentConfiguration: {[string]: any} = {
        parent = state.mvsdScroll,
        registry = state.mvsdFeatures,
    }
    local function card(
        name: string,
        description: string,
        order: number,
        callback: any,
        category: string?
    ): any
        local configuration: {[string]: any} = table.clone(parentConfiguration)
        configuration.categoryName = category
        return host.createUniversalFeature(name, description, order, callback, configuration)
    end

    local configData: any = host.configData
    if type(configData) == "table"
        and configData.values["X2Duels.layout"] ~= "v119" then
        local states: any = configData.states
        local values: any = configData.values
        if states["MVSD.SilentAIM.AutoShoot"] == nil
            and states["MVSD.AutoShoot"] ~= nil then
            states["MVSD.SilentAIM.AutoShoot"] = states["MVSD.AutoShoot"] == true
            if states["MVSD.AutoShoot"] == true then
                states["MVSD.SilentAIM"] = true
            end
        end
        if states["MVSD.SilentAIM.KnifeThrow"] == nil
            and states["MVSD.KnifeThrow"] ~= nil then
            states["MVSD.SilentAIM.KnifeThrow"] = states["MVSD.KnifeThrow"] == true
            if states["MVSD.KnifeThrow"] == true then
                states["MVSD.SilentAIM"] = true
            end
        end
        for _, optionKey: string in ipairs({"Sender", "Fireinterval"}) do
            local oldKey: string = "MVSD.AutoShoot." .. optionKey
            local newKey: string = "MVSD.SilentAIM." .. optionKey
            if values[newKey] == nil and values[oldKey] ~= nil then
                values[newKey] = values[oldKey]
            end
        end
        if states["MVSD.Hitbox"] == nil and states["MVSD.Hitboxes"] ~= nil then
            states["MVSD.Hitbox"] = states["MVSD.Hitboxes"] == true
        end
        -- The former Auto Win was a combat driver. Restore it as an opt-in
        -- statistics card, never as the old automation or its GUI options.
        states["MVSD.AutoFarm"] = false
        states["MVSD.AutoWin"] = false
        states["MVSD.TriggerBot"] = nil
        states["MVSD.AutoShoot"] = nil
        states["MVSD.KnifeThrow"] = nil
        states["MVSD.TeamESP"] = nil
        states["MVSD.AutoWin.PlayAgain"] = nil
        states["MVSD.PlayAgain"] = nil
        values["MVSD.AutoShoot.Throwinterval"] = nil
        values["MVSD.SilentAIM.Throwinterval"] = nil
        values["X2Duels.layout"] = "v119"
        if type(host.queueConfigSave) == "function" then
            host.queueConfigSave()
        end
    end

    local refreshAutoShootMode: () -> () = function(): () end

    autoWinCard = card(
        "Auto Win",
        "Session statistics only: Wins, Time Played, Kills and Loses",
        2,
        function(enabled: boolean): ()
            settings.stats = enabled
            runtimeState.nextStatsAt = 0
            updateStats()
        end,
        "Utilities"
    )
    host.addInformationOption(
        autoWinCard,
        "Status only. No automatic combat, rematch clicks or invented results; counters come from observed MVS events."
    )

    silentAimCard = card(
        "Silent AIM",
        "Nearest-player Gun/Knife combat with Legit camera aim or Silent local ray redirection",
        3,
        function(enabled: boolean): ()
            settings.silentAim = enabled
            setAimActivity(enabled)
            if enabled and settings.silentMode == "Silent" and not installHooks() then
                settings.silentAim = false
                setAimActivity(false)
                pcall(notify, "X2 Duels · Silent requiere hookfunction; Legit no lo necesita")
                forceCardOff(silentAimCard)
            end
            if not settings.silentAim then
                runtimeState.selected = nil
                cancelKnifeThrow()
                uninstallHooks()
                restoreCamera()
            end
            refreshAutoShootMode()
        end,
        "Combat"
    )
    local autoShootOptionLabel: TextLabel? = nil
    refreshAutoShootMode = function(): ()
        if autoShootOptionLabel then
            autoShootOptionLabel.Text = "Auto Shoot · " .. settings.silentMode
        end
        if silentAimCard and type(silentAimCard.SetStatus) == "function" then
            silentAimCard:SetStatus(
                settings.silentAim and settings.autoShoot and settings.silentMode or nil
            )
        end
    end
    if type(host.addSectionOption) == "function" then
        host.addSectionOption(silentAimCard, "Gun")
    end
    local autoShootButton: TextButton = host.addToggleOption(
        silentAimCard,
        "Auto Shoot",
        false,
        function(enabled: boolean): ()
            settings.autoShoot = enabled
            runtimeState.nextGunAt = 0
            if not enabled then
                restoreCamera()
            end
            refreshAutoShootMode()
        end,
        "Runs only while Silent AIM is ON; the same Legit/Silent mode is used for every shot.",
        true
    )
    if autoShootButton.Parent then
        autoShootOptionLabel = autoShootButton.Parent:FindFirstChild("OptionLabel") :: TextLabel?
    end
    refreshAutoShootMode()
    host.addCycleOption(
        silentAimCard, "Mode", {"Legit", "Silent"}, 1,
        function(value: string): ()
            settings.silentMode = value
            if value == "Silent" then
                if settings.silentAim and not installHooks() then
                    settings.silentAim = false
                    setAimActivity(false)
                    pcall(notify, "X2 Duels · no se pudieron instalar los hooks Silent")
                    forceCardOff(silentAimCard)
                end
            else
                uninstallHooks()
            end
            refreshAutoShootMode()
        end
    )
    host.addCycleOption(
        silentAimCard, "Sender", {"CFrame", "Button"}, 1,
        function(value: string): ()
            settings.senderMode = value
            restoreCamera()
        end
    )
    host.addNumberOption(
        silentAimCard, "Fire interval", 0.035, 0.02, 0.25,
        function(value: number): ()
            settings.shotInterval = value
        end
    )
    host.addToggleOption(silentAimCard, "Team Check", true, function(value: boolean): ()
        settings.teamCheck = value
        runtimeState.selected = nil
        restoreAllHitboxes()
    end)
    host.addToggleOption(silentAimCard, "Wall Check", true, function(value: boolean): ()
        settings.wallCheck = value
        runtimeState.selected = nil
    end)
    host.addNumberOption(silentAimCard, "Range", 1000, 50, 1500, function(value: number): ()
        settings.maxDistance = value
    end)
    host.addInformationOption(
        silentAimCard,
        "Team Check rejects confirmed teammates and unknown sides. Wall Check never redirects a ray through geometry."
    )
    host.addInformationOption(
        silentAimCard,
        "CFrame aims before native Tool:Activate() and needs no action button. Button preserves your camera; the assigned key fires without toggling Silent AIM."
    )

    local function pressSenderButton(): ()
        -- This is an action key, not the Silent AIM master toggle. CFrame is
        -- driven by Auto Shoot/native activation and never needs this button.
        if not settings.silentAim or settings.senderMode ~= "Button" then
            return
        end
        local target: {[string]: any}? = selectedTarget()
            or nearestEnemy(settings.maxDistance)
        fireGun(target)
    end
    if type(state.bindFeatureActivationKey) == "function" then
        state.bindFeatureActivationKey(
            silentAimCard, Enum.KeyCode.Unknown, pressSenderButton
        )
    end

    if type(host.addSectionOption) == "function" then
        host.addSectionOption(silentAimCard, "Knife")
    end
    host.addToggleOption(
        silentAimCard,
        "Knife Throw",
        false,
        function(enabled: boolean): ()
            settings.knifeThrow = enabled
            if not enabled then cancelKnifeThrow() end
        end,
        "Requires Silent AIM ON. Attempts the native throw on every frame; there is no interval setting.",
        true
    )
    host.addInformationOption(
        silentAimCard,
        "Knife Throw uses the native right-click/ForceThrow path and waits only for the native windup."
    )

    local auraCard: any = card(
        "Kill Aura",
        "Use native knife activation on a nearby valid target",
        5,
        function(enabled: boolean): ()
            settings.killAura = enabled
            runtimeState.nextAuraAt = 0
            if not enabled then restoreCamera() end
        end,
        "Combat"
    )
    host.addNumberOption(auraCard, "Reach", 12, 3, 25, function(value: number): ()
        settings.killAuraRange = value
    end)
    host.addNumberOption(auraCard, "Swing interval", 0.12, 0.05, 0.6, function(value: number): ()
        settings.killAuraInterval = value
    end)

    local hitboxCard: any = card(
        "Hitbox",
        "Expand only valid target roots and restore their original properties when disabled",
        6,
        function(enabled: boolean): ()
            settings.hitboxes = enabled
            runtimeState.nextHitboxAt = 0
            if not enabled then restoreAllHitboxes() end
        end,
        "Exploits"
    )
    host.addNumberOption(hitboxCard, "Size", 10, 2, 30, function(value: number): ()
        settings.hitboxSize = value
        restoreAllHitboxes()
    end)

    runtimeState.lastMatchToken = matchToken(localPlayer)
    ensureRemoteEvents()
    track(localPlayer.CharacterAdded:Connect(function(): ()
        runtimeState.deadPlayers[localPlayer] = nil
        runtimeState.selected = nil
        runtimeState.nextGunAt = 0
        cancelKnifeThrow()
        restoreCamera()
    end))
    track(players.PlayerRemoving:Connect(function(player: Player): ()
        runtimeState.deadPlayers[player] = nil
        if runtimeState.selected and runtimeState.selected.player == player then
            runtimeState.selected = nil
        end
        restoreHitbox(player)
    end))

    host.featureConnections.X2DuelsCore = runtime.TaskManager:Connect(update)
    host.featureConnections.X2DuelsLegitAim = runtime.TaskManager:Connect(render, "render")

end

function Module.init(runtime: any): any
    if Module.Initialized then
        return Module
    end
    assert(type(runtime) == "table" and runtime.TaskManager,
        "X2Duels requires Runtime.TaskManager")
    Module.Runtime = runtime
    local ok: boolean, failure: any = pcall(buildX2Duels, runtime)
    if not ok then
        moduleCleanup()
        Module.Runtime = nil
        error(failure)
    end
    Module.Initialized = true
    return Module
end

function Module.destroy(): ()
    moduleCleanup()
    moduleCleanup = function(): () end
    Module.Runtime = nil
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Blatant/Fly.lua"] = [[
export type Runtime = {
    framework: any,
    entity: any,
    host: any,
    services: any,
}

local Module = {
    Name = "Fly",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local activeCleanup: (() -> ())? = nil

function Module.init(context: Runtime): any
    local host: any = context.host
    local framework: any = context.framework
    local movementInput: any = context.services.movementInput
    local mobileActions: any = context.services.mobileActions
    local getCharacterParts: any = host.getCharacterParts
    local UserInputService: any = host.UserInputService
    local currentWorkspace: Workspace = host.workspace or workspace

    type FlySettings = {
        method: string,
        floatMethod: string,
        speed: number,
        verticalSpeed: number,
        response: number,
        burstInterval: number,
        wallCheck: boolean,
        faceCamera: boolean,
        upKey: Enum.KeyCode,
        downKey: Enum.KeyCode,
    }

    local flySettings: FlySettings = {
        method = "Velocity",
        floatMethod = "Velocity",
        speed = 70,
        verticalSpeed = 56,
        response = 1,
        burstInterval = 0.2,
        wallCheck = true,
        faceCamera = true,
        upKey = Enum.KeyCode.Space,
        downKey = Enum.KeyCode.LeftControl,
    }

    local flyRuntime: any = {
        yLevel = nil :: number?,
        burstAt = 0,
        platform = nil :: BasePart?,
        walkSpeed = nil :: number?,
        walkHumanoid = nil :: Humanoid?,
        root = nil :: BasePart?,
        method = nil :: string?,
        floatMethod = nil :: string?,
    }
    local flySmoothedVelocity: Vector3 = Vector3.zero

    local flyObjects: {[Instance]: boolean} =
        setmetatable({}, {__mode = "k"}) :: any
    local flyTouchVertical: number = 0

    local function removeFlyObjects(): ()
        for object: Instance in pairs(flyObjects) do
            if object.Parent then
                object:Destroy()
            end
        end
        flyObjects = setmetatable({}, {__mode = "k"}) :: any
    end

    local function restoreWalkSpeed(): ()
        local humanoid: Humanoid? = flyRuntime.walkHumanoid
        if humanoid and humanoid.Parent and flyRuntime.walkSpeed ~= nil then
            humanoid.WalkSpeed = flyRuntime.walkSpeed
        end
        flyRuntime.walkSpeed = nil
        flyRuntime.walkHumanoid = nil
    end

    local function clearPlatform(): ()
        if flyRuntime.platform then flyRuntime.platform:Destroy() end
        flyRuntime.platform = nil
    end

    local function ensureFlyConstraints(root: BasePart): (LinearVelocity, AlignOrientation)
        local attachment: Attachment? = root:FindFirstChild("Wurst_FlyAttachment") :: Attachment?
        if not attachment then
            local newAttachment: Attachment = Instance.new("Attachment")
            newAttachment.Name = "Wurst_FlyAttachment"
            newAttachment.Parent = root
            attachment = newAttachment
        end
        local resolvedAttachment: Attachment = attachment :: Attachment
        flyObjects[resolvedAttachment] = true

        local velocity: LinearVelocity? = root:FindFirstChild("Wurst_FlyVelocity") :: LinearVelocity?
        if not velocity then
            local newVelocity: LinearVelocity = Instance.new("LinearVelocity")
            newVelocity.Name = "Wurst_FlyVelocity"
            newVelocity.Attachment0 = resolvedAttachment
            newVelocity.MaxForce = math.huge
            newVelocity.RelativeTo = Enum.ActuatorRelativeTo.World
            newVelocity.VelocityConstraintMode = Enum.VelocityConstraintMode.Vector
            newVelocity.Parent = root
            velocity = newVelocity
        end
        flyObjects[velocity :: LinearVelocity] = true

        local orientation: AlignOrientation? =
            root:FindFirstChild("Wurst_FlyOrientation") :: AlignOrientation?
        if not orientation then
            local newOrientation: AlignOrientation = Instance.new("AlignOrientation")
            newOrientation.Name = "Wurst_FlyOrientation"
            newOrientation.Attachment0 = resolvedAttachment
            newOrientation.MaxTorque = math.huge
            newOrientation.Mode = Enum.OrientationAlignmentMode.OneAttachment
            newOrientation.Responsiveness = 28
            newOrientation.RigidityEnabled = false
            newOrientation.Parent = root
            orientation = newOrientation
        end
        flyObjects[orientation :: AlignOrientation] = true

        return velocity :: LinearVelocity, orientation :: AlignOrientation
    end

    local function getFlyDirection(camera: Camera): (Vector3, number, Vector3)
        local cameraForward: Vector3 = Vector3.new(
            camera.CFrame.LookVector.X,
            0,
            camera.CFrame.LookVector.Z
        )
        local cameraRight: Vector3 = Vector3.new(
            camera.CFrame.RightVector.X,
            0,
            camera.CFrame.RightVector.Z
        )
        cameraForward = cameraForward.Magnitude > 0.001
            and cameraForward.Unit
            or Vector3.new(0, 0, -1)
        cameraRight = cameraRight.Magnitude > 0.001
            and cameraRight.Unit
            or Vector3.new(1, 0, 0)

        local forwardScalar: number, rightScalar: number = movementInput.getVector()
        local horizontal: Vector3 = cameraForward * forwardScalar
            + cameraRight * rightScalar
        if horizontal.Magnitude > 1 then
            horizontal = horizontal.Unit
        end

        local vertical: number = 0
        local keyboardAvailable: boolean = UserInputService.KeyboardEnabled
            and UserInputService:GetFocusedTextBox() == nil
        if flyTouchVertical > 0
            or (keyboardAvailable
                and UserInputService:IsKeyDown(flySettings.upKey)) then
            vertical = vertical + 1
        end
        if flyTouchVertical < 0
            or (keyboardAvailable
                and UserInputService:IsKeyDown(flySettings.downKey)) then
            vertical = vertical - 1
        end

        if vertical == 0 and not UserInputService.KeyboardEnabled and movementInput.isJumpHeld() then
            vertical = 1
        end

        return horizontal, vertical, cameraForward
    end

    local applyFlyHorizontal: (BasePart, Humanoid, Vector3, number) -> ()
    local applyFlyVertical: (BasePart, Humanoid, number, number) -> ()
    do
    applyFlyHorizontal = function(
        root: BasePart,
        humanoid: Humanoid,
        moveDirection: Vector3,
        deltaTime: number
    ): ()
        local method: string = flySettings.method
        local currentVelocity: Vector3 = root.AssemblyLinearVelocity
        local target: Vector3 = moveDirection * flySettings.speed

        if method == "WalkSpeed" then
            if not flyRuntime.walkSpeed then
                flyRuntime.walkSpeed = humanoid.WalkSpeed
                flyRuntime.walkHumanoid = humanoid
            end
            humanoid.WalkSpeed = flySettings.speed
            if flySettings.speed < 0 then
                root.AssemblyLinearVelocity = Vector3.new(
                    target.X,
                    currentVelocity.Y,
                    target.Z
                )
            end
            return
        end

        if method == "Pulse" then

            local period: number = math.max(flySettings.burstInterval, 0.05) * 2
            local burst: boolean = (os.clock() % period) < (period * 0.5)
            target = target * (burst and 1.8 or 0.2)
        end

        if method == "CFrame" or method == "Blink" then
            local step: Vector3 = moveDirection * flySettings.speed * deltaTime
            if method == "Blink" then
                local interval: number = math.max(flySettings.burstInterval, 0.05)
                if os.clock() < flyRuntime.burstAt then
                    step = Vector3.zero
                else
                    flyRuntime.burstAt = os.clock() + interval
                    step = moveDirection * flySettings.speed * interval
                end
            end
            if step.Magnitude > 0.001 and flySettings.wallCheck then
                local raycastParams: RaycastParams = RaycastParams.new()
                raycastParams.FilterType = Enum.RaycastFilterType.Exclude
                raycastParams.FilterDescendantsInstances = {root.Parent :: Instance}
                local wallHit: RaycastResult? = currentWorkspace:Raycast(
                    root.Position,
                    step + step.Unit * 2,
                    raycastParams
                )
                if wallHit then
                    step = Vector3.zero
                end
            end
            if step.Magnitude > 0.001 then
                root.CFrame = root.CFrame + step
            end

            root.AssemblyLinearVelocity = Vector3.new(0, currentVelocity.Y, 0)
            return
        end

        if method == "Impulse" then
            local difference: Vector3 = (target - currentVelocity)
                * Vector3.new(1, 0, 1)

            local threshold: number = moveDirection.Magnitude < 0.01 and 10 or 2
            if difference.Magnitude > threshold then
                root:ApplyImpulse(difference * root.AssemblyMass)
            end
            return
        end

        local alpha: number = 1 - math.exp(-12 * flySettings.response * deltaTime)
        flySmoothedVelocity = flySmoothedVelocity:Lerp(target, alpha)
        if method == "Constraint" then
            return
        end
        root.AssemblyLinearVelocity = Vector3.new(
            flySmoothedVelocity.X,
            currentVelocity.Y,
            flySmoothedVelocity.Z
        )
    end

    applyFlyVertical = function(
        root: BasePart,
        humanoid: Humanoid,
        vertical: number,
        deltaTime: number
    ): ()
        local method: string = flySettings.floatMethod
        local currentVelocity: Vector3 = root.AssemblyLinearVelocity
        local targetY: number = vertical * flySettings.verticalSpeed

        if method == "Floor" then
            local platform: BasePart? = flyRuntime.platform
            if not platform or not platform.Parent then
                local newPlatform: BasePart = Instance.new("Part")
                newPlatform.Name = "Wurst_FlyPlatform"
                newPlatform.Anchored = true
                newPlatform.CanQuery = false
                newPlatform.CanTouch = false
                newPlatform.Size = Vector3.new(8, 1, 8)
                newPlatform.Transparency = 1

                newPlatform.Parent = currentWorkspace.CurrentCamera
                flyRuntime.platform = newPlatform
                platform = newPlatform
            end
            local resolved: BasePart = platform :: BasePart

            resolved.CFrame = vertical < 0
                and CFrame.new(0, -4096, 0)
                or CFrame.new(root.Position - Vector3.new(0, humanoid.HipHeight + 1.5, 0))
            if vertical > 0 then
                root.AssemblyLinearVelocity = Vector3.new(
                    currentVelocity.X,
                    targetY,
                    currentVelocity.Z
                )
            end
            return
        end

        if method == "Bypass" then

            local period: number = math.max(flySettings.burstInterval, 0.05) * 5
            if (os.clock() % period) > (period * 0.8) then

                flyRuntime.yLevel = nil
                return
            end
            local held: number = flyRuntime.yLevel or root.Position.Y
            held = held + targetY * deltaTime
            flyRuntime.yLevel = held
            root.AssemblyLinearVelocity = Vector3.new(
                currentVelocity.X,
                0,
                currentVelocity.Z
            )
            root.CFrame = root.CFrame + Vector3.new(0, held - root.Position.Y, 0)
            return
        end

        if method == "Hover" or method == "Jump" then
            local level: number = flyRuntime.yLevel or root.Position.Y
            level = level + targetY * deltaTime
            if flySettings.wallCheck then
                local offset: number = level - root.Position.Y
                if math.abs(offset) > 0.001 then
                    local raycastParams: RaycastParams = RaycastParams.new()
                    raycastParams.FilterType = Enum.RaycastFilterType.Exclude
                    raycastParams.FilterDescendantsInstances = {root.Parent :: Instance}
                    local ceilingHit: RaycastResult? = currentWorkspace:Raycast(
                        root.Position,
                        Vector3.new(0, offset, 0),
                        raycastParams
                    )
                    if ceilingHit then
                        level = ceilingHit.Position.Y
                            - math.sign(offset) * (humanoid.HipHeight + 0.5)
                    end
                end
            end
            flyRuntime.yLevel = level
            if method == "Hover" then
                root.AssemblyLinearVelocity = Vector3.new(
                    currentVelocity.X,
                    0,
                    currentVelocity.Z
                )
                root.CFrame = root.CFrame + Vector3.new(0, level - root.Position.Y, 0)
            elseif root.Position.Y < level - 0.5 then
                humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
            end
            return
        end

        if method == "Bounce" then
            local period: number = math.max(flySettings.burstInterval, 0.05) * 4
            local rising: boolean = (os.clock() % period) < (period * 0.5)
            targetY = targetY
                + (rising and 1 or -1) * flySettings.verticalSpeed * 0.45
        end

        if method == "Impulse" then
            local difference: number = targetY - currentVelocity.Y
            if math.abs(difference) > 2 then
                root:ApplyImpulse(Vector3.new(0, difference, 0) * root.AssemblyMass)
            end
            return
        end

        root.AssemblyLinearVelocity = Vector3.new(
            currentVelocity.X,
            targetY,
            currentVelocity.Z
        )
    end
    end

    local fly: any
    fly = framework.Categories.Exploits:CreateModule({
        Name = "Fly",
        Category = "Exploits",
        ConfigKey = "Universal.Fly",
        Tooltip = "Use WASD to move, Space to rise and LeftControl to descend. "
            .. "Method picks how you travel sideways and Float picks what "
            .. "holds you up; if a game blocks one combination, another "
            .. "usually works.",
        Function = function(enabled: boolean): ()

            removeFlyObjects()
            flySmoothedVelocity = Vector3.zero
            flyTouchVertical = 0
            flyRuntime.yLevel = nil
            flyRuntime.burstAt = 0
            clearPlatform()
            restoreWalkSpeed()
            flyRuntime.root = nil
            flyRuntime.method = nil
            flyRuntime.floatMethod = nil

            if not enabled then
                fly:SetStatus(nil)
                local _, humanoid: Humanoid?, root: BasePart? = getCharacterParts()
                if root then
                    (root :: BasePart).AssemblyLinearVelocity = Vector3.zero
                end
                return
            end

            fly:SetStatus(flySettings.method)
            fly:Loop(function(deltaTime: number): ()
                local _, humanoid, root = getCharacterParts()
                local camera: Camera? = currentWorkspace.CurrentCamera
                if not humanoid or not root or not camera then
                    removeFlyObjects()
                    clearPlatform()
                    restoreWalkSpeed()
                    flyRuntime.root = nil
                    flyRuntime.yLevel = nil
                    return
                end

                local method: string = flySettings.method
                local floatMethod: string = flySettings.floatMethod

                if flyRuntime.root ~= root or flyRuntime.method ~= method
                    or flyRuntime.floatMethod ~= floatMethod then
                    removeFlyObjects()
                    clearPlatform()
                    restoreWalkSpeed()
                    flyRuntime.yLevel = nil
                    flyRuntime.burstAt = 0
                    flySmoothedVelocity = Vector3.zero
                    flyRuntime.root = root
                    flyRuntime.method = method
                    flyRuntime.floatMethod = floatMethod
                end

                local moveDirection, vertical, cameraForward = getFlyDirection(camera)
                if flySettings.wallCheck and moveDirection.Magnitude > 0.001 then
                    local raycastParams: RaycastParams = RaycastParams.new()
                    raycastParams.FilterType = Enum.RaycastFilterType.Exclude
                    raycastParams.FilterDescendantsInstances = {root.Parent :: Instance}
                    local wallHit: RaycastResult? = currentWorkspace:Raycast(
                        root.Position,
                        moveDirection.Unit * 2.75,
                        raycastParams
                    )
                    if wallHit then
                        moveDirection = Vector3.zero
                        flySmoothedVelocity = Vector3.zero
                    end
                end

                if method == "Constraint" then
                    local velocity, orientation = ensureFlyConstraints(root)
                    applyFlyHorizontal(root, humanoid, moveDirection, deltaTime)
                    velocity.Enabled = true
                    velocity.VectorVelocity = Vector3.new(
                        flySmoothedVelocity.X,
                        vertical * flySettings.verticalSpeed,
                        flySmoothedVelocity.Z
                    )
                    orientation.Enabled = flySettings.faceCamera
                    orientation.CFrame = CFrame.lookAt(Vector3.zero, cameraForward)
                    return
                end

                removeFlyObjects()
                applyFlyHorizontal(root, humanoid, moveDirection, deltaTime)
                applyFlyVertical(root, humanoid, vertical, deltaTime)

                if floatMethod ~= "Floor" and flyRuntime.platform then
                    (flyRuntime.platform :: BasePart):Destroy()
                    flyRuntime.platform = nil
                end
                if floatMethod ~= "Hover" and floatMethod ~= "Jump" and floatMethod ~= "Bypass" then
                    flyRuntime.yLevel = nil
                end

                if flySettings.faceCamera and cameraForward.Magnitude > 0.001 then
                    root.CFrame = CFrame.lookAt(root.Position, root.Position + cameraForward)
                end
            end)
        end,
    })

    fly:CreateDropdown({
        Name = "Method",
        List = {"Velocity", "Constraint", "Impulse", "CFrame", "Blink", "Pulse", "WalkSpeed"},
        Index = 1,
        Function = function(value: string): ()
            flySettings.method = value
            if fly.Enabled then
                fly:SetStatus(value)
            end
        end,
        Tooltip = "Sideways engine. Velocity is smooth, CFrame ignores physics, "
            .. "WalkSpeed just runs faster.",
    })
    fly:CreateDropdown({
        Name = "Float",
        List = {"Velocity", "Impulse", "Hover", "Jump", "Bounce", "Floor", "Bypass"},
        Index = 1,
        Function = function(value: string): ()
            flySettings.floatMethod = value
        end,
        Tooltip = "Applies to non-Constraint methods; Constraint holds altitude with its own velocity. Hover locks an altitude, Floor "
            .. "stands you on an invisible part, and Bypass drops you to the "
            .. "ground for an instant every few seconds so the server sees "
            .. "you land.",
    })
    fly:CreateSlider({
        Name = "Horizontal speed",
        Min = 1,
        Max = 250,
        Default = flySettings.speed,
        Function = function(value: number): ()
            flySettings.speed = value
        end,
        Tooltip = "Studs per second while holding WASD. Negative values reverse the direction.",
    })
    fly:CreateSlider({
        Name = "Vertical speed",
        Min = 1,
        Max = 250,
        Default = flySettings.verticalSpeed,
        Function = function(value: number): ()
            flySettings.verticalSpeed = value
        end,
        Tooltip = "Studs per second while rising or descending. Negative values reverse the direction.",
    })
    fly:CreateSlider({
        Name = "Response multiplier",
        Show = {Option = "Method", Values = {"Velocity", "Constraint", "Pulse"}},
        Min = 0.5,
        Max = 2,
        Default = flySettings.response,
        Function = function(value: number): ()
            flySettings.response = value
        end,
        Tooltip = "How sharply the flight reacts to input. Higher is twitchier.",
    })
    fly:CreateSlider({
        Name = "Burst interval (s)",
        Min = 0.05,
        Max = 1,
        Default = flySettings.burstInterval,
        Function = function(value: number): ()
            flySettings.burstInterval = value
        end,
        Tooltip = "Cycle length for Blink, Pulse, Bounce and Bypass. Shorter "
            .. "is smoother.",
    })
    fly:CreateToggle({
        Name = "Wall check",
        Default = flySettings.wallCheck,
        Function = function(value: boolean): ()
            flySettings.wallCheck = value
        end,
        Tooltip = "Stop against solid geometry instead of flying through it.",
    })
    fly:CreateToggle({
        Name = "Face camera",
        Default = flySettings.faceCamera,
        Function = function(value: boolean): ()
            flySettings.faceCamera = value
        end,
        Tooltip = "Rotate the character to follow wherever the camera looks.",
    })
    local upKey: any = fly:CreateBind({
        Name = "Up key",
        Default = flySettings.upKey,
        Function = function(value: Enum.KeyCode): ()
            flySettings.upKey = value
        end,
        Tooltip = "Hold to gain altitude.",
    })
    local downKey: any = fly:CreateBind({
        Name = "Down key",
        Default = flySettings.downKey,
        Function = function(value: Enum.KeyCode): ()
            flySettings.downKey = value
        end,
        Tooltip = "Hold to lose altitude.",
    })

    if mobileActions.bindPlacement then
        mobileActions.bindPlacement(
            upKey.Object,
            "UniversalFlyUp",
            "UP",
            function(): () end,
            {
                onPress = function(): ()
                    flyTouchVertical = 1
                end,
                onRelease = function(): ()
                    if flyTouchVertical == 1 then
                        flyTouchVertical = 0
                    end
                end,
            }
        )
        mobileActions.bindPlacement(
            downKey.Object,
            "UniversalFlyDown",
            "DOWN",
            function(): () end,
            {
                onPress = function(): ()
                    flyTouchVertical = -1
                end,
                onRelease = function(): ()
                    if flyTouchVertical == -1 then
                        flyTouchVertical = 0
                    end
                end,
            }
        )
    end

    activeCleanup = function(): ()
        if fly.Enabled then fly:Toggle(false) end
        removeFlyObjects()
        clearPlatform()
        restoreWalkSpeed()
    end
    Module.Initialized = true
    return fly
end

function Module.destroy(): ()
    if activeCleanup then
        pcall(activeCleanup)
    end
    activeCleanup = nil
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Blatant/Invisible.lua"] = [[
-- Local ghost: a real, unanchored Humanoid walks under native gravity.
-- Only explicit Ghost Fly uses CFrame motion; the real character stays hidden.
local Module = {Name="Ghost",PlaceId=0,Initialized=false}
local cleanup

function Module.init(context)
    local host, services = context.host, context.services
    local player, input, run = host.LocalPlayer, host.UserInputService, host.RunService
    local world = host.workspace or workspace
    local settings = {fly=false,speed=55,depth=120,transparency=0.5}
    local state = {connections={},tracks={}}
    local card
    local function parts(character)
        return character and character:FindFirstChildOfClass("Humanoid"),
            character and character:FindFirstChild("HumanoidRootPart")
    end
    local function activity(active)
        if services.activity then services.activity.set("ghost",active) end
    end
    local function cameraBusy()
        return services.freeCam and services.freeCam.IsActive()
            or services.spectate and services.spectate.IsActive()
    end
    local function clearGhost()
        local camera = world.CurrentCamera
        if camera and camera.CameraSubject == state.humanoid then
            camera.CameraSubject = parts(player.Character)
        end
        for _,track in pairs(state.tracks) do pcall(function() track:Stop(0) end) end
        table.clear(state.tracks)
        if state.model then state.model:Destroy() end
        state.model,state.humanoid,state.root,state.animation,state.flyMode = nil,nil,nil,nil,nil
    end
    local function stop()
        for _,connection in ipairs(state.connections) do connection:Disconnect() end
        table.clear(state.connections)
        if state.character == player.Character and state.root then
            local humanoid, root = parts(player.Character)
            if root and humanoid and humanoid.Health > 0 then
                root.CFrame = state.root.CFrame
                root.AssemblyLinearVelocity,root.AssemblyAngularVelocity = Vector3.zero,Vector3.zero
            end
        end
        clearGhost();state.character=nil;activity(false)
    end
    local function spawnGhost(character,root)
        clearGhost()
        local archivable = character.Archivable
        character.Archivable = true
        local ok, clone = pcall(function() return character:Clone() end)
        character.Archivable = archivable
        if not ok or not clone then return false end
        local humanoid, ghostRoot = parts(clone)
        if not humanoid or not ghostRoot then clone:Destroy();return false end
        for _,object in ipairs(clone:GetDescendants()) do
            if object:IsA("Script") or object:IsA("LocalScript") or object:IsA("Tool") then
                object:Destroy()
            elseif object:IsA("BasePart") then
                object.Anchored = false
                object.CanTouch,object.CanQuery,object.CastShadow = false,false,false
                object.Transparency = math.clamp(settings.transparency,0,1)
                object.CanCollide = object.Name=="Head" or object.Name=="Torso"
                    or object.Name=="UpperTorso" or object.Name=="LowerTorso"
            end
        end
        clone.Name="Wurst_Ghost"
        humanoid.AutoRotate=true;humanoid.PlatformStand=false;humanoid.Sit=false
        humanoid.DisplayDistanceType=Enum.HumanoidDisplayDistanceType.None
        humanoid.WalkSpeed=16
        clone:PivotTo(root.CFrame)
        clone.Parent=world
        state.character,state.model,state.humanoid,state.root = character,clone,humanoid,ghostRoot
        state.camera=nil
        local highlight=Instance.new("Highlight")
        highlight.Name="GhostHighlight";highlight.FillColor=Color3.fromRGB(120,210,255)
        highlight.OutlineColor=Color3.fromRGB(220,245,255)
        highlight.FillTransparency=0.6;highlight.OutlineTransparency=0.15
        highlight.Adornee=clone;highlight.Parent=clone
        return true
    end
    local function animate()
        local humanoid=state.humanoid
        local kind=humanoid:GetState()
        local name=kind==Enum.HumanoidStateType.Jumping and "jump"
            or humanoid.FloorMaterial==Enum.Material.Air and "fall"
            or humanoid.MoveDirection.Magnitude>0.05 and (humanoid.WalkSpeed>16 and "run" or "walk") or "idle"
        if settings.fly then name="idle" end
        if state.animation==name then return end
        if state.animation and state.tracks[state.animation] then state.tracks[state.animation]:Stop(0.15) end
        state.animation=name
        if state.tracks[name]==false then return end
        if not state.tracks[name] then
            local source=state.character:FindFirstChild("Animate")
            local folder=source and source:FindFirstChild(name)
            local animation=folder and folder:FindFirstChildWhichIsA("Animation",true)
            local temporary
            if not animation then
                local r6=humanoid.RigType==Enum.HumanoidRigType.R6
                local ids=r6 and {idle=180435571,walk=180426354,run=180426354,jump=125750702,fall=180436148}
                    or {idle=507766666,walk=507777826,run=507767714,jump=507765000,fall=507767968}
                temporary=Instance.new("Animation");temporary.AnimationId="rbxassetid://"..ids[name];animation=temporary
            end
            local ok,track=pcall(function()
                local animator=humanoid:FindFirstChildOfClass("Animator")
                if not animator then animator=Instance.new("Animator");animator.Parent=humanoid end
                return animator:LoadAnimation(animation)
            end)
            if temporary then temporary:Destroy() end
            state.tracks[name]=ok and track or false
        end
        local track=state.tracks[name]
        if track then
            track.Looped=name~="jump"
            track.Priority=name=="idle" and Enum.AnimationPriority.Idle or Enum.AnimationPriority.Movement
            track:Play(0.15)
        end
    end
    local function step(dt)
        local character=player.Character
        local humanoid, root=parts(character)
        if not humanoid or not root or humanoid.Health<=0 then return end
        if state.character~=character then
            if not spawnGhost(character,root) then return end
        end
        if not state.model.Parent or not state.root.Parent or state.humanoid.Health<=0 then card:Toggle(false);return end
        local ghostRoot, ghostHumanoid=state.root,state.humanoid
        if state.flyMode~=settings.fly then
            state.flyMode=settings.fly
            for _,part in ipairs(state.model:GetDescendants()) do
                if part:IsA("BasePart") then
                    part.Anchored=settings.fly and part==ghostRoot
                    part.CanCollide=not settings.fly and (part.Name=="Head" or part.Name=="Torso"
                        or part.Name=="UpperTorso" or part.Name=="LowerTorso")
                end
            end
            ghostHumanoid.PlatformStand=settings.fly
            ghostRoot.AssemblyLinearVelocity,ghostRoot.AssemblyAngularVelocity=Vector3.zero,Vector3.zero
        end
        local camera=world.CurrentCamera
        if camera and not cameraBusy() and (state.camera~=camera or camera.CameraSubject==humanoid) then
            camera.CameraSubject=ghostHumanoid;state.camera=camera
        end
        if settings.fly then
            if camera and not input:GetFocusedTextBox() then
                local direction=Vector3.zero
                for _,control in ipairs({{Enum.KeyCode.W,camera.CFrame.LookVector},{Enum.KeyCode.S,-camera.CFrame.LookVector},
                    {Enum.KeyCode.D,camera.CFrame.RightVector},{Enum.KeyCode.A,-camera.CFrame.RightVector},
                    {Enum.KeyCode.Space,Vector3.yAxis},{Enum.KeyCode.LeftControl,-Vector3.yAxis}}) do
                    if input:IsKeyDown(control[1]) then direction+=control[2] end
                end
                if direction.Magnitude>0 then ghostRoot.CFrame+=direction.Unit*settings.speed*math.clamp(dt,0,0.1) end
            end
        else
            -- No CFrame assignment, floor-snapping or fixed-height plane here.
            -- Roblox resolves gravity, ground, walls, slopes and jumping.
            local focused=input:GetFocusedTextBox()
            ghostHumanoid.WalkSpeed=not focused and input:IsKeyDown(Enum.KeyCode.LeftShift) and 32 or 16
            ghostHumanoid:Move(focused and Vector3.zero or humanoid.MoveDirection,false)
        end
        animate()
        local destroyHeight=world.FallenPartsDestroyHeight
        if destroyHeight~=destroyHeight or math.abs(destroyHeight)==math.huge then destroyHeight=-500 end
        local position=ghostRoot.Position
        root.CFrame=CFrame.new(position.X,math.max(position.Y-settings.depth,destroyHeight+12),position.Z)
        root.AssemblyLinearVelocity,root.AssemblyAngularVelocity=Vector3.zero,Vector3.zero
    end
    card=context.framework.Categories.Utilities:CreateModule({Name="Ghost",Category="Utilities",Order=8,
        Tooltip="Your local ghost walks under gravity; Left Shift runs at 32. Ghost Fly explicitly enables flight.",Function=function(enabled)
            stop()
            if not enabled then return end
            local character=player.Character
            local humanoid,root=parts(character)
            if not humanoid or not root or humanoid.Health<=0 or not spawnGhost(character,root) then
                card:Notify("Ghost could not create a live character.");return
            end
            activity(true)
            table.insert(state.connections,run.PreSimulation:Connect(step))
            table.insert(state.connections,input.JumpRequest:Connect(function()
                if not settings.fly and state.humanoid and not input:GetFocusedTextBox()
                    and state.humanoid.FloorMaterial~=Enum.Material.Air then state.humanoid.Jump=true end
            end))
            step(0)
        end})
    card:CreateToggle({Name="Ghost Fly",Default=false,Function=function(value) settings.fly=value end,
        Tooltip="OFF: native walking, falling and jumping; Left Shift runs at 32. ON: WASD, Space up, Ctrl down."})
    card:CreateSlider({Name="Fly speed",Show={Option="Ghost Fly"},Min=1,Max=250,Default=55,Function=function(value) settings.speed=value end})
    card:CreateSlider({Name="Void depth",Min=50,Max=350,Default=120,Function=function(value) settings.depth=math.max(0,value) end})
    card:CreateSlider({Name="Ghost transparency",Min=0.1,Max=0.9,Step=0.05,Default=0.5,Function=function(value)
        settings.transparency=math.clamp(value,0,1)
        if state.model then for _,part in ipairs(state.model:GetDescendants()) do
            if part:IsA("BasePart") then part.Transparency=settings.transparency end
        end end
    end})
    cleanup=stop;Module.Initialized=true;return card
end
function Module.destroy()
    if cleanup then cleanup() end
    cleanup=nil;Module.Initialized=false
end
return Module

]],
        ["src/games/universal/Blatant/Jesus.lua"] = [[
export type Runtime = {framework: any, entity: any, host: any, services: any}

local Module = {Name = "Jesus", PlaceId = 0, Events = {} :: {[string]: any}, Initialized = false}
local activeCleanup

function Module.init(context: Runtime): any
    local host, framework = context.host, context.framework
    local player = host.LocalPlayer
    
    local settings = {
        mode = "Velocity",
        bounce = 0.5,
    }
    
    local jesus

    local function toggleJesus(enabled)
        if not enabled then
            return
        end
        
        jesus:Clean(host.RunService.PreSimulation:Connect(function(dt)
            local character = player.Character
            if not character then return end
            
            local root = character:FindFirstChild("HumanoidRootPart")
            local humanoid = character:FindFirstChild("Humanoid")
            if not root or not humanoid or humanoid.Health <= 0 then return end

            -- Raycast down to detect water
            local params = RaycastParams.new()
            params.FilterType = Enum.RaycastFilterType.Exclude
            params.FilterDescendantsInstances = {character}
            params.RespectCanCollide = false
            params.IgnoreWater = false

            local rayResult = workspace:Raycast(root.Position, Vector3.new(0, -10, 0), params)
            
            if rayResult and rayResult.Material == Enum.Material.Water then
                local waterSurface = rayResult.Position.Y
                
                -- Keep character on water surface
                if root.Position.Y < waterSurface + settings.bounce then
                    if settings.mode == "Velocity" then
                        root.AssemblyLinearVelocity = Vector3.new(
                            root.AssemblyLinearVelocity.X,
                            math.max(0, root.AssemblyLinearVelocity.Y),
                            root.AssemblyLinearVelocity.Z
                        )
                        root.CFrame = CFrame.new(root.Position.X, waterSurface + settings.bounce, root.Position.Z)
                    elseif settings.mode == "Impulse" then
                        local targetY = waterSurface + settings.bounce
                        local diff = targetY - root.Position.Y
                        if diff > 0.1 then
                            root:ApplyImpulse(Vector3.new(0, diff * 50, 0) * root.AssemblyMass)
                        end
                    else -- CFrame
                        root.CFrame = CFrame.new(root.Position.X, waterSurface + settings.bounce, root.Position.Z)
                    end
                end
            end
        end))
    end

    jesus = framework.Categories.Exploits:CreateModule({
        Name = "Jesus",
        Category = "Exploits",
        ConfigKey = "Universal.Jesus",
        Order = 4,
        Tooltip = "Walk on water by preventing you from sinking.",
        Function = function(enabled)
            if not enabled then
                jesus:SetStatus(nil)
                return
            end
            jesus:Clean(function() end)
            toggleJesus(true)
            jesus:SetStatus(settings.mode)
        end,
    })

    jesus:CreateDropdown({Name = "Mode", List = {"Velocity", "Impulse", "CFrame"}, Index = 1,
        Function = function(value)
            settings.mode = value
            if jesus.Enabled then jesus:SetStatus(value) end
        end,
        Tooltip = "Movement method: Velocity (smooth), Impulse (forces), or CFrame (direct position)."
    })
    
    jesus:CreateSlider({Name = "Bounce", Min = 0, Max = 2, Default = 0.5, Decimal = 1,
        Function = function(value)
            settings.bounce = value
        end,
        Tooltip = "How far above water surface to stay (in studs)."
    })

    activeCleanup = function()
        if jesus.Enabled then jesus:Toggle(false) end
    end
    
    Module.Initialized = true
    return jesus
end

function Module.destroy()
    if activeCleanup then activeCleanup(); activeCleanup = nil end
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Blatant/Noclip.lua"] = [[
export type Runtime = {
    framework: any,
    entity: any,
    host: any,
}

local Module = {
    Name = "Noclip",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local activeCleanup: (() -> ())? = nil

function Module.init(context: Runtime): any
    local host: any = context.host
    local LocalPlayer: any = host.LocalPlayer
    local TaskManager: any = host.TaskManager
    local featureConnections: any = host.featureConnections
    local disconnectFeatureConnection: any = host.disconnectFeatureConnection
    local createUniversalFeature: any = host.createUniversalFeature
    local addFeatureTooltip: any = host.addFeatureTooltip
    local toggleNoclip: (boolean) -> ()
    do
    local originalCollision = setmetatable({}, {__mode = "k"})

    local function restoreCollision()
        for part, canCollide in pairs(originalCollision) do
            if part and part.Parent then
                part.CanCollide = canCollide
            end
        end
        originalCollision = setmetatable({}, {__mode = "k"})
    end

    function toggleNoclip(enabled: boolean): ()
        disconnectFeatureConnection("Noclip")
        restoreCollision()

        if not enabled then
            return
        end

        featureConnections.Noclip = TaskManager:Connect(function()
            local character = LocalPlayer.Character
            if not character then
                return
            end

            for _, descendant in ipairs(character:GetDescendants()) do
                if descendant:IsA("BasePart") then
                    if originalCollision[descendant] == nil then
                        originalCollision[descendant] = descendant.CanCollide
                    end
                    descendant.CanCollide = false
                end
            end
        end)
    end
    end

    local NoclipFeature = createUniversalFeature(
        "Noclip",
        "Disable character collisions",
        11,
        toggleNoclip,
        {noOptions = true, categoryName = "Exploits"}
    )
    addFeatureTooltip(NoclipFeature, "Disables collisions for every local character part. "
        .. "Original collision states are restored when turned off.")

    activeCleanup = function(): ()

        toggleNoclip(false)
    end
    Module.Initialized = true
    return NoclipFeature
end

function Module.destroy(): ()
    if activeCleanup then
        pcall(activeCleanup)
    end
    activeCleanup = nil
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Blatant/Spider.lua"] = [[
export type Runtime = {
    framework: any,
    entity: any,
    host: any,
}

local Module = {
    Name = "Spider",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local activeCleanup: (() -> ())? = nil

function Module.init(context: Runtime): any
    local host: any = context.host
    local Players: any = host.Players
    local LocalPlayer: any = host.LocalPlayer
    local TaskManager: any = host.TaskManager
    local featureConnections: any = host.featureConnections
    local disconnectFeatureConnection: any = host.disconnectFeatureConnection
    local getCharacterParts: any = host.getCharacterParts
    local createUniversalFeature: any = host.createUniversalFeature
    local addToggleOption: any = host.addToggleOption
    local addNumberOption: any = host.addNumberOption
    local addCycleOption: any = host.addCycleOption
    local addFeatureTooltip: any = host.addFeatureTooltip
    local workspace: Workspace = host.workspace or workspace

    type SpiderSettings = {
        mode: string,
        speed: number,
        climbState: boolean,
        impulseInterval: number,
    }
    local spiderSettings: SpiderSettings = {
        mode = "Velocity",
        speed = 30,
        climbState = false,
        impulseInterval = 0.15,
    }
    local SpiderFeature: any = nil
    local climbingHumanoid: Humanoid? = nil
    local function releaseClimbState()
        local humanoid = climbingHumanoid
        climbingHumanoid = nil
        if humanoid and humanoid.Parent and humanoid.Health > 0 and humanoid:GetState() == Enum.HumanoidStateType.Climbing then
            humanoid:ChangeState(humanoid.FloorMaterial == Enum.Material.Air
                and Enum.HumanoidStateType.Freefall or Enum.HumanoidStateType.Running)
        end
    end

    local function toggleSpider(enabled: boolean): ()
        disconnectFeatureConnection("Spider")
        releaseClimbState()
        if not enabled then
            if SpiderFeature then
                SpiderFeature:SetStatus(nil)
            end

            return
        end

        SpiderFeature:SetStatus(spiderSettings.mode)

        local impulseElapsed: number = math.huge

        featureConnections.Spider = TaskManager:Connect(function(deltaTime: number): ()
            impulseElapsed += math.max(0, deltaTime)
            local character: Model?, humanoidOrNil: Humanoid?, rootOrNil: BasePart? =
                getCharacterParts()
            if not character or not humanoidOrNil or not rootOrNil or humanoidOrNil.Health <= 0
                or humanoidOrNil.Sit or rootOrNil.Anchored then
                releaseClimbState()
                return
            end
            if climbingHumanoid and climbingHumanoid ~= humanoidOrNil then releaseClimbState() end
            local humanoid: Humanoid = humanoidOrNil :: Humanoid
            local root: BasePart = rootOrNil :: BasePart

            local raycastParams: RaycastParams = RaycastParams.new()
            raycastParams.FilterType = Enum.RaycastFilterType.Exclude
            raycastParams.RespectCanCollide = true
            raycastParams.CollisionGroup = root.CollisionGroup
            local ignored: {Instance} = {character :: Instance}
            for _, player: Player in ipairs(Players:GetPlayers()) do
                if player ~= LocalPlayer and player.Character then
                    table.insert(ignored, player.Character :: Instance)
                end
            end
            raycastParams.FilterDescendantsInstances = ignored

            local hipHeight: number = humanoid.HipHeight > 0 and humanoid.HipHeight or 2.0
            local rootPos: Vector3 = root.Position
            local moveDir: Vector3 = humanoid.MoveDirection

            if moveDir.Magnitude < 0.05 then
                releaseClimbState()
                return
            end

            local origin: Vector3 = rootPos - Vector3.new(0, math.max(hipHeight - 0.5, 0), 0)
            local wall: RaycastResult? = workspace:Raycast(
                origin,
                moveDir.Unit * 2.5,
                raycastParams
            )
            local velocity: Vector3 = root.AssemblyLinearVelocity
            if not wall or math.abs((wall :: RaycastResult).Normal.Y) >= 0.35 then
                releaseClimbState()
                return
            end

            if moveDir:Dot(wall.Normal) > -0.1 then releaseClimbState();return end

            if spiderSettings.climbState then
                climbingHumanoid = humanoid
                humanoid:ChangeState(Enum.HumanoidStateType.Climbing)
            end

            if spiderSettings.mode == "CFrame" then
                root.AssemblyLinearVelocity = Vector3.new(velocity.X, 0, velocity.Z)
                local rise = Vector3.new(0, spiderSettings.speed * math.clamp(deltaTime, 0, 0.1), 0)
                local ceiling = workspace:Raycast(rootPos, rise + Vector3.new(0, hipHeight + 1, 0), raycastParams)
                if ceiling then rise = Vector3.new(0, math.max(0, ceiling.Distance - hipHeight - 1), 0) end
                root.CFrame = root.CFrame + rise
            elseif spiderSettings.mode == "Impulse" then
                -- Pulsed, mass-independent boost, not +speed every frame.
                -- The old integration accelerated indefinitely and depended on FPS.
                if impulseElapsed >= spiderSettings.impulseInterval then
                    impulseElapsed = 0
                    local deltaVelocity: number = math.max(0, spiderSettings.speed - velocity.Y)
                    if deltaVelocity > 0 then root:ApplyImpulse(Vector3.new(0, deltaVelocity, 0) * root.AssemblyMass) end
                end
            else
                root.AssemblyLinearVelocity = Vector3.new(velocity.X, spiderSettings.speed, velocity.Z)
            end
        end)
    end

    SpiderFeature = createUniversalFeature(
        "Spider",
        "Climb a wall while moving toward it",
        20,
        toggleSpider,
        {categoryName = "Exploits"}
    )
    local modeRows: {[string]: any} = {}
    local function refreshModeRows(): ()
        for name: string, row: any in pairs(modeRows) do
            local visible: boolean = name == "Impulse interval" and spiderSettings.mode == "Impulse"
            if host.setOptionVisible then host.setOptionVisible(SpiderFeature, row, visible)
            elseif row then row.Visible = visible end
        end
    end
    addCycleOption(
        SpiderFeature,
        "Mode",
        {"Velocity", "Impulse", "CFrame"},
        1,
        function(value: string): ()
            spiderSettings.mode = value
            refreshModeRows()
            if SpiderFeature.enabled then
                -- Restart the pulse timer on a mode change.
                toggleSpider(false)
                toggleSpider(true)
            end
        end,
        "Velocity: continuous climb. Impulse: timed upward boosts. CFrame: bounded vertical steps."
    )
    addNumberOption(
        SpiderFeature,
        "Climb speed",
        spiderSettings.speed,
        1,
        250,
        function(value: number): ()
            spiderSettings.speed = value
        end
    )
    addToggleOption(
        SpiderFeature,
        "Climb state",
        spiderSettings.climbState,
        function(value: boolean): ()
            spiderSettings.climbState = value
            if not value then releaseClimbState() end
        end,
        "Uses climbing state in classic modes (Velocity, Impulse, CFrame)."
    )
    local impulseRow: any = addNumberOption(SpiderFeature, "Impulse interval", spiderSettings.impulseInterval,
        0.05, 0.5, function(value: number): () spiderSettings.impulseInterval = value end,
        "Seconds between bounded upward impulses. Only used by Impulse mode.", 0.05)
    if impulseRow then modeRows["Impulse interval"] = impulseRow end
    refreshModeRows()
    addFeatureTooltip(
        SpiderFeature,
        "Climb only when pushing into a nearby vertical wall. No wall rotation or ceiling walking."
    )

    activeCleanup = function(): ()
        toggleSpider(false)
    end
    Module.Initialized = true
    return SpiderFeature
end

function Module.destroy(): ()
    if activeCleanup then
        pcall(activeCleanup)
    end
    activeCleanup = nil
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Blatant/Swim.lua"] = [[
export type Runtime = {framework: any, entity: any, host: any, services: any}

local Module = {Name = "Swim", PlaceId = 0, Events = {} :: {[string]: any}, Initialized = false}
local activeCleanup

function Module.init(context: Runtime): any
    local host, framework = context.host, context.framework
    local player = host.LocalPlayer
    
    local terrain = workspace:FindFirstChildWhichIsA("Terrain")
    local lastpos = nil
    
    local swim

    local function toggleSwim(enabled)
        if not enabled then
            -- Restore terrain when disabled
            if terrain and lastpos then
                pcall(function()
                    terrain:ReplaceMaterial(lastpos, 4, Enum.Material.Water, Enum.Material.Air)
                end)
                lastpos = nil
            end
            return
        end
        
        swim:Clean(host.RunService.PreSimulation:Connect(function(dt)
            local character = player.Character
            if not character then return end
            
            local root = character:FindFirstChild("HumanoidRootPart")
            local humanoid = character:FindFirstChild("Humanoid")
            if not root or not humanoid or humanoid.Health <= 0 then return end

            local moving = humanoid.MoveDirection ~= Vector3.zero
            local space = host.UserInputService:IsKeyDown(Enum.KeyCode.Space)

            if terrain then
                local factor = (moving or space) and Vector3.new(6, 6, 6) or Vector3.new(2, 1, 2)
                local pos = root.Position - Vector3.new(0, 1, 0)
                local newpos = Region3.new(pos - factor, pos + factor)
                
                -- Restore previous position
                if lastpos then
                    pcall(function()
                        terrain:ReplaceMaterial(lastpos, 4, Enum.Material.Water, Enum.Material.Air)
                    end)
                end
                
                -- Create water at new position
                pcall(function()
                    terrain:ReplaceMaterial(newpos, 4, Enum.Material.Air, Enum.Material.Water)
                end)
                
                lastpos = newpos
            end
        end))
    end

    swim = framework.Categories.Exploits:CreateModule({
        Name = "Swim",
        Category = "Exploits",
        ConfigKey = "Universal.Swim",
        Order = 3,
        Tooltip = "Lets you swim midair by converting terrain to water around your character.",
        Function = function(enabled)
            if not enabled then
                swim:SetStatus(nil)
                return
            end
            swim:Clean(function()
                if terrain and lastpos then
                    pcall(function()
                        terrain:ReplaceMaterial(lastpos, 4, Enum.Material.Water, Enum.Material.Air)
                    end)
                    lastpos = nil
                end
            end)
            toggleSwim(true)
            swim:SetStatus("Active")
        end,
    })

    activeCleanup = function()
        if swim.Enabled then swim:Toggle(false) end
        if terrain and lastpos then
            pcall(function()
                terrain:ReplaceMaterial(lastpos, 4, Enum.Material.Water, Enum.Material.Air)
            end)
            lastpos = nil
        end
    end
    
    Module.Initialized = true
    return swim
end

function Module.destroy()
    if activeCleanup then activeCleanup(); activeCleanup = nil end
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Combat/AimAssist.lua"] = [[
export type Runtime = {
    framework: any,
    entity: any,
    host: any,
    libraries: {[string]: any},
    services: any,
}

local Module = {
    Name = "AimAssist",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local activeCard: any = nil

function Module.init(context: Runtime): any
    local framework: any = context.framework
    local host: any = context.host
    local services: any = context.services
    local targeting: any = context.libraries and context.libraries.targeting
    local entity: any = context.entity
    local userInput: UserInputService = host.UserInputService
    local currentWorkspace: Workspace = host.workspace or workspace
    local runtime: any = {
        target = nil,
        lockedTarget = nil,
    }
    local card: any

    local function camera(): Camera?
        return currentWorkspace.CurrentCamera
    end

    local function moveCamera(target: any, deltaTime: number): boolean
        local cameraObject: Camera? = camera()
        if not cameraObject or not target then
            return false
        end
        local current: CFrame = cameraObject.CFrame
        local offset: Vector3 = target.position - current.Position
        if offset.Magnitude <= 0.001 then
            return false
        end

        local mode: string = card.Options["Mode"].Value
        local alpha: number = 1
        if mode ~= "Aimbot" then
            -- Speed caps turn rate; Strength controls the pull near the target.
            -- Both are time-based, rather than a frame-count smoothing factor.
            local dt = math.max(deltaTime, 0)
            local speed = math.max(0, card.Options.Speed.Value)
            local strength = math.max(0, card.Options.Strength.Value) / 100
            if speed == 0 or strength == 0 or dt == 0 then return false end
            local angle = math.acos(math.clamp(current.LookVector:Dot(offset.Unit), -1, 1))
            alpha = math.min(1 - math.exp(-strength * 10 * dt),
                angle > 1e-6 and math.rad(speed) * dt / angle or 1)
        end
        local currentLook: Vector3 = current.LookVector
        local blended: Vector3 = offset.Unit
        if alpha < 1 then
            local dot = math.clamp(currentLook:Dot(offset.Unit), -1, 1)
            local tangent = offset.Unit - currentLook * dot
            if tangent.Magnitude < 1e-6 then tangent = current.RightVector end
            local turn = math.acos(dot) * alpha
            blended = currentLook * math.cos(turn) + tangent.Unit * math.sin(turn)
        end
        if blended.Magnitude <= 0.001 then
            return false
        end
        cameraObject.CFrame = CFrame.lookAt(
            current.Position,
            current.Position + blended.Unit
        )
        return true
    end

    local function anotherAimAdapterIsActive(): boolean
        local activity: any = services and services.activity
        local free = services and services.freeCam
        local spectate = services and services.spectate
        if free and free.IsActive() or spectate and spectate.IsActive() then return true end
        return activity ~= nil
            and type(activity.isActive) == "function"
            and activity.isActive("mvsdSilentAim") == true
    end

    local function selectTarget(): any
        if anotherAimAdapterIsActive()
            or not targeting
            or type(targeting.List) ~= "function" then
            return nil
        end
        local options: any = card.Options
        local mode: string = options["Mode"].Value
        local candidates: {any} = targeting:List(entity, {

            FOV = mode == "Aim Assist" and options["FOV"].Value or nil,
            MaxDistance = options["Max distance"].Value,
            TargetPart = options["Target part"].Value,
            Prediction = options["Prediction"].Value,
            TeamCheck = options["Team check"].Value,
            VisibilityCheck = options["Visibility check"].Value,
            Priority = options["Priority"].Value,
            IncludeNPCs = options["Target NPCs"].Value,
            AllowOffscreen = mode == "Aimbot",
        })
        if mode ~= "Aimbot" then
            runtime.lockedTarget = nil
            return candidates[1]
        end
        if options["Sticky target"].Value and runtime.lockedTarget then
            for _, candidate: any in ipairs(candidates) do
                if candidate.entity == runtime.lockedTarget.entity then
                    runtime.lockedTarget = candidate
                    return candidate
                end
            end
        end
        runtime.lockedTarget = candidates[1]
        return runtime.lockedTarget
    end

    card = framework.Categories.Combat:CreateModule({
        Name = "Aim Assist",
        Category = "Combat",
        ConfigKey = "Universal.AimAssist",
        Order = 4,
        Tooltip = "Eases the local camera toward a valid target; no raycast or "
            .. "remote hooks.",
        Function = function(enabled: boolean): ()
            runtime.target = nil
            runtime.lockedTarget = nil
            if not enabled then
                card:SetStatus(nil)
                return
            end
            card:SetStatus("searching")
            card:Render(function(deltaTime: number): ()

                if anotherAimAdapterIsActive()
                    or services.menu.isVisible()
                    or services.menu.isCapturingInput() then
                    runtime.target = nil
                    runtime.lockedTarget = nil
                    card:SetStatus("paused")
                    return
                end
                if userInput:GetFocusedTextBox() then
                    runtime.target = nil
                    runtime.lockedTarget = nil
                    card:SetStatus("paused")
                    return
                end

                local selected: any = selectTarget()
                runtime.target = selected
                if not selected then
                    card:SetStatus("searching")
                    return
                end
                local moved: boolean = moveCamera(selected, deltaTime)
                local targetPlayer: Player? = selected.player
                local displayName: string = targetPlayer
                    and tostring(targetPlayer.DisplayName or targetPlayer.Name)
                    or tostring(selected.entity.Name or selected.character.Name)
                local distance: number = math.round(selected.distance)
                card:SetStatus(
                    displayName .. " · " .. tostring(distance) .. " studs"
                        .. (moved and " · locked" or " · ready")
                )
            end)
            card:Clean(function(): ()
                runtime.target = nil
                card:SetStatus(nil)
            end)
        end,
    })

    card:CreateDropdown({
        Name = "Mode",
        List = {"Aim Assist", "Aimbot"},
        Index = 1,
        Function = function(): ()
            runtime.lockedTarget = nil
        end,
        Tooltip = "Aim Assist uses Speed and Strength inside FOV. Aimbot snaps "
            .. "to a valid target and can keep a sticky lock.",
    })
    card:CreateSlider({
        Name = "FOV",
        Show = {Option = "Mode", Values = {"Aim Assist"}},
        Min = 15,
        Max = 500,
        Step = 5,
        Default = 180,
        Tooltip = "Pixels around the cursor in which a target may be selected.",
    })
    card:CreateSlider({Name="Speed",Min=0,Max=360,Default=180,Step=5,
        Show={Option="Mode",Values={"Aim Assist"}},
        Tooltip="Maximum camera turn in degrees per second. Higher = faster. 0 = no assist."})
    card:CreateSlider({Name="Strength",Min=0,Max=100,Default=75,Step=5,
        Show={Option="Mode",Values={"Aim Assist"}},
        Tooltip="Pull toward the target, in percent. Higher = firmer tracking; 0 = no assist. Aimbot snaps instead."})
    card:CreateDropdown({
        Name = "Target part",
        List = {"Closest", "Head", "Torso"},
        Index = 1,
        Tooltip = "Body part used as the camera target.",
    })
    card:CreateDropdown({
        Name = "Priority",
        List = {"Cursor", "Distance"},
        Index = 1,
        Tooltip = "Choose the target nearest the cursor or nearest in the world.",
    })
    card:CreateSlider({
        Name = "Prediction",
        Min = 0,
        Max = 0.5,
        Step = 0.01,
        Default = 0.06,
        Tooltip = "Seconds of target velocity to lead. Set to 0 for no lead.",
    })
    card:CreateSlider({
        Name = "Max distance",
        Min = 25,
        Max = 2000,
        Step = 5,
        Default = 600,
        Tooltip = "Ignore targets farther than this many studs.",
    })
    card:CreateToggle({
        Name = "Visibility check",
        Default = true,
        Tooltip = "Skip targets hidden by map geometry.",
    })
    card:CreateToggle({
        Name = "Team check",
        Default = true,
        Tooltip = "Skip teammates and Friend List entries.",
    })
    card:CreateToggle({
        Name = "Target NPCs",
        Default = false,
        Tooltip = "Include non-player humanoid models in both modes.",
    })
    card:CreateToggle({
        Name = "Sticky target",
        Show = {Option = "Mode", Values = {"Aimbot"}},
        Default = true,
        Function = function(value: boolean): ()
            if not value then
                runtime.lockedTarget = nil
            end
        end,
        Tooltip = "Hold the current Aimbot target. Turn off to release it and "
            .. "select a new target every frame.",
    })
    card:CreateNote(
        "Camera-only assist. It never edits remotes, raycasts or hitboxes."
    )

    activeCard = card
    Module.Initialized = true
    return card
end

function Module.destroy(): ()
    if activeCard and activeCard.Enabled then
        activeCard:Toggle(false)
    end
    activeCard = nil
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Combat/KillAura.lua"] = [[
export type Runtime = {
    framework: any,
    entity: any,
    host: any,
}

local Module = {
    Name = "KillAura",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local activeCleanup: (() -> ())? = nil

-- Ignore list: names, display names or user ids, separated by commas. It is
-- parsed outside the per-frame loop and applied to the entity list before any
-- rotation or swing, so an ignored player is never picked.
local function compileIgnoreList(text: string?): {[string]: boolean}
    local ignored: {[string]: boolean} = {}
    for name: string in string.gmatch(text or "", "[^,;%s]+") do
        ignored[string.lower(name)] = true
    end
    return ignored
end

local function isIgnoredEntity(entity: any, ignored: {[string]: boolean}): boolean
    local player: any = entity and entity.Player
    if not player then
        return false
    end
    return ignored[string.lower(player.Name or "")] == true
        or ignored[string.lower(player.DisplayName or "")] == true
        or ignored[tostring(player.UserId)] == true
end

local function collectTools(localPlayer: Player): {Tool}
    local tools: {Tool} = {}
    local character: Model? = localPlayer.Character
    if character then
        for _, child: Instance in ipairs(character:GetChildren()) do
            if child:IsA("Tool") then
                table.insert(tools, child :: Tool)
            end
        end
    end
    local backpack: Instance? = localPlayer:FindFirstChild("Backpack")
    if backpack then
        for _, child: Instance in ipairs(backpack:GetChildren()) do
            if child:IsA("Tool") then
                table.insert(tools, child :: Tool)
            end
        end
    end
    return tools
end

local function toolHandle(tool: Tool?): BasePart?
    if not tool then
        return nil
    end
    local resolved: Tool = tool :: Tool
    local handle: Instance? = resolved:FindFirstChild("Handle")
    if handle and handle:IsA("BasePart") then
        return handle :: BasePart
    end

    for _, descendant: Instance in ipairs(resolved:GetDescendants()) do
        if descendant:IsA("BasePart") then
            return descendant :: BasePart
        end
    end
    return nil
end

local function activateTool(tool: Tool?): ()
    if not tool then
        return
    end
    pcall(function(): ()
        tool:Activate()
    end)
end

local function fireContact(handle: BasePart?, target: BasePart): ()
    if not handle then
        return
    end
    local environment: any = getfenv()
    local fire: any = environment.firetouchinterest
    if type(fire) ~= "function" then
        return
    end

    pcall(fire, handle, target, 1)
    pcall(fire, handle, target, 0)
end

function Module.init(context: Runtime): any
    local host: any = context.host
    local framework: any = context.framework
    local entityLibrary: any = context.entity
    local localPlayer: Player = host.LocalPlayer
    local userInput: UserInputService = host.UserInputService
    local currentWorkspace: Workspace = host.workspace or workspace
    -- Advanced team check (always on): the entity library only knows team
    -- providers, so role-based verdicts (MM2 sides, for example) are applied
    -- as a post filter here.
    local teamCheck: any = host.state and host.state.teamCheck

    local nextSwingAt: number = 0
    local nextStatusAt: number = 0
    local highlights: {[any]: Highlight} = {}

    local function clearHighlights(keep: {[any]: boolean}?): ()
        for key: any, highlight: Highlight in pairs(highlights) do
            if not keep or not keep[key] then
                pcall(function(): ()
                    highlight:Destroy()
                end)
                highlights[key] = nil
            end
        end
    end

    local function markTarget(entity: any, options: any): ()
        if not options["Highlight targets"].Value then
            return
        end
        local key: any = entity.Player or entity.Character
        local existing: Highlight? = highlights[key]
        if not existing or not existing.Parent then
            local created: Highlight = Instance.new("Highlight")
            created.Name = "Wurst_KillAuraTarget"
            created.FillTransparency = 0.75
            created.Parent = entity.Character
            highlights[key] = created
            existing = created
        end
        local highlight: Highlight = existing :: Highlight
        highlight.Adornee = entity.Character
        highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
        local colour: Color3 = options["Highlight colour"].Value
        highlight.FillColor = colour
        highlight.OutlineColor = colour
    end

    local aura: any = nil
    local weapons: any = context.weapons

    local function updateTargetStatus(count: number): ()
        local now: number = os.clock()
        if now < nextStatusAt then
            return
        end
        nextStatusAt = now + 0.25
        aura:SetStatus(tostring(count) .. " in range")
    end

    local learnedWeapon: string? = nil
    local learnConnections: {RBXScriptConnection} = {}

    local function watchTool(tool: Tool): ()
        table.insert(
            learnConnections,
            tool.Activated:Connect(function(): ()
                learnedWeapon = tool.Name
            end)
        )
    end

    local function watchAllTools(): ()
        for _, connection: RBXScriptConnection in ipairs(learnConnections) do
            pcall(function(): ()
                connection:Disconnect()
            end)
        end
        learnConnections = {}
        for _, tool: Tool in ipairs(collectTools(localPlayer)) do
            watchTool(tool)
        end
    end

    local function matchesWanted(tool: Tool, wanted: string): boolean
        return string.find(string.lower(tool.Name), string.lower(wanted), 1, true) ~= nil
    end

    local function equippedTool(): (Tool?, BasePart?)
        local character: Model? = localPlayer.Character
        if not character then
            return nil, nil
        end
        local wanted: string = tostring(aura.Options["Weapon name"].Value or "")
        local held: {Tool} = {}
        for _, child: Instance in ipairs(character:GetChildren()) do
            if child:IsA("Tool") then
                table.insert(held, child :: Tool)
            end
        end

        if wanted ~= "" then
            for _, tool: Tool in ipairs(held) do
                if matchesWanted(tool, wanted) then
                    return tool, toolHandle(tool)
                end
            end
        end
        if learnedWeapon then
            for _, tool: Tool in ipairs(held) do
                if tool.Name == learnedWeapon then
                    return tool, toolHandle(tool)
                end
            end
        end
        local first: Tool? = held[1]
        return first, toolHandle(first)
    end

    local function equipFromBackpack(): ()
        local backpack: Instance? = localPlayer:FindFirstChild("Backpack")
        local humanoid: Humanoid? = localPlayer.Character
            and localPlayer.Character:FindFirstChildOfClass("Humanoid") :: Humanoid?
        if not backpack or not humanoid then
            return
        end
        local wanted: string = tostring(aura.Options["Weapon name"].Value or "")
        local chosen: Tool? = nil
        for _, child: Instance in ipairs(backpack:GetChildren()) do
            if not child:IsA("Tool") then
                continue
            end
            local tool: Tool = child :: Tool
            if wanted ~= "" and matchesWanted(tool, wanted) then
                chosen = tool
                break
            end
            if learnedWeapon and tool.Name == learnedWeapon then
                chosen = tool
                break
            end
            if not chosen then
                chosen = tool
            end
        end
        if chosen then
            pcall(function(): ()
                humanoid:EquipTool(chosen :: Tool)
            end)
        end
    end

    local store: any = host.configData
    if store and store.values then
        local reachKey: string = "Universal.KillAura.Reach"
        local stored: any = store.values["Universal.KillAura.Swingrange"]
        if store.values[reachKey] == nil and type(stored) == "number" then
            store.values[reachKey] = stored
            if type(host.queueConfigSave) == "function" then
                host.queueConfigSave()
            end
        end
    end

    aura = framework.Categories.Combat:CreateModule({
        Name = "KillAura",
        Category = "Combat",
        ConfigKey = "Universal.KillAura",
        Order = 1,
        Tooltip = "Swings your weapon at everyone in reach, with its own "
            .. "range, rate, field of view and rotation.",
        Function = function(enabled: boolean): ()
            if aura.CombatAdapter then
                clearHighlights()
                aura.CombatAdapter(enabled)
                return
            end
            nextSwingAt = 0
            nextStatusAt = 0
            if not enabled then
                aura:SetStatus(nil)
                clearHighlights()
                return
            end
            aura:SetStatus("0 in range")

            aura:Clean(function(): ()
                clearHighlights()
            end)

            watchAllTools()
            aura:Event(localPlayer.CharacterAdded, function(): ()
                task.defer(watchAllTools)
            end)
            local backpack: Instance? = localPlayer:FindFirstChild("Backpack")
            if backpack then
                aura:Event(backpack.ChildAdded, function(child: Instance): ()
                    if child:IsA("Tool") then
                        watchTool(child :: Tool)
                    end
                end)
            end
            aura:Clean(function(): ()
                for _, connection: RBXScriptConnection in ipairs(learnConnections) do
                    pcall(function(): ()
                        connection:Disconnect()
                    end)
                end
                learnConnections = {}
            end)

            aura:Loop(function(): ()
                local options: any = aura.Options
                if options["Activation"].Value == "Hold key"
                    and not userInput:IsKeyDown(options["Hold key"].Value) then
                    updateTargetStatus(0)
                    clearHighlights()
                    return
                end
                if not entityLibrary:IsAlive() then
                    updateTargetStatus(0)
                    clearHighlights()
                    return
                end

                local tool: Tool?, handle: BasePart? = equippedTool()
                if not tool then
                    if options["Auto equip"].Value then
                        equipFromBackpack()
                    end
                    if options["Require tool"].Value then

                        updateTargetStatus(0)
                        clearHighlights()
                        return
                    end
                end

                entityLibrary:Refresh()
                local targets: {any} = entityLibrary:InRange({
                    Range = options["Reach"].Value,
                    Limit = math.round(options["Max targets"].Value),
                    IgnoreTeam = not options["Team check"].Value,
                    IgnoreWalls = not options["Wall check"].Value,
                    Angle = options["Field of view"].Value,
                    IncludeNPCs = options["Target NPCs"].Value,
                    Sort = options["Priority"].Value,
                })
                if options["Team check"].Value and teamCheck then
                    local kept: {any} = {}
                    for _, entity: any in ipairs(targets) do
                        local teammate: boolean = false
                        if entity.Player
                            and type(teamCheck.isSameTeam) == "function" then
                            teammate = teamCheck.isSameTeam(entity.Player)
                        end
                        if not teammate then
                            table.insert(kept, entity)
                        end
                    end
                    targets = kept
                end
                local ignoreText: string = tostring(
                    options["Ignore players"].Value or ""
                )
                if ignoreText ~= "" then
                    local ignored: {[string]: boolean} = compileIgnoreList(ignoreText)
                    local kept: {any} = {}
                    for _, entity: any in ipairs(targets) do
                        if not isIgnoredEntity(entity, ignored) then
                            table.insert(kept, entity)
                        end
                    end
                    targets = kept
                end
                updateTargetStatus(#targets)
                if #targets == 0 then
                    clearHighlights()
                    return
                end
                local now: number = os.clock()
                local rate: number = math.max(options["Swings per second"].Value, 0.5)

                local jitter: number = 1 / rate * 0.25
                local canSwing: boolean = now >= nextSwingAt
                local keep: {[any]: boolean} = {}

                local root: BasePart? = entityLibrary.LocalEntity
                    and entityLibrary.LocalEntity.RootPart
                local rotation: string = options["Rotation"].Value
                local originalCFrame: CFrame? = root and root.CFrame or nil

                if canSwing then

                    nextSwingAt = now
                        + (1 / rate)
                        + (math.random() - 0.5) * 2 * jitter
                end

                if rotation ~= "Off" and root then
                    local first: any = targets[1]
                    local flat: Vector3 = first.RootPart.Position
                        * Vector3.new(1, 0, 1)
                    root.CFrame = CFrame.lookAt(
                        root.Position,
                        Vector3.new(flat.X, root.Position.Y + 0.01, flat.Z)
                    )
                end

                for _, entity: any in ipairs(targets) do
                    keep[entity.Player or entity.Character] = true
                    markTarget(entity, options)

                    if not canSwing then
                        continue
                    end

                    local swung: boolean = false
                    if weapons then
                        for _, label: string in ipairs(aura.Options["Weapons"].Selected or {}) do
                            local candidate: any = weapons:Find(label)
                            if candidate and weapons:Activate(candidate, entity) then
                                swung = true
                            end
                        end
                    end
                    if not swung and tool then
                        activateTool(tool)
                        swung = true
                    end
                    if not swung and weapons then

                        local fallback: any = weapons:Best({Melee = true})
                        swung = fallback ~= nil and weapons:Activate(fallback, entity)
                    end

                    local extraHits: number =
                        math.max(math.round(options["Hits per swing"].Value) - 1, 0)
                    for _ = 1, extraHits do
                        if tool then
                            activateTool(tool)
                        elseif weapons then
                            weapons:Swing()
                        end
                    end
                    if not options["Contact damage"].Value then

                        continue
                    end

                    if not options["Hit through walls"].Value
                        and not entityLibrary:VisibleFrom(entity) then
                        continue
                    end

                    local overlap: OverlapParams = OverlapParams.new()
                    overlap.FilterType = Enum.RaycastFilterType.Include
                    overlap.FilterDescendantsInstances = {entity.Character}
                    local parts: {BasePart} = currentWorkspace:GetPartBoundsInBox(
                        entity.RootPart.CFrame,
                        Vector3.new(5, 6, 5),
                        overlap
                    )
                    for _, part: BasePart in ipairs(parts) do
                        fireContact(handle, part)
                    end
                end

                if rotation == "Silent" and root and originalCFrame then
                    root.CFrame = originalCFrame :: CFrame
                end

                clearHighlights(keep)
            end)
        end,
    })

    aura:CreateDropdown({
        Name = "Activation",
        List = {"Always", "Hold key"},
        Index = 1,
    })
    aura:CreateBind({
        Name = "Hold key",
        Show = {Option = "Activation", Values = {"Hold key"}},
        Default = Enum.KeyCode.Unknown,
    })
    aura:CreateSlider({
        Name = "Reach",
        Min = 5,
        Max = 60,
        Default = 18,
        Tooltip = "Distance at which the weapon swings and its touch events "
            .. "fire. This is the only Kill Aura distance.",
    })
    aura:CreateSlider({
        Name = "Max targets",
        Min = 1,
        Max = 10,
        Default = 3,
        Tooltip = "How many valid players or NPCs one swing may hit. One "
            .. "sticks to the best target.",
    })
    aura:CreateDropdown({
        Name = "Priority",
        List = {"Distance", "Health", "Threat"},
        Index = 1,
        Tooltip = "Which target comes first: nearest, weakest, or the one "
            .. "most dangerous to you.",
    })
    aura:CreateSlider({
        Name = "Swings per second",
        Min = 1,
        Max = 20,
        Default = 8,
        Tooltip = "A fast human clicks about 8-12 times a second. Twenty is "
            .. "not a person, and a server that logs click rates knows it.",
    })

    aura:CreateSlider({
        Name = "Field of view",
        Min = 30,
        Max = 360,
        Default = 360,
        Tooltip = "Degrees around your character. 360 scans every direction; "
            .. "this is not cursor aim.",
    })
    aura:CreateDropdown({
        Name = "Rotation",
        List = {"Off", "Silent", "Face"},
        Index = 2,
        Tooltip = "Silent turns you for the swing only and puts you back; "
            .. "Face keeps you pointed at the target.",
    })
    aura:CreateSlider({
        Name = "Hits per swing",
        Min = 1,
        Max = 8,
        Default = 1,
        Tooltip = "How many times the weapon is pressed for each swing the "
            .. "rate allows. Some games count every press.",
    })
    aura:CreateList({
        Name = "Weapons",
        Items = function(): {string}
            if not weapons then
                return {}
            end
            return weapons:Labels({All = true, Melee = true})
        end,

        EmptyText = "",
        Tooltip = "Melee weapons this module may swing: tools, view models, "
            .. "inventory slots and the game's own attack button. Empty means "
            .. "whatever you are holding.",
    })
    aura:CreateTextBox({
        Name = "Weapon name",
        Default = "",
        Tooltip = "Part of the tool's name. Leave empty and the module uses "
            .. "whatever you last swung by hand.",
    })
    aura:CreateButton({
        Name = "Bind held tool",
        Tooltip = "Remembers whatever is in your hands right now.",
        Function = function(): ()
            local tool: Tool? = equippedTool()
            if not tool then
                aura:Notify("nothing equipped")
                return
            end
            learnedWeapon = (tool :: Tool).Name
            aura:SetStatus((tool :: Tool).Name .. " bound")
        end,
    })
    aura:CreateToggle({
        Name = "Auto equip",
        Default = false,
        Tooltip = "Pull the weapon out of the backpack when empty-handed. Off "
            .. "by default: most games this module helps in do not need "
            .. "anything in your hands at all.",
        Function = function(value: boolean): ()
            if weapons then
                weapons:SetAllowEquip(value)
            end
        end,
    })
    aura:CreateToggle({
        Name = "Require tool",
        Default = false,
        Tooltip = "Do nothing while your hands are empty.",
    })
    aura:CreateToggle({
        Name = "Team check",
        Default = true,
        Tooltip = "Skip teammates, analysed by the always-on advanced team "
            .. "check (game teams, roles, team colours, neutral rules), plus "
            .. "Friend List entries.",
    })
    aura:CreateToggle({
        Name = "Wall check",
        Default = false,
        Tooltip = "Off by default: the aura hits through walls and floors "
            .. "until you ask it not to.",
    })
    aura:CreateToggle({
        Name = "Contact damage",
        Default = true,
        Tooltip = "Also fire the weapon's touch events. Needed by most melee "
            .. "weapons; requires firetouchinterest.",
    })
    aura:CreateToggle({
        Name = "Hit through walls",
        Default = true,
        Tooltip = "Fire contact damage even when the target is behind "
            .. "geometry. Independent of the wall check, which decides "
            .. "whether the target is picked at all.",
    })
    aura:CreateToggle({
        Name = "Target NPCs",
        Default = false,
        Tooltip = "Include non-player humanoid models in the reach scan.",
    })
    aura:CreateTextBox({
        Name = "Ignore players",
        Default = "",
        Tooltip = "Names, display names or user ids, separated by commas. "
            .. "They are skipped by targeting: never picked, rotated to or hit.",
    })
    aura:CreateToggle({
        Name = "Highlight targets",
        Default = false,
    })
    aura:CreateColor({
        Name = "Highlight colour",
        Show = {Option = "Highlight targets"},
        Default = Color3.fromRGB(235, 110, 110),
    })

    aura:CreateNote(
        "Safe band: 8-12 swings a second and a reach close to the weapon's "
            .. "own. Reach is the only distance this card reads; there is no "
            .. "second, longer one. Friend List protects players from this "
            .. "module in every game."
    )

    activeCleanup = function(): ()
        clearHighlights()
    end
    Module.Initialized = true
    return aura
end

function Module.destroy(): ()
    if aura and aura.Enabled then
        pcall(function(): ()
            aura:Toggle(false)
        end)
    end
    if activeCleanup then
        pcall(activeCleanup)
    end
    activeCleanup = nil
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Combat/TargetStrafe.lua"] = [[
export type Runtime = {framework: any, entity: any, host: any, services: any}

local Module = {Name = "StrafeBot", PlaceId = 0, Events = {} :: {[string]: any}, Initialized = false}
local activeCleanup

function Module.init(context: Runtime): any
    local host, framework = context.host, context.framework
    local player = host.LocalPlayer
    local UserInputService = host.UserInputService or game:GetService("UserInputService")
    local RunService = host.RunService or game:GetService("RunService")
    
    local settings = {
        radius = 5,
        speed = 100,
        mode = "Circle",
        smartDodge = true,
    }
    
    local targetStrafe
    local lastTarget: Model? = nil

    local function getTarget(): Model?
        -- Find the nearest enemy within range using the targeting system
        local targeting = state.targeting
        if not targeting or type(targeting.getNearest) ~= "function" then
            return nil
        end
        local result = targeting.getNearest({
            maxDistance = 100,
            teamCheck = true,
            wallCheck = false,
            aliveOnly = true,
        })
        return result and result.character or nil
    end

    local function toggleTargetStrafe(enabled)
        if not enabled then
            lastTarget = nil
            return
        end
        
        targetStrafe:Clean(RunService.PreSimulation:Connect(function(dt)
            local character = player.Character
            if not character then return end
            
            local root = character:FindFirstChild("HumanoidRootPart")
            local humanoid = character:FindFirstChild("Humanoid")
            if not root or not humanoid or humanoid.Health <= 0 then return end

            local target = getTarget()
            if not target or not target.Parent then
                lastTarget = nil
                return
            end

            local targetRoot = target:FindFirstChild("HumanoidRootPart")
            if not targetRoot then return end

            lastTarget = target
            local targetPos = targetRoot.Position
            local myPos = root.Position
            
            -- Calculate vector from target to us
            local toMe = myPos - targetPos
            local horizontal = Vector3.new(toMe.X, 0, toMe.Z)
            
            if horizontal.Magnitude < 0.1 then
                -- We're on top of the target, pick a random direction
                horizontal = Vector3.new(1, 0, 0)
            end
            
            local distance = horizontal.Magnitude
            local direction = horizontal.Unit
            
            -- Strafe mode: move in a circle around the target
            local moveVector: Vector3
            if settings.mode == "Circle" then
                -- Perpendicular to the direction to target (circular motion)
                local perp = Vector3.new(-direction.Z, 0, direction.X)
                -- Adjust radius to maintain desired distance
                local radiusDiff = settings.radius - distance
                local radial = direction * radiusDiff * 2
                moveVector = perp * settings.speed + radial
            elseif settings.mode == "Figure8" then
                -- Figure-8 pattern for unpredictable movement
                local time = os.clock() * 2
                local perp = Vector3.new(-direction.Z, 0, direction.X)
                local figure8 = perp * math.sin(time) * settings.speed + direction * math.cos(time) * settings.speed * 0.5
                local radiusDiff = settings.radius - distance
                moveVector = figure8 + direction * radiusDiff * 2
            else -- ZigZag
                -- Zig-zag pattern
                local perp = Vector3.new(-direction.Z, 0, direction.X)
                local time = os.clock() * 3
                local zigzag = perp * (math.sign(math.sin(time)) * settings.speed)
                local radiusDiff = settings.radius - distance
                moveVector = zigzag + direction * radiusDiff * 2
            end
            
            -- Smart dodge: add random vertical movement to avoid predictable aim
            if settings.smartDodge then
                local state = humanoid:GetState()
                if state == Enum.HumanoidStateType.Freefall or state == Enum.HumanoidStateType.Jumping then
                    -- Add slight vertical variation while airborne
                    local vertical = Vector3.new(0, math.sin(os.clock() * 5) * 20, 0)
                    root.AssemblyLinearVelocity = Vector3.new(moveVector.X, root.AssemblyLinearVelocity.Y + vertical.Y, moveVector.Z)
                    return
                end
            end
            
            -- Apply horizontal movement, preserve vertical
            root.AssemblyLinearVelocity = Vector3.new(moveVector.X, root.AssemblyLinearVelocity.Y, moveVector.Z)
        end))
    end

    targetStrafe = framework.Categories.Combat:CreateModule({
        Name = "StrafeBot",
        Category = "Combat",
        ConfigKey = "Universal.TargetStrafe",
        Order = 4,
        Tooltip = "Automatically strafe around your target in circular, figure-8, or zig-zag patterns. Makes you much harder to hit in combat.",
        Function = function(enabled)
            if not enabled then
                targetStrafe:SetStatus(nil)
                return
            end
            targetStrafe:Clean(function() lastTarget = nil end)
            toggleTargetStrafe(true)
            targetStrafe:SetStatus(settings.mode)
        end,
    })

    targetStrafe:CreateDropdown({
        Name = "Mode",
        List = {"Circle", "Figure8", "ZigZag"},
        Index = 1,
        Function = function(value)
            settings.mode = value
            if targetStrafe.Enabled then targetStrafe:SetStatus(value) end
        end,
        Tooltip = "Circle = constant orbit; Figure8 = unpredictable loops; ZigZag = rapid direction changes."
    })
    
    targetStrafe:CreateSlider({
        Name = "Radius",
        Min = 2,
        Max = 20,
        Default = 5,
        Function = function(value)
            settings.radius = value
        end,
        Tooltip = "Distance to maintain from the target (in studs)."
    })
    
    targetStrafe:CreateSlider({
        Name = "Speed",
        Min = 1,
        Max = 250,
        Default = 100,
        Function = function(value)
            settings.speed = value
        end,
        Tooltip = "How fast to strafe around the target."
    })
    
    targetStrafe:CreateToggle({
        Name = "Smart dodge",
        Default = true,
        Tooltip = "Adds vertical movement variation while airborne to dodge aim."
    })

    activeCleanup = function()
        if targetStrafe.Enabled then targetStrafe:Toggle(false) end
    end
    
    Module.Initialized = true
    return targetStrafe
end

function Module.destroy()
    if activeCleanup then activeCleanup(); activeCleanup = nil end
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Combat/TriggerBot.lua"] = [[
export type Runtime = {
    framework: any,
    entity: any,
    host: any,
    services: any,
}

local Module = {
    Name = "TriggerBot",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local activeCard: any = nil
local activeCleanup: (() -> ())? = nil

function Module.init(context: Runtime): any
    local host: any = context.host
    local framework: any = context.framework
    local localPlayer: Player = host.LocalPlayer
    local playersService: Players = host.Players
    local currentWorkspace: Workspace = host.workspace or workspace
    local protectedTargets: any = context.services.protectedTargets
    local teamCheck: any = host.state and host.state.teamCheck

    local nextShotAt: number = 0

    local function pressMouseButton(): ()
        local environment: any = getfenv()
        local press: any = environment.mouse1press
        local release: any = environment.mouse1release
        if type(press) == "function" and type(release) == "function" then
            pcall(press)
            pcall(release)
            return
        end
        local ok: boolean, virtualInput: any = pcall(function(): any
            return game:GetService("VirtualInputManager")
        end)
        if not ok or type(virtualInput) ~= "table" then
            return
        end
        local camera: Camera? = currentWorkspace.CurrentCamera
        local viewport: Vector2 = camera
            and camera.ViewportSize
            or Vector2.new(0, 0)
        local x: number = viewport.X / 2
        local y: number = viewport.Y / 2
        pcall(function(): ()
            (virtualInput :: any):SendMouseButtonEvent(x, y, 0, true, game, 0)
        end)
        pcall(function(): ()
            (virtualInput :: any):SendMouseButtonEvent(x, y, 0, false, game, 0)
        end)
    end

    local function characterOf(part: BasePart): Model?
        local current: Instance? = part
        while current and current ~= currentWorkspace do
            if current:IsA("Model") then
                local humanoid: Humanoid? =
                    (current :: Model):FindFirstChildOfClass("Humanoid")
                    :: Humanoid?
                if humanoid then
                    return current :: Model
                end
            end
            current = current.Parent
        end
        return nil
    end

    local trigger: any = nil

    trigger = framework.Categories.Combat:CreateModule({
        Name = "TriggerBot",
        Category = "Combat",
        ConfigKey = "Universal.TriggerBot",
        Order = 2,
        Tooltip = "Fires your weapon the instant the crosshair rests on a "
            .. "valid enemy. Uses the always-on team check.",
        Function = function(enabled: boolean): ()
            if not enabled then
                trigger:SetStatus(nil)
                return
            end
            nextShotAt = 0
            trigger:SetStatus("armed")

            trigger:Render(function(): ()
                local camera: Camera? = currentWorkspace.CurrentCamera
                if not camera then
                    return
                end
                local now: number = os.clock()
                if now < nextShotAt then
                    return
                end

                local options: any = trigger.Options
                local range: number = options["Range"].Value
                local viewport: Vector2 = camera.ViewportSize
                local ray: Ray = camera:ViewportPointToRay(
                    viewport.X / 2,
                    viewport.Y / 2
                )
                local parameters: RaycastParams = RaycastParams.new()
                parameters.FilterType = Enum.RaycastFilterType.Exclude
                parameters.IgnoreWater = true
                local exclude: {Instance} = {}
                if localPlayer.Character then
                    table.insert(exclude, localPlayer.Character :: Instance)
                end
                parameters.FilterDescendantsInstances = exclude

                local hit: RaycastResult? = currentWorkspace:Raycast(
                    ray.Origin,
                    ray.Direction * range,
                    parameters
                )
                if not hit then
                    trigger:SetStatus("armed")
                    return
                end
                local character: Model? = characterOf((hit :: RaycastResult).Instance :: BasePart)
                if not character then
                    trigger:SetStatus("armed")
                    return
                end
                local player: Player? =
                    playersService:GetPlayerFromCharacter(character :: Model)
                if not player or player == localPlayer then
                    trigger:SetStatus("armed")
                    return
                end
                local humanoid: Humanoid? =
                    (character :: Model):FindFirstChildOfClass("Humanoid")
                    :: Humanoid?
                if not humanoid or (humanoid :: Humanoid).Health <= 0 then
                    return
                end
                if protectedTargets and protectedTargets.isProtected(player) then
                    return
                end

                -- X2 owns one shared native path per weapon instead of
                -- registering a second TriggerBot card/loop.
                local x2Core: any = host.state and host.state.x2duelsCore
                if x2Core and type(x2Core.isEnemy) == "function"
                    and type(x2Core.fireGun) == "function"
                    and type(x2Core.fireKnife) == "function" then
                    if not x2Core.isEnemy(player, options["Teammates"].Value) then
                        trigger:SetStatus("not opponent")
                        return
                    end
                    local tool: Tool? = x2Core.equippedTool()
                    local kind: string? = x2Core.toolKind(tool)
                    if kind ~= "Gun" and kind ~= "Knife" then
                        trigger:SetStatus("equip gun/knife")
                        return
                    end
                    local target: any = x2Core.targetFor(player)
                    if not target then
                        trigger:SetStatus("no target")
                        return
                    end
                    nextShotAt = now + options["Delay"].Value
                    local fired: boolean = false
                    if kind == "Gun" then
                        fired = x2Core.fireGun(target)
                    else
                        fired = x2Core.fireKnife(target)
                    end
                    trigger:SetStatus(
                        fired and (kind == "Knife" and "throw queued" or "fired gun")
                            or "cooldown"
                    )
                    return
                end

                -- Advanced team check (always on): never fire at a teammate.
                if not options["Teammates"].Value then
                    local friendly: boolean = false
                    if teamCheck and type(teamCheck.isSameTeam) == "function" then
                        friendly = teamCheck.isSameTeam(player)
                    end
                    if friendly then
                        trigger:SetStatus("teammate")
                        return
                    end
                end

                nextShotAt = now + options["Delay"].Value
                pressMouseButton()
                trigger:SetStatus("fired")
            end)
        end,
    })

    trigger:CreateSlider({
        Name = "Range",
        Min = 25,
        Max = 2000,
        Step = 25,
        Default = 500,
        Tooltip = "How far the crosshair ray searches for a target.",
    })
    trigger:CreateSlider({
        Name = "Delay",
        Min = 0.05,
        Max = 1,
        Step = 0.05,
        Default = 0.15,
        Tooltip = "Seconds between automatic shots.",
    })
    trigger:CreateToggle({
        Name = "Teammates",
        Default = false,
        Tooltip = "Also fire at teammates. The advanced team check protects "
            .. "them while this is off.",
    })
    trigger:CreateNote(
        "Fires when the crosshair is over an enemy; it never aims for you. "
            .. "X2 Duels uses native Gun/Knife Tool activation. Other games "
            .. "use mouse1press or VirtualInputManager as before."
    )

    activeCard = trigger
    activeCleanup = function(): () end
    Module.Initialized = true
    return trigger
end

function Module.destroy(): ()
    if activeCard and activeCard.Enabled then
        pcall(function(): ()
            activeCard:Toggle(false)
        end)
    end
    if activeCleanup then
        pcall(activeCleanup)
    end
    activeCleanup = nil
    activeCard = nil
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Movement/AirWalk.lua"] = [[
export type Runtime = {
    framework: any,
    entity: any,
    host: any,
    services: any,
}

local Module = {
    Name = "AirWalk",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local activeCleanup: (() -> ())? = nil

function Module.init(context: Runtime): any
    local host: any = context.host
    local framework: any = context.framework
    local LocalPlayer: Player = host.LocalPlayer
    local UserInputService: UserInputService = host.UserInputService
    local RunService: RunService = host.RunService
    local world: Workspace = host.workspace or workspace
    local create: any = host.create

    local platform: Part? = nil
    local gui: Frame? = nil
    local airY: number? = nil
    local trackedCharacter: Model? = nil
    local connections: {RBXScriptConnection} = {}
    local held: {[string]: {[any]: boolean}} = {
        Up = {},
        Down = {},
    }

    local VERTICAL_SPEED: number = 22

    local function characterParts(): (Model?, Humanoid?, BasePart?)
        local character: Model? = LocalPlayer and LocalPlayer.Character
        if not character then
            return nil, nil, nil
        end
        local humanoid: Humanoid? = character:FindFirstChildOfClass("Humanoid") :: Humanoid?
        local root: BasePart? = character:FindFirstChild("HumanoidRootPart") :: BasePart?
        return character, humanoid, root
    end

    local function footOffsetOf(humanoid: Humanoid, root: BasePart): number
        local hip: number = humanoid.HipHeight or 2
        if hip <= 0 then
            hip = 2
        end
        local rootHalfY: number = 1
        pcall(function(): ()
            rootHalfY = root.Size.Y * 0.5
        end)
        return hip + rootHalfY + 0.5
    end

    local function destroyPlatform(): ()
        if platform then
            pcall(function(): ()
                platform:Destroy()
            end)
            platform = nil
        end
    end

    local function destroyGui(): ()
        if gui then
            pcall(function(): ()
                gui:Destroy()
            end)
            gui = nil
        end
    end

    local function clearConnections(): ()
        for _, conn: RBXScriptConnection in ipairs(connections) do
            pcall(function(): ()
                conn:Disconnect()
            end)
        end
        table.clear(connections)
        table.clear(held.Up)
        table.clear(held.Down)
    end

    local function setHold(direction: string, source: any, isDown: boolean): ()
        local bucket: {[any]: boolean}? = held[direction]
        if not bucket then
            return
        end
        bucket[source] = isDown and true or nil
    end

    local function isDirectionHeld(direction: string): boolean
        local bucket: {[any]: boolean}? = held[direction]
        return bucket ~= nil and next(bucket) ~= nil
    end

    local function ensurePlatform(): Part?
        if platform and platform.Parent then
            return platform
        end
        local ok: boolean, created: any = pcall(function(): any
            local p: Part = Instance.new("Part")
            p.Name = "Wurst_AirWalkPlatform"
            p.Anchored = true
            p.CanCollide = true
            p.CanQuery = false
            p.CanTouch = false
            p.CastShadow = false
            p.Size = Vector3.new(16, 1, 16)
            p.Transparency = 1
            p.Parent = world
            return p
        end)
        if ok and created then
            platform = created :: Part
            return platform
        end
        return nil
    end

    local airWalk: any
    airWalk = framework.Categories.Exploits:CreateModule({
        Name = "AirWalk",
        Category = "Exploits",
        ConfigKey = "Universal.AirWalk",
        Order = 11,
        Tooltip = "Stay in the air with every jump and walk in mid-air. Space to go up, Shift to go down, with mobile Up/Down buttons.",
        Function = function(enabled: boolean): ()
            clearConnections()
            destroyGui()
            destroyPlatform()
            airY = nil
            trackedCharacter = nil

            if not enabled then
                airWalk:SetStatus(nil)
                return
            end

            airWalk:SetStatus("Active")

            local function connect(signal: any, callback: any): ()
                if signal and type(signal.Connect) == "function" then
                    table.insert(connections, signal:Connect(callback))
                end
            end

            connect(UserInputService.InputBegan, function(event: InputObject, processed: boolean): ()
                if processed or UserInputService:GetFocusedTextBox() then
                    return
                end
                if event.UserInputType == Enum.UserInputType.Keyboard then
                    if event.KeyCode == Enum.KeyCode.Space then
                        setHold("Up", "Space", true)
                    elseif event.KeyCode == Enum.KeyCode.LeftShift
                        or event.KeyCode == Enum.KeyCode.RightShift then
                        setHold("Down", event.KeyCode, true)
                    end
                end
            end)

            connect(UserInputService.InputEnded, function(event: InputObject): ()
                if event.UserInputType == Enum.UserInputType.Keyboard then
                    if event.KeyCode == Enum.KeyCode.Space then
                        setHold("Up", "Space", false)
                    elseif event.KeyCode == Enum.KeyCode.LeftShift
                        or event.KeyCode == Enum.KeyCode.RightShift then
                        setHold("Down", event.KeyCode, false)
                    end
                elseif event.UserInputType == Enum.UserInputType.Touch then
                    setHold("Up", event, false)
                    setHold("Down", event, false)
                end
            end)

            if UserInputService.WindowFocusReleased then
                connect(UserInputService.WindowFocusReleased, function(): ()
                    table.clear(held.Up)
                    table.clear(held.Down)
                end)
            end
            if UserInputService.TextBoxFocused then
                connect(UserInputService.TextBoxFocused, function(): ()
                    table.clear(held.Up)
                    table.clear(held.Down)
                end)
            end

            if UserInputService.TouchEnabled and type(create) == "function" and host.ScreenGui then
                gui = create("Frame", {
                    Name = "AirWalkControls",
                    Parent = host.ScreenGui,
                    Size = UDim2.fromScale(1, 1),
                    BackgroundTransparency = 1,
                    ZIndex = 30,
                })
                local function makeMobileButton(name: string, text: string, at: UDim2, size: UDim2): any
                    local object: any = create("TextButton", {
                        Name = name,
                        Parent = gui,
                        Position = at,
                        Size = size,
                        Text = text,
                        Font = Enum.Font.Code,
                        TextSize = 18,
                        TextColor3 = Color3.new(1, 1, 1),
                        BackgroundColor3 = Color3.fromRGB(25, 25, 25),
                        BackgroundTransparency = 0.3,
                        BorderSizePixel = 1,
                        BorderColor3 = Color3.fromRGB(120, 120, 120),
                        AutoButtonColor = true,
                        ZIndex = 31,
                    })
                    if host.ThemeEngine then
                        host.ThemeEngine.Bind(object, "BackgroundColor3", "background")
                        host.ThemeEngine.Bind(object, "TextColor3", "text")
                    end
                    return object
                end

                for _, name: string in ipairs({"Up", "Down"}) do
                    local btn: any = makeMobileButton(
                        name,
                        if name == "Up" then "+" else "−",
                        UDim2.new(1, -70, 1, if name == "Up" then -152 else -96),
                        UDim2.fromOffset(48, 48)
                    )
                    connect(btn.InputBegan, function(event: InputObject): ()
                        if event.UserInputType == Enum.UserInputType.Touch
                            or event.UserInputType == Enum.UserInputType.MouseButton1 then
                            setHold(name, event, true)
                        end
                    end)
                    connect(btn.InputEnded, function(event: InputObject): ()
                        if event.UserInputType == Enum.UserInputType.Touch
                            or event.UserInputType == Enum.UserInputType.MouseButton1 then
                            setHold(name, event, false)
                        end
                    end)
                end
            end

            connect(RunService.Heartbeat, function(dt: number): ()
                local character: Model?, humanoid: Humanoid?, root: BasePart? = characterParts()
                if not character or not humanoid or not root or humanoid.Health <= 0 then
                    destroyPlatform()
                    airY = nil
                    trackedCharacter = nil
                    return
                end

                local stepDt: number = if type(dt) == "number" and dt > 0 and dt < 0.5 then dt else (1 / 60)
                local offset: number = footOffsetOf(humanoid, root)
                local currentFootY: number = root.Position.Y - offset

                if trackedCharacter ~= character or airY == nil then
                    trackedCharacter = character
                    airY = currentFootY
                end

                local keyUp: boolean = false
                local keyDown: boolean = false
                if not UserInputService:GetFocusedTextBox()
                    and type(UserInputService.IsKeyDown) == "function" then
                    pcall(function(): ()
                        keyUp = UserInputService:IsKeyDown(Enum.KeyCode.Space)
                        keyDown = UserInputService:IsKeyDown(Enum.KeyCode.LeftShift)
                            or UserInputService:IsKeyDown(Enum.KeyCode.RightShift)
                    end)
                end

                local goingUp: boolean = keyUp or isDirectionHeld("Up")
                local goingDown: boolean = keyDown or isDirectionHeld("Down")

                local part: Part? = ensurePlatform()

                if goingDown and not goingUp then
                    airY = currentFootY - VERTICAL_SPEED * stepDt - 1.4
                    if part then
                        pcall(function(): ()
                            part.CanCollide = true
                            part.CFrame = CFrame.new(root.Position.X, airY :: number, root.Position.Z)
                        end)
                    end
                    pcall(function(): ()
                        local vel: Vector3 = root.AssemblyLinearVelocity
                        if vel.Y > -VERTICAL_SPEED then
                            root.AssemblyLinearVelocity = Vector3.new(vel.X, -VERTICAL_SPEED, vel.Z)
                        end
                    end)
                elseif goingUp and not goingDown then
                    airY = math.max(airY :: number, currentFootY) + VERTICAL_SPEED * stepDt
                    if part then
                        pcall(function(): ()
                            part.CanCollide = true
                            part.CFrame = CFrame.new(root.Position.X, airY :: number, root.Position.Z)
                        end)
                    end
                    pcall(function(): ()
                        local vel: Vector3 = root.AssemblyLinearVelocity
                        if vel.Y < VERTICAL_SPEED then
                            root.AssemblyLinearVelocity = Vector3.new(vel.X, VERTICAL_SPEED, vel.Z)
                        end
                    end)
                else
                    -- Lock to the highest point reached on any jump so each
                    -- jump leaves the player walking in mid-air at that height.
                    if currentFootY > (airY :: number) then
                        airY = currentFootY
                    end
                    if part then
                        pcall(function(): ()
                            part.CanCollide = true
                            part.CFrame = CFrame.new(root.Position.X, airY :: number, root.Position.Z)
                        end)
                    end
                end
            end)

            airWalk:Clean(function(): ()
                clearConnections()
                destroyGui()
                destroyPlatform()
                airY = nil
                trackedCharacter = nil
            end)
        end,
    })

    activeCleanup = function(): ()
        clearConnections()
        destroyGui()
        destroyPlatform()
        if airWalk and airWalk.Enabled then
            airWalk:Toggle(false)
        end
    end

    Module.Initialized = true
    return airWalk
end

function Module.destroy(): ()
    if activeCleanup then
        pcall(activeCleanup)
    end
    activeCleanup = nil
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Movement/AntiVoid.lua"] = [[
-- Rescue actual void falls, not ordinary jumps or long drops onto lower ground.
local Module={Name="AntiVoid",PlaceId=0,Initialized=false}
local cleanup
function Module.init(context)
    local host, world = context.host, context.host.workspace
    local antiFling, voidGuard, platform, token = false, false, nil, 0
    local previousCharacter, previousRoot, previousVelocity, overSpeedTicks
    -- Fixed physical thresholds, measured against what the body itself can
    -- produce. There is no user-facing velocity limit any more: a single
    -- number has to be retuned per game and per speed setting, and when it
    -- was wrong the protection silently did nothing.
    local SPIN_LIMIT = 20      -- rad/s: a driven spin, not a turn
    local SPEED_FACTOR = 2.2   -- multiples of the character's walking speed
    local JUMP_FACTOR = 3      -- multiples of JumpPower no jump can reach
    local function removePlatform()
        token+=1
        if platform then platform:Destroy();platform=nil end
    end
    local function active(name)
        return context.services.activity and context.services.activity.isActive(name)
    end
    local function module(name)
        return context.framework and context.framework.GetModule and context.framework:GetModule(name)
    end
    local function motionLimits(humanoid)
        local walk=math.max(16,humanoid.WalkSpeed or 16)
        local feature=module("Speed")
        if feature and feature.Enabled and feature.Options and feature.Options.Speed then
            walk=math.max(walk,feature.Options.Speed.Value)
        end
        return walk,math.max(50,humanoid.JumpPower or 50)
    end
    local function step(dt)
        local character,humanoid,root=host.getCharacterParts()
        if not humanoid or not root or humanoid.Health<=0 then return end
        local velocity=root.AssemblyLinearVelocity
        local planar=Vector3.new(velocity.X,0,velocity.Z)
        if previousCharacter~=character or previousRoot~=root then
            previousCharacter,previousRoot,previousVelocity,overSpeedTicks=character,root,velocity,0
            removePlatform()
        end
        local fly=module("Fly")
        local busy=root.Anchored or humanoid.Sit or humanoid.SeatPart or active("fling")
            or active("ghost") or active("teleport") or fly and fly.Enabled
        if antiFling and not busy then
            -- Everything is compared to the body's own mobility, so a fast
            -- walk or an intentional Speed never reads as a fling, and no
            -- slider has to match it.
            local walk,jump=motionLimits(humanoid)
            local limit=walk*SPEED_FACTOR
            local spin=root.AssemblyAngularVelocity.Magnitude>SPIN_LIMIT
            local rise=velocity.Y>jump*JUMP_FACTOR
            local delta=previousVelocity and (velocity-previousVelocity) or Vector3.zero
            local kick=math.max(planar.Magnitude,Vector3.new(delta.X,0,delta.Z).Magnitude)
            if planar.Magnitude>limit then overSpeedTicks=(overSpeedTicks or 0)+1 else overSpeedTicks=0 end
            -- Four signatures, any one of them enough: a driven spin, a rise
            -- no jump can produce, a single-frame planar spike, and a shove
            -- held over several frames (contact flings accelerate instead of
            -- jumping in one tick). Proximity is not one of them: a fling
            -- sent through a tool or a remote arrives from any distance, and
            -- the old 10-stud gate is why it used to need several attempts.
            if spin or rise or kick>limit or overSpeedTicks>=2 then
                -- Remove the impulse, never the position or the input.
                local desired=humanoid.MoveDirection*walk
                local lifted=rise or spin
                root.AssemblyLinearVelocity=Vector3.new(desired.X,
                    lifted and math.min(velocity.Y,jump) or velocity.Y,desired.Z)
                root.AssemblyAngularVelocity=Vector3.zero
                velocity=root.AssemblyLinearVelocity
                planar=Vector3.new(desired.X,0,desired.Z)
                overSpeedTicks=0
            end
        end
        previousVelocity=velocity
        if not voidGuard then return end
        if humanoid.FloorMaterial~=Enum.Material.Air or velocity.Y>=0 or platform then return end
        local destroyHeight=world.FallenPartsDestroyHeight
        if destroyHeight~=destroyHeight or math.abs(destroyHeight)==math.huge then destroyHeight=-500 end
        local distance=root.Position.Y-destroyHeight
        if distance>math.max(20,-velocity.Y*0.25) then return end
        local params=RaycastParams.new()
        params.FilterType=Enum.RaycastFilterType.Exclude
        params.FilterDescendantsInstances={character}
        params.RespectCanCollide=true;params.IgnoreWater=false
        if root.CollisionGroup then params.CollisionGroup=root.CollisionGroup end
        -- A real floor before the destroy layer means this is a legitimate drop.
        local hit=world:Raycast(root.Position,Vector3.new(0,-math.clamp(distance,1,15000),0),params)
        if hit and hit.Position.Y>destroyHeight+2 then return end
        local rescue=Instance.new("Part")
        rescue.Name="Wurst_AntiVoidPlatform";rescue.Anchored=true;rescue.CanCollide=true
        rescue.CanQuery=false;rescue.CanTouch=false;rescue.CastShadow=false
        rescue.Size=Vector3.new(42,1,42);rescue.Transparency=1
        rescue.CFrame=CFrame.new(root.Position-Vector3.new(0,4.25,0));rescue.Parent=world
        platform=rescue
        root.AssemblyLinearVelocity=Vector3.new(velocity.X,0,velocity.Z)
        root.AssemblyAngularVelocity=Vector3.zero
        token+=1;local mine=token
        task.delay(3,function() if mine==token then removePlatform() end end)
    end
    -- Anti fling owns its connection: it protects with Anti Void off, and
    -- Anti Void keeps the rescue without ever turning the damping off.
    local function refresh()
        host.disconnectFeatureConnection("AntiVoid")
        if not antiFling then overSpeedTicks=0 end
        if voidGuard or antiFling then
            host.featureConnections.AntiVoid=host.TaskManager:Connect(step)
        end
    end
    local feature=host.createUniversalFeature("Anti Void","Rescue imminent falls into the destroy layer, not normal drops",4,function(enabled)
        voidGuard=enabled
        removePlatform()
        previousCharacter,previousRoot,previousVelocity,overSpeedTicks=nil,nil,nil,0
        refresh()
    end,{categoryName="Utilities"})
    host.addToggleOption(feature,"Anti fling",false,function(value) antiFling=value;refresh() end,
        "Cancels a fling on contact: driven spin, impossible rise, single-frame shove or a sustained one, all measured against your own walk and jump. Works without Anti Void.")
    host.addFeatureTooltip(feature,"Only rescues a falling character near the void when there is no collidable floor below. Anti fling never teleports you back and keeps your input.")
    cleanup=function() host.disconnectFeatureConnection("AntiVoid");removePlatform() end
    Module.Initialized=true;return feature
end
function Module.destroy()
    if cleanup then cleanup() end
    cleanup=nil;Module.Initialized=false
end
return Module

]],
        ["src/games/universal/Movement/ClickTeleport.lua"] = [[
export type Runtime = {
    framework: any,
    entity: any,
    host: any,
    services: any,
}

local Module = {
    Name = "ClickTeleport",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local activeCleanup: (() -> ())? = nil

local function characterRoot(localPlayer: Player): (BasePart?, Humanoid?)
    local character: Model? = localPlayer.Character
    if not character then
        return nil, nil
    end
    return character:FindFirstChild("HumanoidRootPart") :: BasePart?,
        character:FindFirstChildOfClass("Humanoid") :: Humanoid?
end

function Module.init(context: Runtime): any
    local host: any = context.host
    local framework: any = context.framework
    local localPlayer: Player = host.LocalPlayer
    local userInput: UserInputService = host.UserInputService
    local menu: any = context.services.menu

    local runtime: any = {
        armedUntil = 0,
        point = nil :: string?,
        lastOrigin = nil :: Vector3?,
    }

    local teleport: any
    teleport = framework.Categories.Utilities:CreateModule({
        Name = "Teleport",
        ConfigKey = "Universal.ClickTeleport",
        Category = "Utilities",
        Order = 1,

        Kind = "action",
        Silent = true,
        Tooltip = "Press to travel to the destination selected below.",
        Function = function(): ()
            Module.run(context, teleport, runtime)
        end,
    })

    local destinations = {"Tap point", "Nearest player", "Named player", "Item", "Waypoint", "Last position"}
    if host.GAME_CHECK and host.GAME_CHECK.MM2Active then
        table.insert(destinations, 1, "MM2")
        local config = host.configData
        if config then
            local key = "Universal.ClickTeleport.Destination"
            if config.values[key] == nil or string.sub(tostring(config.values[key]), 1, 4) == "MM2 " then
                config.values[key] = "MM2"
            end
        end
    end
    teleport:CreateDropdown({Name = "Destination", List = destinations, Index = 1,
        Tooltip = "MM2 shows all game teleport buttons together. Other destinations use the main action.",
        Function = function(value)
            runtime.armedUntil = 0
            if runtime.cancelTravel then runtime.cancelTravel() end
            local mm2Controls = { ["Teleport to Map"] = true, ["Teleport to Lobby"] = true,
                ["Teleport to Player"] = true, ["Get Gun"] = true, ["Player name"] = true,
                ["Get Gun key"] = true, ["Auto Get Gun"] = true }
            teleport.OptionFilter = function(name)
                if name == "Destination" then return true end
                return value == "MM2" and mm2Controls[name] == true or value ~= "MM2" and not mm2Controls[name]
            end
            teleport:RefreshVisibility()
        end})
    teleport:CreateTextBox({
        Name = "Player",
        Show = {Option = "Destination", Values = {"Named player"}},
        Default = "",
        Tooltip = "Part of a name or display name, for Named player.",
    })
    teleport:CreateTextBox({
        Name = "Item",
        Show = {Option = "Destination", Values = {"Item"}},
        Default = "",
        Tooltip = "Part or model name to look for, for Item. Partial names "
            .. "match, so \"chest\" finds \"GoldChest\".",
    })
    local pointList=teleport:CreateList({Name="Point",Single=true,
        Show={Option="Destination",Values={"Waypoint"}},
        EmptyText="No points. Save one in Markers.",Items=function()
            local points=context.services.points
            return points and points.Names() or {}
        end,Function=function(_,names) runtime.point=names[1] end,
        Tooltip="The same saved points as Markers. Choose one, then Teleport to point."})
    teleport:CreateButton({Name="Teleport to point",Show={Option="Destination",Values={"Waypoint"}},
        Function=function() Module.run(context,teleport,runtime) end})
    local unsubscribe
    if context.services.points then
        unsubscribe=context.services.points.Subscribe(function()
            if runtime.point and not context.services.points.Get(runtime.point) then
                if runtime.cancelTravel then runtime.cancelTravel() end
                pointList:Set(runtime.point,false)
            end
            pointList:Refresh()
        end)
    end
    teleport:CreateSlider({
        Name = "Arm window",
        Show = {Option = "Destination", Values = {"Tap point"}},
        Min = 1,
        Max = 15,
        Default = 6,
        Tooltip = "Seconds Tap point stays armed after the button is pressed.",
    })
    teleport:CreateSlider({
        Name = "Search range",
        Show = {Option = "Destination", Values = {"Nearest player", "Named player", "Item"}},
        Min = 50,
        Max = 5000,
        Default = 1500,
        Tooltip = "How far to look for items and players.",
    })
    teleport:CreateSlider({
        Name = "Player offset",
        Show = {Option = "Destination", Values = {"Nearest player", "Named player"}},
        Min = 0,
        Max = 20,
        Default = 4,
        Tooltip = "Studs to stop short of a player, so you do not land inside "
            .. "them.",
    })
    teleport:CreateToggle({
        Name = "Skip friends",
        Show = {Option = "Destination", Values = {"Nearest player"}},
        Default = false,
        Tooltip = "Nearest player ignores anyone on the Friend List.",
    })
    teleport:CreateDropdown({
        Name = "Movement",
        List = {"Instant", "Glide"},
        Index = 1,
        Tooltip = "Instant jumps to the destination. Glide moves continuously at Glide speed (studs/sec), regardless of frame rate. A new trip cancels the previous one.",
    })
    teleport:CreateSlider({
        Name = "Glide speed",
        Show = {Option = "Movement", Values = {"Glide"}},
        Min = 1,
        Max = 500,
        Default = 60,
        Tooltip = "Travel speed in studs per second, not distance per frame. Higher = faster.",
    })
    teleport:CreateSlider({
        Name = "Height offset",
        Min = 0,
        Max = 12,
        Default = 3,
        Tooltip = "Studs above whatever you land on.",
    })
    teleport:CreateToggle({
        Name = "Keep momentum",
        Default = false,
        Tooltip = "Leave your velocity alone on arrival instead of zeroing it.",
    })

    local tapConnection: RBXScriptConnection = userInput.InputBegan:Connect(
        function(input: InputObject, processed: boolean): ()
            if processed or os.clock() >= runtime.armedUntil then
                return
            end
            if menu.isCapturingInput() then
                return
            end
            local touched: boolean = input.UserInputType == Enum.UserInputType.Touch
            local clicked: boolean =
                input.UserInputType == Enum.UserInputType.MouseButton1
            if not touched and not clicked then
                return
            end
            runtime.armedUntil = 0
            Module.travel(
                context,
                teleport,
                runtime,
                Module.pointUnder(context, input.Position),
                true
            )
        end
    )

    activeCleanup = function(): ()
        pcall(function(): ()
            tapConnection:Disconnect()
        end)
        runtime.armedUntil = 0
        if runtime.cancelTravel then runtime.cancelTravel() end
        if unsubscribe then unsubscribe() end
    end
    Module.Initialized = true
    return teleport
end

function Module.pointUnder(context: Runtime, screenPosition: Vector3): Vector3?
    local host: any = context.host
    local currentWorkspace: Workspace = host.workspace or workspace
    local camera: Camera? = currentWorkspace.CurrentCamera
    if not camera then
        return nil
    end
    local resolvedCamera: Camera = camera :: Camera
    local ray: Ray = resolvedCamera:ScreenPointToRay(
        screenPosition.X,
        screenPosition.Y
    )
    local parameters: RaycastParams = RaycastParams.new()
    parameters.FilterType = Enum.RaycastFilterType.Exclude
    parameters.IgnoreWater = true
    parameters.FilterDescendantsInstances = {
        host.LocalPlayer.Character :: any,
        resolvedCamera,
    }
    local result: RaycastResult? = currentWorkspace:Raycast(
        ray.Origin,
        ray.Direction.Unit * 4096,
        parameters
    )
    return result and result.Position or nil
end

local function matchesName(candidate: string, query: string): boolean
    return string.find(string.lower(candidate), string.lower(query), 1, true) ~= nil
end

function Module.findItem(
    context: Runtime,
    query: string,
    origin: Vector3,
    range: number
): Vector3?
    local host: any = context.host
    local currentWorkspace: Workspace = host.workspace or workspace
    local best: Vector3? = nil
    local bestDistance: number = range
    local character: Model? = host.LocalPlayer.Character

    for _, descendant: Instance in ipairs(currentWorkspace:GetDescendants()) do
        if character and descendant:IsDescendantOf(character) then
            continue
        end
        if not matchesName(descendant.Name, query) then
            continue
        end
        local position: Vector3? = nil
        if descendant:IsA("BasePart") then
            position = (descendant :: BasePart).Position
        elseif descendant:IsA("Model") then
            local pivotOk: boolean, pivot: any = pcall(function(): CFrame
                return (descendant :: Model):GetPivot()
            end)
            if pivotOk then
                position = (pivot :: CFrame).Position
            end
        end
        if not position then
            continue
        end
        local distance: number = ((position :: Vector3) - origin).Magnitude
        if distance < bestDistance then
            best = position
            bestDistance = distance
        end
    end
    return best
end

function Module.run(context: Runtime, teleport: any, runtime: any): ()
    if runtime.cancelTravel then runtime.cancelTravel() end
    if teleport.Options.Destination.Value == "MM2" then
        teleport:Notify("Choose a MM2 teleport button below")
        return
    end
    local host: any = context.host
    local entityLibrary: any = context.entity
    local localPlayer: Player = host.LocalPlayer
    local options: any = teleport.Options
    local destination: string = options["Destination"].Value

    local root: BasePart? = characterRoot(localPlayer)
    if not root then
        teleport:Notify("no character")
        return
    end
    local origin: Vector3 = (root :: BasePart).Position
    local range: number = options["Search range"].Value

    if destination == "Tap point" then
        runtime.armedUntil = os.clock() + options["Arm window"].Value
        teleport:Notify("tap where you want to go")
        return
    end

    if destination == "Waypoint" then
        local points=context.services.points
        local position,surface
        if points and runtime.point then position,surface=points.Get(runtime.point) end
        if not position then teleport:Notify("Choose a saved point from Markers first.");return end
        Module.travel(context,teleport,runtime,position,surface==true)
        return
    end

    if destination == "Last position" then
        if not runtime.lastOrigin then
            teleport:Notify("nowhere to go back to")
            return
        end
        Module.travel(context, teleport, runtime, runtime.lastOrigin, false)
        return
    end

    if destination == "Item" then
        local query: string = tostring(options["Item"].Value or "")
        if query == "" then
            teleport:Notify("type an item name first")
            return
        end
        local found: Vector3? = Module.findItem(context, query, origin, range)
        if not found then
            teleport:Notify("no \"" .. query .. "\" within range")
            return
        end
        Module.travel(context, teleport, runtime, found, true)
        return
    end

    entityLibrary:Refresh()
    local target: any = nil
    if destination == "Nearest player" then
        local bestDistance: number = range
        for _, entity: any in ipairs(entityLibrary.List) do
            if options["Skip friends"].Value
                and entityLibrary:IsProtected(entity.Player) then
                continue
            end
            if entity.Distance < bestDistance then
                target = entity
                bestDistance = entity.Distance
            end
        end
    else
        local query: string = tostring(options["Player"].Value or "")
        if query == "" then
            teleport:Notify("type a player name first")
            return
        end
        for _, entity: any in ipairs(entityLibrary.List) do
            if matchesName(entity.Player.Name, query)
                or matchesName(entity.Player.DisplayName, query) then
                target = entity
                break
            end
        end
    end

    if not target then
        teleport:Notify("no matching player")
        return
    end

    local targetPosition: Vector3 = target.RootPart.Position
    local offset: number = options["Player offset"].Value
    local approach: Vector3 = targetPosition - origin
    if offset > 0 and approach.Magnitude > offset then
        targetPosition = targetPosition - approach.Unit * offset
    end
    Module.travel(context, teleport, runtime, targetPosition, false)
end

function Module.travel(
    context: Runtime,
    teleport: any,
    runtime: any,
    destination: Vector3?,
    liftToSurface: boolean
): ()
    local host: any = context.host
    local localPlayer: Player = host.LocalPlayer
    if runtime.cancelTravel then runtime.cancelTravel() end
    if not destination then
        teleport:Notify("nothing there")
        return
    end

    local root: BasePart?, humanoid: Humanoid? = characterRoot(localPlayer)
    if not root then
        return
    end
    local resolvedRoot: BasePart = root :: BasePart
    local options: any = teleport.Options

    runtime.lastOrigin = resolvedRoot.Position

    local target: Vector3 = destination :: Vector3
    if liftToSurface then

        local hipHeight: number = humanoid and (humanoid :: Humanoid).HipHeight or 2
        target = target
            + Vector3.new(0, hipHeight + options["Height offset"].Value, 0)
    end

    local keepMomentum: boolean = options["Keep momentum"].Value
    if options["Movement"].Value == "Instant" then
        resolvedRoot.CFrame = resolvedRoot.CFrame + (target - resolvedRoot.Position)
        if not keepMomentum then
            resolvedRoot.AssemblyLinearVelocity = Vector3.zero
            resolvedRoot.AssemblyAngularVelocity = Vector3.zero
        end
        return
    end

    local speed=math.max(0,options["Glide speed"].Value)
    if speed==0 then teleport:Notify("Glide speed must be greater than zero.");return end
    local character=localPlayer.Character
    local connection
    local function finish()
        if connection then connection:Disconnect();connection=nil end
        runtime.cancelTravel=nil
        if context.services.activity then context.services.activity.set("teleport",false) end
        teleport:SetStatus(nil)
    end
    if runtime.cancelTravel then runtime.cancelTravel() end
    runtime.cancelTravel=finish
    if context.services.activity then context.services.activity.set("teleport",true) end
    teleport:SetStatus("Gliding")
    connection=host.RunService.Heartbeat:Connect(function(dt)
        if localPlayer.Character~=character or not resolvedRoot.Parent
            or characterRoot(localPlayer)~=resolvedRoot or humanoid and humanoid.Health<=0 then finish();return end
        local offset=target-resolvedRoot.Position
        local distance=offset.Magnitude
        local amount=math.min(distance,speed*math.clamp(dt,0,0.1))
        if distance<=amount+0.001 then
            resolvedRoot.CFrame=resolvedRoot.CFrame+(target-resolvedRoot.Position)
            if not keepMomentum then resolvedRoot.AssemblyLinearVelocity=Vector3.zero;resolvedRoot.AssemblyAngularVelocity=Vector3.zero end
            finish();return
        end
        if distance>0 then resolvedRoot.CFrame+=offset.Unit*amount end
        if not keepMomentum then resolvedRoot.AssemblyLinearVelocity=Vector3.zero;resolvedRoot.AssemblyAngularVelocity=Vector3.zero end
    end)
end

function Module.destroy(): ()
    if activeCleanup then
        pcall(activeCleanup)
    end
    activeCleanup = nil
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Movement/FreezeMovements.lua"] = [[
export type Runtime = {
    framework: any,
    entity: any,
    host: any,
}

local Module = {
    Name = "FreezeMovements",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local activeCleanup: (() -> ())? = nil

function Module.init(context: Runtime): any
    local host: any = context.host
    local TaskManager: any = host.TaskManager
    local featureConnections: any = host.featureConnections
    local disconnectFeatureConnection: any = host.disconnectFeatureConnection
    local getCharacterParts: any = host.getCharacterParts
    local createUniversalFeature: any = host.createUniversalFeature
    local addCycleOption: any = host.addCycleOption
    local addToggleOption: any = host.addToggleOption
    local freezeSettings = {mode = "Anchor", emotes = true, animation = false}
    -- An old saved emote mode must not silently become Anchor on upgrade.
    local config: any = host.configData
    if config and config.values and config.states then
        local key: string = "Movement.FreezeMovements.Freezemode"
        local legacy: any = config.values[key]
        if legacy == "Freeze Emotes" or legacy == "Glitch Animations" then
            config.values[key] = "Motion"
            local prefix: string = "Movement.FreezeMovements."
            if config.states[prefix .. "FreezeEmotes"] == nil then
                config.states[prefix .. "FreezeEmotes"] = legacy == "Freeze Emotes"
            end
            if config.states[prefix .. "FreezeAnimation"] == nil then
                config.states[prefix .. "FreezeAnimation"] = legacy == "Glitch Animations"
            end
        end
    end
    local FreezeFeature: any = nil
    local originalFreezeState = setmetatable({}, {__mode = "k"})
    -- Motion never changes movement physics. Managed tracks are local;
    -- cross-client visibility depends on the game's animation replication.
    local stickyEmoteTracks: {any} = {}
    local emoteLastSeen: {[any]: number} = setmetatable({}, {__mode = "k"})

    local function getAnimator(humanoid: any): any
        local animator: any = humanoid and humanoid:FindFirstChildOfClass("Animator")
        if not animator and humanoid and humanoid.Parent then
            local character: any = humanoid.Parent
            animator = character and character:FindFirstChildWhichIsA("Animator", true)
        end
        return animator
    end

    local emoteConnection: any = nil
    local catalogEmoteConnection: any = nil
    local emoteGeneration: number = 0
    local watchedHumanoid: any = nil
    local watchedAnimator: any = nil
    local watchedAnimate: any = nil
    local nextMetadataRefresh: number = 0
    local freezeEnabled: boolean = false
    local resolvedAssets: {[number]: boolean} = {}
    local assetAttempts: {[number]: number} = {}
    local pendingEmoteTracks: {any} = {}
    local lastMetadataRefresh: number = -math.huge
    local emoteNames: {[string]: boolean} = {}
    local emoteIds: {[string]: boolean} = {}
    local managedEmotes: {[any]: any} = {}
    local ownedEmotes: {[any]: boolean} = setmetatable({}, {__mode = "k"})
    local isEmoteTrack: (any) -> boolean

    local function clearStickyEmoteTracks(): ()
        emoteGeneration += 1
        if emoteConnection then emoteConnection:Disconnect() end
        if catalogEmoteConnection then catalogEmoteConnection:Disconnect() end
        emoteConnection = nil
        catalogEmoteConnection = nil
        local previousHumanoid: any = watchedHumanoid
        watchedHumanoid = nil
        watchedAnimator = nil
        watchedAnimate = nil
        resolvedAssets = {}
        assetAttempts = {}
        pendingEmoteTracks = {}
        local stopped: {[any]: boolean} = {}
        local function stopOnce(track: any): ()
            if track and not stopped[track] then
                stopped[track] = true
                pcall(function(): () track:Stop(0.1) end)
            end
        end
        -- The original Animate track can still be playing even if we never
        -- had to hand it off. OFF must release that source as well as ours.
        for _, source: any in ipairs(stickyEmoteTracks) do stopOnce(source) end
        local animator: any = getAnimator(previousHumanoid)
        if animator then
            pcall(function(): ()
                for _, track: any in ipairs(animator:GetPlayingAnimationTracks()) do
                    if track.IsPlaying and not ownedEmotes[track] and isEmoteTrack(track) then stopOnce(track) end
                end
            end)
        end
        for _, track: any in pairs(managedEmotes) do
            stopOnce(track)
            pcall(function(): () track:Destroy() end)
        end
        managedEmotes = {}
        ownedEmotes = setmetatable({}, {__mode = "k"})
        emoteNames = {}
        emoteIds = {}
        stickyEmoteTracks = {}
        emoteLastSeen = setmetatable({}, {__mode = "k"})
    end

    local CLASSIC_EMOTES = {
        dance = true, dance1 = true, dance2 = true, dance3 = true,
        wave = true, point = true, cheer = true, laugh = true,
    }

    isEmoteTrack = function(track: any): boolean
        -- Action priority is also used by weapon attacks; it is NOT an
        -- emote identifier. Avoid substring matches such as SpinAttack.
        local function knownName(name: string): boolean
            local lower: string = string.lower(name)
            if emoteNames[lower] then return true end
            lower = lower:gsub("anim$", "")
            return CLASSIC_EMOTES[lower] == true
        end
        if knownName(tostring(track.Name or "")) then return true end
        local animation: any = track.Animation
        if typeof(animation) == "Instance" then
            if knownName(animation.Name) then return true end
            local node: any = animation.Parent
            for _depth: number = 1, 6 do
                if not node then break end
                if knownName(node.Name) then return true end
                node = node.Parent
            end
            local id: string? = string.match(animation.AnimationId, "%d+")
            if id and emoteIds[id] then return true end
        end
        return false
    end

    local function rememberEmote(track: any): ()
        -- A newly selected emote replaces the previous held emote. Never
        -- layer a whole history of dances on the same joints.
        for source: any, managed: any in pairs(managedEmotes) do
            pcall(function(): () managed:Stop(0.1) end)
            pcall(function(): () managed:Destroy() end)
            ownedEmotes[managed] = nil
            managedEmotes[source] = nil
        end
        stickyEmoteTracks = {track}
        emoteLastSeen = setmetatable({}, {__mode = "k"})
        emoteLastSeen[track] = os.clock()
    end

    local function freezeEmotesTick(humanoid: any, root: any): ()
        -- Hold the selected emote while walking with a track Animate does
        -- not own. Keep it through jumps; release on death, replacement,
        -- mode change or disable.
        local okState: boolean, state: any = pcall(function(): any return humanoid:GetState() end)
        if okState and state == Enum.HumanoidStateType.Dead then
            clearStickyEmoteTracks()
            return
        end
        local animator: any = getAnimator(humanoid)
        if not animator then
            if watchedAnimator then clearStickyEmoteTracks() end
            return
        end
        local animate = humanoid.Parent and humanoid.Parent:FindFirstChild("Animate")
        -- Avatar descriptions/Animate are often installed AFTER respawn.
        -- Retry metadata at a bounded rate, and immediately on replacement.
        if watchedHumanoid ~= humanoid or watchedAnimator ~= animator
            or watchedAnimate ~= animate or os.clock() >= nextMetadataRefresh then
            if watchedHumanoid ~= humanoid or watchedAnimator ~= animator then
                clearStickyEmoteTracks()
            else
                if emoteConnection then emoteConnection:Disconnect(); emoteConnection = nil end
                if catalogEmoteConnection then catalogEmoteConnection:Disconnect(); catalogEmoteConnection = nil end
            end
            watchedHumanoid = humanoid
            watchedAnimator = animator
            watchedAnimate = animate
            lastMetadataRefresh = os.clock()
            nextMetadataRefresh = lastMetadataRefresh + 2
            -- Catalog asset IDs are NOT necessarily the AnimationId played
            -- by Animate. Prefer the actual track reported by the engine.
            -- This event requires executor permissions on some client builds;
            -- a denied connection must not prevent the metadata fallback.
            pcall(function(): ()
                catalogEmoteConnection = humanoid.EmoteTriggered:Connect(function(success: boolean, track: any): ()
                    if success and track and watchedHumanoid == humanoid and not ownedEmotes[track] then
                        local animation: any = track.Animation
                        if animation then
                            local id: string? = string.match(animation.AnimationId, "%d+")
                            if id then emoteIds[id] = true end
                        end
                        rememberEmote(track)
                    end
                end)
            end)
            local catalogAssets: {number} = {}
            pcall(function(): ()
                local description: any = humanoid:GetAppliedDescription()
                local ok: boolean, emotes: any = pcall(description.GetEmotes, description)
                description:Destroy()
                if not ok then return end
                local seen: {[number]: boolean} = {}
                for name: string, ids: any in pairs(emotes) do
                    emoteNames[string.lower(name)] = true
                    for _, id: any in ipairs(ids) do
                        emoteIds[tostring(id)] = true
                        local numberId: number? = tonumber(id)
                        if numberId and not seen[numberId] and not resolvedAssets[numberId] and #catalogAssets < 48 then
                            seen[numberId] = true
                            resolvedAssets[numberId] = true
                            assetAttempts[numberId] = (assetAttempts[numberId] or 0) + 1
                            table.insert(catalogAssets, numberId)
                        end
                    end
                end
            end)
            -- Resolve catalog containers without playing an emote to discover
            -- its ID. Never run downloaded scripts; only inspect Animation data.
            local generation: number = emoteGeneration
            if #catalogAssets > 0 and task and game then
                task.spawn(function(): ()
                    for _, assetId: number in ipairs(catalogAssets) do
                        if generation ~= emoteGeneration then return end
                        local ok: boolean, objects: any = pcall(function(): any
                            return game:GetObjects("rbxassetid://" .. tostring(assetId))
                        end)
                        if not ok and generation == emoteGeneration and (assetAttempts[assetId] or 0) < 3 then
                            resolvedAssets[assetId] = nil -- bounded retry after transient load failure
                        end
                        if ok and type(objects) == "table" then
                            for _, object: any in ipairs(objects) do
                                pcall(function(): ()
                                    local nodes: {any} = object:GetDescendants()
                                    table.insert(nodes, object)
                                    for _, node: any in ipairs(nodes) do
                                        if generation == emoteGeneration and node:IsA("Animation") then
                                            local id: string? = string.match(node.AnimationId, "%d+")
                                            if id then emoteIds[id] = true end
                                        end
                                    end
                                end)
                                pcall(function(): () object:Destroy() end)
                            end
                        end
                    end
                end)
            end
            -- R6 /e dance2 commonly plays Animation1/2/3, not a track
            -- named dance2. Read IDs under Animate's named emote folders.
            pcall(function(): ()
                local animate: any = humanoid.Parent:FindFirstChild("Animate")
                if animate then
                    for _, animation: any in ipairs(animate:GetDescendants()) do
                        if animation:IsA("Animation") then
                            local node: any = animation
                            while node and node ~= animate do
                                local name: string = string.lower(node.Name):gsub("anim$", "")
                                if CLASSIC_EMOTES[name] or emoteNames[name] then
                                    local id: string? = string.match(animation.AnimationId, "%d+")
                                    if id then emoteIds[id] = true end
                                    break
                                end
                                node = node.Parent
                            end
                        end
                    end
                end
            end)
            -- Catch tracks at start, before Animate can cancel them on movement.
            emoteConnection = animator.AnimationPlayed:Connect(function(track: any): ()
                if not ownedEmotes[track] and isEmoteTrack(track) and not emoteLastSeen[track] then
                    rememberEmote(track)
                elseif not ownedEmotes[track] then
                    if #pendingEmoteTracks >= 8 then table.remove(pendingEmoteTracks, 1) end
                    table.insert(pendingEmoteTracks, {track = track, at = os.clock()})
                    if os.clock() - lastMetadataRefresh >= 0.25 then nextMetadataRefresh = 0 end
                end
            end)
        end
        for index = #pendingEmoteTracks, 1, -1 do
            local candidate = pendingEmoteTracks[index]
            if isEmoteTrack(candidate.track) then
                rememberEmote(candidate.track)
                table.remove(pendingEmoteTracks, index)
            elseif os.clock() - candidate.at > 5 then
                table.remove(pendingEmoteTracks, index)
            end
        end
        local okTracks: boolean, tracks: any = pcall(function(): any
            return animator:GetPlayingAnimationTracks()
        end)
        if not okTracks or type(tracks) ~= "table" then
            return
        end
        local playing: {[any]: boolean} = {}
        for _, track: any in ipairs(tracks) do
            if track and track.IsPlaying then
                playing[track] = true
                if not ownedEmotes[track] and not emoteLastSeen[track] and isEmoteTrack(track) then
                    rememberEmote(track)
                end
                if emoteLastSeen[track] then
                    emoteLastSeen[track] = os.clock()
                end
            end
        end
        local moving: boolean = root ~= nil
            and root.AssemblyLinearVelocity.Magnitude > 1
        local now: number = os.clock()
        for index: number = #stickyEmoteTracks, 1, -1 do
            local track: any = stickyEmoteTracks[index]
            if not track then
                table.remove(stickyEmoteTracks, index)
            elseif playing[track] or (managedEmotes[track] and managedEmotes[track].IsPlaying) then
                emoteLastSeen[track] = now
            else
                local lastSeen: number = emoteLastSeen[track]
                if lastSeen == nil then
                    lastSeen = now
                    emoteLastSeen[track] = now
                end
                -- Only hand off after a recent, recognized source was
                -- cancelled while moving; do not guess from Action priority.
                if moving and now - lastSeen < 1.5 then
                    pcall(function(): ()
                        -- A separate track is essential: Animate owns the
                        -- original and will keep cancelling it when walking.
                        local managed: any = managedEmotes[track]
                        if not managed then
                            managed = animator:LoadAnimation(track.Animation)
                            ownedEmotes[managed] = true
                            managedEmotes[track] = managed
                            managed.Looped = true
                            managed.Priority = Enum.AnimationPriority.Action
                        end
                        if not managed.IsPlaying then managed:Play(0.1) end
                    end)
                elseif now - lastSeen > 0.5 then
                    local managed: any = managedEmotes[track]
                    if managed then
                        pcall(function(): () managed:Stop(0.1) end)
                        pcall(function(): () managed:Destroy() end)
                        managedEmotes[track] = nil
                        ownedEmotes[managed] = nil
                    end
                    table.remove(stickyEmoteTracks, index)
                    emoteLastSeen[track] = nil
                end
            end
        end
    end

    local motionSource: any = nil
    local motionTrack: any = nil
    local motionHumanoid: any = nil
    local motionAnimator: any = nil
    local function clearMotionTrack(): ()
        if motionTrack then
            pcall(function(): () motionTrack:Stop(0.1) end)
            pcall(function(): () motionTrack:Destroy() end)
        end
        motionSource, motionTrack, motionHumanoid, motionAnimator = nil, nil, nil, nil
    end

    local LOCOMOTION = {walk=true, run=true, idle=true, jump=true, fall=true,
        climb=true, swim=true, swimidle=true}
    local function isLocomotion(track: any): boolean
        if not track or ownedEmotes[track] or isEmoteTrack(track) then return false end
        if track.Priority == Enum.AnimationPriority.Movement then return true end
        if track.Priority ~= Enum.AnimationPriority.Core and track.Priority ~= Enum.AnimationPriority.Idle then return false end
        local function known(name: any): boolean
            local key: string = string.lower(tostring(name or "")):gsub("anim$", "")
            return LOCOMOTION[key] == true
        end
        if known(track.Name) then return true end
        local node: any = track.Animation
        for _index: number = 1, 5 do
            if not node then break end
            if known(node.Name) then return true end
            node = node.Parent
        end
        return false
    end

    local function freezeAnimationTick(humanoid: any): ()
        local animator: any = getAnimator(humanoid)
        if not animator then
            if motionAnimator then clearMotionTrack() end
            return
        end
        if motionHumanoid ~= humanoid or motionAnimator ~= animator then
            clearMotionTrack()
            motionHumanoid = humanoid
            motionAnimator = animator
        end
        if not motionSource then
            local ok: boolean, tracks: any = pcall(function(): any return animator:GetPlayingAnimationTracks() end)
            if not ok or type(tracks) ~= "table" then return end
            local weight: number = -1
            for _, track: any in ipairs(tracks) do
                if track.IsPlaying and isLocomotion(track) then
                    local current: number = tonumber(track.WeightCurrent) or 1
                    if current > weight then motionSource, weight = track, current end
                end
            end
        end
        if not motionSource then return end
        -- Lock the selected clip, NOT its TimePosition. Walking continues
        -- looping even while the native controller switches to jump/fall.
        pcall(function(): ()
            if not motionTrack then
                motionTrack = animator:LoadAnimation(motionSource.Animation)
                motionTrack.Looped = true
                motionTrack.Priority = Enum.AnimationPriority.Action
                motionTrack:Play(0.1)
                motionTrack.TimePosition = motionSource.TimePosition
                motionTrack:AdjustSpeed(motionSource.Speed or 1)
            end
            -- Explicit emotes take precedence when both Motion boxes are on.
            local emotePlaying: boolean = false
            if freezeSettings.emotes then
                for _, source: any in ipairs(stickyEmoteTracks) do
                    if source.IsPlaying or (managedEmotes[source] and managedEmotes[source].IsPlaying) then
                        emotePlaying = true
                        break
                    end
                end
            end
            if emotePlaying then
                if motionTrack.IsPlaying then motionTrack:Stop(0.1) end
            elseif not motionTrack.IsPlaying then
                motionTrack:Play(0.1)
            end
        end)
    end

    local function restoreFreezeMovements(): ()
        for root: any, original: any in pairs(originalFreezeState) do
            pcall(function(): () root.Anchored = original.anchored end)
        end
        originalFreezeState = setmetatable({}, {__mode = "k"})
    end

    local toggleFreezeMovements: (boolean) -> ()
    toggleFreezeMovements = function(enabled: boolean): ()
        freezeEnabled = enabled
        disconnectFeatureConnection("FreezeMovements")
        if not enabled then
            disconnectFeatureConnection("FreezeCharacterAdded")
            disconnectFeatureConnection("FreezeCharacterRemoving")
        end
        restoreFreezeMovements()
        clearMotionTrack()
        clearStickyEmoteTracks()
        if not enabled then
            if FreezeFeature then FreezeFeature:SetStatus(nil) end
            return
        end
        local player = host.LocalPlayer
        if player and player.CharacterAdded and not featureConnections.FreezeCharacterAdded then
            featureConnections.FreezeCharacterAdded = player.CharacterAdded:Connect(function()
                if freezeEnabled then toggleFreezeMovements(true) end
            end)
        end
        if player and player.CharacterRemoving and not featureConnections.FreezeCharacterRemoving then
            featureConnections.FreezeCharacterRemoving = player.CharacterRemoving:Connect(function()
                restoreFreezeMovements()
                clearMotionTrack()
                clearStickyEmoteTracks()
            end)
        end
        FreezeFeature:SetStatus(freezeSettings.mode)
        local previousRoot: any = nil
        featureConnections.FreezeMovements = TaskManager:Connect(function(): ()
            local _, humanoid, root = getCharacterParts()
            if root ~= previousRoot then
                restoreFreezeMovements()
                clearMotionTrack()
                clearStickyEmoteTracks()
                previousRoot = root
            end
            if not humanoid then
                clearMotionTrack()
                clearStickyEmoteTracks()
                return
            end
            local ok: boolean, state: any = pcall(function(): any return humanoid:GetState() end)
            if ok and state == Enum.HumanoidStateType.Dead then
                restoreFreezeMovements()
                clearMotionTrack()
                clearStickyEmoteTracks()
                return
            end
            if freezeSettings.mode == "Motion" then
                if freezeSettings.emotes then freezeEmotesTick(humanoid, root) end
                if freezeSettings.animation then freezeAnimationTick(humanoid) end
            elseif root then
                if not originalFreezeState[root] then originalFreezeState[root] = {anchored = root.Anchored} end
                root.Anchored = true
                root.AssemblyLinearVelocity = Vector3.zero
                root.AssemblyAngularVelocity = Vector3.zero
            end
        end)
    end

    FreezeFeature = createUniversalFeature(
        "Freeze Movements", "Anchor physics or keep selected animations while moving", 4,
        toggleFreezeMovements,
        {categoryName = "Utilities", configKey = "Movement.FreezeMovements"}
    )
    local motionRows: {any} = {}
    local function refreshMotionOptions(): ()
        for _, row: any in ipairs(motionRows) do
            if host.setOptionVisible then
                host.setOptionVisible(FreezeFeature, row, freezeSettings.mode == "Motion")
            else row.Visible = freezeSettings.mode == "Motion" end
        end
    end
    addCycleOption(FreezeFeature, "Freeze mode", {"Anchor", "Motion"}, 1, function(value: string): ()
        freezeSettings.mode = value
        refreshMotionOptions()
        if FreezeFeature and FreezeFeature.enabled then toggleFreezeMovements(true) end
    end)
    -- The section widget renders its own caption and divider, so the card only
    -- has to keep the row in its visibility group.
    local heading: any = host.addSectionOption and host.addSectionOption(FreezeFeature, "Motion settings")
    if heading then
        table.insert(motionRows, heading)
    end
    local emotes: any = addToggleOption(FreezeFeature, "Freeze Emotes", true, function(value: boolean): ()
        freezeSettings.emotes = value
        if not value then clearStickyEmoteTracks() end
    end, "Keep classic and UGC emotes playing while moving. Takes precedence over the locked locomotion clip.")
    if emotes then table.insert(motionRows, emotes.Parent) end
    local animation: any = addToggleOption(FreezeFeature, "Freeze Animation", false, function(value: boolean): ()
        freezeSettings.animation = value
        clearMotionTrack()
    end, "Keep the current locomotion clip looping through jumps and other movement. Does not freeze a single frame.")
    if animation then table.insert(motionRows, animation.Parent) end
    refreshMotionOptions()
    activeCleanup = function(): () toggleFreezeMovements(false) end
    Module.Initialized = true
    return FreezeFeature
end

function Module.destroy(): ()
    if activeCleanup then
        pcall(activeCleanup)
    end
    activeCleanup = nil
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Movement/Gravity.lua"] = [[
export type Runtime = {
    framework: any,
    entity: any,
    host: any,
}

local Module = {
    Name = "Gravity",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local activeCleanup: (() -> ())? = nil

function Module.init(context: Runtime): any
    local host: any = context.host
    local TaskManager: any = host.TaskManager
    local featureConnections: any = host.featureConnections
    local disconnectFeatureConnection: any = host.disconnectFeatureConnection
    local createUniversalFeature: any = host.createUniversalFeature
    local addNumberOption: any = host.addNumberOption
    local workspace: any = host.workspace
    local gravitySettings = {value = 196.2}
    local GravityFeature: any = nil
    local originalGravity = workspace.Gravity

    local function toggleGravity(enabled)
        disconnectFeatureConnection("Gravity")

        if not enabled then
            if GravityFeature then
                GravityFeature:SetStatus(nil)
            end
            workspace.Gravity = originalGravity
            return
        end

        GravityFeature:SetStatus(tostring(math.round(gravitySettings.value)))
        originalGravity = workspace.Gravity
        featureConnections.Gravity = TaskManager:Connect(function()
            workspace.Gravity = gravitySettings.value
        end)
    end

    GravityFeature = createUniversalFeature(
        "Gravity",
        "Keep workspace gravity at a custom value",
        5,
        toggleGravity,
        {categoryName = "World"}
    )
    addNumberOption(GravityFeature, "Gravity value", gravitySettings.value, -500, 500, function(value)
        gravitySettings.value = value
        if GravityFeature.enabled then
            GravityFeature:SetStatus(tostring(math.round(value)))
        end
    end)

    activeCleanup = function(): ()
        disconnectFeatureConnection("Gravity")

        workspace.Gravity = originalGravity
    end
    Module.Initialized = true
    return GravityFeature
end

function Module.destroy(): ()
    if activeCleanup then
        pcall(activeCleanup)
    end
    activeCleanup = nil
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Movement/InfiniteJump.lua"] = [[
export type Runtime = {
    framework: any,
    entity: any,
    host: any,
    services: any,
}

local Module = {
    Name = "Infinite Jump",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local activeCleanup: (() -> ())? = nil

function Module.init(context: Runtime): any
    local host: any = context.host
    local framework: any = context.framework
    local services: any = context.services
    local LocalPlayer: Player = host.LocalPlayer
    local UserInputService: UserInputService = host.UserInputService
    local RunService: RunService = host.RunService
    local movementInput: any = services and services.movementInput

    local lastBoostAt: number = -math.huge
    local pressHeld: boolean = false
    local jumpTouch: any = nil

    local function characterParts(): (Model?, Humanoid?, BasePart?)
        local character: Model? = LocalPlayer and LocalPlayer.Character
        if not character then
            return nil, nil, nil
        end
        local humanoid: Humanoid? = character:FindFirstChildOfClass("Humanoid") :: Humanoid?
        local root: BasePart? = character:FindFirstChild("HumanoidRootPart") :: BasePart?
        return character, humanoid, root
    end

    local function canBoostJump(humanoid: Humanoid?): boolean
        if not humanoid or not humanoid.Parent or humanoid.Health <= 0 then
            return false
        end
        local currentState: Enum.HumanoidStateType = humanoid:GetState()
        return currentState ~= Enum.HumanoidStateType.Seated
            and currentState ~= Enum.HumanoidStateType.Swimming
            and currentState ~= Enum.HumanoidStateType.Climbing
            and currentState ~= Enum.HumanoidStateType.Physics
            and currentState ~= Enum.HumanoidStateType.PlatformStanding
            and currentState ~= Enum.HumanoidStateType.Ragdoll
            and currentState ~= Enum.HumanoidStateType.Dead
    end

    local infiniteJump: any
    infiniteJump = framework.Categories.Exploits:CreateModule({
        Name = "Infinite Jump",
        Category = "Exploits",
        ConfigKey = "Universal.InfiniteJump",
        Order = 10,
        Tooltip = "Jump repeatedly in mid-air on both PC (Spacebar) and Mobile (Touch Jump button).",
        Function = function(enabled: boolean): ()
            lastBoostAt = -math.huge
            pressHeld = false
            jumpTouch = nil
            if not enabled then
                infiniteJump:SetStatus(nil)
                return
            end

            infiniteJump:SetStatus("Active")

            local function executeAirJump(fromTouchButton: boolean?): ()
                local _, humanoid: Humanoid?, root: BasePart? = characterParts()
                if not humanoid or not root or root.Anchored or not canBoostJump(humanoid) then
                    return
                end
                local power: number = infiniteJump.Options["Jump Power"]
                    and infiniteJump.Options["Jump Power"].Value
                    or 50
                -- Leave ordinary positive ground takeoff to Roblox unless
                -- triggered from the mobile JumpButton while airborne or using
                -- negative inverted jump physics.
                if humanoid.FloorMaterial ~= Enum.Material.Air and power >= 0 and not fromTouchButton then
                    return
                end
                local now: number = os.clock()
                if now - lastBoostAt < 0.08 then
                    return
                end
                lastBoostAt = now

                local velocity: Vector3 = root.AssemblyLinearVelocity
                root.AssemblyLinearVelocity = Vector3.new(velocity.X, power, velocity.Z)
                humanoid:ChangeState(
                    if power < 0
                        then Enum.HumanoidStateType.Freefall
                        else Enum.HumanoidStateType.Jumping
                )
            end

            local function onJumpRequested(): ()
                if pressHeld then
                    return
                end
                pressHeld = true
                if UserInputService and UserInputService.TouchEnabled then
                    local okTouches: boolean, touches: any = pcall(function(): any
                        return UserInputService:GetTouches()
                    end)
                    if okTouches and type(touches) == "table" then
                        if #touches == 1 then
                            jumpTouch = touches[1]
                        else
                            local gui: Instance? = LocalPlayer
                                and LocalPlayer:FindFirstChildOfClass("PlayerGui")
                            local touchGui: Instance? = gui and gui:FindFirstChild("TouchGui")
                            local button: any = touchGui and touchGui:FindFirstChild("JumpButton", true)
                            if button then
                                local at: Vector2 = button.AbsolutePosition
                                local size: Vector2 = button.AbsoluteSize
                                for _, touch: any in ipairs(touches) do
                                    local p: Vector3 = touch.Position
                                    if p.X >= at.X and p.Y >= at.Y
                                        and p.X <= at.X + size.X
                                        and p.Y <= at.Y + size.Y then
                                        jumpTouch = touch
                                        break
                                    end
                                end
                            end
                        end
                    end
                end
                executeAirJump(false)
            end

            if movementInput and type(movementInput.onJumpRequest) == "function" then
                infiniteJump:Clean(movementInput.onJumpRequest(onJumpRequested))
            elseif UserInputService and UserInputService.JumpRequest then
                infiniteJump:Clean(UserInputService.JumpRequest:Connect(onJumpRequested))
            end

            -- Direct PC (Spacebar / Gamepad ButtonA) + Mobile TouchGui JumpButton support
            if UserInputService and UserInputService.InputBegan then
                infiniteJump:Clean(UserInputService.InputBegan:Connect(function(input: any, gameProcessed: boolean): ()
                    if input.KeyCode == Enum.KeyCode.Space or input.KeyCode == Enum.KeyCode.ButtonA then
                        if not gameProcessed then
                            onJumpRequested()
                        end
                    elseif input.UserInputType == Enum.UserInputType.Touch then
                        local gui: Instance? = LocalPlayer
                            and LocalPlayer:FindFirstChildOfClass("PlayerGui")
                        local touchGui: Instance? = gui and gui:FindFirstChild("TouchGui")
                        local button: any = touchGui and touchGui:FindFirstChild("JumpButton", true)
                        if button and button.AbsolutePosition and button.AbsoluteSize and input.Position then
                            local at: Vector2 = button.AbsolutePosition
                            local size: Vector2 = button.AbsoluteSize
                            local p: Vector3 = input.Position
                            if p.X >= at.X and p.Y >= at.Y
                                and p.X <= at.X + size.X
                                and p.Y <= at.Y + size.Y then
                                jumpTouch = input
                                pressHeld = true
                                executeAirJump(true)
                            end
                        end
                    end
                end))
            end

            if UserInputService and UserInputService.InputEnded then
                infiniteJump:Clean(UserInputService.InputEnded:Connect(function(event: any): ()
                    if event.KeyCode == Enum.KeyCode.Space
                        or event.KeyCode == Enum.KeyCode.ButtonA
                        or (event.UserInputType == Enum.UserInputType.Touch
                            and (not jumpTouch or event == jumpTouch)) then
                        pressHeld = false
                        jumpTouch = nil
                    end
                end))
            end

            if UserInputService and UserInputService.WindowFocusReleased then
                infiniteJump:Clean(UserInputService.WindowFocusReleased:Connect(function(): ()
                    pressHeld = false
                    jumpTouch = nil
                end))
            end

            if RunService and RunService.PreSimulation then
                infiniteJump:Clean(RunService.PreSimulation:Connect(function(): ()
                    local _, humanoid: Humanoid?, root: BasePart? = characterParts()
                    if not humanoid or not root or humanoid.Health <= 0 then
                        return
                    end
                    local power: number = infiniteJump.Options["Jump Power"]
                        and infiniteJump.Options["Jump Power"].Value
                        or 50
                    if power < 0 and humanoid:GetState() == Enum.HumanoidStateType.Jumping then
                        local vel: Vector3 = root.AssemblyLinearVelocity
                        root.AssemblyLinearVelocity = Vector3.new(vel.X, power, vel.Z)
                        humanoid:ChangeState(Enum.HumanoidStateType.Freefall)
                    end
                end))
            end
        end,
    })

    infiniteJump:CreateSlider({
        Name = "Jump Power",
        Min = 1,
        Max = 250,
        Default = 50,
        Tooltip = "Vertical jump velocity applied in mid-air (1-250 slider preset; supports negative values to invert jump physics).",
    })

    activeCleanup = function(): ()
        if infiniteJump.Enabled then
            infiniteJump:Toggle(false)
        end
    end

    Module.Initialized = true
    return infiniteJump
end

function Module.destroy(): ()
    if activeCleanup then
        activeCleanup()
    end
    activeCleanup = nil
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Movement/Jump.lua"] = [[
export type Runtime = {
    framework: any,
    entity: any,
    host: any,
    services: any,
}

local Module = {
    Name = "Jump",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local activeCleanup: (() -> ())? = nil

function Module.init(context: Runtime): any
    local host: any = context.host
    local framework: any = context.framework
    local movementInput: any = context.services and context.services.movementInput
    local UserInputService: any = host.UserInputService or game:GetService("UserInputService")
    local LocalPlayer: Player = host.LocalPlayer or game:GetService("Players").LocalPlayer

    local originalJumpPower = setmetatable({}, {__mode = "k"}) :: {[Humanoid]: {jumpPower: number, useJumpPower: boolean}}
    local lastInfiniteJumpAt: number = -math.huge

    local function characterParts(): (Model?, Humanoid?, BasePart?)
        local character: Model? = LocalPlayer.Character
        if not character then
            return nil, nil, nil
        end
        local humanoid: Humanoid? = character:FindFirstChildOfClass("Humanoid")
        local root: BasePart? = character:FindFirstChild("HumanoidRootPart") :: BasePart?
        return character, humanoid, root
    end

    local function restoreJumpPower(): ()
        for humanoid: Humanoid, original in pairs(originalJumpPower) do
            if humanoid and humanoid.Parent then
                humanoid.JumpPower = original.jumpPower
                humanoid.UseJumpPower = original.useJumpPower
            end
        end
        originalJumpPower = setmetatable({}, {__mode = "k"}) :: any
    end

    local function canControlJump(humanoid: Humanoid): boolean
        if humanoid.Health <= 0 or humanoid.Sit or humanoid.SeatPart then return false end
        local state = humanoid:GetState()
        return state ~= Enum.HumanoidStateType.Seated and state ~= Enum.HumanoidStateType.Swimming
            and state ~= Enum.HumanoidStateType.Climbing and state ~= Enum.HumanoidStateType.Physics
            and state ~= Enum.HumanoidStateType.PlatformStanding and state ~= Enum.HumanoidStateType.Ragdoll
            and state ~= Enum.HumanoidStateType.FallingDown and state ~= Enum.HumanoidStateType.Dead
    end

    local fallHumanoid: Humanoid? = nil
    local fallConnection: RBXScriptConnection? = nil
    local originalStates = nil
    local redirecting = false
    local fallBoosted: Humanoid? = nil
    local pressHeld = false
    local jumpTouch: InputObject? = nil

    local function clearFallController(): ()
        if fallConnection then fallConnection:Disconnect(); fallConnection = nil end
        if fallHumanoid and fallHumanoid.Parent and originalStates then
            fallHumanoid:SetStateEnabled(Enum.HumanoidStateType.Jumping,originalStates.jumping)
            fallHumanoid:SetStateEnabled(Enum.HumanoidStateType.Freefall,originalStates.freefall)
        end
        fallHumanoid, originalStates, fallBoosted = nil, nil, nil
    end
    local function enforceFall(humanoid: Humanoid): ()
        humanoid.Jump = false
        if humanoid:GetStateEnabled(Enum.HumanoidStateType.Jumping) then humanoid:SetStateEnabled(Enum.HumanoidStateType.Jumping,false) end
        if not humanoid:GetStateEnabled(Enum.HumanoidStateType.Freefall) then humanoid:SetStateEnabled(Enum.HumanoidStateType.Freefall,true) end
        if humanoid:GetState() == Enum.HumanoidStateType.Jumping and not redirecting then
            redirecting = true
            humanoid:ChangeState(Enum.HumanoidStateType.Freefall)
            redirecting = false
        end
    end
    local function syncFallController(humanoid: Humanoid?, enabled: boolean): ()
        if not enabled or not humanoid or not canControlJump(humanoid) then
            if fallHumanoid then clearFallController() end
            return
        end
        if fallHumanoid ~= humanoid then
            clearFallController()
            fallHumanoid = humanoid
            originalStates = {jumping=humanoid:GetStateEnabled(Enum.HumanoidStateType.Jumping),
                freefall=humanoid:GetStateEnabled(Enum.HumanoidStateType.Freefall)}
            fallConnection = humanoid.StateChanged:Connect(function(_,nextState)
                if not canControlJump(humanoid) or nextState == Enum.HumanoidStateType.Landed then clearFallController()
                elseif nextState == Enum.HumanoidStateType.Jumping then enforceFall(humanoid) end
            end)
        end
        enforceFall(humanoid)
    end

    local function performHighJump(velocityOverride: number?): ()
        local _, humanoid: Humanoid?, root: BasePart? = characterParts()
        if not humanoid or not root or root.Anchored or not canControlJump(humanoid) then
            return
        end
        local velocityVal: number = velocityOverride or 72
        local current: Vector3 = (root :: BasePart).AssemblyLinearVelocity
        ;(root :: BasePart).AssemblyLinearVelocity = Vector3.new(
            current.X,
            velocityVal,
            current.Z
        )
        if humanoid.FloorMaterial ~= Enum.Material.Air then
            humanoid:ChangeState(Enum.HumanoidStateType.Freefall)
        end
    end

    local function performInfiniteJump(mode: string, strength: number, interval: number): ()
        local _, humanoid: Humanoid?, root: BasePart? = characterParts()
        if not humanoid or not root or root.Anchored or not canControlJump(humanoid) then
            return
        end

        local now: number = os.clock()
        if now - lastInfiniteJumpAt < interval then
            return
        end
        lastInfiniteJumpAt = now

        local velocity: Vector3 = (root :: BasePart).AssemblyLinearVelocity
        -- Positive Y is intentional: Fall changes the actual local state,
        -- not the trajectory into downward motion or a manual animation.
        -- X/Z momentum is unchanged; this makes no server-state guarantee.
        syncFallController(humanoid, mode == "Fall")
        fallBoosted = mode == "Fall" and humanoid or nil
        ;(root :: BasePart).AssemblyLinearVelocity = Vector3.new(velocity.X, strength, velocity.Z)
        humanoid:ChangeState(mode == "Fall" and Enum.HumanoidStateType.Freefall or Enum.HumanoidStateType.Jumping)
    end

    local jump: any
    local function refreshFall(): ()
        local _, humanoid, root = characterParts()
        syncFallController(humanoid,fallBoosted == humanoid and root ~= nil and not root.Anchored and jump.Enabled and jump.Options["Infinite jump"].Value
            and jump.Options["Infinite jump mode"].Value == "Fall")
    end
    jump = framework.Categories.Exploits:CreateModule({
        Name = "Jump",
        Category = "Exploits",
        ConfigKey = "Universal.Jump",
        Order = 6,
        Tooltip = "Consolidated jump controls: adjust Jump Power, execute High Jump, enable Infinite Jump and Auto Jump.",
        Function = function(enabled: boolean): ()
            restoreJumpPower()
            clearFallController()
            lastInfiniteJumpAt = -math.huge
            pressHeld, jumpTouch = false, nil
            if not enabled then
                jump:SetStatus(nil)
                return
            end

            jump:SetStatus("active")
            jump:Clean(function(): () restoreJumpPower(); clearFallController() end)

            local function requestJump(): ()
                if pressHeld then return end
                pressHeld = true
                if UserInputService.TouchEnabled then
                    local touches = UserInputService:GetTouches()
                    if #touches == 1 then jumpTouch = touches[1]
                    else
                        local gui = LocalPlayer:FindFirstChildOfClass("PlayerGui")
                        local touchGui = gui and gui:FindFirstChild("TouchGui")
                        local button = touchGui and touchGui:FindFirstChild("JumpButton",true)
                        if button then
                            local at, size = button.AbsolutePosition, button.AbsoluteSize
                            for _, touch in ipairs(touches) do
                                local p = touch.Position
                                if p.X >= at.X and p.Y >= at.Y and p.X <= at.X+size.X and p.Y <= at.Y+size.Y then jumpTouch = touch;break end
                            end
                        end
                    end
                end
                local _, humanoid, root = characterParts()
                -- Ground takeoff belongs to Roblox: ordinary Jumping/animation.
                -- Only a new press in midair is an extra jump.
                if not humanoid or not root then return end
                if humanoid.FloorMaterial ~= Enum.Material.Air then return end
                local opts = jump.Options
                if not opts["Infinite jump"] or not opts["Infinite jump"].Value then
                    return
                end
                local mode: string = opts["Infinite jump mode"] and opts["Infinite jump mode"].Value or "Normal"
                if mode == "Rise" then
                    return
                end
                local strength: number = opts["Infinite jump power"] and opts["Infinite jump power"].Value or 50
                local interval: number = opts["Jump interval"] and opts["Jump interval"].Value or 0.18
                performInfiniteJump(mode, strength, interval)
            end
            if movementInput and type(movementInput.onJumpRequest) == "function" then
                jump:Clean(movementInput.onJumpRequest(requestJump))
            else
                jump:Clean(UserInputService.JumpRequest:Connect(requestJump))
            end

            jump:Clean(UserInputService.InputEnded:Connect(function(event)
                if event.KeyCode == Enum.KeyCode.Space or event.KeyCode == Enum.KeyCode.ButtonA
                    or event.UserInputType == Enum.UserInputType.Touch and (not jumpTouch or event == jumpTouch) then
                    pressHeld, jumpTouch = false, nil
                end
            end))
            jump:Clean(UserInputService.WindowFocusReleased:Connect(function() pressHeld, jumpTouch = false, nil end))
            refreshFall()
            jump:Clean(host.RunService.PreSimulation:Connect(function(): ()
                local opts = jump.Options
                local _, humanoid: Humanoid?, root: BasePart? = characterParts()
                if not humanoid or not root or humanoid.Health <= 0 then
                    clearFallController()
                    return
                end

                local canMove = canControlJump(humanoid) and not root.Anchored
                local fallMode: boolean = canMove and opts["Infinite jump"] and opts["Infinite jump"].Value
                    and opts["Infinite jump mode"].Value == "Fall"
                local state = humanoid:GetState()
                local grounded = humanoid.FloorMaterial ~= Enum.Material.Air
                    and state ~= Enum.HumanoidStateType.Jumping and state ~= Enum.HumanoidStateType.Freefall
                if grounded or fallBoosted ~= humanoid then clearFallController() end
                syncFallController(humanoid, fallMode and fallBoosted == humanoid)

                if opts["Custom jump power"] and opts["Custom jump power"].Value then
                    local wantedPower: number = opts["Jump power"] and opts["Jump power"].Value or 80
                    if originalJumpPower[humanoid] == nil then
                        originalJumpPower[humanoid] = {
                            jumpPower = humanoid.JumpPower,
                            useJumpPower = humanoid.UseJumpPower,
                        }
                    end
                    humanoid.UseJumpPower = true
                    humanoid.JumpPower = wantedPower
                    if wantedPower < 0 and state == Enum.HumanoidStateType.Jumping then
                        local curVel: Vector3 = (root :: BasePart).AssemblyLinearVelocity
                        ;(root :: BasePart).AssemblyLinearVelocity = Vector3.new(curVel.X, wantedPower, curVel.Z)
                    end
                else
                    restoreJumpPower()
                end

                if canMove and opts["Auto jump"] and opts["Auto jump"].Value then
                    local moveDir: Vector3 = humanoid.MoveDirection
                    if moveDir.Magnitude > 0.05 and humanoid.FloorMaterial ~= Enum.Material.Air then
                        humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
                    end
                end

                -- Long Jump: horizontal boost when jumping
                if canMove and longJumpEnabled and humanoid.FloorMaterial ~= Enum.Material.Air then
                    local moveDir: Vector3 = humanoid.MoveDirection
                    if moveDir.Magnitude > 0.05 then
                        local dir: Vector3 = moveDir * longJumpSpeed
                        if longJumpMode == "Velocity" then
                            root.AssemblyLinearVelocity = dir + Vector3.new(0, root.AssemblyLinearVelocity.Y, 0)
                        elseif longJumpMode == "Impulse" then
                            local diff: Vector3 = (dir - root.AssemblyLinearVelocity) * Vector3.new(1, 0, 1)
                            if diff.Magnitude > 2 then
                                root:ApplyImpulse(diff * root.AssemblyMass)
                            end
                        else -- CFrame
                            root.CFrame += dir * (1/60)
                        end
                    end
                end

                if canMove and opts["Infinite jump"] and opts["Infinite jump"].Value then
                    local mode: string = opts["Infinite jump mode"] and opts["Infinite jump mode"].Value or "Normal"
                    if mode == "Rise" and movementInput and type(movementInput.isJumpHeld) == "function" and movementInput.isJumpHeld() then
                        humanoid:ChangeState(Enum.HumanoidStateType.Freefall)
                        local curVel: Vector3 = (root :: BasePart).AssemblyLinearVelocity
                        local riseSpd: number = opts["Rise speed"] and opts["Rise speed"].Value or 75
                        ;(root :: BasePart).AssemblyLinearVelocity = Vector3.new(curVel.X, riseSpd, curVel.Z)
                    end
                end
            end))
        end,
    })

    jump:CreateToggle({
        Name = "Custom jump power",
        Default = false,
        Tooltip = "Enables custom jump height/power for ground jumps. Turn off if you only want Infinite Jump or High Jump.",
    })

    jump:CreateSlider({
        Name = "Jump power",
        Show = {Option = "Custom jump power", Values = {true}},
        Min = 1,
        Max = 250,
        Default = 80,
        Function = function(value: number): ()
            if jump.Enabled and jump.Options["Custom jump power"].Value then
                jump:SetStatus(tostring(math.round(value)))
            end
        end,
        Tooltip = "Character jump power (default Roblox jump is 50). Negative values launch the character downward.",
    })

    jump:CreateButton({
        Name = "High jump",
        Function = function(): ()
            local velocityVal: number = jump.Options["High jump velocity"] and jump.Options["High jump velocity"].Value or 72
            performHighJump(velocityVal)
        end,
        Tooltip = "Launches your character into a single massive vertical jump.",
    })

    jump:CreateSlider({
        Name = "High jump velocity",
        Min = 1,
        Max = 250,
        Default = 72,
        Tooltip = "Vertical velocity applied when High Jump button is pressed. Negative values launch the character downward.",
    })

    jump:CreateToggle({
        Name = "Infinite jump",
        Default = false,
        Function = refreshFall,
        Tooltip = "Allows jumping repeatedly in mid-air.",
    })

    jump:CreateDropdown({
        Name = "Infinite jump mode",
        Show = {Option = "Infinite jump", Values = {true}},
        List = {"Normal", "Rise", "Fall"},
        Function = refreshFall,
        Index = 1,
        Tooltip = "Normal = mid-air jump; Rise = hold to rise; Fall = normal ground jump, then Freefall for each extra mid-air press. Release jump between presses; holding does not repeat. Server behavior is not guaranteed.",
    })

    jump:CreateSlider({
        Name = "Infinite jump power",
        Show = {
            {Option = "Infinite jump", Values = {true}},
            {Option = "Infinite jump mode", Values = {"Normal", "Fall"}},
        },
        Min = 1,
        Max = 250,
        Default = 50,
        Tooltip = "Vertical impulse applied during mid-air jumps. Negative values push the character downward.",
    })

    jump:CreateSlider({
        Name = "Rise speed",
        Show = {
            {Option = "Infinite jump", Values = {true}},
            {Option = "Infinite jump mode", Values = {"Rise"}},
        },
        Min = 1,
        Max = 250,
        Default = 75,
        Tooltip = "Vertical speed while holding jump in Rise mode. Negative values descend instead of rising.",
    })

    jump:CreateSlider({
        Name = "Jump interval",
        Show = {
            {Option = "Infinite jump", Values = {true}},
            {Option = "Infinite jump mode", Values = {"Normal", "Fall"}},
        },
        Min = 0.05,
        Max = 0.6,
        Default = 0.18,
        Tooltip = "Minimum delay in seconds between mid-air jumps.",
    })

    jump:CreateToggle({
        Name = "Auto jump",
        Default = false,
        Tooltip = "Continuously jumps while walking on the ground.",
    })

    -- Long Jump: horizontal boost when jumping (from VapeV4)
    local longJumpEnabled = false
    local longJumpSpeed = 50
    local longJumpMode = "Velocity"

    jump:CreateToggle({
        Name = "Long jump",
        Default = false,
        Function = function(value: boolean): ()
            longJumpEnabled = value
        end,
        Tooltip = "Adds horizontal speed boost in your move direction when jumping.",
    })

    jump:CreateDropdown({
        Name = "Long jump mode",
        Show = {Option = "Long jump", Values = {true}},
        List = {"Velocity", "Impulse", "CFrame"},
        Index = 1,
        Function = function(value: string): ()
            longJumpMode = value
        end,
        Tooltip = "How the horizontal boost is applied: Velocity (smooth), Impulse (forces), or CFrame (direct position).",
    })

    jump:CreateSlider({
        Name = "Long jump speed",
        Show = {Option = "Long jump", Values = {true}},
        Min = 1,
        Max = 250,
        Default = 50,
        Function = function(value: number): ()
            longJumpSpeed = value
        end,
        Tooltip = "Horizontal boost speed in studs/second. Negative values boost backwards.",
    })

    activeCleanup = function(): ()
        if jump.Enabled then jump:Toggle(false) end
        restoreJumpPower()
        clearFallController()
    end
    Module.Initialized = true
    return jump
end

function Module.destroy(): ()
    if activeCleanup then
        pcall(activeCleanup)
    end
    activeCleanup = nil
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Movement/SafeWalk.lua"] = [[
export type Runtime = {
    framework: any,
    entity: any,
    host: any,
}

local Module = {
    Name = "Safe Walk",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local activeCleanup: (() -> ())? = nil

function Module.init(context: Runtime): any
    local host: any = context.host
    local TaskManager: any = host.TaskManager
    local featureConnections: any = host.featureConnections
    local disconnectFeatureConnection: any = host.disconnectFeatureConnection
    local getCharacterParts: any = host.getCharacterParts
    local createUniversalFeature: any = host.createUniversalFeature
    local addNumberOption: any = host.addNumberOption
    local currentWorkspace: Workspace = host.workspace or workspace

    local safeWalkSettings: {
        lookAhead: number,
        barrierHeight: number,
    } = {
        lookAhead = 2.8,
        barrierHeight = 4.5,
    }

    local barrierFolder: Folder? = nil
    local barrier: BasePart? = nil
    local SafeWalkFeature: any = nil

    -- Geometry rules (studs). A barrier closer than MIN_EDGE would sit inside the
    -- character's body, which pushes it back every frame; such edges are not guarded.
    -- A gap must be at least MIN_GAP wide to count as a drop, so stair treads and
    -- rail seams never place a barrier.
    local MIN_EDGE: number = 1.25
    local MIN_GAP: number = 1.5
    local PROBE_STEP: number = 0.5
    local PROBE_DEPTH: number = 6

    local function getBarrier(): BasePart
        local existing: BasePart? = barrier
        if existing and existing.Parent then
            return existing
        end
        if not barrierFolder or not barrierFolder.Parent then
            barrierFolder = Instance.new("Folder")
            barrierFolder.Name = "WurstSafeWalk"
            barrierFolder.Parent = currentWorkspace
        end
        local part: BasePart = Instance.new("Part")
        part.Name = "SafeWalkBarrier"
        part.Anchored = true
        part.CanCollide = false
        part.CanQuery = false
        part.CanTouch = false
        part.Massless = true
        part.CastShadow = false
        part.Transparency = 1
        part.Material = Enum.Material.SmoothPlastic
        part:SetAttribute("WurstSafeWalk", true)
        part.Parent = barrierFolder
        barrier = part
        return part
    end

    -- Turns the single barrier off in place: no destroy/recreate, so a part never
    -- appears on top of the character.
    local function releaseBarrier(): ()
        local existing: BasePart? = barrier
        if existing and existing.Parent then
            existing.CanCollide = false
        end
    end

    local function destroyBarrier(): ()
        if barrierFolder then
            barrierFolder:Destroy()
        end
        barrierFolder = nil
        barrier = nil
    end

    -- Distance along moveDirection to the last ground before a confirmed drop
    -- (a gap of at least MIN_GAP with no floor below). nil when none is ahead.
    local function findDrop(root: BasePart, moveDirection: Vector3, parameters: RaycastParams): number?
        -- Scan far enough to confirm a MIN_GAP-wide gap that starts inside the reach.
        local reach: number = 1.0 + safeWalkSettings.lookAhead + MIN_GAP
        local lastGround: number? = nil
        local groundBeforeGap: number? = nil
        local gapStart: number? = nil
        local distance: number = PROBE_STEP
        while distance <= reach do
            local ground: RaycastResult? = currentWorkspace:Raycast(
                root.Position + moveDirection * distance,
                Vector3.new(0, -PROBE_DEPTH, 0),
                parameters
            )
            if ground then
                lastGround = distance
                gapStart = nil
                groundBeforeGap = nil
            else
                if gapStart == nil then
                    gapStart = distance
                    groundBeforeGap = lastGround
                end
                if distance - gapStart >= MIN_GAP then
                    return groundBeforeGap
                end
            end
            distance += PROBE_STEP
        end
        return nil
    end

    local function toggleSafeWalk(enabled: boolean): ()
        disconnectFeatureConnection("SafeWalk")
        destroyBarrier()
        if not enabled then
            if SafeWalkFeature then
                SafeWalkFeature:SetStatus(nil)
            end
            return
        end

        featureConnections.SafeWalk = TaskManager:Connect(function(): ()
            local character: Model?, humanoid: Humanoid?, root: BasePart? = getCharacterParts()
            if not character or not humanoid or not root
                or humanoid.Health <= 0 then
                releaseBarrier()
                return
            end

            -- Jumping or falling is a deliberate choice to leave the ledge: the barrier
            -- is off for the whole airborne phase.
            local state = humanoid:GetState()
            if humanoid.FloorMaterial == Enum.Material.Air
                or state == Enum.HumanoidStateType.Jumping
                or state == Enum.HumanoidStateType.Freefall then
                releaseBarrier()
                return
            end

            local move: Vector3 = humanoid.MoveDirection
            local flat: Vector3 = Vector3.new(move.X, 0, move.Z)
            if flat.Magnitude < 0.05 then
                return
            end
            local moveDirection: Vector3 = flat.Unit

            local parameters: RaycastParams = RaycastParams.new()
            parameters.FilterType = Enum.RaycastFilterType.Exclude
            parameters.FilterDescendantsInstances = {character}
            parameters.IgnoreWater = true

            local edge: number? = findDrop(root :: BasePart, moveDirection, parameters)
            if edge == nil then
                releaseBarrier()
                if SafeWalkFeature then
                    SafeWalkFeature:SetStatus(nil)
                end
                return
            end

            if edge < MIN_EDGE then
                -- Already at the lip: keep whatever barrier was placed on approach,
                -- never place a new one this close.
                return
            end

            local part: BasePart = getBarrier()
            local barrierHeight: number = math.max(safeWalkSettings.barrierHeight, 3)
            local feetY: number = root.Position.Y - (root.Size.Y * 0.5 + humanoid.HipHeight)
            local center: Vector3 = root.Position + moveDirection * edge
            local wallCenter: Vector3 = Vector3.new(center.X, feetY + barrierHeight * 0.5, center.Z)
            part.Size = Vector3.new(7, barrierHeight, 0.35)
            part.CFrame = CFrame.lookAt(wallCenter, wallCenter + moveDirection)
            part.CanCollide = true
            if SafeWalkFeature then
                SafeWalkFeature:SetStatus("edge")
            end
        end)
    end

    SafeWalkFeature = createUniversalFeature(
        "Safe Walk",
        "Place an invisible barrier at edges so you cannot walk off ledges",
        21,
        toggleSafeWalk,
        {
            configKey = "Universal.SafeWalk",
            categoryName = "World",
        }
    )
    addNumberOption(
        SafeWalkFeature,
        "Edge look-ahead",
        safeWalkSettings.lookAhead,
        1.5,
        6,
        function(value: number): ()
            safeWalkSettings.lookAhead = value
        end
    )
    addNumberOption(
        SafeWalkFeature,
        "Barrier height",
        safeWalkSettings.barrierHeight,
        3,
        10,
        function(value: number): ()
            safeWalkSettings.barrierHeight = value
        end
    )

    activeCleanup = function(): ()
        disconnectFeatureConnection("SafeWalk")
        destroyBarrier()
    end
    Module.Initialized = true
    return SafeWalkFeature
end

function Module.destroy(): ()
    if activeCleanup then
        pcall(activeCleanup)
    end
    activeCleanup = nil
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Movement/Speed.lua"] = [[
export type Runtime = {framework: any, entity: any, host: any, services: any}

local Module = {Name = "Speed", PlaceId = 0, Events = {} :: {[string]: any}, Initialized = false}
local activeCleanup

function Module.init(context: Runtime): any
    local host, framework = context.host, context.framework
    local player, world = host.LocalPlayer, host.workspace or workspace
    local walk, vehicle, speed
    local teleportElapsed, lastMode = 0, nil

    local function parts()
        local character = player.Character
        return character, character and character:FindFirstChildOfClass("Humanoid"),
            character and character:FindFirstChild("HumanoidRootPart")
    end
    local function restoreWalk()
        if walk then
            if walk.humanoid.Parent and walk.humanoid.WalkSpeed == walk.applied then walk.humanoid.WalkSpeed = walk.base end
            walk = nil
        end
    end
    local function applyWalk(humanoid, value)
        if walk and walk.humanoid ~= humanoid then restoreWalk() end
        if not walk then walk = {humanoid=humanoid,base=humanoid.WalkSpeed} end
        if walk.applied and humanoid.WalkSpeed ~= walk.applied then walk.base = humanoid.WalkSpeed end
        -- Negative WalkSpeed inverts controls (Roblox legacy behavior)
        humanoid.WalkSpeed = value
        walk.applied = value
        -- When WalkSpeed is negative, invert the move direction by setting
        -- the Humanoid's MoveDirection opposite to input
        if value < 0 then
            local moveDir = humanoid.MoveDirection
            if moveDir and moveDir.Magnitude > 0.01 and type(humanoid.Move) == "function" then
                humanoid:Move(-moveDir, false)
            end
        end
    end
    local function write(record, object, property, value)
        local field = record[property]
        if not field then field = {base=object[property]}; record[property] = field end
        if field.applied ~= nil and object[property] ~= field.applied then field.base = object[property] end
        object[property], field.applied = value, value
    end
    local function restoreRecord(object, record)
        if not object.Parent then return end
        for property, field in pairs(record) do
            if object[property] == field.applied then object[property] = field.base end
        end
    end
    local function restoreVehicle()
        if not vehicle then return end
        if vehicle.connection then vehicle.connection:Disconnect() end
        for object, record in pairs(vehicle.properties) do restoreRecord(object,record) end
        vehicle = nil
    end
    local function resolveVehicle(humanoid, character)
        local seat = humanoid.SeatPart
        -- Passengers and characters standing on an assembly are not drivers.
        if not seat or not seat:IsA("VehicleSeat") or seat.Occupant ~= humanoid then return end
        local assembly = seat.AssemblyRootPart or seat
        if assembly:IsDescendantOf(character) then assembly = seat end
        if assembly.Anchored then return end
        local model = seat:FindFirstAncestorOfClass("Model")
        while model and not assembly:IsDescendantOf(model) do model = model:FindFirstAncestorOfClass("Model") end
        return seat, assembly, model
    end
    local function vehicleStep(humanoid, character)
        local seat, assembly, model = resolveVehicle(humanoid,character)
        if not seat then restoreVehicle(); return false end
        local opts, mode = speed.Options, speed.Options["Vehicle mode"].Value
        if vehicle and (vehicle.seat ~= seat or vehicle.model ~= model or vehicle.mode ~= mode or vehicle.assembly ~= assembly) then restoreVehicle() end
        if not vehicle then vehicle = {seat=seat,assembly=assembly,model=model,mode=mode,properties={}} end
        local function record(object)
            vehicle.properties[object] = vehicle.properties[object] or {}
            return vehicle.properties[object]
        end
        local multiplier = opts["Vehicle multiplier"].Value
        if mode == "Multiplier" then
            local captured = record(seat)
            local baseSpeed = captured.MaxSpeed and captured.MaxSpeed.base or seat.MaxSpeed
            local baseTorque = captured.Torque and captured.Torque.base or seat.Torque
            if captured.MaxSpeed and seat.MaxSpeed ~= captured.MaxSpeed.applied then baseSpeed = seat.MaxSpeed end
            if captured.Torque and seat.Torque ~= captured.Torque.applied then baseTorque = seat.Torque end
            write(captured,seat,"MaxSpeed",baseSpeed*multiplier)
            write(captured,seat,"Torque",baseTorque*multiplier)
        elseif mode == "Seat" then
            write(record(seat),seat,"MaxSpeed",opts["Vehicle speed value"].Value)
        elseif mode == "Velocity" then
            local throttle = math.clamp(seat.ThrottleFloat,-1,1)
            if math.abs(throttle) > 0.01 then
                local look = seat.CFrame.LookVector
                local flat = Vector3.new(look.X,0,look.Z)
                if flat.Magnitude > 0.001 then
                    local current = assembly.AssemblyLinearVelocity
                    local horizontal = flat.Unit * (opts["Vehicle speed value"].Value*throttle)
                    assembly.AssemblyLinearVelocity = Vector3.new(horizontal.X,current.Y,horizontal.Z)
                end
            end
        elseif mode == "Motors" and model then
            -- Discover once per vehicle. Newly added wheel motors are picked up
            -- by DescendantAdded, not by scanning the whole car every frame.
            if not vehicle.motors then
                vehicle.motors = {}
                local owner = vehicle
                local function discover(object)
                    if object:IsA("HingeConstraint") and object.ActuatorType == Enum.ActuatorType.Motor then owner.motors[object] = true end
                end
                for _, object in ipairs(model:GetDescendants()) do discover(object) end
                owner.connection = model.DescendantAdded:Connect(discover)
            end
            for motor in pairs(vehicle.motors) do
                if not motor.Parent or not motor:IsDescendantOf(model) or motor.ActuatorType ~= Enum.ActuatorType.Motor then
                    if vehicle.properties[motor] then restoreRecord(motor,vehicle.properties[motor]) end
                    vehicle.properties[motor], vehicle.motors[motor] = nil, nil
                    continue
                end
                local captured = record(motor)
                local angular = captured.AngularVelocity
                local base = angular and angular.base or motor.AngularVelocity
                if angular and motor.AngularVelocity ~= angular.applied then base = motor.AngularVelocity end
                if math.abs(seat.ThrottleFloat) < 0.01 then base = 0 end
                -- Store the controller's latest command, never multiply our
                -- previous write. Zero and reverse commands remain meaningful.
                if angular then angular.base = base end
                write(captured,motor,"AngularVelocity",base*multiplier)
                captured.AngularVelocity.base = base
                local torque = captured.MotorMaxTorque
                local baseTorque = torque and torque.base or motor.MotorMaxTorque
                if torque and motor.MotorMaxTorque ~= torque.applied then baseTorque = motor.MotorMaxTorque end
                write(captured,motor,"MotorMaxTorque",math.max(baseTorque,opts["Motor torque"].Value))
            end
        end
        return true
    end
    local function direction(humanoid)
        local move = humanoid.MoveDirection
        local flat = Vector3.new(move.X,0,move.Z)
        return flat.Magnitude > 1 and flat.Unit or flat
    end
    local function blocked(root, step)
        if step.Magnitude < 0.001 then return step end
        local params = RaycastParams.new()
        params.FilterType = Enum.RaycastFilterType.Exclude
        params.FilterDescendantsInstances = {player.Character}
        params.RespectCanCollide, params.IgnoreWater = true, true
        params.CollisionGroup = root.CollisionGroup
        if world.Blockcast then
            local hit = world:Blockcast(root.CFrame,root.Size*0.9,step,params)
            return hit and step.Unit*math.max(0,hit.Distance-0.1) or step
        end
        local hit = world:Raycast(root.Position,step,params)
        return hit and step.Unit*math.max(0,(hit.Position-root.Position).Magnitude-root.Size.Magnitude*0.5-0.1) or step
    end
    local function stepSpeed(dt)
        local character, humanoid, root = parts()
        if not humanoid or not root or humanoid.Health <= 0 then
            restoreWalk(); restoreVehicle()
            if speed.ClearSprint then speed.ClearSprint() end
            return
        end
        if not speed.Enabled and not speed.SprintHeld then restoreWalk(); restoreVehicle(); return end
        local seated = humanoid.SeatPart ~= nil or humanoid.Sit
        if speed.SprintFrame then speed.SprintFrame(speed.SprintHeld and not seated,root) end
        if seated then
            restoreWalk()
            if speed.Enabled and speed.Options["Vehicle speed"].Value then vehicleStep(humanoid,character) else restoreVehicle() end
            return
        end
        restoreVehicle()
        local fly = framework.GetModule and framework:GetModule("Fly")
        local state = humanoid:GetState()
        if root.Anchored or (fly and fly.Enabled) or state == Enum.HumanoidStateType.Climbing
            or state == Enum.HumanoidStateType.Swimming or state == Enum.HumanoidStateType.Physics
            or state == Enum.HumanoidStateType.PlatformStanding then restoreWalk(); return end
        local opts = speed.Options
        local mode = speed.Enabled and opts.Mode.Value or "WalkSpeed"
        local target = speed.Enabled and opts.Speed.Value or 0
        if speed.SprintHeld then target = math.max(target,30) end
        if mode ~= lastMode then restoreWalk(); teleportElapsed = 0; lastMode = mode end
        if mode == "WalkSpeed" then applyWalk(humanoid,target) else restoreWalk() end
        local move = direction(humanoid)
        if speed.Enabled and opts["Auto jump"].Value and move.Magnitude > 0.05 and humanoid.FloorMaterial ~= Enum.Material.Air then
            humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
        end
        if mode == "WalkSpeed" and target >= 0 then return end
        local velocity = root.AssemblyLinearVelocity
        if mode == "Velocity" or (mode == "WalkSpeed" and target < 0) then
            root.AssemblyLinearVelocity = Vector3.new(move.X*target,velocity.Y,move.Z*target)
        elseif mode == "Impulse" then
            local difference = Vector3.new(move.X*target-velocity.X,0,move.Z*target-velocity.Z)
            if difference.Magnitude > 0.001 then root:ApplyImpulse(difference*root.AssemblyMass) end
        elseif move.Magnitude > 0.001 then
            local elapsed = math.clamp(dt or 0,0,0.1)
            if mode == "Teleport" then
                teleportElapsed += elapsed
                local interval = opts["Burst delay"].Value
                if teleportElapsed < interval then return end
                teleportElapsed %= interval
                elapsed = interval
            end
            local speedDelta = target < 0 and (target - humanoid.WalkSpeed) or math.max(0, target - humanoid.WalkSpeed)
            local step = move * speedDelta * elapsed
            if opts["Wall check"].Value then step = blocked(root,step) end
            root.CFrame += step
        else teleportElapsed = 0 end
    end
    speed = framework.Categories.Exploits:CreateModule({
        Name="Speed",Category="Exploits",ConfigKey="Universal.Speed",Order=1,
        Tooltip="On-foot movement and driver-only vehicle controls.",
        Function=function(enabled)
            restoreWalk(); restoreVehicle(); teleportElapsed, lastMode = 0, nil
            if not enabled then
                if speed.ClearSprint then speed.ClearSprint() end
                speed:SetStatus(nil)
                if speed.SprintHeld then stepSpeed(0) end
                return
            end
            speed:Clean(function() restoreWalk(); restoreVehicle(); if speed.ClearSprint then speed.ClearSprint() end end)
            speed:Clean(host.RunService.PreSimulation:Connect(stepSpeed))
            speed:SetStatus(speed.Options.Mode.Value)
        end,
    })
    speed.SprintHeld = false
    speed.SetSprintHeld = function(held)
        speed.SprintHeld = held
        stepSpeed(0)
        if not held and speed.ClearSprint then speed.ClearSprint() end
    end
    speed.StepSprint = function(dt) if speed.SprintHeld and not speed.Enabled then stepSpeed(dt) end end
    local function changed()
        restoreWalk(); restoreVehicle(); teleportElapsed, lastMode = 0, nil
        if speed.Enabled then speed:SetStatus(speed.Options.Mode.Value) end
    end
    speed:CreateDropdown({Name="Mode",List={"WalkSpeed","Velocity","Impulse","CFrame","Teleport"},Index=1,Function=changed})
    speed:CreateSlider({Name="Speed",Min=1,Max=250,Default=32})
    speed:CreateToggle({Name="Wall check",Default=true,Show={Option="Mode",Values={"CFrame","Teleport"}}})
    speed:CreateSlider({Name="Burst delay",Min=0.05,Max=1,Default=0.2,Show={Option="Mode",Values={"Teleport"}}})
    speed:CreateToggle({Name="Auto jump",Default=false})
    speed:CreateToggle({Name="Vehicle speed",Default=false,Function=changed,
        Tooltip="Only the occupied driver VehicleSeat; never passengers or platforms."})
    speed:CreateDropdown({Name="Vehicle mode",List={"Multiplier","Motors","Velocity","Seat"},Index=1,Function=changed,
        Show={Option="Vehicle speed",Values={true}},
        Tooltip="Multiplier: native seat engine. Motors: active hinge controller. Velocity: throttle-directed chassis speed. Seat: absolute native speed limit."})
    speed:CreateSlider({Name="Vehicle multiplier",Min=1,Max=10,Default=2,Function=changed,
        Show={{Option="Vehicle speed",Values={true}},{Option="Vehicle mode",Values={"Multiplier","Motors"}}}})
    speed:CreateSlider({Name="Vehicle speed value",Min=1,Max=300,Default=80,
        Show={{Option="Vehicle speed",Values={true}},{Option="Vehicle mode",Values={"Velocity","Seat"}}},
        Tooltip="Vehicle speed in studs per second, independent of on-foot Speed."})
    speed:CreateSlider({Name="Motor torque",Min=1000,Max=250000,Default=50000,
        Show={{Option="Vehicle speed",Values={true}},{Option="Vehicle mode",Values={"Motors"}}}})
    speed:RefreshVisibility()
    activeCleanup = function()
        speed.SprintHeld = false
        if speed.Enabled then speed:Toggle(false) end
        restoreWalk(); restoreVehicle()
        if speed.ClearSprint then speed.ClearSprint() end
    end
    Module.Initialized = true
    return speed
end
function Module.destroy()
    if activeCleanup then activeCleanup(); activeCleanup = nil end
    Module.Initialized = false
end
return Module

]],
        ["src/games/universal/Other/AntiAfk.lua"] = [[
export type Runtime = {
    framework: any,
    entity: any,
    host: any,
}

local Module = {
    Name = "AntiAfk",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local activeCleanup: (() -> ())? = nil

function Module.init(context: Runtime): any
    local host: any = context.host
    local LocalPlayer: any = host.LocalPlayer
    local featureConnections: any = host.featureConnections
    local disconnectFeatureConnection: any = host.disconnectFeatureConnection
    local createUniversalFeature: any = host.createUniversalFeature
    local addFeatureTooltip: any = host.addFeatureTooltip

    -- Simulate one user input. The old build relied on a single legacy
    -- call (VirtualUser:CaptureController + ClickButton2 at (0,0)):
    -- on current clients the capture silently does nothing, so the
    -- handler ran, "worked", and the idle kick landed anyway. Every
    -- strategy is tried in order until one reports success, and a
    -- failure is never mistaken for a success again.
    local function pokeAfk(): boolean
        local camera: any = nil
        pcall(function(): ()
            camera = (host.workspace :: any).CurrentCamera
        end)
        local centre: Vector2 = Vector2.new(400, 300)
        if camera and camera.ViewportSize then
            centre = camera.ViewportSize / 2
        end

        -- Strategy 1: VirtualUser button press (the classic path, but
        -- as an explicit down/up instead of a corner click).
        local virtualUser: any = nil
        pcall(function(): ()
            virtualUser = (game :: any):GetService("VirtualUser")
        end)
        if virtualUser then
            local ok: boolean = pcall(function(): ()
                virtualUser:CaptureController()
                virtualUser:Button2Down(centre, camera and camera.CFrame)
                virtualUser:Button2Up(centre, camera and camera.CFrame)
            end)
            if ok then
                return true
            end
            local legacyOk: boolean = pcall(function(): ()
                virtualUser:ClickButton2(centre)
            end)
            if legacyOk then
                return true
            end
        end

        -- Strategy 2: VirtualInputManager mouse event at screen centre.
        local virtualInput: any = nil
        pcall(function(): ()
            virtualInput = (game :: any):GetService("VirtualInputManager")
        end)
        if virtualInput then
            local ok: boolean = pcall(function(): ()
                virtualInput:SendMouseButtonEvent(centre.X, centre.Y, 0, true, game, false)
                virtualInput:SendMouseButtonEvent(centre.X, centre.Y, 0, false, game, false)
            end)
            if ok then
                return true
            end
        end
        return false
    end

    local function toggleAntiAfk(enabled: boolean): ()
        disconnectFeatureConnection("AntiAFK")
        disconnectFeatureConnection("AntiAFKTimer")

        if not enabled then
            return
        end

        -- Reactive: Roblox warns through Idled shortly before the
        -- 20-minute kick. Answer it.
        featureConnections.AntiAFK = LocalPlayer.Idled:Connect(function(): ()
            pokeAfk()
        end)
        -- Proactive: never let the idle timer get anywhere near the
        -- kick in the first place. Simulated input every 150 s keeps
        -- the session "active" even if the Idled event never fires
        -- (it does not fire while some menus hold focus).
        local elapsed: number = 0
        featureConnections.AntiAFKTimer = host.TaskManager:Connect(
            function(deltaTime: number): ()
                elapsed += deltaTime
                if elapsed < 150 then
                    return
                end
                elapsed = 0
                pokeAfk()
            end
        )
    end

    local AntiAfkFeature = createUniversalFeature(
        "Anti AFK",
        "Simulate input before Roblox's idle kick (about every 2.5 minutes, and on the idle warning)",
        13,
        toggleAntiAfk,
        {
            noOptions = true,
            configKey = "Universal.AntiAFK",
            categoryName = "World",
        }
    )
    addFeatureTooltip(AntiAfkFeature, "Simulates a real input every ~150 seconds and "
        .. "answers Roblox's idle warning, so the 20-minute idle kick never lands. "
        .. "Tries VirtualUser first, then VirtualInputManager. Disconnects immediately when disabled.")

    activeCleanup = function(): ()
        disconnectFeatureConnection("AntiAFK")
        disconnectFeatureConnection("AntiAFKTimer")
    end
    Module.Initialized = true
    return AntiAfkFeature
end

function Module.destroy(): ()
    if activeCleanup then
        pcall(activeCleanup)
    end
    activeCleanup = nil
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Other/Disguise.lua"] = [[
--!strict
export type Runtime = {
    framework: any,
    host: any,
    services: any,
}

type AppearanceTemplate = {
    object: Instance,
    parent: Instance?,
}

type MeshTemplate = {
    part: MeshPart,
    meshId: string,
    textureId: string,
}

type AnimationTemplate = {
    animation: Animation,
    animationId: string,
}

type AppearanceSnapshot = {
    character: Model,
    items: {AppearanceTemplate},
    meshParts: {MeshTemplate},
    animations: {AnimationTemplate},
    emotes: any,
    equippedEmotes: any,
    scales: {[string]: number},
    -- The humanoid description's own animation fields at snapshot
    -- time, so restoring movements can undo a description-route
    -- apply exactly instead of only rewriting Animate ids.
    descAnimations: {[string]: number},
}

local Module = {
    Name = "Disguise",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local activeCard: any = nil

-- 78492 is the default disguise: a normal user avatar whose movement
-- animations come from Roblox's own set, which is also the fallback below.
local DEFAULT_USER_ID: number = 78492
-- Roblox's own R15 animation set, i.e. the IDs inside the default Animate
-- script. A HumanoidDescription stores 0 for "keep the default", so copying
-- only the non-zero fields would silently keep OUR animations on the
-- disguised avatar. Filling the gaps with these makes the disguise use the
-- same set the target actually sees.
local DEFAULT_ANIMATION_IDS: {[string]: {string}} = {
    idle = {"507766666", "507766951", "507766388"},
    walk = {"507777826"},
    run = {"507767714"},
    jump = {"507765000"},
    fall = {"507767968"},
    climb = {"507765644"},
    swim = {"507784897"},
    swimidle = {"507785072"},
}
-- Roblox's own R6 set, i.e. the IDs inside the classic R6 Animate script the
-- engine inserts on blocky rigs. The R15 IDs above are keyed to UpperTorso and
-- RightUpperArm, so an R6 body cannot play them at all: the Animate script
-- stops without an error and the character freezes in its rest pose. That is
-- the still avatar in the report, not a wrong idle.
local DEFAULT_ANIMATION_IDS_R6: {[string]: {string}} = {
    idle = {"180435571", "180435792"},
    walk = {"180426354"},
    run = {"180426354"},
    jump = {"125750702"},
    fall = {"180436148"},
    climb = {"180436334"},
}
-- Every id the R15 default set owns. A HumanoidDescription from an avatar that
-- never bought a pack is indistinguishable from one that asked for the R15
-- defaults, so this table is how an R6 body recognises "these are not mine".
local R15_DEFAULT_IDS: {[string]: boolean} = {}
for _, ids: {string} in pairs(DEFAULT_ANIMATION_IDS) do
    for _, id: string in ipairs(ids) do
        R15_DEFAULT_IDS[id] = true
    end
end
-- The mirror image: every id the R6 default set owns. R6 clips are the only
-- clips an R6 body may play, and R6 ids never belong in an R15 slot.
local R6_DEFAULT_IDS: {[string]: boolean} = {}
for _, ids: {string} in pairs(DEFAULT_ANIMATION_IDS_R6) do
    for _, id: string in ipairs(ids) do
        R6_DEFAULT_IDS[id] = true
    end
end
local SCALE_FIELDS: {string} = {
    "HeightScale",
    "WidthScale",
    "DepthScale",
    "HeadScale",
    "BodyTypeScale",
    "ProportionScale",
}
local BODY_PARTS: {[string]: boolean} = {
    Head = true,
    Torso = true,
    UpperTorso = true,
    LowerTorso = true,
    LeftArm = true,
    RightArm = true,
    LeftLeg = true,
    RightLeg = true,
    LeftUpperArm = true,
    LeftLowerArm = true,
    LeftHand = true,
    RightUpperArm = true,
    RightLowerArm = true,
    RightHand = true,
    LeftUpperLeg = true,
    LeftLowerLeg = true,
    LeftFoot = true,
    RightUpperLeg = true,
    RightLowerLeg = true,
    RightFoot = true,
}
local MOVEMENT_ANIMATIONS: {{descriptionField: string, scriptCategory: string}} = {
    {descriptionField = "IdleAnimation", scriptCategory = "idle"},
    {descriptionField = "WalkAnimation", scriptCategory = "walk"},
    {descriptionField = "RunAnimation", scriptCategory = "run"},
    {descriptionField = "JumpAnimation", scriptCategory = "jump"},
    {descriptionField = "ClimbAnimation", scriptCategory = "climb"},
    {descriptionField = "FallAnimation", scriptCategory = "fall"},
    {descriptionField = "SwimAnimation", scriptCategory = "swim"},
    {descriptionField = "SwimIdleAnimation", scriptCategory = "swimidle"},
    {descriptionField = "MoodAnimation", scriptCategory = "mood"},
}

function Module.init(context: Runtime): any
    local framework: any = context.framework
    local host: any = context.host
    local Players: Players = host.Players or (game :: any):GetService("Players")
    local LocalPlayer: Player = host.LocalPlayer or Players.LocalPlayer

    local cloned = setmetatable({}, {__mode = "k"}) :: {[Instance]: boolean}
    local disguisedItems = setmetatable({}, {__mode = "k"}) :: {[Instance]: boolean}
    local snapshot: AppearanceSnapshot? = nil
    local filteredCharacter: Model? = nil
    local filterConnection: RBXScriptConnection? = nil
    local generation: number = 0
    local restoring: boolean = false
    local emotesAppliedToHumanoid: boolean = false
    local animationOverrideApplied: boolean = false
    -- One notice per target: a pack authored for another rig says so once
    -- instead of on every re-apply.
    local foreignPackNotified: boolean = false
    -- Slots the last apply actually wrote; the status line repeats it.
    local lastAppliedSlotCount: number = 0
    local lastDroppedSlotCount: number = 0
    -- Forward declarations. The write path runs before the settle step is
    -- defined, and Lua resolves names at definition time: without these the
    -- calls would silently become globals.
    local stopPoseMirror: () -> () = function(): () end
    local playingAnimationTracks: (Humanoid?) -> {AnimationTrack} =
        function(): {AnimationTrack}
            return {}
        end
    -- Everything the target user exposes is cached the moment the avatar
    -- description is fetched: the movement animation slots and the emotes.
    -- Character mode applies the avatar but keeps this cache loaded, so the two
    -- toggles work instantly instead of fetching the avatar again.
    type TargetCache = {
        userId: number,
        slots: {[string]: any},
        emotes: any,
        equippedEmotes: any,
        -- "R6"/"R15" when the target is in the server, nil when they are only
        -- known by id. A description never says which rig its clips were
        -- authored for, so this is the only source for that fact.
        rig: string?,
    }
    local targetCache: TargetCache? = nil

    -- The checkbox restores its saved state from configData without calling
    -- back, so the module settings must be read from the same place. Without
    -- this, a saved OFF check would still apply the target's data.
    local function savedToggle(name: string, fallback: boolean): boolean
        local store: any = host.configData
        local states: any = store and store.states
        if type(states) ~= "table" then
            return fallback
        end
        local saved: any = states["Universal.Disguise." .. name:gsub("%W", "")]
        if type(saved) == "boolean" then
            return saved
        end
        return fallback
    end

    local settings = {
        mode = "Character",
        animationSpeed = 1,
        id = tostring(DEFAULT_USER_ID),
        useTargetMovementAnimations = savedToggle(
            "Use target movement animations",
            true
        ),
        showTargetEmotes = savedToggle("Show target emotes", true),
        showAdvanced = false,
        -- Slots of a bundle resolved by id at runtime (any official or
        -- UGC pack), kept for the session so mode switches and the
        -- movement toggle reuse them without resolving again.
        customPackSlots = (nil :: any),
        customPackName = (nil :: any),
        -- Per-slot clips picked from bundles under Show Advanced:
        -- scriptCategory -> rbxassetid string.
        customSlotIds = ({} :: any),
    }

    local function status(message: string): ()
        if activeCard then activeCard:SetStatus(message) end
    end
    local function notify(message: string): ()
        pcall(print, "[Wurst:Disguise] " .. message)
        if activeCard then pcall(activeCard.Notify, activeCard, message) end
    end

    local function isAppearanceItem(obj: Instance): boolean
        return obj:IsA("Accessory")
            or obj:IsA("ShirtGraphic")
            or obj:IsA("Shirt")
            or obj:IsA("Pants")
            or obj:IsA("BodyColors")
            or ((obj:IsA("Decal") or obj:IsA("Texture"))
                and string.lower(obj.Name) == "face")
    end

    local function isInsideCharacter(obj: Instance, character: Model): boolean
        local ok: boolean, result: any = pcall(function()
            return obj:IsDescendantOf(character)
        end)
        return ok and result == true
    end

    local function rebindAccessory(character: Model, accessory: Accessory): ()
        for _, descendant: Instance in ipairs(accessory:GetDescendants()) do
            if descendant:IsA("Weld") and descendant.Part1 then
                local part: Instance? = character:FindFirstChild(
                    descendant.Part1.Name
                )
                if part and part:IsA("BasePart") then
                    descendant.Part1 = part
                end
            elseif descendant:IsA("RigidConstraint")
                and descendant.Attachment1 then
                local attachment: Instance? = character:FindFirstChild(
                    descendant.Attachment1.Name,
                    true
                )
                if attachment and attachment:IsA("Attachment") then
                    descendant.Attachment1 = attachment
                end
            end
        end
    end

    local function destroySnapshot(): ()
        local current: AppearanceSnapshot? = snapshot
        snapshot = nil
        emotesAppliedToHumanoid = false
        animationOverrideApplied = false
        if current then
            for _, entry: AppearanceTemplate in ipairs(current.items) do
                pcall(entry.object.Destroy, entry.object)
            end
        end
    end

    local function getAppliedDescription(humanoid: Humanoid): (any?, boolean)
        local child: HumanoidDescription? = humanoid:FindFirstChildOfClass(
            "HumanoidDescription"
        ) :: HumanoidDescription?
        if not child then
            local waitOk: boolean, waited: any = pcall(function()
                return humanoid:WaitForChild("HumanoidDescription", 2)
            end)
            if waitOk and waited and waited:IsA("HumanoidDescription") then
                child = waited :: HumanoidDescription
            end
        end
        if child then
            return child, false
        end
        local ok: boolean, result: any = pcall(function()
            return humanoid:GetAppliedDescription()
        end)
        if ok and result then
            return result, true
        end
        return nil, false
    end

    local function cloneTable(value: any): any
        if type(value) ~= "table" then
            return value
        end
        local copy: any = {}
        for key: any, entry: any in pairs(value) do
            copy[key] = if type(entry) == "table" then table.clone(entry) else entry
        end
        return copy
    end

    local function readDescriptionEmotes(description: any): (any?, any?)
        local ok: boolean, emotes: any, equipped: any = pcall(function()
            return description:GetEmotes(), description:GetEquippedEmotes()
        end)
        if not ok or type(emotes) ~= "table" or type(equipped) ~= "table" then
            return nil, nil
        end
        return cloneTable(emotes), cloneTable(equipped)
    end

    local function applyDescriptionToHumanoid(
        humanoid: Humanoid,
        description: any
    ): (boolean, string?)
        local humanoidObject: any = humanoid
        local lastError: string = "ApplyDescription is unavailable."
        for _, methodName: string in ipairs({
            "ApplyDescriptionResetAsync",
            "ApplyDescriptionAsync",
            "ApplyDescriptionReset",
            "ApplyDescription",
        }) do
            local method: any = humanoidObject[methodName]
            if type(method) == "function" then
                local ok: boolean, result: any = pcall(
                    method,
                    humanoidObject,
                    description
                )
                if ok then
                    return true, nil
                end
                lastError = tostring(result)
            end
        end
        return false, lastError
    end

    local function setHumanoidEmotes(
        humanoid: Humanoid,
        emotes: any,
        equippedEmotes: any
    ): (boolean, string?)
        if type(emotes) ~= "table" or type(equippedEmotes) ~= "table" then
            return false, "The avatar description did not expose emote data."
        end
        local description: any, isTemporary: boolean = getAppliedDescription(humanoid)
        if not description then
            return false, "Could not read the current HumanoidDescription."
        end
        local setOk: boolean, setError: any = pcall(function()
            description:SetEmotes(cloneTable(emotes))
            description:SetEquippedEmotes(cloneTable(equippedEmotes))
        end)
        if not setOk then
            if isTemporary then
                pcall(description.Destroy, description)
            end
            return false, tostring(setError)
        end
        if not isTemporary then

            return true, nil
        end

        local applied: boolean, applyError: string? =
            applyDescriptionToHumanoid(humanoid, description)
        pcall(description.Destroy, description)
        return applied, applyError
    end

    local function captureSnapshot(
        character: Model,
        humanoid: Humanoid
    ): AppearanceSnapshot
        local items: {AppearanceTemplate} = {}
        local meshParts: {MeshTemplate} = {}
        local animations: {AnimationTemplate} = {}
        local scales: {[string]: number} = {}
        local descAnimations: {[string]: number} = {}
        local emotes: any = {}
        local equippedEmotes: any = {}

        for _, obj: Instance in ipairs(character:GetDescendants()) do
            if isAppearanceItem(obj) then
                local ok: boolean, copy: any = pcall(function()
                    return obj:Clone()
                end)
                if ok and copy then
                    copy.Parent = nil
                    table.insert(items, {
                        object = copy,
                        parent = obj.Parent,
                    })
                end
            elseif obj:IsA("MeshPart") and BODY_PARTS[obj.Name] then
                table.insert(meshParts, {
                    part = obj,
                    meshId = obj.MeshId,
                    textureId = obj.TextureID,
                })
            elseif obj:IsA("Animation") then
                local animate: Instance? = character:FindFirstChild("Animate")
                if animate and obj:IsDescendantOf(animate) then
                    table.insert(animations, {
                        animation = obj,
                        animationId = obj.AnimationId,
                    })
                end
            end
        end

        local description: any, isTemporary: boolean = getAppliedDescription(humanoid)
        if description then
            for _, field: string in ipairs(SCALE_FIELDS) do
                local ok: boolean, value: any = pcall(function()
                    return description[field]
                end)
                if ok and type(value) == "number" then
                    scales[field] = value
                end
            end
            for _, mapping in ipairs(MOVEMENT_ANIMATIONS) do
                local okField: boolean, fieldValue: any = pcall(function()
                    return description[mapping.descriptionField]
                end)
                if okField and type(fieldValue) == "number" then
                    descAnimations[mapping.descriptionField] = fieldValue
                end
            end
            local originalEmotes: any, originalEquipped: any =
                readDescriptionEmotes(description)
            if originalEmotes and originalEquipped then
                emotes = originalEmotes
                equippedEmotes = originalEquipped
            end
            if isTemporary then
                pcall(description.Destroy, description)
            end
        end

        return {
            character = character,
            items = items,
            meshParts = meshParts,
            animations = animations,
            emotes = emotes,
            equippedEmotes = equippedEmotes,
            scales = scales,
            descAnimations = descAnimations,
        }
    end

    local function ensureSnapshot(
        character: Model,
        humanoid: Humanoid
    ): AppearanceSnapshot
        if snapshot and snapshot.character == character then
            return snapshot
        end
        destroySnapshot()
        snapshot = captureSnapshot(character, humanoid)
        return snapshot
    end

    local function restartAnimateScript(animate: Instance): ()
        local scriptObject: any = animate
        local enabledOk: boolean, wasEnabled: any = pcall(function()
            return scriptObject.Enabled
        end)
        if enabledOk and type(wasEnabled) == "boolean" then
            if not wasEnabled then
                return
            end
            local disabledOk: boolean = pcall(function()
                scriptObject.Enabled = false
            end)
            if disabledOk then
                task.wait()
                pcall(function()
                    scriptObject.Enabled = wasEnabled
                end)
                task.wait()
                return
            end
        end

        local disabledOk: boolean, wasDisabled: any = pcall(function()
            return scriptObject.Disabled
        end)
        if disabledOk and type(wasDisabled) == "boolean" then
            local pauseOk: boolean = pcall(function()
                scriptObject.Disabled = true
            end)
            if pauseOk then
                task.wait()
                pcall(function()
                    scriptObject.Disabled = wasDisabled
                end)
                task.wait()
            end
        end
    end


    -- Used when "Use target movement animations" is turned off: restore only
    -- the Animate slots, leaving the current appearance/emotes untouched.
    local function restoreMovementAnimationsOnly(
        character: Model,
        humanoid: Humanoid?
    ): ()
        stopPoseMirror()
        local current: AppearanceSnapshot? = snapshot
        if not current or current.character ~= character
            or not animationOverrideApplied then
            return
        end
        -- Undo a description-route apply on the description itself,
        -- or the engine keeps serving the foreign clips no matter
        -- what the Animate slots say.
        if humanoid and current.descAnimations then
            local description: any, isTemporary: boolean =
                getAppliedDescription(humanoid)
            if description then
                local working: any = description
                if not isTemporary then
                    local cloneOk: boolean, clone: any = pcall(function(): any
                        return description:Clone()
                    end)
                    if cloneOk and clone then
                        working = clone
                        isTemporary = true
                    end
                end
                pcall(function(): ()
                    for field: string, asset: number in pairs(
                        current.descAnimations
                    ) do
                        working[field] = asset
                    end
                end)
                applyDescriptionToHumanoid(humanoid, working)
                if isTemporary then
                    pcall(function(): ()
                        working:Destroy()
                    end)
                end
            end
        end
        for _, entry: AnimationTemplate in ipairs(current.animations) do
            if isInsideCharacter(entry.animation, character) then
                pcall(function()
                    entry.animation.AnimationId = entry.animationId
                end)
            end
        end
        animationOverrideApplied = false
        local animate: Instance? = character:FindFirstChild("Animate")
        if not animate then
            return
        end
        if humanoid then
            local animator: Animator? = humanoid:FindFirstChildOfClass("Animator")
            if animator then
                local tracksOk: boolean, tracks: any = pcall(function()
                    return animator:GetPlayingAnimationTracks()
                end)
                if tracksOk and type(tracks) == "table" then
                    for _, track: AnimationTrack in ipairs(tracks) do
                        pcall(track.Stop, track)
                    end
                end
            end
        end
        restartAnimateScript(animate)
    end

    -- HumanoidDescription already stores the target's animation asset IDs
    -- (rbxassetid://numbers). Assigning them directly is instant and does not
    -- depend on game:GetObjects / InsertService, which are Studio or server
    -- only and are the reason the old button could hang on "Downloading...".
    local function animationIdFromValue(value: any): string?
        local number: number? = nil
        if type(value) == "number" and value > 0 then
            number = value
        elseif type(value) == "string" then
            local matched: string? = string.match(value, "%d+")
            if matched then
                number = tonumber(matched)
            end
        end
        if not number or number <= 0 then
            return nil
        end
        return "rbxassetid://" .. tostring(math.floor(number))
    end

    local function animationSlotsFromDescription(description: any): {[string]: any}
        local slots: {[string]: string} = {}
        for _, mapping in ipairs(MOVEMENT_ANIMATIONS) do
            local readOk: boolean, value: any = pcall(function()
                return description[mapping.descriptionField]
            end)
            local assetId: any = if readOk then value else nil
            local chosenId: string? = animationIdFromValue(assetId)
            if chosenId then
                slots[mapping.scriptCategory] = chosenId
            end
        end
        return slots
    end

    -- Which default set fits the body we are actually driving. An R15 table on
    -- an R6 rig is the failure mode behind the frozen avatar: the clips load
    -- but nothing plays, so the character keeps its rest pose forever.
    local function rigDefaultSlots(humanoid: Humanoid?): {[string]: any}
        local rig: any = nil
        if humanoid then
            pcall(function(): ()
                rig = (humanoid :: any).RigType
            end)
        end
        if rig == Enum.HumanoidRigType.R6 then
            return DEFAULT_ANIMATION_IDS_R6
        end
        return DEFAULT_ANIMATION_IDS
    end

    local function rigName(humanoid: Humanoid?): string?
        local rig: any = nil
        if humanoid then
            pcall(function(): ()
                rig = (humanoid :: any).RigType
            end)
        end
        if rig == Enum.HumanoidRigType.R6 then
            return "R6"
        end
        if rig == Enum.HumanoidRigType.R15 then
            return "R15"
        end
        return nil
    end

    local function belongsToDefaultSet(value: any, set: {[string]: boolean}): boolean
        local function owns(entry: any): boolean
            if type(entry) == "number" then
                entry = tostring(math.floor(entry))
            end
            if type(entry) ~= "string" then
                return false
            end
            local digits: string? = string.match(entry, "%d+")
            return digits ~= nil and set[digits] == true
        end
        if type(value) == "table" then
            if #value == 0 then
                return false
            end
            for _, entry: any in ipairs(value) do
                if not owns(entry) then
                    return false
                end
            end
            return true
        end
        return owns(value)
    end

    local function belongsToR15Defaults(value: any): boolean
        return belongsToDefaultSet(value, R15_DEFAULT_IDS)
    end

    local function belongsToR6Defaults(value: any): boolean
        return belongsToDefaultSet(value, R6_DEFAULT_IDS)
    end

    -- Gaps are filled with the set that matches the rig; a slot that only
    -- holds R15 default ids on an R6 body is treated as a gap.
    --
    -- A pack description never says which rig its clips were authored for, and
    -- every pack sold since 2016 is R15. An R6 body that receives those ids is
    -- handed to the engine's legacy retargeting, which bends the limbs and
    -- sinks the torso instead of refusing the clip: that is the broken pose in
    -- the report, and it only shows up with a non-default pack, because the
    -- default pack resolves to ids the body already plays. The target's rig is
    -- no defence: in an R6 game the target is R6 too, and their description
    -- still hands out R15 clips. The rule is therefore about the clips, not
    -- about the target: an R6 body only accepts the R6 set, and an R15 body
    -- refuses the R6 set. The second return value counts the pack slots that
    -- were dropped for being foreign, so the menu can say it instead of
    -- showing a mangled avatar in silence.
    local function resolvedAnimationSlots(
        slots: {[string]: any},
        humanoid: Humanoid?,
        _targetRig: string?
    ): ({[string]: any}, number)
        local defaults: {[string]: any} = rigDefaultSlots(humanoid)
        local isR6: boolean = defaults == DEFAULT_ANIMATION_IDS_R6
        local dropped: number = 0
        local resolved: {[string]: any} = {}
        for category: string, value: any in pairs(slots) do
            -- Only the body's own rig may be written into its Animate slots.
            -- On R6 that means the R6 default ids; on R15, anything that is
            -- not an R6 default id (pack clips included).
            local owned: boolean
            if isR6 then
                owned = belongsToR6Defaults(value)
            else
                owned = not belongsToR6Defaults(value)
            end
            if owned then
                resolved[category] = value
            elseif not belongsToR15Defaults(value) then
                -- Dropping the R15 defaults is not a loss: they equal the set
                -- the R6 body already had, which is why the default pack looks
                -- fine. Only real pack clips are worth telling the user about.
                dropped += 1
            end
        end
        for category: string, ids: any in pairs(defaults) do
            if resolved[category] == nil then
                resolved[category] = ids
            end
        end
        return resolved, dropped
    end

    local function writeAnimationSlots(
        animate: Instance,
        slots: {[string]: any}
    ): number
        local changedCount: number = 0
        for _, mapping in ipairs(MOVEMENT_ANIMATIONS) do
            local chosen: any = slots[mapping.scriptCategory]
            -- One ID for the whole category, or a list: idle has up to three
            -- variants and Roblox plays them in order, so a default set keeps
            -- all three instead of repeating the first.
            local ids: {string} = {}
            if type(chosen) == "table" then
                for _, value: any in ipairs(chosen) do
                    local id: string? = animationIdFromValue(value)
                    if id then table.insert(ids, id) end
                end
            else
                local id: string? = animationIdFromValue(chosen)
                if id then table.insert(ids, id) end
            end
            local category: Instance? = animate:FindFirstChild(mapping.scriptCategory)
            if #ids > 0 and category then
                local targets: {Animation} = {}
                if category:IsA("Animation") then
                    table.insert(targets, category)
                end
                for _, descendant: Instance in ipairs(category:GetDescendants()) do
                    if descendant:IsA("Animation") then
                        table.insert(targets, descendant)
                    end
                end
                for index: number, animation: Animation in ipairs(targets) do
                    local chosenId: string = #ids == 1
                        and ids[1]
                        or ids[math.min(index, #ids)]
                    if animation.AnimationId ~= chosenId then
                        local changed: boolean = pcall(function()
                            animation.AnimationId = chosenId
                        end)
                        if changed then
                            changedCount += 1
                        end
                    end
                end
            end
        end

        return changedCount
    end

    -- Write the resolved slots into the humanoid's DESCRIPTION (on a
    -- clone, then applied) and return how many fields were set. Kept
    -- as the fallback when the Animate slots cannot be written at all;
    -- as the primary route (v94) it reported success while the running
    -- script kept playing the previous pack.
    local function applySlotsViaDescription(
        humanoid: Humanoid,
        resolved: {[string]: any}
    ): number
        local description: any, isTemporary: boolean =
            getAppliedDescription(humanoid)
        if not description then
            return 0
        end
        local working: any = description
        if not isTemporary then
            local cloneOk: boolean, clone: any = pcall(function(): any
                return description:Clone()
            end)
            if cloneOk and clone then
                working = clone
                isTemporary = true
            end
        end
        local setCount: number = 0
        local setOk: boolean = pcall(function(): ()
            for _, mapping in ipairs(MOVEMENT_ANIMATIONS) do
                local chosen: any = resolved[mapping.scriptCategory]
                if type(chosen) == "table" then
                    chosen = chosen[1]
                end
                local digits: string? = chosen
                    and string.match(tostring(chosen), "%d+")
                    or nil
                local asset: number? = digits and tonumber(digits) or nil
                if asset and asset > 0 then
                    working[mapping.descriptionField] = asset
                    setCount += 1
                end
            end
        end)
        if not setOk or setCount == 0 then
            if isTemporary then
                pcall(function(): ()
                    working:Destroy()
                end)
            end
            return 0
        end
        local applied: boolean = applyDescriptionToHumanoid(
            humanoid,
            working
        )
        if isTemporary then
            pcall(function(): ()
                working:Destroy()
            end)
        end
        return applied and setCount or 0
    end

    -- Clip sanitization lives after refreshMeshPartSnapshot (it must
    -- wait on clip loads; the avatar-copy helpers above may not).
    -- Forward-declared here so applyAnimationSlots can call it.
    local sanitizedSlots: (
        humanoid: Humanoid,
        resolved: {[string]: any}
    ) -> ({[string]: any}, number) =
        function(_humanoid: Humanoid, resolved: {[string]: any}): ({[string]: any}, number)
            return resolved, 0
        end
    local invalidClipNotified: boolean = false

    -- What every caller uses: the target's clips are resolved against the rig
    -- and written into the Animate slots. The result is verified by
    -- settleMovementAnimations right after, which owns every wait and every
    -- fallback: copying an avatar must never block on an animation check.
    local function applyAnimationSlots(
        character: Model,
        humanoid: Humanoid,
        slots: {[string]: any},
        targetRig: string?
    ): number
        local animate: Instance? = character:FindFirstChild("Animate")
        if not animate then
            return 0
        end
        local resolved: {[string]: any}, dropped: number =
            resolvedAnimationSlots(slots, humanoid, targetRig)
        -- The status reports this: "0 slots" on its own looks like a failure
        -- even when the four foreign clips were refused on purpose.
        lastDroppedSlotCount = dropped
        if dropped > 0 and not foreignPackNotified then
            foreignPackNotified = true
            notify(
                "That pack's clips are not "
                    .. (rigName(humanoid) or "your rig")
                    .. " clips; your own animations stay."
            )
        end
        -- Nothing the engine refuses here may reach the description
        -- or the slots: sanitized first, rig defaults in their place.
        local sanitized: {[string]: any}, replacedClips: number =
            sanitizedSlots(humanoid, resolved)
        resolved = sanitized
        lastResolvedSlots = resolved
        if replacedClips > 0 and not invalidClipNotified then
            invalidClipNotified = true
            notify(
                tostring(replacedClips)
                    .. " of those animation slots cannot be used in "
                    .. "this game (the engine refuses the clips); "
                    .. "your rig's own clips fill them instead."
            )
        end
        -- The Animate slots are the write that demonstrably retargets
        -- the running script (packs switched correctly until v94).
        -- The description route stays as fallback for builds whose
        -- slots cannot be written: it reports success without changing
        -- what the script plays here, which is exactly the reported
        -- "I pick Mage and Ninja keeps playing" desync.
        local changedCount: number = writeAnimationSlots(animate, resolved)
        if changedCount == 0 then
            changedCount = applySlotsViaDescription(humanoid, resolved)
        end
        if changedCount == 0 then
            return 0
        end
        animationOverrideApplied = true
        for _, track: AnimationTrack in ipairs(playingAnimationTracks(humanoid)) do
            pcall(function(): ()
                track:Stop()
            end)
        end
        restartAnimateScript(animate)
        return changedCount
    end

    -- Runs as soon as a description is fetched, before anything is applied:
    -- this is the "load everything in the background" step. It only reads the
    -- description, so it can never touch or roll back the visible appearance.
    -- The target's own rig, when they are in the server. A description carries
    -- clip ids but never the rig those clips were authored for.
    local function targetRigFor(userId: number): string?
        local ok: boolean, player: any = pcall(function(): any
            return Players:GetPlayerByUserId(userId)
        end)
        if not ok or not player then
            return nil
        end
        local character: any = player.Character
        local humanoid: any = character and character:FindFirstChildOfClass("Humanoid")
        if not humanoid then
            return nil
        end
        return rigName(humanoid)
    end

    local function cacheTarget(userId: number, description: any): ()
        local emotes: any, equippedEmotes: any = readDescriptionEmotes(description)
        -- Only what the target actually chose. A 0 in a description means
        -- "use Roblox's default", and which default that is depends on OUR rig,
        -- so the gap is filled at apply time, never here.
        local slots: {[string]: any} = animationSlotsFromDescription(description)
        foreignPackNotified = false
        targetCache = {
            userId = userId,
            slots = slots,
            emotes = emotes,
            equippedEmotes = equippedEmotes,
            rig = targetRigFor(userId),
        }
    end

    local function refreshMeshPartSnapshot(
        character: Model,
        current: AppearanceSnapshot
    ): ()
        local originalByName: {[string]: {meshId: string, textureId: string}} = {}
        for _, entry: MeshTemplate in ipairs(current.meshParts) do
            originalByName[entry.part.Name] = {
                meshId = entry.meshId,
                textureId = entry.textureId,
            }
        end

        local refreshed: {MeshTemplate} = {}
        for _, obj: Instance in ipairs(character:GetDescendants()) do
            if obj:IsA("MeshPart") and BODY_PARTS[obj.Name] then
                local original: {meshId: string, textureId: string}? =
                    originalByName[obj.Name]
                table.insert(refreshed, {
                    part = obj,
                    meshId = original and original.meshId or obj.MeshId,
                    textureId = original and original.textureId or obj.TextureID,
                })
            end
        end
        if #refreshed > 0 then
            current.meshParts = refreshed
        end
    end

    -- Runs after the ids are written. The Animate script is restarted by the
    -- write itself, but a restart does not guarantee a playing track: the
    -- classic script only replays the idle loop from a Humanoid.Running event,
    -- and a body standing still never fires one. That is the frozen pose in
    -- the report. Here the body is checked, the idle is bridged when needed,
    -- and a rig that cannot play the target's clips gets its own set back
    -- instead of keeping a still avatar.
    playingAnimationTracks = function(humanoid: Humanoid?): {AnimationTrack}
        local playing: {AnimationTrack} = {}
        if not humanoid then
            return playing
        end
        local animator: Animator? = humanoid:FindFirstChildOfClass("Animator")
        if not animator then
            return playing
        end
        local ok: boolean, tracks: any = pcall(function(): any
            return animator:GetPlayingAnimationTracks()
        end)
        if not ok or type(tracks) ~= "table" then
            return playing
        end
        for _, track: AnimationTrack in ipairs(tracks) do
            local isPlaying: boolean = false
            pcall(function(): ()
                isPlaying = track.IsPlaying == true
            end)
            if isPlaying then
                table.insert(playing, track)
            end
        end
        return playing
    end

    -- The Animator writes every pose into Motor6D.Transform. A clip built for
    -- the OTHER rig never writes a joint: Roblox still hands back a track that
    -- reports IsPlaying, so `#playingAnimationTracks > 0` is not proof that the
    -- body moves. That gap is the frozen avatar reported with every target
    -- except the default one: a bought R15 pack on an R6 body "plays" forever
    -- without moving a single limb. Reading the joints is the only client-side
    -- way to tell a body that animates from one stuck in its rest pose.
    local function poseSignature(humanoid: Humanoid?): number?
        local character: Instance? = humanoid and humanoid.Parent
        if not character then
            return nil
        end
        local joints: number = 0
        local signature: number = 0
        for _, object: Instance in ipairs(character:GetDescendants()) do
            if object:IsA("Motor6D")
                or object:IsA("AnimationConstraint") then
                local ok: boolean, transform: CFrame = pcall(function(): CFrame
                    return (object :: any).Transform
                end)
                if ok and transform then
                    joints += 1
                    signature += transform.X * 13.17 + transform.Y * 7.31
                        + transform.Z * 3.77 + transform.R00 * 29.1
                        + transform.R11 * 17.3 + transform.R22 * 11.9
                end
            end
        end
        if joints == 0 then
            -- A rig we cannot read is not a rig we may accuse of being frozen.
            return nil
        end
        return signature
    end

    -- A clip holding a pose (the floating/hover idles UGC packs ship)
    -- barely moves a joint over time, but it still WRITES the joints:
    -- their Transforms sit away from identity. A clip built for the
    -- other rig never writes a joint at all, so its Transforms stay at
    -- identity forever. That is how a held pose counts as animation
    -- while a frozen wrong-rig clip still does not.
    local function poseDriven(humanoid: Humanoid?): boolean
        local character: Instance? = humanoid and humanoid.Parent
        if not character then
            return false
        end
        for _, object: Instance in ipairs(character:GetDescendants()) do
            if object:IsA("Motor6D")
                or object:IsA("AnimationConstraint") then
                local ok: boolean, transform: CFrame = pcall(function(): CFrame
                    return (object :: any).Transform
                end)
                if ok and transform then
                    if math.abs(transform.X) > 1e-4
                        or math.abs(transform.Y) > 1e-4
                        or math.abs(transform.Z) > 1e-4
                        or math.abs(transform.R00 - 1) > 1e-3
                        or math.abs(transform.R11 - 1) > 1e-3
                        or math.abs(transform.R22 - 1) > 1e-3 then
                        return true
                    end
                end
            end
        end
        return false
    end

    -- nil means "cannot tell" (no joints exposed), and callers must keep the
    -- old behaviour in that case. A fixed step count instead of a wall clock
    -- keeps the check from ever spinning when the scheduler is stubbed.
    local function poseMoves(humanoid: Humanoid?, seconds: number): boolean?
        local before: number? = poseSignature(humanoid)
        if before == nil then
            return nil
        end
        local steps: number = 5
        for _ = 1, steps do
            task.wait(seconds / steps)
            local after: number? = poseSignature(humanoid)
            if after == nil then
                return nil
            end
            if math.abs(after - before) > 1e-3 then
                return true
            end
        end
        return false
    end

    -- Clears the tracks, restarts the script and proves the body moves again.
    -- Returns false only when nothing plays, which is the signal to fall back
    -- to the rig's own clips instead of leaving a frozen character.
    local function activateAnimationOverride(
        character: Model,
        humanoid: Humanoid,
        animate: Instance
    ): boolean
        for _, track: AnimationTrack in ipairs(playingAnimationTracks(humanoid)) do
            pcall(function(): ()
                track:Stop()
            end)
        end
        restartAnimateScript(animate)
        task.wait(0.1)
        return #playingAnimationTracks(humanoid) > 0
    end

    -- Session cache of clip verdicts, and its one-time notice.
    -- A verdict is computed ONCE per id and never inside the Animate
    -- script's retry loop.
    local clipValidity: {[string]: boolean} = {}

    -- May the engine play this clip in this place? v95 probed by
    -- loading the clip, but the probe itself printed "Failed to load
    -- animation with sanitized ID ..." for every refused clip: quieter
    -- than the old retry spam, still noise the user has to read. This
    -- verdict never loads anything into an Animator:
    --   1. Catalog metadata condemns what is certainly unusable -- a
    --      deleted/private asset, or an id that is not an Animation at
    --      all (a bundle id pasted where a clip belongs).
    --   (A fetch probe was tried and removed: ContentProvider cannot
    --      download other creators' animation assets at all, so it
    --      condemned every foreign clip -- including packs already
    --      playing on screen. Metadata is the only honest judge.)
    -- Anything a probe cannot judge acquits: an unreadable answer must
    -- never punish a working pack.
    local function clipLoads(_humanoid: Humanoid, id: string): boolean
        local cached: boolean? = clipValidity[id]
        if cached ~= nil then
            return cached
        end
        local valid: boolean = true
        -- The rigs' own sets always play; skip the probes entirely.
        if belongsToR15Defaults(id) or belongsToR6Defaults(id) then
            clipValidity[id] = true
            return true
        end
        local digits: string? = string.match(id, "%d+")
        local assetId: number? = digits and tonumber(digits) or nil
        if assetId then
            local service: any = nil
            pcall(function(): ()
                service = (host :: any).MarketplaceService
                    or (game :: any):GetService("MarketplaceService")
            end)
            if service and type(service.GetProductInfo) == "function" then
                local infoOk: boolean, info: any = pcall(function(): any
                    return service:GetProductInfo(
                        assetId,
                        Enum.InfoType.Asset
                    )
                end)
                if not infoOk or type(info) ~= "table" then
                    -- Gone or private: every load would be refused too.
                    valid = false
                else
                    local assetType: any = info.AssetTypeId
                    if assetType ~= nil then
                        local isAnimation: boolean = false
                        pcall(function(): ()
                            if type(assetType) == "number" then
                                isAnimation = assetType
                                    == Enum.AssetType.Animation.Value
                            else
                                isAnimation = assetType
                                    == Enum.AssetType.Animation
                            end
                        end)
                        if not isAnimation then
                            valid = false
                        end
                    end
                end
            end
        end
        clipValidity[id] = valid
        return valid
    end

    -- Drop every clip the engine refuses here and fill the slot with
    -- the rig's own set BEFORE anything reaches the description or the
    -- Animate slots. An invalid id inside the Animate script is the
    -- console spam and the 64-track pile-up: the script retries the
    -- load forever and every retry is another track.
    sanitizedSlots = function(
        humanoid: Humanoid,
        resolved: {[string]: any}
    ): ({[string]: any}, number)
        local defaults: {[string]: any} = rigDefaultSlots(humanoid)
        local out: {[string]: any} = {}
        local replaced: number = 0
        for category: string, value: any in pairs(resolved) do
            local kept: {string} = {}
            local list: {any} = type(value) == "table"
                and value
                or {value}
            for _, entry: any in ipairs(list) do
                local id: string? = animationIdFromValue(entry)
                if id and clipLoads(humanoid, id) then
                    table.insert(kept, id)
                end
            end
            if #kept > 0 then
                out[category] = #kept == 1 and kept[1] or kept
            else
                replaced += 1
                out[category] = defaults[category]
            end
        end
        return out, replaced
    end


    local mirrorAllowed: boolean = false
    local lastResolvedSlots: {[string]: any}? = nil

    local function settleMovementAnimations(
        character: Model,
        humanoid: Humanoid
    ): boolean
        if not animationOverrideApplied then
            return false
        end
        local animate: Instance? = character:FindFirstChild("Animate")
        if not animate then
            return false
        end
        local tracks: number = #playingAnimationTracks(humanoid)
        if tracks > 0 then
            -- The script is playing something. Only a moving pose proves it
            -- belongs to this rig.
            if poseMoves(humanoid, 0.3) ~= false then
                return true
            end
            -- A loaded clip holding a pose is still an animation: the
            -- floating/hover idles UGC packs ship barely move a joint
            -- in 0.3 s, and reverting those to the default set is
            -- exactly the "the toggle gives me no animation" report.
            if poseDriven(humanoid) then
                return true
            end
        end
        -- Description retry, the offline-capable route: the ids came
        -- from the target's HumanoidDescription (they are not in this
        -- server to be read live), and a description's animations are
        -- loaded by the avatar pipeline when it is applied. It only
        -- counts if real tracks end up playing.
        if mirrorAllowed and lastResolvedSlots then
            local viaDescription: number =
                applySlotsViaDescription(humanoid, lastResolvedSlots)
            if viaDescription > 0 then
                restartAnimateScript(animate)
                task.wait(0.15)
                if #playingAnimationTracks(humanoid) > 0
                    and (poseMoves(humanoid, 0.3) ~= false
                        or poseDriven(humanoid)) then
                    notify(
                        "The target's animations were applied through "
                            .. "their avatar description."
                    )
                    return true
                end
            end
        end

        -- Pose mirror: copy the target's joints (AnimationConstraint
        -- on this rig). startPoseMirror verifies the copy actually
        -- lands on our body before it may claim success.
        if mirrorAllowed and startPoseMirror(character, humanoid) then
            return true
        end
        local defaults: {[string]: any} = rigDefaultSlots(humanoid)
        local isR6: boolean = defaults == DEFAULT_ANIMATION_IDS_R6
        if writeAnimationSlots(animate, defaults) > 0 then
            for _, track: AnimationTrack in ipairs(
                playingAnimationTracks(humanoid)
            ) do
                pcall(function(): ()
                    track:Stop()
                end)
            end
            restartAnimateScript(animate)
            task.wait(0.1)
            if #playingAnimationTracks(humanoid) > 0
                and poseMoves(humanoid, 0.3) ~= false then
                notify(
                    "Those clips do not play on your "
                        .. (isR6 and "R6" or "R15")
                        .. " rig; your rig's own set is back."
                )
                return true
            end
        end

        restoreMovementAnimationsOnly(character, humanoid)
        notify(
            "The target's animations do not play on your rig; "
                .. "your own animations are back."
        )
        return false
    end

    -- Animation mode also accepts an animation *bundle* id (the same thing
    -- Vape's Disguise accepts). A bundle item is a catalog entry, not always
    -- a playable AnimationId, so the asset is inspected when the executor
    -- exposes GetObjects; when it does not, the item id is used directly and
    -- the status says so instead of pretending the pack was loaded.
    local function animationAssetId(itemId: any): string?
        local normalizedId: string? = animationIdFromValue(itemId)
        if not normalizedId then
            return nil
        end
        if type((game :: any).GetObjects) == "function" then
            local ok: boolean, objects: any = pcall(function(): any
                return (game :: any):GetObjects(normalizedId)
            end)
            if ok and type(objects) == "table" then
                for _, object: any in ipairs(objects) do
                    if typeof(object) == "Instance" then
                        if object:IsA("Animation") then
                            local id: string? = animationIdFromValue(object.AnimationId)
                            if id then
                                return id
                            end
                        end
                        for _, descendant: Instance in ipairs(object:GetDescendants()) do
                            if descendant:IsA("Animation") then
                                local id: string? = animationIdFromValue(descendant.AnimationId)
                                if id then
                                    return id
                                end
                            end
                        end
                    end
                end
            end
        end
        return nil
    end

    -- Which Animate slot a bundle item belongs to, from its name.
    -- Official packs name items "Ninja Run" / "Run Animation"; UGC packs
    -- name them however the creator liked ("Endless Aura Floating Pack -
    -- Idle", "hover idle", "Swim (Idle)"), so matching is by keyword
    -- with the swim-idle pair resolved before plain idle can steal it.
    local function bundleItemCategory(rawName: any): string?
        local name: string = string.lower(tostring(rawName or ""))
        local hasSwim: boolean = string.find(name, "swim", 1, true) ~= nil
        local hasIdle: boolean = string.find(name, "idle", 1, true) ~= nil
        if hasSwim and hasIdle then
            return "swimidle"
        end
        if hasIdle then
            return "idle"
        end
        if string.find(name, "walk", 1, true) then
            return "walk"
        end
        if string.find(name, "run", 1, true) then
            return "run"
        end
        if string.find(name, "jump", 1, true) then
            return "jump"
        end
        if string.find(name, "climb", 1, true) then
            return "climb"
        end
        if string.find(name, "fall", 1, true) then
            return "fall"
        end
        if hasSwim then
            return "swim"
        end
        return nil
    end

    local function slotsFromBundleItems(items: any): {[string]: any}
        local slots: {[string]: any} = {}
        if type(items) ~= "table" then
            return slots
        end
        for _, item: any in ipairs(items) do
            if type(item) == "table" then
                -- Catalog endpoints do not all use the same casing or ID
                -- field. Resolve the item itself, not merely its position
                -- in the bundle, so a full bundle pasted into Walk always
                -- contributes its Walk clip (and likewise for every slot).
                local category: string? = bundleItemCategory(
                    item.Name or item.name or item.DisplayName
                        or item.displayName or item.Type or item.type
                )
                local itemId: any = item.Id or item.id
                    or item.AssetId or item.assetId
                if category and itemId then
                    local id: string? = animationAssetId(itemId)
                        or animationIdFromValue(itemId)
                    if id then
                        -- Several items can share a slot (idle variants):
                        -- keep them all, in order, like a description does.
                        local existing: any = slots[category]
                        if type(existing) == "table" then
                            table.insert(existing, id)
                        elseif existing ~= nil then
                            slots[category] = {existing, id}
                        else
                            slots[category] = id
                        end
                    end
                end
            end
        end
        return slots
    end

    -- Any animation bundle id -> its Animate slots, whether Roblox made
    -- the pack or a UGC creator did. Two sources, in order: the
    -- MarketplaceService product info (bundle items with names), then
    -- the public catalog API for the same bundle when the executor can
    -- HttpGet it. Nothing is downloaded and nothing is hardcoded per
    -- pack, which is the only way the thousands of UGC packs can work.
    local function bundleAnimationSlots(bundleId: number): ({[string]: any}?, string?)
        local service: any = (host :: any).MarketplaceService
            or (game :: any):GetService("MarketplaceService")
        local ok: boolean, product: any = pcall(function(): any
            return service:GetProductInfo(bundleId, Enum.InfoType.Bundle)
        end)
        if ok and type(product) == "table"
            and (product.BundleType == nil
                or product.BundleType == "AvatarAnimations")
            and type(product.Items) == "table" then
            local slots: {[string]: any} = slotsFromBundleItems(product.Items)
            if next(slots) ~= nil then
                return slots, nil
            end
        end
        local httpOk: boolean, body: any = pcall(function(): any
            return (game :: any):HttpGet(
                "https://catalog.roblox.com/v1/bundles/"
                    .. tostring(math.floor(bundleId)) .. "/details"
            )
        end)
        if httpOk and type(body) == "string" then
            local httpService: any = (game :: any):GetService("HttpService")
            local decodeOk: boolean, decoded: any = pcall(function(): any
                return httpService:JSONDecode(body)
            end)
            if decodeOk and type(decoded) == "table"
                and type(decoded.items) == "table" then
                local slots: {[string]: any} =
                    slotsFromBundleItems(decoded.items)
                if next(slots) ~= nil then
                    return slots, nil
                end
            end
        end
        if ok and type(product) == "table"
            and product.BundleType ~= nil
            and product.BundleType ~= "AvatarAnimations" then
            return nil, "That bundle is not an animation pack."
        end
        return nil, "That ID is not a user and no animation pack items were found for it."
    end


    -- The target's REAL slot ids, read from their own Animate script
    -- while they are in this server. A description is a catalog
    -- snapshot; the script riding their body holds the ids the engine
    -- actually loaded for them, which are the ones that play here
    -- (Probe 1 measured exactly those loading on our own Animator).
    local function targetAnimateSlots(userId: number): {[string]: any}?
        local player: any = nil
        pcall(function(): ()
            player = Players:GetPlayerByUserId(userId)
        end)
        local targetCharacter: any = player and player.Character
        local animate: any = targetCharacter
            and targetCharacter:FindFirstChild("Animate")
        if not animate then
            return nil
        end
        local slots: {[string]: any} = {}
        for _, mapping in ipairs(MOVEMENT_ANIMATIONS) do
            local container: any =
                animate:FindFirstChild(mapping.scriptCategory)
            local animation: any = nil
            if container then
                if container:IsA("Animation") then
                    animation = container
                else
                    for _, descendant: any in ipairs(
                        container:GetDescendants()
                    ) do
                        if descendant:IsA("Animation") then
                            animation = descendant
                            break
                        end
                    end
                end
            end
            if animation then
                local id: string? =
                    animationIdFromValue(animation.AnimationId)
                if id then
                    slots[mapping.scriptCategory] = id
                end
            end
        end
        if next(slots) == nil then
            return nil
        end
        return slots
    end

    -- Applies what was already cached for the current target. No fetch and no
    -- clone: turning a toggle back on is immediate.
    local function applyCachedMovementAnimations(
        character: Model,
        humanoid: Humanoid
    ): number
        local cached: TargetCache? = targetCache
        if not cached then
            return 0
        end
        local slots: {[string]: any} =
            targetAnimateSlots(cached.userId) or cached.slots
        local changedCount: number = applyAnimationSlots(
            character,
            humanoid,
            slots,
            cached.rig
        )
        -- Zero writes do not mean the body is fine: the ids may already be
        -- the frozen set from a previous apply, and re-selecting the same
        -- target has to settle it again instead of trusting the old state.
        if changedCount > 0 or animationOverrideApplied then
            mirrorAllowed = true
            settleMovementAnimations(character, humanoid)
            mirrorAllowed = false
        end
        return changedCount
    end

    -- Advanced packs use the same resolved animation path as a target's
    -- clips. Empty slots still fall back to the current rig's own set.
    local function selectedPackSlots(): {[string]: any}?
        return settings.customPackSlots
    end

    local function packDisplayName(): string
        return settings.customPackName or "Custom"
    end

    local function applyAnimationPack(
        character: Model,
        humanoid: Humanoid
    ): number
        stopPoseMirror()
        local slots: {[string]: any}? = selectedPackSlots()
        if not slots then
            return 0
        end
        local changedCount: number = applyAnimationSlots(
            character,
            humanoid,
            slots,
            nil
        )
        if changedCount > 0 or animationOverrideApplied then
            settleMovementAnimations(character, humanoid)
        end
        return changedCount
    end

    local function applyCachedEmotes(
        character: Model,
        humanoid: Humanoid
    ): boolean
        local cached: TargetCache? = targetCache
        local current: AppearanceSnapshot? = snapshot
        if not cached or not current or current.character ~= character then
            return false
        end
        if type(cached.emotes) ~= "table" or type(cached.equippedEmotes) ~= "table" then
            return false
        end
        local applied: boolean = setHumanoidEmotes(
            humanoid,
            cached.emotes,
            cached.equippedEmotes
        )
        if not applied then
            return false
        end
        emotesAppliedToHumanoid = true
        refreshMeshPartSnapshot(character, current)
        return true
    end

    -- Independent counterpart of restoreMovementAnimationsOnly: only the
    -- emotes go back to the snapshot, the avatar and the animations stay.
    local function restoreEmotesOnly(
        character: Model,
        humanoid: Humanoid?
    ): ()
        local current: AppearanceSnapshot? = snapshot
        if not humanoid or not current or current.character ~= character
            or not emotesAppliedToHumanoid then
            return
        end
        local restored: boolean = setHumanoidEmotes(
            humanoid,
            current.emotes,
            current.equippedEmotes
        )
        if restored then
            emotesAppliedToHumanoid = false
            refreshMeshPartSnapshot(character, current)
        end
    end

    local function restoreOriginalAppearance(
        character: Model,
        humanoid: Humanoid?
    ): ()
        local current: AppearanceSnapshot? = snapshot
        if not current or current.character ~= character then
            return
        end

        restoring = true
        if emotesAppliedToHumanoid and humanoid then
            local emotesRestored: boolean = setHumanoidEmotes(
                humanoid,
                current.emotes,
                current.equippedEmotes
            )
            if emotesRestored then
                emotesAppliedToHumanoid = false
                refreshMeshPartSnapshot(character, current)
            end
        end

        local removals: {Instance} = {}
        table.clear(disguisedItems)
        table.clear(cloned)
        for _, obj: Instance in ipairs(character:GetDescendants()) do
            if isAppearanceItem(obj) then
                table.insert(removals, obj)
            end
        end
        for _, obj: Instance in ipairs(removals) do
            pcall(obj.Destroy, obj)
        end

        for _, entry: MeshTemplate in ipairs(current.meshParts) do
            if isInsideCharacter(entry.part, character) then
                pcall(function()
                    entry.part.MeshId = entry.meshId
                    entry.part.TextureID = entry.textureId
                end)
            end
        end
        for _, entry: AnimationTemplate in ipairs(current.animations) do
            if isInsideCharacter(entry.animation, character) then
                pcall(function()
                    entry.animation.AnimationId = entry.animationId
                end)
            end
        end

        local restartRestoredAnimations: boolean = animationOverrideApplied
        animationOverrideApplied = false

        for _, entry: AppearanceTemplate in ipairs(current.items) do
            local ok: boolean, copy: any = pcall(function()
                return entry.object:Clone()
            end)
            if ok and copy then
                local parent: Instance = entry.parent or character
                if parent ~= character and not isInsideCharacter(parent, character) then
                    if (copy:IsA("Decal") or copy:IsA("Texture"))
                        and string.lower(copy.Name) == "face" then
                        parent = character:FindFirstChild("Head") or character
                    else
                        parent = character
                    end
                end
                if copy:IsA("Accessory") then
                    rebindAccessory(character, copy)
                end
                pcall(function()
                    copy.Parent = parent
                end)
            end
        end
        restoring = false
        if restartRestoredAnimations then
            local animate: Instance? = character:FindFirstChild("Animate")
            if animate then
                if humanoid then
                    local animator: Animator? = humanoid:FindFirstChildOfClass("Animator")
                    if animator then
                        local tracksOk: boolean, tracks: any = pcall(function()
                            return animator:GetPlayingAnimationTracks()
                        end)
                        if tracksOk and type(tracks) == "table" then
                            for _, track: AnimationTrack in ipairs(tracks) do
                                pcall(track.Stop, track)
                            end
                        end
                    end
                end
                restartAnimateScript(animate)
            end
        end
    end

    local function stopAppearanceFilter(): ()
        if filterConnection then
            pcall(filterConnection.Disconnect, filterConnection)
            filterConnection = nil
        end
        filteredCharacter = nil
    end

    local function removeUnexpectedAppearance(obj: Instance): ()
        if restoring
            or not isAppearanceItem(obj)
            or cloned[obj]
            or disguisedItems[obj]
            or not activeCard
            or not activeCard.Enabled
            or settings.mode ~= "Character" then
            return
        end
        task.defer(function(): ()
            if restoring
                or not activeCard
                or not activeCard.Enabled
                or settings.mode ~= "Character"
                or cloned[obj]
                or disguisedItems[obj] then
                return
            end
            pcall(obj.Destroy, obj)
        end)
    end

    local function installAppearanceFilter(character: Model): ()
        if filteredCharacter == character
            and filterConnection
            and filterConnection.Connected then
            return
        end
        stopAppearanceFilter()
        filteredCharacter = character
        filterConnection = character.DescendantAdded:Connect(
            removeUnexpectedAppearance
        )
        if activeCard then
            activeCard:Clean(filterConnection)
        end
    end

    local function parseId(): (number?, string?)
        local trimmed: string = tostring(settings.id)
            :gsub("^%s+", "")
            :gsub("%s+$", "")
        if trimmed == "" then
            return nil, "Enter a positive integer ID or username first."
        end
        local value: number? = tonumber(trimmed)
        if value and value > 0 and value % 1 == 0 then
            return value, nil
        end
        for _, p: Player in ipairs(Players:GetPlayers()) do
            if string.lower(p.Name) == string.lower(trimmed)
                or string.lower(p.DisplayName) == string.lower(trimmed) then
                return p.UserId, nil
            end
        end
        local ok: boolean, resolvedId: any = pcall(function()
            return Players:GetUserIdFromNameAsync(trimmed)
        end)
        if ok and type(resolvedId) == "number" and resolvedId > 0 then
            return resolvedId, nil
        end
        return nil, "Enter a positive integer ID or valid username."
    end

    local function getUserDescription(userId: number): (any?, string?)
        local playersObject: any = Players
        local asyncGetter: any = playersObject.GetHumanoidDescriptionFromUserIdAsync
        local syncGetter: any = playersObject.GetHumanoidDescriptionFromUserId
        if type(asyncGetter) == "function" then
            local ok: boolean, result: any = pcall(asyncGetter, playersObject, userId)
            if ok and result then
                return result, nil
            end
            if not ok then
                local asyncError: string = tostring(result)
                if type(syncGetter) ~= "function" then
                    return nil, asyncError
                end
            end
        end
        if type(syncGetter) == "function" then
            local ok: boolean, result: any = pcall(syncGetter, playersObject, userId)
            if ok and result then
                return result, nil
            end
            return nil, tostring(result)
        end
        return nil, "This client does not expose a HumanoidDescription lookup API."
    end

    local function stillCurrent(token: number, character: Model): boolean
        return generation == token
            and activeCard ~= nil
            and activeCard.Enabled
            and LocalPlayer.Character == character
    end

    local function setDescriptionScales(
        description: any,
        current: AppearanceSnapshot
    ): ()
        for _, field: string in ipairs(SCALE_FIELDS) do
            local value: number? = current.scales[field]
            if value ~= nil then
                pcall(function()
                    description[field] = value
                end)
            end
        end
    end

    local function copyCharacterAppearance(
        character: Model,
        clone: Model
    ): ()
        local realHead: Instance? = character:FindFirstChild("Head")
        for _, source: Instance in ipairs(clone:GetChildren()) do
            if isAppearanceItem(source) then
                cloned[source] = true
                disguisedItems[source] = true
                if source:IsA("Accessory") then
                    rebindAccessory(character, source)
                end
                source.Parent = character
            end
        end

        local targetFace: Instance? = clone:FindFirstChild("face", true)
        if targetFace and isAppearanceItem(targetFace) and realHead then
            cloned[targetFace] = true
            disguisedItems[targetFace] = true
            targetFace.Parent = realHead
        end

    end

    local function destroyInstance(instance: Instance?): ()
        if instance then
            pcall(instance.Destroy, instance)
        end
    end

    local function applyCharacterDisguise(
        token: number,
        character: Model,
        humanoid: Humanoid,
        userId: number
    ): ()
        lastDroppedSlotCount = 0
        local description: any, fetchError: string? = getUserDescription(userId)
        if not description then
            if stillCurrent(token, character) then
                notify("Could not load that avatar: " .. tostring(fetchError))
            end
            return
        end
        if not stillCurrent(token, character) then
            destroyInstance(description)
            return
        end

        -- Load the target's animations and emotes first. They stay cached even
        -- when both toggles are off, so the appearance copy below is the only thing the
        -- toggles can ever apply later without another fetch.
        cacheTarget(userId, description)
        local cached: TargetCache? = targetCache

        local current: AppearanceSnapshot = ensureSnapshot(character, humanoid)
        restoreOriginalAppearance(character, humanoid)
        setDescriptionScales(description, current)

        local oldArchivable: boolean = character.Archivable
        character.Archivable = true
        local cloneOk: boolean, cloneResult: any = pcall(function()
            return character:Clone()
        end)
        character.Archivable = oldArchivable
        if not cloneOk or not cloneResult then
            destroyInstance(description)
            notify("Could not stage the disguise character.")
            return
        end

        local clone: Model = cloneResult :: Model
        local parentOk: boolean = pcall(function()
            clone.Parent = game
        end)
        if not parentOk then
            destroyInstance(description)
            destroyInstance(clone)
            notify("Could not stage the disguise character in this client.")
            return
        end

        local cloneHumanoid: Humanoid? = clone:FindFirstChildOfClass("Humanoid")
        if not cloneHumanoid then
            destroyInstance(description)
            destroyInstance(clone)
            notify("The staged character has no Humanoid.")
            return
        end

        local applied: boolean, applyError: string? =
            applyDescriptionToHumanoid(cloneHumanoid, description)
        if not applied then
            destroyInstance(description)
            destroyInstance(clone)
            notify("Could not apply the avatar description: " .. tostring(applyError))
            return
        end
        if not stillCurrent(token, character) then
            destroyInstance(description)
            destroyInstance(clone)
            return
        end

        local emoteWarning: string? = nil
        if settings.showTargetEmotes then
            if cached and type(cached.emotes) == "table"
                and type(cached.equippedEmotes) == "table" then
                local emotesApplied: boolean, emoteError: string? = setHumanoidEmotes(
                    humanoid,
                    cached.emotes,
                    cached.equippedEmotes
                )
                if emotesApplied then
                    emotesAppliedToHumanoid = true
                    refreshMeshPartSnapshot(character, current)
                else
                    emoteWarning = tostring(emoteError)

                    local rolledBack: boolean = setHumanoidEmotes(
                        humanoid,
                        current.emotes,
                        current.equippedEmotes
                    )
                    if not rolledBack then
                        emotesAppliedToHumanoid = true
                        emoteWarning ..= " The original emotes could not be restored yet."
                    end
                end
            else
                emoteWarning = "The target avatar description did not expose emotes."
            end
        end
        if not stillCurrent(token, character) then
            if emotesAppliedToHumanoid then
                local rolledBack: boolean = setHumanoidEmotes(
                    humanoid,
                    current.emotes,
                    current.equippedEmotes
                )
                if rolledBack then
                    emotesAppliedToHumanoid = false
                end
            end
            destroyInstance(description)
            destroyInstance(clone)
            return
        end

        installAppearanceFilter(character)
        restoring = true
        local oldItems: {Instance} = {}
        for _, obj: Instance in ipairs(character:GetDescendants()) do
            if isAppearanceItem(obj) then
                table.insert(oldItems, obj)
            end
        end
        for _, obj: Instance in ipairs(oldItems) do
            pcall(obj.Destroy, obj)
        end
        restoring = false

        local copied: boolean, copyError: any = pcall(function()
            copyCharacterAppearance(character, clone)
        end)
        destroyInstance(clone)
        if not copied then
            destroyInstance(description)
            notify("The avatar was loaded, but some appearance parts could not be copied: "
                .. tostring(copyError))
            return
        end
        if not stillCurrent(token, character) then
            destroyInstance(description)
            return
        end
        activeCard:SetStatus("Character")
        if emoteWarning and settings.showTargetEmotes then
            notify("Disguise emotes could not be applied: " .. emoteWarning)
        end
        -- Movement animations are cosmetic and optional, so they run LAST and
        -- can never block or roll back the appearance copy above.
        if settings.useTargetMovementAnimations then
            local movementOk: boolean, movementResult: any = pcall(
                applyCachedMovementAnimations,
                character,
                humanoid
            )
            lastAppliedSlotCount = movementOk
                and (tonumber(movementResult) or 0)
                or 0
            if not movementOk then
                notify(
                    "The appearance was applied, but movement animations failed: "
                        .. tostring(movementResult)
                )
            end
        end
        if settings.customPackSlots ~= nil then
            local packOk: boolean, packResult: any = pcall(
                applyAnimationPack,
                character,
                humanoid
            )
            if packOk then
                lastAppliedSlotCount = tonumber(packResult) or 0
            end
        end
        destroyInstance(description)
        -- The rig and the number of slots are the two facts a report needs:
        -- "R6 · 0 slots" and "R15 · 7 slots" are different bugs.
        local applied: string = string.format(
            "%s · %s · %d slots",
            settings.mode,
            rigName(humanoid) or "rig?",
            lastAppliedSlotCount
        )
        if (lastDroppedSlotCount or 0) > 0 then
            applied ..= string.format(
                " · %d pack clips skipped",
                lastDroppedSlotCount or 0
            )
        end
        if settings.customPackSlots ~= nil then
            applied ..= " · pack " .. packDisplayName()
        end
        status(applied)
    end

    -- Animation mode: the same target user as Character mode, but only what
    -- moves on our own avatar. No clone, mesh, accessory or texture is copied:
    -- the character you already have must stay fully visible.
    local function applyAnimationDisguise(
        token: number,
        character: Model,
        humanoid: Humanoid,
        userId: number
    ): ()
        lastDroppedSlotCount = 0
        local bundleTarget: boolean = false
        local description: any, fetchError: string? = getUserDescription(userId)
        if description then
            if not stillCurrent(token, character) then
                destroyInstance(description)
                return
            end
            cacheTarget(userId, description)
        else
            -- Not a user: Animation mode also accepts an animation pack id.
            local slots: {[string]: any}?, bundleError: string? =
                bundleAnimationSlots(userId)
            if not slots then
                if stillCurrent(token, character) then
                    notify(
                        "Could not load that ID: " .. tostring(fetchError)
                            .. " " .. tostring(bundleError)
                    )
                end
                return
            end
            if not stillCurrent(token, character) then
                return
            end
            -- Keep the resolved pack in the session library: switching
            -- to Character mode (or its movement toggle) reuses these
            -- slots instead of resolving the bundle again.
            settings.customPackSlots = slots
            settings.customPackName = "Bundle " .. tostring(userId)
            bundleTarget = true
            targetCache = {
                userId = userId,
                slots = slots :: {[string]: any},
                emotes = nil,
                equippedEmotes = nil,
            }
        end
        local cached: TargetCache? = targetCache

        local current: AppearanceSnapshot = ensureSnapshot(character, humanoid)
        restoreOriginalAppearance(character, humanoid)
        stopAppearanceFilter()

        -- Animation mode is fixed: the target's emotes and movement animations
        -- always apply. Neither Character toggle exists in this mode.
        local emotesApplied: boolean = false
        if cached and type(cached.emotes) == "table"
            and type(cached.equippedEmotes) == "table" then
            local applied: boolean, emoteError: string? = setHumanoidEmotes(
                humanoid,
                cached.emotes,
                cached.equippedEmotes
            )
            if applied then
                emotesApplied = true
                emotesAppliedToHumanoid = true
                refreshMeshPartSnapshot(character, current)
            else
                notify(
                    "Disguise emotes could not be applied: "
                        .. tostring(emoteError)
                )
            end
        end

        local changedCount: number = applyCachedMovementAnimations(character, humanoid)
        if not bundleTarget and settings.customPackSlots ~= nil then
            local packCount: number = applyAnimationPack(character, humanoid)
            if packCount > 0 then
                changedCount = packCount
            end
        end
        destroyInstance(description)
        if not stillCurrent(token, character) then
            if emotesApplied then
                local rolledBack: boolean = setHumanoidEmotes(
                    humanoid,
                    current.emotes,
                    current.equippedEmotes
                )
                if rolledBack then
                    emotesAppliedToHumanoid = false
                end
            end
            return
        end
        if not emotesApplied and changedCount == 0 then
            notify("That avatar did not expose emotes or movement animations.")
            return
        end

        activeCard:SetStatus("Animation")
        local animationLine: string = string.format(
            "Animation · %s · emotes %s · %d slots",
            rigName(humanoid) or "rig?",
            emotesApplied and "applied" or "not available",
            changedCount
        )
        if (lastDroppedSlotCount or 0) > 0 then
            animationLine ..= string.format(
                " · %d pack clips skipped",
                lastDroppedSlotCount or 0
            )
        end
        if settings.customPackSlots ~= nil then
            animationLine ..= " · pack " .. packDisplayName()
        end
        status(animationLine .. ". Your own avatar stays visible.")
    end

    local function applyDisguise(): ()
        lastDroppedSlotCount = 0
        generation += 1
        local token: number = generation
        local character: Model? = LocalPlayer.Character
        local humanoid: Humanoid? = character
            and character:FindFirstChildOfClass("Humanoid")
            :: Humanoid?
        if not character or not humanoid or humanoid.Health <= 0 then
            notify("Your character is not ready yet.")
            return
        end
        local numericId: number?, idError: string? = parseId()
        if not numericId then
            notify(tostring(idError))
            return
        end

        local selectedMode: string = settings.mode
        -- A new application invalidates the previous target's cache. The fetch
        -- that follows repopulates it before anything is applied.
        targetCache = nil
        task.spawn(function(): ()
            if selectedMode == "Character" then
                applyCharacterDisguise(
                    token,
                    character :: Model,
                    humanoid :: Humanoid,
                    numericId :: number
                )
            else
                applyAnimationDisguise(
                    token,
                    character :: Model,
                    humanoid :: Humanoid,
                    numericId :: number
                )
            end
        end)
    end

    local function activeCharacter(): (any, any)
        local character: any = LocalPlayer.Character
        local humanoid: any = character
            and character:FindFirstChildOfClass("Humanoid")
        if not character or not humanoid then
            return nil, nil
        end
        return character, humanoid
    end

    -- Animation Speed: every playing track of our own character runs at
    -- this rate (0 freezes, 1 is normal, 2 is double). The Heartbeat
    -- below re-applies it, because the Animate script starts new tracks
    -- at speed 1 whenever the animation changes.
    local function applyAnimationSpeedValue(speed: number): ()
        local _character: any, humanoid: any = activeCharacter()
        if not humanoid then
            return
        end
        for _, track: AnimationTrack in ipairs(playingAnimationTracks(humanoid)) do
            pcall(function(): ()
                track:AdjustSpeed(speed)
            end)
        end
    end

    local function applyAnimationSpeed(): ()
        applyAnimationSpeedValue(settings.animationSpeed)
    end

    -- Character mode only. Both toggles are independent: one touches the
    -- Animate slots, the other the Humanoid emotes, and neither refetches the
    -- avatar because cacheTarget already loaded everything.
    local function setMovementAnimationsEnabled(enabled: boolean): ()
        settings.useTargetMovementAnimations = enabled
        if not activeCard or not activeCard.Enabled or settings.mode ~= "Character" then
            return
        end
        local character: any, humanoid: any = activeCharacter()
        if not character then
            return
        end
        if enabled then
            if not targetCache then
                applyDisguise()
                return
            end
            local appliedCount: number =
                applyCachedMovementAnimations(character, humanoid)
            if appliedCount == 0 and not animationOverrideApplied then
                -- The cache wrote nothing (the Animate slots already
                -- matched, or the snapshot belongs to another body):
                -- refetch and apply the whole disguise instead of
                -- leaving the character with no animation change.
                applyDisguise()
                return
            end
        else
            restoreMovementAnimationsOnly(character, humanoid)
        end
        status(settings.mode)
    end

    local function setTargetEmotesEnabled(enabled: boolean): ()
        settings.showTargetEmotes = enabled
        if not activeCard or not activeCard.Enabled or settings.mode ~= "Character" then
            return
        end
        local character: any, humanoid: any = activeCharacter()
        if not character then
            return
        end
        if enabled then
            if not targetCache then
                applyDisguise()
                return
            end
            if type(targetCache.emotes) ~= "table"
                or type(targetCache.equippedEmotes) ~= "table" then
                notify("That avatar did not expose emotes.")
                return
            end
            applyCachedEmotes(character, humanoid)
        else
            restoreEmotesOnly(character, humanoid)
        end
        status(settings.mode)
    end

    local function restoreAndRelease(): ()
        generation += 1
        applyAnimationSpeedValue(1)
        stopAppearanceFilter()
        local character: Model? = LocalPlayer.Character
        local humanoid: Humanoid? = character
            and character:FindFirstChildOfClass("Humanoid")
            :: Humanoid?
        if character then
            restoreOriginalAppearance(character, humanoid)
        end
        destroySnapshot()
        targetCache = nil
        table.clear(cloned)
        table.clear(disguisedItems)
    end

    local card: any
    card = framework.Categories.World:CreateModule({
        Name = "Disguise",
        Category = "World",
        ConfigKey = "Universal.Disguise",
        Order = 26,
        Tooltip = "Character: copies accessories, clothing, face, body colors and other compatible appearance items while keeping your own body, rig and scales. Emotes and movement animations have independent toggles. Animation: applies only animations/emotes to your own avatar, without hiding it. Default ID 78492.",
        Function = function(enabled: boolean): ()
            if enabled then
                card:SetStatus(settings.mode)
                -- Keep new tracks at the chosen speed: the Animate
                -- script starts each one at 1.
                local runService: any = host.RunService
                if not runService then
                    local ok: boolean, service: any = pcall(function(): any
                        return (game :: any):GetService("RunService")
                    end)
                    if ok then
                        runService = service
                    end
                end
                if runService and runService.Heartbeat then
                    local lastSpeedAt: number = 0
                    card:Clean(runService.Heartbeat:Connect(function(): ()
                        local now: number = os.clock()
                        if now - lastSpeedAt < 0.2 then
                            return
                        end
                        lastSpeedAt = now
                        applyAnimationSpeed()
                    end))
                end
                card:Clean(LocalPlayer.CharacterAdded:Connect(function(): ()
                    generation += 1
                    stopAppearanceFilter()
                    destroySnapshot()
                    task.wait(0.5)
                    if card.Enabled then
                        applyDisguise()
                    end
                end))
                applyDisguise()
            else
                restoreAndRelease()
                card:SetStatus(nil)
            end
        end,
    })

    card:CreateDropdown({
        Name = "Mode",
        List = {"Character", "Animation"},
        Index = 1,
        Function = function(value: string): ()
            settings.mode = value
            card:SetStatus(value)
            if card.Enabled then
                if value == "Animation" then
                    local character: Model? = LocalPlayer.Character
                    local humanoid: Humanoid? = character
                        and character:FindFirstChildOfClass("Humanoid")
                        :: Humanoid?
                    if character then
                        restoreOriginalAppearance(character, humanoid)
                    end
                    stopAppearanceFilter()
                end
                applyDisguise()
            end
        end,
        Tooltip = "Character: compatible appearance items on your preserved body/rig, plus independent emote and movement toggles. Animation: the same user ID's emotes and movement animations only, always on; your character stays exactly as it is.",
    })

    card:CreateSlider({
        Name = "Animation Speed",
        Min = 0,
        Max = 2,
        Step = 0.05,
        Default = settings.animationSpeed,
        Function = function(value: number): ()
            settings.animationSpeed = math.clamp(value, 0, 2)
            if card.Enabled then
                applyAnimationSpeed()
            end
        end,
        Tooltip = "Playback speed of your character's animations while Disguise is on: 0 freezes them, 1 is normal, 2 is double speed. Turning Disguise off restores speed 1.",
    })

    -- Show Advanced only reveals the bundle inputs. It never changes the
    -- current animations before the user actually submits a bundle ID.
    card:CreateToggle({
        Name = "Show Advanced",
        Default = settings.showAdvanced,
        Function = function(value: boolean): ()
            settings.showAdvanced = value
        end,
        Tooltip = "Shows bundle inputs for a complete pack or individual slots. Opening or closing these inputs does not change the animations already applied.",
    })

    card:CreateTextBox({
        Name = "Pack Bundle ID",
        Show = {Option = "Show Advanced", Values = {true}},
        Default = "",
        Function = function(value: string): ()
            local trimmed: string = tostring(value or "")
                :gsub("^%s+", "")
                :gsub("%s+$", "")
            local digits: string? = string.match(trimmed, "%d+")
            local bundleId: number? = digits and tonumber(digits) or nil
            if not bundleId then
                notify("Enter an animation bundle ID first (the number in its catalog link).")
                return
            end
            -- Any pack at all -- official or UGC -- resolved live from
            -- the bundle's own items, so the thousands of creator packs
            -- work without a single hardcoded id.
            local slots: {[string]: any}?, bundleError: string? =
                bundleAnimationSlots(bundleId)
            if not slots then
                notify("Could not load that pack: " .. tostring(bundleError))
                return
            end
            settings.customPackSlots = slots
            settings.customPackName = "Bundle " .. tostring(bundleId)
            table.clear(settings.customSlotIds)
            if not card.Enabled then
                notify("Pack " .. tostring(bundleId) .. " loaded; it applies while Disguise is on.")
                return
            end
            local character: Model? = LocalPlayer.Character
            local humanoid: Humanoid? = character
                and character:FindFirstChildOfClass("Humanoid")
                :: Humanoid?
            if character and humanoid then
                applyAnimationPack(character, humanoid)
                status(settings.mode .. " · pack Bundle " .. tostring(bundleId))
            end
        end,
        Tooltip = "Any animation pack bundle ID from its catalog link (roblox.com/bundles/<id>/...), official or UGC -- for example 4899847411546. The bundle's items are resolved when you enter it (nothing is downloaded; the engine streams the clips) and the pack is kept for the session. It wins over the target's movement animations. R15-only clips are not forced onto an incompatible R6 body.",
    })

    -- Per-slot bundle inserts: paste any pack's bundle ID into a slot
    -- and that slot takes the pack's clip for it (Idle from one pack,
    -- Run from another, ...). Slots left empty fall back to your rig's
    -- own set when the pack applies.
    local SLOT_INSERTS: {{string}} = {
        {"Idle", "idle"},
        {"Walk", "walk"},
        {"Run", "run"},
        {"Jump", "jump"},
        {"Fall", "fall"},
        {"Climb", "climb"},
        {"Swim", "swim"},
        {"Swim Idle", "swimidle"},
    }
    for _, slotInsert: {string} in ipairs(SLOT_INSERTS) do
        local label: string = slotInsert[1]
        local category: string = slotInsert[2]
        card:CreateTextBox({
            Name = label .. " Bundle ID",
            Show = {Option = "Show Advanced", Values = {true}},
            Default = "",
            Function = function(value: string): ()
                local digits: string? = string.match(
                    tostring(value or ""),
                    "%d+"
                )
                local bundleId: number? = digits and tonumber(digits)
                    or nil
                if not bundleId then
                    notify("Enter a bundle ID for the " .. label .. " slot first.")
                    return
                end
                local slots: {[string]: any}?, bundleError: string? =
                    bundleAnimationSlots(bundleId)
                if not slots then
                    notify("Could not load that pack: " .. tostring(bundleError))
                    return
                end
                local clip: any = slots[category]
                if type(clip) == "table" then
                    clip = clip[1]
                end
                if not clip then
                    notify("That bundle has no " .. label .. " clip to take.")
                    return
                end
                settings.customSlotIds[category] = clip
                local merged: {[string]: any} = {}
                for mergedCategory: string, mergedId: any in pairs(
                    settings.customSlotIds
                ) do
                    merged[mergedCategory] = mergedId
                end
                settings.customPackSlots = merged
                settings.customPackName = "Custom slots"
                if not card.Enabled then
                    notify(label .. " slot set; it applies while Disguise is on.")
                    return
                end
                local character: Model? = LocalPlayer.Character
                local humanoid: Humanoid? = character
                    and character:FindFirstChildOfClass("Humanoid")
                    :: Humanoid?
                if character and humanoid then
                    applyAnimationPack(character, humanoid)
                    status(settings.mode .. " · pack Custom slots")
                end
            end,
            Tooltip = "Set the " .. label .. " slot from any animation pack: paste the pack's bundle ID (official or UGC) and this slot takes that pack's " .. label .. " clip. Mix slots from different packs freely; empty slots use your rig's own set.",
        })
    end

    card:CreateToggle({
        Name = "Use target movement animations",
        -- Character only: Animation mode always applies them and has no control.
        Show = {Option = "Mode", Values = {"Character"}},
        Default = settings.useTargetMovementAnimations,
        Function = function(value: boolean): ()
            setMovementAnimationsEnabled(value)
        end,
        Tooltip = "Character mode only. Shows the target user's movement animations (idle, walk, run, jump, climb, fall, swim, and Roblox's default set for any slot the avatar leaves empty) on the disguised avatar. They are already loaded, so this is instant; turning it off restores your own animations. Emotes are independent and stay untouched.",
    })

    card:CreateTextBox({
        Name = "Target ID",
        Default = settings.id,
        Function = function(value: string): ()
            local trimmed: string = tostring(value or "")
                :gsub("^%s+", "")
                :gsub("%s+$", "")
            if trimmed == "" then
                notify("Enter a user ID or animation bundle ID first.")
                return
            end
            settings.id = trimmed
            if card.Enabled then
                applyDisguise()
            end
        end,
        Tooltip = "User ID (Character copies compatible appearance items without replacing your body/rig; Animation copies only emotes and movement animations) or an animation pack ID in Animation mode. Default 78492. Missing animation slots fall back to your rig's own set.",
    })

    card:CreateToggle({
        Name = "Show target emotes",
        -- Character only: Animation mode always applies the target's emotes.
        Show = {Option = "Mode", Values = {"Character"}},
        Default = settings.showTargetEmotes,
        Function = function(value: boolean): ()
            setTargetEmotesEnabled(value)
        end,
        Tooltip = "Character mode only. Shows the target user's emotes and equipped emote slots on the disguised avatar. Independent from movement animations; turning it off restores your own emotes without touching the disguise.",
    })

    activeCard = card
    Module.Initialized = true
    return card
end

function Module.destroy(): ()
    if activeCard then
        if activeCard.Enabled then
            pcall(activeCard.Toggle, activeCard, false)
        end
        activeCard = nil
    end
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Other/ImproveFps.lua"] = [[
export type Runtime = {
    framework: any,
    entity: any,
    host: any,
}

local Module = {
    Name = "ImproveFps",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local activeCleanup: (() -> ())? = nil

function Module.init(context: Runtime): any
    local host: any = context.host
    local featureConnections: any = host.featureConnections
    local disconnectFeatureConnection: any = host.disconnectFeatureConnection
    local createUniversalFeature: any = host.createUniversalFeature
    local addToggleOption: any = host.addToggleOption

    local fpsSettings: {[string]: boolean} = {
        textures = true,
        particles = true,
        shadows = true,
        materials = false,
        lighting = false,
        post = false,
        guiEffects = false,
        worldGui = false,
        gameGui = false,
        coreGui = false,
        geometry = false,
        scenery = false,
        quality = false,
        terrain = false,
        lights = false,
    }
    local fpsModeEnabled: boolean = false
    local generation: number = 0
    local ImproveFpsFeature: any = nil
    local function selectedEffectCount(): number
        local count: number = 0
        for _name: string, selected: boolean in pairs(fpsSettings) do
            if selected then count += 1 end
        end
        return count
    end

    local fpsVisualCache: any = {}
    local propertyWatches: {[any]: any} = {}

    local function cacheFpsProperty(object: any, property: string): ()
        local data: any = fpsVisualCache[object]
        if not data then
            data = {}
            fpsVisualCache[object] = data
            -- Keep snapshots strongly until OFF (even detached objects).
            -- Destroyed objects cannot be restored and must not accumulate.
            local ok, connection = pcall(function()
                return object.Destroying:Connect(function()
                    fpsVisualCache[object] = nil
                    local watch = propertyWatches[object]
                    propertyWatches[object] = nil
                    if watch then watch:Disconnect() end
                end)
            end)
            if ok then propertyWatches[object] = connection end
        end
        if data[property] == nil then
            data[property] = object[property]
        end
    end

    local lighting: any = host.Lighting
    local playerGui: any = host.PlayerGui
    local scenery: {[any]: boolean} = setmetatable({}, {__mode = "k"})
    local coreGuiCache: {[any]: boolean} = {}
    local function setProperty(object: any, property: string, value: any): ()
        -- Individual protected writes: an unsupported property must not
        -- prevent the remaining optimizations on that object.
        pcall(function()
            cacheFpsProperty(object, property)
            object[property] = value
        end)
    end
    local function protectedGui(object: any): boolean
        local current = object
        while current do
            if current == host.ScreenGui or current.Name == "TouchGui"
                or current.Name == "Chat" or current.Name == "BubbleChat" then return true end
            current = current.Parent
            if type(current) ~= "table" and typeof(current) ~= "Instance" then break end
        end
        return false
    end
    local function updateScenery(part: any): ()
        local character = host.LocalPlayer and host.LocalPlayer.Character
        local root = character and character:FindFirstChild("HumanoidRootPart")
        local cached = fpsVisualCache[part]
        local function restorePart()
            if cached and cached.LocalTransparencyModifier ~= nil then
                pcall(function() part.LocalTransparencyModifier = cached.LocalTransparencyModifier end)
            end
        end
        if not root or not part.Parent or not part.Anchored or not part.CanCollide then restorePart(); return end
        -- Static map only. Never cull characters, tools, or physics objects.
        local current = part.Parent
        while current and current ~= workspace do
            if current:IsA("Tool") or current:IsA("Accessory")
                or current:FindFirstChildOfClass("Humanoid") then restorePart(); return end
            current = current.Parent
        end
        local far = (part.Position - root.Position).Magnitude > 350
        if far then setProperty(part, "LocalTransparencyModifier", 1)
        elseif cached and cached.LocalTransparencyModifier ~= nil then
            pcall(function() part.LocalTransparencyModifier = cached.LocalTransparencyModifier end)
        end
    end

    local function applyFpsObject(object: Instance): ()
        -- A deferred DescendantAdded callback can arrive after destruction.
        -- Keep existing detached snapshots for restoration, but never acquire
        -- new ownership of an object already outside the scene.
        if object ~= workspace and object ~= lighting and object ~= playerGui and object.Parent == nil then return end
        local target: any = object
        if lighting and object == lighting and fpsSettings.lighting then
            setProperty(object, "EnvironmentDiffuseScale", 0)
            setProperty(object, "EnvironmentSpecularScale", 0)
        end
        if fpsSettings.shadows and object == lighting then setProperty(object, "GlobalShadows", false) end
        if fpsSettings.lights and object:IsA("Light") then setProperty(object, "Enabled", false) end
        if fpsSettings.terrain and object:IsA("Terrain") then
            setProperty(object, "Decoration", false)
            setProperty(object, "WaterWaveSize", 0)
            setProperty(object, "WaterWaveSpeed", 0)
            setProperty(object, "WaterReflectance", 0)
        end
        if fpsSettings.post and object:IsA("PostEffect") then
            setProperty(object, "Enabled", false)
        end
        if not protectedGui(object) then
            if fpsSettings.guiEffects and (object:IsA("UIStroke") or object:IsA("UIGradient")) then
                setProperty(object, "Enabled", false)
            elseif fpsSettings.guiEffects and object:IsA("ViewportFrame") then
                setProperty(object, "Visible", false)
            end
            if fpsSettings.worldGui and (object:IsA("BillboardGui") or object:IsA("SurfaceGui")) then
                setProperty(object, "Enabled", false)
            end
            if fpsSettings.gameGui and object:IsA("ScreenGui") then
                setProperty(object, "Enabled", false)
            end
        end
        if fpsSettings.geometry and (object:IsA("MeshPart") or object:IsA("PartOperation")) then
            setProperty(object, "RenderFidelity", Enum.RenderFidelity.Performance)
        end
        if fpsSettings.scenery and object:IsA("BasePart") and object.Anchored and object.CanCollide then
            scenery[object] = true
            updateScenery(object)
        end
        if fpsSettings.textures and (object:IsA("Decal") or object:IsA("Texture")) then
            cacheFpsProperty(object, "Transparency")
            target.Transparency = 1
        elseif fpsSettings.textures and object:IsA("MeshPart") then
            setProperty(object, "TextureID", "")
        elseif fpsSettings.textures and object:IsA("SpecialMesh") then
            setProperty(object, "TextureId", "")
        end

        if fpsSettings.particles
            and (object:IsA("ParticleEmitter")
                or object:IsA("Trail")
                or object:IsA("Beam")
                or object:IsA("Smoke")
                or object:IsA("Fire")
                or object:IsA("Sparkles")) then
            cacheFpsProperty(object, "Enabled")
            target.Enabled = false
        end

        if object:IsA("BasePart") then
            if fpsSettings.shadows then
                cacheFpsProperty(object, "CastShadow")
                object.CastShadow = false
            end
            if fpsSettings.materials then
                cacheFpsProperty(object, "Material")
                cacheFpsProperty(object, "Reflectance")
                object.Material = Enum.Material.SmoothPlastic
                object.Reflectance = 0
            end
        end
    end

    local function restoreFpsObjects(): ()
        for _, connection in pairs(propertyWatches) do pcall(function() connection:Disconnect() end) end
        propertyWatches = {}
        for object: any, properties: any in pairs(fpsVisualCache) do
            if object then
                for property: string, value: any in pairs(properties) do
                    pcall(function(): ()
                        object[property] = value
                    end)
                end
            end
        end
        fpsVisualCache = {}
        scenery = setmetatable({}, {__mode = "k"})
        local starterGui = host.StarterGui
        if starterGui then
            for kind, value in pairs(coreGuiCache) do
                pcall(function() starterGui:SetCoreGuiEnabled(kind, value) end)
            end
        end
        coreGuiCache = {}
    end

    local function toggleImproveFps(enabled: boolean): ()
        generation += 1
        local token: number = generation
        fpsModeEnabled = enabled
        for _, name in ipairs({"ImproveFPS", "ImproveFPSLighting", "ImproveFPSGui", "ImproveFPSDistance"}) do
            disconnectFeatureConnection(name)
        end
        restoreFpsObjects()

        if not enabled then
            if ImproveFpsFeature then ImproveFpsFeature:SetStatus(nil) end
            return
        end
        ImproveFpsFeature:SetStatus(tostring(selectedEffectCount()) .. " options")
        if fpsSettings.quality then
            pcall(function() setProperty(settings().Rendering, "QualityLevel", Enum.QualityLevel.Level01) end)
        end

        local containers = {workspace}
        if lighting then table.insert(containers, lighting) end
        if playerGui then table.insert(containers, playerGui) end
        for index, container in ipairs(containers) do
            local name = ({"ImproveFPS", "ImproveFPSLighting", "ImproveFPSGui"})[index]
            featureConnections[name] = container.DescendantAdded:Connect(function(object)
                if fpsModeEnabled and token == generation then pcall(applyFpsObject, object) end
            end)
        end
        if fpsSettings.coreGui and host.StarterGui then
            -- Do not disable All, Health or the mobile touch controls.
            for _, kind in ipairs({Enum.CoreGuiType.PlayerList, Enum.CoreGuiType.Backpack,
                Enum.CoreGuiType.Chat, Enum.CoreGuiType.EmotesMenu}) do
                pcall(function()
                    local value = host.StarterGui:GetCoreGuiEnabled(kind)
                    if type(value) == "boolean" then
                        coreGuiCache[kind] = value
                        host.StarterGui:SetCoreGuiEnabled(kind, false)
                    end
                end)
            end
        end
        if fpsSettings.scenery and host.TaskManager then
            local elapsed, cursor = 0, 1
            local pending = {}
            featureConnections.ImproveFPSDistance = host.TaskManager:Connect(function(dt)
                elapsed += dt
                if cursor > #pending then
                    if elapsed < 1 then return end
                    elapsed = 0
                    pending = {}
                    for part in pairs(scenery) do
                        if part.Parent then table.insert(pending, part) else scenery[part] = nil end
                    end
                    cursor = 1
                end
                -- Bound work per frame instead of rescanning a huge map in
                -- one callback, which would defeat an FPS optimization.
                local last = math.min(#pending, cursor + 199)
                while cursor <= last do
                    if not fpsModeEnabled or token ~= generation then return end
                    pcall(updateScenery, pending[cursor])
                    cursor += 1
                end
            end)
        end
        task.spawn(function(): ()
            local scanned = 0
            for _, container in ipairs(containers) do
                if not fpsModeEnabled or token ~= generation then return end
                pcall(applyFpsObject, container)
                for _, object in ipairs(container:GetDescendants()) do
                    if not fpsModeEnabled or token ~= generation then return end
                    pcall(applyFpsObject, object)
                    scanned += 1
                    if scanned % 250 == 0 then task.wait() end
                end
            end
        end)
    end

    local function refreshFps(): ()
        if fpsModeEnabled then
            toggleImproveFps(true)
        end
    end

    ImproveFpsFeature = createUniversalFeature(
        "Improve FPS",
        "Apply only the selected reversible optimizations",
        26,
        toggleImproveFps,
        {categoryName = "World"}
    )
    addToggleOption(ImproveFpsFeature, "Remove textures", true, function(value: boolean): ()
        fpsSettings.textures = value
        refreshFps()
    end)
    addToggleOption(ImproveFpsFeature, "Disable particles", true, function(value: boolean): ()
        fpsSettings.particles = value
        refreshFps()
    end)
    addToggleOption(ImproveFpsFeature, "Disable shadows", true, function(value: boolean): ()
        fpsSettings.shadows = value
        refreshFps()
    end)
    addToggleOption(ImproveFpsFeature, "Simple materials", false, function(value: boolean): ()
        fpsSettings.materials = value
        refreshFps()
    end)

    for _, definition in ipairs({
        {"Lowest render quality", "quality", "Requests render quality Level01 where the client permits it; restores the original level when OFF."},
        {"Simple lighting", "lighting", "Disables environment diffuse/specular reflections."},
        {"Disable local lights", "lights", "Turns off PointLight, SpotLight and SurfaceLight instances. May darken the map."},
        {"Simplify terrain", "terrain", "Disables terrain decoration, water waves and water reflections where writable. Physics is unchanged."},
        {"Disable post effects", "post", "Disables bloom, blur (including menu blur), depth of field, color correction and sun rays."},
        {"Simplify game UI", "guiEffects", "Disables game UI strokes, gradients and 3D viewport previews. Menu and touch controls are protected."},
        {"Hide world UI", "worldGui", "Hides floating labels and SurfaceGui displays; may hide game information."},
        {"Hide game UI", "gameGui", "Aggressive: hides game ScreenGuis, including HUD/objectives. Keeps this menu, chat and TouchGui."},
        {"Hide Roblox panels", "coreGui", "Hides player list, backpack, chat and emotes panel. Health and mobile movement remain available."},
        {"Low detail meshes", "geometry", "Requests Performance render fidelity for meshes/unions; does not change collisions."},
        {"Hide distant scenery", "scenery", "Aggressive: locally hides static map parts beyond 350 studs, updating periodically. May hide distant objectives; collisions remain."},
    }) do
        local key: string = definition[2]
        addToggleOption(ImproveFpsFeature, definition[1], false, function(value: boolean)
            fpsSettings[key] = value
            refreshFps()
        end, definition[3])
    end

    activeCleanup = function(): ()
        toggleImproveFps(false)
    end
    Module.Initialized = true
    return ImproveFpsFeature
end

function Module.destroy(): ()
    if activeCleanup then
        pcall(activeCleanup)
    end
    activeCleanup = nil
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Other/InteractExtender.lua"] = [[
export type Runtime = {
    framework: any,
    entity: any,
    host: any,
}

local Module = {
    Name = "InteractExtender",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local activeCleanup: (() -> ())? = nil

function Module.init(context: Runtime): any
    local host: any = context.host
    local TaskManager: any = host.TaskManager
    local featureConnections: any = host.featureConnections
    local disconnectFeatureConnection: any = host.disconnectFeatureConnection
    local createUniversalFeature: any = host.createUniversalFeature
    local addToggleOption: any = host.addToggleOption
    local addNumberOption: any = host.addNumberOption
    type InteractionSettings = {
        distance: number,
        instantPrompts: boolean,
        proximityPrompts: boolean,
        clickDetectors: boolean,
    }
    type PromptState = {distance: number, holdDuration: number}
    local interactionSettings: InteractionSettings = {
        distance = 32,
        instantPrompts = false,
        proximityPrompts = true,
        clickDetectors = true,
    }
    local originalPrompts: {[ProximityPrompt]: PromptState} =
        setmetatable({}, {__mode = "k"}) :: any
    local originalClickDetectors: {[ClickDetector]: number} =
        setmetatable({}, {__mode = "k"}) :: any
    local interactionExtenderEnabled: boolean = false
    local InteractFeature: any = nil
    local interactionRefreshClock: number = 0

    local function refreshInteractionExtender(): ()
        for prompt: ProximityPrompt, original: PromptState in pairs(originalPrompts) do
            if not prompt.Parent then
                continue
            end
            local wantedDistance: number = interactionExtenderEnabled
                    and interactionSettings.proximityPrompts
                    and interactionSettings.distance
                or original.distance
            local wantedHold: number = interactionExtenderEnabled
                    and interactionSettings.proximityPrompts
                    and interactionSettings.instantPrompts
                    and 0
                or original.holdDuration

            if prompt.MaxActivationDistance ~= wantedDistance then
                prompt.MaxActivationDistance = wantedDistance
            end
            if prompt.HoldDuration ~= wantedHold then
                prompt.HoldDuration = wantedHold
            end
        end
        for detector: ClickDetector, originalDistance: number in pairs(originalClickDetectors) do
            if not detector.Parent then
                continue
            end
            local wantedDistance: number = interactionExtenderEnabled
                    and interactionSettings.clickDetectors
                    and interactionSettings.distance
                or originalDistance
            if detector.MaxActivationDistance ~= wantedDistance then
                detector.MaxActivationDistance = wantedDistance
            end
        end
    end

    local function applyInteractionExtension(instance: Instance): ()
        if not interactionExtenderEnabled then
            return
        end
        if instance:IsA("ProximityPrompt") then
            if originalPrompts[instance] == nil then
                originalPrompts[instance] = {
                    distance = instance.MaxActivationDistance,
                    holdDuration = instance.HoldDuration,
                }
            end
            local original: PromptState = originalPrompts[instance]
            instance.MaxActivationDistance = interactionSettings.proximityPrompts
                    and interactionSettings.distance
                or original.distance
            instance.HoldDuration = interactionSettings.proximityPrompts
                    and interactionSettings.instantPrompts
                    and 0
                or original.holdDuration
        elseif instance:IsA("ClickDetector") then
            if originalClickDetectors[instance] == nil then
                originalClickDetectors[instance] = instance.MaxActivationDistance
            end
            instance.MaxActivationDistance = interactionSettings.clickDetectors
                    and interactionSettings.distance
                or originalClickDetectors[instance]
        end
    end

    local function restoreInteractionExtender(): ()
        interactionExtenderEnabled = false
        refreshInteractionExtender()
        originalPrompts = setmetatable({}, {__mode = "k"}) :: any
        originalClickDetectors = setmetatable({}, {__mode = "k"}) :: any
    end

    local function toggleInteractionExtender(enabled: boolean): ()
        disconnectFeatureConnection("InteractExtender")
        disconnectFeatureConnection("InteractExtenderRefresh")
        restoreInteractionExtender()
        interactionRefreshClock = 0
        if not enabled then
            if InteractFeature then InteractFeature:SetStatus(nil) end
            return
        end
        InteractFeature:SetStatus(tostring(math.round(interactionSettings.distance)) .. " studs")
        interactionExtenderEnabled = true
        featureConnections.InteractExtender = workspace.DescendantAdded:Connect(
            applyInteractionExtension
        )
        featureConnections.InteractExtenderRefresh = TaskManager:Connect(
            function(deltaTime: number): ()
                interactionRefreshClock += deltaTime
                if interactionRefreshClock >= 0.5 then
                    interactionRefreshClock = 0
                    refreshInteractionExtender()
                end
            end
        )
        task.spawn(function(): ()
            for index: number, instance: Instance in ipairs(workspace:GetDescendants()) do
                if not interactionExtenderEnabled then
                    return
                end
                applyInteractionExtension(instance)
                if index % 240 == 0 then
                    task.wait()
                end
            end
        end)
    end

    InteractFeature = createUniversalFeature(
        "Interact Extender",
        "Extend prompt and click interaction range without auto-firing",
        24,
        toggleInteractionExtender,
        {categoryName = "Exploits"}
    )
    addNumberOption(
        InteractFeature,
        "Interaction distance",
        interactionSettings.distance,
        8,
        250,
        function(value: number): ()
            interactionSettings.distance = value
            if InteractFeature.enabled then
                InteractFeature:SetStatus(tostring(math.round(value)) .. " studs")
            end
            refreshInteractionExtender()
        end
    )
    addToggleOption(
        InteractFeature,
        "Instant prompts",
        interactionSettings.instantPrompts,
        function(value: boolean): ()
            interactionSettings.instantPrompts = value
            refreshInteractionExtender()
        end
    )
    addToggleOption(
        InteractFeature,
        "Proximity prompts",
        interactionSettings.proximityPrompts,
        function(value: boolean): ()
            interactionSettings.proximityPrompts = value
            refreshInteractionExtender()
        end
    )
    addToggleOption(
        InteractFeature,
        "Click detectors",
        interactionSettings.clickDetectors,
        function(value: boolean): ()
            interactionSettings.clickDetectors = value
            refreshInteractionExtender()
        end
    )

    activeCleanup = function(): ()
        disconnectFeatureConnection("InteractExtender")
        disconnectFeatureConnection("InteractExtenderRefresh")
        restoreInteractionExtender()
        interactionRefreshClock = 0
        if InteractFeature then
            InteractFeature:SetStatus(nil)
        end
    end
    Module.Initialized = true
    return InteractFeature
end

function Module.destroy(): ()
    if activeCleanup then
        pcall(activeCleanup)
    end
    activeCleanup = nil
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Other/RejoinServer.lua"] = [[
export type Runtime = {
    framework: any,
    entity: any,
    host: any,
    services: any,
}

local Module = {
    Name = "RejoinServer",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local activeCleanup: (() -> ())? = nil

function Module.init(context: Runtime): any
    local host: any = context.host
    local LocalPlayer: any = host.LocalPlayer
    local createUniversalFeature: any = host.createUniversalFeature
    local cloneReference: any = host.cloneReference
    local notify: (string) -> () = host.notify
    local function rejoinCurrentServer(): ()
        local teleportService: TeleportService = cloneReference(
            game:GetService("TeleportService")
        )
        local placeId: number = game.PlaceId
        local jobId: string = tostring(game.JobId or "")

        local rejoined: boolean = false
        if jobId ~= "" then
            rejoined = pcall(function(): ()
                teleportService:TeleportToPlaceInstance(placeId, jobId, LocalPlayer)
            end)
        end
        if not rejoined then
            local ok: boolean, teleportError: any = pcall(function(): ()
                teleportService:Teleport(placeId, LocalPlayer)
            end)
            if not ok then
                notify("Rejoin failed: " .. tostring(teleportError))
            end
        end
    end
    local actionId: string = "RejoinServer"
    local registries: any = context.services.registries
    local wurstOptions: any = registries.wurstOptions()
    if wurstOptions and type(wurstOptions.RegisterAction) == "function" then
        local registered: boolean, registration: any = pcall(
            wurstOptions.RegisterAction,
            actionId,
            "Rejoin Server",
            rejoinCurrentServer,
            {
                description = "Reconnect to the current server instance",
                configKey = "Universal.RejoinServer",
            }
        )
        if not registered then
            error("Wurst Options refused Rejoin Server: " .. tostring(registration))
        end
        local search: any = registries.moduleSearch()
        local searchFeature: any = {
            name = "Rejoin Server",
            configKey = "Universal.RejoinServer",
            kind = "action",
            searchable = false,
            enabled = false,
            activate = rejoinCurrentServer,
        }
        if search and type(search.Register) == "function" then
            search.Register(searchFeature)
        end
        activeCleanup = function(): ()
            if search and type(search.Unregister) == "function" then
                search.Unregister(searchFeature)
            end
            if type(registration) == "table"
                and type(registration.Unregister) == "function" then
                registration.Unregister()
            elseif type(wurstOptions.UnregisterAction) == "function" then
                pcall(wurstOptions.UnregisterAction, actionId)
            end
        end
        Module.Initialized = true
        return registration
    end

    local feature: any = createUniversalFeature(
        "Rejoin Server",
        "Reconnect to the current server instance",
        22,
        rejoinCurrentServer,
        {
            action = true,
            noOptions = true,
            categoryName = "Other",
            searchable = false,
        }
    )

    activeCleanup = function(): () end
    Module.Initialized = true
    return feature
end

function Module.destroy(): ()
    if activeCleanup then
        pcall(activeCleanup)
    end
    activeCleanup = nil
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Render/Arrows.lua"] = [[
export type Runtime = {
    framework: any,
    entity: any,
    render: any,
    host: any,
    services: any,
}

local Module = {
    Name = "Arrows",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local activeCard: any = nil

function Module.init(context: Runtime): any
    local framework: any = context.framework
    local entity: any = context.entity
    local render: any = context.render
    local protectedTargets: any = context.services.protectedTargets
    local gameBridge: any = context.services.gameBridge
    local teamCheck: any = context.host.state and context.host.state.teamCheck
    local currentWorkspace: Workspace = context.host.workspace or workspace
    local layer: Frame = render:Layer("ArrowsLayer")
    local shown: {[Player]: boolean} = {}

    local function roleColour(player: Player): Color3?
        if gameBridge and type(gameBridge.playerRoleColor) == "function" then
            local ok: boolean, colour: any =
                pcall(gameBridge.playerRoleColor, player)
            if ok and typeof(colour) == "Color3" then
                return colour
            end
        end
        return nil
    end

    local card: any
    local function clear(): ()
        render:ReleaseAll(layer)
        table.clear(shown)
        layer.Visible = false
    end

    card = framework.Categories.Visuals:CreateModule({
        Name = "Arrows",
        Category = "Render",
        ConfigKey = "Universal.Arrows",
        Order = 3,
        Tooltip = "Points toward players outside the camera view.",
        Function = function(enabled: boolean): ()
            layer.Visible = enabled
            if not enabled then
                clear()
                card:SetStatus(nil)
                return
            end
            card:Render(function(): ()
                local camera: Camera? = currentWorkspace.CurrentCamera
                if not camera then
                    render:ReleaseAll(layer)
                    table.clear(shown)
                    return
                end
                local viewport: Vector2 = camera.ViewportSize
                local centre: Vector2 = Vector2.new(viewport.X / 2, viewport.Y / 2)
                local radius: number = math.max(40, math.min(viewport.X, viewport.Y) * 0.4)
                local seen: {[Player]: boolean} = {}
                local count: number = 0
                for _, target: any in ipairs(entity:Refresh()) do
                    local player: Player = target.Player
                    local friendly: boolean = target.IsFriendly
                    if not friendly
                        and teamCheck
                        and type(teamCheck.isSameTeam) == "function" then
                        friendly = teamCheck.isSameTeam(player)
                    end
                    if (not card.Options["Teammates"].Value and friendly)
                        or protectedTargets.isProtected(player)
                        or not target.Humanoid
                        or target.Humanoid.Health <= 0
                        or not target.RootPart
                        or target.Distance > card.Options["Max distance"].Value then
                        render:Release(layer, player)
                        continue
                    end
                    local projected: Vector3, onScreen: boolean =
                        camera:WorldToViewportPoint(target.RootPart.Position)
                    if onScreen then
                        render:Release(layer, player)
                        continue
                    end
                    local drawing: any = render:Set(layer, player)
                    local delta: Vector2 = Vector2.new(projected.X, projected.Y) - centre
                    if projected.Z < 0 then
                        delta = Vector2.new(-delta.X, -delta.Y)
                    end
                    if delta.Magnitude < 0.001 then
                        delta = Vector2.new(0, -1)
                    end
                    local direction: Vector2 = delta.Unit
                    local perpendicular: Vector2 = Vector2.new(-direction.Y, direction.X)
                    local tip: Vector2 = centre + direction * radius
                    local back: Vector2 = tip - direction * 16
                    -- Colour priority: the game's role colour when roles are
                    -- known (green by default otherwise), then teammates in
                    -- their team colour while the team-colour option is on.
                    local roleColourForTarget: Color3? = roleColour(player)
                    local colour: Color3 = roleColourForTarget
                        or (card.Options["Team colours"].Value
                            and friendly
                            and player.Team
                            and player.Team.TeamColor.Color
                            or card.Options["Colour"].Value)
                    drawing:Line("Arrow", 1, tip, back + perpendicular * 8, 2, colour)
                    drawing:Line("Arrow", 2, tip, back - perpendicular * 8, 2, colour)
                    drawing:HideLines("Arrow", 3, 8)
                    if card.Options["Distance"].Value then
                        drawing:Label(
                            "Distance",
                            "[" .. tostring(math.round(target.Distance)) .. "]",
                            tip - direction * 26,
                            0.5,
                            12,
                            colour,
                            true
                        )
                    else
                        drawing:HideLabel("Distance")
                    end
                    drawing:Show(true)
                    seen[player] = true
                    count += 1
                end
                for player: Player in pairs(shown) do
                    if not seen[player] then
                        render:Release(layer, player)
                    end
                end
                shown = seen
                card:SetStatus(tostring(count))
            end)
            card:Clean(clear)
        end,
    })

    card:CreateColor({Name = "Colour", Default = Color3.fromRGB(85, 255, 85), Tooltip = "Base arrow colour. Arrows use role colours instead whenever the game knows roles."})
    card:CreateToggle({Name = "Distance", Default = true})
    card:CreateSlider({Name = "Max distance", Min = 25, Max = 2000, Step = 25, Default = 500})
    card:CreateToggle({Name = "Teammates", Default = false, Tooltip = "Also point at teammates. The advanced team check decides who counts."})
    card:CreateToggle({Name = "Team colours", Default = false, Tooltip = "Teammates point in their Roblox team colour; everyone else keeps the base colour. Role colours always win."})

    activeCard = card
    Module.Initialized = true
    return card
end

function Module.destroy(): ()
    if activeCard and activeCard.Enabled then
        activeCard:Toggle(false)
    end
    activeCard = nil
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Render/Chams.lua"] = [[
export type Runtime = {
    framework: any,
    entity: any,
    host: any,
    services: any,
}

local Module = {
    Name = "Chams",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local activeCard: any = nil
local activeBridgeCleanup: (() -> ())? = nil

function Module.init(context: Runtime): any
    local framework: any = context.framework
    local entity: any = context.entity
    local host: any = context.host
    local protectedTargets: any = context.services.protectedTargets
    local gameBridge: any = context.services.gameBridge
    local teamCheck: any = host.state and host.state.teamCheck
    local currentWorkspace: Workspace = host.workspace or workspace
    local highlights: {[Player]: Highlight} = {}
    local lastUpdate: number = -math.huge
    local roles: any = nil
    local function playerPerk(player: Player): string?
        if type(gameBridge) ~= "table"
            or type(gameBridge.playerPerk) ~= "function" then
            return nil
        end
        local ok: boolean, perk: any = pcall(gameBridge.playerPerk, player)
        if ok and type(perk) == "string" then
            return perk
        end
        return nil
    end

    -- MM2 perk assets; this module owns only the icon, not text labels.
    local PERK_ICONS: {[string]: string} = {
        ["Footsteps"] = "rbxassetid://336404773",
        ["Sleight"] = "rbxassetid://340309581",
        ["Ninja"] = "rbxassetid://416832054",
        ["Haste"] = "rbxassetid://416942717",
        ["FakeGun"] = "rbxassetid://17899774181",
        ["Fake Gun"] = "rbxassetid://17899774181",
        ["Ghost"] = "rbxassetid://335206856",
        ["Xray"] = "rbxassetid://340313896",
        ["X-Ray"] = "rbxassetid://340313896",
        ["Trap"] = "rbxassetid://4966828196",
        ["Sprint"] = "rbxassetid://4970219155",
        ["VampireBat"] = "rbxassetid://129078122681639",
        ["Bat Form"] = "rbxassetid://129078122681639",
        ["Decoy"] = "rbxassetid://113722008817201",
    }

    local perkTag: BillboardGui? = nil

    local function destroyPerkTag(): ()
        if perkTag then
            pcall(perkTag.Destroy, perkTag)
            perkTag = nil
        end
    end

    local function clear(): ()
        for player: Player, highlight: Highlight in pairs(highlights) do
            highlights[player] = nil
            highlight:Destroy()
        end
        destroyPerkTag()
    end

    if type(gameBridge) == "table" and type(gameBridge.onEvent) == "function" then
        activeBridgeCleanup = gameBridge.onEvent(function(kind: string): ()
            if kind == "roleUpdate" then
                lastUpdate = -math.huge
            end
        end)
    end

    local store: any = host.configData
    if store and store.values and store.states then
        local oldMode: any = store.values["Universal.PlayerESP.Chams"]
        if store.states["Universal.Chams"] == nil
            and (oldMode == "Overlay" or oldMode == "Outline") then
            store.states["Universal.Chams"] = true
            local fillKey: string = "Universal.Chams.Filltransparency"
            if store.values[fillKey] == nil then
                store.values[fillKey] = oldMode == "Outline" and 1 or 0.55
            end
            if type(host.queueConfigSave) == "function" then
                host.queueConfigSave()
            end
        end
        -- The old build shipped team colours ON by default, which painted
        -- everyone red when no team data existed. Forget that legacy state
        -- (unless the player actually customised the colours) so the new
        -- white default applies.
        local teamKey: string = "Universal.Chams.Teamcolours"
        if store.states[teamKey] == true
            and store.values["Universal.Chams.Fillcolour"] == nil
            and store.values["Universal.Chams.Outlinecolour"] == nil then
            store.states[teamKey] = false
            if type(host.queueConfigSave) == "function" then
                host.queueConfigSave()
            end
        end
    end

    local card: any

    card = framework.Categories.Visuals:CreateModule({
        Name = "Chams",
        Category = "Render",
        ConfigKey = "Universal.Chams",
        Order = 2,
        Tooltip = "Player highlights with independent role palettes and filters. Names and health have their own modules.",
        Function = function(enabled: boolean): ()
            if not enabled then
                clear()
                card:SetStatus(nil)
                return
            end
            card:SetStatus("0")

            card:Render(function(): ()
                local now: number = os.clock()
                if now - lastUpdate < 0.2 then
                    return
                end
                lastUpdate = now
                local seen: {[Player]: boolean} = {}
                local count: number = 0
                local roleMode = roles and roles.provider ~= nil
                local teamsReplaced = roleMode and roles.provider.ReplacesTeams == true
                local useTeamColours = not teamsReplaced and card.Options["Team colours"].Value
                local allowTeammates = not teamsReplaced and card.Options["Teammates"].Value
                local showPerk = card.Options["Show Perk"] and card.Options["Show Perk"].Value
                local perkTarget: Player? = nil
                local targets: any = entity:Refresh()
                -- Dead is a real MM2 role, not an inert colour row. Include
                -- existing corpse models only when the provider declares it.
                if roleMode and type(roles.provider.DeadRoles) == "table" and host.Players then
                    targets = table.clone(targets)
                    local included = {}
                    for _, target in ipairs(targets) do included[target.Player] = true end
                    for _, player in ipairs(host.Players:GetPlayers()) do
                        if player == host.LocalPlayer or included[player] then continue end
                        local character = player.Character
                        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
                        if character and character.Parent and humanoid and humanoid.Health <= 0
                            and table.find(roles.provider.DeadRoles, roles:Role(player)) then
                            table.insert(targets, {Player = player, Character = character, Humanoid = humanoid,
                                IsFriendly = entity.IsFriendly and entity:IsFriendly(player) or false})
                        end
                    end
                end
                for _, target: any in ipairs(targets) do
                    local player: Player = target.Player

                    -- Universal games: the teammate toggle decides who is
                    -- highlighted. Role games: every role is known, per-role
                    -- toggles decide, and role colours always win.
                    local allowedTeam: boolean = true
                    if not teamsReplaced then
                        local friendly: boolean = target.IsFriendly
                        if not friendly and teamCheck
                            and type(teamCheck.isSameTeam) == "function" then
                            friendly = teamCheck.isSameTeam(player)
                        end
                        allowedTeam = allowTeammates or not friendly
                    end
                    if not (allowedTeam
                        and not protectedTargets.isProtected(player)
                        and target.Character
                        and target.Humanoid
                        and (target.Humanoid.Health > 0 or roleMode and type(roles.provider.DeadRoles) == "table"
                            and table.find(roles.provider.DeadRoles, roles:Role(player)))) then
                        continue
                    end

                    local roleColour: Color3? = nil
                    if roleMode then
                        if not roles:Allows(player) then continue end
                        local role
                        roleColour, role = roles:Resolve(player, nil)
                        if role == "Murderer" then perkTarget = player end
                    end
                    local teamColour: Color3? = nil
                    if not roleColour and useTeamColours and target.IsFriendly then
                        local team: Team? = player.Team
                        if team then
                            teamColour = team.TeamColor.Color
                        end
                    end
                    local fillColour: Color3 = roleColour
                        or teamColour
                        or card.Options["Fill colour"].Value
                    local outlineColour: Color3 = roleColour
                        or teamColour
                        or card.Options["Outline colour"].Value
                    local fillTransparency: number =
                        card.Options["Fill transparency"].Value
                    local outlineTransparency: number =
                        card.Options["Outline transparency"].Value
                    local depthMode: Enum.HighlightDepthMode =
                        card.Options["Through walls"].Value
                            and Enum.HighlightDepthMode.AlwaysOnTop
                        or Enum.HighlightDepthMode.Occluded

                    seen[player] = true
                    count += 1

                    local highlight: Highlight? = highlights[player]
                    if not highlight or not highlight.Parent then
                        highlight = Instance.new("Highlight")
                        highlight.Name = "Wurst_Chams"
                        highlight.Parent = currentWorkspace
                        highlights[player] = highlight
                    end
                    local resolved: Highlight = highlight :: Highlight
                    if resolved.Adornee ~= target.Character then
                        resolved.Adornee = target.Character
                    end
                    if resolved.FillColor ~= fillColour then
                        resolved.FillColor = fillColour
                    end
                    if resolved.OutlineColor ~= outlineColour then
                        resolved.OutlineColor = outlineColour
                    end
                    if resolved.FillTransparency ~= fillTransparency then
                        resolved.FillTransparency = fillTransparency
                    end
                    if resolved.OutlineTransparency ~= outlineTransparency then
                        resolved.OutlineTransparency = outlineTransparency
                    end
                    if resolved.DepthMode ~= depthMode then
                        resolved.DepthMode = depthMode
                    end

                end

                for player: Player, highlight: Highlight in pairs(highlights) do
                    if not seen[player] then
                        highlights[player] = nil
                        highlight:Destroy()
                    end
                end
                -- Perk icon above the murderer (role games only).
                if roleMode and showPerk and perkTarget and perkTarget.Character then
                    local head: BasePart? = perkTarget.Character:FindFirstChild("Head")
                        or perkTarget.Character:FindFirstChild("HumanoidRootPart")
                        :: BasePart?
                    local perk: string? = head and playerPerk(perkTarget) or nil
                    if head and perk then
                        local iconId: string? = PERK_ICONS[perk]
                            or PERK_ICONS[string.gsub(perk, "%s+", "")]
                        if iconId then
                            if not perkTag
                                or not perkTag.Parent
                                or perkTag.Adornee ~= head then
                                destroyPerkTag()
                                local billboard: BillboardGui = Instance.new("BillboardGui")
                                billboard.Name = "Wurst_ChamPerk"
                                billboard.AlwaysOnTop = true
                                billboard.LightInfluence = 0
                                billboard.Size = UDim2.fromOffset(26, 26)
                                billboard.StudsOffset = Vector3.new(0, 2.9, 0)
                                billboard.MaxDistance = 1500
                                billboard.Adornee = head
                                billboard.Parent = head
                                local icon: ImageLabel = Instance.new("ImageLabel")
                                icon.Name = "Perk"
                                icon.BackgroundTransparency = 1
                                icon.Size = UDim2.fromScale(1, 1)
                                icon.Image = iconId
                                icon.Parent = billboard
                                perkTag = billboard
                            end
                            local icon: any = perkTag and perkTag:FindFirstChild("Perk")
                            if icon and icon.Image ~= iconId then
                                icon.Image = iconId
                            end
                        else
                            destroyPerkTag()
                        end
                    else
                        destroyPerkTag()
                    end
                else
                    destroyPerkTag()
                end

                card:SetStatus(tostring(count))
            end)
            card:Clean(clear)
        end,
    })

    card:CreateColor({Name = "Fill colour", Default = Color3.fromRGB(85, 255, 85)})
    card:CreateColor({Name = "Outline colour", Default = Color3.fromRGB(85, 255, 85)})
    card:CreateSlider({Name = "Fill transparency", Min = 0, Max = 1, Step = 0.05, Default = 0.55})
    card:CreateSlider({Name = "Outline transparency", Min = 0, Max = 1, Step = 0.05, Default = 0})
    card:CreateToggle({Name = "Through walls", Default = true})
    card:CreateToggle({Name = "Teammates", Default = false})
    card:CreateToggle({Name = "Team colours", Default = false})
    if host.state and host.state.activeGameName == "MM2" then
        card:CreateToggle({Name = "Show Perk", Default = true, Tooltip = "Perk icon above the murderer."})
    end
    roles = context.services.gameRoles:Bind(card, {filters = true})
    card.OptionFilter = function(name)
        if roles.provider and roles.provider.ReplacesTeams and (name == "Teammates" or name == "Team colours") then return false end
        if name == "Show Perk" then return roles.provider ~= nil and roles.provider.Name == "MM2" end
        return true
    end
    card:RefreshVisibility()
    Module.roles = roles
    activeCard = card
    Module.Initialized = true
    return card
end

function Module.destroy(): ()
    if activeCard and activeCard.Enabled then
        activeCard:Toggle(false)
    end
    if activeBridgeCleanup then
        pcall(activeBridgeCleanup)
        activeBridgeCleanup = nil
    end
    if Module.roles then Module.roles:Destroy(); Module.roles = nil end
    activeCard = nil
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Render/FieldOfView.lua"] = [[
export type Runtime = {
    framework: any,
    entity: any,
    host: any,
    services: any,
}

local Module = {
    Name = "FieldOfView",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local activeCleanup: (() -> ())? = nil

function Module.init(context: Runtime): any
    local host: any = context.host
    local TaskManager: any = host.TaskManager
    local featureConnections: any = host.featureConnections
    local disconnectFeatureConnection: any = host.disconnectFeatureConnection
    local fovOwnership: any = context.services.fovOwnership
    local createUniversalFeature: any = host.createUniversalFeature
    local addNumberOption: any = host.addNumberOption
    local workspace: any = host.workspace
    local fovSettings = {value = 90}
    local FovFeature: any = nil

    local function toggleFov(enabled)
        disconnectFeatureConnection("FOV")
        fovOwnership.set("Universal", enabled and fovSettings.value or nil)
        if not enabled then
            if FovFeature then FovFeature:SetStatus(nil) end
            return
        end

        FovFeature:SetStatus(tostring(math.round(fovSettings.value)))
        featureConnections.FOV = TaskManager:Connect(function()
            fovOwnership.set("Universal", fovSettings.value)
            fovOwnership.apply(workspace.CurrentCamera)
        end)
    end

    FovFeature = createUniversalFeature(
        "FOV",
        "Keep the camera field of view fixed",
        10,
        toggleFov,
        {categoryName = "Render"}
    )
    addNumberOption(FovFeature, "Field of view", fovSettings.value, 20, 120, function(value)
        fovSettings.value = value
        if FovFeature.enabled then
            FovFeature:SetStatus(tostring(math.round(value)))
        end
    end)

    activeCleanup = function(): ()
        disconnectFeatureConnection("FOV")
        fovOwnership.set("Universal", nil)
    end
    Module.Initialized = true
    return FovFeature
end

function Module.destroy(): ()
    if activeCleanup then
        pcall(activeCleanup)
    end
    activeCleanup = nil
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Render/FreeCam.lua"] = [[
local Module = {Name = "FreeCam", Initialized = false}
local card, services

function Module.init(context)
    local host = context.host
    services = context.services
    local input, run = host.UserInputService, host.RunService
    local actions = game:GetService("ContextActionService")
    local access = context.services.cameraAccess
    local world = host.workspace or workspace
    local create = host.create
    local id = "ARandomMenu.FreeCam." .. tostring({})
    local cameraState = {IsActive=function() return card ~= nil and card.Enabled end}
    context.services.freeCam = cameraState
    local function spectating()
        return context.services.spectate and context.services.spectate.IsActive()
    end

    card = context.framework.Categories.Visuals:CreateModule({
        Name = "FreeCam", Category = "World", ConfigKey = "Universal.FreeCam", Order = 6,
        Tooltip = "Move the camera without moving your character. WASD, Q/E, right-drag; touch controls on mobile.",
        Function = function(enabled)
            cameraState.Session = enabled and {} or nil
            if not enabled then card:SetStatus(nil); return end
            local keys, held, connections = {}, {}, {}
            local camera, saved, position, pitch, yaw
            local writtenFrame, writtenFocus
            local controls, controlsEnabled
            local touchGui, touchGuiEnabled
            local moveTouch, lookTouch, dragging
            local stick = Vector2.zero
            local mouseMode, mouseIcon
            local gui, pad, knob

            local function connect(signal, callback)
                table.insert(connections, signal:Connect(callback))
            end
            local function releaseMouse()
                if not dragging then return end
                dragging = false
                if input.MouseBehavior == Enum.MouseBehavior.LockCurrentPosition then input.MouseBehavior = mouseMode end
                if input.MouseIconEnabled == false then input.MouseIconEnabled = mouseIcon end
            end
            local function resetInput()
                table.clear(keys); table.clear(held)
                moveTouch, lookTouch = nil, nil
                stick = Vector2.zero
                if knob then knob.Position = UDim2.fromScale(0.5,0.5) end
                releaseMouse()
            end
            local function restoreCamera()
                if camera and saved then
                    pcall(function()
                        if camera.CameraType ~= Enum.CameraType.Scriptable then return end
                        camera.CameraType = saved.kind
                        if camera.CFrame == writtenFrame then camera.CFrame = saved.frame end
                        if camera.Focus == writtenFocus then camera.Focus = saved.focus end
                    end)
                end
                camera, saved, writtenFrame, writtenFocus = nil, nil, nil, nil
            end
            local function releaseControls()
                if controls and controlsEnabled then pcall(controls.Enable, controls) end
                controls, controlsEnabled = nil, nil
                if touchGui then pcall(function() touchGui.Enabled = touchGuiEnabled end) end
                touchGui = nil
            end
            card:Clean(function()
                run:UnbindFromRenderStep(id)
                table.clear(keys); table.clear(held)
                for _, name in ipairs({"Forward","Back","Left","Right","Up","Down"}) do actions:UnbindAction(id .. name) end
                for _, connection in ipairs(connections) do connection:Disconnect() end
                releaseMouse(); restoreCamera(); releaseControls()
                if gui then gui:Destroy() end
            end)
            local function hold(name, source, down)
                held[name] = held[name] or {}
                held[name][source] = down and true or nil
                keys[name] = next(held[name]) ~= nil
            end
            for _, definition in ipairs({
                {"Forward",Enum.KeyCode.W,Enum.KeyCode.Up}, {"Back",Enum.KeyCode.S,Enum.KeyCode.Down},
                {"Left",Enum.KeyCode.A,Enum.KeyCode.Left}, {"Right",Enum.KeyCode.D,Enum.KeyCode.Right},
                {"Up",Enum.KeyCode.E,Enum.KeyCode.Space}, {"Down",Enum.KeyCode.Q,Enum.KeyCode.LeftControl},
            }) do
                local name = definition[1]
                actions:BindActionAtPriority(id .. name, function(_, state, event)
                    if spectating() or input:GetFocusedTextBox() then held[name] = nil; keys[name] = false; return Enum.ContextActionResult.Pass end
                    if state == Enum.UserInputState.Cancel then held[name] = nil; keys[name] = false
                    else hold(name,event.KeyCode,state == Enum.UserInputState.Begin or state == Enum.UserInputState.Change) end
                    return Enum.ContextActionResult.Sink
                end, false, Enum.ContextActionPriority.High.Value + 1, definition[2], definition[3])
            end
            local function pan(delta)
                if spectating() then return end
                local sensitivity = math.rad(card.Options.Sensitivity.Value)
                yaw -= delta.X * sensitivity
                pitch = math.clamp(pitch - delta.Y * sensitivity, -math.rad(89), math.rad(89))
            end
            connect(input.InputBegan, function(event, processed)
                if processed or spectating() or input:GetFocusedTextBox() or not position then return end
                if event.UserInputType == Enum.UserInputType.MouseButton2 then
                    mouseMode, mouseIcon = input.MouseBehavior, input.MouseIconEnabled
                    dragging = true
                    input.MouseBehavior = Enum.MouseBehavior.LockCurrentPosition
                    input.MouseIconEnabled = false
                end
            end)
            connect(input.InputChanged, function(event)
                if dragging and event.UserInputType == Enum.UserInputType.MouseMovement and not input:GetFocusedTextBox() then pan(event.Delta) end
            end)
            connect(input.InputEnded, function(event)
                if event.UserInputType == Enum.UserInputType.MouseButton2 then releaseMouse() end
            end)
            connect(input.WindowFocusReleased, resetInput)
            connect(input.TextBoxFocused, resetInput)

            if input.TouchEnabled then
                gui = create("Frame", {Name="FreeCamControls", Parent=host.ScreenGui, Size=UDim2.fromScale(1,1), BackgroundTransparency=1, ZIndex=30})
                local function button(name, text, at, size)
                    local object = create("TextButton", {Name=name, Parent=gui, Position=at, Size=size, Text=text, Font=Enum.Font.Code,
                        TextSize=18, TextColor3=Color3.new(1,1,1), BackgroundColor3=Color3.fromRGB(25,25,25), BackgroundTransparency=0.3,
                        BorderSizePixel=1, BorderColor3=Color3.fromRGB(120,120,120), AutoButtonColor=true, ZIndex=31})
                    if host.ThemeEngine then
                        host.ThemeEngine.Bind(object,"BackgroundColor3","background")
                        host.ThemeEngine.Bind(object,"TextColor3","text")
                    end
                    return object
                end
                pad = button("Move", "", UDim2.new(0,22,1,-152), UDim2.fromOffset(104,104))
                knob = create("Frame", {Parent=pad, Name="Stick", AnchorPoint=Vector2.new(0.5,0.5), Position=UDim2.fromScale(0.5,0.5),
                    Size=UDim2.fromOffset(26,26), BackgroundColor3=Color3.fromRGB(220,220,220), BorderSizePixel=0, ZIndex=32})
                local function moveStick(event)
                    local centre = pad.AbsolutePosition + pad.AbsoluteSize * 0.5
                    local delta = (Vector2.new(event.Position.X,event.Position.Y) - centre) / 42
                    stick = delta.Magnitude > 1 and delta.Unit or delta
                    if stick.Magnitude < 0.12 then stick = Vector2.zero end
                    knob.Position = UDim2.new(0.5,stick.X*36,0.5,stick.Y*36)
                end
                connect(pad.InputBegan, function(event)
                    if event.UserInputType == Enum.UserInputType.Touch and not moveTouch then moveTouch = event; moveStick(event) end
                end)
                for _, name in ipairs({"Up","Down"}) do
                    local object = button(name, name == "Up" and "+" or "−", UDim2.new(1,-70,1,name == "Up" and -152 or -96), UDim2.fromOffset(48,48))
                    connect(object.InputBegan, function(event) if event.UserInputType == Enum.UserInputType.Touch then hold(name,event,true) end end)
                    connect(object.InputEnded, function(event) if event.UserInputType == Enum.UserInputType.Touch then hold(name,event,false) end end)
                end
                local exit = button("Exit", "Exit FreeCam", UDim2.new(0.5,-66,0,48), UDim2.fromOffset(132,30))
                connect(exit.Activated, function()
                    if card.Feature and card.Feature.enabled and card.Feature.activate then card.Feature.activate() else card:Toggle(false) end
                end)
                connect(input.TouchStarted, function(event, processed)
                    local current = world.CurrentCamera
                    if not processed and not spectating() and not lookTouch and event ~= moveTouch and current
                        and event.Position.X > current.ViewportSize.X * 0.45 and not input:GetFocusedTextBox() then lookTouch = event end
                end)
                connect(input.TouchMoved, function(event)
                    if event == moveTouch then
                        moveStick(event)
                    elseif event == lookTouch and position then pan(event.Delta) end
                end)
                connect(input.TouchEnded, function(event)
                    hold("Up",event,false); hold("Down",event,false)
                    if event == moveTouch then moveTouch = nil; stick = Vector2.zero; knob.Position = UDim2.fromScale(0.5,0.5) end
                    if event == lookTouch then lookTouch = nil end
                end)
            end
            card:SetStatus("WASD / touch")
            run:BindToRenderStep(id, Enum.RenderPriority.Camera.Value + 1, function(dt)
                if spectating() then
                    resetInput()
                    if gui then gui.Visible = false end
                    return
                end
                if gui then gui.Visible = true end
                local nextCamera = world.CurrentCamera
                if camera ~= nextCamera then
                    restoreCamera()
                    camera = nextCamera
                    if camera then
                        saved = {kind=camera.CameraType, frame=camera.CFrame, focus=camera.Focus}
                        if not position then
                            position = camera.CFrame.Position
                            local look = camera.CFrame.LookVector
                            pitch, yaw = math.asin(math.clamp(look.Y,-1,1)), math.atan2(-look.X,-look.Z)
                        end
                    end
                end
                if not camera then return end
                if writtenFrame and camera.CameraType ~= Enum.CameraType.Scriptable then
                    saved.kind, saved.frame, saved.focus = camera.CameraType, camera.CFrame, camera.Focus
                elseif writtenFrame and camera.CFrame ~= writtenFrame then
                    saved.frame, saved.focus = camera.CFrame, camera.Focus
                end
                local nextControls = access:GetControls()
                if type(nextControls) ~= "table" or type(nextControls.Disable) ~= "function" or type(nextControls.Enable) ~= "function" then nextControls = nil end
                if nextControls ~= controls then
                    releaseControls(); controls = nextControls
                    if controls then
                        controlsEnabled = controls.controlsEnabled ~= false
                        local ok = pcall(controls.Disable, controls)
                        if not ok then controls, controlsEnabled = nil, nil end
                    end
                end
                local playerGui = host.LocalPlayer:FindFirstChildOfClass("PlayerGui")
                local nativeTouch = playerGui and playerGui:FindFirstChild("TouchGui")
                if nativeTouch ~= touchGui then
                    if touchGui then pcall(function() touchGui.Enabled = touchGuiEnabled end) end
                    touchGui = nativeTouch
                    if touchGui then touchGuiEnabled = touchGui.Enabled end
                end
                if touchGui then touchGui.Enabled = false end
                if not controls then
                    local character = host.LocalPlayer.Character
                    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
                    if humanoid then humanoid:Move(Vector3.zero, false) end
                end
                local rotation = CFrame.fromOrientation(pitch,yaw,0)
                if not input:GetFocusedTextBox() then
                    local move = Vector3.new((keys.Right and 1 or 0)-(keys.Left and 1 or 0)+stick.X,
                        (keys.Up and 1 or 0)-(keys.Down and 1 or 0), (keys.Back and 1 or 0)-(keys.Forward and 1 or 0)+stick.Y)
                    local direction = rotation:VectorToWorldSpace(Vector3.new(move.X,0,move.Z)) + Vector3.yAxis * move.Y
                    if direction.Magnitude > 1 then direction = direction.Unit end
                    local speed = card.Options.Speed.Value * (input:IsKeyDown(Enum.KeyCode.LeftShift) and 3 or 1)
                    position += direction * speed * math.clamp(dt,0,0.1)
                end
                camera.CameraType = Enum.CameraType.Scriptable
                camera.CFrame = CFrame.new(position) * rotation
                camera.Focus = camera.CFrame * CFrame.new(0,0,-16)
                writtenFrame, writtenFocus = camera.CFrame, camera.Focus
            end)
        end,
    })
    card:CreateSlider({Name="Speed", Min=1, Max=250, Default=48})
    card:CreateSlider({Name="Sensitivity", Min=0.05, Max=0.6, Default=0.2})
    Module.Initialized = true
    return card
end
function Module.destroy()
    if card and card.Enabled then card:Toggle(false) end
    if services then services.freeCam = nil end
    card, services = nil, nil
    Module.Initialized = false
end
return Module

]],
        ["src/games/universal/Render/Fullbright.lua"] = [[
local Module = {Name = "Fullbright", PlaceId = 0, Initialized = false}
local card

function Module.init(context)
    local lighting = context.host.Lighting
    local original, applied = {}, {}
    local originalTime, appliedTime, elapsed
    local function write(key, value)
        if applied[key] ~= nil and lighting[key] ~= applied[key] then original[key] = lighting[key] end
        if original[key] == nil then original[key] = lighting[key] end
        lighting[key], applied[key] = value, value
    end
    local function restoreTime()
        if appliedTime ~= nil and lighting.ClockTime == appliedTime then lighting.ClockTime = originalTime end
        originalTime, appliedTime = nil, nil
    end
    local function restore()
        restoreTime()
        for key, value in pairs(original) do if lighting[key] == applied[key] then lighting[key] = value end end
        table.clear(original); table.clear(applied)
    end
    local function tick(dt)
        -- Roblox does not accept math.huge for Lighting.Brightness; clamp
        -- the display value to a large finite number so infinity on the
        -- slider still produces a fully white screen.
        local brightness = card.Options.Brightness.Value
        if brightness == math.huge then brightness = 1000 end
        write("Brightness",brightness)
        write("GlobalShadows",false)
        write("FogEnd",100000)
        write("Ambient",Color3.fromRGB(178,178,178))
        write("OutdoorAmbient",Color3.fromRGB(178,178,178))
        if card.Options["Time Changer"].Value then
            if appliedTime ~= nil and lighting.ClockTime ~= appliedTime then originalTime = lighting.ClockTime end
            if originalTime == nil then originalTime = lighting.ClockTime end
            elapsed = (elapsed + math.max(0,dt or 0)) % 4
            appliedTime = (card.Options["Fast time"].Value and elapsed * 6 or card.Options.Time.Value) % 24
            lighting.ClockTime = appliedTime
        else restoreTime() end
    end
    card = context.framework.Categories.Render:CreateModule({Name="Fullbright",Category="Render",ConfigKey="Universal.Fullbright",
        Tooltip="Bright lighting; optionally control the time of day.",Function=function(enabled)
            if not enabled then restore(); return end
            elapsed = 0
            card:Clean(restore)
            tick(0);card:Loop(tick)
        end})
    card:CreateSlider({Name="Brightness",Min=-10,Max=math.huge,Default=3})
    card:CreateToggle({Name="Time Changer",Default=false,Function=function(value) if not value then restoreTime() end end})
    card:CreateSlider({Name="Time",Min=0,Max=24,Default=14,Show={Option="Time Changer",Values={true}}})
    card:CreateToggle({Name="Fast time",Default=false,Show={Option="Time Changer",Values={true}},Tooltip="Loop a full day every four seconds."})
    Module.Initialized=true
    return card
end
function Module.destroy()
    if card and card.Enabled then card:Toggle(false) end
    card=nil;Module.Initialized=false
end
return Module

]],
        ["src/games/universal/Render/HP.lua"] = [[
local Module = {Name = "HP", Initialized = false}
local activeCard, cleanup, hud, roleBinding

-- Shared by world bars and Self HP; finite/max-health guards avoid NaN UI sizes.
local function healthValues(health, maximum)
    if type(health) ~= "number" or health ~= health or math.abs(health) == math.huge then health = 0 end
    if type(maximum) ~= "number" or maximum ~= maximum or maximum <= 0 or maximum == math.huge then maximum = 100 end
    health = math.max(0, health)
    return health, maximum, math.clamp(health / maximum, 0, 1)
end
local function healthColour(fraction)
    local low, mid, high = Color3.fromRGB(255,70,70), Color3.fromRGB(255,220,60), Color3.fromRGB(85,255,85)
    return fraction < 0.5 and low:Lerp(mid, fraction * 2) or mid:Lerp(high, (fraction - 0.5) * 2)
end

function Module.init(context: any): any
    local host, render, entity = context.host, context.render, context.entity
    local create = host.create
    local layer, tracked = render:Layer("HPLayer"), {}
    local store = host.configData
    if store and store.states["Universal.HP"] == nil then
        store.states["Universal.HP"] = store.states["Universal.PlayerESP"] == true
            and (store.states["Universal.PlayerESP.Healthbar"] ~= false or store.states["Universal.PlayerESP.Healthtext"] == true)
    end
    -- Vape Health is a simple number + heart near the crosshair, not a card.
    hud = create("TextLabel", {Name="SelfHP",Parent=host.ScreenGui,
        AnchorPoint=Vector2.new(0.5,0),Position=UDim2.new(0.5,6,0.5,30),Size=UDim2.fromOffset(140,24),
        BackgroundTransparency=1,BorderSizePixel=0,Visible=false,ZIndex=20,
        Text="",Font=Enum.Font.Arial,TextSize=18,TextStrokeTransparency=1,TextColor3=healthColour(1)})
    local scale = create("UIScale", {Parent=hud,Scale=1})
    local card
    local function clear()
        render:ReleaseAll(layer); table.clear(tracked); layer.Visible = false
        hud.Visible = false; hud.Text = ""
    end
    card = context.framework.Categories.Visuals:CreateModule({Name = "HP", Category = "Render", ConfigKey = "Universal.HP", Order = 4,
        Tooltip = "Independent player health bars and optional heart-style Self HP display.", Function = function(enabled)
            if not enabled then clear(); card:SetStatus(nil); return end
            card:Clean(clear)
            card:Render(function(dt)
                local options = card.Options
                local targets = entity:Refresh()
                local camera = (host.workspace or workspace).CurrentCamera
                layer.Visible = true
                local seen, count = {}, 0
                if camera and options.Players.Value then
                    for _, target in ipairs(targets) do
                        if not target.Player or target.Health <= 0 or target.Distance > options["Max distance"].Value
                            or not (roleBinding.provider and roleBinding.provider.ReplacesTeams) and not options.Teammates.Value and target.IsFriendly then continue end
                        local rect = render:ModelRect(camera,target.Character)
                        if not rect or not options["Through walls"].Value and not entity:VisibleFrom(target) then continue end
                        local health, maximum, fraction = healthValues(target.Health,target.MaxHealth)
                        local drawing = render:Set(layer,target.Player)
                        drawing:Show(true); drawing:Bar(Vector2.new(rect.left-2,rect.top), rect.height, fraction)
                        if options["Health text"].Value then
                            drawing:Label("HP", tostring(math.ceil(health)), Vector2.new(rect.left-14,rect.top+(1-fraction)*rect.height), 0.5, 12, healthColour(fraction), false)
                        else drawing:HideLabel("HP") end
                        tracked[target.Player] = true; seen[target.Player] = true; count += 1
                    end
                end
                for player in pairs(tracked) do if not seen[player] then render:Release(layer,player); tracked[player] = nil end end
                hud.Visible = options["Self HP"].Value
                if hud.Visible then
                    local character = host.LocalPlayer.Character
                    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
                    local health, maximum, fraction = healthValues(humanoid and humanoid.Health, humanoid and humanoid.MaxHealth)
                    local wanted = humanoid and humanoid.Health > 0 and tostring(math.ceil(health)) .. " ❤️" or ""
                    if hud.Text ~= wanted then hud.Text = wanted end
                    hud.TextColor3 = healthColour(fraction)
                    hud.Position = options["Self HP position"].Value == "Bottom" and UDim2.new(0.5,0,1,-110) or UDim2.new(0.5,6,0.5,30)
                    local wantedScale = options["Self HP scale"].Value
                    if camera then wantedScale = math.min(wantedScale, math.max(0.5, (camera.ViewportSize.X - 24) / 140)) end
                    scale.Scale = wantedScale
                end
                card:SetStatus(options["Self HP"].Value and tostring(count) .. " + self" or tostring(count))
            end)
        end})
    card:CreateToggle({Name = "Players", Default = true})
    card:CreateToggle({Name = "Health text", Default = false, Show = {Option = "Players"}})
    card:CreateSlider({Name = "Max distance", Min = 50, Max = 5000, Default = 2000, Show = {Option = "Players"}})
    card:CreateToggle({Name = "Teammates", Default = true, Show = {Option = "Players"}})
    card:CreateToggle({Name = "Through walls", Default = true, Show = {Option = "Players"}})
    card:CreateToggle({Name = "Self HP", Default = false})
    card:CreateDropdown({Name="Self HP position",List={"Center","Bottom"},Index=1,Show={Option="Self HP"}})
    card:CreateSlider({Name = "Self HP scale", Min = 0.8, Max = 1.6, Decimal = 1, Default = 1, Show = {Option = "Self HP"}})
    roleBinding = context.services.gameRoles:Bind(card, {palette = false})
    card.OptionFilter = function(name)
        return not (name == "Teammates" and roleBinding.provider and roleBinding.provider.ReplacesTeams)
    end
    card:RefreshVisibility()
    activeCard, cleanup = card, clear
    Module.Initialized = true
    return card
end
function Module.destroy()
    if activeCard and activeCard.Enabled then activeCard:Toggle(false) end
    if cleanup then cleanup() end
    if hud then hud:Destroy() end
    if roleBinding then roleBinding:Destroy() end
    activeCard, cleanup, hud, roleBinding = nil, nil, nil, nil
    Module.Initialized = false
end
return Module

]],
        ["src/games/universal/Render/ItemRender.lua"] = [[
export type Runtime = {
    framework: any,
    entity: any,
    host: any,
    render: any,
    services: any,
}

local Module = {
    Name = "ItemRender",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
    layer = nil :: Frame?,
}

local activeCleanup: (() -> ())? = nil

-- A game provider (Gun ESP, Trap ESP, ...) only draws while Item ESP is ON,
-- and the card owns that switch. Turning the provider row ON with the card
-- OFF used to leave the row ON and silently dead; now it brings the card
-- with it, so ON always means drawn.
local function setProviderEnabled(
    render: any,
    providerStates: {[string]: boolean},
    provider: any,
    value: boolean
): ()
    providerStates[provider.name] = value
    if render.Enabled then
        pcall(provider.setEnabled, value)
        return
    end
    if not value then
        return
    end
    -- The card's own switch, not the internal state: the user must see Item
    -- ESP turn ON, not only behind the scenes.
    local feature: any = render.Feature
    if feature
        and type(feature.activate) == "function"
        and feature.enabled ~= true then
        feature.activate()
    else
        render:Toggle(true)
    end
end

-- Bounded template fingerprint, not semantic image recognition. Ignore names,
-- world position and colour; compare geometry and mesh asset identity instead.
function Module.appearanceSignature(object: Instance): string?
    local parts: {BasePart} = {}
    local queue: {Instance} = {object}
    local cursor: number = 1
    while cursor <= #queue do
        local node: Instance = queue[cursor]
        cursor += 1
        if node:IsA("BasePart") then table.insert(parts, node :: BasePart) end
        if #parts > 32 then return nil end
        for _, child: Instance in ipairs(node:GetChildren()) do
            if #queue >= 96 then return nil end
            table.insert(queue, child)
        end
    end
    if #parts == 0 then return nil end
    local center: Vector3 = Vector3.zero
    for _, part: BasePart in ipairs(parts) do center += part.Position end
    center /= #parts
    local function numberKey(value: number): string
        return tostring(math.round(value * 20)) -- 0.05 stud tolerance
    end
    local function vectorKey(value: Vector3): string
        return numberKey(value.X) .. "," .. numberKey(value.Y) .. "," .. numberKey(value.Z)
    end
    local tokens: {string} = {}
    for _, part: BasePart in ipairs(parts) do
        local meshId: string = ""
        local meshShape: string = ""
        if part:IsA("MeshPart") then meshId = (part :: MeshPart).MeshId end
        local mesh: SpecialMesh? = part:FindFirstChildOfClass("SpecialMesh") :: SpecialMesh?
        if mesh then
            meshId = mesh.MeshId
            meshShape = tostring(mesh.MeshType) .. ":" .. vectorKey(mesh.Scale)
                .. ":" .. vectorKey(mesh.Offset)
        end
        local shape: string = part:IsA("Part") and tostring((part :: Part).Shape) or part.ClassName
        -- Pairwise distances preserve composition across rotation/translation.
        local distances: {string} = {}
        for _, other: BasePart in ipairs(parts) do
            table.insert(distances, numberKey((part.Position - other.Position).Magnitude))
        end
        table.sort(distances)
        table.insert(tokens, table.concat({part.ClassName, shape, vectorKey(part.Size),
            meshId, meshShape, numberKey((part.Position - center).Magnitude),
            table.concat(distances, ",")}, ":"))
    end
    table.sort(tokens)
    return table.concat(tokens, "|")
end

function Module.init(context: Runtime): any
    local host: any = context.host
    local framework: any = context.framework
    local localPlayer: Player = host.LocalPlayer
    local userInput: UserInputService = host.UserInputService
    local currentWorkspace: Workspace = host.workspace or workspace
    local menu: any = context.services.menu

    local tracked: {[Instance]: boolean} = {}

    local index: {Instance} = {}
    local indexConnections: {RBXScriptConnection} = {}
    local indexDirty: boolean = true

    local known: {string} = {}
    local wanted: {string} = {}
    local picking: boolean = false
    local touchMatching: string = "Appearance"
    local appearances: {[string]: string} = {}
    local signatureCache: {[Instance]: any} = setmetatable({}, {__mode = "k"})
    local profileSequence: number = 0
    local nextIndexAt: number = 0
    local nextShapeRefresh: number = 0

    local function signature(instance: Instance): string?
        if signatureCache[instance] == nil then
            signatureCache[instance] = Module.appearanceSignature(instance) or false
        end
        return signatureCache[instance] or nil
    end

    local function release(instance: Instance): ()
        if not tracked[instance] then
            return
        end
        tracked[instance] = nil
        local renderLib: any = context.render
        if renderLib and Module.layer then
            renderLib:Release(Module.layer, instance)
        end
    end

    local function releaseAll(): ()
        for instance: Instance in pairs(tracked) do
            release(instance)
        end
    end

    local function matches(instance: Instance): boolean
        local lowered: string = string.lower(instance.Name)
        for _, entry: string in ipairs(wanted) do
            local appearance: string? = appearances[entry]
            if appearance then
                if signature(instance) == appearance then return true end
            elseif not string.match(entry, "^Look #%d+ ")
                and string.find(lowered, string.lower(entry), 1, true) then
                return true
            end
        end
        return false
    end

    local function rebuildIndex(): ()
        table.clear(index)
        indexDirty = false
        if #wanted == 0 then
            return
        end
        for _, descendant: Instance in ipairs(currentWorkspace:GetDescendants()) do
            if descendant:IsA("BasePart") or descendant:IsA("Model") or descendant:IsA("Tool") then
                if matches(descendant) then
                    table.insert(index, descendant)
                end
            end
        end
    end

    local function watchWorkspace(): ()
        local function changed(descendant: Instance): ()
            signatureCache[descendant] = nil
            local ancestor: Instance? = descendant.Parent
            while ancestor and ancestor ~= currentWorkspace do
                signatureCache[ancestor] = nil
                ancestor = ancestor.Parent
            end
            if #wanted > 0 then indexDirty = true end
        end
        table.insert(indexConnections, currentWorkspace.DescendantAdded:Connect(changed))
        table.insert(indexConnections, currentWorkspace.DescendantRemoving:Connect(changed))
    end

    local renderLib: any = context.render
    local layer: Frame? = renderLib and renderLib:Layer("ItemRenderLayer") or nil
    Module.layer = layer

    local itemEsp: any = context.services and context.services.itemEsp
    local providerStates: {[string]: boolean} = {}

    local function forEachProvider(callback: (any) -> ()): ()
        if not itemEsp or type(itemEsp.providers) ~= "function" then
            return
        end
        for _, provider: any in ipairs(itemEsp.providers()) do
            pcall(callback, provider)
        end
    end

    local render: any
    render = framework.Categories.Visuals:CreateModule({
        Name = "ItemESP",
        Category = "Render",
        ConfigKey = "Universal.ItemRender",
        Order = 2,
        Tooltip = "Names and outlines every object on the list, wherever it is.",
        Function = function(enabled: boolean): ()
            if layer then
                layer.Visible = enabled
            end
            if not enabled then
                forEachProvider(function(provider: any): ()
                    if providerStates[provider.name] then
                        pcall(provider.setEnabled, false)
                    end
                end)
                render:SetStatus(nil)
                releaseAll()
                picking = false
                return
            end
            forEachProvider(function(provider: any): ()
                if providerStates[provider.name] then
                    pcall(provider.setEnabled, true)
                end
            end)
            render:SetStatus("0")
            render:Clean(function(): ()
                releaseAll()
                picking = false
                if layer then
                    layer.Visible = false
                end
            end)
            indexDirty = true
            watchWorkspace()
            render:Clean(function(): ()
                for _, connection: RBXScriptConnection in ipairs(indexConnections) do
                    pcall(function(): ()
                        connection:Disconnect()
                    end)
                end
                indexConnections = {}
                table.clear(index)
            end)
            render:Render(function(): ()
                -- Assets can fill MeshId/Size after parenting (streaming).
                -- Refresh at low frequency, never traverse geometry per frame.
                if next(appearances) ~= nil and os.clock() >= nextShapeRefresh then
                    nextShapeRefresh = os.clock() + 5
                    signatureCache = setmetatable({}, {__mode = "k"})
                    indexDirty = true
                end
                if indexDirty and os.clock() >= nextIndexAt then
                    nextIndexAt = os.clock() + 0.25
                    rebuildIndex()
                end
                Module.render(context, render, tracked, wanted, release, index, matches)
            end)
        end,
    })

    local objectList: any
    objectList = render:CreateList({
        Name = "Objects",
        Items = function(): {string}
            return known
        end,
        Tooltip = "Every object the module knows about. Tick the ones to draw.",
        Function = function(_selected: any, names: {string}): ()
            wanted = names
            indexDirty = true
            releaseAll()
        end,
    })

    local function learn(name: string): ()
        if name == "" then
            return
        end
        if not table.find(known, name) then
            table.insert(known, name)
            table.sort(known)
        end
        objectList:Set(name, true)
    end

    local function findBestMatchingName(query: string): string?
        local lowered: string = string.lower(query)
        local candidates: {string} = {}
        for _, descendant: Instance in ipairs(currentWorkspace:GetDescendants()) do
            if descendant:IsA("BasePart") or descendant:IsA("Model") or descendant:IsA("Tool") then
                local dName: string = descendant.Name
                local dLower: string = string.lower(dName)
                if dLower == lowered then
                    return dName
                end
                if string.find(dLower, lowered, 1, true) then
                    table.insert(candidates, dName)
                end
            end
        end
        for _, c: string in ipairs(candidates) do
            if string.find(string.lower(c), "^" .. lowered) then
                return c
            end
        end
        if #candidates > 0 then
            return candidates[1]
        end
        return nil
    end

    local pendingInput: string = ""
    local addBox: any

    local function commitAddByName(rawText: string?): ()
        local text: string = rawText or pendingInput
        local trimmed: string = string.match(text, "^%s*(.-)%s*$") or text
        if trimmed == "" or #trimmed < 2 then
            return
        end
        local best: string = findBestMatchingName(trimmed) or trimmed
        learn(best)
        render:SetStatus("Added: " .. best)
        pendingInput = ""
        if addBox and addBox.Object and typeof(addBox.Object) == "Instance" and addBox.Object:IsA("TextBox") then
            addBox.Object.Text = ""
        end
    end

    addBox = render:CreateTextBox({
        Name = "Add by name",
        Default = "",
        Tooltip = "Type a name and press Enter (or click Add Object). Finds closest matching items.",
        Function = function(value: string): ()
            pendingInput = value
        end,
    })

    if addBox and addBox.Object and typeof(addBox.Object) == "Instance" and addBox.Object:IsA("TextBox") then
        local box: TextBox = addBox.Object
        box.FocusLost:Connect(function(enterPressed: boolean)
            if enterPressed then
                commitAddByName(box.Text)
            end
        end)
    end

    render:CreateButton({
        Name = "Add object",
        Tooltip = "Adds the name typed above to the list.",
        Function = function(): ()
            local text: string = (addBox.Object and addBox.Object.Text) or pendingInput
            commitAddByName(text)
        end,
    })

    local function resolveItemInstance(part: BasePart): Instance
        local tool: Tool? = part:FindFirstAncestorOfClass("Tool")
        if tool then
            return tool
        end
        local parent: Instance? = part.Parent
        if parent and parent:IsA("Model") and parent ~= currentWorkspace then
            local parentNameLower: string = string.lower(parent.Name)
            local isGenericMap: boolean = parentNameLower == "map"
                or parentNameLower == "workspace"
                or parentNameLower == "geometry"
                or parentNameLower == "spawns"
                or parentNameLower == "terrain"
                or parentNameLower == "baseplate"
            local childCount: number = #parent:GetChildren()
            if not isGenericMap and childCount <= 15 then
                return parent
            end
        end
        return part
    end

    render:CreateDropdown({
        Name = "Touch matching",
        List = {"Appearance", "Name"},
        Index = 1,
        Function = function(value: string): () touchMatching = value end,
        Tooltip = "Appearance matches a small geometry/mesh template, not every Model. "
            .. "Templates last this session; reselect after rejoining. Name keeps the old search.",
    })

    render:CreateButton({
        Name = "Touch part",
        Tooltip = "Hides the menu, then adds whatever you tap next.",
        Function = function(): ()
            if picking then
                picking = false
                render:SetStatus("cancelled")
                return
            end
            picking = true

            menu.setVisible(false)
            render:Notify("tap the object you want rendered")
        end,
    })

    render:CreateButton({
        Name = "Clear list",
        Function = function(): ()
            for _, name: string in ipairs(known) do
                objectList:Set(name, false)
            end
            table.clear(known)
            table.clear(appearances)
            signatureCache = setmetatable({}, {__mode = "k"})
            wanted = {}
            objectList:Refresh()
            releaseAll()
            render:SetStatus("list cleared")
        end,
    })

    render:CreateToggle({
        Name = "Show distance",
        Default = true,
    })
    render:CreateToggle({
        Name = "Outline",
        Default = true,
        Tooltip = "Draw the object's silhouette through walls.",
    })
    render:CreateSlider({
        Name = "Max distance",
        Min = 50,
        Max = 5000,
        Default = 1200,
    })
    render:CreateSlider({
        Name = "Text size",
        Min = 8,
        Max = 22,
        Default = 12,
    })
    render:CreateColor({
        Name = "Colour",
        Default = Color3.fromRGB(85, 255, 85),
    })

    local pickConnection: RBXScriptConnection = userInput.InputBegan:Connect(
        function(input: InputObject, processed: boolean): ()
            if not picking or processed then
                return
            end
            if input.UserInputType ~= Enum.UserInputType.Touch
                and input.UserInputType ~= Enum.UserInputType.MouseButton1 then
                return
            end
            local camera: Camera? = currentWorkspace.CurrentCamera
            if not camera then
                return
            end

            local ray: Ray = (camera :: Camera):ScreenPointToRay(
                input.Position.X,
                input.Position.Y
            )
            local parameters: RaycastParams = RaycastParams.new()
            parameters.FilterType = Enum.RaycastFilterType.Exclude
            parameters.IgnoreWater = true
            parameters.FilterDescendantsInstances = {
                localPlayer.Character :: any,
                camera,
            }
            local result: RaycastResult? = currentWorkspace:Raycast(
                ray.Origin,
                ray.Direction.Unit * 4096,
                parameters
            )
            if not result then
                render:Notify("nothing under that tap")
                return
            end
            picking = false

            local hit: Instance = (result :: RaycastResult).Instance
            if not hit:IsA("BasePart") then
                render:Notify("invalid part tapped")
                menu.setVisible(true)
                return
            end
            local targetItem: Instance = resolveItemInstance(hit :: BasePart)
            local name: string = targetItem.Name
            if touchMatching == "Appearance" then
                -- Refresh cached geometry when the user explicitly selects.
                local fingerprint: string? = Module.appearanceSignature(targetItem)
                if not fingerprint then
                    menu.setVisible(true)
                    render:Notify("Object too large/complex; select a smaller part or use Name")
                    return
                end
                profileSequence += 1
                name = "Look #" .. tostring(profileSequence) .. " (" .. name .. ")"
                appearances[name] = fingerprint
            end
            learn(name)
            menu.setVisible(true)
            render:SetStatus(name .. " added")
        end
    )

    render:CreateNote(
        "Touch matching: Appearance selects matching geometry in this session; Name selects by name."
    )

    -- Game-provided item highlights (for example MM2's Gun ESP and Trap ESP)
    -- appear here as their own toggles. The card itself stays game-agnostic:
    -- games register providers, this module only renders them.
    local providerOptionNames: {[string]: boolean} = {}
    local function attachProvider(provider: any): ()
        if providerOptionNames[provider.name] then
            return
        end
        providerOptionNames[provider.name] = true
        render:CreateToggle({
            Name = provider.name,
            Default = false,
            Tooltip = provider.tooltip,
            Function = function(value: boolean): ()
                setProviderEnabled(render, providerStates, provider, value)
            end,
        })
    end
    forEachProvider(attachProvider)
    local providerWatch: (() -> ())? = nil
    if itemEsp and type(itemEsp.onChanged) == "function" then
        providerWatch = itemEsp.onChanged(function(): ()
            forEachProvider(attachProvider)
        end)
    end

    activeCleanup = function(): ()
        if render.Enabled then render:Toggle(false) end
        picking = false
        pcall(function(): ()
            pickConnection:Disconnect()
        end)
        if providerWatch then
            pcall(providerWatch)
            providerWatch = nil
        end
        for _, connection: RBXScriptConnection in ipairs(indexConnections) do
            connection:Disconnect()
        end
        table.clear(indexConnections)
        releaseAll()
    end
    Module.Initialized = true
    return render
end

function Module.render(
    context: Runtime,
    render: any,
    tracked: {[Instance]: any},
    wanted: {string},
    release: (Instance) -> (),
    index: {Instance},
    matches: (Instance) -> boolean
): ()
    local host: any = context.host
    local renderLib: any = context.render
    local layer: Frame? = Module.layer
    local localPlayer: Player = host.LocalPlayer
    local options: any = render.Options
    local currentWorkspace: Workspace = host.workspace or workspace
    local camera: Camera? = currentWorkspace.CurrentCamera

    if #wanted == 0 or not renderLib or not layer or not camera then
        for instance: Instance in pairs(tracked) do
            release(instance)
        end
        return
    end

    local resolvedCamera: Camera = camera :: Camera
    local resolvedLayer: Frame = layer :: Frame
    local character: Model? = localPlayer.Character
    local root: BasePart? = character
        and character:FindFirstChild("HumanoidRootPart") :: BasePart?
    local origin: Vector3 = root and (root :: BasePart).Position or Vector3.zero
    local maxDistance: number = options["Max distance"].Value
    local colour: Color3 = options["Colour"].Value
    local textSize: number = math.round(options["Text size"].Value)
    local seen: {[Instance]: boolean} = {}

    for _, descendant: Instance in ipairs(index) do
        if not descendant.Parent then
            continue
        end
        local isPart: boolean = descendant:IsA("BasePart")
        local isModel: boolean = descendant:IsA("Model") or descendant:IsA("Tool")
        if not isPart and not isModel then
            continue
        end
        if character and descendant:IsDescendantOf(character) then
            continue
        end
        if not matches(descendant) then
            continue
        end
        local duplicate: boolean = false
        local ancestor: Instance? = descendant.Parent
        while ancestor and ancestor ~= currentWorkspace do
            if (ancestor:IsA("Model") or ancestor:IsA("Tool")) and matches(ancestor) then
                duplicate = true
                break
            end
            ancestor = ancestor.Parent
        end
        if duplicate then continue end

        local anchor: BasePart? = nil
        if isPart then
            anchor = descendant :: BasePart
        else
            anchor = descendant:IsA("Model") and (descendant :: Model).PrimaryPart or nil
            anchor = anchor or descendant:FindFirstChildWhichIsA("BasePart", true) :: BasePart?
        end
        if not anchor then
            continue
        end
        local resolvedAnchor: BasePart = anchor :: BasePart
        local distance: number = (resolvedAnchor.Position - origin).Magnitude
        if distance > maxDistance then
            continue
        end
        local projected: Vector2? = renderLib:Project(resolvedCamera, resolvedAnchor.Position)
        if not projected then
            continue
        end

        seen[descendant] = true
        tracked[descendant] = true
        local drawings: any = renderLib:Set(resolvedLayer, descendant)
        drawings:Show(true)
        drawings:Label(
            "NameTag",
            options["Show distance"].Value
                    and ("[" .. tostring(math.round(distance)) .. "] " .. descendant.Name)
                or descendant.Name,
            projected :: Vector2,
            0.5,
            textSize,
            colour,
            true
        )
        drawings:Highlight(
            descendant,
            colour,
            1,
            options["Outline"].Value and "Outline" or "Off"
        )
    end

    local count: number = 0
    for instance: Instance in pairs(tracked) do
        if not seen[instance] or not instance.Parent then
            release(instance)
        else
            count += 1
        end
    end
    local status: string = tostring(count)
    if render.Status ~= status then
        render:SetStatus(status)
    end
end

function Module.destroy(): ()
    if activeCleanup then
        pcall(activeCleanup)
    end
    activeCleanup = nil
    Module.layer = nil
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Render/Markers.lua"] = [[
-- Vape-style world waypoints, with names / Save here instead of encoded coordinates.
local Module = {Name="Markers",Initialized=false}
local card, clear, inputConnection, services
function Module.init(context)
    local host, render = context.host, context.render
    services = context.services
    local menu = services.menu
    local layer = render:Layer("MarkersLayer")
    local key = "Universal.Markers.Places." .. tostring(game.PlaceId)
    local config = host.configData
    local points = {}
    local stored = config and config.values[key]
    if type(stored) ~= "table" then stored = {} end
    local loaded = 0
    for name, position in pairs(stored) do
        if type(name)=="string" and type(position)=="table" and loaded < 128 then
            local x,y,z=tonumber(position[1]),tonumber(position[2]),tonumber(position[3])
            if x and y and z and x==x and y==y and z==z and math.max(math.abs(x),math.abs(y),math.abs(z)) < 1e7 then
                points[name]={x,y,z,position[4]=="surface" and "surface" or nil}; loaded += 1
            end
        end
    end
    local listeners = {}
    local function pointNames()
        local names={};for name in pairs(points) do table.insert(names,name) end;table.sort(names);return names
    end
    services.points = {
        Names=pointNames,
        Get=function(name)
            local data=points[name]
            if data then return Vector3.new(data[1],data[2],data[3]),data[4]=="surface" end
        end,
        Subscribe=function(callback)
            listeners[callback]=true
            return function() listeners[callback]=nil end
        end,
    }
    local list, tracked = nil, {}
    local picking, pickName, pickMenuVisible = false, nil, false
    local function finishPick(status, reopen)
        local wasPicking = picking
        picking = false
        if card then card:SetStatus(status) end
        if wasPicking and pickMenuVisible and reopen ~= false then menu.setVisible(true) end
        pickMenuVisible = false
    end
    local function save()
        if config then config.values[key]=points;if host.queueConfigSave then host.queueConfigSave() end end
        for callback in pairs(listeners) do callback() end
    end
    clear=function(reopen) render:ReleaseAll(layer);table.clear(tracked);layer.Visible=false;finishPick(nil,reopen) end
    card=context.framework.Categories.Render:CreateModule({Name="Markers",Category="Render",ConfigKey="Universal.Markers",
        Tooltip="Save your standing coordinates or mark a surface. Points are shared with Teleport and kept per game.",Function=function(enabled)
            if not enabled then clear();return end
            layer.Visible=true;card:Clean(clear)
            card:Render(function()
                local camera=(host.workspace or workspace).CurrentCamera
                if not camera then clear();return end
                layer.Visible=true
                local seen={}
                for name, data in pairs(points) do
                    if not list:IsSelected(name) then continue end
                    local position=Vector3.new(data[1],data[2],data[3])
                    local at=render:Project(camera,position)
                    if not at or at.X<0 or at.Y<0 or at.X>camera.ViewportSize.X or at.Y>camera.ViewportSize.Y then continue end
                    local text=name
                    if card.Options.Distance.Value then text ..= " [" .. math.round((camera.CFrame.Position-position).Magnitude) .. "]" end
                    local drawing=render:Set(layer,name)
                    drawing:Show(true)
                    drawing:Label("Marker",text,Vector2.new(at.X,at.Y),1,14,card.Options.Colour.Value,true)
                    seen[name],tracked[name]=true,true
                end
                for name in pairs(tracked) do if not seen[name] then render:Release(layer,name);tracked[name]=nil end end
            end)
        end})
    local function pointName()
        return string.sub(string.match(card.Options.Name.Value or "","^%s*(.-)%s*$") or "",1,48)
    end
    local function nextPointName()
        local base=pointName()
        local index=1
        while true do
            local suffix=base=="" and tostring(index) or " #"..index
            local name=(base=="" and "Point " or string.sub(base,1,48-#suffix))..suffix
            if not points[name] then return name end
            index+=1
        end
    end
    local function savedName()
        local name=pointName()
        return name~="" and name or nextPointName()
    end
    local function storePoint(position,name,surface)
        if name=="" then card:Notify("Enter a point name.");return false end
        if not position or position.X~=position.X or position.Y~=position.Y or position.Z~=position.Z
            or math.max(math.abs(position.X),math.abs(position.Y),math.abs(position.Z))>=1e7 then
            card:Notify("Position unavailable. Use coordinates in the form x, y, z.");return false
        end
        local count=0;for _ in pairs(points) do count+=1 end
        if count>=128 and not points[name] then card:Notify("Marker limit reached (128). Delete a point first.");return false end
        points[name]={position.X,position.Y,position.Z,surface and "surface" or nil};save();list:Refresh();list:Set(name,true)
        card:SetStatus(name);return true
    end
    card:CreateTextBox({Name="Name",Default="",Placeholder="Home, exit, meeting spot..."})
    card:CreateButton({Name="Save here",Tooltip="Save your character standing x, y, z here, not the camera position.",Function=function()
        local character=host.LocalPlayer.Character
        local root=character and character:FindFirstChild("HumanoidRootPart")
        storePoint(root and root.Position,savedName())
    end})
    card:CreateButton({Name="Touch",Tooltip="Hides the menu to pick a surface. Escape cancels; new points are numbered, never overwritten. Works while OFF too.",Function=function()
        if picking then finishPick();return end
        pickName=nextPointName()
        picking=true
        pickMenuVisible=menu.isVisible()
        card:SetStatus("Click/tap a surface · Esc cancels")
        menu.setVisible(false)
    end})
    if config and config.values["Universal.Markers.Point"]==nil then
        config.values["Universal.Markers.Point"]=config.values["Universal.Markers.Places"]
    end
    list=card:CreateList({Name="Point",Items=pointNames,Default=pointNames(),
        EmptyText="No points. Use Save here or Touch.",OnRemove=function(name)
            if not points[name] then return end
            list:Set(name,false);points[name]=nil;save();list:Refresh()
            render:Release(layer,name);tracked[name]=nil
        end})
    card:CreateToggle({Name="Manual coordinates",Default=false})
    card:CreateTextBox({Name="Coordinates",Default="",Placeholder="x, y, z",Show={Option="Manual coordinates",Values={true}}})
    card:CreateButton({Name="Save coordinates",Show={Option="Manual coordinates",Values={true}},Function=function()
        local x,y,z=string.match(card.Options.Coordinates.Value or "","^%s*([%+%-%.%deE]+)%s*,%s*([%+%-%.%deE]+)%s*,%s*([%+%-%.%deE]+)%s*$")
        x,y,z=tonumber(x),tonumber(y),tonumber(z)
        storePoint(x and y and z and Vector3.new(x,y,z) or nil,savedName())
    end})
    card:CreateToggle({Name="Distance",Default=true})
    card:CreateColor({Name="Colour",Default=Color3.fromRGB(85,255,85)})
    inputConnection=host.UserInputService.InputBegan:Connect(function(event,processed)
        if not picking then return end
        if event.KeyCode==Enum.KeyCode.Escape then
            finishPick();return
        end
        if processed or host.UserInputService:GetFocusedTextBox() then return end
        if event.UserInputType~=Enum.UserInputType.MouseButton1 and event.UserInputType~=Enum.UserInputType.Touch then return end
        local camera=(host.workspace or workspace).CurrentCamera
        if not camera then return end
        local params=RaycastParams.new()
        params.FilterType=Enum.RaycastFilterType.Exclude
        params.FilterDescendantsInstances=host.LocalPlayer.Character and {host.LocalPlayer.Character} or {}
        params.RespectCanCollide=true;params.IgnoreWater=true
        local ray=camera:ScreenPointToRay(event.Position.X,event.Position.Y)
        local hit=(host.workspace or workspace):Raycast(ray.Origin,ray.Direction*5000,params)
        if hit and storePoint(hit.Position,pickName,true) then finishPick(pickName)
        else card:SetStatus("No surface · tap again") end
    end)
    Module.Initialized=true
    return card
end
function Module.destroy()
    if clear then clear(false) end
    if card and card.Enabled then card:Toggle(false) end
    if inputConnection then inputConnection:Disconnect();inputConnection=nil end
    if services then services.points=nil end
    card,clear,services=nil,nil,nil;Module.Initialized=false
end
return Module

]],
        ["src/games/universal/Render/NPCESP.lua"] = [[
export type Runtime = {
    framework: any,
    entity: any,
    render: any,
    host: any,
    services: any,
}

local Module = {
    Name = "NPCESP",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local activeCard: any = nil

local STANDARD_PART_NAMES: {[string]: boolean} = {
    head = true,
    torso = true,
    uppertorso = true,
    lowertorso = true,
    humanoidrootpart = true,
    leftarm = true,
    rightarm = true,
    leftleg = true,
    rightleg = true,
    leftupperarm = true,
    leftlowerarm = true,
    lefthand = true,
    rightupperarm = true,
    rightlowerarm = true,
    righthand = true,
    leftupperleg = true,
    leftlowerleg = true,
    leftfoot = true,
    rightupperleg = true,
    rightlowerleg = true,
    rightfoot = true,
}

local VERDICT_COOLDOWN: number = 0.5

local function normalizeName(value: string): string
    local normalized: string = string.lower(value):gsub("[%s_%-]", "")
    return normalized
end

function Module.init(context: Runtime): any
    local framework: any = context.framework
    local render: any = context.render
    local host: any = context.host
    local players: Players = host.Players
    local currentWorkspace: Workspace = host.workspace or workspace
    local layer: Frame = render:Layer("NpcEspLayer")
    local lastStatusAt: number = -math.huge
    local lastSweepAt: number = -math.huge

    local bots: {[Model]: boolean} = {}
    local rigInfo: any = setmetatable({}, {__mode = "k"})
    local verdicts: any = setmetatable({}, {__mode = "k"})
    local forcedNames: {string} = {}

    local function modelFor(instance: Instance): Model?
        if instance:IsA("Model") then
            return instance :: Model
        end
        return instance:FindFirstAncestorOfClass("Model") :: Model?
    end

    local function isPlayerCharacterModel(model: Model): boolean
        if players:GetPlayerFromCharacter(model) ~= nil then
            return true
        end
        for _, player: Player in ipairs(players:GetPlayers()) do
            local character: Model? = player.Character
            if character and model:IsDescendantOf(character) then
                return true
            end
        end
        return false
    end

    local function matchesForcedName(model: Model): boolean
        local name: string = string.lower(model.Name)
        for _, needle: string in ipairs(forcedNames) do
            if needle ~= "" and string.find(name, needle, 1, true) then
                return true
            end
        end
        return false
    end

    local function classify(model: Model): string

        if model:GetAttribute("WurstDisguise") == true then
            return "reject"
        end
        if matchesForcedName(model) then
            return "rig"
        end
        local humanoid: Humanoid? = model:FindFirstChildOfClass("Humanoid") :: Humanoid?
        local standardParts: number = 0
        local motors: number = 0
        for _, child: Instance in ipairs(model:GetChildren()) do
            if child:IsA("BasePart") then
                if STANDARD_PART_NAMES[normalizeName(child.Name)] then
                    standardParts += 1
                end
            elseif child:IsA("Motor6D") then
                motors += 1
            end
        end
        if humanoid ~= nil then

            if standardParts >= 3 then
                return "rig"
            end
            return "creature"
        end

        if standardParts >= 4 or (standardParts >= 3 and motors >= 2) then
            return "rig"
        end
        if model:FindFirstChildWhichIsA("Humanoid", true) ~= nil then
            return "creature"
        end
        return "reject"
    end

    local function verdictFor(model: Model): string
        local entry: any = verdicts[model]
        if entry == nil then
            entry = {
                verdict = isPlayerCharacterModel(model) and "reject" or classify(model),
                at = os.clock(),
                dirty = false,
            }
            verdicts[model] = entry
            return entry.verdict
        end
        if entry.dirty then
            local now: number = os.clock()
            if now - entry.at >= VERDICT_COOLDOWN then
                entry.verdict =
                    isPlayerCharacterModel(model) and "reject" or classify(model)
                entry.at = now
                entry.dirty = false
            end
        end
        return entry.verdict
    end

    local function markDirty(model: Model): ()
        local entry: any = verdicts[model]
        if entry and not entry.dirty then
            entry.dirty = true
        end
        rigInfo[model] = nil
    end

    local function invalidate(instance: Instance): ()
        local parent: Instance? = instance.Parent
        if parent and parent:IsA("Model") then
            markDirty(parent :: Model)
        end
        if instance:IsA("Model") then
            markDirty(instance :: Model)
        end
    end

    local function add(model: Model, verdict: string): ()
        if verdict ~= "rig" then
            bots[model] = true
            return
        end

        for existing: Model in pairs(bots) do
            if existing:IsDescendantOf(model) then
                return
            end
            if model:IsDescendantOf(existing) then
                bots[existing] = nil
                render:Release(layer, existing)
            end
        end
        bots[model] = true
    end

    local function inspect(instance: Instance): ()
        if not (instance:IsA("Model") or instance:IsA("Humanoid")
            or instance:IsA("BasePart") or instance:IsA("Motor6D")) then
            return
        end
        invalidate(instance)
        local model: Model? = modelFor(instance)
        local creature: Model? = nil
        while model and model ~= currentWorkspace do
            local verdict: string = verdictFor(model)
            if verdict == "rig" then
                add(model, "rig")
                return
            end
            if verdict == "creature" and creature == nil then
                creature = model
            end
            local parent: Instance? = model.Parent
            if not parent then
                break
            end
            model = parent:IsA("Model") and parent :: Model
                or parent:FindFirstAncestorOfClass("Model") :: Model?
        end
        if creature then
            add(creature, "creature")
        end
    end

    local function sweep(now: number): ()
        for model: any, entry: any in pairs(verdicts) do
            if entry.dirty and now - entry.at >= VERDICT_COOLDOWN then
                local resolved: Model = model :: Model
                local verdict: string =
                    isPlayerCharacterModel(resolved) and "reject" or classify(resolved)
                entry.verdict = verdict
                entry.at = now
                entry.dirty = false
                if verdict == "rig" then
                    add(resolved, "rig")
                end
            end
        end
    end

    local function scan(): ()
        table.clear(bots)
        for _, object: Instance in ipairs(currentWorkspace:GetDescendants()) do
            if object:IsA("Model") then
                inspect(object)
            end
        end
    end

    local function clear(): ()
        render:ReleaseAll(layer)
        table.clear(bots)
        layer.Visible = false
    end

    local card: any
    card = framework.Categories.Visuals:CreateModule({
        Name = "NPCESP",
        Category = "Render",
        ConfigKey = "Universal.NPCESP",
        Order = 4,
        Tooltip = "Displays character-shaped NPC models - bots, shopkeepers "
            .. "and display statues like the creator's rig - whether or not "
            .. "their Humanoid is alive.",
        Function = function(enabled: boolean): ()
            layer.Visible = enabled
            if not enabled then
                clear()
                card:SetStatus(nil)
                return
            end
            scan()
            card:Event(currentWorkspace.DescendantAdded, inspect)
            card:Event(currentWorkspace.DescendantRemoving, invalidate)
            card:Render(function(): ()
                local camera: Camera? = currentWorkspace.CurrentCamera
                if not camera then
                    return
                end
                local resolvedCamera: Camera = camera :: Camera
                local now: number = os.clock()
                if now - lastSweepAt >= 1 then
                    lastSweepAt = now
                    sweep(now)
                end

                local maxDistance: number = card.Options["Max distance"].Value
                local includeCreatures: boolean = card.Options["All humanoids"].Value
                local localCharacter: Model? = host.LocalPlayer.Character
                local localRoot: BasePart? = localCharacter and (
                    localCharacter:FindFirstChild("HumanoidRootPart") :: BasePart?
                    or localCharacter.PrimaryPart
                    or localCharacter:FindFirstChildWhichIsA("BasePart", true) :: BasePart?
                ) or nil
                local origin: Vector3 = localRoot and localRoot.Position
                    or resolvedCamera.CFrame.Position
                local count: number = 0
                for model: Model in pairs(bots) do
                    if not model:IsDescendantOf(currentWorkspace)
                        or players:GetPlayerFromCharacter(model) ~= nil then
                        bots[model] = nil
                        render:Release(layer, model)

                        verdicts[model] = {verdict = "reject", at = now, dirty = false}
                        continue
                    end
                    local verdict: string = verdictFor(model)
                    if verdict == "reject" then
                        bots[model] = nil
                        render:Release(layer, model)
                        continue
                    end

                    if verdict == "creature" and not includeCreatures then

                        render:Release(layer, model)
                        continue
                    end

                    local drawing: any = render:Set(layer, model)

                    local info: any = rigInfo[model]
                    if not (info and info.root and info.root.Parent) then
                        info = {
                            root = model:FindFirstChild("HumanoidRootPart") :: BasePart?
                                or model.PrimaryPart
                                or model:FindFirstChildWhichIsA("BasePart", true) :: BasePart?,
                            humanoid = model:FindFirstChildOfClass("Humanoid") :: Humanoid?
                                or model:FindFirstChildWhichIsA("Humanoid", true) :: Humanoid?,
                        }
                        rigInfo[model] = info
                    end
                    local root: BasePart? = info.root
                    if not root or (root.Position - origin).Magnitude > maxDistance then
                        drawing:Show(false)
                        continue
                    end

                    if verdict == "creature"
                        and info.humanoid
                        and info.humanoid.Health <= 0 then
                        drawing:Show(false)
                        continue
                    end

                    local rect: any = render:ModelRect(resolvedCamera, model)
                    if not rect then
                        drawing:Show(false)
                        continue
                    end

                    local colour: Color3 = card.Options["Colour"].Value
                    drawing:Box(rect, card.Options["Box"].Value and "Full" or "Off", 1, colour)
                    if card.Options["Name"].Value then
                        local text: string = card.Options["Model name"].Value
                            and model.Name ~= "" and model.Name
                            or "BOT"
                        local humanoid: Humanoid? = info.humanoid
                        if humanoid and card.Options["Health"].Value then
                            text ..= " [" .. tostring(math.round(humanoid.Health)) .. "]"
                        end
                        drawing:Label(
                            "NameTag",
                            text,
                            Vector2.new(rect.centreX, rect.top - 4),
                            1,
                            13,
                            colour,
                            true
                        )
                    else
                        drawing:HideLabel("NameTag")
                    end
                    drawing:Highlight(
                        model,
                        colour,
                        0.55,
                        not card.Options["Highlight"].Value and "Off"
                            or (card.Options["Through walls"].Value and "AlwaysOnTop" or "Occluded")
                    )
                    drawing:Show(true)
                    count += 1
                end

                if now - lastStatusAt >= 0.25 then
                    lastStatusAt = now
                    card:SetStatus(tostring(count))
                end
            end)
            card:Clean(clear)
        end,
    })

    card:CreateToggle({Name = "Box", Default = true})
    card:CreateToggle({Name = "Highlight", Default = true})
    card:CreateToggle({Name = "Through walls", Default = true, Show = {Option = "Highlight"}})
    card:CreateToggle({Name = "Name", Default = true})
    card:CreateToggle({
        Name = "Model name",
        Show = {Option = "Name"},
        Default = false,
        Tooltip = "Label each model with its own name instead of BOT.",
    })
    card:CreateToggle({
        Name = "Health",
        Show = {Option = "Name"},
        Default = true,
        Tooltip = "Append the Humanoid's hit points to the label when the "
            .. "model has one.",
    })
    card:CreateToggle({
        Name = "All humanoids",
        Default = false,
        Tooltip = "Also flag non-character models that merely carry a living "
            .. "Humanoid (creatures, monsters). Off by default: NPCESP tracks "
            .. "character-shaped rigs.",
    })
    card:CreateColor({Name = "Colour", Default = Color3.fromRGB(85, 255, 85)})
    card:CreateSlider({Name = "Max distance", Min = 25, Max = 2000, Step = 25, Default = 500})

    local addBox: any
    addBox = card:CreateTextBox({
        Name = "Force by name",
        Default = "",
        Tooltip = "Type a model name and it is always treated as an NPC rig, "
            .. "whatever it is built from. Partial names match, so statue "
            .. "catches CreatorStatue.",
        Function = function(value: string): ()
            local trimmed: string = string.match(value, "^%s*(.-)%s*$") or value
            if trimmed == "" then
                return
            end
            local needle: string = string.lower(trimmed)
            if not table.find(forcedNames, needle) then
                table.insert(forcedNames, needle)
            end
            table.clear(verdicts)
            table.clear(rigInfo)
            if card.Enabled then
                scan()
            end
            addBox:Set("")
        end,
    })

    card:CreateButton({
        Name = "Clear forced names",
        Function = function(): ()
            table.clear(forcedNames)
            table.clear(verdicts)
            table.clear(rigInfo)
            if card.Enabled then
                scan()
            end
        end,
    })

    activeCard = card
    Module.Initialized = true
    return card
end

function Module.destroy(): ()
    if activeCard and activeCard.Enabled then
        activeCard:Toggle(false)
    end
    activeCard = nil
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Render/Nametags.lua"] = [[
local Module = {Name = "Nametags", Initialized = false}
local activeCard, cleanup, roleBinding

function Module.init(context: any): any
    local host, entity, render = context.host, context.entity, context.render
    local layer = render:Layer("NametagsLayer")
    local tracked = {}
    local store = host.configData
    -- Preserve explicit new choices; migrate only previously enabled overlays.
    if store and store.states["Universal.Nametags"] == nil then
        local states, values = store.states, store.values
        states["Universal.Nametags"] = states["Universal.Chams"] == true and states["Universal.Chams.Nametags"] == true
            or states["Universal.PlayerESP"] == true and states["Universal.PlayerESP.Nametags"] ~= false
        if values["Universal.Nametags.Textsize"] == nil then values["Universal.Nametags.Textsize"] = values["Universal.PlayerESP.Textsize"] end
        for new, old in pairs({Background="Nameplate",Displayname="Displayname",Heldtool="Heldtool",Showrole="Showrole",Rolecolours="Rolecolours"}) do
            local key = "Universal.Nametags." .. new
            if states[key] == nil then states[key] = states["Universal.PlayerESP." .. old] end
        end
        for key, colour in pairs(table.clone(values)) do
            if string.sub(key,1,20) == "Universal.PlayerESP." and string.lower(string.sub(key,-6)) == "colour" then
                local newKey = "Universal.Nametags." .. string.sub(key,21)
                if values[newKey] == nil then values[newKey] = colour end
            end
        end
    end
    local textService = game:GetService("TextService")
    local card
    local function clear()
        render:ReleaseAll(layer); table.clear(tracked); layer.Visible = false
    end
    local function fit(drawing, slot, text, size, viewport)
        local label = drawing.labels[slot]
        if not label then return end
        local key = text .. ":" .. tostring(size) .. ":" .. tostring(viewport.X)
        drawing.textMetrics = drawing.textMetrics or {}
        if not drawing.textMetrics[slot] or drawing.textMetrics[slot].key ~= key then
            local width = #text * size * 0.65 + 8
            pcall(function() width = textService:GetTextSize(text, size, Enum.Font.Arial, Vector2.new(10000,100)).X + 8 end)
            width = math.max(1, math.min(width, viewport.X - 24))
            drawing.textMetrics[slot] = {key = key, width = width}
        end
        label.AutomaticSize = Enum.AutomaticSize.None
        label.Size = UDim2.fromOffset(drawing.textMetrics[slot].width, size + 7)
        label.TextTruncate = Enum.TextTruncate.AtEnd
        -- Clamped to screen independently of target position, not a clipped name.
        local half = label.Size.X.Offset * 0.5
        label.Position = UDim2.fromOffset(math.clamp(label.Position.X.Offset, half + 8, math.max(half + 8, viewport.X - half - 8)), label.Position.Y.Offset)
    end
    card = context.framework.Categories.Visuals:CreateModule({Name = "Nametags", Category = "Render",
        ConfigKey = "Universal.Nametags", Order = 3,
        Tooltip = "Readable player nameplates, account names, distance and game roles. Independent of ESP and Chams.",
        Function = function(enabled)
            if not enabled then clear(); card:SetStatus(nil); return end
            layer.Visible = true
            card:Clean(clear)
            card:Render(function()
                local camera = (host.workspace or workspace).CurrentCamera
                if not camera then clear(); return end
                layer.Visible = true
                local seen, count = {}, 0
                local options = card.Options
                for _, target in ipairs(entity:Refresh()) do
                    local player = target.Player
                    if not player or target.Health <= 0 or target.Distance > options["Max distance"].Value
                        or not (roleBinding.provider and roleBinding.provider.ReplacesTeams) and not options.Teammates.Value and target.IsFriendly then continue end
                    local head = target.Head or target.RootPart
                    local point = head and render:Project(camera, head.Position + Vector3.new(0, head.Size.Y * 0.5 + 0.7, 0))
                    if not point or point.X < 0 or point.Y < 0 or point.X > camera.ViewportSize.X or point.Y > camera.ViewportSize.Y
                        or not options["Through walls"].Value and not entity:VisibleFrom(target) then continue end
                    local colour, role = roleBinding:Resolve(player, options.Colour.Value)
                    local shown = options["Display name"].Value and player.DisplayName or player.Name
                    local details = {}
                    if options["Account name"].Value and shown ~= player.Name then table.insert(details, "@" .. player.Name) end
                    if options["Show role"].Value and role then table.insert(details, role) end

                    if options["Held tool"].Value then
                        local tool = target.Character:FindFirstChildOfClass("Tool")
                        if tool then table.insert(details, tool.Name) end
                    end
                    seen[player] = true; tracked[player] = true; count += 1
                    local drawing = render:Set(layer, player)
                    drawing:Show(true)
                    local size = math.round(options["Text size"].Value)
                    if #details > 0 then shown ..= " [" .. table.concat(details, "] [") .. "]" end
                    if options.Distance.Value then shown = "[" .. tostring(math.round(target.Distance)) .. "] " .. shown end
                    local y = math.max(point.Y, size + 16)
                    drawing:Label("Name", shown, Vector2.new(point.X, y), 1, size, colour, options.Background.Value)
                    local label = drawing.labels.Name
                    if label then
                        if not drawing.flatNametag then
                            for _, child in ipairs(label:GetChildren()) do
                                if child:IsA("UICorner") or child:IsA("UIStroke") then child:Destroy()
                                elseif child:IsA("UIPadding") then
                                    child.PaddingLeft, child.PaddingRight = UDim.new(0,4), UDim.new(0,4)
                                end
                            end
                            drawing.flatNametag = true
                        end
                        label.Font = Enum.Font.Arial
                        label.BackgroundColor3 = Color3.new(0,0,0)
                        label.BackgroundTransparency = options.Background.Value and 0.5 or 1
                        label.TextStrokeTransparency = 1
                    end
                    fit(drawing, "Name", shown, size, camera.ViewportSize)
                    drawing:HideLabel("Details")
                end
                for player in pairs(tracked) do
                    if not seen[player] then render:Release(layer,player); tracked[player] = nil end
                end
                card:SetStatus(tostring(count))
            end)
        end})
    card:CreateToggle({Name = "Display name", Default = true})
    card:CreateToggle({Name = "Account name", Default = false, Show = {Option = "Display name"}})
    card:CreateToggle({Name = "Distance", Default = false})
    card:CreateToggle({Name = "Show role", Default = false})
    card:CreateToggle({Name = "Held tool", Default = false})
    card:CreateToggle({Name = "Background", Default = true})
    card:CreateSlider({Name = "Text size", Min = 10, Max = 24, Default = 14})
    card:CreateColor({Name = "Colour", Default = Color3.fromRGB(85, 255, 85)})
    card:CreateSlider({Name = "Max distance", Min = 50, Max = 5000, Default = 1000})
    card:CreateToggle({Name = "Through walls", Default = true})
    card:CreateToggle({Name = "Teammates", Default = true})
    roleBinding = context.services.gameRoles:Bind(card)
    card.OptionFilter = function(name)
        if name == "Show role" then return roleBinding.provider ~= nil end
        return not (name == "Teammates" and roleBinding.provider and roleBinding.provider.ReplacesTeams)
    end
    card:RefreshVisibility()
    activeCard, cleanup = card, clear
    Module.Initialized = true
    return card
end
function Module.destroy()
    if activeCard and activeCard.Enabled then activeCard:Toggle(false) end
    if cleanup then cleanup() end
    if roleBinding then roleBinding:Destroy() end
    activeCard, cleanup, roleBinding = nil, nil, nil
    Module.Initialized = false
end
return Module

]],
        ["src/games/universal/Render/PlayerESP.lua"] = [[
export type Runtime = {
    framework: any,
    entity: any,
    host: any,
    services: any,
}

local Module = {
    Name = "PlayerESP",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local activeCleanup: (() -> ())? = nil
local activeCard: any = nil

function Module.init(context: Runtime): any
    local host: any = context.host
    local framework: any = context.framework
    local players: Players = host.Players

    local render: any = context.render

    local container: Frame = render:Layer("PlayerEspLayer")
    local pool: {[Player]: boolean} = {}
    local lastStatusAt: number = -math.huge
    local visibilityCache: any = setmetatable({}, {__mode = "k"})

    local esp: any
    esp = framework.Categories.Visuals:CreateModule({
        Name = "PlayerESP",
        Category = "Render",
        ConfigKey = "Universal.PlayerESP",
        Order = 1,
        Tooltip = "Outlined boxes, skeletons and tracers. Nametags and HP are independent modules.",
        Function = function(enabled: boolean): ()
            container.Visible = enabled
            if not enabled then
                esp:SetStatus(nil)
                render:ReleaseAll(container)
                table.clear(pool)
                return
            end
            lastStatusAt = -math.huge
            esp:SetStatus("0")
            esp:Render(function(): ()
                Module.render(context, container, pool, esp, visibilityCache)
                local now: number = os.clock()
                if now - lastStatusAt >= 0.25 then
                    lastStatusAt = now
                    local count: number = 0
                    for _player: Player in pairs(pool) do
                        count += 1
                    end
                    esp:SetStatus(tostring(count))
                end
            end)
            esp:Event(players.PlayerRemoving, function(player: Player): ()
                render:Release(container, player)
                pool[player] = nil
            end)
            esp:Clean(function(): ()
                render:ReleaseAll(container)
                table.clear(pool)
                container.Visible = false
            end)
        end,
    })

    esp:CreateDropdown({
        Name = "Boxes",
        List = {"Corner", "Full", "Off"},
        Index = 1,
        Tooltip = "Corner draws four brackets, Full draws the whole rectangle.",
    })
    esp:CreateSlider({
        Name = "Box thickness",
        Show = {Option = "Boxes", Values = {"Corner", "Full"}},
        Min = 1,
        Max = 5,
        Default = 1,
    })
    esp:CreateToggle({
        Name = "Filled box",
        Show = {Option = "Boxes", Values = {"Corner", "Full"}},
        Default = false,
        Tooltip = "Wash the inside of the box in the target's colour. Reads "
            .. "at a glance across a map; noisy in a crowd.",
    })
    esp:CreateToggle({
        Name = "Skeleton",
        Default = false,
        Tooltip = "Draw the rig's bones. Works on both R6 and R15.",
    })
    esp:CreateDropdown({
        Name = "Tracers",
        List = {"Off", "Bottom", "Centre", "Cursor"},
        Index = 1,
        Tooltip = "Where the line to each target starts.",
    })
    esp:CreateToggle({
        Name = "Team check",
        Default = false,
        Tooltip = "Skip players on your own team.",
    })
    esp:CreateToggle({
        Name = "Visibility check",
        Default = false,
        Tooltip = "Recolour targets that are behind geometry.",
    })
    esp:CreateSlider({
        Name = "Max distance",
        Min = 50,
        Max = 5000,
        Default = 2000,
    })

    esp:CreateColor({
        Name = "Colour",
        Default = Color3.fromRGB(85, 255, 85),
        Tooltip = "Used for every target the game gives no colour of its own.",
    })
    esp:CreateToggle({
        Name = "Team colours",
        Default = true,
        Tooltip = "Draw each player in their own team's colour where the game "
            .. "has teams.",
    })
    local roles = context.services.gameRoles:Bind(esp)
    Module.roles = roles
    esp.OptionFilter = function(name)
        return not (roles.provider and roles.provider.ReplacesTeams and (name == "Team check" or name == "Team colours"))
    end
    esp:RefreshVisibility()
    local function addExtraRows(extra: any): ()
        if type(extra) ~= "table" or type(extra.Name) ~= "string" or esp.Options[extra.Name] then return end
        esp:CreateToggle({
            Name = extra.Name,
            Default = extra.Default == true,
            Tooltip = extra.Tooltip,
            Function = function(value: boolean): ()
                if type(extra.Toggle) == "function" then
                    pcall(extra.Toggle, value)
                end
            end,
        })
        if extra.Color then
            esp:CreateColor({
                Name = extra.Name .. " colour",
                Show = {Option = extra.Name},
                Default = extra.Color,
                Function = function(value: Color3): ()
                    if type(extra.SetColor) == "function" then
                        pcall(extra.SetColor, value)
                    end
                end,
            })
        end

        for _, definition: any in ipairs(extra.Options or {}) do
            local rowName: string = extra.Name .. " " .. definition.Name
            if definition.Kind == "toggle" then
                esp:CreateToggle({
                    Name = rowName,
                    Show = {Option = extra.Name},
                    Default = definition.Default == true,
                    Tooltip = definition.Tooltip,
                    Function = function(value: boolean): ()
                        if type(definition.Set) == "function" then
                            pcall(definition.Set, value)
                        end
                    end,
                })
            else
                esp:CreateSlider({
                    Name = rowName,
                    Show = {Option = extra.Name},
                    Min = definition.Min or 0,
                    Max = definition.Max or 100,
                    Default = definition.Default or definition.Min or 0,
                    Tooltip = definition.Tooltip,
                    Function = function(value: number): ()
                        if type(definition.Set) == "function" then
                            pcall(definition.Set, value)
                        end
                    end,
                })
            end
        end
    end

    local gameBridge: any = context.services.gameBridge
    if type(gameBridge.onEvent) == "function" then
        Module.bridgeCleanup = gameBridge.onEvent(function(kind: string, payload: any): ()
            if kind == "extra" then
                addExtraRows(payload)
            end
        end)
    end

    activeCleanup = function(): ()
        render:ReleaseAll(container)
        table.clear(pool)
        container.Visible = false
    end
    activeCard = esp
    Module.Initialized = true
    return esp
end

function Module.render(
    context: Runtime,
    container: Frame,
    pool: {[Player]: any},
    esp: any,
    visibilityCache: any
): ()
    local host: any = context.host
    local entityLibrary: any = context.entity
    local render: any = context.render
    local gameBridge: any = context.services.gameBridge
    local currentWorkspace: Workspace = host.workspace or workspace
    local camera: Camera? = currentWorkspace.CurrentCamera
    if not camera then
        container.Visible = false
        return
    end
    container.Visible = true
    local resolvedCamera: Camera = camera :: Camera
    local options: any = esp.Options
    local viewport: Vector2 = resolvedCamera.ViewportSize

    entityLibrary:Refresh()
    local seen: {[Player]: boolean} = {}

    for _, entity: any in ipairs(entityLibrary.List) do
        local player: Player = entity.Player
        if not (Module.roles and Module.roles.provider and Module.roles.provider.ReplacesTeams)
            and options["Team check"].Value and entity.IsFriendly then
            continue
        end
        if entity.Distance > options["Max distance"].Value then

            continue
        end

        local rect: any = render:ModelRect(resolvedCamera, entity.Character)

        seen[player] = true
        pool[player] = true
        local drawings: any = render:Set(container, player)

        if not rect then

            drawings:Show(false)
            continue
        end

        local visible: boolean = true
        if options["Visibility check"].Value then
            local cache: any = visibilityCache[player]
            local now: number = os.clock()
            if not cache or now - cache.at > 0.12 then
                cache = {at = now, value = entityLibrary:VisibleFrom(entity)}
                visibilityCache[player] = cache
            end
            visible = cache.value
        end
        local colour = options["Colour"].Value
        local roles = Module.roles
        local roleColour = roles and roles:Resolve(player, nil)
        if roleColour then
            colour = roleColour
        elseif not (roles and roles.provider and roles.provider.ReplacesTeams)
            and options["Team colours"].Value and player.Team then
            colour = player.Team.TeamColor.Color
        end

        if not visible then
            colour = colour:Lerp(Color3.new(0, 0, 0), 0.45)
        end

        local left: number = rect.left
        local top: number = rect.top
        local bottom: number = rect.bottom
        local height: number = rect.height
        local centreX: number = rect.centreX

        drawings:Show(true)

        local thickness: number = math.round(options["Box thickness"].Value)
        local boxMode: string = options["Boxes"].Value
        drawings:Fill(
            options["Filled box"].Value and boxMode ~= "Off" and rect or nil,
            colour,
            0.82
        )
        drawings:Box(rect, boxMode, thickness, colour)

        if options["Skeleton"].Value then
            local bones: {{BasePart}} = entityLibrary:Rig(entity)
            for index: number = 1, 14 do
                local pair: {BasePart}? = bones[index]
                local first: Vector2? = pair
                    and render:Project(resolvedCamera, pair[1].Position)
                local second: Vector2? = pair
                    and render:Project(resolvedCamera, pair[2].Position)
                if first and second then
                    drawings:Line(
                        "Bone",
                        index,
                        first :: Vector2,
                        second :: Vector2,
                        1,
                        colour
                    )
                else
                    drawings:HideLines("Bone", index, index)
                end
            end
        else
            drawings:HideLines("Bone", 1, 14)
        end

        local tracerMode: string = options["Tracers"].Value
        if tracerMode == "Off" then
            drawings:HideLines("Tracer", 1, 1)
        else
            local origin: Vector2
            if tracerMode == "Bottom" then
                origin = Vector2.new(viewport.X * 0.5, viewport.Y)
            elseif tracerMode == "Centre" then
                origin = viewport * 0.5
            else
                origin = host.UserInputService:GetMouseLocation()
            end
            drawings:Line(
                "Tracer",
                1,
                origin,
                Vector2.new(centreX, bottom),
                1,
                colour
            )
        end

    end

    for player: Player in pairs(pool) do
        if not seen[player] then
            render:Release(container, player)
            pool[player] = nil
        end
    end
end

function Module.destroy(): ()
    if activeCard and activeCard.Enabled then activeCard:Toggle(false) end
    if activeCleanup then
        pcall(activeCleanup)
    end
    if Module.roles then Module.roles:Destroy(); Module.roles = nil end
    if Module.bridgeCleanup then Module.bridgeCleanup(); Module.bridgeCleanup = nil end
    activeCleanup = nil
    activeCard = nil
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Render/Spectate.lua"] = [[
-- Native player spectating; FreeCam pauses without losing its position.
local Module = {Name="Spectate", Initialized=false}
local card, services, stop

function Module.init(context)
    local host = context.host
    services = context.services
    local world = host.workspace or workspace
    local chosen, camera, saved, writtenSubject
    local enabled=false
    local config=host.configData
    if config then
        if config.states["Universal.FreeCam.Spectate"]==nil then config.states["Universal.FreeCam.Spectate"]=config.states["Universal.Spectate"] end
        if config.values["Universal.FreeCam.SpectatePlayer"]==nil then config.values["Universal.FreeCam.SpectatePlayer"]=config.values["Universal.Spectate.Player"] end
    end
    card=assert(context.framework:GetModule("FreeCam"),"Spectate requires FreeCam options")
    local playerList
    local id = "ARandomMenu.Spectate." .. tostring({})
    local function localHumanoid()
        local character = host.LocalPlayer.Character
        return character and character:FindFirstChildOfClass("Humanoid")
    end
    local function freeCamSession()
        local free = services.freeCam
        return free and free.IsActive() and free.Session or nil
    end
    local function restore()
        if camera and saved then
            pcall(function()
                -- Do not take the camera back from a later owner.
                if camera.CameraType ~= Enum.CameraType.Custom or camera.CameraSubject ~= writtenSubject then return end
                local returnedToFreeCam = saved.freeCam and saved.freeCam == freeCamSession()
                if saved.freeCam and not returnedToFreeCam then
                    camera.CameraType = Enum.CameraType.Custom
                    camera.CameraSubject = localHumanoid()
                else
                    camera.CameraType = saved.kind
                    local subject=saved.subject
                    if subject==saved.localHumanoid or typeof(subject)=="Instance" and subject.Parent==nil then subject=localHumanoid() end
                    camera.CameraSubject=subject
                    camera.CFrame, camera.Focus = saved.frame, saved.focus
                end
            end)
        end
        camera, saved, writtenSubject = nil, nil, nil
    end
    local function targetHumanoid()
        for _, player in ipairs(host.Players:GetPlayers()) do
            if player ~= host.LocalPlayer and player.Name == chosen then
                local character = player.Character
                local humanoid = character and character:FindFirstChildOfClass("Humanoid")
                return humanoid and humanoid.Health > 0 and humanoid or nil, true
            end
        end
        return nil, false
    end
    local function step()
        local humanoid, present = targetHumanoid()
        if chosen and not present then
            local departed = chosen
            chosen = nil
            if playerList then playerList:Set(departed,false);playerList:Refresh() end
        end
        if not humanoid then
            restore()
            card:SetStatus(chosen and "Waiting for respawn" or "Choose a player")
            return
        end
        local nextCamera = world.CurrentCamera
        if camera ~= nextCamera then restore() end
        if not nextCamera then return end
        if not camera then
            camera = nextCamera
            saved = {kind=camera.CameraType,subject=camera.CameraSubject,frame=camera.CFrame,focus=camera.Focus,
                freeCam=freeCamSession(),localHumanoid=localHumanoid()}
        elseif camera.CameraType ~= Enum.CameraType.Custom or camera.CameraSubject ~= writtenSubject then
            -- Adopt a newer camera baseline rather than restoring over it later.
            saved = {kind=camera.CameraType,subject=camera.CameraSubject,frame=camera.CFrame,focus=camera.Focus,
                freeCam=false,localHumanoid=localHumanoid()}
        end
        camera.CameraType = Enum.CameraType.Custom
        camera.CameraSubject = humanoid
        writtenSubject = humanoid
        card:SetStatus(chosen)
    end
    local state = {IsActive=function()
        if not enabled or not chosen then return false end
        local humanoid = targetHumanoid()
        return humanoid ~= nil
    end}
    services.spectate = state
    stop=function()
        enabled=false
        host.RunService:UnbindFromRenderStep(id)
        restore()
    end
    card:CreateToggle({Name="Spectate",Default=false,
        Tooltip="Follow a player independently: FreeCam may stay OFF. Turn this off or deselect to return.",
        Function=function(value)
            stop();enabled=value
            if enabled then
                host.RunService:BindToRenderStep(id,Enum.RenderPriority.Camera.Value-1,step)
                step()
            end
        end})
    playerList = card:CreateList({Name="Spectate Player",Single=true,Show={Option="Spectate"},Items=function()
        local names={}
        for _,player in ipairs(host.Players:GetPlayers()) do
            if player ~= host.LocalPlayer then table.insert(names,player.Name) end
        end
        table.sort(names);return names
    end,EmptyText="No other players",Tooltip="Select one player; click the selected player again to stop spectating.",Function=function(_,names)
        local nextName = names[1]
        if chosen ~= nextName then restore();chosen=nextName end
        if enabled then step() end
    end})
    Module.Initialized=true
    return Module
end

function Module.destroy()
    if stop then stop() end
    if services then services.spectate=nil end
    card,services,stop=nil,nil,nil
    Module.Initialized=false
end
return Module

]],
