-- Vape Xray's kept-part list, with bounded updates and owned-only restoration.
local Module = {Name="XRay",PlaceId=0,Initialized=false}
local card
function Module.init(context)
    local host, world = context.host, context.host.workspace or workspace
    local records = setmetatable({}, {__mode="k"})
    local indexed = setmetatable({}, {__mode="k"})
    local candidates, cursor, pause = {}, 1, 0
    local named, kept = {}, {}
    local function names(text)
        local result={}
        for name in string.gmatch(string.lower(text or ""),"[^,]+") do
            name=string.match(name,"^%s*(.-)%s*$")
            if name~="" then result[name]=true end
        end
        return result
    end
    local function restore(part)
        local record=records[part]
        if not record then return end
        pcall(function()
            if part.LocalTransparencyModifier==record.applied then part.LocalTransparencyModifier=record.base end
        end)
        records[part]=nil
    end
    local function restoreAll()
        for part in pairs(records) do restore(part) end
    end
    local function changed()
        restoreAll();cursor=1;pause=0
        if card and card.Options["Part names"] and card.Options["Keep visible"] then
            named=names(card.Options["Part names"].Value)
            kept=names(card.Options["Keep visible"].Value)
        end
    end
    local function add(part)
        if part:IsA("BasePart") and not indexed[part] then
            indexed[part]=true;table.insert(candidates,part)
        end
    end
    local function eligible(part,origin,root)
        local opts=card.Options
        if part.Transparency>=0.98 or kept[string.lower(part.Name)] then return false end
        if not opts["Include unanchored"].Value and not part.Anchored then return false end
        if opts["Collidable only"].Value and not part.CanCollide then return false end
        if opts["Limit range"].Value and origin and (part.Position-origin).Magnitude>opts.Range.Value+part.Size.Magnitude*0.5 then return false end
        if part.Name=="Wurst_AntiVoidPlatform" or host.isMenuOwned and host.isMenuOwned(part) then return false end
        local ancestor=part.Parent
        while ancestor and ancestor~=world do
            if ancestor:IsA("Tool") or ancestor:IsA("Model") and ancestor:FindFirstChildOfClass("Humanoid") then return false end
            ancestor=ancestor.Parent
        end
        local thinFloor=part.Size.Y<=math.min(part.Size.X,part.Size.Z)*0.35
        if opts["Keep floors"].Value and thinFloor and root and part.Position.Y<=root.Position.Y then return false end
        local mode=opts.Scope.Value
        if mode=="Named parts" then return named[string.lower(part.Name)]==true end
        if mode=="Walls" then return not thinFloor and part.Size.Y>math.min(part.Size.X,part.Size.Z)*1.5 end
        return true
    end
    local function step(dt)
        pause=math.max(0,pause-(dt or 0))
        if pause>0 or #candidates==0 then return end
        local camera=world.CurrentCamera
        local character=host.LocalPlayer.Character
        local root=character and character:FindFirstChild("HumanoidRootPart")
        local origin=camera and camera.CFrame.Position or root and root.Position
        for _=1,200 do
            local part=candidates[cursor]
            if not part then cursor=1;pause=0.2;break end
            if not part.Parent or not part:IsDescendantOf(world) then
                restore(part);indexed[part]=nil
                candidates[cursor]=candidates[#candidates];candidates[#candidates]=nil
            else
                if eligible(part,origin,root) then
                    local current=part.LocalTransparencyModifier
                    local record=records[part]
                    if not record then record={base=current};records[part]=record
                    elseif current~=record.applied then record.base=current end
                    record.applied=math.max(record.base,card.Options.Transparency.Value)
                    part.LocalTransparencyModifier=record.applied
                else restore(part) end
                cursor+=1
            end
        end
    end
    card=context.framework.Categories.Render:CreateModule({Name="X-Ray",Category="Render",ConfigKey="Universal.XRay",
        Tooltip="Fade map parts locally. Keep named objects visible; never fade characters or held tools.",Function=function(enabled)
            restoreAll();table.clear(candidates);table.clear(indexed);cursor=1;pause=0
            if not enabled then card:SetStatus(nil);return end
            changed()
            for _,part in ipairs(world:GetDescendants()) do add(part) end
            card:Clean(restoreAll)
            card:Clean(world.DescendantAdded:Connect(add))
            card:Loop(step);step(0)
        end})
    card:CreateDropdown({Name="Scope",List={"All map","Walls","Named parts"},Index=1,Function=changed})
    card:CreateSlider({Name="Transparency",Min=0,Max=1,Default=0.5,Step=0.05,Decimal=2,Function=changed})
    card:CreateTextBox({Name="Part names",Default="",Placeholder="Wall, Window",Show={Option="Scope",Values={"Named parts"}},Function=changed,
        Tooltip="Exact part names, separated by commas. Only these names fade in Named parts scope."})
    card:CreateTextBox({Name="Keep visible",Default="",Placeholder="Spawn, Objective",Function=changed,
        Tooltip="Vape-style kept-part list. Exact names separated by commas; these parts never fade."})
    card:CreateToggle({Name="Keep floors",Default=true,Function=changed})
    card:CreateToggle({Name="Collidable only",Default=true,Function=changed})
    card:CreateToggle({Name="Include unanchored",Default=false,Function=changed})
    card:CreateToggle({Name="Limit range",Default=true,Function=changed})
    card:CreateSlider({Name="Range",Min=25,Max=5000,Default=250,Show={Option="Limit range",Values={true}},Function=changed})
    Module.Initialized=true
    return card
end
function Module.destroy()
    if card and card.Enabled then card:Toggle(false) end
    card=nil;Module.Initialized=false
end
return Module

]],
        ["src/games/universal/Render/ZoomUnlocker.lua"] = [[
local Module = {Name = "ZoomUnlocker", Initialized = false}
local cleanup

function Module.init(context)
    local host, player = context.host, context.host.LocalPlayer
    local access = context.services.cameraAccess
    local settings = {minimum=0.5, maximum=400, firstPerson=true, walls=false}
    local original, feature
    local function bounds(minimum,maximum)
        if player.CameraMinZoomDistance > maximum then player.CameraMinZoomDistance = minimum end
        player.CameraMaxZoomDistance = maximum
        player.CameraMinZoomDistance = minimum
    end
    local function apply()
        bounds(math.min(settings.minimum,settings.maximum),math.max(settings.minimum,settings.maximum))
        player.CameraMode = settings.firstPerson and Enum.CameraMode.Classic or original.mode
        local walls = access:ThroughWalls(settings.walls)
        feature:SetStatus(settings.walls and (walls and tostring(math.round(settings.maximum)) .. " / walls" or "walls unavailable")
            or tostring(math.round(settings.maximum)) .. " studs")
    end
    cleanup = function()
        host.disconnectFeatureConnection("ZoomUnlocker")
        access:ThroughWalls(false)
        if original then
            bounds(original.minimum,original.maximum)
            player.CameraMode = original.mode
            original = nil
        end
    end
    feature = host.createUniversalFeature("Zoom", "Extend zoom; optionally let the camera pass through walls.", 23, function(enabled)
        cleanup()
        if not enabled then feature:SetStatus(nil); return end
        original = {minimum=player.CameraMinZoomDistance, maximum=player.CameraMaxZoomDistance, mode=player.CameraMode}
        apply()
        host.featureConnections.ZoomUnlocker = host.TaskManager:Connect(apply)
    end, {configKey="Universal.ZoomUnlocker", categoryName="Render"})
    local function update(key,value)
        settings[key] = value
        if feature.enabled then apply() end
    end
    host.addNumberOption(feature,"Maximum distance",settings.maximum,25,2000,function(value) update("maximum",value) end)
    host.addNumberOption(feature,"Minimum distance",settings.minimum,0.5,50,function(value) update("minimum",value) end)
    host.addToggleOption(feature,"Unlock forced first person",settings.firstPerson,function(value) update("firstPerson",value) end)
    host.addToggleOption(feature,"Through walls",settings.walls,function(value) update("walls",value) end)
    Module.Initialized = true
    return feature
end
function Module.destroy()
    if cleanup then pcall(cleanup); cleanup = nil end
    Module.Initialized = false
end
return Module

]],
        ["src/gui/Current/gui.lua"] = [=[
--!strict

--[[
    Complete standalone presentation kernel for A Random Menu.
    Game modules only need to call createModule() and add their controls.
]]

local executorEnvironment: any = getfenv()
local cloneReference: (Instance) -> Instance = (
    executorEnvironment.cloneref
    or function(instance: Instance): Instance
        return instance
    end
) :: (Instance) -> Instance

local Players: Players = cloneReference(game:GetService("Players")) :: Players
local UserInputService: UserInputService =
    cloneReference(game:GetService("UserInputService")) :: UserInputService
local TweenService: TweenService =
    cloneReference(game:GetService("TweenService")) :: TweenService
local Lighting: Lighting = cloneReference(game:GetService("Lighting")) :: Lighting
local HttpService: HttpService =
    cloneReference(game:GetService("HttpService")) :: HttpService

local RAW_BASE: string =
    "https://raw.githubusercontent.com/XzAngel19/ARandomMenu/refs/heads/main/"
local CACHE_ROOT: string = "ARandomMenu/Assets"
local RUNTIME_COMPATIBILITY_MARKER: string =
    "Initialization error — check executor console"
local RUNTIME_SAFETY_SOURCE_URL: string =
    "https://raw.githubusercontent.com/XzAngel19/ARandomMenu/4b10e4bfe00aa356afb3e0420a72e745327f6259/ARandomMenu.luau"

export type Theme = {
    Background: Color3,
    Surface: Color3,
    SurfaceHover: Color3,
    SurfaceActive: Color3,
    Accent: Color3,
    Text: Color3,
    MutedText: Color3,
    Outline: Color3,
}

export type AssetSource = {
    url: string,
    fileName: string,
    fallback: string,
}

export type GuiOptions = {
    name: string?,
    title: string?,
    initiallyVisible: boolean?,
    parent: Instance?,
    reinjectUrl: string?,
}

export type FeatureController = {
    row: Frame,
    options: Frame,
    enabled: boolean,
    expanded: boolean,
    addSlider: (
        self: FeatureController,
        label: string,
        minimum: number,
        maximum: number,
        initial: number,
        callback: (number) -> ()
    ) -> (),
    addKeybind: (
        self: FeatureController,
        label: string,
        initial: Enum.KeyCode,
        callback: (Enum.KeyCode) -> ()
    ) -> TextButton,
    setEnabled: (self: FeatureController, enabled: boolean) -> (),
    setExpanded: (self: FeatureController, expanded: boolean) -> (),
}

export type ModuleController = {
    id: string,
    page: ScrollingFrame,
    addToggle: (
        self: ModuleController,
        id: string,
        label: string,
        description: string,
        callback: (boolean) -> ()
    ) -> FeatureController,
    addAction: (
        self: ModuleController,
        id: string,
        label: string,
        description: string,
        callback: () -> ()
    ) -> FeatureController,
}

export type GuiController = {
    screenGui: ScreenGui,
    window: Frame,
    content: Frame,
    modules: {[string]: ModuleController},
    pages: {[string]: ScrollingFrame},
    tabButtons: {[string]: TextButton},
    connections: {RBXScriptConnection},
    featureConnections: {RBXScriptConnection},
    activeTab: string?,
    visible: boolean,
    textScale: number,
    blurEnabled: boolean,
    createModule: (
        self: GuiController,
        id: string,
        label: string,
        layoutOrder: number
    ) -> ModuleController,
    setTab: (self: GuiController, id: string) -> (),
    setTabIcon: (self: GuiController, id: string, assetKey: string) -> (),
    setTextScale: (self: GuiController, scale: number) -> (),
    setVisible: (self: GuiController, visible: boolean) -> (),
    destroy: (self: GuiController) -> (),
}

local THEME: Theme = table.freeze({
    Background = Color3.fromRGB(0, 0, 0),
    Surface = Color3.fromRGB(15, 15, 17),
    SurfaceHover = Color3.fromRGB(29, 29, 33),
    SurfaceActive = Color3.fromRGB(37, 37, 42),
    Accent = Color3.fromRGB(236, 236, 240),
    Text = Color3.fromRGB(246, 246, 248),
    MutedText = Color3.fromRGB(156, 156, 164),
    Outline = Color3.fromRGB(82, 82, 90),
})

-- Every image used by this GUI is visible here. Custom art is downloaded from
-- GitHub and converted with getcustomasset/getsynasset. The Roblox asset IDs
-- are explicit fallbacks for executors without a file asset API.
local ASSETS: {[string]: AssetSource} = table.freeze({
    Header = {
        url = RAW_BASE .. "src/gui/Current/Assets/Header/anime-header.jpg",
        fileName = "anime-header-v1.jpg",
        fallback = "rbxassetid://6031091002",
    },
    CosmicControls = {
        url = RAW_BASE
            .. "src/gui/Current/Assets/Source/cosmic-controls-sheet.png",
        fileName = "cosmic-controls-sheet-v1.png",
        fallback = "rbxassetid://6031094678",
    },
    KeybindPill = {
        url = RAW_BASE .. "src/gui/Current/Assets/Frames/keybind-pill-hd.png",
        fileName = "keybind-pill-hd-v1.png",
        fallback = "",
    },
    MobileToggle = {
        url = RAW_BASE .. "src/gui/Current/Images/menu-toggle.png",
        fileName = "menu-toggle-v3.png",
        fallback = "rbxassetid://6031094678",
    },
    InkScratch = {
        url = RAW_BASE .. "src/gui/Current/Assets/Decorations/ink-scratch.png",
        fileName = "ink-scratch-v1.png",
        fallback = "rbxassetid://6031280882",
    },
    Spinner = {
        url = RAW_BASE .. "src/gui/Current/Assets/Status/spinner_minimal.png",
        fileName = "spinner-minimal-v1.png",
        fallback = "rbxassetid://6031094678",
    },
    IconHome = {
        url = RAW_BASE .. "src/gui/Current/Assets/Icons/home.png",
        fileName = "icon-home-v1.png",
        fallback = "rbxassetid://6026568198",
    },
    IconSearch = {
        url = RAW_BASE .. "src/gui/Current/Assets/Icons/search.png",
        fileName = "icon-search-v1.png",
        fallback = "rbxassetid://6031154871",
    },
    IconSettings = {
        url = RAW_BASE .. "src/gui/Current/Assets/Icons/settings.png",
        fileName = "icon-settings-v1.png",
        fallback = "rbxassetid://6031280882",
    },
    IconTarget = {
        url = RAW_BASE .. "src/gui/Current/Assets/Icons/target_cross.png",
        fileName = "icon-target-v1.png",
        fallback = "rbxassetid://6034287594",
    },
})

local DEFAULT_TAB_ICONS: {[string]: string} = table.freeze({
    Universal = "IconHome",
    Movement = "IconTarget",
    Search = "IconSearch",
    Settings = "IconSettings",
})

local function create<T>(className: string, properties: {[string]: any}): T
    local instance: Instance = Instance.new(className)
    for property: string, value: any in pairs(properties) do
        if property ~= "Parent" then
            (instance :: any)[property] = value
        end
    end
    local parent: Instance? = properties.Parent
    if parent then
        instance.Parent = parent
    end
    return (instance :: any) :: T
end

local function tween(target: Instance, properties: {[string]: any}): ()
    TweenService:Create(
        target,
        TweenInfo.new(0.16, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
        properties
    ):Play()
end

local function round(object: GuiObject, radius: number): UICorner
    return create("UICorner", {
        CornerRadius = UDim.new(0, radius),
        Parent = object,
    })
end

local function stroke(
    object: GuiObject,
    transparency: number,
    thickness: number?
): UIStroke
    return create("UIStroke", {
        ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
        Color = THEME.Outline,
        Thickness = thickness or 1,
        Transparency = transparency,
        Parent = object,
    })
end

local function ensureCacheFolder(): ()
    local isFolder: any = executorEnvironment.isfolder
    local makeFolder: any = executorEnvironment.makefolder
    if type(isFolder) ~= "function" or type(makeFolder) ~= "function" then
        return
    end
    if not isFolder("ARandomMenu") then
        makeFolder("ARandomMenu")
    end
    if not isFolder(CACHE_ROOT) then
        makeFolder(CACHE_ROOT)
    end
end

local function getAssetResolver(): ((string) -> string)?
    local resolver: any = executorEnvironment.getcustomasset
        or executorEnvironment.getsynasset
    return type(resolver) == "function" and resolver or nil
end

local function isSupportedImageBody(body: any): boolean
    if type(body) ~= "string" or #body < 256 then
        return false
    end
    local header: string = body:sub(1, 8)
    local isPng: boolean = header == "\137PNG\r\n\26\n"
    local isJpg: boolean = header:sub(1, 3) == "\255\216\255"
    return isPng or isJpg
end

local function resolveAsset(source: AssetSource): string
    local resolver: ((string) -> string)? = getAssetResolver()
    local writeFile: any = executorEnvironment.writefile
    local isFile: any = executorEnvironment.isfile
    local readFile: any = executorEnvironment.readfile
    if resolver == nil or type(writeFile) ~= "function" then
        return source.fallback
    end
    ensureCacheFolder()
    local path: string = CACHE_ROOT .. "/" .. source.fileName
    local cached: boolean = false
    local checked: boolean = false
    local exists: any = false
    if type(isFile) == "function" then
        checked, exists = pcall(isFile, path)
    end
    if checked and exists == true then
        if type(readFile) == "function" then
            local readOk: boolean, cachedBody: any = pcall(readFile, path)
            cached = readOk and isSupportedImageBody(cachedBody)
        else
            cached = true
        end
    end
    if not cached then
        local downloaded: boolean, body: any = pcall(function(): string
            return (game :: any):HttpGet(source.url, true)
        end)
        if not downloaded or not isSupportedImageBody(body) then
            return source.fallback
        end
        if not pcall(writeFile, path, body) then
            return source.fallback
        end
    end
    local resolved: boolean, asset: any = pcall(resolver, path)
    return resolved and type(asset) == "string" and asset or source.fallback
end

local function loadImage(
    target: ImageLabel | ImageButton,
    key: string,
    onResolved: ((boolean) -> ())?
): ()
    local source: AssetSource? = ASSETS[key]
    if source == nil then
        return
    end
    if source.fallback ~= "" then
        target.Image = source.fallback
    end
    task.spawn(function(): ()
        local asset: string = resolveAsset(source :: AssetSource)
        if asset ~= "" and target.Parent ~= nil then
            target.Image = asset
            if onResolved then
                onResolved(true)
            end
        elseif onResolved then
            onResolved(false)
        end
    end)
end

local function getGuiParent(playerGui: PlayerGui): Instance
    local getHiddenUi: any = executorEnvironment.gethui
    if type(getHiddenUi) == "function" then
        local succeeded: boolean, hiddenUi: any = pcall(getHiddenUi)
        if succeeded and typeof(hiddenUi) == "Instance" then
            return hiddenUi :: Instance
        end
    end
    return playerGui
end

local function makeLabel(
    parent: Instance,
    text: string,
    size: number,
    scale: number,
    registry: {Instance}?
): TextLabel
    local label: TextLabel = create("TextLabel", {
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        Font = Enum.Font.Gotham,
        Text = text,
        TextColor3 = THEME.Text,
        TextSize = math.round(size * scale),
        TextXAlignment = Enum.TextXAlignment.Left,
        TextYAlignment = Enum.TextYAlignment.Center,
        Parent = parent,
    })
    label:SetAttribute("BaseTextSize", size)
    if registry then
        table.insert(registry, label)
    end
    return label
end

local function makeButton(
    parent: Instance,
    text: string,
    size: number,
    scale: number,
    registry: {Instance}?
): TextButton
    local button: TextButton = create("TextButton", {
        AutoButtonColor = false,
        BackgroundColor3 = THEME.Surface,
        BorderSizePixel = 0,
        Font = Enum.Font.GothamMedium,
        Text = text,
        TextColor3 = THEME.Text,
        TextSize = math.round(size * scale),
        Parent = parent,
    })
    button:SetAttribute("BaseTextSize", size)
    if registry then
        table.insert(registry, button)
    end
    round(button, 8)
    stroke(button, 0.52)
    return button
end

local function applyKeySlotStyle(button: TextButton): ImageLabel
    button.ZIndex = math.max(2, button.ZIndex)
    local corner: UICorner? = button:FindFirstChildOfClass("UICorner")
    local buttonStroke: UIStroke? = button:FindFirstChildOfClass("UIStroke")
    local frame: ImageLabel = create("ImageLabel", {
        Name = "KeySlotFrame",
        AnchorPoint = Vector2.new(0.5, 0.5),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        Image = ASSETS.KeybindPill.fallback,
        ImageColor3 = THEME.Text,
        ImageTransparency = 0.06,
        Position = UDim2.fromScale(0.5, 0.5),
        ScaleType = Enum.ScaleType.Slice,
        SliceCenter = Rect.new(300, 300, 1870, 420),
        SliceScale = 0.5,
        Size = UDim2.new(1, 10, 1, 10),
        ZIndex = button.ZIndex - 1,
        Parent = button,
    })
    loadImage(frame, "KeybindPill", function(loaded: boolean): ()
        if not loaded or button.Parent == nil then
            return
        end
        button.BackgroundTransparency = 1
        if corner and corner.Parent then
            corner:Destroy()
        end
        if buttonStroke and buttonStroke.Parent then
            buttonStroke:Destroy()
        end
    end)
    return frame
end

local function getPointer(input: InputObject): Vector2
    return Vector2.new(input.Position.X, input.Position.Y)
end

local Gui = {
    Assets = ASSETS,
    Theme = THEME,
}

function Gui.new(options: GuiOptions?): GuiController
    local resolved: GuiOptions = options or {}
    local player: Player = Players.LocalPlayer
    local playerGui: PlayerGui = player:WaitForChild("PlayerGui") :: PlayerGui
    local isMobile: boolean = UserInputService.TouchEnabled
        and not UserInputService.KeyboardEnabled
    local camera: Camera? = workspace.CurrentCamera
    local viewport: Vector2 = camera and camera.ViewportSize or Vector2.new(1280, 720)
    local width: number = math.floor(viewport.X * (isMobile and 0.94 or 0.72))
    local height: number = math.floor(viewport.Y * (isMobile and 0.84 or 0.78))
    local textObjects: {Instance} = {}
    local capturingKeybind: boolean = false

    local screenGui: ScreenGui = create("ScreenGui", {
        Name = resolved.name or "ARandomMenuGui",
        ResetOnSpawn = false,
        IgnoreGuiInset = true,
        DisplayOrder = 999999,
        ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
        Parent = resolved.parent or getGuiParent(playerGui),
    })
    local blur: BlurEffect = create("BlurEffect", {
        Name = "ARandomMenuBlur",
        Enabled = true,
        Size = 14,
        Parent = Lighting,
    })
    local window: Frame = create("Frame", {
        Name = "Window",
        Active = true,
        BackgroundColor3 = THEME.Background,
        BorderSizePixel = 0,
        ClipsDescendants = true,
        Position = UDim2.fromOffset(
            math.max(0, math.floor((viewport.X - width) / 2)),
            math.max(0, math.floor((viewport.Y - height) / 2))
        ),
        Size = UDim2.fromOffset(width, height),
        Parent = screenGui,
    })
    round(window, 18)
    local windowStroke: UIStroke = stroke(window, 0.28, 1.2)
    windowStroke.Color = Color3.fromRGB(188, 188, 194)

    local header: Frame = create("Frame", {
        Name = "Header",
        Active = true,
        BackgroundColor3 = THEME.Background,
        BorderSizePixel = 0,
        ClipsDescendants = true,
        Size = UDim2.new(1, 0, 0, 82),
        ZIndex = 20,
        Parent = window,
    })
    local headerImage: ImageLabel = create("ImageLabel", {
        Name = "HeaderImage",
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        Image = ASSETS.Header.fallback,
        ImageColor3 = Color3.fromRGB(220, 220, 224),
        ImageTransparency = 0.2,
        ScaleType = Enum.ScaleType.Crop,
        Size = UDim2.fromScale(1, 1),
        ZIndex = 21,
        Parent = header,
    })
    loadImage(headerImage, "Header")
    create("Frame", {
        Name = "HeaderShade",
        BackgroundColor3 = THEME.Background,
        BackgroundTransparency = 0.35,
        BorderSizePixel = 0,
        Size = UDim2.fromScale(1, 1),
        ZIndex = 22,
        Parent = header,
    })
    local title: TextLabel = makeLabel(
        header,
        resolved.title or "A Random Menu",
        isMobile and 25 or 31,
        1,
        textObjects
    )
    title.Font = Enum.Font.Fondamento
    title.Position = UDim2.fromOffset(26, 2)
    title.Size = UDim2.new(1, -52, 1, -16)
    title.TextXAlignment = Enum.TextXAlignment.Center
    title.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
    title.TextStrokeTransparency = 0.25
    title.ZIndex = 24

    local ornament: ImageLabel = create("ImageLabel", {
        Name = "CosmicDivider",
        AnchorPoint = Vector2.new(0.5, 1),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        Image = ASSETS.CosmicControls.fallback,
        ImageColor3 = THEME.Text,
        ImageRectOffset = Vector2.new(666, 298),
        ImageRectSize = Vector2.new(171, 48),
        ImageTransparency = 0.12,
        Position = UDim2.new(0.5, 0, 1, -2),
        ScaleType = Enum.ScaleType.Stretch,
        Size = UDim2.new(0.56, 0, 0, 30),
        ZIndex = 23,
        Parent = header,
    })
    loadImage(ornament, "CosmicControls")

    local tabs: ScrollingFrame = create("ScrollingFrame", {
        Name = "Tabs",
        Active = true,
        AutomaticCanvasSize = Enum.AutomaticSize.X,
        BackgroundColor3 = Color3.fromRGB(8, 8, 9),
        BorderSizePixel = 0,
        CanvasSize = UDim2.fromOffset(0, 0),
        Position = UDim2.fromOffset(0, 82),
        ScrollBarThickness = 0,
        ScrollingDirection = Enum.ScrollingDirection.X,
        Size = UDim2.new(1, 0, 0, 46),
        ZIndex = 10,
        Parent = window,
    })
    create("UIListLayout", {
        FillDirection = Enum.FillDirection.Horizontal,
        Padding = UDim.new(0, 4),
        SortOrder = Enum.SortOrder.LayoutOrder,
        Parent = tabs,
    })
    create("UIPadding", {
        PaddingLeft = UDim.new(0, 8),
        PaddingRight = UDim.new(0, 8),
        Parent = tabs,
    })
    local tabDivider: ImageLabel = create("ImageLabel", {
        Name = "TabDivider",
        AnchorPoint = Vector2.new(0.5, 0),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        Image = ASSETS.InkScratch.fallback,
        ImageColor3 = THEME.Outline,
        ImageRectOffset = Vector2.new(0, 0),
        ImageRectSize = Vector2.new(489, 124),
        ImageTransparency = 0.35,
        Position = UDim2.new(0.5, 0, 0, 126),
        ScaleType = Enum.ScaleType.Stretch,
        Size = UDim2.new(0.82, 0, 0, 14),
        ZIndex = 4,
        Parent = window,
    })
    loadImage(tabDivider, "InkScratch")
    local content: Frame = create("Frame", {
        Name = "Content",
        BackgroundColor3 = THEME.Background,
        BackgroundTransparency = 0,
        BorderSizePixel = 0,
        Position = UDim2.fromOffset(0, 128),
        Size = UDim2.new(1, 0, 1, -128),
        ZIndex = 3,
        Parent = window,
    })

    local controller: GuiController = {
        screenGui = screenGui,
        window = window,
        content = content,
        modules = {},
        pages = {},
        tabButtons = {},
        connections = {},
        featureConnections = {},
        activeTab = nil,
        visible = resolved.initiallyVisible ~= false,
        textScale = 1.08,
        blurEnabled = true,
        createModule = nil :: any,
        setTab = nil :: any,
        setTabIcon = nil :: any,
        setTextScale = nil :: any,
        setVisible = nil :: any,
        destroy = nil :: any,
    }

    function controller:setTab(id: string): ()
        if self.pages[id] == nil then
            return
        end
        self.activeTab = id
        for pageId: string, page: ScrollingFrame in pairs(self.pages) do
            page.Visible = pageId == id
        end
        for buttonId: string, button: TextButton in pairs(self.tabButtons) do
            local selected: boolean = buttonId == id
            button:SetAttribute("Selected", selected)
            tween(button, {
                BackgroundColor3 = selected and THEME.SurfaceActive or THEME.Surface,
                TextColor3 = selected and THEME.Text or THEME.MutedText,
            })
            local indicator: Frame? = button:FindFirstChild("Indicator") :: Frame?
            if indicator then
                tween(indicator, {BackgroundTransparency = selected and 0 or 1})
            end
            local icon: ImageLabel? = button:FindFirstChild("TabIcon") :: ImageLabel?
            if icon then
                tween(icon, {
                    ImageColor3 = selected and THEME.Text or THEME.MutedText,
                })
            end
        end
    end

    function controller:setTabIcon(id: string, assetKey: string): ()
        local button: TextButton? = self.tabButtons[id]
        local source: AssetSource? = ASSETS[assetKey]
        if button == nil or source == nil then
            return
        end
        local existing: Instance? = button:FindFirstChild("TabIcon")
        if existing then
            existing:Destroy()
        end
        local icon: ImageLabel = create("ImageLabel", {
            Name = "TabIcon",
            AnchorPoint = Vector2.new(0, 0.5),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            Image = (source :: AssetSource).fallback,
            ImageColor3 = self.activeTab == id and THEME.Text or THEME.MutedText,
            Position = UDim2.new(0, 10, 0.5, 0),
            ScaleType = Enum.ScaleType.Fit,
            Size = UDim2.fromOffset(16, 16),
            ZIndex = button.ZIndex + 1,
            Parent = button,
        })
        loadImage(icon, assetKey)
        button.TextXAlignment = Enum.TextXAlignment.Left
        local padding: UIPadding? = button:FindFirstChildOfClass("UIPadding")
        if padding == nil then
            create("UIPadding", {
                PaddingLeft = UDim.new(0, 32),
                Parent = button,
            })
        end
    end

    function controller:setTextScale(scale: number): ()
        local nextScale: number = math.clamp(scale, 0.85, 1.35)
        if math.abs(nextScale - self.textScale) < 0.0001 then
            return
        end
        self.textScale = nextScale
        for index: number = #textObjects, 1, -1 do
            local textObject: Instance = textObjects[index]
            if textObject.Parent == nil then
                table.remove(textObjects, index)
            else
                local baseSize: any = textObject:GetAttribute("BaseTextSize")
                if type(baseSize) == "number" then
                    (textObject :: any).TextSize = math.round(baseSize * nextScale)
                end
            end
        end
    end

    function controller:createModule(
        id: string,
        label: string,
        layoutOrder: number
    ): ModuleController
        assert(self.modules[id] == nil, "Duplicate module: " .. id)
        local tabButton: TextButton = makeButton(
            tabs,
            label,
            13,
            self.textScale,
            textObjects
        )
        tabButton.Name = id .. "Tab"
        tabButton.LayoutOrder = layoutOrder
        tabButton.Size = UDim2.fromOffset(isMobile and 106 or 124, 42)
        tabButton.TextColor3 = THEME.MutedText
        tabButton.ZIndex = 11
        local indicator: Frame = create("Frame", {
            Name = "Indicator",
            AnchorPoint = Vector2.new(0, 1),
            BackgroundColor3 = THEME.Accent,
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            Position = UDim2.new(0, 9, 1, -2),
            Size = UDim2.new(1, -18, 0, 2),
            Parent = tabButton,
        })
        round(indicator, 2)
        local page: ScrollingFrame = create("ScrollingFrame", {
            Name = id .. "Page",
            Active = true,
            AutomaticCanvasSize = Enum.AutomaticSize.Y,
            BackgroundColor3 = THEME.Background,
            BackgroundTransparency = 0,
            BorderSizePixel = 0,
            CanvasSize = UDim2.fromOffset(0, 0),
            ScrollBarImageColor3 = THEME.MutedText,
            ScrollBarThickness = 4,
            Size = UDim2.fromScale(1, 1),
            Visible = false,
            Parent = content,
        })
        create("UIPadding", {
            PaddingBottom = UDim.new(0, 18),
            PaddingLeft = UDim.new(0, 18),
            PaddingRight = UDim.new(0, 18),
            PaddingTop = UDim.new(0, 18),
            Parent = page,
        })
        create("UIListLayout", {
            Padding = UDim.new(0, 8),
            SortOrder = Enum.SortOrder.LayoutOrder,
            Parent = page,
        })

        local module: ModuleController = {
            id = id,
            page = page,
            addToggle = nil :: any,
            addAction = nil :: any,
        }

        local function createFeature(
            featureId: string,
            featureLabel: string,
            description: string,
            isAction: boolean,
            callback: any
        ): FeatureController
            local row: Frame = create("Frame", {
                Name = featureId .. "Feature",
                Active = true,
                BackgroundColor3 = THEME.Background,
                BackgroundTransparency = 1,
                BorderSizePixel = 0,
                ClipsDescendants = true,
                Size = UDim2.new(1, 0, 0, 54),
                Parent = page,
            })
            round(row, 10)
            local rowStroke: UIStroke = stroke(row, 1)
            local activeStripe: Frame = create("Frame", {
                Name = "ActiveStripe",
                BackgroundColor3 = THEME.Accent,
                BackgroundTransparency = 1,
                BorderSizePixel = 0,
                Position = UDim2.fromOffset(0, 7),
                Size = UDim2.new(0, 3, 0, 40),
                Parent = row,
            })
            round(activeStripe, 3)
            local featureTitle: TextLabel = makeLabel(
                row,
                featureLabel,
                13,
                controller.textScale,
                textObjects
            )
            featureTitle.Font = Enum.Font.GothamMedium
            featureTitle.Position = UDim2.fromOffset(16, 0)
            featureTitle.Size = UDim2.new(1, -148, 0, 31)
            local featureDescription: TextLabel = makeLabel(
                row,
                description,
                11,
                controller.textScale,
                textObjects
            )
            featureDescription.Position = UDim2.fromOffset(16, 27)
            featureDescription.Size = UDim2.new(1, -148, 0, 21)
            featureDescription.TextColor3 = THEME.MutedText
            featureDescription.TextTruncate = Enum.TextTruncate.AtEnd

            local toggle: TextButton = makeButton(
                row,
                isAction and "RUN" or "",
                10,
                controller.textScale,
                textObjects
            )
            toggle.Name = "Toggle"
            toggle.AnchorPoint = Vector2.new(1, 0.5)
            toggle.Position = UDim2.new(1, -40, 0, 27)
            toggle.Size = isAction and UDim2.fromOffset(48, 25) or UDim2.fromOffset(42, 24)
            local toggleKnob: Frame? = nil
            if not isAction then
                toggleKnob = create("Frame", {
                    Name = "Knob",
                    AnchorPoint = Vector2.new(0, 0.5),
                    BackgroundColor3 = THEME.Text,
                    BorderSizePixel = 0,
                    Position = UDim2.new(0, 4, 0.5, 0),
                    Size = UDim2.fromOffset(16, 16),
                    Parent = toggle,
                })
                round(toggleKnob :: Frame, 8)
            end
            local more: TextButton = makeButton(
                row,
                "•••",
                12,
                controller.textScale,
                textObjects
            )
            more.Name = "More"
            more.AnchorPoint = Vector2.new(1, 0.5)
            more.BackgroundTransparency = 1
            more.Position = UDim2.new(1, -7, 0, 27)
            more.Size = UDim2.fromOffset(27, 27)
            more.TextColor3 = THEME.MutedText

            local optionsFrame: Frame = create("Frame", {
                Name = "Options",
                BackgroundColor3 = THEME.Surface,
                BackgroundTransparency = 0.45,
                BorderSizePixel = 0,
                Position = UDim2.fromOffset(10, 56),
                Size = UDim2.new(1, -20, 0, 0),
                Visible = false,
                Parent = row,
            })
            round(optionsFrame, 8)
            create("UIPadding", {
                PaddingBottom = UDim.new(0, 7),
                PaddingLeft = UDim.new(0, 9),
                PaddingRight = UDim.new(0, 9),
                PaddingTop = UDim.new(0, 7),
                Parent = optionsFrame,
            })
            local optionsLayout: UIListLayout = create("UIListLayout", {
                Padding = UDim.new(0, 6),
                SortOrder = Enum.SortOrder.LayoutOrder,
                Parent = optionsFrame,
            })
            local feature: FeatureController = {
                row = row,
                options = optionsFrame,
                enabled = false,
                expanded = false,
                addSlider = nil :: any,
                addKeybind = nil :: any,
                setEnabled = nil :: any,
                setExpanded = nil :: any,
            }
            local resizing: boolean = false

            local function refreshEnabled(): ()
                local enabled: boolean = feature.enabled
                tween(row, {
                    BackgroundColor3 = enabled and THEME.SurfaceActive or THEME.Background,
                    BackgroundTransparency = enabled and 0.06 or 1,
                })
                tween(rowStroke, {
                    Color = enabled and THEME.Accent or THEME.Outline,
                    Transparency = enabled and 0.14 or 1,
                })
                tween(activeStripe, {BackgroundTransparency = enabled and 0 or 1})
                tween(featureTitle, {
                    TextColor3 = enabled and Color3.new(1, 1, 1) or THEME.Text,
                })
                if toggleKnob then
                    tween(toggle, {
                        BackgroundColor3 = enabled and THEME.Accent or THEME.Surface,
                    })
                    tween(toggleKnob :: Frame, {
                        BackgroundColor3 = enabled and THEME.Background or THEME.Text,
                        Position = enabled
                            and UDim2.new(1, -20, 0.5, 0)
                            or UDim2.new(0, 4, 0.5, 0),
                    })
                end
            end

            function feature:setEnabled(enabled: boolean): ()
                if isAction then
                    return
                end
                self.enabled = enabled
                refreshEnabled()
            end

            function feature:setExpanded(expanded: boolean): ()
                self.expanded = expanded
                local optionsHeight: number = optionsLayout.AbsoluteContentSize.Y + 14
                self.options.Visible = expanded
                self.options.Size = UDim2.new(1, -20, 0, expanded and optionsHeight or 0)
                self.row.Size = UDim2.new(1, 0, 0, expanded and 64 + optionsHeight or 54)
                more.TextColor3 = expanded and THEME.Text or THEME.MutedText
            end

            function feature:addSlider(
                sliderLabel: string,
                minimum: number,
                maximum: number,
                initial: number,
                sliderCallback: (number) -> ()
            ): ()
                assert(maximum > minimum, "Slider maximum must exceed minimum")
                local value: number = math.clamp(initial, minimum, maximum)
                local option: Frame = create("Frame", {
                    BackgroundTransparency = 1,
                    BorderSizePixel = 0,
                    Size = UDim2.new(1, 0, 0, 38),
                    Parent = optionsFrame,
                })
                local optionLabel: TextLabel = makeLabel(
                    option,
                    sliderLabel,
                    10,
                    controller.textScale,
                    textObjects
                )
                optionLabel.Size = UDim2.new(0.38, 0, 1, 0)
                local valueLabel: TextLabel = makeLabel(
                    option,
                    tostring(math.round(value)),
                    10,
                    controller.textScale,
                    textObjects
                )
                valueLabel.AnchorPoint = Vector2.new(1, 0)
                valueLabel.Position = UDim2.new(1, 0, 0, 0)
                valueLabel.Size = UDim2.fromOffset(42, 38)
                valueLabel.TextXAlignment = Enum.TextXAlignment.Right
                local track: TextButton = create("TextButton", {
                    AutoButtonColor = false,
                    BackgroundColor3 = Color3.fromRGB(50, 50, 55),
                    BorderSizePixel = 0,
                    Position = UDim2.new(0.4, 0, 0.5, -2),
                    Size = UDim2.new(0.6, -50, 0, 4),
                    Text = "",
                    Parent = option,
                })
                round(track, 3)
                local ratio: number = (value - minimum) / (maximum - minimum)
                local fill: Frame = create("Frame", {
                    BackgroundColor3 = THEME.Accent,
                    BorderSizePixel = 0,
                    Size = UDim2.fromScale(ratio, 1),
                    Parent = track,
                })
                round(fill, 3)
                local knob: Frame = create("Frame", {
                    AnchorPoint = Vector2.new(0.5, 0.5),
                    BackgroundColor3 = THEME.Text,
                    BorderSizePixel = 0,
                    Position = UDim2.fromScale(ratio, 0.5),
                    Size = UDim2.fromOffset(12, 12),
                    Parent = track,
                })
                round(knob, 6)
                local dragInput: InputObject? = nil
                local function update(pointerX: number): ()
                    local nextRatio: number = math.clamp(
                        (pointerX - track.AbsolutePosition.X)
                            / math.max(1, track.AbsoluteSize.X),
                        0,
                        1
                    )
                    value = minimum + (maximum - minimum) * nextRatio
                    fill.Size = UDim2.fromScale(nextRatio, 1)
                    knob.Position = UDim2.fromScale(nextRatio, 0.5)
                    valueLabel.Text = tostring(math.round(value))
                    sliderCallback(value)
                end
                table.insert(controller.featureConnections, track.InputBegan:Connect(function(
                    input: InputObject
                ): ()
                    if input.UserInputType == Enum.UserInputType.MouseButton1
                        or input.UserInputType == Enum.UserInputType.Touch then
                        dragInput = input
                        update(input.Position.X)
                    end
                end))
                table.insert(controller.featureConnections,
                    UserInputService.InputChanged:Connect(function(input: InputObject): ()
                        if dragInput and (input == dragInput
                            or input.UserInputType == Enum.UserInputType.MouseMovement) then
                            update(input.Position.X)
                        end
                    end)
                )
                table.insert(controller.featureConnections,
                    UserInputService.InputEnded:Connect(function(input: InputObject): ()
                        if input == dragInput
                            or input.UserInputType == Enum.UserInputType.MouseButton1
                            or input.UserInputType == Enum.UserInputType.Touch then
                            dragInput = nil
                        end
                    end)
                )
            end

            function feature:addKeybind(
                keybindLabel: string,
                initial: Enum.KeyCode,
                keybindCallback: (Enum.KeyCode) -> ()
            ): TextButton
                local selected: Enum.KeyCode = initial
                local capturing: boolean = false
                local option: Frame = create("Frame", {
                    BackgroundTransparency = 1,
                    BorderSizePixel = 0,
                    Size = UDim2.new(1, 0, 0, 38),
                    Parent = optionsFrame,
                })
                local optionLabel: TextLabel = makeLabel(
                    option,
                    keybindLabel,
                    11,
                    controller.textScale,
                    textObjects
                )
                optionLabel.Size = UDim2.new(0.48, 0, 1, 0)
                local keyButton: TextButton = makeButton(
                    option,
                    selected.Name,
                    11,
                    controller.textScale,
                    textObjects
                )
                keyButton.AnchorPoint = Vector2.new(1, 0.5)
                keyButton.Position = UDim2.new(1, -4, 0.5, 0)
                keyButton.Size = UDim2.new(0.45, 0, 0, 30)
                local keyFrame: ImageLabel = applyKeySlotStyle(keyButton)
                table.insert(controller.featureConnections,
                    keyButton.MouseButton1Click:Connect(function(): ()
                        capturing = true
                        capturingKeybind = true
                        keyButton.Text = "PRESS A KEY…"
                        tween(keyFrame, {
                            ImageColor3 = Color3.new(1, 1, 1),
                            ImageTransparency = 0,
                        })
                    end)
                )
                table.insert(controller.featureConnections,
                    UserInputService.InputBegan:Connect(function(
                        input: InputObject,
                        _processed: boolean
                    ): ()
                        if not capturing
                            or input.UserInputType ~= Enum.UserInputType.Keyboard
                            or input.KeyCode == Enum.KeyCode.Unknown then
                            return
                        end
                        capturing = false
                        selected = input.KeyCode
                        keyButton.Text = selected.Name
                        tween(keyFrame, {
                            ImageColor3 = THEME.Text,
                            ImageTransparency = 0.06,
                        })
                        keybindCallback(selected)
                        task.defer(function(): ()
                            capturingKeybind = false
                        end)
                    end)
                )
                keybindCallback(selected)
                return keyButton
            end

            table.insert(controller.connections, more.MouseButton1Click:Connect(function(): ()
                feature:setExpanded(not feature.expanded)
            end))
            table.insert(controller.connections, toggle.MouseButton1Click:Connect(function(): ()
                if isAction then
                    task.spawn(callback)
                    return
                end
                local requested: boolean = not feature.enabled
                local succeeded: boolean, message: any = pcall(callback, requested)
                feature.enabled = succeeded and requested or false
                if not succeeded then
                    warn("[ARandomMenu] " .. featureLabel .. ": " .. tostring(message))
                end
                refreshEnabled()
            end))
            table.insert(controller.connections, row.MouseEnter:Connect(function(): ()
                if not feature.enabled then
                    tween(row, {
                        BackgroundColor3 = THEME.SurfaceHover,
                        BackgroundTransparency = 0.24,
                    })
                end
            end))
            table.insert(controller.connections, row.MouseLeave:Connect(refreshEnabled))
            table.insert(controller.connections,
                optionsLayout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(
                    function(): ()
                        if feature.expanded and not resizing then
                            resizing = true
                            feature:setExpanded(true)
                            resizing = false
                        end
                    end
                )
            )
            return feature
        end

        function module:addToggle(
            featureId: string,
            featureLabel: string,
            description: string,
            callback: (boolean) -> ()
        ): FeatureController
            return createFeature(featureId, featureLabel, description, false, callback)
        end

        function module:addAction(
            featureId: string,
            featureLabel: string,
            description: string,
            callback: () -> ()
        ): FeatureController
            return createFeature(featureId, featureLabel, description, true, callback)
        end

        self.modules[id] = module
        self.pages[id] = page
        self.tabButtons[id] = tabButton
        local defaultIcon: string? = DEFAULT_TAB_ICONS[id]
        if defaultIcon then
            self:setTabIcon(id, defaultIcon)
        end
        table.insert(self.connections, tabButton.MouseButton1Click:Connect(function(): ()
            self:setTab(id)
        end))
        table.insert(self.connections, tabButton.MouseEnter:Connect(function(): ()
            if self.activeTab ~= id then
                tween(tabButton, {BackgroundColor3 = THEME.SurfaceHover})
            end
        end))
        table.insert(self.connections, tabButton.MouseLeave:Connect(function(): ()
            if self.activeTab ~= id then
                tween(tabButton, {BackgroundColor3 = THEME.Surface})
            end
        end))
        if self.activeTab == nil then
            self:setTab(id)
        elseif id ~= "Settings" and self.activeTab == "Settings" then
            self:setTab(id)
        end
        return module
    end

    function controller:setVisible(visible: boolean): ()
        self.visible = visible
        window.Visible = visible
        blur.Enabled = visible and self.blurEnabled
        blur.Size = (visible and self.blurEnabled) and 14 or 0
    end

    function controller:destroy(): ()
        capturingKeybind = false
        for _, connection: RBXScriptConnection in ipairs(self.featureConnections) do
            connection:Disconnect()
        end
        table.clear(self.featureConnections)
        for _, connection: RBXScriptConnection in ipairs(self.connections) do
            connection:Disconnect()
        end
        table.clear(self.connections)
        table.clear(textObjects)
        if blur.Parent then
            blur:Destroy()
        end
        if screenGui.Parent then
            screenGui:Destroy()
        end
    end

    local settings: ModuleController = controller:createModule(
        "Settings",
        "Settings",
        999
    )
    local textSetting: FeatureController = settings:addAction(
        "TextSize",
        "Text size",
        "Drag the linear bar to resize all interface text",
        function(): () end
    )
    local textToggle: Instance? = textSetting.row:FindFirstChild("Toggle")
    if textToggle and textToggle:IsA("GuiObject") then
        textToggle.Visible = false
    end
    local textMore: Instance? = textSetting.row:FindFirstChild("More")
    if textMore and textMore:IsA("GuiObject") then
        textMore.Visible = false
    end
    textSetting:addSlider("Scale", 85, 135, 108, function(value: number): ()
        controller:setTextScale(value / 100)
    end)
    task.defer(function(): ()
        textSetting:setExpanded(true)
    end)

    local blurSetting: FeatureController = settings:addToggle(
        "BlurMode",
        "Blur mode",
        "Blur the game while the menu is visible",
        function(enabled: boolean): ()
            controller.blurEnabled = enabled
            blur.Enabled = controller.visible and enabled
            blur.Size = (controller.visible and enabled) and 14 or 0
        end
    )
    blurSetting:setEnabled(true)

    local menuKey: Enum.KeyCode = Enum.KeyCode.RightShift
    local menuKeySetting: FeatureController = settings:addAction(
        "MenuKey",
        "Menu key",
        "Choose the key used to show or hide this interface",
        function(): () end
    )
    local menuKeyAction: Instance? = menuKeySetting.row:FindFirstChild("Toggle")
    if menuKeyAction and menuKeyAction:IsA("GuiObject") then
        menuKeyAction.Visible = false
    end
    menuKeySetting:addKeybind(
        "Show / hide",
        menuKey,
        function(selected: Enum.KeyCode): ()
            menuKey = selected
        end
    )
    task.defer(function(): ()
        menuKeySetting:setExpanded(true)
    end)

    local reinjectButton: TextButton? = nil
    local reinjecting: boolean = false
    local _reinjectSetting: FeatureController = settings:addAction(
        "Reinject",
        "Reinject latest",
        "Download and restart the newest main build",
        function(): ()
            if reinjecting then
                return
            end
            local compiler: any = executorEnvironment.loadstring
            if type(compiler) ~= "function" then
                warn("[ARandomMenu] Reinject requires loadstring support")
                return
            end
            reinjecting = true
            if reinjectButton then
                reinjectButton.Text = "DOWNLOADING…"
            end
            local sourceUrls: {string} = {
                resolved.reinjectUrl or (RAW_BASE .. "ARandomMenu.luau"),
                RUNTIME_SAFETY_SOURCE_URL,
            }
            local downloaded: boolean = false
            local sourceOrError: any = nil
            local downloadFailures: {string} = {}
            for _, candidateUrl: string in ipairs(sourceUrls) do
                local requestUrl: string = candidateUrl
                    .. "?reinject=v3&nocache="
                    .. HttpService:GenerateGUID(false)
                local requestOk: boolean, bodyOrError: any = pcall(function(): string
                    return (game :: any):HttpGet(requestUrl, true)
                end)
                local current: boolean = requestOk
                    and type(bodyOrError) == "string"
                    and #bodyOrError >= 1024
                    and bodyOrError:find(
                        RUNTIME_COMPATIBILITY_MARKER,
                        1,
                        true
                    ) ~= nil
                if current then
                    downloaded = true
                    sourceOrError = bodyOrError
                    break
                end
                table.insert(downloadFailures, tostring(bodyOrError))
            end
            if not downloaded then
                reinjecting = false
                if reinjectButton then
                    reinjectButton.Text = "REINJECT"
                end
                warn("[ARandomMenu] Reinject download: "
                    .. table.concat(downloadFailures, " | "))
                return
            end
            local compiledOk: boolean, compiledOrError: any, returnedError: any = pcall(
                compiler,
                sourceOrError,
                "@ARandomMenu.luau"
            )
            if not compiledOk or type(compiledOrError) ~= "function" then
                reinjecting = false
                if reinjectButton then
                    reinjectButton.Text = "REINJECT"
                end
                warn("[ARandomMenu] Reinject compile: "
                    .. tostring(compiledOk and returnedError or compiledOrError))
                return
            end
            if reinjectButton then
                reinjectButton.Text = "RESTARTING…"
            end
            controller:destroy()
            task.defer(function(): ()
                local executed: boolean, executionError: any = xpcall(
                    compiledOrError,
                    debug.traceback
                )
                if not executed then
                    warn("[ARandomMenu] Reinject runtime: " .. tostring(executionError))
                end
            end)
        end
    )
    reinjectButton = _reinjectSetting.row:FindFirstChild("Toggle") :: TextButton?
    if reinjectButton then
        reinjectButton.Text = "REINJECT"
        reinjectButton.Size = UDim2.fromOffset(86, 27)
    end

    local dragging: boolean = false
    local dragInput: InputObject? = nil
    local dragOrigin: Vector2 = Vector2.zero
    local windowOrigin: Vector2 = Vector2.zero
    table.insert(controller.connections, header.InputBegan:Connect(function(
        input: InputObject
    ): ()
        if input.UserInputType ~= Enum.UserInputType.MouseButton1
            and input.UserInputType ~= Enum.UserInputType.Touch then
            return
        end
        dragging = true
        dragInput = input
        dragOrigin = getPointer(input)
        windowOrigin = Vector2.new(window.Position.X.Offset, window.Position.Y.Offset)
    end))
    table.insert(controller.connections, UserInputService.InputChanged:Connect(function(
        input: InputObject
    ): ()
        local matches: boolean = dragInput ~= nil
            and (((dragInput :: InputObject).UserInputType == Enum.UserInputType.Touch
                and input == dragInput)
                or input.UserInputType == Enum.UserInputType.MouseMovement)
        if not dragging or not matches then
            return
        end
        local currentCamera: Camera? = workspace.CurrentCamera
        local currentViewport: Vector2 = currentCamera
            and currentCamera.ViewportSize
            or viewport
        local nextPosition: Vector2 = windowOrigin + (getPointer(input) - dragOrigin)
        window.Position = UDim2.fromOffset(
            math.clamp(nextPosition.X, 0, math.max(0, currentViewport.X - window.AbsoluteSize.X)),
            math.clamp(nextPosition.Y, 0, math.max(0, currentViewport.Y - window.AbsoluteSize.Y))
        )
    end))
    table.insert(controller.connections, UserInputService.InputEnded:Connect(function(
        input: InputObject
    ): ()
        if input == dragInput or input.UserInputType == Enum.UserInputType.MouseButton1 then
            dragging = false
            dragInput = nil
        end
    end))
    table.insert(controller.connections, UserInputService.InputBegan:Connect(function(
        input: InputObject,
        processed: boolean
    ): ()
        if capturingKeybind or processed then
            return
        end
        if input.UserInputType == Enum.UserInputType.Keyboard
            and input.KeyCode == menuKey then
            controller:setVisible(not controller.visible)
        end
    end))

    if isMobile or menuKey == Enum.KeyCode.Unknown then
        local menuButton: ImageButton = create("ImageButton", {
            Name = "MobileMenuButton",
            AnchorPoint = Vector2.new(1, 0),
            AutoButtonColor = false,
            BackgroundColor3 = THEME.Surface,
            BorderSizePixel = 0,
            Image = ASSETS.MobileToggle.fallback,
            Position = UDim2.new(1, -18, 0, 18),
            ScaleType = Enum.ScaleType.Crop,
            Size = UDim2.fromOffset(52, 52),
            ClipsDescendants = true,
            ZIndex = 100,
            Parent = screenGui,
        })
        round(menuButton, 26)
        stroke(menuButton, 0.18, 1.2)
        loadImage(menuButton, "MobileToggle")
        table.insert(controller.connections, menuButton.Activated:Connect(
            function(): ()
                controller:setVisible(not controller.visible)
            end
        ))
    end

    local spinner: ImageLabel = create("ImageLabel", {
        Name = "LoadingSpinner",
        AnchorPoint = Vector2.new(1, 0.5),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        Image = ASSETS.Spinner.fallback,
        ImageColor3 = THEME.MutedText,
        Position = UDim2.new(1, -16, 0, 41),
        Size = UDim2.fromOffset(18, 18),
        ZIndex = 25,
        Parent = header,
    })
    loadImage(spinner, "Spinner")
    task.spawn(function(): ()
        local elapsed: number = 0
        while elapsed < 6 and spinner.Parent ~= nil do
            elapsed += task.wait(0.05)
            spinner.Rotation = (spinner.Rotation + 9) % 360
        end
        if spinner.Parent ~= nil then
            spinner:Destroy()
        end
    end)

    controller:setVisible(resolved.initiallyVisible ~= false)
    return controller
end

return table.freeze(Gui)

]=],
        ["src/guis/Wurst/Code/Cards.lua"] = [[
local Module = {
    Name = "Cards",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local moduleCleanup: () -> () = function(): () end

function Module.init(context: any): any
    local host: any = context
    local state: any = host.state
    local configData: any = host.configData
    local queueConfigSave: any = host.queueConfigSave
    local flushConfigSave: any = host.flushConfigSave or queueConfigSave
    local create: any = host.create
    local makeButton: any = host.makeButton
    local makeTextLabel: any = host.makeTextLabel
    local notify: any = host.notify
    local Theme: any = host.Theme
    local CONTROL_FONT: any = host.CONTROL_FONT
    local trackUiConnection: any = host.trackUiConnection
    local beginKeyCapture: any = host.beginKeyCapture
    local UserInputService: any = host.UserInputService
    local applyKeySlotStyle: any = host.applyKeySlotStyle
    local bindActionShortcut: any = host.bindActionShortcut
    local getFeatureCardParent: any = host.getFeatureCardParent

    local FEATURE_CATEGORIES: any = host.FEATURE_CATEGORIES
    local DEFAULT_FEATURE_CATEGORY: any = host.DEFAULT_FEATURE_CATEGORY
    local normalizeFeatureCategory: any = host.normalizeFeatureCategory

    local universalFeatures: any = host.universalFeatures
    local movementFeatures: any = host.movementFeatures
    local mm2Features: any = host.mm2Features
    local allFeatures: any = host.allFeatures
    local registeredSearchFeatures: {any} = {}

    local applyFeaturePresentation: any = host.applyFeaturePresentation
    local refreshFeatureToggle: any = host.refreshFeatureToggle
    local addFeatureTooltip: any = host.addFeatureTooltip

    local drawPixelIcon: any = host.drawPixelIcon
        or function(parent: Instance, _kind: string, _color: Color3?): Frame
            local existing: Instance? = (parent :: any):FindFirstChild("PixelIcon")
            if existing then
                existing:Destroy()
            end
            return create("Frame", {
                Parent = parent,
                Name = "PixelIcon",
                BackgroundTransparency = 1,
            }) :: Frame
        end

    local function createUniversalFeature(
        name: string,
        description: string,
        layoutOrder: number,
        onToggle: any,
        configuration: any?
    ): any
        configuration = configuration or {}
        local ordered: {[string]: number} = {
            ["ItemESP"] = 1, ["PlayerESP"] = 2, ["Chams"] = 3,
            ["Nametags"] = 4, ["HP"] = 5, ["Arrows"] = 6, ["NPCESP"] = 7,
            ["FOV"] = 8, ["Fullbright"] = 9,
            ["X-Ray"] = 10, ["Zoom"] = 11, ["Markers"] = 12,
            ["Aim Assist"] = 1,
            ["KillAura"] = 2,
            ["TriggerBot"] = 3,
            ["SilentAIM"] = 4,
            ["Gun Aimbot"] = 4,
            ["Fly"] = 1,
            ["Fling"] = 7,
            ["Noclip"] = 2,
            ["Spider"] = 3,
            ["Speed"] = 4,
            ["Jump"] = 5,
            ["Interact Extender"] = 6,
            ["Anti Void"] = 1,
            ["Teleport"] = 2,
            ["Freeze Movements"] = 3,
            ["Ghost"] = 4,
            ["Improve FPS"] = 1,
            ["Gravity"] = 2,
            ["Anti AFK"] = 3,
            ["Safe Walk"] = 4,
            ["Blurt Roles"] = 5,
            ["FreeCam"] = 6,
            ["Disguise"] = 7,
        }
        layoutOrder = ordered[name] or (100 + layoutOrder)
        local registry: any = configuration.registry or universalFeatures
        local sectionName: string = configuration.section
            or (registry == mm2Features and "MM2")
            or (registry == state.trsFeatures and "TRS")
            or (registry == state.vdFeatures and "VD")
            or (registry == state.bedFightFeatures and "BedFight")
            or (registry == state.bedWarsFeatures and "BedWars")
            or (registry == state.mvsdFeatures and "MVSD")
            or (registry == movementFeatures and "Movement")
            or "Universal"
        local configKey: string = configuration.configKey
            or (sectionName .. "." .. name:gsub("%W", ""))

        local rawCategory: any = type(configuration.categoryName) == "string"
            and configuration.categoryName
            or FEATURE_CATEGORIES[name]
            or DEFAULT_FEATURE_CATEGORY
        local categoryName: string = type(normalizeFeatureCategory) == "function"
            and normalizeFeatureCategory(rawCategory)
            or tostring(rawCategory)

        local feature: any = {
            name = name,
            description = description,
            categoryName = categoryName,
            enabled = false,
            expanded = false,

            kind = configuration.kind
                or (configuration.action == true and "action")
                or (configuration.holdAction == true and "hold")
                or (configuration.category == true and "group")
                or "toggle",
            silentAction = configuration.silentAction == true,
            searchable = configuration.searchable ~= false,
            onHold = configuration.onHold,
            optionCount = 0,
            optionRows = {},
            collapsedHeight = state.layout.cardHeight,
            onToggle = onToggle,
            configKey = configKey,
            registry = registry,
            sectionName = sectionName,
            searchText = string.lower(
                name
                    .. " "
                    .. description
                    .. " "
                    .. sectionName
                    .. " "
                    .. categoryName
            ),
            tooltipText = description,
            tooltipBound = false,
        }

        feature.isAction = feature.kind == "action"
        feature.isCategory = feature.kind == "group"
        feature.isHoldAction = feature.kind == "hold"
        feature.isAlwaysOn = feature.kind == "hold" or feature.kind == "group"

        local requestedParent: Instance? =
            configuration.parent :: any
        local fallback: Instance = (host :: any).ScreenGui or (host :: any).PopupLayer or ({} :: any)
        local rowParent: Instance = getFeatureCardParent(requestedParent or fallback)
        if type(rowParent) ~= "table" or (rowParent :: any).Children == nil then
            rowParent = fallback
        end
        local row: Frame = (create("Frame", {
            Parent = rowParent,
            Name = name:gsub("%W", "") .. "Feature",
            Active = true,
            BackgroundColor3 = state.guiStyle == "Default"
                and Theme.surface
                or Theme.background,
            BackgroundTransparency = state.guiStyle == "Default" and 0.82 or 1,
            BorderSizePixel = 0,
            ClipsDescendants = true,
            LayoutOrder = layoutOrder,
            Size = UDim2.new(1, 0, 0, feature.collapsedHeight),
        }) :: any) :: Frame
        feature.row = row

        row:SetAttribute("FeatureCategory", categoryName)
        row:SetAttribute("FeatureSortOrder", ordered[name])
        row:SetAttribute("FeatureSortName", string.lower(name))

        local bitmapText: any = state.bitmapText
        local title: TextLabel? = nil
        if bitmapText and type(bitmapText.draw) == "function" then
            feature.drawTitle = function(color: Color3?, transparency: number?): ()
                if color ~= nil then
                    feature.titleColor = color
                end
                if transparency ~= nil then
                    feature.titleTransparency = transparency
                end
                bitmapText.draw(row, {
                    {
                        text = name,
                        color = feature.titleColor or Theme.text,
                    },
                }, {
                    Name = "Title",
                    TextSize = state.layout.titleFontSize,
                    ZIndex = 7,
                    align = "Center",
                    transparency = feature.titleTransparency or 0,

                    maxWidth = 140,
                })
            end
            feature.drawTitle(Theme.text, 0)
        else
            title = (makeTextLabel(row, name, state.layout.titleFontSize) :: any) :: TextLabel
            local label: TextLabel = title :: TextLabel
            label.FontFace = CONTROL_FONT

            label.Position = UDim2.fromOffset(28, 0)
            label.Size = UDim2.new(1, -56, 0, feature.collapsedHeight)
            label.TextXAlignment = Enum.TextXAlignment.Center
            label.TextTruncate = Enum.TextTruncate.AtEnd
            label.TextColor3 = state.guiStyle == "Default"
                and Theme.text
                or Theme.text
            feature.title = label
        end

        local arrow: TextButton? = nil
        local toggleExpansion: () -> () = function(): () end

        function feature.hasOptions(): boolean
            if configuration.noOptions == true then
                return false
            end
            for _, optionRow: GuiObject in ipairs(feature.optionRows) do
                if optionRow.Visible then
                    return true
                end
            end
            return false
        end

        local function syncArrow(): ()
            local expandable: boolean = feature.hasOptions()
            feature.hasSettings = expandable
            if expandable and not arrow then
                local built: TextButton = (create("TextButton", {
                    TextTruncate = Enum.TextTruncate.AtEnd,
                    Parent = row,
                    Name = "Expand",
                    Active = true,
                    AnchorPoint = Vector2.new(1, 0),
                    AutoButtonColor = false,
                    BackgroundTransparency = 1,
                    BorderSizePixel = 0,
                    FontFace = CONTROL_FONT,
                    Position = UDim2.new(1, 0, 0, 0),
                    Size = UDim2.fromOffset(22, feature.collapsedHeight),
                    Text = "",
                    TextSize = 10,
                    ZIndex = 9,
                }) :: any) :: TextButton
                trackUiConnection(built.MouseButton1Click:Connect(function(): ()
                    toggleExpansion()
                end))
                arrow = built
                feature.arrow = built
            end
            if arrow then
                (arrow :: TextButton).Visible = expandable

                drawPixelIcon(
                    arrow :: TextButton,
                    feature.expanded and "up" or "down",
                    nil,
                    "arrows"
                )
            end
        end
        feature.syncArrow = syncArrow
        -- Palette changes must repaint the expand arrows immediately. The
        -- per-pixel theme binding covers this too, but the arrow icon is
        -- destroyed and rebuilt on every expansion toggle, and a redraw hook
        -- guarantees the chosen colour lands on every copy ("tengo que
        -- tocarlas para que se aplica el color").
        if state and type(state.registerThemeRefresh) == "function" then
            state.registerThemeRefresh(function(): ()
                if row.Parent and arrow then
                    syncArrow()
                end
            end, {"arrows"})
        end

        local activationTarget: TextButton = create("TextButton", {
            TextTruncate = Enum.TextTruncate.AtEnd,
            ClipsDescendants = true,
            Parent = row,
            Name = "ActivationTarget",
            Active = true,
            AutoButtonColor = false,
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            Position = UDim2.fromOffset(0, 0),
            Size = UDim2.new(1, 0, 0, feature.collapsedHeight),
            Text = "",
            ZIndex = 6,
        }) :: TextButton
        feature.activationTarget = activationTarget
        if title then
            (title :: TextLabel).ZIndex = 7
        end

        trackUiConnection(row.MouseEnter:Connect(function(): ()
            state.applyCardSkin(feature, true)
        end))
        trackUiConnection(row.MouseLeave:Connect(function(): ()
            state.applyCardSkin(feature, false)
        end))

        local options: Frame = (create("Frame", {
            Parent = row,
            Name = "Options",
            Active = true,
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            Position = UDim2.fromOffset(4, feature.collapsedHeight),
            Size = UDim2.new(1, -8, 0, 0),
            Visible = false,
            ZIndex = row.ZIndex + 10,
        }) :: any) :: Frame
        feature.options = options
        create("UIPadding", {
            Parent = options,
            PaddingBottom = UDim.new(0, 4),
            PaddingLeft = UDim.new(0, 0),
            PaddingRight = UDim.new(0, 0),
            PaddingTop = UDim.new(0, 4),
        })
        local optionsLayout: UIListLayout = (create("UIListLayout", {
            Parent = options,
            FillDirection = Enum.FillDirection.Vertical,
            HorizontalAlignment = Enum.HorizontalAlignment.Center,
            Padding = UDim.new(0, 4),
            SortOrder = Enum.SortOrder.LayoutOrder,
        }) :: any) :: UIListLayout

        local function updateExpandedSize(_animate: boolean?): ()

            local visibleOptions: number = 0
            local declaredHeight: number = 0
            for _, optionRow: GuiObject in ipairs(feature.optionRows) do
                if optionRow.Visible then
                    visibleOptions += 1
                    declaredHeight += optionRow.Size.Y.Offset
                end
            end
            local expectedHeight: number = if visibleOptions > 0
                then declaredHeight + math.max(0, visibleOptions - 1) * 4
                else 0
            local measuredHeight: number = math.max(
                optionsLayout.AbsoluteContentSize.Y,
                expectedHeight
            )
            local singleOptionExtra: number = if visibleOptions == 1 then 8 else 0

            local optionsHeight: number = measuredHeight + 8 + singleOptionExtra
            feature.optionsHeight = optionsHeight
            options.Size = UDim2.new(1, 0, 0, optionsHeight)
            syncArrow()
            local settingsWindow: any = feature.settingsWindow
            if settingsWindow and settingsWindow.resizeToOptions then
                settingsWindow.resizeToOptions()
            end
        end
        feature.updateExpandedSize = updateExpandedSize
        trackUiConnection(
            optionsLayout:GetPropertyChangedSignal("AbsoluteContentSize")
                :Connect(function(): ()
                    updateExpandedSize(false)
                end)
        )

        toggleExpansion = function(): ()
            if not feature.hasOptions() then

                syncArrow()
                return
            end

            local windows: any = state.windows
            if windows and type(windows.OpenFeatureSettings) == "function" then
                -- Pressing the arrow again closes the options window (the
                -- same path as the window's X button), so the arrows are a
                -- real open/close toggle.
                local window: any = feature.settingsWindow
                if window
                    and window.root
                    and window.root.Visible == true then
                    window.root.Visible = false
                    feature.expanded = false
                    if feature.syncArrow then
                        feature.syncArrow()
                    end
                    return
                end
                windows.OpenFeatureSettings(feature)
            end
        end
        feature.toggleExpansion = toggleExpansion

        function feature.setHeld(held: boolean): ()
            if feature.held == held then
                return
            end
            feature.held = held
            local handler: any = feature.onHold
            if type(handler) ~= "function" then
                return
            end
            local ok: boolean, failure: any = pcall(handler, held)
            if not ok then
                warn("[Random Testing Menu] " .. name .. ": " .. tostring(failure))
                return
            end
            feature.active = held
            refreshFeatureToggle(feature)
        end

        local function activateFeature(): ()
            if feature.isHoldAction then

                return
            end
            if feature.isCategory then
                if not feature.hasOptions() then
                    return
                end
                feature.expanded = not feature.expanded
                updateExpandedSize(true)
                return
            end
            if feature.isAction then
                if feature.actionRunning then
                    return
                end
                feature.actionRunning = true
                task.spawn(function(): ()
                    local success: boolean, errorMessage: any = pcall(feature.onToggle)
                    feature.actionRunning = false
                    if not success then
                        warn("[Random Testing Menu] " .. name .. ": " .. tostring(errorMessage))
                        notify("Could not run " .. name)
                    end
                end)
                return
            end

            local requestedState: boolean = not feature.enabled
            local success: boolean, errorMessage: any = pcall(
                feature.onToggle,
                requestedState
            )
            if success then
                feature.enabled = requestedState
                if requestedState then
                    feature.enabledAt = os.clock()
                end
                configData.states[feature.configKey] = requestedState
                flushConfigSave()
            else
                warn("[Random Testing Menu] " .. name .. ": " .. tostring(errorMessage))
                feature.enabled = false
                pcall(feature.onToggle, false)
                local reason: string = tostring(errorMessage)
                if #reason > 90 then
                    reason = string.sub(reason, 1, 90)
                end
                notify("Could not toggle " .. name .. ": " .. reason)
            end
            refreshFeatureToggle(feature)
        end
        feature.activate = activateFeature

        state.applyCardSkin(feature, false)
        if feature.isAction then

            trackUiConnection(activationTarget.MouseButton1Down:Connect(function(): ()
                if feature.row then
                    (feature.row :: Frame).BackgroundTransparency = 0.46
                end
            end))
            trackUiConnection(activationTarget.MouseButton1Up:Connect(function(): ()
                state.applyCardSkin(feature, true)
            end))
        end

        trackUiConnection(activationTarget.MouseButton1Click:Connect(activateFeature))

        trackUiConnection(activationTarget.InputBegan:Connect(function(input: InputObject): ()
            if input.UserInputType == Enum.UserInputType.MouseButton2 then
                toggleExpansion()
            end
        end))

        local shortcutButton: TextButton? = nil
        if state.isMobile then
            local slot: TextButton =
                (makeButton(row, "KEY", 9) :: any) :: TextButton
            slot.Name = "Shortcut"

            slot.AnchorPoint = Vector2.new(0, 0.5)
            slot.Position = UDim2.new(0, 4, 0, feature.collapsedHeight / 2)
            slot.Size = UDim2.fromOffset(22, 22)
            slot.ZIndex = 9
            applyKeySlotStyle(slot)
            slot.TextScaled = true
            create("UITextSizeConstraint", {
                Parent = slot,
                MaxTextSize = 11,
                MinTextSize = 7,
            })
            shortcutButton = slot
        end
        feature.shortcutButton = shortcutButton
        if feature.kind == "group" then

            if shortcutButton then
                (shortcutButton :: TextButton).Visible = false
            end
        elseif feature.kind == "hold" then

            bindActionShortcut(
                shortcutButton,
                feature.configKey,
                name,
                function(): () end,
                {
                    hold = true,
                    onPress = function(): ()
                        feature.setHeld(true)
                    end,
                    onRelease = function(): ()
                        feature.setHeld(false)
                    end,
                }
            )
        else
            bindActionShortcut(
                shortcutButton,
                feature.configKey,
                name,
                activateFeature
            )
        end

        -- Mobile: the little square is not a key slot, it is the touch button
        -- for this feature. It previews the configured shape and colour, "+"
        -- when the button does not exist yet, and opens the editor on tap.
        if state.isMobile and shortcutButton and state.mobileUi then
            local slot: TextButton = shortcutButton :: TextButton
            local mobileUi: any = state.mobileUi
            local actionId: string = mobileUi.actionId(feature.configKey)
            local function syncMobileSlot(): ()
                local action: any = mobileUi.actions[actionId]
                local corner: UICorner? = slot:FindFirstChildOfClass("UICorner")
                if action then
                    slot.Text = ""
                    slot.BackgroundColor3 = mobileUi.colorFromHex(action.color)
                        or Theme.surfaceRaised
                    slot.BackgroundTransparency = 0.12
                    if corner then
                        corner.CornerRadius = action.shape == "Circle"
                            and UDim.new(1, 0)
                            or action.shape == "Rounded"
                                and UDim.new(0, 10)
                                or UDim.new(0, 2)
                    end
                else
                    slot.Text = "+"
                    slot.BackgroundColor3 = Theme.surfaceRaised
                    slot.BackgroundTransparency = 0.35
                    if corner then corner.CornerRadius = UDim.new(0, 6) end
                end
            end
            syncMobileSlot()
            if type(mobileUi.onChanged) == "function" then
                mobileUi.onChanged(syncMobileSlot)
            end
            local binding: any = state.shortcutBindings
                and state.shortcutBindings[feature.configKey]
            if binding then
                local previous: any = binding.refresh
                binding.refresh = function(): ()
                    if type(previous) == "function" then previous() end
                    syncMobileSlot()
                end
            end
        end

        if (feature.kind == "toggle"
                or feature.kind == "action"
                or feature.kind == "hold")
            and not state.isMobile
            and type(beginKeyCapture) == "function"
            and type(state.shortcutBindings) == "table"
            and state.shortcutBindings[feature.configKey] ~= nil then
            local binding: any = state.shortcutBindings[feature.configKey]
            local UNBOUND_BG: Color3 = Color3.fromRGB(0, 0, 0)
            local square: TextButton = (create("TextButton", {
                TextTruncate = Enum.TextTruncate.AtEnd,
                Parent = row,
                Name = "BindSquare",
                Active = true,
                AnchorPoint = Vector2.new(0, 0.5),
                AutoButtonColor = false,
                BackgroundColor3 = UNBOUND_BG,
                BackgroundTransparency = 0.55,
                BorderSizePixel = 0,
                FontFace = CONTROL_FONT,
                Position = UDim2.new(0, 4, 0.5, 0),
                Size = UDim2.fromOffset(18, 18),
                Text = "",
                TextColor3 = Theme.text,
                TextTransparency = 0,
                TextSize = 8,
                ZIndex = 8,
            }) :: any) :: TextButton
            square:SetAttribute("CaptureIdleText", "")
            local edge: UIStroke = (create("UIStroke", {
                Parent = square,
                Name = "StyleStroke",
                Color = Theme.outline,
                Thickness = 1,
                Transparency = 0.6,
            }) :: any) :: UIStroke

            local COMPACT_KEY_NAMES: {[string]: string} = {
                LeftShift = "LS",
                RightShift = "RS",
                LeftControl = "LC",
                RightControl = "RC",
                LeftAlt = "LA",
                RightAlt = "RA",
                CapsLock = "CL",
                Backspace = "Bk",
                Return = "En",
                Escape = "Es",
                Space = "Sp",
                PageUp = "PU",
                PageDown = "PD",
                Insert = "Ins",
                Delete = "Del",
                Home = "Hm",
                End = "End",
            }
            local function keyCaption(): string
                if binding.key == nil or binding.key == Enum.KeyCode.Unknown then
                    return ""
                end
                local name: string = tostring(binding.key.Name or "")
                local compact: string? = COMPACT_KEY_NAMES[name]
                if compact then
                    return compact
                end
                local display: string = state.keyDisplayName
                        and tostring(state.keyDisplayName(name))
                    or name
                return string.sub(display, 1, 3)
            end

            local capturing: boolean = false
            local function conflictWith(): any
                if binding.key == nil or binding.key == Enum.KeyCode.Unknown then
                    return nil
                end
                for _, other: any in pairs(state.shortcutBindings) do
                    if other ~= binding and other.key == binding.key then
                        return other
                    end
                end
                return nil
            end
            local function syncSquare(): ()
                if capturing then
                    return
                end
                local caption: string = keyCaption()
                square.Text = caption
                square:SetAttribute("CaptureIdleText", caption)
                local bound: boolean = binding.key ~= nil
                    and binding.key ~= Enum.KeyCode.Unknown
                -- Palette-driven: a bound key paints with the Enabled
                -- colour, a conflicting one with the negative colour, so the
                -- squares match whatever the user picked in UI Settings.
                local conflict: any = bound and conflictWith() or nil
                if conflict then
                    square.BackgroundColor3 = Theme.negative
                    square.BackgroundTransparency = 0.35
                    edge.Color = Theme.negative
                    edge.Transparency = 0.15
                elseif bound then
                    square.BackgroundColor3 = Theme.enabled
                    square.BackgroundTransparency = 0.35
                    edge.Color = Theme.enabled
                    edge.Transparency = 0.25
                else
                    square.BackgroundColor3 = UNBOUND_BG
                    square.BackgroundTransparency = 0.55
                    edge.Color = Theme.outline
                    edge.Transparency = 0.6
                end
            end
            feature.bindSquare = square
            feature.syncBindSquare = syncSquare
            if state.registerThemeRefresh then
                state.registerThemeRefresh(function(): ()
                    if square.Parent then
                        syncSquare()
                    end
                end, {"enabled", "outline"})
            end
            local refreshBinding: any = binding.refresh
            binding.refresh = function(): ()
                if refreshBinding then
                    refreshBinding()
                end
                syncSquare()
            end
            syncSquare()

            local function syncKeyboard(): ()
                square.Visible = UserInputService == nil
                    or UserInputService.KeyboardEnabled ~= false
            end
            syncKeyboard()
            pcall(function(): ()
                trackUiConnection(
                    UserInputService:GetPropertyChangedSignal("KeyboardEnabled")
                        :Connect(syncKeyboard)
                )
            end)

            local function tipText(): string
                local bound: boolean = binding.key ~= nil
                    and binding.key ~= Enum.KeyCode.Unknown
                if not bound then
                    return "Bind: click, then press a key"
                end
                local conflict: any = conflictWith()
                if conflict then
                    return binding.key.Name .. " — also bound to "
                        .. tostring(conflict.id)
                end
                return "Bound: " .. binding.key.Name
            end
            trackUiConnection(square.MouseEnter:Connect(function(): ()
                local tooltip: any = state.featureTooltip
                if not tooltip then
                    return
                end
                state.tooltipToken = (state.tooltipToken or 0) + 1
                local token: number = state.tooltipToken
                task.delay(0.4, function(): ()
                    if state.tooltipToken ~= token or not square.Parent then
                        return
                    end
                    local rawText: string = tipText()
                    local bitmap: any = state.bitmapText
                    local measured: number = bitmap
                            and type(bitmap.measure) == "function"
                            and tonumber(bitmap.measure({{text = rawText}}, 16))
                        or #rawText * 8
                    local width: number = math.clamp(measured + 24, 140, 360)
                    local wrapped: string = rawText
                    local lines: number = 1
                    if bitmap and type(bitmap.wrap) == "function" then
                        wrapped, lines = bitmap.wrap(rawText, width - 24, 16)
                    end
                    tooltip.Text = wrapped
                    tooltip.TextTransparency = 1
                    tooltip.Size = UDim2.fromOffset(width, math.max(30, lines * 18 + 12))
                    tooltip.Position = UDim2.fromOffset(
                        square.AbsolutePosition.X,
                        square.AbsolutePosition.Y + square.AbsoluteSize.Y + 8
                    )
                    if state.bitmapText and type(state.bitmapText.draw) == "function" then
                        state.bitmapText.draw(tooltip, {
                            {text = tooltip.Text},
                        }, {
                            Name = "Glyphs",
                            TextSize = 16,
                            maxWidth = width - 24,
                            ellipsis = true,
                            ZIndex = 251,
                        })
                    end
                    tooltip.Visible = true
                end)
            end))
            trackUiConnection(square.MouseLeave:Connect(function(): ()
                state.tooltipToken = (state.tooltipToken or 0) + 1
                if state.featureTooltip then
                    state.featureTooltip.Visible = false
                end
            end))

            local outsideConnection: RBXScriptConnection? = nil
            local function cleanupCapture(): ()
                capturing = false
                if outsideConnection then
                    pcall(function(): ()
                        (outsideConnection :: RBXScriptConnection):Disconnect()
                    end)
                    outsideConnection = nil
                end
                syncSquare()

                task.delay(0.2, function(): ()
                    if square.Parent and not capturing then
                        syncSquare()
                    end
                end)
            end
            trackUiConnection(square.MouseButton1Click:Connect(function(): ()
                if capturing then

                    if state.keyCaptureCancel then
                        state.keyCaptureCancel()
                    else
                        cleanupCapture()
                    end
                    return
                end
                capturing = true
                beginKeyCapture(square, function(keyCode: Enum.KeyCode): ()

                    local backspaceKey: any = (Enum.KeyCode :: any).Backspace
                    local deleteKey: any = (Enum.KeyCode :: any).Delete
                    if keyCode == backspaceKey or keyCode == deleteKey then
                        if binding.key ~= Enum.KeyCode.Unknown
                            and type(binding.assign) == "function" then
                            binding.assign(binding.key)
                        end
                    elseif type(binding.assign) == "function" then
                        binding.assign(keyCode)
                    end
                    cleanupCapture()
                end)

                local baseCancel: any = state.keyCaptureCancel
                state.keyCaptureCancel = function(): ()
                    if baseCancel then
                        baseCancel()
                    end
                    cleanupCapture()
                end

                pcall(function(): ()
                    outsideConnection = UserInputService.InputBegan:Connect(function(
                        input: InputObject
                    ): ()
                        if input.UserInputType ~= Enum.UserInputType.MouseButton1
                            and input.UserInputType ~= Enum.UserInputType.Touch then
                            return
                        end
                        local px: number = input.Position.X
                        local py: number = input.Position.Y
                        local ax: number = square.AbsolutePosition.X
                        local ay: number = square.AbsolutePosition.Y
                        if px < ax or px > ax + square.AbsoluteSize.X
                            or py < ay or py > ay + square.AbsoluteSize.Y then
                            if state.keyCaptureCancel then
                                state.keyCaptureCancel()
                            end
                        end
                    end)
                end)
            end))
        end

        feature.applyLayout = function(): ()
            local metrics: LayoutMetrics = state.layout
            feature.collapsedHeight = metrics.cardHeight
            if title then
                state.setTextMetric(title, metrics.titleFontSize)
            elseif feature.drawTitle then

                feature.drawTitle(nil, nil)
            end
            if arrow then
                (arrow :: TextButton).Size =
                    UDim2.fromOffset(22, metrics.cardHeight)
            end
            if shortcutButton then
                (shortcutButton :: TextButton).Size = UDim2.fromOffset(22, 22);
                (shortcutButton :: TextButton).Position =
                    UDim2.new(0, 4, 0, metrics.cardHeight / 2)
            end
            activationTarget.Size = UDim2.new(1, 0, 0, metrics.cardHeight)
            options.Position = UDim2.fromOffset(4, metrics.cardHeight)
            syncArrow()
            updateExpandedSize(false)
        end

        feature.applyLayout()

        function feature:SetStatus(status: string?): ()
            feature.status = status
        end

        registry[name] = feature
        table.insert(allFeatures, feature)

        if state.floatingUi then
            state.floatingUi.registerFeature(feature)
        end

        if state.clickGui then
            state.clickGui.place(feature)
        end
        applyFeaturePresentation(feature, state.guiStyle == "Default")

        if type(addFeatureTooltip) == "function" and description ~= "" then
            addFeatureTooltip(feature, description)
        end

        local search: any = state.moduleSearch
        if search and type(search.Register) == "function" then
            search.Register(feature)
            table.insert(registeredSearchFeatures, feature)
        end

        if feature.isAlwaysOn then
            task.defer(function(): ()
                local ok: boolean, failure: any = pcall(feature.onToggle, true)
                if not ok then
                    warn("[Random Testing Menu] " .. name .. ": " .. tostring(failure))
                end
            end)
        end

        if not feature.isAction
            and not feature.isCategory
            and not feature.isHoldAction
            and configuration.restore ~= false
            and configData.states[feature.configKey] == true then
            task.defer(function(): ()
                local success: boolean, errorMessage: any = pcall(
                    feature.onToggle,
                    true
                )
                if success then
                    feature.enabled = true
                    feature.enabledAt = os.clock()
                    refreshFeatureToggle(feature)
                else
                    configData.states[feature.configKey] = false
                    queueConfigSave()
                    warn(
                        "[Random Testing Menu] Could not restore "
                            .. name
                            .. ": "
                            .. tostring(errorMessage)
                    )
                end
            end)
        end
        return feature
    end

    moduleCleanup = function(): ()
        local search: any = state.moduleSearch
        if search and type(search.Unregister) == "function" then
            for _, feature: any in ipairs(registeredSearchFeatures) do
                search.Unregister(feature)
            end
        end
        table.clear(registeredSearchFeatures)
    end
    Module.Initialized = true
    return {createUniversalFeature = createUniversalFeature}
end

function Module.destroy(): ()
    moduleCleanup()
    moduleCleanup = function(): () end
    Module.Initialized = false
end

return Module

]],
        ["src/guis/Wurst/Code/ClickGui.lua"] = [[
export type CategoryWindow = {
    name: string,
    window: any,
    layout: UIListLayout,
    count: number,
}

local Module = {
    Name = "ClickGui",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local activeCleanup: (() -> ())? = nil

local WINDOW_WIDTH: number = 200
local WINDOW_MAX_HEIGHT: number = 300

local SCALE_MINIMUM: number = 0.7
local SCALE_MAXIMUM: number = 1.6

local CALIBRATION_WIDTH: number = 1600
local CALIBRATION_HEIGHT: number = 900
local GRID_MARGIN: number = 10
local WINDOW_GAP: number = 2

local GRID_GAP: number = 10
local TITLE_HEIGHT: number = 26

local CATEGORY_ORDER: {string} = {
    "Combat", "Exploits", "Utilities", "World", "Render", "Blocks", "Items",
}
local CATEGORY_ALIASES: {[string]: string} = {
    Blatant = "Exploits", Movement = "World", Other = "Utilities",
    Fun = "Utilities", Visuals = "Render", Protection = "Utilities",
    Utility = "Utilities", Spoof = "Utilities", General = "Utilities", Player = "World",
}

local function fallbackNormalize(raw: any): string
    local name: string = tostring(raw or "Utilities")
    if table.find(CATEGORY_ORDER, name) ~= nil then
        return name
    end
    return CATEGORY_ALIASES[name] or "Utilities"
end

function Module.init(context: any): any
    local host: any = context
    local state: any = host.state
    local create: any = host.create
    local allFeatures: {any} = host.allFeatures
    local normalizeFeatureCategory: any = host.normalizeFeatureCategory

    local function viewportScale(): number
        local shape: any = host.ThemeEngine and host.ThemeEngine.shape
        local wanted: number = shape and tonumber(shape.scale) or 1
        local camera: Camera? = workspace.CurrentCamera
        local viewport: Vector2 = camera
            and (camera :: Camera).ViewportSize
            or Vector2.new(CALIBRATION_WIDTH, CALIBRATION_HEIGHT)
        local fit: number = math.min(
            viewport.X / CALIBRATION_WIDTH,
            viewport.Y / CALIBRATION_HEIGHT
        )
        return math.clamp(wanted * fit, SCALE_MINIMUM, SCALE_MAXIMUM)
    end

    local function logicalViewport(): Vector2
        local camera: Camera? = workspace.CurrentCamera
        local viewport: Vector2 = camera
            and (camera :: Camera).ViewportSize
            or Vector2.new(CALIBRATION_WIDTH, CALIBRATION_HEIGHT)
        local factor: number = viewportScale()
        return Vector2.new(viewport.X / factor, viewport.Y / factor)
    end

    local windows: any = state.windows
    if not windows then

        error("ClickGui requires the window manager")
    end

    local ClickGui: any = {
        categories = {} :: {[string]: CategoryWindow},
        order = {} :: {string},

        connections = {} :: {RBXScriptConnection},
    }

    local productVersion: string = tostring(
        (host.PRODUCT and host.PRODUCT.version) or "0.1 Beta"
    )
    local LOGO_CHIP_WIDTH: number = 142 + 10 + (8 + #productVersion * 15) + 4
    local LOGO_CHIP_HEIGHT: number = 44
    local TOP_ROW_X: number = 14 + LOGO_CHIP_WIDTH + GRID_GAP
    local TOP_ROW_Y: number = 10
    local nextX: number = TOP_ROW_X
    local nextY: number = TOP_ROW_Y
    local rowHeight: number = LOGO_CHIP_HEIGHT

    local function nextSlot(height: number): Vector2
        local viewport: Vector2 = logicalViewport()
        if nextX + WINDOW_WIDTH > viewport.X - GRID_MARGIN then
            nextX = GRID_MARGIN
            nextY += rowHeight + GRID_GAP
            rowHeight = 0
        end
        local slot: Vector2 = Vector2.new(nextX, nextY)
        nextX += WINDOW_WIDTH + GRID_GAP
        rowHeight = math.max(rowHeight, height)
        return slot
    end

    local function categoryWindow(name: string): CategoryWindow
        local existing: CategoryWindow? = ClickGui.categories[name]
        if existing then
            return existing :: CategoryWindow
        end

        local height: number = TITLE_HEIGHT + 8
        local window: any = windows.Create({
            id = "ClickGui_" .. name,
            title = name,
            size = Vector2.new(WINDOW_WIDTH, height),
            position = nextSlot(WINDOW_MAX_HEIGHT * 0.5),
            maxHeight = WINDOW_MAX_HEIGHT,

            closable = false,
        })

        local layout: UIListLayout = create("UIListLayout", {
            Parent = window.body,
            Padding = UDim.new(0, WINDOW_GAP),
            SortOrder = Enum.SortOrder.LayoutOrder,
        }) :: UIListLayout
        create("UIPadding", {
            Parent = window.body,
            PaddingTop = UDim.new(0, WINDOW_GAP),
            PaddingBottom = UDim.new(0, WINDOW_GAP),
            PaddingLeft = UDim.new(0, WINDOW_GAP),
            PaddingRight = UDim.new(0, WINDOW_GAP),
        })

        local record: CategoryWindow = {
            name = name,
            window = window,
            layout = layout,
            count = 0,
        }
        ClickGui.categories[name] = record
        table.insert(ClickGui.order, name)
        table.sort(ClickGui.order, function(left: string, right: string): boolean
            local leftRank: number = table.find(CATEGORY_ORDER, left) or math.huge
            local rightRank: number = table.find(CATEGORY_ORDER, right) or math.huge
            if leftRank == rightRank then
                return left < right
            end
            return leftRank < rightRank
        end)

        local function resize(): ()

            local limit: number = tonumber(state.uiMaxHeight) or WINDOW_MAX_HEIGHT
            if limit <= 0 then
                limit = math.huge
            end

            limit = math.min(limit, logicalViewport().Y - 12)

            local declaredHeight: number = 0
            local visibleRows: number = 0
            for _, child: Instance in ipairs(window.body:GetChildren()) do
                if child:IsA("GuiObject") and (child :: GuiObject).Visible then
                    visibleRows += 1
                    declaredHeight += (child :: GuiObject).Size.Y.Offset
                end
            end
            declaredHeight += math.max(visibleRows - 1, 0) * WINDOW_GAP
            local contentHeight: number = math.max(
                layout.AbsoluteContentSize.Y,
                declaredHeight
            )
            local wanted: number = math.min(
                TITLE_HEIGHT + contentHeight + 4,
                limit
            )
            window.fullHeight = wanted
            if not window.collapsed then
                window.root.Size = UDim2.fromOffset(WINDOW_WIDTH, wanted)
            end

            if windows.ClampWindow then
                windows.ClampWindow(window)
            end
        end
        table.insert(
            ClickGui.connections,
            layout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(resize)
        )
        resize()
        record.resize = resize :: any
        return record
    end

    local function sortCategoryRows(record: CategoryWindow): ()
        local rows: {GuiObject} = {}
        for _, child: Instance in ipairs(record.window.body:GetChildren()) do
            if not child:IsA("GuiObject") then
                continue
            end
            local key: any = child:GetAttribute("FeatureSortName")
            if type(key) == "string" then
                table.insert(rows, child :: GuiObject)
            end
        end
        table.sort(rows, function(left: GuiObject, right: GuiObject): boolean
            local leftOrder: number = tonumber(left:GetAttribute("FeatureSortOrder")) or math.huge
            local rightOrder: number = tonumber(right:GetAttribute("FeatureSortOrder")) or math.huge
            if leftOrder ~= rightOrder then return leftOrder < rightOrder end
            local leftKey: string = tostring(left:GetAttribute("FeatureSortName") or "")
            local rightKey: string = tostring(right:GetAttribute("FeatureSortName") or "")
            if leftKey == rightKey then
                return left.Name < right.Name
            end
            return leftKey < rightKey
        end)
        for index: number, row: GuiObject in ipairs(rows) do
            row.LayoutOrder = index
        end
    end

    function ClickGui.place(feature: any): ()
        local row: Frame? = feature and feature.row
        if not row then
            return
        end

        local raw: any = (row :: Frame):GetAttribute("FeatureCategory")
        local name: string = type(normalizeFeatureCategory) == "function"
            and normalizeFeatureCategory(raw)
            or fallbackNormalize(raw)
        local record: CategoryWindow = categoryWindow(name)
        record.count += 1;
        (row :: Frame).Parent = record.window.body;
        (row :: Frame).Size = UDim2.new(1, 0, 0, feature.collapsedHeight or 22)
        sortCategoryRows(record)
        if record.resize then
            (record.resize :: () -> ())()
        end
        local userMoved: boolean = false
        for _, category: string in ipairs(ClickGui.order) do
            local candidate: CategoryWindow? = ClickGui.categories[category]
            if candidate and candidate.window.userMoved == true then
                userMoved = true
                break
            end
        end
        if not userMoved and type(ClickGui.Retile) == "function" then
            ClickGui.Retile()
        end
    end

    function ClickGui.Retile(): ()

        nextX = TOP_ROW_X
        nextY = TOP_ROW_Y
        rowHeight = LOGO_CHIP_HEIGHT
        for _, name: string in ipairs(ClickGui.order) do
            local record: CategoryWindow = ClickGui.categories[name]
            if record then
                local slot: Vector2 = nextSlot(
                    record.window.fullHeight or WINDOW_MAX_HEIGHT * 0.5
                )
                record.window.root.Position = UDim2.fromOffset(slot.X, slot.Y)
                if type(windows.ClampWindow) == "function" then
                    windows.ClampWindow(record.window)
                end
            end
        end
    end

    function ClickGui.RefreshHeights(): ()
        for _, name: string in ipairs(ClickGui.order) do
            local record: CategoryWindow = ClickGui.categories[name]
            if record and record.resize then
                (record.resize :: () -> ())()
            end
        end
    end

    function ClickGui.SetVisible(visible: boolean): ()
        for _, name: string in ipairs(ClickGui.order) do
            local record: CategoryWindow = ClickGui.categories[name]

            if not visible and record.window.pinned then
                continue
            end
            record.window:SetVisible(visible and record.window.userVisible ~= false)
        end
    end

    local function resolvedCategory(feature: any): string
        local row: any = feature and feature.row
        local raw: any = row and row:GetAttribute("FeatureCategory")
        if type(normalizeFeatureCategory) == "function" then
            return normalizeFeatureCategory(raw)
        end
        return fallbackNormalize(raw)
    end
    for _, name: string in ipairs(CATEGORY_ORDER) do
        for _, feature: any in ipairs(allFeatures) do
            if resolvedCategory(feature) == name then
                categoryWindow(name)
                break
            end
        end
    end

    for _, feature: any in ipairs(allFeatures) do
        ClickGui.place(feature)
    end

    local scale: UIScale = create("UIScale", {
        Parent = host.PopupLayer,
        Name = "ClickGuiScale",
        Scale = viewportScale(),
    }) :: UIScale

    state.onLayout(function(): ()
        scale.Scale = viewportScale()
        ClickGui.RefreshHeights()
    end)
    ClickGui.scale = scale

    state.clickGui = ClickGui
    state.addMenuVisibilityListener(function(visible: boolean): ()
        ClickGui.SetVisible(visible)
    end)
    ClickGui.SetVisible(state.visible == true)

    activeCleanup = function(): ()
        for _, name: string in ipairs(ClickGui.order) do
            local record: CategoryWindow? = ClickGui.categories[name]
            if record then
                pcall(function(): ()
                    (record :: CategoryWindow).window:Destroy()
                end)
            end
        end
        for _, connection: RBXScriptConnection in ipairs(ClickGui.connections) do
            pcall(function(): ()
                connection:Disconnect()
            end)
        end
        ClickGui.connections = {}
        ClickGui.categories = {}
        ClickGui.order = {}
        state.clickGui = nil
    end
    Module.Initialized = true
    return ClickGui
end

function Module.destroy(): ()
    if activeCleanup then
        pcall(activeCleanup)
    end
    activeCleanup = nil
    Module.Initialized = false
end

return Module

]],
        ["src/guis/Wurst/Code/FloatingWindows.lua"] = [[
export type FloatingWindowRecord = {
    id: string,
    root: Frame,
    body: Frame,
    closeButton: TextButton,
}

local activeCleanup: (() -> ())? = nil

local Module = {
    Name = "FloatingWindows",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

function Module.init(context: any): any
    local host: any = context
    local state: any = host.state
    local configData: any = host.configData
    local queueConfigSave: any = host.queueConfigSave
    local create: any = host.create
    local makeButton: any = host.makeButton
    local makeTextBox: any = host.makeTextBox
    local makeTextLabel: any = host.makeTextLabel
    local Theme: any = host.Theme
    local ThemeEngine: any = host.ThemeEngine
    local CONTROL_FONT: any = host.CONTROL_FONT
    local THIN_FONT: any = host.THIN_FONT
    local VALVE_FONT: any = host.VALVE_FONT
    local PopupLayer: any = host.PopupLayer
    local UI_RADIUS: any = host.UI_RADIUS
    local cornerRadius: any = host.cornerRadius
    local trackUiConnection: any = host.trackUiConnection
    local createToggleSwitch: any = host.createToggleSwitch
    local setToggleSwitch: any = host.setToggleSwitch
    local TweenService: any = host.TweenService
    local UserInputService: any = host.UserInputService
    local Players: any = host.Players
    local LocalPlayer: any = host.LocalPlayer
    local Stats: any = host.Stats
    local TaskManager: any = host.TaskManager
    local allFeatures: any = host.allFeatures

    local function bind(instance: Instance, property: string, token: string): ()
        if ThemeEngine and type(ThemeEngine.Bind) == "function" then
            ThemeEngine.Bind(instance, property, token)
        else
            (instance :: any)[property] = Theme[token]
        end
    end

    local ownedTasks: {any} = {}

    local FloatingUi: any = {
        favorites = {},
        favoriteRows = {},
        overlays = {},
        featureRows = {},
        windows = {},
    }
    state.floatingUi = FloatingUi

    if type(configData.ui.favorites) ~= "table" then
        configData.ui.favorites = {}
    end
    if type(configData.ui.overlays) ~= "table" then
        configData.ui.overlays = {}
    end
    if type(configData.ui.floatingPositions) ~= "table" then
        configData.ui.floatingPositions = {}
    end
    if type(configData.ui.overlaySettings) ~= "table" then
        configData.ui.overlaySettings = {}
    end
    local overlaySettings: any = configData.ui.overlaySettings
    overlaySettings.TextGUI = type(overlaySettings.TextGUI) == "table"
        and overlaySettings.TextGUI
        or {}
    overlaySettings.SessionInfo = type(overlaySettings.SessionInfo) == "table"
        and overlaySettings.SessionInfo
        or {}
    overlaySettings.TargetInfo = type(overlaySettings.TargetInfo) == "table"
        and overlaySettings.TargetInfo
        or {}
    overlaySettings.Radar = type(overlaySettings.Radar) == "table"
        and overlaySettings.Radar
        or {}
    local textGuiSettings: any = overlaySettings.TextGUI
    textGuiSettings.sort = textGuiSettings.sort or "Alphabetical"
    textGuiSettings.font = textGuiSettings.font or "Builder Sans"
    textGuiSettings.colorMode = textGuiSettings.colorMode or "Match GUI"
    textGuiSettings.scale = math.clamp(tonumber(textGuiSettings.scale) or 1, 0.75, 2)
    textGuiSettings.shadow = textGuiSettings.shadow ~= false
    textGuiSettings.gradient = textGuiSettings.gradient == true
    textGuiSettings.v4Gradient = textGuiSettings.v4Gradient == true
    textGuiSettings.animations = textGuiSettings.animations ~= false
    textGuiSettings.watermark = textGuiSettings.watermark == true
    textGuiSettings.background = textGuiSettings.background == true
    textGuiSettings.hideModules = textGuiSettings.hideModules == true
    textGuiSettings.hideRender = textGuiSettings.hideRender == true
    textGuiSettings.customText = tostring(textGuiSettings.customText or "")
    local sessionSettings: any = overlaySettings.SessionInfo
    sessionSettings.showPerformance = sessionSettings.showPerformance ~= false
    sessionSettings.showServer = sessionSettings.showServer ~= false
    sessionSettings.showRole = sessionSettings.showRole ~= false
    sessionSettings.showDeaths = sessionSettings.showDeaths ~= false
    sessionSettings.showWins = sessionSettings.showWins ~= false
    local targetSettings: any = overlaySettings.TargetInfo
    targetSettings.mode = targetSettings.mode or "Smart Priority"
    targetSettings.showAvatar = targetSettings.showAvatar ~= false
    targetSettings.showHealth = targetSettings.showHealth ~= false
    targetSettings.showDistance = targetSettings.showDistance ~= false
    local radarSettings: any = overlaySettings.Radar
    radarSettings.range = math.clamp(tonumber(radarSettings.range) or 250, 25, 2000)
    radarSettings.size = math.clamp(tonumber(radarSettings.size) or 190, 140, 280)
    radarSettings.rotation = radarSettings.rotation or "Camera"
    radarSettings.colorMode = radarSettings.colorMode or "Smart"
    radarSettings.outOfRange = radarSettings.outOfRange or "Clamp"
    radarSettings.showNames = radarSettings.showNames == true
    radarSettings.showDistance = radarSettings.showDistance == true
    radarSettings.showTeam = radarSettings.showTeam ~= false
    radarSettings.aliveOnly = radarSettings.aliveOnly ~= false
    radarSettings.grid = radarSettings.grid ~= false
    radarSettings.rings = radarSettings.rings ~= false

    local function getFloatingViewport(): Vector2
        local camera: Camera? = workspace.CurrentCamera
        return camera and camera.ViewportSize or Vector2.new(1280, 720)
    end

    local function clampFloatingPosition(
        position: Vector2,
        size: Vector2
    ): Vector2
        local viewport: Vector2 = getFloatingViewport()
        return Vector2.new(
            math.clamp(position.X, 6, math.max(6, viewport.X - size.X - 6)),
            math.clamp(position.Y, 6, math.max(6, viewport.Y - size.Y - 6))
        )
    end

    local function bringFloatingToFront(record: FloatingWindowRecord): ()
        state.windows.Raise(record.id)
    end

    local function createFloatingWindow(
        id: string,
        titleText: string,
        size: Vector2,
        defaultPosition: Vector2,
        onClose: (() -> ())?,
        chromeless: boolean?
    ): FloatingWindowRecord
        local bare: boolean = chromeless == true
        local headerHeight: number = bare and 0 or 30
        local saved: any = configData.ui.floatingPositions[id]
        local position: Vector2 = type(saved) == "table"
            and Vector2.new(
                tonumber(saved[1]) or defaultPosition.X,
                tonumber(saved[2]) or defaultPosition.Y
            )
            or defaultPosition
        position = clampFloatingPosition(position, size)

        local root: Frame = create("Frame", {
            Parent = PopupLayer,
            Name = "Floating_" .. id,
            Active = true,
            BackgroundColor3 = Theme.background,
            BackgroundTransparency = bare and 1 or 0.08,
            BorderSizePixel = 0,
            ClipsDescendants = not bare,
            Position = UDim2.fromOffset(position.X, position.Y),
            Size = UDim2.fromOffset(size.X, size.Y),
            Visible = false,
            ZIndex = 150,
        }) :: Frame
        bind(root, "BackgroundColor3", "background")
        if not bare then
            create("UICorner", {
                Parent = root,
                CornerRadius = cornerRadius(UI_RADIUS.panel),
            })
            local edge: UIStroke = create("UIStroke", {
                Parent = root,
                Name = "WindowOutline",
                Color = Theme.outline,
                Transparency = 0.08,
                Thickness = 1,
            }) :: UIStroke
            bind(edge, "Color", "outline")

            local shade: Frame = create("Frame", {
                Parent = root,
                Name = "Readability",
                BackgroundColor3 = Theme.background,
                BackgroundTransparency = 0.28,
                BorderSizePixel = 0,
                Size = UDim2.fromScale(1, 1),
            }) :: Frame
            bind(shade, "BackgroundColor3", "background")
            shade:SetAttribute("FloatingDepth", 2)
        end

        local header: Frame = create("Frame", {
            Parent = root,
            Name = "Header",
            Active = not bare,
            BackgroundColor3 = Theme.surface,
            BackgroundTransparency = 0.24,
            BorderSizePixel = 0,
            Size = UDim2.new(1, 0, 0, headerHeight),
            Visible = not bare,
        }) :: Frame
        bind(header, "BackgroundColor3", "surface")
        header:SetAttribute("FloatingDepth", 3)

        local closeButton: TextButton
        if bare then

            closeButton = create("TextButton", {
                TextTruncate = Enum.TextTruncate.AtEnd,
                ClipsDescendants = true,
                Parent = header,
                Name = "Close",
                BackgroundTransparency = 1,
                Text = "",
                Visible = false,
            }) :: TextButton
        else
            local accent: Frame = create("Frame", {
                Parent = header,
                BackgroundColor3 = Theme.outline,
                BackgroundTransparency = 0.62,
                BorderSizePixel = 0,
                Position = UDim2.fromOffset(0, headerHeight - 1),
                Size = UDim2.new(1, 0, 0, 1),
            }) :: Frame
            bind(accent, "BackgroundColor3", "outline")
            accent:SetAttribute("FloatingDepth", 1)
            local title: TextLabel = makeTextLabel(header, titleText, 10)
            title.FontFace = CONTROL_FONT
            title.Position = UDim2.fromOffset(10, 0)
            title.Size = UDim2.new(1, -40, 1, 0)
            title.TextColor3 = Theme.text
            bind(title, "TextColor3", "text")
            title:SetAttribute("FloatingDepth", 2)

            closeButton = makeButton(header, "x", 9)
            closeButton.Name = "Close"
            closeButton.AnchorPoint = Vector2.new(1, 0.5)
            closeButton.BackgroundTransparency = 1
            closeButton.Position = UDim2.new(1, -6, 0.5, 0)
            closeButton.Size = UDim2.fromOffset(22, 22)
            closeButton.TextColor3 = Theme.textMuted
            closeButton:SetAttribute("ThemeRole", "Icon")
            closeButton:SetAttribute("FloatingDepth", 3)
            local closeStroke: UIStroke? =
                closeButton:FindFirstChild("StyleStroke") :: UIStroke?
            if closeStroke then
                closeStroke.Enabled = false
            end
        end

        local body: Frame = create("Frame", {
            Parent = root,
            Name = "Body",
            Active = false,
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            Position = UDim2.fromOffset(0, headerHeight),
            Size = UDim2.new(1, 0, 1, -headerHeight),
        }) :: Frame
        body:SetAttribute("FloatingDepth", 4)

        if bare then
            root.Active = state.visible == true

            create("UICorner", {
                Parent = root,
                CornerRadius = cornerRadius(UI_RADIUS.control),
            })
            local hint: UIStroke = create("UIStroke", {
                Parent = root,
                Name = "MoveHint",
                Color = Theme.outline,
                Thickness = 1,
                Transparency = state.visible and 0.72 or 1,
            }) :: UIStroke
            bind(hint, "Color", "outline")
            state.addMenuVisibilityListener(function(visible: boolean): ()
                if not root.Parent then
                    return
                end
                root.Active = visible
                hint.Transparency = visible and 0.72 or 1
            end)
        end

        local record: FloatingWindowRecord = {
            id = id,
            root = root,
            body = body,
            closeButton = closeButton,
        }

        state.windows.Adopt(root, {
            id = id,
            body = body,
            header = header,
            closeButton = closeButton,
            headerHeight = headerHeight,
            dragHandle = bare and root or header,
            requiresMenuOpen = bare,
            layered = true,
            onClose = onClose,
        })
        return record
    end

    function FloatingUi.reclamp(): ()
        state.windows.Reclamp()
    end

    state.onLayout(function(): ()
        FloatingUi.reclamp()
    end)

    local FavoritesWindow: FloatingWindowRecord = createFloatingWindow(
        "Favorites",
        "Favorites",
        Vector2.new(state.layout.compact and 240 or 270, 236),
        Vector2.new(40, 90),
        function(): ()
            configData.ui.favoritesWindowOpen = false
            queueConfigSave()
        end
    )
    local FavoritesList: ScrollingFrame = create("ScrollingFrame", {
        Parent = FavoritesWindow.body,
        Name = "FavoriteModules",
        Active = true,
        AutomaticCanvasSize = Enum.AutomaticSize.Y,
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        CanvasSize = UDim2.fromOffset(0, 0),
        Position = UDim2.fromOffset(8, 8),
        ScrollBarImageColor3 = Theme.outline,
        ScrollBarThickness = 3,
        Size = UDim2.new(1, -16, 1, -16),
    }) :: ScrollingFrame
    FavoritesList:SetAttribute("FloatingDepth", 2)
    create("UIListLayout", {
        Parent = FavoritesList,
        Padding = UDim.new(0, 5),
        SortOrder = Enum.SortOrder.LayoutOrder,
    })

    local function syncFavoriteButton(feature: any): ()
        if not feature.favoriteButton then
            return
        end
        local selected: boolean = configData.ui.favorites[feature.configKey] == true
        feature.favoriteButton.Text = selected and "★" or "☆"
        feature.favoriteButton.TextColor3 = selected
            and Theme.accent
            or Theme.textMuted
        feature.favoriteButton.TextTransparency = selected and 0 or 0.34
    end

    local function refreshFavorites(): ()
        for _, row: GuiObject in ipairs(FloatingUi.favoriteRows) do
            row:Destroy()
        end
        table.clear(FloatingUi.favoriteRows)
        local order: number = 0
        for _, feature: any in ipairs(allFeatures) do
            if configData.ui.favorites[feature.configKey] == true then
                order += 1
                local row: TextButton = create("TextButton", {
                    TextTruncate = Enum.TextTruncate.AtEnd,
                    ClipsDescendants = true,
                    Parent = FavoritesList,
                    Name = feature.configKey:gsub("%W", ""),
                    AutoButtonColor = false,
                    BackgroundColor3 = Theme.surface,
                    BackgroundTransparency = 0.38,
                    BorderSizePixel = 0,
                    FontFace = THIN_FONT,
                    LayoutOrder = order,
                    Size = UDim2.new(1, -4, 0, 36),
                    Text = feature.name,
                    TextColor3 = feature.enabled
                        and Theme.accent
                        or Theme.text,
                    TextSize = 13,
                    TextXAlignment = Enum.TextXAlignment.Left,
                }) :: TextButton
                create("UICorner", {
                    Parent = row,
                    CornerRadius = cornerRadius(8),
                })
                row:SetAttribute("FloatingDepth", 3)
                create("UIPadding", {
                    Parent = row,
                    PaddingLeft = UDim.new(0, 12),
                    PaddingRight = UDim.new(0, 38),
                })
                local status: Frame = create("Frame", {
                    Parent = row,
                    Name = "Status",
                    AnchorPoint = Vector2.new(1, 0.5),
                    BackgroundColor3 = feature.enabled
                        and Theme.accent
                        or Theme.textMuted,
                    BackgroundTransparency = feature.enabled and 0 or 0.58,
                    BorderSizePixel = 0,
                    Position = UDim2.new(1, -14, 0.5, 0),
                    Size = UDim2.fromOffset(feature.enabled and 9 or 7, feature.enabled and 9 or 7),
                }) :: Frame
                create("UICorner", {Parent = status, CornerRadius = UDim.new(1, 0)})
                status:SetAttribute("FloatingDepth", 2)
                row.MouseButton1Click:Connect(function(): ()
                    if feature.isCategory then
                        state.setMenuVisible(true)
                    end
                    feature.activate()
                end)
                table.insert(FloatingUi.favoriteRows, row)
            end
        end
        if order == 0 then
            local empty: TextLabel = create("TextLabel", {
                TextTruncate = Enum.TextTruncate.AtEnd,
                ClipsDescendants = true,
                Parent = FavoritesList,
                BackgroundTransparency = 1,
                FontFace = THIN_FONT,
                LayoutOrder = 1,
                Size = UDim2.new(1, -4, 0, 52),
                Text = "Star a module to keep it here",
                TextColor3 = Theme.textMuted,
                TextSize = 13,
                TextTransparency = 0.28,
                TextXAlignment = Enum.TextXAlignment.Center,
            }) :: TextLabel
            empty:SetAttribute("FloatingDepth", 3)
            table.insert(FloatingUi.favoriteRows, empty)
        end
    end

    function FloatingUi.toggleFavorite(feature: any): ()
        local nextValue: boolean = configData.ui.favorites[feature.configKey] ~= true
        configData.ui.favorites[feature.configKey] = nextValue and true or nil
        syncFavoriteButton(feature)
        refreshFavorites()
        queueConfigSave()
    end

    function FloatingUi.registerFeature(feature: any): ()
        FloatingUi.favorites[feature.configKey] = feature
        syncFavoriteButton(feature)
        if configData.ui.favorites[feature.configKey] == true then
            refreshFavorites()
        end
    end

    function FloatingUi.unregisterFeature(feature: any): ()
        FloatingUi.favorites[feature.configKey] = nil
        if configData.ui.favorites[feature.configKey] == true then
            refreshFavorites()
        end
    end

    function FloatingUi.refreshFeature(feature: any): ()
        if configData.ui.favorites[feature.configKey] == true then
            refreshFavorites()
        end
    end

    local OverlayMenu: FloatingWindowRecord = createFloatingWindow(
        "OverlayMenu",
        "Overlays",
        Vector2.new(state.layout.compact and 232 or 252, 220),
        Vector2.new(340, 90),
        function(): ()
            configData.ui.overlayMenuOpen = false
            queueConfigSave()
        end
    )
    local OverlayList: Frame = create("Frame", {
        Parent = OverlayMenu.body,
        BackgroundTransparency = 1,
        Position = UDim2.fromOffset(8, 8),
        Size = UDim2.new(1, -16, 1, -16),
    }) :: Frame
    OverlayList:SetAttribute("FloatingDepth", 2)
    create("UIListLayout", {
        Parent = OverlayList,
        Padding = UDim.new(0, 5),
        SortOrder = Enum.SortOrder.LayoutOrder,
    })

    local overlayDefinitions: {any} = {
        {id = "SessionInfo", title = "Session Info", size = Vector2.new(210, 118), position = Vector2.new(24, 300)},
        {id = "TextGUI", title = "Text GUI", size = Vector2.new(240, 220), position = Vector2.new(250, 300)},
        {id = "TargetInfo", title = "Target Info", size = Vector2.new(260, 86), position = Vector2.new(510, 300)},
        {id = "Radar", title = "Radar", size = Vector2.new(radarSettings.size, radarSettings.size), position = Vector2.new(820, 280)},
    }

    local function setOverlayEnabled(id: string, enabled: boolean): ()
        local overlay: any = FloatingUi.overlays[id]
        if not overlay then
            return
        end
        overlay.enabled = enabled
        overlay.window.root.Visible = enabled
        setToggleSwitch(overlay.toggle, enabled, true)
        configData.ui.overlays[id] = enabled
        queueConfigSave()
        if enabled then
            bringFloatingToFront(overlay.window)
        end
    end

    FloatingUi.settingsWindows = {}
    FloatingUi.openSettings = function(id: string): ()
        local window: FloatingWindowRecord? = FloatingUi.settingsWindows[id]
        if window then
            window.root.Visible = not window.root.Visible
            if window.root.Visible then
                bringFloatingToFront(window)
            end
        end
    end

    for index: number, definition: any in ipairs(overlayDefinitions) do
        local overlayId: string = definition.id
        local overlayWindow: FloatingWindowRecord
        overlayWindow = createFloatingWindow(
            overlayId,
            definition.title,
            definition.size,
            definition.position,
            function(): ()
                setOverlayEnabled(overlayId, false)
            end,
            true
        )
        local managerRow: Frame = create("Frame", {
            Parent = OverlayList,
            BackgroundColor3 = Theme.surface,
            BackgroundTransparency = 0.48,
            BorderSizePixel = 0,
            LayoutOrder = index,
            Size = UDim2.new(1, 0, 0, 40),
        }) :: Frame
        managerRow:SetAttribute("FloatingDepth", 3)
        create("UICorner", {
            Parent = managerRow,
            CornerRadius = cornerRadius(8),
        })
        local managerLabel: TextLabel = makeTextLabel(managerRow, definition.title, 10)
        managerLabel.Position = UDim2.fromOffset(10, 0)
        managerLabel.Size = UDim2.new(1, -112, 1, 0)
        managerLabel.TextColor3 = Theme.textMuted
        managerLabel:SetAttribute("FloatingDepth", 1)
        local settingsButton: TextButton = makeButton(managerRow, "", 9)
        settingsButton.Name = "Settings"

        state.applyLinesGlyph(settingsButton, false)
        settingsButton.AnchorPoint = Vector2.new(1, 0.5)
        settingsButton.BackgroundTransparency = 1
        settingsButton.Position = UDim2.new(1, -58, 0.5, 0)
        settingsButton.Size = UDim2.fromOffset(28, 28)
        settingsButton:SetAttribute("FloatingDepth", 2)
        local settingsStroke: UIStroke? =
            settingsButton:FindFirstChild("StyleStroke") :: UIStroke?
        if settingsStroke then
            settingsStroke.Enabled = false
        end
        local toggle: TextButton = createToggleSwitch(managerRow, false, 42)
        toggle.AnchorPoint = Vector2.new(1, 0.5)
        toggle.Position = UDim2.new(1, -7, 0.5, 0)
        toggle:SetAttribute("FloatingDepth", 2)
        FloatingUi.overlays[overlayId] = {
            window = overlayWindow,
            toggle = toggle,
            enabled = false,
        }
        trackUiConnection(toggle.MouseButton1Click:Connect(function(): ()
            setOverlayEnabled(overlayId, not FloatingUi.overlays[overlayId].enabled)
        end))
        trackUiConnection(settingsButton.MouseButton1Click:Connect(function(): ()
            FloatingUi.openSettings(overlayId)
        end))
    end

    local function createOverlaySettingsWindow(
        id: string,
        title: string,
        height: number,
        position: Vector2
    ): (FloatingWindowRecord, ScrollingFrame)

        local window: FloatingWindowRecord = createFloatingWindow(
            id .. "Settings",
            title,
            Vector2.new(
                state.layout.compact and 268 or 292,
                math.min(height, math.max(180, getFloatingViewport().Y - 24))
            ),
            position,
            nil
        )
        local scroll: ScrollingFrame = create("ScrollingFrame", {
            Parent = window.body,
            Active = true,
            AutomaticCanvasSize = Enum.AutomaticSize.Y,
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            CanvasSize = UDim2.fromOffset(0, 0),
            Position = UDim2.fromOffset(8, 8),
            ScrollBarImageColor3 = Theme.accentDim,
            ScrollBarThickness = 3,
            Size = UDim2.new(1, -16, 1, -16),
        }) :: ScrollingFrame
        scroll:SetAttribute("FloatingDepth", 2)
        create("UIListLayout", {
            Parent = scroll,
            Padding = UDim.new(0, 5),
            SortOrder = Enum.SortOrder.LayoutOrder,
        })
        FloatingUi.settingsWindows[id] = window
        return window, scroll
    end

    local function createCompactSettingRow(parent: Instance, labelText: string): Frame
        local row: Frame = create("Frame", {
            Parent = parent,
            BackgroundColor3 = Theme.surface,
            BackgroundTransparency = 0.44,
            BorderSizePixel = 0,
            Size = UDim2.new(1, -4, 0, 38),
        }) :: Frame
        create("UICorner", {Parent = row, CornerRadius = cornerRadius(8)})
        local label: TextLabel = makeTextLabel(row, labelText, 9)
        label.Position = UDim2.fromOffset(10, 0)
        label.Size = UDim2.new(0.48, -10, 1, 0)
        label.TextColor3 = Theme.textMuted
        return row
    end

    local function addCompactCycle(
        parent: Instance,
        labelText: string,
        values: {string},
        currentValue: string,
        callback: (string) -> ()
    ): ()
        local row: Frame = createCompactSettingRow(parent, labelText)
        local index: number = table.find(values, currentValue) or 1
        local button: TextButton = makeButton(row, values[index], 8)
        button.Position = UDim2.new(0.48, 4, 0, 4)
        button.Size = UDim2.new(0.52, -8, 1, -8)
        trackUiConnection(button.MouseButton1Click:Connect(function(): ()
            index = index % #values + 1
            button.Text = values[index]
            callback(values[index])
            queueConfigSave()
        end))
    end

    local function addCompactToggle(
        parent: Instance,
        labelText: string,
        initial: boolean,
        callback: (boolean) -> ()
    ): ()
        local row: Frame = createCompactSettingRow(parent, labelText)
        local enabled: boolean = initial
        local toggle: TextButton = createToggleSwitch(row, enabled, 42)
        toggle.AnchorPoint = Vector2.new(1, 0.5)
        toggle.Position = UDim2.new(1, -8, 0.5, 0)
        trackUiConnection(toggle.MouseButton1Click:Connect(function(): ()
            enabled = not enabled
            setToggleSwitch(toggle, enabled, true)
            callback(enabled)
            queueConfigSave()
        end))
    end

    local function addCompactText(
        parent: Instance,
        labelText: string,
        initial: string,
        callback: (string) -> ()
    ): ()
        local row: Frame = createCompactSettingRow(parent, labelText)
        local box: TextBox = makeTextBox(row, initial)
        box.Position = UDim2.new(0.48, 4, 0, 4)
        box.Size = UDim2.new(0.52, -8, 1, -8)
        box.PlaceholderText = "Custom text"
        box.TextXAlignment = Enum.TextXAlignment.Left
        trackUiConnection(box.FocusLost:Connect(function(): ()
            callback(string.sub(box.Text, 1, 80))
            queueConfigSave()
        end))
    end

    do
        local textSettingsScroll: ScrollingFrame
        local _textSettingsWindow: FloatingWindowRecord
        _textSettingsWindow, textSettingsScroll = createOverlaySettingsWindow(
            "TextGUI",
            "Text GUI settings",
            state.layout.compact and 500 or 540,
            Vector2.new(300, 70)
        )
        addCompactCycle(textSettingsScroll, "Sort", {"Alphabetical", "Length", "Enabled order", "Section"}, textGuiSettings.sort, function(value: string): () textGuiSettings.sort = value end)
        addCompactCycle(textSettingsScroll, "Font", {"Builder Sans", "Source Sans", "Gotham", "Code", "Valve"}, textGuiSettings.font, function(value: string): () textGuiSettings.font = value end)
        addCompactCycle(textSettingsScroll, "Color mode", {"Match GUI", "Solid white", "Greyscale", "Rainbow", "By section"}, textGuiSettings.colorMode, function(value: string): () textGuiSettings.colorMode = value end)
